  const AGENT_MARKERS = [
    { identifier: 'agentSystemPrompt', name: 'Agent System Prompt', role: 'system' },
    { identifier: 'agentResults',      name: 'Agent Results',       role: 'system' },
    { identifier: 'agentTask',         name: 'Agent Task',          role: 'user'   },
  ];
  const STRIP_FIELDS = ['injection_position', 'injection_depth', 'injection_order', 'forbid_overrides'];

  // 🦊 一定要走 top window：脚本在 about:srcdoc iframe 里跑，SillyTavern 数据在酒馆主页
  function getTopWin() {
    try {
      return (typeof window !== 'undefined' && window.parent && window.parent !== window)
        ? window.parent
        : window;
    } catch { return typeof window !== 'undefined' ? window : null; }
  }
  function getCtx() {
    try { return getTopWin()?.SillyTavern?.getContext?.() || null; }
    catch { return null; }
  }

  const lockedPrompts = new WeakSet();

  // 用 defineProperty 把 marker/system_prompt/role/name 锁成"永远返回正确值"、
  // 写入静默吞掉。这样宿主 sanitize 无论怎么 `p.marker = false` 都改不动。
  function lockPrompt(p, def) {
    if (!p || typeof p !== 'object') return;
    if (lockedPrompts.has(p)) return;
    const fixedValues = {
      marker: true,
      system_prompt: true,
      role: def.role,
      name: def.name,
    };
    for (const [key, val] of Object.entries(fixedValues)) {
      try {
        Object.defineProperty(p, key, {
          configurable: true,
          enumerable: true,
          get() { return val; },
          set(_v) { /* 静默吞掉宿主的擦写 */ },
        });
      } catch (e) {
        try { p[key] = val; } catch {}
      }
    }
    for (const k of STRIP_FIELDS) {
      try {
        try { delete p[k]; } catch {}
        Object.defineProperty(p, k, {
          configurable: true,
          enumerable: false,
          get() { return undefined; },
          set(_v) { /* 静默吞掉，不允许宿主往 marker 上塞 injection_* */ },
        });
      } catch {}
    }
    if (typeof p.enabled !== 'boolean') { try { p.enabled = true; } catch {} }
    if (typeof p.content !== 'string')  { try { p.content = ''; } catch {} }
    lockedPrompts.add(p);
  }

  // 对一个 prompts 数组扫描一遍，把三个 marker 对象上锁。
  function lockArray(arr) {
    if (!Array.isArray(arr)) return;
    for (const def of AGENT_MARKERS) {
      const p = arr.find(x => x?.identifier === def.identifier);
      if (p && !lockedPrompts.has(p)) lockPrompt(p, def);
    }
  }

  // 🔒 关键防线：给 chatCompletionSettings.prompts 装 getter/setter。
  // 只要有人（含宿主）把整个 prompts 数组赋值成新对象，setter 会在
  // "同步同 tick 内"立刻扫描锁定新数组里的 marker 对象；后续 UI 读这个 prompts
  // 时读到的已经是被锁死的对象，PromptManager 不会再把它识别成普通 preset prompt。
  const installedHosts = new WeakSet();
  function installArrayGuard(host) {
    if (!host || typeof host !== 'object') return false;
    if (installedHosts.has(host)) return true;

    // 先取一次现有值
    let _prompts;
    try { _prompts = host.prompts; } catch { _prompts = undefined; }

    try {
      Object.defineProperty(host, 'prompts', {
        configurable: true,
        enumerable: true,
        get() {
          // read-time 兜底：万一数组内容被 splice/push 等原地改动（对象引用未变
          // 但里面对象被换掉），也能在下一次被读到时立即锁上新对象。
          lockArray(_prompts);
          return _prompts;
        },
        set(v) {
          _prompts = v;
          // 同步锁：新数组赋值这一瞬间就完成锁定，让宿主 sanitize 之后的任何
          // "prompts.forEach(sanitize)"都写不动 marker/system_prompt/role。
          lockArray(v);
        },
      });
      installedHosts.add(host);
      // 立即锁一次现值
      lockArray(_prompts);
      return true;
    } catch (e) {
      try { console.warn('[agent-marker-guard] installArrayGuard 失败，回退到扫描模式', e); } catch {}
      // 回退：至少把当前数组扫一遍
      lockArray(_prompts);
      return false;
    }
  }

  // 扫描当前预设，返回是否有新锁定
  function restore() {
    const ctx = getCtx();
    const host = ctx?.chatCompletionSettings;
    if (!host) return false;

    // 每次都尝试装 prompts 属性守卫；WeakSet 保证同一 host 只装一次
    installArrayGuard(host);

    let prompts;
    try { prompts = host.prompts; } catch { prompts = null; }
    if (!Array.isArray(prompts)) return false;

    const beforeSize = lockedPrompts;
    let touchedNew = false;
    for (const def of AGENT_MARKERS) {
      const p = prompts.find(x => x?.identifier === def.identifier);
      if (!p) continue;
      if (!lockedPrompts.has(p)) {
        lockPrompt(p, def);
        touchedNew = true;
      }
    }
    if (touchedNew) {
      try { ctx?.saveSettingsDebounced?.(); } catch {}
      try { console.warn('[agent-marker-guard] 已重新锁定 agent marker（引用被替换）'); } catch {}
    }
    return touchedNew;
  }

  // 1) 启动后每 500ms 探一次上下文，就绪就锁一次；上限 20 次防长期空转。
  //    🦊 性能优化：从 250ms×40次 降为 500ms×20次，总等待时间不变但调用频率减半
  let bootTries = 0;
  const boot = setInterval(() => {
    if (++bootTries > 20) return clearInterval(boot);
    if (getCtx()?.chatCompletionSettings) {
      restore();
      clearInterval(boot);
    }
  }, 500);

  // 2) 事件绑定：任何一次预设/设置/请求相关事件后都重锁一次。
  //    - OAI_PRESET_CHANGED_AFTER / _BEFORE / PRESET_CHANGED：预设切换
  //    - SETTINGS_UPDATED / SETTINGS_LOADED_AFTER：设置写回
  //    - CHATCOMPLETION_SOURCE_CHANGED：源切换会重建 prompts
  //    - CHAT_COMPLETION_SETTINGS_READY：构造请求前的 settings ready
  //    - CHAT_COMPLETION_PROMPT_READY：构造 prompt 完成、即将发出——出请求前最后一道防线
  //    - GENERATION_STARTED / APP_READY：兜底
  const EVENT_NAMES = [
    'APP_READY',
    'OAI_PRESET_CHANGED_AFTER',
    'OAI_PRESET_CHANGED_BEFORE',
    'PRESET_CHANGED',
    'SETTINGS_UPDATED',
    'SETTINGS_LOADED_AFTER',
    'CHATCOMPLETION_SOURCE_CHANGED',
    'CHAT_COMPLETION_SETTINGS_READY',
    'CHAT_COMPLETION_PROMPT_READY',
    'GENERATION_STARTED',
  ];
  const tryBindEvents = () => {
    try {
      const ctx = getCtx();
      const eo  = ctx?.eventSource;
      const te  = ctx?.eventTypes ?? getTopWin()?.tavern_events;
      if (!eo || !te) return false;
      const fixNow  = () => { try { restore(); } catch {} };
      const fixLate = () => setTimeout(fixNow, 0);
      for (const name of EVENT_NAMES) {
        const ev = te[name];
        if (!ev) continue;
        try { eo.on?.(ev, fixNow); }  catch {}
        try { eo.on?.(ev, fixLate); } catch {}
      }
      return true;
    } catch { return false; }
  };
  let bindTries = 0;
  // 🦊 性能优化：从 250ms×40次 降为 500ms×20次，总等待时间不变但调用频率减半
  const bind = setInterval(() => {
    if (++bindTries > 20) return clearInterval(bind);
    if (tryBindEvents()) clearInterval(bind);
  }, 500);

  // 3) 兜底轮询：属性锁一旦生效对同一对象是空操作，几乎零开销；
  //    真正生效是宿主把 prompts 数组整体替换（预设导入/切换/重载）且事件没触发到的场景。
  //    🦊 性能优化：从 2s 改为 30s——事件绑定已覆盖绝大多数场景，此处仅作最终兜底。
  setInterval(() => { try { restore(); } catch {} }, 30000);

  // 4) 前 15 秒内额外密集扫描（覆盖 4s 初始化窗口 + 各种延迟加载），
  //    这段窗口是历史上最容易翻车的时段（脚本自己的 updatePresetWith 就在此期间跑）。
  //    🦊 性能优化：从 500ms×60次(30s) 降为 1000ms×15次(15s)，减少启动期 CPU 占用。
  let fastTries = 0;
  const fast = setInterval(() => {
    if (++fastTries > 15) return clearInterval(fast); // 15 * 1000ms = 15s
    try { restore(); } catch {}
  }, 1000);
})();

