  function _fsModuleName(key) {
    for (const [prefix, name] of _FS_PREFIX_MAP) {
      if (key.startsWith(prefix)) return name;
    }
    return null;
  }

  function _scheduleFileSync() {
    if (_fileSyncTimer) clearTimeout(_fileSyncTimer);
    _fileSyncTimer = setTimeout(async () => {
      _fileSyncTimer = null;
      if (!_fileStorageActive) return;
      try {
        const map = {};
        for (const [key, value] of Object.entries(_fileCache)) {
          const mod = _fsModuleName(key);
          if (!mod) continue;
          if (!map[mod]) map[mod] = {};
          map[mod][key] = value;
        }
        if (typeof FoxStorage !== 'undefined' && FoxStorage.isActive()) {
          for (const [mod, data] of Object.entries(map)) {
            await FoxStorage.saveModuleFile(mod, data);
          }
        }
      } catch (e) { /* 静默失败 */ }
    }, 2000);
  }

  // 🦊 核心：用 const localStorage 遮蔽 window.localStorage
  const localStorage = {
    getItem(key) {
      if (_fileStorageActive) return key in _fileCache ? _fileCache[key] : null;
      return _realLS.getItem(key);
    },
    setItem(key, value) {
      if (_fileStorageActive) {
        _fileCache[key] = String(value);
        _scheduleFileSync();
      } else {
        _realLS.setItem(key, value);
      }
    },
    removeItem(key) {
      if (_fileStorageActive) {
        delete _fileCache[key];
        _scheduleFileSync();
      } else {
        _realLS.removeItem(key);
      }
    },
    get length() {
      if (_fileStorageActive) return Object.keys(_fileCache).length;
      return _realLS.length;
    },
    key(index) {
      if (_fileStorageActive) return Object.keys(_fileCache)[index] || null;
      return _realLS.key(index);
    },
    clear() {
      if (_fileStorageActive) {
        for (const k of Object.keys(_fileCache)) delete _fileCache[k];
        _scheduleFileSync();
      } else {
        _realLS.clear();
      }
    },
  };

  function _activateFileStorage() {
    for (let i = 0; i < _realLS.length; i++) {
      const key = _realLS.key(i);
      if (key) _fileCache[key] = _realLS.getItem(key);
    }
    _fileStorageActive = true;
    _scheduleFileSync();
  }

  function _deactivateFileStorage() {
    for (const [key, value] of Object.entries(_fileCache)) {
      try { _realLS.setItem(key, value); } catch (e) {}
    }
    _fileStorageActive = false;
  }

  async function _loadCacheFromFiles() {
    if (typeof FoxStorage === 'undefined' || !FoxStorage.isActive()) return;
    try {
      const result = await FoxStorage.importAllFromFolder();
      for (const [moduleName, data] of Object.entries(result)) {
        if (data && typeof data === 'object') {
          for (const [key, value] of Object.entries(data)) {
            if (key === '__promptBackup') continue;
            _fileCache[key] = String(value);
          }
        }
      }
    } catch (e) { console.error('[🦊][文件存储] 从文件加载缓存失败', e); }
  }

