  const SS_CUSTOM_API_PRESETS_KEY = 'SPreset_CustomApiPresets';

  function ssLoadCustomApiPresets() {
    try {
      const raw = localStorage.getItem(SS_CUSTOM_API_PRESETS_KEY);
      const arr = raw ? JSON.parse(raw) : [];
      return Array.isArray(arr) ? arr.filter(x => x && (x.apiurl || x.key || x.model)) : [];
    } catch {
      return [];
    }
  }

  function ssSaveCustomApiPresets(list) {
    try {
      localStorage.setItem(SS_CUSTOM_API_PRESETS_KEY, JSON.stringify(Array.isArray(list) ? list : []));
    } catch { }
  }

  function ssGetCustomApiPresetOptionsHtml() {
    const list = ssLoadCustomApiPresets();
    if (!list.length) return '<option value="">暂无保存项</option>';
    return '<option value="">选择保存项</option>' + list.map(x => `<option value="${escapeHtml(x.id)}">${escapeHtml(x.name || x.apiurl || x.model || '未命名')}</option>`).join('');
  }

  function ssReadCustomApiValues(prefix) {
    const $ = id => topDoc.getElementById(`${prefix}-${id}`);
    return {
      apiurl: $('api-url')?.value?.trim() || '',
      key: $('api-key')?.value?.trim() || '',
      model: $('api-model')?.value?.trim() || $('model')?.value?.trim() || '',
      proxyPreset: $('proxy-preset')?.value?.trim() || '',
      temperature: $('api-temp')?.value?.trim() || '',
      max_tokens: $('api-max-tokens')?.value?.trim() || '',
      top_p: $('api-top-p')?.value?.trim() || '',
      frequency_penalty: $('api-freq-pen')?.value?.trim() || '',
      presence_penalty: $('api-pres-pen')?.value?.trim() || '',
    };
  }

  function ssApplyCustomApiValues(prefix, item) {
    if (!item) return;
    const set = (id, v) => {
      const el = topDoc.getElementById(`${prefix}-${id}`);
      if (el) el.value = v || '';
    };
    set('api-url', item.apiurl);
    set('api-key', item.key);
    set('api-model', item.model);
    set('model', item.model);
    set('proxy-preset', item.proxyPreset);
    set('api-temp', item.temperature);
    set('api-max-tokens', item.max_tokens);
    set('api-top-p', item.top_p);
    set('api-freq-pen', item.frequency_penalty);
    set('api-pres-pen', item.presence_penalty);
  }

  function ssAttachCustomApiPresetControls(prefix, { onApply, onSave, readValues, applyValues } = {}) {
    const sel = topDoc.getElementById(`${prefix}-saved-api-select`);
    const applyBtn = topDoc.getElementById(`${prefix}-saved-api-apply`);
    const saveBtn = topDoc.getElementById(`${prefix}-saved-api-save`);
    const delBtn = topDoc.getElementById(`${prefix}-saved-api-delete`);

    const refresh = () => {
      if (sel) sel.innerHTML = ssGetCustomApiPresetOptionsHtml();
    };

    if (applyBtn && sel) {
      applyBtn.onclick = () => {
        const item = ssLoadCustomApiPresets().find(x => String(x.id) === String(sel.value));
        if (!item) { toast('⚠️ 请先选择保存项', 'warning'); return; }
        if (applyValues) {
          applyValues(item);
        } else {
          ssApplyCustomApiValues(prefix, item);
        }
        try { onApply?.(item); } catch { }
        toast('✅ 已填入保存的 API / URL', 'success');
      };
    }

    if (saveBtn) {
      saveBtn.onclick = () => {
        const values = readValues ? readValues() : ssReadCustomApiValues(prefix);
        if (!values.apiurl && !values.key && !values.model && !values.proxyPreset) {
          toast('⚠️ 当前没有可保存的 API / URL / 模型', 'warning');
          return;
        }
        const promptFn = topWindow?.prompt || window.prompt;
         const promptedName = promptFn ? promptFn.call(topWindow || window, '给这组 API 配置起个名字：', values.model || values.apiurl || '自定义API') : '';
         if (promptedName === null) {
           toast('已取消保存 API 配置', 'info');
           return;
         }
         const name = promptedName || '';
        const list = ssLoadCustomApiPresets();
        list.unshift({ id: `api_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`, name: name.trim() || values.model || values.apiurl || '自定义API', ...values, updatedAt: new Date().toISOString() });
        ssSaveCustomApiPresets(list.slice(0, 50));
        refresh();
        try { onSave?.(values); } catch { }
        toast('✅ 已保存自定义 API / URL', 'success');
      };
    }

    if (delBtn && sel) {
      delBtn.onclick = () => {
        const id = sel.value;
        if (!id) { toast('⚠️ 请先选择保存项', 'warning'); return; }
        ssSaveCustomApiPresets(ssLoadCustomApiPresets().filter(x => String(x.id) !== String(id)));
        refresh();
        toast('🗑️ 已删除保存项', 'success');
      };
    }
  }

