  /** 将 localStorage 按模块分组，返回 { 模块名: { key: value, ... }, ... } */
  function buildModuleDataMap() {
    const map = {};
    const allKeys = [];
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (!key) continue;
      // 仅收集玄狐相关的 key
      if (key.startsWith('SPreset_') || key.startsWith('smoothStream_') || key.startsWith('Xuanhu_ParallelWorld_') ||
          key === 'websearch_settings' || key === 'hushen_profile_settings' || key === 'Xuanhu_UserStreamPreference') {
        allKeys.push(key);
      }
    }

    for (const key of allKeys) {
      const value = localStorage.getItem(key);
      // 找到匹配的模块
      let moduleName = '其他配置';
      for (const m of FOX_MODULE_PREFIX_MAP) {
        if (key.startsWith(m.prefix)) { moduleName = m.file; break; }
      }
      if (!map[moduleName]) map[moduleName] = {};
      map[moduleName][key] = value;
    }

    // 额外保存预设条目备份
    const promptBackup = buildPromptBackup();
    if (Object.keys(promptBackup).length > 0) {
      map['预设条目'] = { __promptBackup: JSON.stringify(promptBackup) };
    }

    return map;
  }

  /** 将模块数据写回 localStorage */
  function applyModuleData(moduleName, data) {
    if (!data || typeof data !== 'object') return 0;
    let count = 0;
    for (const [key, value] of Object.entries(data)) {
      if (key === '__promptBackup') {
        // 预设条目特殊处理
        try {
          const promptBackup = JSON.parse(value);
          if (promptBackup && typeof promptBackup === 'object') {
            updatePresetWith('in_use', (preset) => {
              for (const backup of Object.values(promptBackup)) {
                const refList = [backup.id, backup.identifier].filter(Boolean);
                const p = preset.prompts.find(x => refList.includes(x.id) || refList.includes(x.identifier));
                if (!p) continue;
                if (typeof backup.content === 'string') p.content = backup.content;
                if (typeof backup.enabled === 'boolean') p.enabled = backup.enabled;
              }
              return preset;
            }).catch(e => logError('[文件存储] 恢复预设条目失败', e));
          }
        } catch (e) { logError('[文件存储] 解析预设备份失败', e); }
        continue;
      }
      try {
        if (value == null) localStorage.removeItem(key);
        else localStorage.setItem(key, String(value));
        count++;
      } catch (e) { logError('[文件存储] 写入 localStorage 失败:', key, e); }
    }
    return count;
  }

  /** 导出全部配置到文件夹（分模块） */
  async function exportAllToFolder() {
    const moduleDataMap = buildModuleDataMap();

    // 路径 A：File System Access API 可用 -> 直接写入文件夹
    if (FoxStorage.isActive()) {
      try {
        const count = await FoxStorage.exportAllToFolder(moduleDataMap);
        toast(`✅ 已导出 ${count} 个模块配置文件到「${FoxStorage.getDirName()}」文件夹`, 'success');
        return;
      } catch (e) {
        toast(`❌ 写入文件夹失败：${e.message || e}，改为下载方式`, 'warning');
      }
    }

    // 路径 B：回退 -> 下载单个合并 JSON 文件（包含所有模块）
    try {
      const exportData = {
        version: 'xuanhu_folder_backup_v1',
        exportedAt: new Date().toISOString(),
        modules: moduleDataMap,
      };
      FoxStorage.downloadJson(exportData, `玄狐配置备份_${new Date().toISOString().slice(0, 10)}.json`);
      const moduleCount = Object.keys(moduleDataMap).length;
      toast(`✅ 已下载配置备份文件（含 ${moduleCount} 个模块）\n💡 如需分模块保存：请用 Chrome/Edge 并点击"选择存储文件夹"`, 'success');
    } catch (e) {
      toast(`❌ 导出失败：${e.message || e}`, 'error');
    }
  }

  /** 从文件夹导入全部配置（自动解析模块文件） */
  async function importAllFromFolder() {
    const ok = topWindow?.confirm
      ? topWindow.confirm('确定要导入配置吗？\n\n选择文件夹后会自动解析其中所有 .json 配置文件，\n有对应的会覆盖，没有的不受影响。导入后需重新打开面板。')
      : confirm('确定要导入配置吗？\n\n选择文件夹后会自动解析其中所有 .json 配置文件，\n有对应的会覆盖，没有的不受影响。导入后需重新打开面板。');
    if (!ok) return;

    try {
      let result;

      // 路径 A：File System Access API 可用 -> 从已绑定的文件夹读取
      if (FoxStorage.isActive()) {
        result = await FoxStorage.importAllFromFolder();
      } else {
        // 路径 B：回退 -> 弹出文件夹选择器 <input webkitdirectory>
        toast('请在弹出的对话框中选择包含配置文件的文件夹', 'info');
        result = await FoxStorage.pickFolderForImport();
      }

      const moduleNames = Object.keys(result);
      if (moduleNames.length === 0) {
        toast('没有找到任何配置文件（.json）\n💡 如果之前下载的是合并备份文件，请用上方"📥 一键导入全部配置"按钮', 'warning');
        return;
      }

      let totalKeys = 0;
      for (const [moduleName, data] of Object.entries(result)) {
        // 兼容合并备份格式：如果 data 有 modules 字段，展开它
        if (data && data.modules && typeof data.modules === 'object' && !Array.isArray(data.modules)) {
          for (const [subName, subData] of Object.entries(data.modules)) {
            totalKeys += applyModuleData(subName, subData);
          }
        } else {
          totalKeys += applyModuleData(moduleName, data);
        }
      }

      // 重新加载各模块配置
      try { state.husouSettings = loadHusouSettings(); } catch {}
      try { state.hushenSettings = loadHushenSettings(); } catch {}
      try { foxMemoryConfig = loadFoxMemoryConfig(); } catch {}
      try { novelModeConfig = loadNovelModeConfig(); } catch {}
      try { outlineApiConfig = loadOutlineApiConfig(); } catch {}
      try { pwState.config = pwLoadConfig(); } catch {}

      toast(`✅ 已导入 ${moduleNames.length} 个模块配置（${totalKeys} 项），重新打开面板即可生效`, 'success');
    } catch (e) {
      toast(`❌ 导入失败：${e.message || e}`, 'error');
    }
  }

  function buildAllLocalStorageBackup() {
    const data = {
