  // ==================== 🦊 文件存储系统 ====================
  // 混合存储策略：
  // 1. 优先使用 File System Access API（window.showDirectoryPicker）实现文件夹读写
  // 2. 不支持时回退到 <input webkitdirectory> 导入 + 下载导出
  // 3. 目录句柄通过 IndexedDB 持久化，刷新后自动恢复
  const FoxStorage = (function () {
    const DB_NAME = 'FoxStorageDB';
    const DB_STORE = 'handles';
    const DB_KEY = 'dirHandle';

    let _dirHandle = null;
    // 🦊 关键修复：优先检测 window 自身（iframe 内），而非 topWindow
    // 因为 showDirectoryPicker 需要用户手势上下文，跨 window 调用会丢失手势
    const _isSupported = typeof window?.showDirectoryPicker === 'function'
      || (typeof topWindow?.showDirectoryPicker === 'function' && topWindow === window);

    function _openDB() {
      return new Promise((resolve, reject) => {
        try {
          const req = indexedDB.open(DB_NAME, 1);
          req.onupgradeneeded = () => { req.result.createObjectStore(DB_STORE); };
          req.onsuccess = () => resolve(req.result);
          req.onerror = () => reject(req.error);
        } catch (e) { reject(e); }
      });
    }
    async function _saveHandle(handle) {
      try {
        const db = await _openDB();
        const tx = db.transaction(DB_STORE, 'readwrite');
        tx.objectStore(DB_STORE).put(handle, DB_KEY);
        await new Promise(r => { tx.oncomplete = r; tx.onerror = r; });
      } catch (e) { /* ignore */ }
    }
    async function _loadHandle() {
      try {
        const db = await _openDB();
        const tx = db.transaction(DB_STORE, 'readonly');
        const req = tx.objectStore(DB_STORE).get(DB_KEY);
        return new Promise(resolve => { req.onsuccess = () => resolve(req.result || null); req.onerror = () => resolve(null); });
      } catch (e) { return null; }
    }
    async function _clearHandle() {
      try {
        const db = await _openDB();
        const tx = db.transaction(DB_STORE, 'readwrite');
        tx.objectStore(DB_STORE).delete(DB_KEY);
        await new Promise(r => { tx.oncomplete = r; });
      } catch (e) { /* ignore */ }
    }
    async function _verifyPermission(handle) {
      try {
        const opts = { mode: 'readwrite' };
        if ((await handle.queryPermission(opts)) === 'granted') return true;
        if ((await handle.requestPermission(opts)) === 'granted') return true;
        return false;
      } catch (e) { return false; }
    }

    async function init() {
      if (!_isSupported) return false;
      _dirHandle = await _loadHandle();
      if (_dirHandle) {
        const ok = await _verifyPermission(_dirHandle);
        if (!ok) { _dirHandle = null; await _clearHandle(); return false; }
        return true;
      }
      return false;
    }

    async function pickDirectory() {
      if (!_isSupported) throw new Error('当前浏览器不支持文件存储，请使用 Chrome/Edge');
      // 🦊 必须用 window 自身调用，保留用户手势上下文
      const handle = await window.showDirectoryPicker({ mode: 'readwrite' });
      _dirHandle = handle;
      await _saveHandle(handle);
      return true;
    }

    async function clearDirectory() { _dirHandle = null; await _clearHandle(); }

    async function saveModuleFile(moduleName, data) {
      if (!_dirHandle) return false;
      try {
        const fh = await _dirHandle.getFileHandle(`${moduleName}.json`, { create: true });
        const w = await fh.createWritable();
        await w.write(JSON.stringify(data, null, 2));
        await w.close();
        return true;
      } catch (e) { logError('[文件存储] 保存失败:', moduleName, e); return false; }
    }

    async function loadModuleFile(moduleName) {
      if (!_dirHandle) return null;
      try {
        const fh = await _dirHandle.getFileHandle(`${moduleName}.json`);
        const file = await fh.getFile();
        return JSON.parse(await file.text());
      } catch (e) { return null; }
    }

    async function listModuleFiles() {
      if (!_dirHandle) return [];
      const names = [];
      try {
        for await (const [name, handle] of _dirHandle.entries()) {
          if (handle.kind === 'file' && name.endsWith('.json')) names.push(name.replace(/\.json$/, ''));
        }
      } catch (e) { logError('[文件存储] 列举失败', e); }
      return names;
    }

    async function exportAllToFolder(moduleDataMap) {
      if (!_dirHandle) throw new Error('未选择存储文件夹');
      let count = 0;
      for (const [name, data] of Object.entries(moduleDataMap)) {
        if (await saveModuleFile(name, data)) count++;
      }
      return count;
    }

    async function importAllFromFolder() {
      if (!_dirHandle) throw new Error('未选择存储文件夹');
      const result = {};
      const names = await listModuleFiles();
      for (const name of names) {
        const data = await loadModuleFile(name);
        if (data) result[name] = data;
      }
      return result;
    }

    /** 🦊 回退方案：通过 <input webkitdirectory> 选择文件夹导入（不需要 File System Access API） */
    function pickFolderForImport() {
      return new Promise((resolve, reject) => {
        try {
          const inp = topDoc.createElement('input');
          inp.type = 'file';
          inp.setAttribute('webkitdirectory', '');
          inp.setAttribute('directory', '');
          inp.setAttribute('multiple', '');
          inp.style.display = 'none';
          inp.onchange = async (e) => {
            const files = Array.from(e.target.files || []);
            const jsonFiles = files.filter(f => f.name.endsWith('.json'));
            if (jsonFiles.length === 0) { resolve({}); return; }
            const result = {};
            for (const file of jsonFiles) {
              try {
                const moduleName = file.name.replace(/\.json$/, '');
                const text = await file.text();
                result[moduleName] = JSON.parse(text);
              } catch (err) { /* 跳过解析失败的文件 */ }
            }
            resolve(result);
          };
          topDoc.body.appendChild(inp);
          inp.click();
          // 清理
          setTimeout(() => { try { inp.remove(); } catch {} }, 10000);
        } catch (e) { reject(e); }
      });
    }

    /** 🦊 回退方案：下载单个 JSON 文件 */
    function downloadJson(data, filename) {
      try {
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = topDoc.createElement('a');
        a.href = url; a.download = filename;
        a.style.display = 'none';
        topDoc.body.appendChild(a);
        a.click();
        setTimeout(() => { try { a.remove(); URL.revokeObjectURL(url); } catch {} }, 1000);
      } catch (e) { logError('[文件存储] 下载失败', e); }
    }

    function isActive() { return _dirHandle !== null; }
    function isSupported() { return _isSupported; }
    function getDirName() { return _dirHandle?.name || '(未选择)'; }

    return {
      init, pickDirectory, clearDirectory,
      saveModuleFile, loadModuleFile, listModuleFiles,
      exportAllToFolder, importAllFromFolder,
      pickFolderForImport, downloadJson,
      isActive, isSupported, getDirName
    };
  })();

  try { window.FoxStorage = FoxStorage; } catch (e) {}

  let foxJudgeDiagSeq = 0;
  let foxJudgeActiveDiag = null;
  let foxJudgeLastDiag = null;

  // ==================== 🦊 模块化提示词自定义管理系统 ====================
  // 提供统一的提示词存储/读取/应用机制，所有模块的硬编码提示词均可通过此系统自定义。
  // 存储格式：localStorage["SPreset_XhPromptCustom_<moduleId>"] = JSON.stringify({
  //   head: "头部提示词", middle: "中间提示词", tail: "尾部提示词"
  // })
  // 读取优先级：用户自定义 > 默认值（硬编码原文）
  const XH_PROMPT_CUSTOM_KEY = (moduleId) => `SPreset_XhPromptCustom_${moduleId}`;

  // 各模块提示词默认值注册表（运行时由各构建函数注册）
  const xhPromptDefaults = {};

  // 注册模块提示词默认值（仅注册未自定义的部分）
  function xhRegisterPromptDefault(moduleId, slots) {
    if (!xhPromptDefaults[moduleId]) {
      xhPromptDefaults[moduleId] = { ...slots };
      return;
    }
    // 合并新字段（不覆盖已存在的默认值）
    for (const k of Object.keys(slots)) {
      if (xhPromptDefaults[moduleId][k] == null) {
        xhPromptDefaults[moduleId][k] = slots[k];
      }
    }
  }

  // 读取模块提示词自定义配置
  function xhReadPromptCustom(moduleId) {
    try {
      const raw = localStorage.getItem(XH_PROMPT_CUSTOM_KEY(moduleId));
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed === 'object') return parsed;
    } catch (e) { log('[提示词自定义] 读取失败', moduleId, e); }
    return null;
  }

  // 保存模块提示词自定义配置
  function xhSavePromptCustom(moduleId, custom) {
    try {
      const data = custom && typeof custom === 'object' ? custom : {};
      localStorage.setItem(XH_PROMPT_CUSTOM_KEY(moduleId), JSON.stringify(data));
      log(`[提示词自定义] 已保存 ${moduleId}`);
    } catch (e) { log('[提示词自定义] 保存失败', moduleId, e); }
  }

  // 删除模块提示词自定义配置（恢复默认）
  function xhResetPromptCustom(moduleId) {
    try {
      localStorage.removeItem(XH_PROMPT_CUSTOM_KEY(moduleId));
      log(`[提示词自定义] 已重置 ${moduleId}`);
    } catch (e) { log('[提示词自定义] 重置失败', moduleId, e); }
  }

  // 获取单个槽位的最终提示词（用户自定义优先，否则返回默认值）
  function xhGetPrompt(moduleId, slot) {
    const custom = xhReadPromptCustom(moduleId);
    if (custom && typeof custom[slot] === 'string' && custom[slot].trim()) {
      return custom[slot];
    }
    const def = xhPromptDefaults[moduleId];
    return def && def[slot] != null ? def[slot] : '';
  }

  // 检查模块是否有中间提示词槽位（用于 UI 自动跳过）
  function xhModuleHasMiddlePrompt(moduleId) {
    const def = xhPromptDefaults[moduleId];
    return !!(def && def.middle != null);
  }

  // 构建提示词编辑器 HTML（三段式：头部/中间/尾部）
  function xhBuildPromptEditorHtml(moduleId, moduleLabel) {
    const def = xhPromptDefaults[moduleId] || {};
    const custom = xhReadPromptCustom(moduleId) || {};
    const hasMiddle = def.middle != null;

    const buildSlot = (slot, label, desc) => {
      const defaultValue = def[slot] != null ? String(def[slot]) : '';
      const currentValue = (custom[slot] != null && custom[slot] !== '')
        ? String(custom[slot])
        : defaultValue;
      const isCustom = custom[slot] != null && custom[slot] !== '' && custom[slot] !== defaultValue;
      return `
        <div class="xh-prompt-slot" data-slot="${slot}" style="display:flex;flex-direction:column;gap:6px;">
          <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
            <label style="font-size:11.5px;color:#f0a070;font-weight:600;">${label}</label>
            <span class="xh-prompt-status" style="font-size:10px;color:${isCustom ? '#3ad07a' : '#706058'};">${isCustom ? '● 已自定义' : '○ 默认'}</span>
          </div>
          <div style="font-size:10px;color:#706058;line-height:1.4;">${desc}</div>
          <textarea class="xh-prompt-textarea" data-slot="${slot}" spellcheck="false"
            style="width:100%;min-height:90px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.18);border-radius:8px;color:#e8ddd4;padding:8px;font-size:12px;font-family:monospace;resize:vertical;box-sizing:border-box;line-height:1.5;">${escapeHtml(currentValue)}</textarea>
          <div style="display:flex;gap:6px;align-items:center;">
            <button type="button" class="xh-prompt-reset-slot" data-slot="${slot}"
              style="padding:4px 10px;border:1px solid rgba(232,120,74,0.2);border-radius:6px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:11px;">↺ 恢复默认</button>
            <span style="flex:1"></span>
            <span class="xh-prompt-char-count" data-slot="${slot}" style="font-size:10px;color:#706058;">${currentValue.length} 字</span>
          </div>
        </div>
      `;
    };

    return `
      <details class="xh-prompt-editor" data-module="${moduleId}" style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.12);border-radius:10px;padding:0;margin-top:10px;overflow:hidden;">
        <summary style="cursor:pointer;padding:10px 14px;font-size:12px;color:#f0a070;font-weight:600;user-select:none;display:flex;align-items:center;gap:8px;list-style:none;">
          <span style="font-size:14px;">✏️</span>
          <span>${escapeHtml(moduleLabel || moduleId)} · 提示词自定义</span>
          <span class="xh-prompt-editor-badge" style="margin-left:auto;font-size:10px;padding:2px 8px;border-radius:99px;background:rgba(232,120,74,0.12);color:#f0a070;">点击展开</span>
        </summary>
        <div class="xh-prompt-editor-body" style="padding:12px 14px;display:flex;flex-direction:column;gap:12px;border-top:1px dashed rgba(232,120,74,0.12);">
          <div style="font-size:11px;color:#a09088;line-height:1.6;background:rgba(255,255,255,0.02);padding:8px 10px;border-radius:6px;">
            🦊 修改下方提示词后点击"保存并应用"，下次该模块注入时自动使用新内容。留空则使用默认值。
          </div>
          ${buildSlot('head', '🟢 头部提示词', '注入到模块内容开头的引导文字')}
          ${hasMiddle ? buildSlot('middle', '🟡 中间提示词', '注入到模块内容中间的过渡/分隔文字') : ''}
          ${buildSlot('tail', '🔴 尾部提示词', '注入到模块内容结尾的收尾文字')}
          <div style="display:flex;gap:8px;align-items:center;padding-top:4px;border-top:1px dashed rgba(232,120,74,0.1);">
            <button type="button" class="xh-prompt-save"
              style="padding:6px 14px;border:1px solid rgba(232,120,74,0.4);border-radius:8px;background:linear-gradient(135deg,rgba(232,120,74,0.25),rgba(232,120,74,0.1));color:#ffb06a;cursor:pointer;font-size:12px;font-weight:600;">💾 保存并应用</button>
            <button type="button" class="xh-prompt-reset-all"
              style="padding:6px 14px;border:1px solid rgba(139,0,0,0.3);border-radius:8px;background:rgba(139,0,0,0.1);color:#d08080;cursor:pointer;font-size:11px;">↺ 全部恢复默认</button>
            <span style="flex:1"></span>
            <span class="xh-prompt-saved-tip" style="font-size:10px;color:#3ad07a;display:none;">✓ 已保存</span>
          </div>
        </div>
      </details>
    `;
  }

  // 绑定提示词编辑器交互事件（全局事件委托，避免重复绑定）
  let xhPromptEditorBound = false;
  function xhBindPromptEditorEvents() {
    if (xhPromptEditorBound) return;
    xhPromptEditorBound = true;

    topDoc.addEventListener('click', (e) => {
      // 单槽位恢复默认
      const resetSlotBtn = e.target.closest('.xh-prompt-reset-slot');
      if (resetSlotBtn) {
        const editor = resetSlotBtn.closest('.xh-prompt-editor');
        if (!editor) return;
        const moduleId = editor.dataset.module;
        const slot = resetSlotBtn.dataset.slot;
        const def = xhPromptDefaults[moduleId] || {};
        const ta = editor.querySelector(`textarea[data-slot="${slot}"]`);
        if (ta && def[slot] != null) {
          ta.value = String(def[slot]);
          ta.dispatchEvent(new Event('input', { bubbles: true }));
        }
        return;
      }

      // 全部恢复默认
      const resetAllBtn = e.target.closest('.xh-prompt-reset-all');
      if (resetAllBtn) {
        const editor = resetAllBtn.closest('.xh-prompt-editor');
        if (!editor) return;
        const moduleId = editor.dataset.module;
        const def = xhPromptDefaults[moduleId] || {};
        editor.querySelectorAll('textarea.xh-prompt-textarea').forEach(ta => {
          const slot = ta.dataset.slot;
          if (def[slot] != null) {
            ta.value = String(def[slot]);
            ta.dispatchEvent(new Event('input', { bubbles: true }));
          }
        });
        xhResetPromptCustom(moduleId);
        xhRefreshEditorStatus(editor, moduleId);
        try { toast('🦊 已恢复默认提示词', 'info'); } catch {}
        return;
      }

      // 保存并应用
      const saveBtn = e.target.closest('.xh-prompt-save');
      if (saveBtn) {
        const editor = saveBtn.closest('.xh-prompt-editor');
        if (!editor) return;
        const moduleId = editor.dataset.module;
        const def = xhPromptDefaults[moduleId] || {};
        const custom = {};
        editor.querySelectorAll('textarea.xh-prompt-textarea').forEach(ta => {
          const slot = ta.dataset.slot;
          const val = ta.value;
          // 只保存与默认值不同的内容
          if (val !== (def[slot] != null ? String(def[slot]) : '')) {
            custom[slot] = val;
          }
        });
        xhSavePromptCustom(moduleId, custom);
        xhRefreshEditorStatus(editor, moduleId);
        const tip = editor.querySelector('.xh-prompt-saved-tip');
        if (tip) {
          tip.style.display = 'inline';
          setTimeout(() => { tip.style.display = 'none'; }, 2000);
        }
        try { toast('🦊 提示词已保存，下次注入自动生效', 'success'); } catch {}
        return;
      }
    });

    // 字数统计 + 状态实时更新
    topDoc.addEventListener('input', (e) => {
      const ta = e.target.closest('textarea.xh-prompt-textarea');
      if (!ta) return;
      const editor = ta.closest('.xh-prompt-editor');
      if (!editor) return;
      const moduleId = editor.dataset.module;
      const slot = ta.dataset.slot;
      const counter = editor.querySelector(`.xh-prompt-char-count[data-slot="${slot}"]`);
      if (counter) counter.textContent = `${ta.value.length} 字`;
      xhRefreshEditorStatus(editor, moduleId);
    });
  }

  // 刷新编辑器内的"已自定义/默认"状态标记
  function xhRefreshEditorStatus(editor, moduleId) {
    if (!editor) return;
    const def = xhPromptDefaults[moduleId] || {};
    editor.querySelectorAll('.xh-prompt-slot').forEach(slotEl => {
      const slot = slotEl.dataset.slot;
      const ta = slotEl.querySelector(`textarea[data-slot="${slot}"]`);
      if (!ta) return;
      const isCustom = ta.value !== (def[slot] != null ? String(def[slot]) : '');
      const status = slotEl.querySelector('.xh-prompt-status');
      if (status) {
        status.textContent = isCustom ? '● 已自定义' : '○ 默认';
        status.style.color = isCustom ? '#3ad07a' : '#706058';
      }
    });
  }

  // 在指定容器内挂载提示词编辑器（供各模块调用）
  function xhMountPromptEditor(containerEl, moduleId, moduleLabel) {
    if (!containerEl) return;
    // 避免重复挂载
    const existing = containerEl.querySelector(`.xh-prompt-editor[data-module="${moduleId}"]`);
    if (existing) return;
    containerEl.insertAdjacentHTML('beforeend', xhBuildPromptEditorHtml(moduleId, moduleLabel));
    xhBindPromptEditorEvents();
  }

  // ==================== 模块化提示词自定义管理系统 END ====================

  function ssRedactDiagnosticText(value) {
    return String(value ?? '')
      .replace(/(?:Bearer|Basic)\s+[A-Za-z0-9._~+\/=\/-]+/gi, match => `${match.split(/\s+/)[0]} [已隐藏]`)
      .replace(/([?&](?:key|api[_-]?key|token|access[_-]?token|secret|password)=)[^&\s]+/gi, '$1[已隐藏]')
      .replace(/("?(?:api[_-]?key|x-api-key|access[_-]?token|client[_-]?secret|secret|authorization|proxy_password|password|key|token)"?\s*[:=]\s*")[^"]+/gi, '$1[已隐藏]')
      .replace(/((?:api[_-]?key|x-api-key|access[_-]?token|client[_-]?secret|secret|authorization|proxy_password|password|key|token)\s*[:=]\s*)(?!\[已隐藏\])[^\s,;}"]+/gi, '$1[已隐藏]');
  }

  function foxJudgeDiagError(error) {
    if (!error) return null;
    const seen = new Set();
    const serialize = (value, depth = 0) => {
      if (value == null || depth > 3) return value == null ? value : '[depth-limit]';
      if (typeof value !== 'object') return ssRedactDiagnosticText(value);
      if (seen.has(value)) return '[circular]';
      seen.add(value);
      const out = {
        name: String(value.name || value.constructor?.name || 'Error'),
        message: ssRedactDiagnosticText(value.message || value.statusText || value),
      };
      if (value.stack) out.stack = ssRedactDiagnosticText(value.stack);
      if (value.code != null) out.code = String(value.code);
      if (value.status != null) out.status = value.status;
      if (value.type != null) out.type = String(value.type);
      if (value.cause != null && value.cause !== value) out.cause = serialize(value.cause, depth + 1);
      return out;
    };
    return serialize(error);
  }

  function foxJudgeDiagValue(value, depth = 0) {
    if (value == null || typeof value === 'number' || typeof value === 'boolean') return value;
    if (typeof value === 'string') {
      const safe = ssRedactDiagnosticText(value);
      return safe.length > 500
        ? `${safe.slice(0, 240)}...[省略 ${safe.length - 480} 字符]...${safe.slice(-240)}`
        : safe;
    }
    if (value instanceof Error || value?.stack) return foxJudgeDiagError(value);
    if (depth > 4) return '[depth-limit]';
    if (Array.isArray(value)) return value.slice(0, 30).map(v => foxJudgeDiagValue(v, depth + 1));
    if (typeof value === 'object') {
      const out = {};
      for (const [key, item] of Object.entries(value).slice(0, 60)) {
        if (/^(key|api[_-]?key|x-api-key|access[_-]?token|client[_-]?secret|secret|password|proxy_password|authorization|cookie|token)$/i.test(key)) {
          out[key] = item ? '[已隐藏]' : '';
        } else {
          out[key] = foxJudgeDiagValue(item, depth + 1);
        }
      }
      return out;
    }
    return String(value);
  }

  function foxJudgeBeginDiag(source, meta = {}) {
    const diag = {
      id: `FJ-${Date.now().toString(36)}-${(++foxJudgeDiagSeq).toString(36)}`,
      source: String(source || 'unknown'),
      startedAt: Date.now(),
    };
    foxJudgeActiveDiag = diag;
    foxJudgeLastDiag = diag;
    foxJudgeDiag('会话开始', meta, 'info', diag);
    return diag;
  }

  function foxJudgeDiag(stage, data = {}, level = 'log', diag = foxJudgeActiveDiag || foxJudgeLastDiag) {
    try {
      const id = diag?.id || 'FJ-NO-SESSION';
      const elapsed = diag?.startedAt ? Date.now() - diag.startedAt : 0;
      const method = level === 'error' ? 'error' : (level === 'warn' ? 'warn' : (level === 'info' ? 'info' : 'log'));
      const safeData = foxJudgeDiagValue(data);
      let detail = '';
      try { detail = JSON.stringify(safeData); } catch { detail = String(safeData ?? ''); }
      // 酒馆日志查看器会把 console 的第二个对象参数强制显示成 [object Object]，
      // 因此诊断数据必须序列化进同一个字符串参数，截图中才能直接看到错误细节。
      console[method](`[狐裁诊断][${id}][+${elapsed}ms][${stage}] ${detail}`);
    } catch (e) {
      try { console.error('[狐裁诊断][日志器自身失败]', e); } catch { }
    }
  }

  function foxJudgeEndDiag(outcome, data = {}, diag = foxJudgeActiveDiag || foxJudgeLastDiag) {
    foxJudgeDiag(`会话结束:${outcome}`, data, outcome === 'success' ? 'info' : 'error', diag);
    if (foxJudgeActiveDiag === diag) foxJudgeActiveDiag = null;
  }

  let ssModuleDiagSeq = 0;
  const ssModuleDiagByGenerationId = new Map();
  const ssDirectModuleDiags = new Set();
  function ssModuleDiagBegin(module, action, meta = {}) {
    const diag = {
      id: `XH-${Date.now().toString(36)}-${(++ssModuleDiagSeq).toString(36)}`,
      module: String(module || '玄狐'),
      action: String(action || '任务'),
      startedAt: Date.now(),
    };
    ssModuleDiag(diag, '开始', meta, 'info');
    return diag;
  }

  function ssModuleDiag(diag, stage, data = {}, level = 'log') {
    try {
      const method = level === 'error' ? 'error' : (level === 'warn' ? 'warn' : (level === 'info' ? 'info' : 'log'));
      const elapsed = diag?.startedAt ? Date.now() - diag.startedAt : 0;
      const safeData = foxJudgeDiagValue(data);
      let detail = '';
      try { detail = JSON.stringify(safeData); } catch { detail = String(safeData ?? ''); }
      console[method](`[玄狐诊断][${diag?.module || '玄狐'}][${diag?.id || 'NO-SESSION'}][+${elapsed}ms][${stage}] ${detail}`);
    } catch (e) {
      try { console.error('[玄狐诊断][日志器自身失败]', e); } catch { }
    }
  }

  function ssModuleFromTaskName(taskName, label = '') {
    const text = `${taskName || ''} ${label || ''}`.toLowerCase();
    if (/outline|狐构/.test(text)) return '狐构';
    if (/fox_memory|foxmem|狐忆/.test(text)) return '狐忆';
    if (/fox_judge|狐裁/.test(text)) return '狐裁';
    if (/hushen|狐析/.test(text)) return '狐析';
    if (/husou|狐搜/.test(text)) return '狐搜';
    if (/parallel_world|平行世界/.test(text)) return '平行世界';
    if (/novel|小说/.test(text)) return '小说模式';
    if (/summary|beat|总结|拷打/.test(text)) return '总结与分析';
    return '玄狐核心';
  }

  function foxJudgeResponseSummary(value) {
    const summary = {
      jsType: value === null ? 'null' : (Array.isArray(value) ? 'array' : typeof value),
    };
    if (typeof value === 'string') {
      summary.rawLength = value.length;
      summary.trimmedLength = value.trim().length;
      summary.startsLikeJson = /^[\s]*[\[{]/.test(value);
    } else if (value && typeof value === 'object') {
      summary.keys = Object.keys(value).slice(0, 40);
      if (Array.isArray(value.choices)) summary.choiceCount = value.choices.length;
      if (Array.isArray(value.content)) summary.contentBlockCount = value.content.length;
    }
    try { summary.extractedTextLength = foxJudgeExtractText(value).trim().length; } catch { }
    return summary;
  }

  function foxJudgeIsUserCancellation(error) {
    let current = error;
    for (let depth = 0; current && depth < 5; depth++) {
      if (current.__ssUserCancelled === true) return true;
      current = current.cause && current.cause !== current ? current.cause : null;
    }
    return ssActiveTasks.get('fox_judge_chain')?.cancelled === true;
  }
  function getFn(n) { return topWindow?.[n] || window?.[n]; }
  const getPreset = (...args) => getFn('getPreset')?.(...args);
  const updatePresetWith = (...args) => getFn('updatePresetWith')?.(...args);
  const eventOn = (...args) => getFn('eventOn')?.(...args);
  const getPresetNames = (...args) => getFn('getPresetNames')?.(...args);
  const replacePreset = (...args) => getFn('replacePreset')?.(...args);
  const setPreset = (...args) => getFn('setPreset')?.(...args);
  const createChatMessages = (...args) => getFn('createChatMessages')?.(...args);
  const eventEmit = (...args) => getFn('eventEmit')?.(...args);

  const tavern_events = getFn('tavern_events') || {
    GENERATION_STARTED: 'generation_started',
    GENERATION_ENDED: 'generation_ended',
    CHARACTER_EDITED: 'character_edited',

    MESSAGE_SENT: 'message_sent',
