  function ssPromptLikeToText(value, limit = 240000) {
    const out = [];
    let used = 0;
    const push = (v) => {
      if (v == null || used >= limit) return;
      const s = String(v);
      if (!s) return;
      const room = limit - used;
      out.push(s.length > room ? s.slice(0, room) : s);
      used += Math.min(s.length, room);
    };
    const walk = (v, depth = 0) => {
      if (v == null || used >= limit || depth > 4) return;
      if (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') {
        push(v);
        return;
      }
      if (Array.isArray(v)) {
        for (const x of v) walk(x, depth + 1);
        return;
      }
      if (typeof v === 'object') {
        push(v.identifier);
        push(v.name);
        push(v.role);
        push(v.content);
        push(v.prompt);
        push(v.user_input);
        push(v.message);
        if (Array.isArray(v.chat)) walk(v.chat, depth + 1);
        if (Array.isArray(v.messages)) walk(v.messages, depth + 1);
