              const nxt = lines[idx];
              if (nxt.indent < subBaseIndent) break;
              if (nxt.indent !== subBaseIndent) break;
              if (nxt.content.startsWith('- ')) break;
              const colon2 = nxt.content.indexOf(':');
              if (colon2 < 0) break;
              idx++;
              handleKV(nxt.content);
            }
            arr.push(obj);
          } else {
            arr.push(parseScalar(after));
          }
        }
        return arr;
      }
      // 对象
      const obj = {};
      while (idx < lines.length) {
        const cur = lines[idx];
        if (cur.indent < baseIndent) break;
        if (cur.indent !== baseIndent) break;
        if (cur.content.startsWith('- ')) break;
        const colon = cur.content.indexOf(':');
        if (colon < 0) break;
        const key = cur.content.slice(0, colon).trim().replace(/^["']|["']$/g, '');
        const val = cur.content.slice(colon + 1).trim();
        idx++;
        if (val === '') {
          const next = peek();
          if (next && next.indent > baseIndent) {
            obj[key] = parseBlock(next.indent);
          } else {
            obj[key] = null;
          }
        } else {
          obj[key] = parseScalar(val);
        }
      }
      return obj;
    }

    try {
      const baseIndent = lines[0].indent;
      const result = parseBlock(baseIndent);
      return result;
    } catch (e) {
      log('[附加参数] YAML 解析失败', e);
      return null;
    }
  }

  // 从 customApi-like 对象中读取三个 YAML 字段，构建 inject。
  // customApi 至少包含：extraBodyParamsYaml / excludeBodyParamsYaml / extraHeadersYaml
  //
  // ⚠️ 关键修复：SillyTavern 服务端在 /api/backends/chat-completions/generate 里，
  //    只在 chat_completion_source === 'custom' 时，读取请求体里的三个原生字段：
  //      custom_include_body   (YAML 文本 -> mergeObjectWithYaml 进上游请求体)
  //      custom_exclude_body   (YAML 数组 -> excludeKeysByYaml 从上游请求体删 key)
  //      custom_include_headers(YAML 文本 -> mergeObjectWithYaml 进上游请求头)
  //    服务端只把这三个字段透传给上游，**不会**把我们额外塞到顶层的 top_k / 自定义 header
  //    转发出去——这正是"附加参数填了却完全不生效"的根因。
  //    因此这里保留用户填写的**原始 YAML 文本**，由 fetch hook 写进上述原生字段，
  //    与酒馆原生"附加参数"完全等效。YAML 解析仅用于校验格式，不参与最终注入。
  function ssBuildExtraInjectFromCustomApi(customApi) {
    if (!customApi) return null;
    const inject = { includeBodyYaml: null, excludeBodyYaml: null, includeHeadersYaml: null };
    let any = false;

    const bodyText = customApi.extraBodyParamsYaml;
    if (typeof bodyText === 'string' && bodyText.trim()) {
      const parsed = ssParseSimpleYaml(bodyText);
      if (ssIsPlainObject(parsed)) {
        // ✅ 统一回写为规范文本（JSON 是合法的 YAML flow，服务端 yaml.parse 能可靠解析）。
        //    直接转发用户原始文本会在“多行 JSON”这类输入下被服务端 YAML 解析器误读，
        //    导致字段（如 thinking）丢失——这正是“附加参数填了却完全不生效”的根因之一。
        inject.includeBodyYaml = JSON.stringify(parsed);
        any = true;
      } else if (parsed != null) {
        log('[附加参数] 包括主体参数 必须是 YAML/JSON 对象，已忽略');
      } else {
        log('[附加参数] 包括主体参数 解析失败（非合法 YAML/JSON），已忽略');
      }
    }

    const exclText = customApi.excludeBodyParamsYaml;
    if (typeof exclText === 'string' && exclText.trim()) {
      const parsed = ssParseSimpleYaml(exclText);
      if (Array.isArray(parsed)) {
        const arr = parsed.map(x => String(x || '').trim()).filter(Boolean);
        if (arr.length) {
          inject.excludeBodyYaml = JSON.stringify(arr);
          any = true;
        }
      } else if (parsed != null) {
        log('[附加参数] 排除主体参数 必须是 YAML/JSON 数组，已忽略');
      } else {
        log('[附加参数] 排除主体参数 解析失败（非合法 YAML/JSON），已忽略');
      }
    }

    const hdrText = customApi.extraHeadersYaml;
    if (typeof hdrText === 'string' && hdrText.trim()) {
      const parsed = ssParseSimpleYaml(hdrText);
      if (ssIsPlainObject(parsed)) {
        if (Object.keys(parsed).length) {
          inject.includeHeadersYaml = JSON.stringify(parsed);
          any = true;
        }
      } else if (parsed != null) {
        log('[附加参数] 包含请求标头 必须是 YAML/JSON 对象，已忽略');
      } else {
        log('[附加参数] 包含请求标头 解析失败（非合法 YAML/JSON），已忽略');
      }
    }

    return any ? inject : null;
  }

  // 设置 / 应用 fetch hook。只 hook 一次。
  let __ssFetchHookInstalled = false;
  function ssInstallExtraInjectFetchHook() {
    if (__ssFetchHookInstalled) return;
    __ssFetchHookInstalled = true;

    const targets = [];
    try { if (topWindow && topWindow.fetch) targets.push(topWindow); } catch { }
    if (window !== topWindow && window.fetch) targets.push(window);

    const isTarget = (url) => {
      try {
        const s = String(url || '');
        return s.includes('/api/backends/chat-completions/generate');
      } catch { return false; }
    };

    const applyInject = (init, inject) => {
      const newInit = { ...(init || {}) };
      // ✅ 先无条件剥离脚本注入的关联令牌 ssInjectToken（仅用于 hook 内部精确匹配 entry，
      //    绝不能透传到上游 API，否则可能被部分服务端当作非法字段拒绝）。
      if (newInit.body && typeof newInit.body === 'string' && newInit.body.includes('ssInjectToken')) {
        try {
          const o = JSON.parse(newInit.body);
          if (ssIsPlainObject(o) && 'ssInjectToken' in o) {
            delete o.ssInjectToken;
            newInit.body = JSON.stringify(o);
          }
        } catch { }
      }
      // ✅ 与酒馆原生"附加参数"完全等效：把用户填写的 YAML 文本写进请求体的三个原生字段
      //    custom_include_body / custom_exclude_body / custom_include_headers。
      //
      // ⚠️ 关键修复（之前完全不生效的真正根因）：
      //    SillyTavern 服务端 /api/backends/chat-completions/generate **只在**
      //    chat_completion_source === 'custom' 时，才读取并透传上述三个原生字段
      //    （见服务端 mergeObjectWithYaml(bodyParams, custom_include_body) /
      //     excludeKeysByYaml(requestBody, custom_exclude_body) /
      //     mergeObjectWithYaml(headers, custom_include_headers)）。
      //    而本脚本各模块构建的 custom_api.source 默认是 'openai'（直连 reverse_proxy），
      //    宿主 TavernHelper 会把 generate_data.chat_completion_source 设成 'openai'，
      //    于是服务端的最终上游请求体只取固定白名单字段（messages/model/temperature/...），
      //    custom_include_body 等三个字段被**整个丢弃** —— 这就是"附加参数填了却完全不生效"的真因。
      //
      //    修复思路与「数据库.js」一致：把本次请求**就地升级成 source==='custom'**，
      //    并把 openai 直连用的 reverse_proxy / proxy_password 映射成 custom 源所需的
      //    custom_url 与 Authorization 头（写进 custom_include_headers），
      //    然后再写入三个原生字段。这样服务端就会按 custom 源逻辑透传附加参数。
      if ((inject.includeBodyYaml || inject.excludeBodyYaml || inject.includeHeadersYaml)
        && newInit.body && typeof newInit.body === 'string') {
        try {
          const obj = JSON.parse(newInit.body);
          if (ssIsPlainObject(obj)) {
            // ① 解析出最终要写入 custom_include_headers 的对象：用户填写的标头 + Authorization。
            let headerObj = {};
            if (inject.includeHeadersYaml) {
              try {
                const parsedHdr = JSON.parse(inject.includeHeadersYaml);
                if (ssIsPlainObject(parsedHdr)) headerObj = { ...parsedHdr };
              } catch { /* includeHeadersYaml 总是由本脚本 JSON.stringify 而来，正常不会失败 */ }
            }

            // ② 把请求就地升级成 custom 源，让服务端读取三个原生字段。
            //    仅当当前是非 custom 源、且带有直连 reverse_proxy 时才升级，
            //    避免破坏用户本就走 custom 源 / 走酒馆主源（无 reverse_proxy）的请求。
            const proxyUrl = obj.reverse_proxy || obj.custom_url;
            if (obj.chat_completion_source !== 'custom' && proxyUrl) {
              obj.chat_completion_source = 'custom';
              obj.custom_url = proxyUrl;
              obj.reverse_proxy = proxyUrl;
              // custom 源的上游鉴权头取自 custom_include_headers 里的 Authorization；
              // 把 openai 直连用的 proxy_password 补进去，避免升级后丢 key 导致 401。
              if (obj.proxy_password && !('Authorization' in headerObj)) {
                headerObj.Authorization = `Bearer ${obj.proxy_password}`;
              }
            } else if (obj.chat_completion_source === 'custom'
              && typeof obj.custom_include_headers === 'string'
              && obj.custom_include_headers.trim()) {
              // ✅ 用户本就走 custom 源：宿主可能已写好 custom_include_headers
              //    （含 TavernHelper 注入的 Authorization）。此处与用户填写的附加标头**合并**而非覆盖，
              //    用户标头优先，但保留宿主已设的鉴权头，避免直接 JSON.stringify(headerObj) 把 key 抹掉导致 401。
              try {
                const existing = ssParseSimpleYaml(obj.custom_include_headers);
                if (ssIsPlainObject(existing)) headerObj = { ...existing, ...headerObj };
              } catch { /* 解析失败则保持用户标头，至少不比旧行为差 */ }
            }

            // ③ 写入三个原生字段（custom_include_headers 用合并后的对象 -> JSON 文本）。
            if (inject.includeBodyYaml) {
              obj.custom_include_body = inject.includeBodyYaml;
            }
            if (inject.excludeBodyYaml) {
              obj.custom_exclude_body = inject.excludeBodyYaml;
            }
            if (Object.keys(headerObj).length) {
              obj.custom_include_headers = JSON.stringify(headerObj);
            }
            newInit.body = JSON.stringify(obj);
          }
        } catch (e) {
          log('[附加参数] 解析请求体失败，跳过本次注入', e);
        }
      }
      return newInit;
    };

    // ✅ 判定"这是不是一次真正的对话生成请求"。
    //    同一个 /generate 端点在一次 generateRaw 周期内，宿主可能先发起 token 计数 / 探测 /
    //    预检请求，再发起真正的生成请求。旧逻辑用纯 FIFO "见到第一个匹配 URL 就消费 entry"，
    //    会让探测请求把本应用于真正生成请求的注入吃掉 —— 这正是"阶段一思考没应用附加参数、
    //    阶段二却正常"的根因（阶段一恰好多了一个前置请求）。
    //    这里要求请求体里出现 messages / prompt / chat_completion_source 等"真生成"特征字段，
    //    才允许消费注入；拿不到 body 时按真生成处理（保持旧行为，不会漏注入）。
    const bodyLooksLikeRealGenerate = (bodyText) => {
      if (typeof bodyText !== 'string' || !bodyText) return true;
      try {
        const obj = JSON.parse(bodyText);
        if (!ssIsPlainObject(obj)) return true;
        if (Array.isArray(obj.messages)) return true;
        if (typeof obj.prompt === 'string' && obj.prompt) return true;
        if ('chat_completion_source' in obj) return true;
        if (Array.isArray(obj.prompt)) return true;
        // 明显的探测/计数请求特征：只带 token 计数相关字段、没有 messages/prompt
        if ('only_count_tokens' in obj || 'getCount' in obj) return false;
        // 既不像真生成、也无明显计数特征：保守按"真生成"处理，避免漏注入
        return true;
      } catch {
        return true;
      }
    };

    // 取"尚未被消费且未被占用"的 entry，并立刻标记 claimed 占用。
    // ✅ 并发健壮性：匹配优先级 ssInjectToken（唯一、最权威）> generation_id（次级，同名任务复用时可能相同）
    //    > FIFO（仅当两者都被宿主剥离时回退）。这样可避免多模块同时运行时把 A 模块的注入
    //    （含自定义 API key/url/model/headers）错配到 B 模块的请求上造成"串台"。
    const takeEntry = (keys) => {
      const token = keys && keys.token != null ? keys.token : null;
      const genId = keys && keys.genId ? keys.genId : null;
      // 1) 有 ssInjectToken：它是每个 entry 唯一的 id，最权威，只接受 token 精确匹配。
      //    匹配不到则绝不错配别的 entry（返回 null，不注入）。
      if (token != null) {
        for (let i = 0; i < ssExtraInjectQueue.length; i++) {
          const e = ssExtraInjectQueue[i];
          if (!e.done && !e.claimed && e.id === token) { e.claimed = true; return e; }
        }
        return null;
      }
      // 2) 无 token 但有 generation_id：作为次级通道匹配。
      //    ⚠️ generation_id 在同名任务并发复用时可能相同，仅在 token 缺失时才用它，避免歧义。
      if (genId != null) {
        for (let i = 0; i < ssExtraInjectQueue.length; i++) {
          const e = ssExtraInjectQueue[i];
          if (!e.done && !e.claimed && e.genId && e.genId === genId) { e.claimed = true; return e; }
        }
        return null;
      }
      // 3) 无任何标识（宿主剥离了自定义字段且未透传 generation_id）：回退 FIFO。
      for (let i = 0; i < ssExtraInjectQueue.length; i++) {
        const e = ssExtraInjectQueue[i];
        if (!e.done && !e.claimed) { e.claimed = true; return e; }
      }
      return null;
    };
    // 释放占用：用于"取到了 entry 但本次请求其实不是真生成"的场景，把它还给后续真请求。
    const releaseEntry = (entry) => {
      if (entry && !entry.done) entry.claimed = false;
    };

    // 从请求体文本里提取关联标识：ssInjectToken（脚本写入的数字令牌）与 generation_id（字符串）。
    const extractInjectKeys = (bodyText) => {
      const out = { token: null, genId: null };
      if (typeof bodyText !== 'string' || !bodyText) return out;
      try {
        const obj = JSON.parse(bodyText);
        if (ssIsPlainObject(obj)) {
          if (obj.ssInjectToken != null) {
            const n = Number(obj.ssInjectToken);
            if (Number.isFinite(n)) out.token = n;
          }
          if (typeof obj.generation_id === 'string' && obj.generation_id) out.genId = obj.generation_id;
        }
      } catch { }
      return out;
    };

    // 把 body 文本里的 ssInjectToken 去掉后返回新文本；无该字段或无法解析则原样返回 null（表示无需改写）。
    const stripTokenFromBody = (bodyText) => {
      if (typeof bodyText !== 'string' || !bodyText || !bodyText.includes('ssInjectToken')) return null;
      try {
        const o = JSON.parse(bodyText);
        if (ssIsPlainObject(o) && 'ssInjectToken' in o) {
          delete o.ssInjectToken;
          return JSON.stringify(o);
        }
      } catch { }
      return null;
    };

    // 放行一个目标请求，但确保 ssInjectToken 不会被透传到上游（未命中注入时也要清理）。
    const forwardWithoutToken = (orig, input, init, isRequestObj, bodyText) => {
      const cleaned = stripTokenFromBody(bodyText);
      if (cleaned == null) return orig(input, init);
      try {
        if (isRequestObj) {
          const reqInit = {
            method: input.method,
            headers: input.headers,
            credentials: input.credentials,
            cache: input.cache,
            redirect: input.redirect,
            referrer: input.referrer,
            integrity: input.integrity,
          };
          const baseInit = { ...reqInit, ...(init || {}), body: cleaned };
          return orig(input.url, baseInit);
        }
        return orig(input, { ...(init || {}), body: cleaned });
      } catch {
        return orig(input, init);
      }
    };

    for (const w of targets) {
      const orig = w.fetch.bind(w);
      w.fetch = function (input, init) {
        let __claimed = null;
        try {
          // 🦊 dry-run 短路（最高优先级）：识别玄狐"为抓取完整 prompt 而发起的静默 generate"，
          //    在请求真正发往上游主模型之前直接返回伪响应。
          //    - prompt 组合事件早在 fetch 之前已经触发，监听器已经捕获到完整 prompt；
          //    - 短路后宿主拿到一个合法的 OpenAI 风格 JSON，generate Promise 自然 resolve，
          //      不会真的产生 input/output token 费用。
          //    只对 chat-completions/generate 这类目标 URL 短路，避免误伤无关请求。
          if (__ssDryRunMarkers.size) {
            const url = typeof input === 'string' ? input : (input && input.url) || '';
            if (isTarget(url)) {
              const isRequestObj = typeof input !== 'string' && input && typeof input === 'object' && input.url;
              let syncBody = null;
              if (init && typeof init.body === 'string') syncBody = init.body;
              else if (typeof input !== 'string' && input && typeof input.body === 'string') syncBody = input.body;

              if (isRequestObj && syncBody == null) {
                return (async () => {
                  let bodyText = null;
                  try { bodyText = await input.clone().text(); } catch { }
                  const hit = ssBodyMatchesDryRunMarker(bodyText);
                  if (hit) {
                    log('[dry-run 短路] 命中 marker, 跳过主模型上游请求');
                    return ssMakeDryRunShortCircuitResponse(hit);
                  }
                  return orig(input, init);
                })();
              }

              const hit = ssBodyMatchesDryRunMarker(syncBody);
              if (hit) {
                log('[dry-run 短路] 命中 marker, 跳过主模型上游请求');
                return Promise.resolve(ssMakeDryRunShortCircuitResponse(hit));
              }
            }
          }

          if (ssExtraInjectQueue.length) {
            const url = typeof input === 'string'
              ? input
              : (input && input.url) || '';
            if (isTarget(url)) {
              const isRequestObj = typeof input !== 'string' && input && typeof input === 'object' && input.url;

              let syncBody = null;
              if (init && typeof init.body === 'string') syncBody = init.body;
              else if (typeof input !== 'string' && input && typeof input.body === 'string') syncBody = input.body;

              if (isRequestObj && syncBody == null) {
                return (async () => {
                  let bodyText = null;
                  try { bodyText = await input.clone().text(); }
                  catch (e) { log('[附加参数] 读取 Request body 失败，跳过主体参数注入', e); }

                  if (!bodyLooksLikeRealGenerate(bodyText)) {
                    return forwardWithoutToken(orig, input, init, true, bodyText);
                  }

                  const keys = extractInjectKeys(bodyText);
                  const entry = takeEntry(keys);
                  if (!entry || !entry.inject) {
                    if (entry) releaseEntry(entry);
                    return forwardWithoutToken(orig, input, init, true, bodyText);
                  }
                  entry.done = true;
                  const reqInit = {
                    method: input.method,
                    headers: input.headers,
                    credentials: input.credentials,
                    cache: input.cache,
                    redirect: input.redirect,
                    referrer: input.referrer,
                    integrity: input.integrity,
                  };
                  const baseInit = { ...reqInit, ...(init || {}) };
                  if (typeof bodyText === 'string') baseInit.body = bodyText;
                  const merged = applyInject(baseInit, entry.inject);
                  return orig(input.url, merged);
                })();
              }

              if (!bodyLooksLikeRealGenerate(syncBody)) {
                return forwardWithoutToken(orig, input, init, isRequestObj, syncBody);
              }

              const keys = extractInjectKeys(syncBody);
              const entry = takeEntry(keys);
              if (entry && entry.inject) {
                __claimed = entry;
                entry.done = true;
                if (isRequestObj) {
                  const reqInit = {
                    method: input.method,
                    headers: input.headers,
                    credentials: input.credentials,
                    cache: input.cache,
                    redirect: input.redirect,
                    referrer: input.referrer,
                    integrity: input.integrity,
                  };
                  const baseInit = { ...reqInit, ...(init || {}) };
                  if (typeof syncBody === 'string') baseInit.body = syncBody;
                  const merged = applyInject(baseInit, entry.inject);
                  return orig(input.url, merged);
                }
                const merged = applyInject(init, entry.inject);
                return orig(input, merged);
              } else {
                if (entry) releaseEntry(entry);
                return forwardWithoutToken(orig, input, init, isRequestObj, syncBody);
              }
            }
          }
        } catch (e) {
          log('[附加参数] fetch hook 内部错误', e);
        } finally {
          // 占用了 entry 但同步路径既没消费（done）也没显式释放（异常 / inject 为空 / 落到兜底）时，
          // 在这里释放回队列，避免 entry 被永久占住导致后续真生成请求拿不到注入。
          // 已 done 的 entry 不会被释放（releaseEntry 内有 !done 守卫）。
          if (__claimed && !__claimed.done) { try { releaseEntry(__claimed); } catch { } }
        }
        return orig(input, init);
      };
    }
    log('[附加参数] fetch hook 已安装');
  }

  let __foxJudgeFetchDiagInstalled = false;
  function ssInstallFoxJudgeFetchDiagnostics() {
    if (__foxJudgeFetchDiagInstalled) return;
    __foxJudgeFetchDiagInstalled = true;
    const targets = [];
    try { if (topWindow?.fetch) targets.push(topWindow); } catch { }
    try { if (window !== topWindow && window.fetch) targets.push(window); } catch { }

    const readBody = async (input, init) => {
      if (typeof init?.body === 'string') return init.body;
      if (input && typeof input !== 'string' && typeof input.clone === 'function') {
        try { return await input.clone().text(); } catch { }
      }
      return '';
    };

    const safeErrorBody = text => {
      const raw = String(text || '');
      try {
        const parsed = JSON.parse(raw);
        const error = parsed?.error;
        return foxJudgeDiagValue({
          error: typeof error === 'string' ? error : {
            message: error?.message || '',
            type: error?.type || '',
            code: error?.code || '',
            param: error?.param || '',
          },
          message: parsed?.message || '',
          detail: parsed?.detail || '',
          code: parsed?.code || '',
          type: parsed?.type || '',
        });
      } catch { }
      return raw.slice(0, 1600)
        .replace(/("?(?:api[_-]?key|authorization|proxy_password|key|token)"?\s*[:=]\s*")[^"]+/gi, '$1[已隐藏]')
        .replace(/Bearer\s+[A-Za-z0-9._~+\/-]+/gi, 'Bearer [已隐藏]');
    };

    for (const target of targets) {
      const orig = target.fetch.bind(target);
      target.fetch = async function (input, init) {
        const url = typeof input === 'string' ? input : (input?.url || '');
        const isGenerateEndpoint = String(url).includes('/api/backends/chat-completions/generate');
        if (!isGenerateEndpoint) return orig(input, init);

        const bodyText = await readBody(input, init);
        let body = null;
        try { body = bodyText ? JSON.parse(bodyText) : null; } catch { }
        const generationId = String(body?.generation_id || '');
        const directDiag = !generationId && ssDirectModuleDiags.size === 1 ? [...ssDirectModuleDiags][0] : null;
        if (!generationId.startsWith('xuanhu_') && !directDiag) return orig(input, init);
        const moduleDiag = ssModuleDiagByGenerationId.get(generationId) || directDiag || null;
        const isFoxJudgeGeneration = generationId.startsWith('xuanhu_fox_judge_chain_request_');

        const startedAt = Date.now();
        const messages = Array.isArray(body?.messages) ? body.messages : [];
        if (isFoxJudgeGeneration) foxJudgeDiag('网络:请求发出', {
          generationId,
          url: (() => { try { const u = new URL(String(url), topWindow?.location?.origin || location.origin); return `${u.origin}${u.pathname}`; } catch { return String(url).replace(/[?#].*$/, ''); } })(),
          method: init?.method || input?.method || 'GET',
          bodyLength: bodyText.length,
          chatCompletionSource: body?.chat_completion_source || '',
          model: body?.model || '',
          messageCount: messages.length,
          messageRoles: messages.map(m => m?.role || '').slice(0, 40),
          messageLengths: messages.map(m => String(m?.content || '').length).slice(0, 40),
          hasCustomUrl: !!body?.custom_url,
          hasReverseProxy: !!body?.reverse_proxy,
          hasProxyPassword: !!body?.proxy_password,
          hasCustomIncludeBody: !!body?.custom_include_body,
          hasCustomExcludeBody: !!body?.custom_exclude_body,
          hasCustomIncludeHeaders: !!body?.custom_include_headers,
          stream: body?.stream ?? null,
          maxTokens: body?.max_tokens ?? body?.max_completion_tokens ?? null,
        });
        if (!isFoxJudgeGeneration) {
          ssModuleDiag(moduleDiag, '网络:请求发出', {
            generationId,
            url: (() => { try { const u = new URL(String(url), topWindow?.location?.origin || location.origin); return `${u.origin}${u.pathname}`; } catch { return String(url).replace(/[?#].*$/, ''); } })(),
            method: init?.method || input?.method || 'GET',
            bodyLength: bodyText.length,
            chatCompletionSource: body?.chat_completion_source || '',
            model: body?.model || '',
            messageCount: messages.length,
            messageRoles: messages.map(m => m?.role || '').slice(0, 40),
            messageLengths: messages.map(m => String(m?.content || '').length).slice(0, 40),
            stream: body?.stream ?? null,
            maxTokens: body?.max_tokens ?? body?.max_completion_tokens ?? null,
          });
        }

        try {
          const response = await orig(input, init);
          const responseMeta = {
            generationId,
            durationMs: Date.now() - startedAt,
            status: response?.status,
            statusText: response?.statusText || '',
            ok: response?.ok,
            contentType: response?.headers?.get?.('content-type') || '',
          };
          if (response && !response.ok) {
            try { responseMeta.errorBody = safeErrorBody(await response.clone().text()); } catch { }
          }
          if (isFoxJudgeGeneration) foxJudgeDiag('网络:收到响应', responseMeta, response?.ok ? 'info' : 'error');
          if (!isFoxJudgeGeneration) ssModuleDiag(moduleDiag, '网络:收到响应', responseMeta, response?.ok ? 'info' : 'error');
          return response;
        } catch (e) {
          if (isFoxJudgeGeneration) foxJudgeDiag('网络:fetch抛出异常', {
            generationId,
            durationMs: Date.now() - startedAt,
            error: foxJudgeDiagError(e),
          }, 'error');
          if (!isFoxJudgeGeneration) {
            ssModuleDiag(moduleDiag, '网络:fetch抛出异常', {
              generationId,
              durationMs: Date.now() - startedAt,
              error: foxJudgeDiagError(e),
            }, 'error');
          }
          throw e;
        }
      };
    }
    log('[狐裁诊断] fetch 网络诊断已安装');
  }

  // 入队：用于一次 generateRaw 调用周期内激活附加参数。返回 handle（即 entry 本身）。
  // genId：可选的关联 generation_id（字符串），作为 ssInjectToken 之外的第二条精确匹配通道，
  //        因为 generation_id 一定会落进请求体（宿主用它来 stopGenerationById），可靠性更高。
  function ssPushExtraInject(inject, genId) {
    if (!inject) return null;
    const entry = { id: ++__ssExtraInjectSeq, inject, done: false, claimed: false, genId: genId || null };
    ssExtraInjectQueue.push(entry);
    return entry;
  }
  // 出队：把该 entry 标记 done 并移出队列。
  // 即使本次调用产生的 fetch 已经消费过它（done=true），这里也只是安全地把它清出队列。
  function ssPopExtraInject(handle) {
    if (!handle) return;
    handle.done = true;
    const i = ssExtraInjectQueue.indexOf(handle);
    if (i >= 0) ssExtraInjectQueue.splice(i, 1);
  }

  // 三个模块面板共享的 HTML / 事件绑定工具。
  // panelKey: 字符串前缀，避免 id 冲突（如 'foxjudge' / 'foxmem' / 'husou'）
  // values:   { extraBodyParamsYaml, excludeBodyParamsYaml, extraHeadersYaml }
  function ssRenderExtraParamsPanelHtml(panelKey, values, opts = {}) {
    const v = values || {};
    const accent = opts.accent || '#f0a070';
    const border = opts.border || 'rgba(232,120,74,0.12)';
    const bg = opts.bg || 'rgba(255,255,255,0.02)';
    const inputBg = opts.inputBg || 'rgba(255,255,255,0.04)';
    const inputBorder = opts.inputBorder || 'rgba(232,120,74,0.15)';
    const labelColor = opts.labelColor || '#706058';
    const hintColor = opts.hintColor || '#8a7a72';
    const textColor = opts.textColor || '#e8ddd4';

    const ta = (id, val, ph, rows = 4) =>
      `<textarea id="${id}" rows="${rows}" placeholder="${escapeHtml(ph)}" style="width:100%;box-sizing:border-box;background:${inputBg};border:1px solid ${inputBorder};border-radius:6px;color:${textColor};padding:6px 8px;font-size:12px;font-family:monospace;resize:vertical;">${escapeHtml(val || '')}</textarea>`;

    return `
      <details style="margin-top:10px;border:1px solid ${border};border-radius:8px;background:${bg};">
        <summary style="cursor:pointer;padding:8px 10px;color:${accent};font-size:12px;font-weight:600;user-select:none;">🧬 附加参数（YAML）</summary>
        <div style="padding:10px;display:flex;flex-direction:column;gap:10px;">
          <div style="font-size:11px;color:${hintColor};line-height:1.6;">
            这里的设置在向 <b>聊天完成请求</b> 发送时生效，与酒馆原生"附加参数"等效：<br>
            • <b>包括主体参数</b>：YAML 对象，会合并进请求体；<br>
            • <b>排除主体参数</b>：YAML 数组，会从请求体里删除对应字段；<br>
            • <b>包含请求标头</b>：YAML 对象，会以 header 形式附加到请求。
          </div>

          <div>
            <label style="font-size:11px;color:${labelColor};display:block;margin-bottom:4px;">
              📦 包括主体参数（YAML 对象）
            </label>
            ${ta(`${panelKey}-extra-body-yaml`, v.extraBodyParamsYaml, 'top_k: 20\nrepetition_penalty: 1.1', 5)}
          </div>

          <div>
            <label style="font-size:11px;color:${labelColor};display:block;margin-bottom:4px;">
              🚫 排除主体参数（YAML 数组）
            </label>
            ${ta(`${panelKey}-exclude-body-yaml`, v.excludeBodyParamsYaml, '- frequency_penalty\n- presence_penalty', 4)}
          </div>

          <div>
            <label style="font-size:11px;color:${labelColor};display:block;margin-bottom:4px;">
              📨 包含请求标头（YAML 对象）
            </label>
            ${ta(`${panelKey}-extra-headers-yaml`, v.extraHeadersYaml, 'CustomHeader: 自定义值\nAnotherHeader: 自定义值', 4)}
          </div>

          <div style="font-size:10px;color:${hintColor};">
            注：未启用"自定义 OpenAI 兼容 API"时，本节内容不会生效。
          </div>
        </div>
      </details>`;
  }

  function ssReadExtraParamsFromPanel(panelKey, root) {
    const r = root || topDoc;
    const get = (suffix) => {
      const el = r.getElementById ? r.getElementById(`${panelKey}-${suffix}`)
        : r.querySelector?.(`#${panelKey}-${suffix}`);
      return (el && typeof el.value === 'string') ? el.value : '';
    };
    return {
      extraBodyParamsYaml: get('extra-body-yaml'),
      excludeBodyParamsYaml: get('exclude-body-yaml'),
      extraHeadersYaml: get('extra-headers-yaml'),
    };
  }

  // 🦊 流式泄漏防护（引用计数 + 属性拦截）
  //    内部请求传 should_stream:false 时，部分酒馆版本会把它写回 in_use 预设
  //    settings.should_stream 并持久化，导致用户的主线流式被意外关闭。
  //    这里在内部请求期间临时拦截 should_stream 的写入（setter 吞掉宿主赋值），
  //    从根源阻止泄漏；脚本不主动改变 should_stream 的值，完全由用户自行控制。
  //    支持并发请求：引用计数，所有请求结束后才解除拦截。
  // ✅ 修复 BUG（用户反馈"打开了自动关闭"）：旧版 setter 吞掉 ALL 写入，包括
  //    用户在内部请求期间通过 UI 切换流式的写入。导致用户打开流式后被静默吞掉，
  //    请求结束时 guard 把 should_stream 恢复为旧值（false），用户看到的"一开就关"。
  //    现在改为：guard 只吞掉与内部请求同值（false）的写入（host 持久化路径），
  //    用户切换写入（任意值）一律放行并更新内部 v，guard 退出时按"用户最新意图"恢复。
  let __ssStreamGuardCount = 0;
  // ✅ 流式状态唯一权威：平滑流式开关（CONFIG.ENABLED_KEY = 'smoothStream_enabled'）
  //    打开平滑流式 → 强制 should_stream=true
  //    关闭平滑流式 → 强制 should_stream=false
  //    不管其他谁调整了流式，都被这个开关强制覆盖
  const SS_STREAM_PREF_KEY = 'Xuanhu_UserStreamPreference'; // 保留旧键名兼容，不再使用
  function ssLoadStreamPreference() {
    try {
      // 🦊 平滑流式开关是流式状态的唯一权威
      // 与 state.enabled 默认值一致：localStorage 未设置时默认开
      return localStorage.getItem(CONFIG.ENABLED_KEY) !== 'false';
    } catch { return true; }
  }
  // ssSaveStreamPreference 不再需要：偏好由平滑流式按钮直接控制
  function ssSaveStreamPreference(_v) { /* no-op: 偏好由平滑流式按钮控制 */ }

  function ssStreamGuardEnter(blockedValue) {
    try {
      const settings = getPreset?.('in_use')?.settings;
      if (!settings || typeof settings.should_stream !== 'boolean') return null;
      if (__ssStreamGuardCount === 0) {
        let v = settings.should_stream;
        Object.defineProperty(settings, 'should_stream', {
          configurable: true,
          enumerable: true,
          get() { return v; },
          set(_v) {
            // ✅ 只吞掉与内部请求 should_stream 相同的值（host 持久化路径）。
            //    用户切换写入（任意值，包括与 blockedValue 相同的巧合）放行。
            //    区分依据：host 写入通常批量且与 blockedValue 一致；用户写入是单次 UI 操作。
            //    实践中，host 在 generateRaw 内部同步写入 false；用户在 UI 点击写入 true。
            //    用 blockedValue===false && _v===false 双重条件，最大概率命中 host 路径。
            if (blockedValue === false && _v === false) {
              // host 想把 should_stream:false 持久化，吞掉
              return;
            }
            // 用户写入放行，但不保存偏好（偏好由平滑流式按钮控制）
            // ssStreamGuardExit 退出时会按平滑流式开关恢复，强制覆盖请求期间的临时切换
            v = _v;
          },
        });
      }
      __ssStreamGuardCount++;
      return { settings, val: settings.should_stream };
    } catch { return null; }
  }

  function ssStreamGuardExit(token) {
    if (!token) return;
    __ssStreamGuardCount = Math.max(0, __ssStreamGuardCount - 1);
    if (__ssStreamGuardCount > 0) return;
    try {
      // ✅ 平滑流式开关是唯一权威：恢复时强制使用平滑流式开关的状态，
      //    覆盖请求期间的任何临时切换。
      const restoreVal = ssLoadStreamPreference();
      const curSettings = getPreset?.('in_use')?.settings;
      if (curSettings && curSettings !== token.settings) {
        try { curSettings.should_stream = restoreVal; } catch {}
      }
      Object.defineProperty(token.settings, 'should_stream', {
        configurable: true,
        enumerable: true,
        writable: true,
        value: restoreVal,
      });
      if (curSettings && curSettings !== token.settings) {
        Object.defineProperty(curSettings, 'should_stream', {
          configurable: true,
          enumerable: true,
          writable: true,
          value: restoreVal,
        });
      }
    } catch {
      try { token.settings.should_stream = token.val; } catch {}
      try { getPreset?.('in_use')?.settings && (getPreset('in_use').settings.should_stream = token.val); } catch {}
    }
  }

  async function ssGenerateRaw(taskName, params, label = '') {
    const gr = getFn('generateRaw');
    if (typeof gr !== 'function') throw new Error('无 generateRaw');
    if (taskName === 'beat_mode') {
      const beatApi = ssBuildBeatCustomApi();
      if (beatApi) params = { ...params, custom_api: beatApi };
    }
    const isFoxJudgeRequest = taskName === 'fox_judge_chain';
    const requestStartedAt = Date.now();
    const moduleDiag = ssModuleDiagBegin(ssModuleFromTaskName(taskName, label), label || taskName, {
      taskName,
      existingTask: ssActiveTasks.has(taskName),
      request: {
        shouldSilence: params?.should_silence,
        shouldStream: params?.should_stream,
        maxChatHistory: params?.max_chat_history,
        orderedPromptCount: Array.isArray(params?.ordered_prompts) ? params.ordered_prompts.length : 0,
        orderedPromptRoles: Array.isArray(params?.ordered_prompts)
          ? params.ordered_prompts.map(p => typeof p === 'string' ? p : p?.role || typeof p)
          : [],
        orderedPromptLengths: Array.isArray(params?.ordered_prompts)
          ? params.ordered_prompts.map(p => typeof p === 'string' ? p.length : String(p?.content || '').length)
          : [],
        userInputLength: String(params?.user_input || '').length,
        apiMode: params?.custom_api ? 'custom' : 'main',
        customApi: params?.custom_api ? {
          source: params.custom_api.source || '',
          model: params.custom_api.model || '',
          hasUrl: !!(params.custom_api.apiurl || params.custom_api.proxy_preset),
          hasKey: !!params.custom_api.key,
        } : null,
        hasExtraInject: !!params?.__ssExtraInject,
      },
    });
    if (isFoxJudgeRequest) {
      foxJudgeDiag('generateRaw:入口', {
        label,
        hasGenerateRaw: true,
        existingTask: ssActiveTasks.has(taskName),
        params: {
          shouldSilence: params?.should_silence,
          shouldStream: params?.should_stream,
          maxChatHistory: params?.max_chat_history,
          orderedPromptCount: Array.isArray(params?.ordered_prompts) ? params.ordered_prompts.length : null,
          orderedPromptRoles: Array.isArray(params?.ordered_prompts)
            ? params.ordered_prompts.map(p => typeof p === 'string' ? p : p?.role || typeof p)
            : null,
          orderedPromptLengths: Array.isArray(params?.ordered_prompts)
            ? params.ordered_prompts.map(p => typeof p === 'string' ? p.length : String(p?.content || '').length)
            : null,
          userInputLength: String(params?.user_input || '').length,
          hasCustomApi: !!params?.custom_api,
          customApi: params?.custom_api ? {
            source: params.custom_api.source,
            model: params.custom_api.model || '',
            hasUrl: !!(params.custom_api.apiurl || params.custom_api.proxy_preset),
            hasKey: !!params.custom_api.key,
            maxTokens: params.custom_api.max_tokens ?? null,
            temperature: params.custom_api.temperature ?? null,
          } : null,
          hasExtraInject: !!params?.__ssExtraInject,
          skipJailbreak: !!params?.__ssSkipJailbreak,
        },
      });
    }

    // 🦊 取出可能附带的"附加参数"注入（YAML 解析后的结构）。
    // 三个模块（狐裁/狐忆/狐搜）通过 params.__ssExtraInject 透传。
    let __extraInject = null;
    if (params && params.__ssExtraInject) {
      __extraInject = params.__ssExtraInject;
      params = { ...params };
      delete params.__ssExtraInject;
    }

    // 🦊 是否跳过破限统一注入。狐裁的一/二阶段思考由预设里已有的破限条目负责注入，
    //    脚本不应再重复推送一次，否则会出现两份破限头部。其它功能仍照常注入。
    let __skipJailbreak = false;
    if (params && params.__ssSkipJailbreak) {
      __skipJailbreak = true;
      params = { ...params };
      delete params.__ssSkipJailbreak;
    }

    // 🧨 破限模式统一注入：把当前启用的破限提示词放到 ordered_prompts 的最最最顶部。
    // 这样所有走 ssGenerateRaw 且使用 ordered_prompts 的额外功能（总结/狐构/狐忆/
    // 狐搜/狐神/平行世界/小说/文风分析）都会自动带上破限头部，无需逐个改。
    // ⚠️ 狐裁两阶段思考通过 __ssSkipJailbreak 显式跳过（预设里已注入破限，避免重复）。
    if (!__skipJailbreak && params && Array.isArray(params.ordered_prompts)) {
      params = { ...params, ordered_prompts: ssPrependJailbreakToOrderedPrompts(params.ordered_prompts) };
    }

    let task = ssActiveTasks.get(taskName);
    let createdHere = false;

    if (!task) {
      ssStartTask(taskName, label);
      task = ssActiveTasks.get(taskName);
      createdHere = true;
    }

    // 🦊 并发复用计数：同名任务并发调用 ssGenerateRaw 时，任务条目必须等最后一个请求结束
    //    才能清理。否则先结束的 createdHere 请求会把还在跑的同名请求的任务条目提前删掉，
    //    导致该请求无法被 ssCancelTask 中断、自动队列的 idle 检测也等不到它（抢请求/漏中断）。
    if (createdHere) task.__ssGRCreated = true;
    task.__ssGRCount = (task.__ssGRCount || 0) + 1;

    // 每次 generateRaw 都必须使用独立 generation_id。部分 TavernHelper / SillyTavern
    // 版本会在一次生成结束后永久结算该 ID；两阶段狐裁若复用任务 ID，第二阶段会被宿主
    // 当成已结束请求立即 abort。任务本身仍通过 generationIds 聚合这些请求，点击中断时全部停止。
    const requestGenerationId = ssMakeGenerationId(`${taskName}_request`);
    if (!task.generationIds) task.generationIds = new Set();
    task.generationIds.add(requestGenerationId);
    params = { ...params, generation_id: requestGenerationId };
    ssModuleDiagByGenerationId.set(requestGenerationId, moduleDiag);
    log(`[生成请求] ${label || taskName} generation_id=${requestGenerationId}`);
    ssModuleDiag(moduleDiag, '请求已分配', { requestGenerationId });
    if (isFoxJudgeRequest) {
      foxJudgeDiag('generateRaw:请求ID已分配', {
        label,
        requestGenerationId,
        taskGenerationId: task?.generationId,
        activeRequestIds: [...(task?.generationIds || [])],
      });
    }

    // ✅ 给当前任务挂一个 AbortController，让 ssCancelTask 能立即把
    //    本次 generateRaw 的 await 解开（即使宿主 stopGenerationById 不可用 / 被吞），
    //    避免点击中断后界面长时间卡在"生成中"的问题。
    const abortCtrl = new AbortController();
    try { ssAttachAbortController(taskName, abortCtrl); } catch { }
    // 不把 AbortSignal 传进 generateRaw。signal 不是 TavernHelper generateRaw 的标准参数，
    // 部分版本会在真正发起 fetch 前复制/序列化参数并直接失败，表现为选择“酒馆当前 API”后
    // 后台完全收不到请求。中断仍由下方 cancelWatch + stopGenerationById 负责。

    const cancelWatch = new Promise((_, reject) => {
      if (abortCtrl.signal.aborted) {
        const error = new Error('aborted');
        error.__ssUserCancelled = true;
        reject(error);
        return;
      }
      abortCtrl.signal.addEventListener('abort', () => {
        const error = new Error('aborted');
        error.__ssUserCancelled = true;
        reject(error);
      }, { once: true });
    });

    // 🦊 附加参数：在 gr() 调用周期内入队，被 fetch hook 按令牌精确匹配后一次性消费来 merge body / headers。
    const __extraHandle = __extraInject ? ssPushExtraInject(__extraInject, params.generation_id) : null;
    // ✅ 把本次注入的关联令牌写进请求参数，最终落到请求体里，供 fetch hook 精确配对，
    //    避免多模块并发时纯 FIFO 串台（hook 会在发往上游前剥离该字段）。
    //    generation_id 作为第二条匹配通道（更可靠，宿主一定会带），双保险。
    if (__extraHandle) {
      params = { ...params, ssInjectToken: __extraHandle.id };
    }

    // 🦊 流式泄漏防护：内部请求期间拦截 should_stream 写入，阻止宿主把
    //    should_stream:false 泄漏到 in_use 预设。脚本不主动改变 should_stream 的值。
    // ✅ 传入本次请求的 should_stream，guard 据此只吞掉 host 持久化路径的写入。
    const __streamGuard = ssStreamGuardEnter(params?.should_stream === false ? false : true);

    try {
      // 用 race 让 abort 立刻生效；正常返回时 abort 监听不再触发。
      if (isFoxJudgeRequest) foxJudgeDiag('generateRaw:调用宿主前', { requestGenerationId });
      xhMarkInternalGeneration(true);
      const r = await ssWithMainInjectSuppressed(() => Promise.race([gr(params), cancelWatch]), params.generation_id);
      ssModuleDiag(moduleDiag, '响应成功', {
        requestGenerationId,
        durationMs: Date.now() - requestStartedAt,
        response: foxJudgeResponseSummary(r),
      }, 'info');
      if (isFoxJudgeRequest) {
        foxJudgeDiag('generateRaw:宿主正常返回', {
          requestGenerationId,
          durationMs: Date.now() - requestStartedAt,
          response: foxJudgeResponseSummary(r),
        }, 'info');
      }
      return r;
    } catch (e) {
      const msg = e?.message || String(e || '');
      if (abortCtrl.signal.aborted && e && typeof e === 'object') {
        try { e.__ssUserCancelled = true; } catch { }
      }
      ssModuleDiag(moduleDiag, '响应失败', {
        requestGenerationId,
        durationMs: Date.now() - requestStartedAt,
        controllerAborted: abortCtrl.signal.aborted,
        taskCancelled: task?.cancelled === true,
        error: foxJudgeDiagError(e),
      }, 'error');
      if (isFoxJudgeRequest) {
        foxJudgeDiag('generateRaw:捕获异常', {
          requestGenerationId,
          durationMs: Date.now() - requestStartedAt,
          controllerAborted: abortCtrl.signal.aborted,
          taskStillActive: ssActiveTasks.get(taskName) === task,
          taskCancelled: task?.cancelled === true,
          error: foxJudgeDiagError(e),
        }, 'error');
      }
      // 只有本任务自己的 AbortController 被 ssCancelTask 触发，才属于用户中断。
      // 宿主/API 抛出的 AbortError 不能再伪装成“狐裁已中断”，否则现场没有任何真实错误可查。
      if (/abort|aborted|cancel|中断|取消/i.test(msg) && !abortCtrl.signal.aborted) {
        const err = new Error(`${label || taskName}请求被宿主提前终止，请查看控制台“生成请求”日志`);
        err.cause = e;
        log(`[生成请求] 非用户中断 id=${requestGenerationId}`, e);
        throw err;
      }
      throw e;
    } finally {
      xhMarkInternalGeneration(false);
      // 🦊 解除 should_stream 写入拦截，恢复为普通可写属性（值保持用户原始状态不变）。
      ssStreamGuardExit(__streamGuard);
      if (__extraHandle) ssPopExtraInject(__extraHandle);
      // 清理：把本次调用挂的 controller 从任务集合里移除，避免悬挂；
      //       同名任务复用时也不会误清其他并发调用的 controller。
      try { ssDetachAbortController(taskName, abortCtrl); } catch { }
      try { task?.generationIds?.delete(requestGenerationId); } catch { }
      ssModuleDiagByGenerationId.delete(requestGenerationId);
      ssModuleDiag(moduleDiag, '清理完成', {
        requestGenerationId,
        durationMs: Date.now() - requestStartedAt,
        controllerAborted: abortCtrl.signal.aborted,
        createdTaskHere: createdHere,
      });
      if (isFoxJudgeRequest) {
        foxJudgeDiag('generateRaw:清理完成', {
          requestGenerationId,
          durationMs: Date.now() - requestStartedAt,
          controllerAborted: abortCtrl.signal.aborted,
          remainingRequestIds: [...(task?.generationIds || [])],
          createdTaskHere: createdHere,
        });
      }
      // 🦊 并发复用计数：所有 ssGenerateRaw 调用都递减引用计数；只有"由 ssGenerateRaw 创建"
      //    的任务在计数归零时才结束条目，避免提前删除还在运行的同名请求（详见入口处的计数）。
      //    由外部 ssStartTask 直接创建的任务（如狐搜/狐构整段流程）仍由其自身 ssEndTask 收尾。
      try { task.__ssGRCount = Math.max(0, (task.__ssGRCount || 1) - 1); } catch { }
      if (task.__ssGRCreated && (task.__ssGRCount || 0) === 0) ssEndTask(taskName);
    }
  }

  function ssSetRunningButton(btn, text = '⏳ 运行中，再点中断') {
    if (!btn) return;
    if (!btn.dataset.oldText) btn.dataset.oldText = btn.textContent || '';
    btn.textContent = text;
    btn.disabled = false;
  }

  function ssRestoreButton(btn) {
    if (!btn) return;
    if (btn.dataset.oldText) btn.textContent = btn.dataset.oldText;
    delete btn.dataset.oldText;
    btn.disabled = false;
  }

  // ✅ 每个任务存一条记录：{ el(原始 DOM，用于 dataset 标记), $el(jQuery 对象，用于 toastr.clear) }
  //    之前只存原始 DOM 节点，调用 toastr.clear(rawDom) 时 toastr 期望的是 jQuery 对象，
  //    会静默失败 —— 这正是"狐裁等任务弹窗无法被中断 / 无法被关闭"的根因。
  const ssTaskToasts = new Map();

  function ssClearTaskToast(taskName) {
    const rec = ssTaskToasts.get(taskName);
    ssTaskToasts.delete(taskName);
    if (!rec) return;
    const t = topWindow?.toastr || window.toastr;
    try {
      // 优先用 jQuery 对象走 toastr.clear（带淡出动画且能正确从内部队列移除）
      if (rec.$el && t?.clear) {
        t.clear(rec.$el);
      } else if (rec.el && t?.clear && topWindow?.jQuery) {
        t.clear(topWindow.jQuery(rec.el));
      } else if (rec.el?.remove) {
        rec.el.remove();
      }
    } catch {
      try { rec.el?.remove?.(); } catch { }
    }
    // 兜底：无论 clear 是否成功，强制把残留 DOM 移除，确保弹窗一定消失
    try { if (rec.el && rec.el.parentNode) rec.el.remove(); } catch { }
  }

  function ssTaskToast(taskName, text) {
    ssClearTaskToast(taskName);
    let el = null;
    let $el = null;

    try {
      const t = topWindow?.toastr || window.toastr;
      if (t?.info) {
        // ✅ 关键：toastr.info() 直接返回这条 toast 的 jQuery 元素，
        //    不能用 querySelector('.toast-info:last-child') 抓取——
        //    因为 newestOnTop:true 时新 toast 是 :first-child，
        //    而且多个并发任务弹窗会让 :last-child 抓到错误的那一条，
        //    导致 cancel 按钮的点击处理被绑到别的任务的弹窗上、本条弹窗的按钮无任何反应。
        const $t = t.info(
          `${text}<br><button class="ss-toast-cancel" data-task="${escapeHtml(taskName)}" style="margin-top:8px;padding:4px 10px;border:1px solid rgba(232,120,74,0.35);border-radius:6px;background:rgba(139,0,0,0.22);color:#ffd0c0;cursor:pointer;pointer-events:auto;position:relative;z-index:1;">⛔ 中断</button>`,
          '🦊玄狐',
          {
            timeOut: 0,
            extendedTimeOut: 0,
            closeButton: true,
            tapToDismiss: false,
            newestOnTop: true,
            // ✅ 同任务名重复弹窗会被 ssClearTaskToast 主动清掉，不依赖 toastr 的去重；
            //    保留 preventDuplicates:true 反而会让"同名 toast 被静默丢弃"，导致弹窗看似没出现。
            preventDuplicates: false,
            escapeHtml: false,
            toastClass: 'toast xh-toast xh-toast--info',
          }
        );

        // toastr.info 会返回这条 toast 的 jQuery 对象
        try {
          if ($t && typeof $t === 'object') {
            if ($t.nodeType) {
              el = $t;
            } else {
              // jQuery 对象：同时保留 jQuery 句柄（给 toastr.clear 用）与原始 DOM（给 dataset 用）
              $el = $t;
              if ($t[0]) el = $t[0];
              else if ($t.get && typeof $t.get === 'function') el = $t.get(0) || null;
            }
          }
        } catch { }

        // 兜底：如果拿不到返回值，再用最稳妥的"任意一条 .toast-info"，但优先 :first-child（newestOnTop）
        if (!el) {
          el =
            topDoc.querySelector('#toast-container .toast-info:first-child') ||
            topDoc.querySelector('#toast-container .toast-info') ||
            topDoc.querySelector('.toast-info');
        }
        // 没拿到 jQuery 句柄时，用宿主 jQuery 包一层，保证 toastr.clear 一定能命中这条弹窗
        if (!$el && el) {
          try { if (topWindow?.jQuery) $el = topWindow.jQuery(el); } catch { }
        }

        if (el) {
          // 用 dataset 记录任务名，让全局事件代理可以识别本条弹窗并触发中断
          try { el.dataset.ssTask = taskName; } catch { }
          ssTaskToasts.set(taskName, { el, $el });
          // ✅ 双保险：除了下面的全局事件代理（ssBindToastCancelDelegation），再给本条弹窗的
          //    取消按钮直接绑一次 onclick。某些宿主/主题会在 toast-container 上 stopPropagation
          //    或把 toast 渲染进与 topDoc 不同的realm，导致 capture 代理收不到点击 —— 这正是
          //    "点中断没反应"的根因之一。直接绑定 + 代理里的 __ssCancelHandled 去重，
          //    保证至少一条路径一定能触发，且不会重复中断。
          try {
            const btn = el.querySelector ? el.querySelector('.ss-toast-cancel') : null;
            if (btn && !btn.__ssBound) {
              btn.__ssBound = true;
              btn.addEventListener('click', (ev) => {
                try { ev.preventDefault(); ev.stopPropagation(); } catch { }
                const tn = btn.getAttribute('data-task') || taskName;
                if (!tn) return;
                if (el.__ssCancelHandled) return;
                el.__ssCancelHandled = true;
                try { ssCancelTask(tn); } catch { }
                try { ssClearTaskToast(tn); } catch { }
              });
            }
          } catch { }
        }
      }
    } catch { }

    return el;
  }

  // ✅ 全局兜底：用事件代理在 toast-container 上监听 .ss-toast-cancel 点击。
  //    即使 toast DOM 在某些时机没正确取到（比如 newestOnTop / 并发任务弹窗），
  //    也能保证"中断按钮"始终可点。绑定一次即可。
  (function ssBindToastCancelDelegation() {
    const bind = (doc) => {
      if (!doc || doc.__ssToastCancelBound) return;
      doc.__ssToastCancelBound = true;
      doc.addEventListener('click', (ev) => {
        const target = ev.target;
        if (!target || !target.closest) return;
        const btn = target.closest('.ss-toast-cancel');
        if (!btn) return;
        ev.preventDefault();
        ev.stopPropagation();
        // 优先取按钮上的 data-task；取不到时回退到所在 toast 的 dataset.ssTask
        let taskName = btn.getAttribute('data-task') || '';
        const toastEl = btn.closest('.toast');
        if (!taskName) {
          taskName = toastEl?.dataset?.ssTask || '';
        }
        if (!taskName) return;
        // 与按钮直绑路径去重：任一路径先触发即标记，避免重复中断
        if (toastEl && toastEl.__ssCancelHandled) return;
        if (toastEl) toastEl.__ssCancelHandled = true;
        try { ssCancelTask(taskName); } catch { }
        try { ssClearTaskToast(taskName); } catch { }
      }, true);
    };
    try { bind(topDoc); } catch { }
    try { if (document !== topDoc) bind(document); } catch { }
  })();

  // ==================== 🦊 面板自动保存代理 ====================
  // 用法：ssAttachAutoSave(panelEl, { saveBtnIds: ['foo-save'], excludeSelectors: ['.search-input'] })
  //       或者 ssAttachAutoSave(panelEl, { resolveSaveBtns: (target) => ['some-id'] })
  // 工作方式：监听面板内所有 input/select/textarea/checkbox 的 input 与 change 事件，
  //          发生变化时 debounce 600ms 后静默触发对应保存按钮的 click（保留原 save 逻辑），
  //          同时显示一个轻量"自动保存中…"指示器；按钮自身的点击事件不受影响。
  // 不会监听：button、type=button、type=submit、reset、file，以及 excludeSelectors 命中的元素，
  //          以及面板上 data-no-autosave 标记的元素。
  // 🎯 查找面板的 PC 顶栏容器（新版边栏面板优先 .pc-head / .fm-hd / .hx-head / 含关闭按钮的头部）
  function ssFindPanelPcHead(panelEl) {
    if (!panelEl) return null;
    const head = panelEl.querySelector('.pc-head, .fm-hd, .hx-head');
    if (head) return head;
    // 兜底：包含关闭按钮的头部容器（排除 mb-top 等移动端元素）
    const closeBtn = panelEl.querySelector('[id$="-close-pc"], [id$="-close"], .ss-panel-close');
    if (closeBtn) {
      const host = closeBtn.parentElement;
      if (host && host !== panelEl && !host.classList.contains('mb-top')) return host;
    }
    return null;
  }

  function ssAttachAutoSave(panelEl, opts = {}) {
    if (!panelEl || panelEl.__ssAutoSaveAttached) return;
    panelEl.__ssAutoSaveAttached = true;

    const saveBtnIds = Array.isArray(opts.saveBtnIds) ? opts.saveBtnIds.filter(Boolean) : [];
    const resolveSaveBtns = typeof opts.resolveSaveBtns === 'function' ? opts.resolveSaveBtns : null;
    const excludeSelectors = Array.isArray(opts.excludeSelectors) ? opts.excludeSelectors : [];
    const debounceMs = typeof opts.debounceMs === 'number' ? opts.debounceMs : 600;

    // 在面板顶部插入一个轻量指示条
    let indicator = panelEl.querySelector('.ss-autosave-indicator');
    if (!indicator) {
      indicator = topDoc.createElement('div');
      indicator.className = 'ss-autosave-indicator';
      indicator.style.cssText = 'font-size:11px;color:#7a8f7a;margin:-2px 0 6px 0;padding:3px 8px;border-radius:6px;background:rgba(120,180,120,0.06);border:1px solid rgba(120,180,120,0.15);display:inline-block;align-self:flex-start;transition:opacity 0.25s;opacity:0.85;';
      indicator.textContent = '✨ 已开启自动保存：你的修改会立即生效，无需手动点保存';
      // ✅ 统一插入位置：优先嵌入 PC 顶栏右侧区域（.hd-right），避免挤压左侧标题
      const pcHead = ssFindPanelPcHead(panelEl);
      if (pcHead) {
        const closeBtn = pcHead.querySelector('[id$="-close-pc"], [id$="-close"], .ss-panel-close');
        indicator.style.cssText = 'font-size:10.5px;color:#7a8f7a;padding:3px 10px;border-radius:99px;background:rgba(120,180,120,0.07);border:1px solid rgba(120,180,120,0.18);display:inline-flex;align-items:center;gap:4px;transition:opacity 0.25s;opacity:0.85;white-space:nowrap;margin:0;flex-shrink:0;';
        const hdRight = pcHead.querySelector('.hd-right, .fm-hd-right, .hx-hd-right, .ft-hd-right');
        if (hdRight) hdRight.appendChild(indicator);
        else if (closeBtn) pcHead.insertBefore(indicator, closeBtn);
        else pcHead.appendChild(indicator);
      } else {
        // 旧逻辑：插入到面板第一个子元素之后
        const firstChild = panelEl.firstElementChild;
        if (firstChild && firstChild.nextSibling) {
          panelEl.insertBefore(indicator, firstChild.nextSibling);
        } else {
          panelEl.insertBefore(indicator, panelEl.firstChild);
        }
      }
      // ✅ 移动端顶栏同步放一份（PC隐藏的 .mb-top / .fj-mb-top 在移动端显示时也能看到自动保存状态）
      // ⚠️ 平行世界面板(#pw-panel)不插入移动端指示器，避免圆形按钮挤占顶栏
      try {
        if (panelEl.id === 'pw-panel') throw new Error('skip pw-panel');
        const mbHead = panelEl.querySelector('.mb-top, .fj-mb-top');
        if (mbHead && mbHead !== pcHead) {
          const mbInd = topDoc.createElement('div');
          mbInd.className = 'ss-autosave-indicator ss-autosave-mb';
          mbInd.style.cssText = 'font-size:9px;color:#7a8f7a;padding:2px 8px;border-radius:99px;background:rgba(120,180,120,0.07);border:1px solid rgba(120,180,120,0.18);display:inline-flex;align-items:center;gap:3px;opacity:0.9;white-space:nowrap;margin-left:auto;flex-shrink:0;';
          mbInd.textContent = '✨ 自动保存';
          const mbRight = mbHead.querySelector('.mb-right, .fm-hd-right, .mb-title');
          if (mbRight && mbRight.nextSibling) mbHead.insertBefore(mbInd, mbRight.nextSibling);
          else mbHead.appendChild(mbInd);
        }
      } catch (e) { log('[autosave] 移动端指示器插入失败', e); }
    }

    // 为不同的 changed target 分别累计待触发的 save 按钮 ID
    const pendingIds = new Set();
    let savingTimer = null;

    const flashSaving = () => {
      const apply = (el, phase) => {
        if (!el || !el.isConnected) return;
        if (phase === 'saving') {
          el.textContent = el.classList.contains('ss-autosave-mb') ? '💾 保存中' : '💾 自动保存中…';
          el.style.color = '#f0a070';
          el.style.background = 'rgba(232,120,74,0.06)';
          el.style.borderColor = 'rgba(232,120,74,0.18)';
        } else if (phase === 'done') {
          el.textContent = el.classList.contains('ss-autosave-mb') ? '✅ 已保存' : '✅ 已自动保存';
          el.style.color = '#7ab97a';
          el.style.background = 'rgba(120,180,120,0.08)';
          el.style.borderColor = 'rgba(120,180,120,0.2)';
        } else {
          el.textContent = el.classList.contains('ss-autosave-mb') ? '✨ 自动保存' : '✨ 已开启自动保存：你的修改会立即生效，无需手动点保存';
          el.style.color = '#7a8f7a';
          el.style.background = 'rgba(120,180,120,0.06)';
          el.style.borderColor = 'rgba(120,180,120,0.15)';
        }
      };
      const allIndicators = [...(panelEl.querySelectorAll('.ss-autosave-indicator') || [])];
      const firstInd = allIndicators[0] || indicator;
      allIndicators.forEach(el => apply(el, 'saving'));
      clearTimeout(firstInd.__resetTimer);
      firstInd.__resetTimer = setTimeout(() => {
        allIndicators.forEach(el => apply(el, 'done'));
        // 2.5 秒后回到默认提示
        clearTimeout(firstInd.__idleTimer);
        firstInd.__idleTimer = setTimeout(() => {
          allIndicators.forEach(el => { if (el.isConnected) apply(el, 'idle'); });
        }, 2500);
      }, 250);
    };

    const triggerSave = () => {
      const ids = Array.from(pendingIds);
      pendingIds.clear();
      if (!ids.length) return;
      __ssBeginAutoSaveSilent();
      let clickedAny = false;
      try {
        for (const id of ids) {
          const btn = panelEl.querySelector('#' + id) || topDoc.getElementById(id);
          if (btn && typeof btn.click === 'function' && !btn.disabled) {
            try { btn.click(); clickedAny = true; } catch (e) { try { log('[autosave] 触发', id, '失败', e); } catch {} }
          }
        }
      } finally {
        // settle 1500ms 覆盖 async save handler 在 await 之后才 toast 的场景
        __ssEndAutoSaveSilent(1500);
      }
      // 只有真正触发了保存才闪"已保存"，避免面板已 detach 时 save handler 提前 return 却误报成功
      if (clickedAny) flashSaving();
    };

    // 🦊 关闭前同步刷新：捕获阶段在关闭操作的冒泡 handler 移除面板之前，先同步 flush。
    //   修复"编辑后 600ms 内关闭面板 -> debounce 在面板已 detach 后才触发 ->
    //   save handler 经 topDoc.getElementById 读不到面板而提前 return -> 改动丢失"的竞态。
    //   mousedown/keydown(Esc) 捕获阶段先于冒泡的 close onclick，此时面板仍在文档中，能正确保存。
    const flushPending = () => {
      if (panelEl.isConnected && pendingIds.size) {
        clearTimeout(savingTimer);
        triggerSave();
      }
    };
    const onPreCloseMouseDown = (e) => {
      if (!panelEl.isConnected || !pendingIds.size) return;
      // 若点的是保存按钮本身，交由其 onclick 处理，不预刷（避免双存 + 手动保存的 toast 被静默吞掉）
      const t = e.target;
      let saveIds = null;
      if (resolveSaveBtns) { try { saveIds = resolveSaveBtns(t); } catch {} }
      if (!saveIds || !saveIds.length) saveIds = saveBtnIds;
      if (saveIds && saveIds.length && t && saveIds.some(id => id && (t.id === id || (t.closest && t.closest('#' + id))))) return;
      flushPending();
    };
    const onPreCloseKey = (e) => { if (e.key === 'Escape' && panelEl.isConnected && pendingIds.size) flushPending(); };

    const queueIdsFor = (target) => {
      // 优先用 resolveSaveBtns（更精细）；否则用通用 saveBtnIds
      let ids = null;
      if (resolveSaveBtns) {
        try { ids = resolveSaveBtns(target); } catch (e) { try { log('[autosave] resolveSaveBtns 抛错', e); } catch {} }
      }
      if (!ids || !ids.length) ids = saveBtnIds;
      if (!ids || !ids.length) return false;
      let added = false;
      for (const id of ids) {
        if (id) { pendingIds.add(id); added = true; }
      }
      return added;
    };

    const isWatchable = (el) => {
      if (!el || !el.tagName) return false;
      const tag = el.tagName.toLowerCase();
      if (tag !== 'input' && tag !== 'select' && tag !== 'textarea') return false;
      // 跳过按钮型 input
      const t = (el.type || '').toLowerCase();
      if (t === 'button' || t === 'submit' || t === 'reset' || t === 'file' || t === 'image') return false;
      // 跳过只读
      if (el.readOnly === true || el.disabled === true) return false;
      // 跳过显式标记
      if (el.hasAttribute('data-no-autosave')) return false;
      // 跳过 excludeSelectors 命中
      for (const sel of excludeSelectors) {
        try { if (sel && el.matches(sel)) return false; } catch {}
        try { if (sel && el.closest(sel)) return false; } catch {}
      }
      return true;
    };

    const onEvt = (e) => {
      if (!isWatchable(e.target)) return;
      if (!queueIdsFor(e.target)) return;
      clearTimeout(savingTimer);
      savingTimer = setTimeout(triggerSave, debounceMs);
    };

    panelEl.addEventListener('input', onEvt, true);
    panelEl.addEventListener('change', onEvt, true);
    // 捕获阶段：用户点关闭按钮/遮罩/Esc/切走标签页前，先把待保存改动同步落盘
    topDoc.addEventListener('mousedown', onPreCloseMouseDown, true);
    topDoc.addEventListener('keydown', onPreCloseKey, true);
    try { topWindow.addEventListener('pagehide', flushPending); } catch {}

    // 面板被 remove 时同步清理 timer 与监听器，避免后续触发不存在的按钮
    let cleanupInterval = null;
    const cleanup = () => {
      clearTimeout(savingTimer);
      clearTimeout(indicator?.__resetTimer);
      clearTimeout(indicator?.__idleTimer);
      panelEl.removeEventListener('input', onEvt, true);
      panelEl.removeEventListener('change', onEvt, true);
      topDoc.removeEventListener('mousedown', onPreCloseMouseDown, true);
      topDoc.removeEventListener('keydown', onPreCloseKey, true);
      try { topWindow.removeEventListener('pagehide', flushPending); } catch {}
      if (cleanupInterval) { clearInterval(cleanupInterval); cleanupInterval = null; }
    };
    panelEl.__ssAutoSaveCleanup = cleanup;

    // 不再用 MutationObserver 监听 body 全量子节点变动（成本随会话累积）：
    // 改为低频 poll 检查 panel 是否仍在 DOM 中，触发后即清理并停 poll。
    // 面板关闭通常由用户操作（≤数秒延迟可接受），不影响功能。
    cleanupInterval = setInterval(() => {
      if (!panelEl.isConnected) cleanup();
    }, 3000);
  }

  // ==================== 🦊 面板恢复默认按钮 ====================
  // 用法：ssAttachPanelResetButton(panelEl, { label: '↩ 恢复狐裁默认', confirm: '...', onReset: () => { ... } })
  // 在面板顶部（标题栏附近）插入一个红色"恢复本面板默认"按钮，
  // 点击时弹确认 → 调用 onReset() → 关闭重开当前面板（由 onReset 自行实现或返回 reopen 函数）。
  function ssAttachPanelResetButton(panelEl, opts = {}) {
    if (!panelEl || panelEl.__ssResetBtnAttached) return;
    panelEl.__ssResetBtnAttached = true;

    const label = opts.label || '↩ 恢复本面板默认';
    const confirmText = opts.confirm || '确定恢复本面板的全部设置为默认值吗？此操作不可撤销。';
    const onReset = typeof opts.onReset === 'function' ? opts.onReset : null;

    const btn = topDoc.createElement('button');
    btn.type = 'button';
    btn.className = 'ss-panel-reset-btn';
    btn.textContent = label;
    btn.setAttribute('data-no-autosave', '1');
    btn.style.cssText = 'align-self:flex-start;padding:5px 10px;border:1px solid rgba(139,0,0,0.35);border-radius:6px;background:rgba(139,0,0,0.13);color:#d08080;cursor:pointer;font-size:11px;font-family:inherit;margin:0 0 6px 0;';
    btn.onclick = (e) => {
      e.preventDefault();
      e.stopPropagation();
      // 与文件其它处一致的调用方式：保留 this 绑定，避免 strict-mode 抛 Illegal invocation
      const ok = topWindow?.confirm ? topWindow.confirm(confirmText) : confirm(confirmText);
      if (!ok) return;
      try { onReset && onReset(); } catch (err) { try { log('[reset] 失败', err); } catch {} ; toast(`❌ 恢复默认失败：${err?.message || err}`, 'error'); return; }
      toast('✅ 已恢复本面板默认设置', 'success');
    };

    // ✅ 统一插入位置：优先嵌入 PC 顶栏右侧区域（.hd-right），紧跟自动保存指示器，
    //   避免挤压左侧标题 / 被隐藏的 mb-top 挤走造成"白色按钮悬浮"
    const pcHead = ssFindPanelPcHead(panelEl);
    if (pcHead) {
      btn.style.cssText = 'padding:5px 11px;border:1px solid rgba(139,0,0,0.35);border-radius:6px;background:rgba(139,0,0,0.13);color:#d08080;cursor:pointer;font-size:11px;font-family:inherit;margin:0;flex-shrink:0;';
      const indicator = pcHead.querySelector('.ss-autosave-indicator');
      const closeBtn = pcHead.querySelector('[id$="-close-pc"], [id$="-close"], .ss-panel-close');
      const hdRight = pcHead.querySelector('.hd-right, .fm-hd-right, .hx-hd-right, .ft-hd-right');
      if (hdRight) {
        hdRight.appendChild(btn);
      } else if (indicator && indicator.nextSibling) {
        pcHead.insertBefore(btn, indicator.nextSibling);
      } else if (closeBtn) {
        pcHead.insertBefore(btn, closeBtn);
      } else {
        pcHead.appendChild(btn);
      }
    } else {
      // 插入：尝试放在自动保存指示器之后（如果有），否则插入到第一个子元素后
      const indicator = panelEl.querySelector('.ss-autosave-indicator');
      if (indicator && indicator.nextSibling) {
        panelEl.insertBefore(btn, indicator.nextSibling);
      } else {
        const firstChild = panelEl.firstElementChild;
        if (firstChild && firstChild.nextSibling) {
          panelEl.insertBefore(btn, firstChild.nextSibling);
        } else {
          panelEl.insertBefore(btn, panelEl.firstChild);
        }
      }
    }
  }

  // ==================== 🦊 全局生成类型追踪器：reroll / swipe 保护 ====================
  // 背景：
  //   SillyTavern 的 MESSAGE_RECEIVED 事件并不总是把 type 透传给监听器
  //   （只有 GENERATION_STARTED 一定会传 type='regenerate' / 'swipe' / 'continue' / 'quiet' / 'impersonate' / 'normal'）。
  //   而狐忆自动分析、平行世界自动推进、狐构自动修正都挂在 MESSAGE_RECEIVED 上，
  //   靠 (type && type !== 'normal') 来过滤"非用户主动新回复"的情况。
  //   一旦 MESSAGE_RECEIVED 没有 type 参数，这个过滤就会失效——用户重 roll / swipe
  //   出来的回复也会被当成"普通新回复"，再触发一遍狐忆 / 平行世界更新，
  //   这就是"重 roll、swipe 又更新一遍平行世界和狐忆"出问题的根因。
  //
  // 策略：
  //   在 GENERATION_STARTED 里抓住本次生成的 type，存进全局变量；
  //   MESSAGE_RECEIVED 处理函数在 type 缺失时，回退用这个全局值来判断。
  //   GENERATION_STARTED 总能拿到 type，所以即使 ST 没把 type 透传给 MESSAGE_RECEIVED，
  //   我们也能在事件链里把它接住。
  //
  // 注意：
  //   - dryRun 不算正式生成，不能污染 lastType（否则资料抓取等会被误标记成 normal/quiet）。
  //   - 脚本自己跑的 generateRaw（狐忆/平行世界/狐构/狐搜/大总结/文风分析等）会以 'quiet' 类型
  //     再触发 GENERATION_STARTED，**必须过滤掉**——否则会污染 lastType，下一次真正主线 normal
  //     回复的 MESSAGE_RECEIVED 在 ST 没透传 type 时回退到残留 'quiet'，合法回复也被跳过。
  //     我们靠 ssActiveTasks / state.*IsRunning|Generating|Analyzing / pwState.running|internalGenerating
  //     这些已有的"内部任务进行中"标志，在追踪器入口就把内部 GENERATION_STARTED 拦掉。
  //   - 同时，我们在 foxMemoryShouldAutoAnalyze / pwShouldAutoAdvance 内部已经在 MESSAGE_RECEIVED 触发的
  //     "那一刻"就读取 lastType 并冻结到 snapshotType（见下文），所以即使追踪器漏掉了某种内部任务，
  //     setTimeout 之后 lastType 再被覆盖也不会影响本次判定。这是双重保险。
  let xhLastGenerationType = null;
  let xhLastGenerationTypeHandle = null;
  let xhInternalGenerationDepth = 0;
  let xhCurrentGenerationIsInternal = false;
  let xhRecentInternalGenerationUntil = 0;

  function xhMarkInternalGeneration(active) {
    if (active) {
      xhInternalGenerationDepth += 1;
      xhCurrentGenerationIsInternal = true;
      xhRecentInternalGenerationUntil = Date.now() + 5000;
      return;
    }
    xhInternalGenerationDepth = Math.max(0, xhInternalGenerationDepth - 1);
    xhCurrentGenerationIsInternal = xhInternalGenerationDepth > 0;
    if (!xhCurrentGenerationIsInternal) xhRecentInternalGenerationUntil = Date.now() + 1500;
  }

  function xhIsInternalMessageEvent(type) {
    const normalized = typeof type === 'string' ? type.toLowerCase() : '';
    // MESSAGE_RECEIVED 明确透传类型时，以该次事件自身为准；只有缺失 type 时才使用内部作用域兜底。
    if (normalized) return normalized !== 'normal';
    return xhCurrentGenerationIsInternal || xhInternalGenerationDepth > 0 || Date.now() < xhRecentInternalGenerationUntil;
  }

  function xhGetLastGenerationType() {
    return xhLastGenerationType;
  }

  function xhRegisterGenerationTypeTracker() {
    xhUnregisterGenerationTypeTracker();
    try {
      const eo = getFn('eventOn');
      const te = getFn('tavern_events') || tavern_events;
      if (typeof eo !== 'function' || !te?.GENERATION_STARTED) {
        log('[生成类型追踪] 注册失败：缺少 eventOn 或 GENERATION_STARTED');
        return;
      }
      xhLastGenerationTypeHandle = eo(te.GENERATION_STARTED, (type, _option, dryRun) => {
        if (dryRun) return;
        // 🦊 关键：脚本自身跑的 generateRaw（狐忆 / 平行世界 / 狐搜 / 狐构 / 大总结 /
        //    文风分析 / 狐析 / 狐裁 等）也会触发 GENERATION_STARTED 且 type 一般为 'quiet'。
        //    必须过滤掉，否则会把 xhLastGenerationType 污染成 'quiet'，下一次真正用户
        //    主线 normal 回复的 MESSAGE_RECEIVED 在 ST 没透传 type 时回退到这个残留值，
        //    合法的主线回复也会被错误跳过狐忆 / 平行世界更新。
        // 🦊 关键修复：只用 xhMarkInternalGeneration 设置的标志判断是否内部生成。
        //    之前用 ssActiveTasks.size > 0 等任务状态判断，在"上一次自动分析任务还没
        //    完全清理完，用户就发了下一条消息"时，会把用户的 normal 生成误判为内部
        //    quiet 生成，导致 xhLastGenerationType 永远不被更新为 'normal'，后续所有
        //    MESSAGE_RECEIVED 都被跳过，表现为"楼层多了之后自动分析再也不触发"。
        let isInternal = xhCurrentGenerationIsInternal || xhInternalGenerationDepth > 0;
        if (isInternal) {
          xhCurrentGenerationIsInternal = true;
          xhRecentInternalGenerationUntil = Date.now() + 5000;
          log('[生成类型追踪] 已登记内部 GENERATION_STARTED type=', type);
          return;
        }
        xhCurrentGenerationIsInternal = false;
        xhRecentInternalGenerationUntil = 0;
        xhLastGenerationType = type || 'normal';
        log('[生成类型追踪] 捕获 GENERATION_STARTED type=', xhLastGenerationType);
      });
      log('[生成类型追踪] 已注册 GENERATION_STARTED 监听');
    } catch (e) {
      log('[生成类型追踪] 注册异常', e);
    }
  }

  function xhUnregisterGenerationTypeTracker() {
    ssStopEventHandle(xhLastGenerationTypeHandle);
    xhLastGenerationTypeHandle = null;
  }

  // ==================== 🦊 自动任务全局队列：防止狐搜/狐忆/狐构/平行世界同时 generateRaw 冲突 ====================
  const xhAutoQueue = {
    chain: Promise.resolve(),
    pending: new Set(),
  };

  function xhIsAbortLike(e) {
    const msg = e?.message || String(e || '');
    return /abort|aborted|cancel|取消|中断/i.test(msg);
  }

  async function xhWaitForIdleBeforeAuto(timeoutMs = 180000) {
    const start = Date.now();
    let logged = false;

    while (ssActiveTasks.size > 0 || state.husouIsRunning || state.foxAnalyzing || state.outlineIsCorrecting || state.outlineIsGenerating || pwState?.running || ftState?.running || (typeof SillyTavern !== 'undefined' && SillyTavern?.getContext?.()?.isStreaming)) {
      if (!logged) {
        const blockers = [];
        if (ssActiveTasks.size > 0) blockers.push(`activeTasks=[${[...ssActiveTasks].join(',')}]`);
        if (state.husouIsRunning) blockers.push('狐搜');
        if (state.foxAnalyzing) blockers.push('狐析');
        if (state.outlineIsCorrecting) blockers.push('狐构修正');
        if (state.outlineIsGenerating) blockers.push('狐构生成');
        if (pwState?.running) blockers.push('平行世界');
        if (ftState?.running) blockers.push('狐刻');
        if (typeof SillyTavern !== 'undefined' && SillyTavern?.getContext?.()?.isStreaming) blockers.push('主模型流式输出中');
        log(`[自动任务队列] 等待其他任务结束：${blockers.join('，') || '未知'}`);
        logged = true;
      }
      if (Date.now() - start > timeoutMs) {
        // ✅ 修复：超时后降级继续执行而非抛错放弃。
        //    原逻辑超时抛错会导致排队中的狐忆等任务直接失败（用户反馈"只跑了平行世界没跑狐忆"）。
        //    中断/超时后降级继续，保证任务不丢失；并发风险由各模块 quiet 隔离缓解。
        log('[自动任务队列] 等待其他任务结束超时，降级继续执行（排队任务不丢弃）');
        break;
      }

      await new Promise(r => setTimeout(r, 350));
    }
  }

  // 🦊 手动操作前等待全局空闲：防止手动触发的新请求与正在运行的自动任务/其他模块/
  //    主模型流式输出并发（抢请求）。与 xhWaitForIdleBeforeAuto 的区别：
  //    - 排除当前任务自身（保留"再点即中断"的同模块切换语义）；
  //    - 超时后降级继续执行，绝不阻塞/丢弃手动操作。
  async function ssWaitForManualIdle(taskNameOrNames, timeoutMs = 90000) {
    const excluded = new Set(Array.isArray(taskNameOrNames) ? taskNameOrNames : [taskNameOrNames]);
    const start = Date.now();
    let logged = false;
    while (true) {
      const blockers = [];
      if (typeof SillyTavern !== 'undefined' && SillyTavern?.getContext?.()?.isStreaming) blockers.push('主模型流式输出中');
      for (const name of ssActiveTasks.keys()) {
        if (!excluded.has(name)) blockers.push(name);
      }
      if (state.husouIsRunning && !excluded.has('husou_search')) blockers.push('狐搜');
      if (state.foxAnalyzing && !excluded.has('fox_memory_analyze')) blockers.push('狐析');
      if ((state.outlineIsCorrecting || state.outlineIsGenerating) && !excluded.has('outline_generate') && !excluded.has('outline_correct')) blockers.push('狐构');
      if (pwState?.running && !excluded.has('parallel_world') && !excluded.has('parallel_world_single') && !excluded.has('parallel_world_summarize')) blockers.push('平行世界');
      if (ftState?.running && !excluded.has('fox_time')) blockers.push('狐刻');
      if (!blockers.length) return true;
      if (!logged) {
        log(`[手动任务队列] 等待其他任务空闲：${blockers.join('，')}（排除=${[...excluded].join(',')}）`);
        try { toast(`⏳ ${blockers.slice(0, 3).join('、')}进行中，本操作将排队等待…`, 'info'); } catch { }
        logged = true;
      }
      if (Date.now() - start > timeoutMs) {
        log(`[手动任务队列] 等待超时（${[...excluded].join(',')}），降级直接执行`);
        return false;
      }
      await new Promise(r => setTimeout(r, 350));
    }
  }

  function xhEnqueueAutoTask(taskKey, label, runner, opts = {}) {
    const key = String(taskKey || label || 'auto_task');
    const dedupe = opts.dedupe !== false;

    if (dedupe && xhAutoQueue.pending.has(key)) {
      log(`[自动任务队列] 已存在待执行任务，跳过重复入队：${label}`);
      xhAutoQueue.chain.queued = false;
      return xhAutoQueue.chain;
    }

    xhAutoQueue.pending.add(key);

    xhAutoQueue.chain = xhAutoQueue.chain
      .catch(() => { })
      .then(async () => {
        await xhWaitForIdleBeforeAuto();

        log(`[自动任务队列] 开始：${label}`);

        try {
          await runner();
          log(`[自动任务队列] 完成：${label}`);
        } catch (e) {
          if (xhIsAbortLike(e)) {
            log(`[自动任务队列] 已中断：${label}`, e);
          } else {
            log(`[自动任务队列] 失败：${label}`, e);
            toast(`❌ ${label}失败：${e?.message || e}`, 'error');
          }
        } finally {
          xhAutoQueue.pending.delete(key);
          await new Promise(r => setTimeout(r, 250));
        }
      });

    xhAutoQueue.chain.queued = true;
    return xhAutoQueue.chain;
  }

  function escapeHtml(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\"/g, '&quot;'); }

