  // ==================== 🦊 统一当前请求体注入系统 ====================
  // 统一顺序：
  // 1. 狐搜搜索内容
  // 2. 狐忆长期记忆
  // 3. 狐构剧情大纲
  // 4. 平行世界后台摘要
  //
  // 插入位置：
  // 优先插入到 <fox_extra></fox_extra> 内部最下方、结束标签上方。
  // 如果没有 <fox_extra>，则使用尾部锚点或回退位置。

  const SS_CURRENT_INJECT_START = '<!-- XUANHU_CURRENT_PROMPT_INJECT_START -->';
  const SS_CURRENT_INJECT_END = '<!-- XUANHU_CURRENT_PROMPT_INJECT_END -->';
  // 🦊 狐裁思维链注入标记支持自定义（改为函数形式，实时读取用户配置）
  xhRegisterPromptDefault('fox_judge', {
    head: 'START THINKING：',
    tail: 'hashlib follow the ⋙ request：\n THINKING END，NO EXPLANATION, NO OPENING REMARKS, NO ADDITIONAL THINKING. IMMEDIATELY REFER TO THE THINKING RESULTS AND BEGIN OUTPUTTING THE MAIN TEXT：'
  });
  function ssGetFoxJudgeInjectStart() { return xhGetPrompt('fox_judge', 'head'); }
  function ssGetFoxJudgeInjectEnd() { return xhGetPrompt('fox_judge', 'tail'); }

  // ✅ 尾部锚点：用户的尾部提示词（如 "hashlib follow the ⋙ request： OUTPUT"）
  // 注入逻辑会把狐忆/狐构/狐搜/狐裁全部插入到该锚点之前，保证尾部提示词永远在最后。
  const SS_TAIL_ANCHOR_KEY = 'SPreset_TailAnchor';
  const SS_TAIL_ANCHOR_DEFAULT = '';

  function ssGetTailAnchor() {
    try {
      const v = localStorage.getItem(SS_TAIL_ANCHOR_KEY);
      if (v && v.trim()) return v;
    } catch { }
    return SS_TAIL_ANCHOR_DEFAULT;
  }

  function ssSetTailAnchor(text) {
    try {
      const v = (text == null ? '' : String(text)).trim();
      if (!v) localStorage.removeItem(SS_TAIL_ANCHOR_KEY);
      else localStorage.setItem(SS_TAIL_ANCHOR_KEY, v);
    } catch { }
  }

  // 把锚点字符串转成宽容匹配正则：
  // - 大小写不敏感
  // - 全角冒号 ：== 半角冒号 :
  // - ⋙ 等特殊三角箭头 == >>>
  // - 多个空白合并成 \s+
  function ssBuildTailAnchorRegex(anchor) {
    const raw = String(anchor || '').trim();
    if (!raw) return null;
    let pattern = raw
      .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')           // 转义正则元字符
      .replace(/[：:]/g, '[：:]')                        // 半/全角冒号互通
      .replace(/⋙|>{3,}/g, '(?:⋙|>{3,})')               // ⋙ 与 >>> 互通
      .replace(/\s+/g, '\\s+');                          // 任意空白
    try {
      return new RegExp(pattern, 'i');
    } catch {
      return null;
    }
  }

  function ssExtractCurrentPromptInjectBlock(text) {
    const raw = String(text || '');
    const re = new RegExp(
      `${SS_CURRENT_INJECT_START.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}[\\s\\S]*?${SS_CURRENT_INJECT_END.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`,
      'm'
    );
    const m = raw.match(re);
    return m ? m[0].trim() : '';
  }

  function ssFindExistingCurrentPromptInjectBlockInArray(arr) {
    if (!Array.isArray(arr)) return '';
    for (const msg of arr) {
      if (!msg || typeof msg.content !== 'string') continue;
      const block = ssExtractCurrentPromptInjectBlock(msg.content);
      if (block) return block;
    }
    return '';
  }

  function ssStripCurrentPromptInjectBlock(text) {
    return String(text || '').replace(
      new RegExp(
        `\\n*${SS_CURRENT_INJECT_START.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}[\\s\\S]*?${SS_CURRENT_INJECT_END.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\n*`,
        'g'
      ),
      ''
    );
  }

  function ssGetHusouPendingInjectText() {
    try {
      const s = state.husouSettings || (state.husouSettings = loadHusouSettings());

      if (!s.injectCurrentPrompt) {
        husouDiag('注入:跳过', { reason: 'injectCurrentPrompt_disabled' });
        return '';
      }
      if (s.backgroundSilent && (state.husouIsRunning || xhAutoQueue.pending.has('husou_auto_search'))) {
        log('[统一注入] 狐搜后台静默更新尚未完成，本次跳过注入');
        husouDiag('注入:跳过', { reason: 'background_search_running', husouIsRunning: state.husouIsRunning, queuePending: xhAutoQueue.pending.has('husou_auto_search') }, 'warn');
        return '';
      }

      // 1. 优先注入本轮刚搜索出来的 pending 内容
      if (state.husouPendingInject?.size) {
        state.husouPendingConsumed = true;
        const text = husouBuildInjectBlock(state.husouPendingInject).trim();
        husouDiag('注入:使用pending', { entryCount: state.husouPendingInject.size, textLength: text.length }, text ? 'info' : 'error');
        return text;
      }

      // 2. 如果没有 pending，则按当前角色卡 localStorage 注入
      // 这样狐搜以 localStorage 为准，切角色卡不会串。
      if (typeof husouLoadLocalText === 'function') {
        const localText = husouLoadLocalText();

        if (localText?.trim()) {
          const text = ssBuildSearchResultsInject(localText.trim()).trim();
          husouDiag('注入:使用localStorage', { localLength: localText.length, injectLength: text.length }, text ? 'info' : 'error');
          return text;
        }
      }

      husouDiag('注入:无内容', { pendingCount: state.husouPendingInject?.size || 0, localStorageEmpty: true });
      return '';
    } catch (e) {
      log('[统一注入] 获取狐搜注入失败', e);
      husouDiag('注入:失败', { error: husouErrorInfo(e) }, 'error');
      return '';
    }
  }

  function ssGetFoxMemoryCurrentInjectText() {
    try {
      foxMemoryConfig = loadFoxMemoryConfig();
      if (foxMemoryConfig.backgroundSilent && (state.foxAnalyzing || [...xhAutoQueue.pending].some(key => key.startsWith('fox_memory_auto_analyze_')))) {
        log('[统一注入] 狐忆后台静默更新尚未完成，本次跳过注入');
        return '';
      }

      if (!foxMemoryConfig.injectCurrentPrompt) {
        log('[统一注入] 狐忆当前提示词注入未开启');
        return '';
      }

      const memories = foxMemoryGetCurrent();
      const memData = loadFoxMemory();
      const atomCount = foxMemoryGetCurrentAtoms().length;
      const stateCount = (memData.currentStates || []).length;
      const profileCount = foxMemoryConfig.cognitionArchEnabled ? Object.keys(memData.characterProfiles || {}).length : 0;
      // 🆕 人物表格：有自定义字段的档案数 + 独立自定义表数（独立于认知档案开关）
      const tableCount = Object.values(memData.characterProfiles || {}).filter(p => (p.custom?.fields || []).length).length
        + (Array.isArray(memData.customTables) ? memData.customTables.length : 0);

      if (!memories.length && !atomCount && !stateCount && !profileCount && !tableCount) {
        log('[统一注入] 狐忆记忆库为空，跳过注入');
        return '';
      }

      // 实时读取输入框，兼容其他脚本直接赋值但没有触发 input 事件的情况。
      // 查询始终由“最近聊天正文（含 user/assistant）+ 最新用户输入”共同构成。
      const latestUserInput = String(topDoc.getElementById('send_textarea')?.value || state.foxMemoryVectorLastInput || '').trim();
      const liveQueryText = foxMemoryBuildVectorQuery(latestUserInput);
      const buildOptions = {
        maxPlotChunks: 999,
        keywordFilterByContext: true,
        queryText: liveQueryText,
        intentText: latestUserInput,
      };
      const memoryBody = foxMemoryBuildMemoryBodyForInject(memories, buildOptions);
      foxMemoryScheduleRecallReactivation({
        atoms: buildOptions.__selectedPlotAtomIds || [],
        states: buildOptions.__selectedCurrentStateIds || [],
        memories: buildOptions.__selectedNonPlotMemoryIds || [],
      }, liveQueryText);

      // 🆕 V3 认知档案召回：cognitionArchEnabled 时，追加角色认知档案（L0主角常驻+L1涉事+L2关系扩散+L3详情按需）
      let profileBody = '';
      if (foxMemoryConfig.cognitionArchEnabled && profileCount) {
        try {
          profileBody = foxMemoryBuildProfileInjectBody(buildOptions.queryText || buildOptions.intentText || '');
        } catch (e) { foxMemoryV2Log('认知档案召回失败', e?.message || e); }
      }
      // 🆕 人物表格召回：剧情中出现角色名/表名即注入其表格（与人物召回同规则，且不受认知档案开关限制）
      let tableBody = '';
      if (tableCount) {
        try {
          tableBody = foxMemoryBuildTableInjectBody(buildOptions.queryText || buildOptions.intentText || '', memData);
        } catch (e) { foxMemoryV2Log('表格召回失败', e?.message || e); }
      }
      const fullBody = [memoryBody, profileBody, tableBody].filter(x => x && String(x).trim()).join('\n\n');

      if (!fullBody.trim()) {
        log('[统一注入] 狐忆记忆筛选后为空，跳过注入');
        return '';
      }

      const injectText = ssBuildFoxMemoryInject(fullBody).trim();
      log(`[统一注入] 狐忆注入已构建，记忆数=${memories.length}，长度=${injectText.length}`);
      foxMemoryV2Log('注入完成', `target=current_prompt atoms=${buildOptions.__selectedPlotAtomCount || 0} nonPlot=${buildOptions.__matchedNonPlotCount || 0} chars=${injectText.length}`);

      // 命中关键词的非剧情记忆，弹 toast 告知用户本次注入了哪些。
      // 注意：单次生成会触发多个注入事件（PROMPT_READY/AFTER_DATA/COMBINE），
      // 这里用签名+时间窗去重，避免一次生成弹多次重复 toast。
      try {
        const hitCount = buildOptions.__matchedNonPlotCount || 0;
        const hitKeywords = buildOptions.__matchedNonPlotKeywords || [];
        if (hitCount > 0) {
          const kwText = hitKeywords.length
            ? `（${hitKeywords.slice(0, 8).join('、')}${hitKeywords.length > 8 ? '…' : ''}）`
            : '';
          const sig = `${hitCount}|${hitKeywords.join(',')}`;
          const now = Date.now();
          if (state.__foxMemInjectToastSig !== sig || now - (state.__foxMemInjectToastTs || 0) > 4000) {
            toast(`🦊 狐忆：命中 ${hitCount} 条记忆${kwText}`, 'success');
            state.__foxMemInjectToastSig = sig;
            state.__foxMemInjectToastTs = now;
          }
        }
      } catch { }

      return injectText;
    } catch (e) {
      log('[统一注入] 获取狐忆注入失败', e);
      return '';
    }
  }

  function ssGetOutlineCurrentInjectText() {
    try {
      if (state.outlineBackgroundSilent && (state.outlineIsCorrecting || xhAutoQueue.pending.has('outline_auto_correct'))) {
        log('[统一注入] 狐构后台静默更新尚未完成，本次跳过注入');
        return '';
      }
      if (localStorage.getItem(CONFIG.OUTLINE_INJECT_CURRENT_KEY) === 'false') {
        log('[统一注入] 狐构当前提示词注入未开启');
        return '';
      }

      const raw = outlineLoadLocalRaw();

      if (!raw?.trim()) return '';

      // 狐构：默认直接插入当前请求体；如果用户打开“注入预设”，也允许预设里存在。
      // 这里仍然插入当前请求体，确保它跟随角色卡本地大纲。
      return ssBuildOutlineInject(raw).trim();
    } catch (e) {
      log('[统一注入] 获取狐构注入失败', e);
      return '';
    }
  }

  function ssDescribeInjectBlock(block) {
    const text = String(block || '');
    const names = [];
    if (text.includes('<SearchResults>')) names.push('狐搜');
    if (text.includes('<fox_memory>')) names.push('狐忆');
    if (text.includes('<fox_outline>')) names.push('狐构');
    if (text.includes('<parallel_world>')) names.push('平行世界');
    if (text.includes('<fox_social_state>')) names.push('狐映');
    return names.length ? `含${names.join('/')}` : '含当前提示词注入';
  }

  function ssBuildCurrentPromptInjectBlock() {
    const parts = [];

    // 1. 狐搜搜索内容
    const searchText = ssGetHusouPendingInjectText();
    if (searchText) parts.push(searchText);

    // 2. 狐忆长期记忆
    const memoryText = ssGetFoxMemoryCurrentInjectText();
    if (memoryText) parts.push(memoryText);

    // 3. 狐构剧情大纲
    const outlineText = ssGetOutlineCurrentInjectText();
    if (outlineText) parts.push(outlineText);

    // 4. 平行世界后台摘要
    const parallelText = typeof ssGetParallelWorldCurrentInjectText === 'function'
      ? ssGetParallelWorldCurrentInjectText()
      : '';

    if (parallelText) parts.push(parallelText);

    // 🔧 狐刻 / 狐映 不再动态注入提示词，仅通过操控预设条目实现功能。
    //   旧代码在此处调用 ssGetFoxTimeCurrentInjectText / ssGetFoxImageCurrentInjectText
    //   生成 <timeline> / <fox_social_state> 块注入 <fox_extra>，即使模块关闭也无法停止。
    //   现已彻底删除注入函数，模块仅靠 ftSyncPromptEntry / foxImageApplyPrompt 开关预设条目。

    if (!parts.length) return '';

    // ✅ 输出纯净内容，不再自包 <fox_extra> 外壳。
    // 注入函数会直接把这段内容塞到预设里预留的 <fox_extra></fox_extra> 之间。
    return `
${SS_CURRENT_INJECT_START}
${parts.join('\n\n')}
${SS_CURRENT_INJECT_END}`.trim();
  }

  // ==================== 🦊 跨模块联动补充：狐构 / 狐搜 / 平行世界 ====================
  // 说明：
  // - 这里只联动狐搜、狐构、平行世界。
  // - 不读取狐忆，不调用 foxMemoryGetCurrent，不调用 ssGetFoxMemoryCurrentInjectText。
  // - 目的：避免狐忆长期记忆混入大纲/搜索/平行世界后台，保持狐忆只服务主线。

  function ssGetHusouCrossModuleSupplementText() {
    try {
      const parts = [];

      // 1. 本轮刚搜索出来、还没清理的 pending 狐搜结果
      // 注意：这里不调用 ssGetHusouPendingInjectText()，避免把 pending 标记为 consumed。
      if (state.husouPendingInject?.size && typeof husouBuildInjectBlock === 'function') {
        const pendingText = husouBuildInjectBlock(state.husouPendingInject).trim();

        if (pendingText) {
          parts.push(`【本轮临时狐搜结果】\n${pendingText}`);
        }
      }

      // 2. 当前角色卡 localStorage 里的狐搜资料库
      if (typeof husouLoadLocalText === 'function') {
        const localText = husouLoadLocalText();

        if (localText?.trim()) {
          parts.push(`【当前角色卡狐搜资料库】\n${ssBuildSearchResultsInject(localText.trim())}`);
        }
      }

      const body = parts.join('\n\n').trim();

      if (!body) return '';

      // 🦊 注册默认提示词，支持用户自定义
      xhRegisterPromptDefault('husou_cross_supplement', {
        head: '',
        tail: ''
      });

      const husouHead = xhGetPrompt('husou_cross_supplement', 'head');
      const husouTail = xhGetPrompt('husou_cross_supplement', 'tail');

      return `<linked_husou_reference>
${husouHead ? husouHead + '\n\n' : ''}${body}${husouTail ? '\n\n' + husouTail : ''}
</linked_husou_reference>`;
    } catch (e) {
      log('[跨模块联动] 获取狐搜补充失败', e);
      return '';
    }
  }

