  function ssBindTagPairsEditor(prefix, root = topDoc) {
    const module = root.querySelector?.(`.${prefix}-tag-module`);
    if (!module || module.dataset.bound === '1') return;
    module.dataset.bound = '1';

    const list = module.querySelector(`.${prefix}-tag-list`);
    const addBtn = module.querySelector(`.${prefix}-tag-add`);

    const createRow = (start = '', end = '') => {
      const row = topDoc.createElement('div');
      row.className = `${prefix}-tag-row`;
      row.style.cssText = 'display:grid;grid-template-columns:1fr 1fr auto;gap:8px;align-items:center;margin-bottom:7px;';
      row.innerHTML = `
        <input class="${prefix}-tag-start" value="${escapeHtml(start)}" placeholder="开始标签，可留空" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.18);border-radius:6px;color:#e8ddd4;padding:6px 8px;font-size:11px;font-family:monospace;box-sizing:border-box;">
        <input class="${prefix}-tag-end" value="${escapeHtml(end)}" placeholder="结束标签，可留空" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.18);border-radius:6px;color:#e8ddd4;padding:6px 8px;font-size:11px;font-family:monospace;box-sizing:border-box;">
        <button type="button" class="${prefix}-tag-remove" style="padding:5px 9px;border:1px solid rgba(139,0,0,0.35);border-radius:6px;background:rgba(139,0,0,0.16);color:#d08080;cursor:pointer;font-size:12px;">-</button>
      `;
      return row;
    };

    addBtn.onclick = () => {
      list.appendChild(createRow());
    };

    list.onclick = (e) => {
      const btn = e.target?.closest?.(`.${prefix}-tag-remove`);
      if (!btn) return;

      const row = btn.closest(`.${prefix}-tag-row`);
      if (!row) return;

      const rows = list.querySelectorAll(`.${prefix}-tag-row`);
      if (rows.length <= 1) {
        row.querySelector(`.${prefix}-tag-start`).value = '';
        row.querySelector(`.${prefix}-tag-end`).value = '';
        return;
      }

      row.remove();
    };
  }

  function ssReadTagPairsEditor(prefix, root = topDoc) {
    const rows = root.querySelectorAll?.(`.${prefix}-tag-row`) || [];
    const pairs = [];

    rows.forEach(row => {
      const start = row.querySelector(`.${prefix}-tag-start`)?.value?.trim() || '';
      const end = row.querySelector(`.${prefix}-tag-end`)?.value?.trim() || '';

      if (!start && !end) return;
      pairs.push({ start, end });
    });

    return pairs;
  }

  // ==================== 主模型请求体抓取 + 严格标签过滤 ====================

  function ssMessageArrayToContextText(messages = [], filterSettings = null, opts = {}) {
    const arr = Array.isArray(messages) ? messages : [];
    if (!arr.length) return '';

    const s = ssNormalizeTagFilterSettings(filterSettings || {});
    const skipRoleLabels = opts.skipRoleLabels === true;

    if (opts.filterAssistantOnly === true) {
      const parts = arr.map(msg => {
        const role = msg?.role || 'system';
        let content = ssCleanXuanhuInjectedBlocksFromMessage(String(msg?.content ?? msg?.message ?? ''));
        if (!content.trim()) return '';
        if (role === 'assistant') {
          content = ssFilterByTagPairs(content, s, {
            fallbackToFullText: opts.fallbackToFullText === true,
          });
        }
        content = String(content || '').trim();
        if (!content) return '';
        return skipRoleLabels ? content : `【${role}】\n${content}`;
      }).filter(Boolean);
      return parts.join('\n\n').trim();
    }

    const fullRawPrompt = arr
      .map(msg => {
        const role = msg?.role || 'system';
        const content = String(msg?.content ?? msg?.message ?? '');
        if (!content.trim()) return '';
        return skipRoleLabels ? content : `【${role}】\n${content}`;
      })
      .filter(Boolean)
      .join('\n\n');

    if (!fullRawPrompt.trim()) return '';

    let cleanedPrompt = fullRawPrompt
      .replace(new RegExp(`${CONFIG.SUMMARY_FLOOR_START}[\\s\\S]*?${CONFIG.SUMMARY_FLOOR_END}`, 'g'), '')
      .replace(new RegExp(`${FULL_SUMMARY_FLOOR_MARK}[\\s\\S]*`, 'g'), '');

    // 🦊 keepModuleInject=true（狐裁）：保留 狐构/狐忆/狐搜/平行世界 等模块注入，
    //    使狐裁上下文 = 主模型请求体，仅由下方 ssFilterByTagPairs 按用户排除标签过滤。
    //    其他场景（默认）仍剥离这些模块注入，保持"只读聊天记录"语义。
    if (opts.keepModuleInject !== true) {
      cleanedPrompt = cleanedPrompt
        .replace(/<fox_outline>[\s\S]*?<\/fox_outline>/gi, '')
        .replace(/<fox_memory>[\s\S]*?<\/fox_memory>/gi, '')
        .replace(/<SearchResults>[\s\S]*?<\/SearchResults>/gi, '');
      try {
        if (typeof ssStripCurrentPromptInjectBlock === 'function') {
          cleanedPrompt = ssStripCurrentPromptInjectBlock(cleanedPrompt);
        }
      } catch { }
    }

    log('[完整原始请求体进入过滤预览]', cleanedPrompt.slice(0, 300000));

    const filtered = ssFilterByTagPairs(cleanedPrompt, s, {
      fallbackToFullText: opts.fallbackToFullText === true,
    });

    if (filtered?.trim()) {
      log('[过滤后上下文预览]', filtered.slice(0, 300000));
      return filtered.trim();
    }

    if (opts.fallbackToFullText === true) {
      return cleanedPrompt.trim();
    }

    return '';
  }


  let ssLastLoadedWorldInfoEntries = [];
  let ssLastActivatedWorldInfoEntries = [];
  let ssHasNativeWorldInfoActivationSnapshot = false;

  function ssNormalizeWorldInfoEventEntries(entries) {
    return (Array.isArray(entries) ? entries : []).filter(entry => entry && typeof entry === 'object');
  }

  function ssIsWorldInfoConstant(entry) {
    return entry?.constant === true || entry?.constant === 'true' || entry?.type === 'constant';
  }

  function ssLogNativeWorldInfoEntries(entries, source = 'WORLD_INFO_ACTIVATED') {
    const list = ssNormalizeWorldInfoEventEntries(entries);
    if (!list.length) {
      log(`[世界书·原生扫描] ${source}：本轮没有激活条目`);
      return;
    }

    const details = list.map((entry, index) => {
      const world = String(entry.world || entry.book || entry.worldName || '未知世界书');
      const uid = String(entry.uid ?? entry.id ?? '?');
      const name = String(entry.comment || entry.name || (Array.isArray(entry.key) ? entry.key.join(',') : (entry.key || '未命名条目')));
      const type = ssIsWorldInfoConstant(entry) ? '常驻蓝灯' : '激活绿灯';
      return `${index + 1}. ${world} / uid=${uid} / ${name} / ${type}`;
    });

    log(`[世界书·原生扫描] ${source}：酒馆已激活 ${list.length} 条（常驻蓝灯 + 关键词绿灯）`);
    log('[世界书·原生扫描] 激活条目明细：', details.join(' | '));
  }

  // 🦊 best-effort 读取酒馆已经加载的全局/角色/聊天/玩家世界书，以及角色/聊天绑定书。
  //    用于狐裁/未来其他模块的"直读上下文"路径，作为对原"主模型抓 prompt"路径的补齐：
  //    避免直读时丢失 world_info_before / world_info_after 里的设定/世界观/规则。
  //
  //    依赖 SillyTavern TavernHelper 暴露的全局函数（同 getChatMessages / generateRaw 走 getFn）：
  //      - getCharLorebooks({ name?, type? }) → { primary, additional: [] }
  //      - getChatLorebook?() → string
  //      - getLorebookEntries(bookName) → [{ enabled, content, comment, key, ... }]
  //    任一缺失或抛错都按"无世界书"处理，绝不抛异常打断狐裁主流程。
  async function ssReadActivatedWorldInfoEntriesDirect() {
    const out = [];
    const startedAt = Date.now();
    foxJudgeDiag('世界书:直读开始', {
      cachedLoadedEntries: ssLastLoadedWorldInfoEntries?.length || 0,
      cachedActivatedEntries: ssLastActivatedWorldInfoEntries?.length || 0,
      hasNativeActivationSnapshot: !!ssHasNativeWorldInfoActivationSnapshot,
      api: {
        getCharLorebooks: typeof getFn('getCharLorebooks') === 'function',
        getChatLorebook: typeof getFn('getChatLorebook') === 'function',
        getLorebookEntries: typeof getFn('getLorebookEntries') === 'function',
      },
    });
    try {
      const getCharLorebooks = getFn('getCharLorebooks');
      // 只使用纯读取 API，避免兜底上下文意外创建并绑定空聊天世界书。
      const getChatLorebook = getFn('getChatLorebook');
      const getLorebookEntries = getFn('getLorebookEntries');
      if (typeof getLorebookEntries !== 'function') return out;

      // 🦊 从 SillyTavern chat_metadata 拿到本轮已激活（绿灯）的条目 uid 集合。
      //    主模型只注入：条目 enabled（蓝灯）且本轮激活（绿灯 或 constant）。
      //    如果拿不到 wi_activated（旧版/无聊天），只注入能确定为常驻的蓝灯条目。
      const activatedUids = new Set();
      const activatedKeys = new Set();
      let hasActivationData = false;
      try {
        const ctx = (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) ? SillyTavern.getContext() : null;
        const meta = ctx?.chatMetadata || ctx?.chat_metadata;
        const wiActivated = meta?.wi_activated;
        if (Array.isArray(wiActivated)) {
          // 字段存在即表示酒馆已经给出激活结果；空数组表示本轮没有绿灯。
          hasActivationData = true;
          for (const uid of wiActivated) {
            if (uid == null) continue;
            const ref = String(uid);
            if (ref.includes('.')) activatedKeys.add(ref);
            else activatedUids.add(ref);
          }
        }
        // 兼容部分版本：wi_activated 可能是对象 { uid: true }
        if (!Array.isArray(wiActivated) && wiActivated && typeof wiActivated === 'object') {
          hasActivationData = true;
          for (const k of Object.keys(wiActivated)) {
            if (!wiActivated[k]) continue;
            if (String(k).includes('.')) activatedKeys.add(String(k));
            else activatedUids.add(String(k));
          }
        }
      } catch (e) {
        log('[上下文兜底·世界书] 读取 wi_activated 失败，改用原生事件缓存或常驻蓝灯保守兜底', e);
      }
      if (!hasActivationData && ssHasNativeWorldInfoActivationSnapshot) {
        hasActivationData = true;
        for (const entry of ssLastActivatedWorldInfoEntries) {
          const uid = entry?.uid ?? entry?.id;
          if (uid == null) continue;
          const world = String(entry.world || entry.book || entry.worldName || '');
          if (world) activatedKeys.add(`${world}.${uid}`);
          else activatedUids.add(String(uid));
        }
        log(`[上下文兜底·世界书] chat_metadata 无激活字段，改用酒馆激活缓存：精确键=${activatedKeys.size}，兼容UID=${activatedUids.size}`);
      }
      // 即使 chat_metadata 只有 UID，也优先用原生事件里的 world.uid 精确键消除跨世界书 UID 碰撞。
      if (ssHasNativeWorldInfoActivationSnapshot) {
        for (const entry of ssLastActivatedWorldInfoEntries) {
          const uid = entry?.uid ?? entry?.id;
          const world = String(entry?.world || entry?.book || entry?.worldName || '');
          if (uid != null && world) activatedKeys.add(`${world}.${uid}`);
        }
      }

      const bookNames = new Set();
      try {
        if (typeof getCharLorebooks === 'function') {
          const cl = await Promise.resolve(getCharLorebooks({}));
          if (cl?.primary) bookNames.add(cl.primary);
          for (const n of (cl?.additional || [])) if (n) bookNames.add(n);
        }
      } catch (e) { log('[上下文兜底·世界书] 读取角色绑定世界书失败', e); }

      try {
        if (typeof getChatLorebook === 'function') {
          const cb = await Promise.resolve(getChatLorebook());
          if (typeof cb === 'string' && cb) bookNames.add(cb);
        }
      } catch (e) { log('[上下文兜底·世界书] 读取聊天绑定世界书失败', e); }

      let totalEntries = 0;
      let constantInjected = 0;
      let greenInjected = 0;
      let disabledSkipped = 0;
      let inactiveSkipped = 0;
      const injectedLabels = [];
      const injectedKeys = new Set();

      for (const book of bookNames) {
        try {
          const entries = await Promise.resolve(getLorebookEntries(book)) || [];
          foxJudgeDiag('世界书:读取单本', { book, entryCount: Array.isArray(entries) ? entries.length : null });
          for (const e of entries) {
            if (!e) continue;
            totalEntries++;
            // 蓝灯关闭：直接跳过
            if (e.enabled === false || e.disable === true) {
              disabledSkipped++;
              continue;
            }
            const content = String(e.content || '').trim();
            if (!content) continue;

            const uid = String(e.uid ?? e.id ?? '');
            const isConstant = ssIsWorldInfoConstant(e);
            const bookHasPreciseSnapshot = Array.from(activatedKeys).some(key => key.startsWith(`${book}.`));
            const isActivated = activatedKeys.has(`${book}.${uid}`)
              || (!bookHasPreciseSnapshot && activatedUids.has(uid));
            const label = String(e.comment || e.name || (Array.isArray(e.key) ? e.key.join(',') : (e.key || ''))).trim();

            // 🦊 绿灯匹配：有激活数据时，只保留本轮激活的条目（跟主模型一致）
            //    条件：constant=true（常驻条目，永远绿灯）OR uid 在 wi_activated 里
            //    没有激活数据时只保留常驻蓝灯，避免误把未触发的关键词条目全部注入。
            if (hasActivationData) {
              if (!isConstant && !isActivated) {
                inactiveSkipped++;
                continue;
              }
            } else if (!isConstant) {
              inactiveSkipped++;
              continue;
            }

            if (isConstant) constantInjected++;
            else if (hasActivationData && isActivated) greenInjected++;
            injectedKeys.add(`${book}.${uid}`);
            injectedLabels.push(`${book} / ${label || `uid=${uid || '?'}`} / ${isConstant ? '常驻蓝灯' : '激活绿灯'}`);
            out.push({
              role: 'system',
              content: label
                ? `【世界书·${book}·${label}】\n${content}`
                : `【世界书·${book}】\n${content}`,
            });
          }
        } catch (e) {
          log(`[上下文兜底·世界书] 读取条目失败 book=${book}`, e);
          foxJudgeDiag('世界书:读取单本异常', { book, error: foxJudgeDiagError(e) }, 'error');
        }
      }

      // WORLDINFO_ENTRIES_LOADED 含全局/角色/聊天/玩家四类世界书；补齐绑定书 API 无法枚举的全局/玩家条目。
      for (const e of ssLastLoadedWorldInfoEntries) {
        const book = String(e.world || e.book || e.worldName || '未知世界书');
        const uid = String(e.uid ?? e.id ?? '');
        const uniqueKey = `${book}.${uid}`;
        if (injectedKeys.has(uniqueKey)) continue;
        totalEntries++;
        if (e.enabled === false || e.disable === true) {
          disabledSkipped++;
          continue;
        }
        const content = String(e.content || '').trim();
        if (!content) continue;
        const isConstant = ssIsWorldInfoConstant(e);
        const bookHasPreciseSnapshot = Array.from(activatedKeys).some(key => key.startsWith(`${book}.`));
        const isActivated = activatedKeys.has(uniqueKey)
          || (!bookHasPreciseSnapshot && activatedUids.has(uid));
        if (!isConstant && (!hasActivationData || !isActivated)) {
          inactiveSkipped++;
          continue;
        }
        const label = String(e.comment || e.name || (Array.isArray(e.key) ? e.key.join(',') : (e.key || ''))).trim();
        if (isConstant) constantInjected++;
        else if (hasActivationData && isActivated) greenInjected++;
        injectedKeys.add(uniqueKey);
        injectedLabels.push(`${book} / ${label || `uid=${uid || '?'}`} / ${isConstant ? '常驻蓝灯' : '激活绿灯'}`);
        out.push({
          role: 'system',
          content: label
            ? `【世界书·${book}·${label}】\n${content}`
            : `【世界书·${book}】\n${content}`,
        });
      }

      if (hasActivationData) {
        log(`[上下文兜底·世界书] 原生匹配模式：精确激活键=${activatedKeys.size}，兼容UID=${activatedUids.size}，扫描=${totalEntries}，注入=${out.length}（常驻蓝灯=${constantInjected}，激活绿灯=${greenInjected}），关闭跳过=${disabledSkipped}，未激活跳过=${inactiveSkipped}`);
      } else {
        log(`[上下文兜底·世界书] 保守兜底模式：未取得激活快照，扫描=${totalEntries}，仅注入常驻蓝灯=${out.length}，关闭跳过=${disabledSkipped}，普通关键词条目跳过=${inactiveSkipped}`);
      }
      if (injectedLabels.length) {
        log('[上下文兜底·世界书] 已注入条目明细：', injectedLabels.join(' | '));
      } else {
        log('[上下文兜底·世界书] 本次没有可注入条目（无常驻蓝灯，且无已激活绿灯）');
      }
      foxJudgeDiag('世界书:直读完成', {
        durationMs: Date.now() - startedAt,
        bookCount: bookNames.size,
        totalEntries,
        injectedCount: out.length,
        constantInjected,
        greenInjected,
        disabledSkipped,
        inactiveSkipped,
        hasActivationData,
        activatedKeyCount: activatedKeys.size,
        activatedUidCount: activatedUids.size,
        injectedContentChars: out.reduce((sum, item) => sum + String(item?.content || '').length, 0),
      }, 'info');
    } catch (e) {
      log('[上下文兜底·世界书] 整体失败', e);
      foxJudgeDiag('世界书:直读整体异常', { durationMs: Date.now() - startedAt, error: foxJudgeDiagError(e) }, 'error');
    }
    return out;
  }

  // 🦊 直读上下文（不依赖事件监听、不发静默 generate）。
  //    用于与其他监听脚本（PVP / 缓存监控 / QR 等）冲突时的兜底：
  //    这些脚本会拦截 generate 流程或抢占 stopGeneration，导致玄狐的静默 generate
  //    被打断、prompt 广播事件根本不触发，于是事件抓取超时报“没有监听到完整请求体”。
  //    本兜底完全不碰生成流程，直接从角色卡 + 玩家设定 + 聊天楼层组装上下文，
  //    与狐构/狐忆的固定上下文同源（ssBuildFilteredChatHistoryPromptsForAnalysis）。
  async function ssBuildMainContextMessagesDirect(filterSettings = null, opts = {}) {
    const messages = [];
    const startedAt = Date.now();
    foxJudgeDiag('上下文直读:开始', {
      excludeChatHistory: opts.excludeChatHistory === true,
      filterEnabled: filterSettings?.enableContentFilter !== false,
      contextFloors: filterSettings?.contextFloors ?? null,
    });
    try {
      const ctx = (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) ? SillyTavern.getContext() : null;

      // 角色卡（描述 / 性格 / 场景）+ 玩家设定，直接从 context 读，不触发生成。
      if (ctx) {
        try {
          const char = (ctx.characters && ctx.characterId !== undefined) ? ctx.characters[ctx.characterId] : null;
          if (char) {
            const desc = String(char.description || '').trim();
            const pers = String(char.personality || '').trim();
            const scen = String(char.scenario || '').trim();
            if (desc) messages.push({ role: 'system', content: `【角色卡·描述】\n${desc}` });
            if (pers) messages.push({ role: 'system', content: `【角色卡·性格】\n${pers}` });
            if (scen) messages.push({ role: 'system', content: `【角色卡·场景】\n${scen}` });
          }
        } catch (e) { log('[上下文兜底] 读取角色卡失败', e); }

        try {
          const persona = String(ctx.userAlias || ctx.name1 || '').trim();
          const personaDesc = String(
            ctx.powerUserSettings?.persona_description
            || ctx.persona_description
            || (ctx.power_user && ctx.power_user.persona_description)
            || ''
          ).trim();
          if (personaDesc) messages.push({ role: 'system', content: `【玩家设定】\n${personaDesc}` });
          else if (persona) messages.push({ role: 'system', content: `【玩家】\n${persona}` });
          else log('[上下文兜底] 未能从 getContext 解析到玩家设定/玩家名（persona 字段缺失或为空），本次兜底不含玩家设定');
        } catch (e) { log('[上下文兜底] 读取玩家设定失败', e); }
      }

      // 🦊 世界书（best-effort）：角色绑定 + 聊天绑定，按 enabled 过滤；无 API/无书则跳过。
      try {
        const wi = await ssReadActivatedWorldInfoEntriesDirect();
        if (wi.length) {
          messages.push(...wi);
          log(`[上下文兜底] 已附加世界书条目 ${wi.length} 条`);
        } else {
          log('[上下文兜底] 未读到任何世界书条目（可能未绑定 / API 不可用 / 条目全部禁用）');
        }
      } catch (e) {
        log('[上下文兜底] 读取世界书失败', e);
      }

      // 聊天楼层：异步直读实际消息数组，不发 generate、不监听 prompt 事件。
      try {
        if (opts.excludeChatHistory === true) return messages.filter(m => m && String(m.content || '').trim());
        const chatPrompts = await ssBuildFilteredChatHistoryPromptsForExactFloors(
          filterSettings || {},
          Number(filterSettings?.contextFloors) || 0
        );
        for (const p of (chatPrompts || [])) {
          if (p && typeof p.content === 'string' && p.content.trim()) {
            messages.push({ role: p.role || 'system', content: p.content });
          }
        }
      } catch (e) {
        log('[上下文兜底] 读取聊天楼层失败', e);
      }
    } catch (e) {
      log('[上下文兜底] 直读上下文失败', e);
      foxJudgeDiag('上下文直读:整体异常', { error: foxJudgeDiagError(e) }, 'error');
    }
    const filtered = messages.filter(m => m && String(m.content || '').trim());
    foxJudgeDiag('上下文直读:完成', {
      durationMs: Date.now() - startedAt,
      messageCount: filtered.length,
      totalChars: filtered.reduce((sum, item) => sum + String(item?.content || '').length, 0),
      roleCounts: filtered.reduce((acc, item) => { const role = item?.role || 'unknown'; acc[role] = (acc[role] || 0) + 1; return acc; }, {}),
      worldInfoMessageCount: filtered.filter(item => String(item?.content || '').startsWith('【世界书')).length,
    }, 'info');
    return filtered;
  }

  async function ssCaptureMainRequestMessages(taskName = '上下文抓取', filterSettings = null, opts = {}) {
    // ✅ 直接请求一次当前 in_use 预设组合后的完整请求体。
    // ✅ 只监听酒馆正常生成流程里的 prompt 事件。
    // ✅ 不 stop，不缓存，不手动读楼层，不改聊天文件。
    // ✅ 让静默 generate 自然结束，避免 Windows EPERM 文件锁。
    // ✅ 与其他监听脚本冲突时（事件抓取超时），自动回退到直读上下文，避免狐裁失败。

    const gen = getFn('generate');
    const eo = getFn('eventOn');
    const te = getFn('tavern_events') || tavern_events;

    if (typeof gen !== 'function') throw new Error('无 generate，无法请求完整上下文');
    if (typeof eo !== 'function') throw new Error('无 eventOn，无法监听完整请求体');

    let captured = null;
    const stops = [];
    const captureStartedAt = Date.now();
    foxJudgeDiag('上下文事件抓取:入口', {
      taskName,
      requireCaptured: opts.requireCaptured === true,
      maxChatHistory: opts.maxChatHistory ?? '未指定',
      hasGenerate: typeof gen === 'function',
      hasEventOn: typeof eo === 'function',
      availableEvents: {
        chatCompletionPromptReady: !!te?.CHAT_COMPLETION_PROMPT_READY,
        generateAfterData: !!te?.GENERATE_AFTER_DATA,
        generateAfterCombinePrompts: !!te?.GENERATE_AFTER_COMBINE_PROMPTS,
      },
    });
    // 🦊 dry-run marker：在 try 之前声明，finally 才能注销它（即便中途抛错也会注销）。
    let __dryRunMarker = null;

    const normalizeMessages = (arr) => {
      if (!Array.isArray(arr)) return [];

      return arr
        .map(x => ({
          role: x?.role || 'system',
          content: String(x?.content ?? x?.message ?? ''),
        }))
        .filter(x => x.content.trim());
    };

    const capture = (arr, source = '') => {
      if (captured) return;

      const messages = normalizeMessages(arr);
      if (!messages.length) return;
      if (__dryRunMarker && !messages.some(m => m.content.includes(__dryRunMarker))) return;

      captured = messages;
      foxJudgeDiag('上下文事件抓取:命中事件', {
        source,
        durationMs: Date.now() - captureStartedAt,
        messageCount: messages.length,
        totalChars: messages.reduce((sum, item) => sum + String(item?.content || '').length, 0),
        roles: messages.map(item => item.role),
      }, 'info');
      log(`[${taskName}] 已抓取完整请求体 source=${source} messages=${messages.length}`);
      log(`[${taskName}] 请求体预览`, messages.map(m => `【${m.role}】\n${m.content}`).join('\n\n').slice(0, 3000));
    };

    try {
      if (te?.CHAT_COMPLETION_PROMPT_READY) {
        stops.push(eo(te.CHAT_COMPLETION_PROMPT_READY, d => {
          if (d?.dryRun) return;
          if (Array.isArray(d?.chat)) {
            capture(d.chat, 'CHAT_COMPLETION_PROMPT_READY.chat');
          }
        }));
      }

      if (te?.GENERATE_AFTER_DATA) {
        stops.push(eo(te.GENERATE_AFTER_DATA, (d, dryRun) => {
          if (dryRun || d?.dryRun) return;
          if (Array.isArray(d?.prompt)) {
            capture(d.prompt, 'GENERATE_AFTER_DATA.prompt');
          }
        }));
      }

      if (te?.GENERATE_AFTER_COMBINE_PROMPTS) {
        stops.push(eo(te.GENERATE_AFTER_COMBINE_PROMPTS, r => {
          if (r?.dryRun) return;

          if (Array.isArray(r?.prompt)) {
            capture(r.prompt, 'GENERATE_AFTER_COMBINE_PROMPTS.prompt[]');
          } else if (typeof r?.prompt === 'string' && !captured) {
            if (__dryRunMarker && !String(r.prompt).includes(__dryRunMarker)) return;
            captured = [{
              role: 'system',
              content: r.prompt,
            }];

            log(`[${taskName}] 已抓取完整请求体 source=GENERATE_AFTER_COMBINE_PROMPTS.prompt string`);
            log(`[${taskName}] 请求体预览`, r.prompt.slice(0, 3000));
          }
        }));
      }

      // ✅ 关键：发一次静默请求，让酒馆正常组合完整 prompt。
      // 🦊 注册 dry-run marker：让 fetch hook 在请求真正发到主模型之前短路返回伪响应，
      //    保证完整 prompt（含预设/世界书/破限/狐析）通过事件被监听器捕获，但**不产生计费**。
      //    marker 嵌进 user_input，最终会出现在 chat-completions/generate 请求体里，
      //    fetch hook 用 includes 匹配命中即短路。
      __dryRunMarker = ssBeginDryRunCapture();
      let genSettled = false;
      const hasExplicitHistoryLimit = Object.prototype.hasOwnProperty.call(opts, 'maxChatHistory');
      const maxChatHistory = hasExplicitHistoryLimit
        ? (Number.isFinite(opts.maxChatHistory) && opts.maxChatHistory > 0 ? Math.floor(opts.maxChatHistory) : 0)
        : 10;  // 🦊 修复：从 'all' 改为默认 10 楼，防止 token 爆炸
      foxJudgeDiag('上下文事件抓取:发起dry-run', { marker: __dryRunMarker, maxChatHistory });
      log(`[${taskName}] 上下文楼层限制：${maxChatHistory === 'all' ? '全部楼层' : (maxChatHistory === 0 ? '不由宿主附加聊天楼层' : `最近 ${maxChatHistory} 楼`)}`);
      const p = gen({
        preset_name: 'in_use',
        user_input: `【玄狐上下文抓取】${__dryRunMarker}`,
        should_silence: true,
        should_stream: false,
        max_chat_history: maxChatHistory,
      }).catch(e => {
        log(`[${taskName}] 静默请求结束/失败，可忽略`, e);
        return '';
      }).finally(() => { genSettled = true; });

      const start = Date.now();

      // ✅ 提前退出条件：
      //    1) 已捕获到请求体 → 成功，立即返回。
      //    2) 静默 generate 已 settle 但仍未捕获 → 强烈表明被其他脚本打断/抢占，
      //       再多等 300ms 给事件一个落地窗口后即跳出走兜底，不再干等满 8 秒。
      while (!captured && Date.now() - start < 8000) {
        if (genSettled) {
          // generate 已结束仍没抓到：给事件一个极短的兜底窗口
          await new Promise(r => setTimeout(r, 300));
          break;
        }
        await new Promise(r => setTimeout(r, 50));
      }

      // 不 stop，等它自然结束，避免 EPERM。
      try {
        await Promise.race([
          p,
          new Promise(r => setTimeout(r, 3000)),
        ]);
      } catch { }

      if (!captured?.length) {
        foxJudgeDiag('上下文事件抓取:未命中', {
          durationMs: Date.now() - captureStartedAt,
          generateSettled: genSettled,
          requireCaptured: opts.requireCaptured === true,
        }, 'error');
        // 🦊 事件抓取失败（最常见原因：其他监听脚本拦截/抢占了 generate 流程，
        //    或本次静默 generate 被中断，导致 prompt 广播事件从未触发）。
        //    即使调用方要求完整捕获，也必须先回退直读上下文；旧逻辑在此直接抛错，
        //    会让狐裁的正式一/二阶段请求根本没有机会发出，外观上就像“当前 API 完全无效”。
        log(`[${taskName}] 事件抓取未命中（可能与其他监听脚本冲突），回退到直读上下文兜底`);
        const fallback = await ssBuildMainContextMessagesDirect(filterSettings, { excludeChatHistory: maxChatHistory === 0 });
        if (fallback.length) {
          // 标记为直读消息：已含弹性聊天楼层（带【第N楼】前缀），
          // 下游不得再按"捕获体"做楼层剥离/重复追加，否则会留下标题残留行或聊天被二次注入。
          fallback.__xhDirectContext = true;
          log(`[${taskName}] 兜底成功：直读上下文 messages=${fallback.length}`);
          return fallback;
        }
        throw new Error(`${taskName}：没有监听到完整请求体，且直读上下文兜底为空（请检查当前是否有聊天楼层）。`);
      }

      const cleaned = captured.map(m => ({
        ...m,
        content: String(m.content || '').replace(`【玄狐上下文抓取】${__dryRunMarker}`, '').trim(),
      })).filter(m => m.content);
      foxJudgeDiag('上下文事件抓取:完成', {
        durationMs: Date.now() - captureStartedAt,
        messageCount: cleaned.length,
        totalChars: cleaned.reduce((sum, item) => sum + String(item?.content || '').length, 0),
      }, 'info');
      return cleaned;
    } finally {
      for (const h of stops) {
        try { h?.stop?.(); } catch { }
      }
      // 🦊 注销 dry-run marker：之后的真实生成请求一律不会被短路。
      try { ssEndDryRunCapture(__dryRunMarker); } catch { }
      foxJudgeDiag('上下文事件抓取:监听清理', {
        durationMs: Date.now() - captureStartedAt,
        listenerCount: stops.length,
        hadCapture: !!captured?.length,
      });
    }
  }

  async function ssRemoveCapturedChatHistory(messages, filterSettings = null) {
    const gcm = getFn('getChatMessages');
    const glmi = getFn('getLastMessageId');
    if (!gcm || !glmi) return Array.isArray(messages) ? messages : [];
    const actualLastId = Number(await glmi());
    const targetLastId = Number(filterSettings?.targetLastId);
    const lastId = Number.isFinite(targetLastId)
      ? Math.max(-1, Math.min(actualLastId, Math.floor(targetLastId)))
      : actualLastId;
    if (!Number.isFinite(lastId) || lastId < 0) return Array.isArray(messages) ? messages : [];
    const chatResult = await gcm(`0-${lastId}`, { hide_state: 'all', include_swipes: false });
    const chatRows = Array.isArray(chatResult) ? chatResult : [];
    const candidates = chatRows.filter(m => m?.role === 'user' || m?.role === 'assistant').map(m => ({
      role: m?.role === 'assistant' ? 'assistant' : (m?.role === 'user' ? 'user' : 'system'),
      content: ssCleanXuanhuInjectedBlocksFromMessage(m?.message || '').trim(),
      used: false,
    })).filter(x => x.content);
    let removed = 0;
    let partialStrips = 0;
    const kept = (Array.isArray(messages) ? messages : []).map(msg => {
      const role = msg?.role || 'system';
      const content = String(msg?.content ?? msg?.message ?? '').trim();
      if (!content) return null;
      const exactMatch = (role === 'user' || role === 'assistant')
        ? candidates.find(x => !x.used && x.role === role && content === x.content)
        : null;
      if (exactMatch) {
        exactMatch.used = true;
        removed++;
        return null;
      }

      // 部分 ST 版本会把深度世界书/作者注释与真实楼层合并在同一条 user/assistant 消息中。
      // 这种消息不能整条删除，只剥离同角色的真实聊天正文，保留其余非聊天上下文。
      // system 世界书即使引用/复述了聊天原文也绝不能参与匹配，否则旧世界书中包含正文片段时
      // 会被误判为“聊天楼层泄漏”，正是大量用户在上下文抓取后秒中断的根因。
      let remainder = content;
      let changed = false;
      if (role === 'user' || role === 'assistant') {
        const suffixMatch = candidates.find(x => !x.used && x.role === role && x.content.length >= 12 && remainder.endsWith(x.content));
        if (suffixMatch) {
          remainder = remainder.slice(0, -suffixMatch.content.length).trim();
          suffixMatch.used = true;
          removed++;
          changed = true;
        }
        for (const candidate of candidates) {
          if (candidate.used || candidate.role !== role || candidate.content.length < 12) continue;
          const index = remainder.lastIndexOf(candidate.content);
          if (index < 0) continue;
          remainder = `${remainder.slice(0, index)}${remainder.slice(index + candidate.content.length)}`.trim();
          candidate.used = true;
          removed++;
          changed = true;
        }
      }
      if (!remainder) return null;
      if (changed) partialStrips++;
      return { ...msg, content: remainder };
    }).filter(Boolean);
    const leaked = kept.some(msg => candidates.some(x => {
      const role = msg?.role || 'system';
      if (role !== x.role || (role !== 'user' && role !== 'assistant')) return false;
      const content = String(msg?.content ?? msg?.message ?? '');
      return !x.used && x.content.length >= 12 && content.includes(x.content);
    }));
    if (leaked) {
      foxJudgeDiag('上下文:聊天楼层剥离仍有同角色残留', {
        candidateCount: candidates.length,
        removed,
        partialStrips,
        keptCount: kept.length,
      }, 'warn');
      // 不再主动取消整轮狐裁。残留只会造成少量上下文重复，远小于直接让狐裁完全失效的损害。
    }
    foxJudgeDiag('上下文:聊天楼层剥离完成', {
      candidateCount: candidates.length,
      removed,
      partialStrips,
      keptCount: kept.length,
      hasSameRoleRemainder: leaked,
    }, leaked ? 'warn' : 'info');
    log(`[狐裁] 从完整请求体中剥离真实聊天楼层 ${removed}/${candidates.length} 条（复合消息部分剥离 ${partialStrips} 条），保留全部非聊天上下文`);
    return kept;
  }

  // 狐裁聊天窗口：固定 N 楼作为稳定前缀，尾部最多连续追加 10 楼；满后整段推进。
  // pin 同时保存内容签名，旧楼被编辑、删除或重编号时会在下次构建自动失效。
  const FOX_JUDGE_ELASTIC_FLOORS = 10;
  const FOX_JUDGE_CHAT_PIN_PREFIX = 'SPreset_FoxJudge_ChatPin_';
  let __foxJudgeLastElasticMeta = null;

  function foxJudgeChatPinStorageKey(scopeId) {
    return FOX_JUDGE_CHAT_PIN_PREFIX + String(scopeId || 'default');
  }

  function foxJudgeChatRowSignature(row) {
    const text = String(row?.message || '');
    let hash = 2166136261;
    for (let i = 0; i < text.length; i++) {
      hash ^= text.charCodeAt(i);
      hash = Math.imul(hash, 16777619);
    }
    return `${row?.role || ''}:${text.length}:${(hash >>> 0).toString(36)}`;
  }

  function foxJudgeLoadChatPinState(scopeId) {
    try {
      const raw = localStorage.getItem(foxJudgeChatPinStorageKey(scopeId));
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      return parsed && Array.isArray(parsed.pinnedIds) ? parsed : null;
    } catch {
      return null;
    }
  }

  function foxJudgeSaveChatPinState(scopeId, state) {
    try {
      localStorage.setItem(foxJudgeChatPinStorageKey(scopeId), JSON.stringify(state));
    } catch (e) {
      log('[狐裁] 保存聊天窗口锚点失败', e);
    }
  }

  function foxJudgeInvalidateChatPin(scopeId) {
    try {
      const sid = scopeId != null && String(scopeId) !== ''
        ? String(scopeId)
        : ((typeof getCurrentChatScopeId === 'function' && getCurrentChatScopeId()) || 'default');
      localStorage.removeItem(foxJudgeChatPinStorageKey(sid));
      __foxJudgeLastElasticMeta = null;
      log(`[狐裁] 已清空聊天窗口锚点（scope=${sid}）`);
    } catch (e) {
      log('[狐裁] 清空聊天窗口锚点失败', e);
    }
  }

  function foxJudgeInvalidateAllChatPins() {
    try {
      const keys = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key?.startsWith(FOX_JUDGE_CHAT_PIN_PREFIX)) keys.push(key);
      }
      keys.forEach(key => localStorage.removeItem(key));
      __foxJudgeLastElasticMeta = null;
      if (keys.length) log(`[狐裁] 已清空 ${keys.length} 个聊天窗口锚点`);
    } catch (e) {
      log('[狐裁] 清空全部聊天窗口锚点失败', e);
    }
  }

  function foxJudgeBuildElasticChatRows(allRows, stableCount, elasticMax) {
    const rowsIn = Array.isArray(allRows) ? allRows : [];
    const stable = Math.max(0, Math.floor(Number(stableCount) || 0));
    const elastic = Math.max(0, Math.floor(Number(elasticMax) || 0));
    const scopeId = (typeof getCurrentChatScopeId === 'function' && getCurrentChatScopeId()) || 'default';
    const rowMap = new Map();
    rowsIn.forEach(row => {
      const id = Number(row?.message_id);
      if (Number.isFinite(id)) rowMap.set(id, row);
    });

    let state = foxJudgeLoadChatPinState(scopeId);
    let rePinned = false;
    let advanced = false;
    const pinValid = !!(
      state?.pinnedIds?.length
      && Number(state.stableCount) === stable
      && Number(state.elasticMax) === elastic
      && state.pinnedIds.every((id, index) => {
        const row = rowMap.get(Number(id));
        return row && state.pinnedSignatures?.[index] === foxJudgeChatRowSignature(row);
      })
    );

    if (!pinValid) {
      const windowSize = Math.min(rowsIn.length, stable > 0 ? stable + elastic : rowsIn.length);
      const window = rowsIn.slice(-windowSize);
      const pinnedRows = window.slice(0, Math.min(stable || window.length, window.length));
      state = {
        version: 3,
        pinnedIds: pinnedRows.map(row => Number(row.message_id)).filter(Number.isFinite),
        pinnedSignatures: pinnedRows.map(foxJudgeChatRowSignature),
        stableCount: stable,
        elasticMax: elastic,
      };
      rePinned = true;
    }

    let stableRows = state.pinnedIds.map(id => rowMap.get(Number(id))).filter(Boolean);
    const maxPinnedId = stableRows.length ? Math.max(...state.pinnedIds.map(Number)) : -Infinity;
    let afterPin = stableRows.length
      ? rowsIn.filter(row => Number(row?.message_id) > maxPinnedId)
      : rowsIn.slice();

    while (stable > 0 && stableRows.length < stable && afterPin.length) {
      stableRows.push(afterPin.shift());
      rePinned = true;
    }

    while (elastic > 0 && afterPin.length > elastic) {
      const remaining = [...stableRows, ...afterPin].slice(elastic);
      stableRows = remaining.slice(0, Math.min(stable, remaining.length));
      afterPin = remaining.slice(stableRows.length);
      advanced = true;
    }

    if (rePinned || advanced) {
      state = {
        ...state,
        version: 3,
        pinnedIds: stableRows.map(row => Number(row.message_id)).filter(Number.isFinite),
        pinnedSignatures: stableRows.map(foxJudgeChatRowSignature),
        stableCount: stable,
        elasticMax: elastic,
      };
      foxJudgeSaveChatPinState(scopeId, state);
    }

    return {
      rows: [...stableRows, ...afterPin],
      state,
      scopeId,
      rePinned,
      advanced,
      stableCount: stableRows.length,
      elasticCount: afterPin.length,
    };
  }

  async function ssBuildFilteredChatHistoryPromptsForExactFloors(filterSettings, exactChatFloors) {
    const gcm = getFn('getChatMessages');
    const glmi = getFn('getLastMessageId');
    if (!gcm || !glmi) return [];

    const lastId = Number(await glmi());
    if (!Number.isFinite(lastId) || lastId < 0) return [];

    const rowsResult = await gcm(`0-${lastId}`, { hide_state: 'all', include_swipes: false });
    const allRows = Array.isArray(rowsResult) ? rowsResult : [];
    const floorCount = Math.max(0, Math.floor(Number(exactChatFloors) || 0));
    let rows = allRows;
    __foxJudgeLastElasticMeta = null;
    if (floorCount > 0) {
      const result = foxJudgeBuildElasticChatRows(allRows, floorCount, FOX_JUDGE_ELASTIC_FLOORS);
      rows = result.rows;
      const firstPin = result.state?.pinnedIds?.[0] ?? '?';
      const lastPin = result.state?.pinnedIds?.[result.state.pinnedIds.length - 1] ?? '?';
      __foxJudgeLastElasticMeta = {
        rePinned: result.rePinned,
        advanced: result.advanced,
        stableCount: result.stableCount,
        elasticCount: result.elasticCount,
        elasticMax: FOX_JUDGE_ELASTIC_FLOORS,
        pinnedIdRange: `${firstPin}~${lastPin}`,
        scopeId: result.scopeId,
      };
      const action = result.advanced ? '推进锚定' : (result.rePinned ? '新建锚定' : '复用锚定');
      log(`[狐裁] 弹性楼层：${action}，稳定 ${result.stableCount} 楼 id=${firstPin}~${lastPin} + 弹性 ${result.elasticCount}/${FOX_JUDGE_ELASTIC_FLOORS} 楼`);
    }
    const prompts = [];

    for (const m of rows) {
      if (!m || typeof m.message !== 'string') continue;
      const role = m.role === 'assistant' ? 'assistant' : (m.role === 'user' ? 'user' : 'system');
      let message = ssCleanXuanhuInjectedBlocksFromMessage(m.message || '');
      // ✅ 仅对自取聊天记录剥离行动选项标签 <fox_selc>/<fox_tip>：
      //    预设规则里这些标签是"字面说明"（须保留让AI知道怎么生成选项，且为字面文本无真实闭合，正则不匹配）；
      //    聊天记录里是"真实生成的行动选项"（须过滤，避免狐裁把选项内容当用户行动）。
      //    这里只剥离聊天记录，不影响捕获的预设请求体（预设部分的规则由全局过滤保留）。
      message = String(message || '')
        .replace(/<fox_selc>[\s\S]*?<\/fox_selc>/gi, '')
        .replace(/<fox_tips?>[\s\S]*?<\/fox_tips?>/gi, '')
        .replace(/<fox_selc>[\s\S]*$/gi, '')
        .replace(/<fox_tips?>[\s\S]*$/gi, '');
      // 这里只重建真实楼层，不提前做（包含/排除）标签过滤。最终上下文汇总会统一按角色过滤一次，
      // 避免包含标签在这里被剥掉外壳后，又被全局严格过滤误删。
      message = String(message || '').trim();
      if (!message) continue;
      const name = m.name ? `/${m.name}` : '';
      const hiddenMark = m.is_hidden ? '（隐藏楼层）' : '';
      prompts.push({
        role,
        content: `【第${m.message_id}楼 ${role}${name}${hiddenMark}】\n${message}`,
      });
    }

    return prompts;
  }

  function ssBuildFoxJudgeChatContextText(chatMessages, filterSettings, opts = {}) {
    const arr = Array.isArray(chatMessages) ? chatMessages : [];
    if (!arr.length) return '';
    return ssMessageArrayToContextText(arr, filterSettings, {
      fallbackToFullText: true,
      skipRoleLabels: opts.skipRoleLabels === true,
      filterAssistantOnly: true,
      keepModuleInject: false,
    }).trim();
  }

  function ssResolveHushenModuleContent(mod) {
    let content = '';
    try {
      content = String(findPromptByIdOrIdentifier(mod.identifier)?.content || '').trim();
    } catch { }
    if (!content) {
      try {
        if (!state.hushenSettings) state.hushenSettings = loadHushenSettings();
        content = String(state.hushenSettings?.analyzed?.[mod.id] || '').trim();
      } catch { }
    }
    return content;
  }

  function ssBuildUserPrefsXmlBlock() {
    const parts = [];
    try {
      for (const mod of HUSHEN_MODULES || []) {
        const content = ssResolveHushenModuleContent(mod);
        if (content) parts.push(`【${mod.label}】\n${content}`);
      }
    } catch (e) {
      log('[狐裁] 构建 User_Prefs 失败', e);
    }
    return parts.length ? `以下是用户偏好段落：\n<User_Prefs>\n${parts.join('\n\n')}\n</User_Prefs>` : '';
  }

  function ssUserPrefsBlockHasContent(text) {
    const blocks = [...String(text || '').matchAll(/<User_Prefs>([\s\S]*?)<\/User_Prefs>/gi)];
    return blocks.some(match => match[1].replace(/【[^】]+】/g, '').replace(/\s+/g, ' ').trim().length > 2);
  }

  function ssEnsureUserPrefsInContextText(text, taskName = '狐裁') {
    const block = ssBuildUserPrefsXmlBlock();
    let out = String(text || '');
    if (!block || ssUserPrefsBlockHasContent(out)) return out;
    if (/<User_Prefs>[\s\S]*?<\/User_Prefs>/i.test(out)) {
      out = out.replace(/以下是用户偏好段落：\s*\n?/gi, '');
      out = out.replace(/<User_Prefs>[\s\S]*?<\/User_Prefs>/i, block);
      log(`[${taskName}] 已用狐析保存内容替换空的 User_Prefs`);
      return out;
    }
    log(`[${taskName}] 上下文缺少 User_Prefs，已从狐析保存内容补入`);
    return [out.trim(), block].filter(Boolean).join('\n\n');
  }

  async function ssBuildFilteredMainContextText(taskName, filterSettings, opts = {}) {
    // 🦊 useDirectContext: true → 完全跳过"为了抓 prompt 而发起的主模型静默 generate"，
    //    直接用 ssBuildMainContextMessagesDirect 从 SillyTavern.getContext() + 聊天楼层组装上下文。
    //    未显式启用时走 V14.8 的事件抓取路径；dry-run fetch hook 会在上游请求前短路，
    //    但预设组合及统一注入监听仍会正常执行，因此可读取与主模型一致的完整上下文。
    let messages;
    const exactChatFloors = Number.isFinite(opts.exactChatFloors) && opts.exactChatFloors > 0 ? Math.floor(opts.exactChatFloors) : 0;
    foxJudgeDiag('上下文汇总:选择路径', {
      taskName,
      exactChatFloors,
      useDirectContext: opts.useDirectContext === true,
      requireCaptured: opts.requireCaptured === true,
      skipRoleLabels: opts.skipRoleLabels === true,
    });
    // 先过滤捕获体中的静态上下文，再追加连续聊天窗口和本轮输入。
    // 动态内容永远位于稳定聊天之后，避免每轮输入提前截断服务端 prefix cache。
    if (opts.useDirectContext === true) {
      messages = await ssBuildMainContextMessagesDirect(filterSettings);
      if (!messages.length) {
        if (opts.neverGenerateForContext === true) {
          throw new Error(`${taskName}：本地直读上下文为空。为避免产生额外主模型请求，已取消本次思考。`);
        }
        // 直读为空时再回退到事件抓取，避免完全无上下文。
        // ⚠️ 注意：ssCaptureMainRequestMessages 会发起一次主模型静默 generate（max_tokens=1，
        //    但带完整 input token，依然会被计费）。为了不悄悄回退到计费路径，这里必须把
        //    该行为明确告知用户，让其能感知"为什么本次仍有一次主模型计费"。
        log(`[${taskName}] 直读上下文为空，回退到事件抓取（将产生一次主模型静默请求）`);
        try { toast(`⚠️ ${taskName}：直读上下文为空，本次回退到主模型抓取，可能产生一次额外计费`, 'warning'); } catch { }
        messages = await ssCaptureMainRequestMessages(taskName, filterSettings, opts);
      }
    } else if (opts.requireCaptured === true) {
      messages = await ssCaptureMainRequestMessages(taskName, filterSettings, { ...opts, requireCaptured: true });
      if (!messages?.length) throw new Error(`${taskName}：未能捕获完整请求体，为避免发送不完整上下文已取消本次思考`);
    } else {
      messages = await ssCaptureMainRequestMessages(taskName, filterSettings, opts);
    }

    // 直读消息（显式 useDirectContext，或事件抓取失败后的兜底）已含弹性聊天楼层且带【第N楼】前缀，
    // 不能再按"捕获体"执行楼层剥离/单独重建聊天窗口，否则剥离匹配失败会留下标题残留、聊天被二次追加。
    const isDirectMessages = opts.useDirectContext === true || messages?.__xhDirectContext === true;
    let chatMessages = [];
    let latestUserTail = '';
    if (!isDirectMessages) {
      chatMessages = await ssBuildFilteredChatHistoryPromptsForExactFloors(filterSettings, exactChatFloors);
      if (Array.isArray(messages) && messages.length) {
        messages = await ssRemoveCapturedChatHistory(messages, filterSettings);
      }
    }
    if (opts.latestUserInput && typeof opts.latestUserInput === 'string' && opts.latestUserInput.trim()) {
      const userText = opts.latestUserInput.trim();
      const probe = userText.slice(0, Math.min(120, userText.length));
      const alreadyInChat = chatMessages.some(m => typeof m?.content === 'string' && m.content.includes(probe))
        || (isDirectMessages && Array.isArray(messages) && messages.some(m => typeof m?.content === 'string' && m.content.includes(probe)));
      if (!alreadyInChat) {
        latestUserTail = `【本轮用户输入】\n${userText}`;
      }
    }

    let usedFallbackToFullText = false;

    // ✅ reroll/swipe 专用：排除最后一条 assistant 消息（用户不满意的旧文本）。
    //    reroll/swipe 会替换最后一条 assistant，新请求的上下文不包含旧文本。
    //    狐裁思考也应基于"没有旧文本"的上下文，否则会参考旧文本导致新输出与旧文本雷同。
    if (opts.excludeLastAssistant === true && Array.isArray(chatMessages)) {
      for (let i = chatMessages.length - 1; i >= 0; i--) {
        if (chatMessages[i]?.role === 'assistant') {
          chatMessages.splice(i, 1);
          break;
        }
      }
    }
    if (opts.excludeLastAssistant === true && Array.isArray(messages)) {
      for (let i = messages.length - 1; i >= 0; i--) {
        if (messages[i]?.role === 'assistant') {
          messages.splice(i, 1);
          log(`[${taskName}] 已排除最后一条 assistant 消息（reroll/swipe 上下文修正）`);
          break;
        }
      }
    }

    // 🦊 安全网：确保狐裁上下文始终包含 fox_extra 内的注入内容（狐搜/狐忆/狐构/平行世界）。
    //    事件抓取期间，统一注入监听器理论上会先于抓取监听器执行并把内容塞进 <fox_extra></fox_extra>。
    //    但在某些 ST 版本/事件顺序下，注入监听器可能未在抓取窗口内触发，
    //    导致抓到的请求体里 fox_extra 是空的 -> 狐裁无法读取注入内容。
    //    这里在抓取完成后补一次注入：仅当请求体中尚无当前注入块且存在 <fox_extra> 标签时才执行，
    //    避免与已正常触发的注入冲突（ssInjectIntoPromptArrayByFoxExtra 会先剥离旧块再插入新块）。
    try {
      if (Array.isArray(messages) && messages.length) {
        const alreadyInjected = !!ssFindExistingCurrentPromptInjectBlockInArray(messages);
        const hasFoxExtraTag = messages.some(m =>
          typeof m?.content === 'string' && /<\s*fox_extra\b[^>]*>/i.test(m.content)
        );
        if (!alreadyInjected && hasFoxExtraTag) {
          ssInjectIntoPromptArrayByFoxExtra(messages);
          log(`[${taskName}] 安全网：抓取的请求体缺少注入块，已补注入 fox_extra 内容`);
        }
      }
    } catch (e) {
      log(`[${taskName}] 安全网：补注入 fox_extra 内容失败`, e);
    }

    let text = ssMessageArrayToContextText(messages, filterSettings, {
      fallbackToFullText: false,
      skipRoleLabels: opts.skipRoleLabels === true,
      keepModuleInject: true,
    });

    // ✅ 标签过滤后为空时，先用 fallbackToFullText 再兜一次（避免包含标签设置过严直接判失败）。
    if (!text.trim()) {
      usedFallbackToFullText = true;
      text = ssMessageArrayToContextText(messages, filterSettings, {
        fallbackToFullText: true,
        skipRoleLabels: opts.skipRoleLabels === true,
        keepModuleInject: true,
      });
    }

    // 狐搜/狐忆/狐构/平行世界属于每轮可能变化的模块块，移到稳定聊天之后；
    // 否则模块内容先变化会让服务端缓存尚未到达聊天区就中断。
    const dynamicModuleTail = ssExtractCurrentPromptInjectBlock(text);
    if (dynamicModuleTail) text = ssStripCurrentPromptInjectBlock(text);
    text = ssEnsureUserPrefsInContextText(text, taskName);
    if (chatMessages.length && !isDirectMessages) {
      const chatText = ssBuildFoxJudgeChatContextText(chatMessages, filterSettings, {
        skipRoleLabels: opts.skipRoleLabels === true,
      });
      if (chatText) text = [text.trim(), chatText].filter(Boolean).join('\n\n');
    }
    if (dynamicModuleTail) text = [text.trim(), dynamicModuleTail].filter(Boolean).join('\n\n');
    if (latestUserTail) text = [text.trim(), latestUserTail].filter(Boolean).join('\n\n');

    if (!text.trim()) {
      throw new Error(
        `${taskName}：已经请求到上下文，但按当前标签过滤后为空。请检查狐构/狐忆的包含标签设置。`
      );
    }

    foxJudgeDiag('上下文汇总:文本完成', {
      messageCount: messages?.length || 0,
      textLength: text.length,
      exactChatFloors,
      usedFallbackToFullText,
      containsFoxExtraTag: /<\s*fox_extra\b[^>]*>/i.test(text),
      containsFoxExtraContent: SS_CURRENT_INJECT_START ? text.includes(SS_CURRENT_INJECT_START) : false,
      containsChatHistory: /【第\d+楼\s+(user|assistant)/i.test(text),
      chatMessageCount: chatMessages.length,
      userPrefsHasContent: ssUserPrefsBlockHasContent(text),
      chatPinRePinned: !!__foxJudgeLastElasticMeta?.rePinned,
      chatPinAdvanced: !!__foxJudgeLastElasticMeta?.advanced,
      chatStableCount: __foxJudgeLastElasticMeta?.stableCount ?? 0,
      chatElasticCount: __foxJudgeLastElasticMeta?.elasticCount ?? 0,
      chatPinnedIdRange: __foxJudgeLastElasticMeta?.pinnedIdRange || '',
    }, 'info');

    return text;
  }

  // ==================== 狐构/狐忆统一固定上下文 ====================
  // 固定顺序：
  // 1. char_description
  // 2. persona_description
  // 3. world_info_before
  // 4. world_info_after
  // 5. chatHistory
  //
  // 注意：
  // - user 消息不做标签过滤
  // - assistant/char 消息按传入的标签过滤设置过滤
  // - 不限制字数
  // - 不抓完整请求体，不缓存，不临时 generate 抓 prompt

  function ssCleanXuanhuInjectedBlocksFromMessage(text) {
    let msg = String(text || '');

    try {
      msg = msg
        .replace(new RegExp(`${CONFIG.SUMMARY_FLOOR_START}[\\s\\S]*?${CONFIG.SUMMARY_FLOOR_END}`, 'g'), '')
        .replace(new RegExp(`${FULL_SUMMARY_FLOOR_MARK}[\\s\\S]*`, 'g'), '')
        .replace(/<fox_outline>[\s\S]*?<\/fox_outline>/gi, '')
        .replace(/<fox_memory>[\s\S]*?<\/fox_memory>/gi, '')
        .replace(/<parallel_world>[\s\S]*?<\/parallel_world>/gi, '')
        .replace(/<SearchResults>[\s\S]*?<\/SearchResults>/gi, '')
        .replace(/<think_fox~>[\s\S]*?<\/think_fox~>/gi, '')
        .replace(/<fox_phone_log>[\s\S]*?<\/fox_phone_log>/gi, '')
        .replace(/<fox_social>[\s\S]*?<\/fox_social>/gi, '')
        .replace(/<fox_input>[\s\S]*?<\/fox_input>/gi, block => {
          const match = block.match(/【原始输入】\s*([\s\S]*?)(?=\n\s*【(?:润色后大纲|思考方向|注意事项|角色卡、世界书与上下文设定)】|\s*<\/fox_input>)/i);
          return match ? match[1].trim() : '';
        });

      if (typeof ssStripCurrentPromptInjectBlock === 'function') {
        msg = ssStripCurrentPromptInjectBlock(msg);
      }
    } catch { }

    return msg.trim();
  }

  function ssBuildUserPreferenceContextPrompt() {
    const lines = [];

    try {
      for (const mod of HUSHEN_MODULES || []) {
        const content = ssResolveHushenModuleContent(mod);

        if (!content) continue;

        let enabledText = '未启用但仍读取';
        try {
          if (findPromptByIdOrIdentifier(mod.identifier)?.enabled === true) enabledText = '启用中';
        } catch { }
        lines.push(`【${mod.label}｜${enabledText}】\n${content}`);
      }
    } catch (e) {
      log('[固定上下文] 读取狐析用户偏好失败', e);
    }

    if (!lines.length) {
      // 🦊 注册默认提示词，支持用户自定义
      xhRegisterPromptDefault('fox_hushen', {
        head: '【狐析用户偏好】\n以下是用户通过狐析模块写入或保存的长期偏好。狐构和狐忆分析时必须读取并参考这些内容。',
        tail: ''
      });
      return {
        role: 'system',
        content: `${xhGetPrompt('fox_hushen', 'head')}\n（暂无用户偏好内容）`,
      };
    }

    // 🦊 注册默认提示词，支持用户自定义
    xhRegisterPromptDefault('fox_hushen', {
      head: '【狐析用户偏好】\n以下是用户通过狐析模块写入或保存的长期偏好。狐构和狐忆分析时必须读取并参考这些内容。',
      tail: ''
    });
    const hushenHead = xhGetPrompt('fox_hushen', 'head');
    const hushenTail = xhGetPrompt('fox_hushen', 'tail');
    const hushenBody = lines.join('\n\n');

    return {
      role: 'system',
      content: hushenTail
        ? `${hushenHead}\n\n${hushenBody}\n\n${hushenTail}`
        : `${hushenHead}\n\n${hushenBody}`,
    };
  }

  function ssBuildFilteredChatHistoryPromptsForAnalysis(filterSettings) {
    const prompts = [];

    const gcm = getFn('getChatMessages');
    const glmi = getFn('getLastMessageId');

    if (!gcm || !glmi) {
      log('[固定上下文] 缺少 getChatMessages / getLastMessageId');
      return prompts;
    }

    const actualLastId = glmi();
    const targetLastId = Number(filterSettings?.targetLastId);
    const lastId = Number.isFinite(targetLastId)
      ? Math.max(-1, Math.min(actualLastId, Math.floor(targetLastId)))
      : actualLastId;
    if (lastId < 0) {
      log('[固定上下文] 当前无聊天楼层');
      return prompts;
    }

    // ✅ 楼层发送限制：0 = 全部楼层，N = 只发最新 N 楼聊天记录
    // 优先从 filterSettings 读取，否则回退到 foxMemoryConfig
    // ✅ 支持从指定楼层开始（大总结增量模式：只发上次总结点之后的新增楼层）
    const startFloorId = Number.isFinite(filterSettings?.startFloorId) ? filterSettings.startFloorId : null;
    let contextFloors = filterSettings?.contextFloors;
    if (contextFloors == null || !Number.isFinite(contextFloors)) {
      contextFloors = foxMemoryConfig?.contextFloors;
    }
    let startId = 0;
    if (startFloorId != null && startFloorId >= 0) {
      startId = Math.max(0, startFloorId);
      log(`[固定上下文] 增量起点生效：startFloorId=${startFloorId}，发送第${startId}-${lastId}楼`);
    } else if (Number.isFinite(contextFloors) && contextFloors > 0) {
      startId = Math.max(0, lastId - contextFloors + 1);
      log(`[固定上下文] 楼层限制生效：contextFloors=${contextFloors}，发送第${startId}-${lastId}楼`);
    }

    // ✅ 关键修复：
    // 必须读取 all，不能只读 unhidden。
    // 否则被隐藏/折叠/总结流程处理过的 char 楼层会直接消失，只剩 user。
    let ms = gcm(`${startId}-${lastId}`, {
      hide_state: 'all',
      include_swipes: false,
    }) || [];
    // 按实际返回的聊天楼层计数，而不是假设 message_id 连续。
    // 删除过楼层时 ID 可能有空洞，直接用 lastId-N+1 会少发；slice(-N) 才是严格的“最新 N 楼”。
    if (startFloorId == null && Number.isFinite(contextFloors) && contextFloors > 0) {
      const allRows = gcm(`0-${lastId}`, { hide_state: 'all', include_swipes: false }) || [];
      ms = allRows.slice(-Math.floor(contextFloors));
      if (ms.length) startId = Number.isFinite(ms[0]?.message_id) ? ms[0].message_id : startId;
    }

    const settings = ssNormalizeTagFilterSettings(filterSettings || {});

    // ✅ 可选：跳过隐藏楼层（大总结需要只总结非隐藏楼层，避免重复总结已隐藏内容）。
    const excludeHidden = filterSettings?.excludeHidden === true;

    let userCount = 0;
    let assistantCount = 0;
    let systemCount = 0;
    let skippedCount = 0;
    // 🦊 分角色跳过计数：assistant 被标签过滤/清洗清空时一眼可查（历史事故：保留标签
    //    只配 <All_Context> 时 assistant 楼层全部被丢弃，但旧日志仍把 assistant 计入，
    //    表现为"日志看着正常、实际正文全丢"，极难排查）。
    let userSkipped = 0;
    let assistantSkipped = 0;
    let systemSkipped = 0;

    for (const m of ms) {
      if (!m || typeof m.message !== 'string') {
        skippedCount++;
        continue;
      }

      if (excludeHidden && m.is_hidden) {
        skippedCount++;
        continue;
      }

      const role = m.role === 'assistant'
        ? 'assistant'
        : (m.role === 'user' ? 'user' : 'system');

      let msg = ssCleanXuanhuInjectedBlocksFromMessage(m.message || '');

      if (!msg.trim()) {
        skippedCount++;
        if (role === 'assistant') assistantSkipped++;
        else if (role === 'user') userSkipped++;
        else systemSkipped++;
        continue;
      }

      let finalMsg = '';

      if (role === 'user') {
        // ✅ 用户消息绝对不做标签过滤
        finalMsg = msg;
      } else {
        // ✅ char/assistant/system 先按当前模块标签过滤
        finalMsg = ssFilterByTagPairs(msg, settings, {
          fallbackToFullText: filterSettings?.fallbackToFullTextOnNoInclude === true,
        });
      }

      finalMsg = String(finalMsg || '').trim();

      if (!finalMsg) {
        skippedCount++;
        if (role === 'assistant') assistantSkipped++;
        else if (role === 'user') userSkipped++;
        else systemSkipped++;
        continue;
      }

      // ✅ 只有真正进入注入内容的楼层才计数，日志所见即所得
      if (role === 'user') userCount++;
      else if (role === 'assistant') assistantCount++;
      else systemCount++;

      const name = m.name ? `/${m.name}` : '';
      const hiddenMark = m.is_hidden ? '（隐藏楼层）' : '';

      prompts.push({
        role,
        content: `【第${m.message_id}楼 ${role}${name}${hiddenMark}｜chatHistory，可能包含深度世界书/作者注释影响】\n${finalMsg}`,
      });
    }

    log(
      `[固定上下文] chatHistory 构建完成：总楼层=${ms.length}，注入=${prompts.length}，user=${userCount}，assistant=${assistantCount}，system=${systemCount}，跳过=${skippedCount}（清洗/过滤丢弃：user=${userSkipped} assistant=${assistantSkipped} system=${systemSkipped}）`
    );

    return prompts;
  }
  function ssBuildFixedContextOrderedPrompts(filterSettings) {
    log('[固定上下文·世界书] 已加入 world_info_before/world_info_after；狐构、狐忆、狐搜由酒馆原生扫描并注入常驻蓝灯与激活绿灯条目');
    const prompts = [
      {
        role: 'system',
        content: `【固定上下文读取说明】
接下来会按固定顺序读取角色卡、玩家设定、场景、世界书、用户偏好与聊天记录。
你必须把这些内容视为完整上下文，不允许只看最新用户输入。`,
      },

      // 角色卡与玩家设定
      'char_description',
      'char_personality',
      'scenario',
      'persona_description',

      // 狐析用户偏好：强制读取所有非空狐析条目
      ssBuildUserPreferenceContextPrompt(),

      // 世界书 before / after：保留酒馆原生占位符，覆盖全局/角色/聊天/玩家世界书。
      'world_info_before',
      'world_info_after',
    ];

    // 新对话可能尚未创建对应聊天文件。宿主聊天 API 抛错时保留其余固定上下文继续生成。
    try {
      prompts.push(...ssBuildFilteredChatHistoryPromptsForAnalysis(filterSettings));
    } catch (e) {
      log('[固定上下文] chatHistory 读取失败，已跳过聊天记录继续构建', e);
    }

    return prompts;
  }

  // ==================== 额外分析任务：临时净化当前预设 ====================
  // 用于狐构/狐忆：
  // - 仍然调用 generate({ preset_name:'in_use' })，让酒馆自己扫描世界书/角色卡/场景。
  // - 但临时关闭普通提示词，避免你的正文思维链、抢话规则、stage 检查块污染分析任务。
  // - 任务结束后恢复所有条目开关。
  const SS_CONTEXT_PLACEHOLDER_IDS = new Set([
    'worldInfoBefore',
    'personaDescription',
    'charDescription',
    'charPersonality',
    'scenario',
    'worldInfoAfter',
    'dialogueExamples',
    'chatHistory',
  ]);

  async function ssRunWithContextOnlyPreset(taskName, runner) {
    const snapshot = [];

    try {
      await updatePresetWith('in_use', (preset) => {
        for (const p of preset.prompts || []) {
          const ref = p.id || p.identifier || '';

          snapshot.push({
            id: p.id || '',
            identifier: p.identifier || '',
            enabled: !!p.enabled,
          });

          // ✅ 只保留上下文占位符，关闭所有普通提示词/系统提示词/预设规则
          if (!SS_CONTEXT_PLACEHOLDER_IDS.has(ref)) {
            p.enabled = false;
          }
        }

        return preset;
      }, { render: 'none' });

      log(`[${taskName}] 已临时净化预设：仅保留上下文占位符`);

      return await runner();
    } finally {
      try {
        await updatePresetWith('in_use', (preset) => {
          for (const p of preset.prompts || []) {
            const old = snapshot.find(x =>
              (x.id && x.id === p.id) ||
              (x.identifier && x.identifier === p.identifier)
            );

            if (old) {
              p.enabled = old.enabled;
            }
          }

          return preset;
        }, { render: 'debounced' });

        log(`[${taskName}] 已恢复预设开关`);
      } catch (e) {
        log(`[${taskName}] 恢复预设开关失败`, e);
      }
    }
  }

  function getRegexes() { return SillyTavern.getContext?.()?.chatCompletionSettings?.extensions?.regex_scripts; }
  function updateMemory(fn) {
    const r = getRegexes();
    if (!r) return Promise.resolve(false);
    fn(r);
    return syncRegexToPreset(r).then(() => true);
  }
  async function syncRegexToPreset(regexArr) {
    try {
      await updatePresetWith('in_use', (preset) => {
        if (!preset?.extensions) return preset;
        if (!preset.extensions.regex_scripts) return preset;
        for (const src of regexArr) {
          const dst = preset.extensions.regex_scripts.find(p => p.id === src.id);
          if (dst) {
            // 旧格式字段 (RegexScriptData: disabled / markdownOnly / minDepth)
            if (typeof src.disabled === 'boolean') dst.disabled = src.disabled;
            if (typeof src.markdownOnly === 'boolean') dst.markdownOnly = src.markdownOnly;
            if (typeof src.minDepth === 'number' || src.minDepth === null) dst.minDepth = src.minDepth;
            // 新 API 字段 (TavernRegex: enabled / min_depth)
            if (typeof src.enabled === 'boolean') dst.enabled = src.enabled;
            if (typeof src.min_depth === 'number' || src.min_depth === null) dst.min_depth = src.min_depth;
          }
        }
        return preset;
      }, { render: 'debounced' });
      const ctx = SillyTavern?.getContext?.();
      if (ctx?.saveSettingsDebounced) ctx.saveSettingsDebounced();
    } catch (e) {
      log('[syncRegexToPreset] 同步regex到预设失败', e);
    }
  }
  function isThoughtVisible() { const hr = (getRegexes() || []).find(r => r.id === CONFIG.HIDE_ID); return !hr || hr.markdownOnly === false; }
  function getThoughtVisiblePreference() {
    const saved = localStorage.getItem(CONFIG.THOUGHT_VISIBLE_KEY);
    if (saved === 'true' || saved === 'false') return saved === 'true';

    const current = isThoughtVisible();
    localStorage.setItem(CONFIG.THOUGHT_VISIBLE_KEY, current ? 'true' : 'false');
    return current;
  }
  async function setThoughtVisible(v, options = {}) {
    const persist = options.persist !== false;
    if (persist) {
      localStorage.setItem(CONFIG.THOUGHT_VISIBLE_KEY, v ? 'true' : 'false');
      state.thoughtVisibilityIntentVersion++;
    }
    await updateMemory(rx => { const r = rx.find(r => r.id === CONFIG.HIDE_ID); if (r) { r.disabled = false; r.markdownOnly = !v; } });
  }

  // 🆕 隐藏远楼层：通过 regex minDepth 控制正文楼层的可见范围
  async function foxMemoryApplyHideFarFloors(enabled, threshold) {
    const id = CONFIG.FOX_MEMORY_HIDE_FAR_FLOORS_ID;
    if (!id) { log('[狐忆·隐藏远楼层] 缺少正则ID配置'); return; }
    const depth = Math.max(1, parseInt(threshold) || 10);

    // 优先使用新 API (TavernRegex: enabled / min_depth)
    const updateTavernRegexesWithFn = getFn('updateTavernRegexesWith');
    if (typeof updateTavernRegexesWithFn === 'function') {
      try {
        const getTavernRegexesFn = getFn('getTavernRegexes');
        if (typeof getTavernRegexesFn === 'function') {
          const tavRegexes = getTavernRegexesFn({ type: 'preset', name: 'in_use' });
          if (tavRegexes) {
            const tavTarget = tavRegexes.find(r => r.id === id);
            if (!tavTarget) { log(`[狐忆·隐藏远楼层] 新API未找到ID=${id} 的正则脚本，回退旧方式`); }
            else {
              await updateTavernRegexesWithFn(rx => {
                const r = rx.find(r => r.id === id);
                if (r) {
                  r.enabled = enabled;
                  r.min_depth = depth;
                  log(`[狐忆·隐藏远楼层] 已应用(新API): enabled=${r.enabled}, min_depth=${r.min_depth}`);
                }
                return rx;
              }, { type: 'preset', name: 'in_use' });
              return;
            }
          }
        }
      } catch (e) {
        log('[狐忆·隐藏远楼层] 新API失败，回退旧方式:', e);
      }
    }

    // 回退：直接操作 chatCompletionSettings.extensions.regex_scripts
    const regexes = getRegexes();
    if (!regexes) { log('[狐忆·隐藏远楼层] 未找到 regex_scripts，无法应用'); return; }
    const target = regexes.find(r => r.id === id);
    if (!target) { log(`[狐忆·隐藏远楼层] 未找到ID=${id} 的正则脚本，无法应用`); return; }
    await updateMemory(rx => {
      const r = rx.find(r => r.id === id);
      if (r) {
        // 兼容新旧两种字段格式：旧 (disabled/minDepth) + 新 (enabled/min_depth)
        r.disabled = !enabled;
        r.minDepth = depth;
        r.enabled = enabled;
        r.min_depth = depth;
        log(`[狐忆·隐藏远楼层] 已应用: disabled=${r.disabled}, minDepth=${r.minDepth}, enabled=${r.enabled}, min_depth=${r.min_depth}`);
      }
    });
  }
  function getStyleId(s, e) { if (s === 'HUSHE') return e ? CONFIG.HUSHE_EXPANDED_ID : CONFIG.HUSHE_ID; if (s === 'JIANYUE') return e ? CONFIG.JIANYUE_EXPANDED_ID : CONFIG.JIANYUE_ID; if (s === 'BIAOLI') return e ? CONFIG.BIAOLI_EXPANDED_ID : CONFIG.BIAOLI_ID; return e ? CONFIG.HUSHE_EXPANDED_ID : CONFIG.HUSHE_ID; }
  function getMiniId(s) { if (s === 'HUSHE') return CONFIG.MINI_HUSHE_ID; if (s === 'JIANYUE') return CONFIG.MINI_JIANYUE_ID; if (s === 'BIAOLI') return CONFIG.MINI_BIAOLI_ID; return CONFIG.MINI_HUSHE_ID; }
  async function setBeautyStyle(style, expanded) {
    if (state.isMini) {
      await disableAllBeauty();
      await enableOnlyMini(style);
      return;
    }
    await disableAllMini();
    const tid = getStyleId(style, expanded);
    await updateMemory(rx => {
      for (const id of ALL_STYLE_IDS) {
        const r = rx.find(r => r.id === id);
        if (r) r.disabled = (id !== tid);
      }
      for (const id of ALL_MINI_IDS) {
        const r = rx.find(r => r.id === id);
        if (r) r.disabled = true;
      }
    });
  }
  async function disableAllBeauty() { await updateMemory(rx => { for (const id of ALL_STYLE_IDS) { const r = rx.find(r => r.id === id); if (r) r.disabled = true; } }); }
  async function disableAllMini() { await updateMemory(rx => { for (const id of ALL_MINI_IDS) { const r = rx.find(r => r.id === id); if (r) r.disabled = true; } }); }
  async function enableOnlyMini(style) {
    const mid = getMiniId(style);
    await updateMemory(rx => {
      for (const id of ALL_STYLE_IDS) {
        const r = rx.find(r => r.id === id);
        if (r) r.disabled = true;
      }
      for (const id of ALL_MINI_IDS) {
        const r = rx.find(r => r.id === id);
        if (r) r.disabled = (id !== mid);
      }
    });
  }
  function getCurrentLastMessageId() {
    try {
      const fn = getFn('getLastMessageId');
      return typeof fn === 'function' ? (fn() ?? -1) : -1;
    } catch {
      return -1;
    }
  }
  async function forceRefresh(mid) {
    const id = mid ?? getCurrentLastMessageId();
    const scm = getFn('setChatMessages');
    if (id >= 0 && typeof scm === 'function') {
      await scm([{ message_id: id }], { refresh: 'affected' });
    }
  }

  async function forceRefreshAll() {
    try {
      const glmi = getFn('getLastMessageId');
      const scm = getFn('setChatMessages');
      const gcm = getFn('getChatMessages');
      if (!glmi || !scm || !gcm) return;
      const lastId = glmi();
      if (lastId < 0) return;
      const msgs = gcm(`0-${lastId}`);
      if (!Array.isArray(msgs)) return;
      const updates = msgs.map(m => ({ message_id: m.message_id })).filter(u => u.message_id != null);
      if (updates.length > 0) {
        await scm(updates, { refresh: 'affected' });
      }
    } catch (e) {
      log('[forceRefreshAll] 失败', e);
    }
  }
  function getStyleName(s) { const n = { HUSHE: '🦊 狐神抚', JIANYUE: '◈ 简约黑', BIAOLI: '◇ 表裏1.0' }; return n[s] || '未知'; }
  function isStreamingEnabled() {
    try {
      return getPreset?.('in_use')?.settings?.should_stream === true;
    } catch {
      return false;
    }
  }

  // 🦊 流式开关：仅用于修改 should_stream。
  //    偏好由平滑流式按钮控制（CONFIG.ENABLED_KEY），此函数只负责写入预设。
  async function setStreaming(enabled) {
    await updatePresetWith('in_use', (p) => {
      if (!p.settings) p.settings = {};
      p.settings.should_stream = !!enabled;
      return p;
    }, { render: 'debounced' });
  }

  // ✅ 流式偏好恢复：平滑流式开关是唯一权威，任何偏离都强制恢复。
  //    用于修复"切换后流式被自动关掉"或"聊着聊着流式莫名关闭"。
  async function ssRestoreStreamPreferenceIfNeeded(reason = '') {
    try {
      const pref = ssLoadStreamPreference();
      const current = isStreamingEnabled();
      if (current !== pref) {
        await setStreaming(pref);
        log(`[流式恢复] ${reason}：检测到 should_stream=${current} 偏离平滑流式开关=${pref}，已强制恢复`);
        try { toast(`💡 已恢复流式传输设置（${reason}时被重置）`, 'info'); } catch {}
      }
