  function ssFindNewAutoSummaryFloorId(currentMessageId) {
    try {
      const gcm = getFn('getChatMessages');
      if (!gcm) return -1;

      const last = Number(currentMessageId ?? getCurrentLastMessageId());
      if (!Number.isFinite(last) || last < 0) return -1;

      const from = Math.max(0, last - Math.max(20, (state.summaryAutoThreshold || 200) + 50));
      const ms = gcm(`${from}-${last}`, {
        hide_state: 'unhidden',
        include_swipes: false,
      }) || [];

      let best = -1;

      for (const m of ms) {
        if (m?.role !== 'assistant') continue;
        if (m?.is_hidden) continue;

        if (ssIsAutoSummaryFloorMessage(m.message || '')) {
          best = Math.max(best, Number(m.message_id) || -1);
        }
      }

      return best;
    } catch (e) {
