        // 兼容之前的 START/END 标记
        const s = msg.indexOf(CONFIG.SUMMARY_FLOOR_START);
        const e = msg.indexOf(CONFIG.SUMMARY_FLOOR_END, s);
        if (s !== -1 && e !== -1) {
