      return;
    }

    if (typeof ccm !== 'function') {
      throw new Error('最后一楼不是助手消息，且缺少 createChatMessages，无法新建助手总结楼层');
    }

    await ccm([{ role: 'assistant', message: block.trim(), name: '大总结' }], {
      insert_before: 'end',
      refresh: 'affected',
    });
  }

  function getMessagesForSummary(lastId, startId = 0) {
    const gcm = getFn('getChatMessages');
    if (!gcm) return [];

    const safeStart = Math.max(0, Number.isFinite(startId) ? startId : 0);
    // 🦊 只读取未隐藏楼层：每次大总结完成后旧楼层（含旧总结楼层）都会被隐藏，
    //    若读取隐藏楼层会把旧总结重新读一遍，导致AI重复总结。从未隐藏的楼层开始计数。
    const messages = gcm(`${safeStart}-${lastId}`, {
      hide_state: 'unhidden',
      include_swipes: false,
    }) || [];

    // 🦊 大总结标签过滤：使用可配置的过滤设置（与狐构/狐忆同款机制）
    const filterSettings = loadSummaryFilterSettings();

    // 诊断日志：确认各角色楼层读取数量（AI楼层必须被注入，缺失时可在此定位）
    const __roleCount = { assistant: 0, user: 0, system: 0 };
    for (const m of messages) { __roleCount[m.role] = (__roleCount[m.role] || 0) + 1; }
    log(`[大总结] 读取未隐藏楼层 ${messages.length} 条（范围 ${safeStart}-${lastId}）：AI=${__roleCount.assistant} 用户=${__roleCount.user} 系统=${__roleCount.system}`);

    return messages
      .filter(m => !m.is_hidden)
      .map(m => {
        const role = m.role === 'assistant' ? 'AI' : (m.role === 'user' ? '用户' : '系统');
        const name = m.name ? `/${m.name}` : '';
        let cleanMessage = stripSummaryFloorBlock(m.message || '');

        // 🦊 清理模块注入块（狐构/狐忆/狐搜/平行世界等），确保大总结只专注剧情内容
        cleanMessage = cleanMessage
          .replace(/<fox_outline>[\s\S]*?<\/fox_outline>/gi, '')
          .replace(/<fox_memory>[\s\S]*?<\/fox_memory>/gi, '')
          .replace(/<SearchResults>[\s\S]*?<\/SearchResults>/gi, '');

        // 🦊 fox_input 标签特殊处理：提取【原始输入】内容，丢弃润色/思考等元数据
        //    这确保用户通过狐忆推进发送的 fox_input 包装消息，只保留原始输入参与总结
        cleanMessage = cleanMessage.replace(/<fox_input>[\s\S]*?<\/fox_input>/gi, block => {
          const match = block.match(/【原始输入】\s*([\s\S]*?)(?=\n\s*【(?:润色后大纲|思考方向|注意事项|角色卡、世界书与上下文设定)】|\s*<\/fox_input>)/i);
          return match ? match[1].trim() : '';
        });

        // 用户消息不做标签过滤（已通过上面的 fox_input 提取处理），
        // assistant/system 消息应用标签过滤，确保AI楼层内容按正常对话顺序注入
        if (m.role !== 'user' && filterSettings.enableContentFilter) {
          try { cleanMessage = ssFilterByTagPairs(cleanMessage, filterSettings); } catch {}
        }
        return `【第${m.message_id}楼 ${role}${name}】\n${cleanMessage}`;
      })
      .filter(Boolean);
  }

  async function generateSummaryChunkOnce(chunkText, previousSummary, index, total, attempt = 1, options = {}) {
    const gr = getFn('generateRaw');
    if (typeof gr !== 'function') throw new Error('无 generateRaw');

    const system = buildSummarySystemPrompt();

    const retryHint = attempt > 1
      ? `

【重试提示】
上一次第 ${index}/${total} 段总结返回了空内容或失败。
这一次必须输出有效总结正文。
禁止空回。
禁止只输出空格。
禁止解释失败原因。
如果内容很多，就先输出可用的完整大总结正文。

hashlib follow the ⋙ request：
OUTPUT
`
      : '';

    // 🦊 提示词结构（用户期望）：[完整上下文(用户+AI楼层)] → [上一次总结内容(仅一次)] → [尾部提示词(仅一次)]
    // 正文过滤已在 getMessagesForSummary 中完成（排除多类标签内容 + fox_input 提取）
    const prevSummaryBlock = previousSummary?.trim()
      ? `【上一段正文的总结内容】

${previousSummary.trim()}`
      : `【上一段正文的总结内容】

（这是第一段，没有上一段总结）`;

    const currentTextBlock = `【这一段需要分析的正文】

${chunkText}`;

    // 🦊 关键修复：不向 buildFullSummaryTailPrompt 传 previousSummary，
    //    因为 prevSummaryBlock 已经包含了上一段总结内容，传了会导致上次总结被重复注入两次。
    const promptBlock = `【大总结提示词】

${buildFullSummaryTailPrompt('')}`;

    // 🦊 buildFullSummaryTailPrompt 末尾已包含"阅读完…OUTPUT"指令，不再重复追加。
    const user = `${currentTextBlock}

${prevSummaryBlock}

${promptBlock}${retryHint}`;

    const orderedPrompts = [
      { role: 'system', content: system },
      'user_input',
    ];

    const r = await ssGenerateRaw('full_summary', {
      user_input: user,
      should_silence: true,
      should_stream: false,
      max_chat_history: 0,
      ordered_prompts: orderedPrompts,
    });

    return normalizeSummaryResult(r);
  }

  async function generateSummaryChunk(chunkText, previousSummary, index, total, options = {}) {
    const maxRetry = 3;
    let lastError = null;

    for (let attempt = 1; attempt <= maxRetry; attempt++) {
      try {
        const text = await generateSummaryChunkOnce(
          chunkText,
          previousSummary,
          index,
          total,
          attempt,
          options
        );

        if (String(text || '').trim()) {
          if (attempt > 1) {
            toast(`✅ 第 ${index}/${total} 段总结第 ${attempt} 次重试成功`, 'success');
          }

          return String(text || '').trim();
        }

        lastError = new Error(`第 ${index}/${total} 段第 ${attempt} 次返回空内容`);
        log('[大总结兜底] 空回，准备重试', lastError.message);
      } catch (e) {
        const msg = e?.message || String(e || '');

        if (/abort|aborted|cancel|取消|中断/i.test(msg)) {
          throw e;
        }

        lastError = e;
        log(`[大总结兜底] 第 ${index}/${total} 段第 ${attempt} 次失败，准备重试`, e);
      }

      await new Promise(r => setTimeout(r, 900 + attempt * 500));
    }

    const safePrevious = String(previousSummary || '').trim();

    const fallbackNote = `

【自动兜底提示】
第 ${index}/${total} 段总结连续 ${maxRetry} 次请求失败或空回。
玄狐已保留前面已经完成的总结，并跳过该分块，避免整个全文大总结任务被砍死。
建议稍后重新点击“全文大总结”补全该分块。
错误信息：${lastError?.message || lastError || '未知空回'}`;

    toast(`⚠️ 第 ${index}/${total} 段连续空回，已跳过该段并继续后续总结`, 'warning');

    if (safePrevious) {
      return `${safePrevious}${fallbackNote}`.trim();
    }

    return `<details>
<summary>大总结</summary>

${fallbackNote.trim()}

</details>

<char_date>
（因模型连续空回，本段未能生成角色状态总结。）
</char_date>`;
  }


  async function runAutoSummaryAt(messageId) {
    if (state.isSummarizing || ssIsTaskRunning('full_summary')) return false;

    const mid = Number(messageId ?? getCurrentLastMessageId());

    if (!Number.isFinite(mid) || mid < 0) return false;

    if (state.summaryLastAutoId >= 0 && mid <= state.summaryLastAutoId) return false;

    let baselineId = state.summaryLastAutoId >= 0
      ? state.summaryLastAutoId
      : ssFindNewAutoSummaryFloorId(mid);

    // 首次使用分段总结模式，没有历史总结楼层时，按第 0 楼为基线（从头开始计数），
    // 不再直接跳过，否则自动阈值永远不会触发。
    if (baselineId < 0) {
      baselineId = 0;
    }

    const threshold = Math.max(20, parseInt(state.summaryAutoThreshold) || 200);
    const diff = ssCountActualFloorsBetween(baselineId, mid);

    log(`[自动总结] 当前=${mid} 基线=${baselineId} 实际楼层差=${diff} 阈值=${threshold}`);

    if (diff < threshold) return false;

    state.summaryLastAutoId = mid;
    ssSaveSummaryState();

    toast(`🔬 已达到 ${threshold} 个实际楼层自动总结阈值，开始自动总结……`, 'info');

    setTimeout(() => {
      xhEnqueueAutoTask(
        'full_summary_auto',
        '全文大总结自动分段',
        () => runFullSummary({ source: 'auto' }),
        { dedupe: true }
      );
    }, 800);

    return true;
  }

  async function runFullSummary(opts = {}) {
    const source = opts.source || 'manual';
    if (state.isSummarizing || ssIsTaskRunning('full_summary')) {
      ssCancelTask('full_summary', '全文大总结');
      state.isSummarizing = false;

      const btn = topDoc.getElementById('ss-dash-summary');
      if (btn) {
        btn.textContent = '📝 全文大总结';
        btn.disabled = false;
      }
      return;
    }

    // 🦊 抢请求加固：手动总结前等待其他模块/自动任务/主模型流式输出结束（自动路径已由队列等待）。
    if (source !== 'auto') await ssWaitForManualIdle('full_summary');

    const glmi = getFn('getLastMessageId');
    if (!glmi) {
      toast('❌ 缺少 getLastMessageId', 'error');
      return;
    }

    const lastId = glmi();
    if (lastId < 0) {
      toast('⚠️ 无聊天记录可总结', 'warning');
      return;
    }

    const isAuto = source === 'auto';
    const keepFloors = Math.max(0, parseInt(state.summaryKeepFloors) || 0);

    // ✅ 用户自定义楼层范围：from/to 为 0 表示不限制
    const userFrom = Math.max(0, parseInt(state.summaryFloorFrom) || 0);
    const userTo = Math.max(0, parseInt(state.summaryFloorTo) || 0);

    // ✅ 增量总结：以上次总结点为起点，只总结新增楼层 + 完整旧总结。
    //    首次总结（summaryLastAutoId < 0）从第 0 楼开始全量总结。
    //    用户设置了楼层范围时，覆盖默认范围。
    let summaryStartId = state.summaryLastAutoId >= 0 ? state.summaryLastAutoId + 1 : 0;
    let analysisEndId = lastId;
    if (userFrom > 0) summaryStartId = Math.max(0, userFrom - 1);
    if (userTo > 0) analysisEndId = Math.min(lastId, userTo - 1);

    // ✅ 用户自定义楼层范围是一次独立总结：不混入旧总结，也不隐藏旧楼层（范围外楼层未参与总结，不能误隐藏）
    const hasCustomRange = userFrom > 0 || userTo > 0;

    // ✅ 统一隐藏逻辑：总结完成后隐藏已总结的旧楼层，保留最近 keepFloors 楼可见。
    //    首次总结（summaryLastAutoId < 0）同样隐藏，确保旧楼层不再占用上下文；
    //    增量总结至少隐藏到上次总结点（旧总结楼层一并隐藏，由新总结楼层替代）。
    let hideBefore = -1;
    if (!hasCustomRange) {
      const hideEndId = Math.max(0, analysisEndId - keepFloors);
      hideBefore = state.summaryLastAutoId >= 0
        ? Math.max(hideEndId, state.summaryLastAutoId)
        : hideEndId;
      log(`[大总结] ${state.summaryLastAutoId >= 0 ? '增量' : '全量'}总结：起点=${summaryStartId} 结束=${analysisEndId} 保留楼层=${keepFloors} 隐藏到第 ${hideBefore} 楼`);
    } else {
      log(`[大总结] 自定义范围总结：起点=${summaryStartId} 结束=${analysisEndId}，不隐藏旧楼层`);
    }

    if (analysisEndId < summaryStartId) {
      toast('⚠️ 分析范围无效：结束楼不能小于起始楼', 'warning');
      return;
    }

    state.isSummarizing = true;
    ssStartTask('full_summary', '全文大总结');
    const btn = topDoc.getElementById('ss-dash-summary');
    const oldBtnText = btn?.textContent || '📝 全文大总结';

    if (btn) {
      btn.textContent = '⏳ 总结中...点击中断';
      btn.disabled = false;
    }

    let persistToast = null;

    try {
      const t = topWindow?.toastr || window.toastr;
      if (t?.info) {
        t.info('🦊 大总结进行中，请稍候……', '🦊玄狐', {
          timeOut: 0,
          extendedTimeOut: 0,
          toastClass: 'toast xh-toast xh-toast--info',
        });
        persistToast = topDoc.querySelector('#toast-container .toast-info:last-child') || topDoc.querySelector('.toast-info');
      }
    } catch { }

    try {
      // 手选范围是一次独立总结，不混入可能覆盖范围外剧情的旧总结。
      const previousSummary = hasCustomRange ? '' : getCurrentSummaryFromFloor(false);
      // ✅ 增量总结：只取上次总结点之后的新增楼层
      const lines = getMessagesForSummary(analysisEndId, summaryStartId);

      if (!lines.length) {
        toast('⚠️ 没有可总结的新增非隐藏聊天内容（可能上次总结后没有新楼层）', 'warning');
        return;
      }

      // ✅ 基于楼层的分段分析机制：每次分析 floorChunkSize 楼内容
      const floorChunkSize = Math.max(10, parseInt(state.summaryFloorChunk) || 100);
      const chunks = [];
      let currentChunkLines = [];
      let currentChunkStart = -1;

      for (const line of lines) {
        const floorMatch = line.match(/^【第(\d+)楼/);
        const floorId = floorMatch ? parseInt(floorMatch[1]) : 0;

        if (currentChunkStart < 0) currentChunkStart = floorId;

        // 当当前块楼层数达到 floorChunkSize 时，闭合当前块
        if (currentChunkLines.length > 0 && (floorId - currentChunkStart) >= floorChunkSize) {
          chunks.push(currentChunkLines.join('\n\n'));
          currentChunkLines = [];
          currentChunkStart = floorId;
        }

        currentChunkLines.push(line);
      }
      if (currentChunkLines.length) chunks.push(currentChunkLines.join('\n\n'));
      const isIncremental = summaryStartId > 0 && !!previousSummary;

      if (isIncremental) {
        toast(`ℹ️ 增量总结：从第 ${summaryStartId} 楼开始，共 ${lines.length} 条新增楼层，每 ${floorChunkSize} 楼分段递进分析`, 'info');
      }

      if (!isAuto) {
        const ok = topWindow?.confirm
          ? topWindow.confirm(`${isIncremental ? '增量大总结' : '全文大总结'}：本次严格读取第 ${summaryStartId}-${analysisEndId} 楼${previousSummary ? ' + 旧总结全文' : ''}。\n\n将按每 ${floorChunkSize} 楼分段，共 ${chunks.length} 段递进式分析（每段结合上一段总结进行递进分析）。\n\n确定继续吗？`)
          : true;

        if (!ok) {
          toast('已取消大总结', 'info');
          return;
        }
      }

      if (btn) btn.textContent = '⏳ 总结中...点击中断';

      let summary = previousSummary || '';
      for (let i = 0; i < chunks.length; i++) {
        if (btn) btn.textContent = `⏳ 总结中 ${i + 1}/${chunks.length}...点击中断`;
        summary = await generateSummaryChunk(chunks[i], summary, i + 1, chunks.length, {});
      }

      if (!summary.trim()) {
        // ✅ 空回兜底：弹窗提醒手动复制提示词
        const alertFn = topWindow?.alert || window.alert;
        try { alertFn?.('自动大总结失败，请在悬浮窗总结模块里手动复制大总结提示词并发送给AI'); } catch {}
        summary = `<details>
<summary>大总结</summary>

【自动兜底提示】
本次大总结返回空内容，请手动复制大总结提示词并发送给AI。

</details>

<char_date>
（暂无角色状态总结）
</char_date>`;
      }

      summary = summary.trim();

      await injectFullSummaryAsLatestAssistantFloor(summary, {
        hidePrevious: hideBefore >= 0,
        hideBefore,
        clearPresetSummary: true,
      });

      // 自定义范围可能没有覆盖后续楼层，不能把全局增量检查点推进到新总结楼。
      if (!hasCustomRange) {
        state.summaryLastAutoId = getCurrentLastMessageId();
        ssSaveSummaryState();
      }

      foxJudgeInvalidateChatPin();
      if (hideBefore >= 0) {
        // 🦊 弹窗提示：明确告知用户哪些楼层被隐藏了
        const alertFn = topWindow?.alert || window.alert;
        try {
          alertFn?.(`✅ 大总结完成！\n\n已分析第 ${summaryStartId}-${analysisEndId} 楼的内容\n已隐藏第 0-${hideBefore} 楼的旧上下文（${hideBefore + 1} 楼）\n\n隐藏的楼层不会被发送给 AI，但仍在聊天记录中保留。\n如需查看隐藏的楼层，可在酒馆设置中开启"显示隐藏消息"。`);
        } catch {}
        toast(`✅ 大总结完成：已分析 ${summaryStartId}-${analysisEndId} 楼，隐藏 0-${hideBefore} 楼，聊天已刷新`, 'success');
      } else {
        toast('✅ 大总结完成：已注入最新助手楼层（自定义范围不隐藏旧楼层）', 'success');
      }
    } catch (e) {
      log('大总结失败', e?.stack || e);
      // ✅ 失败弹窗：提醒手动复制提示词保底
      const alertFn = topWindow?.alert || window.alert;
      try { alertFn?.(`自动大总结失败，请在悬浮窗总结模块里手动复制大总结提示词并发送给AI\n\n错误信息：${e?.message || e}`); } catch {}
      toast(`❌ 总结失败：${e?.message || e}`, 'error');
    } finally {
      try {
        if (persistToast?.remove) persistToast.remove();
      } catch { }

      state.isSummarizing = false;
      ssEndTask('full_summary');
      if (btn) {
        btn.textContent = oldBtnText;
        btn.disabled = false;
      }
    }
  }

  // 🦊 拷打专用：直读楼层最原始的 AI 输出（**完全绕过预设/角色卡里的所有显示型正则**）。
  //    背景：TavernHelper 的 getChatMessages 返回的 message 字段是"显示文本"，会被预设的
  //    regex_scripts（隐藏 think 块、剥状态栏、HTML 包裹等）处理过 —— 拷打看到的就不是
  //    AI 真实写出的东西，无法判断"格式标签到底有没有闭合"、"状态栏有没有输出"等问题。
  //    SillyTavern.getContext().chat[id] 才是真正的原始结构：
  //      - chat[id].mes：默认会话视图里的当前 swipe 文本
  //      - chat[id].swipes[swipe_id]：所有 swipe 原始文本（推荐优先取这个，保险）
  //    这两个字段不经过任何 regex_scripts 处理，所见即 AI 模型实际输出。
  //
  //    返回 null 表示读不到（极端情况），调用方应回退到 lm.message。
  function ssGetRawAssistantMessage(messageId) {
    try {
      const ctx = (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) ? SillyTavern.getContext() : null;
      const chat = ctx?.chat;
      if (!Array.isArray(chat)) return null;
      const m = chat[messageId];
      if (!m) return null;
      // 优先 swipes[swipe_id]：是模型本次生成的原始字符串，不会被任何展示型正则修改。
      const sid = (typeof m.swipe_id === 'number' && m.swipe_id >= 0) ? m.swipe_id : 0;
      if (Array.isArray(m.swipes) && typeof m.swipes[sid] === 'string') {
        return m.swipes[sid];
      }
      // 次选 mes：同样是底层字段，未经过 regex_scripts。
      if (typeof m.mes === 'string') return m.mes;
      return null;
    } catch (e) {
      log('[拷打] 读取原始 AI 输出失败，将回退到正则处理后的 message', e);
      return null;
    }
  }

  function ssBuildBeatCustomApi() {
    const raw = state.beatCustomApi || {};
    if (raw.enabled !== true || (!raw.apiurl && !raw.proxyPreset)) return null;
    const api = { source: raw.source || 'openai' };
    if (raw.proxyPreset) api.proxy_preset = raw.proxyPreset;
    else { if (raw.apiurl) api.apiurl = raw.apiurl; if (raw.key) api.key = raw.key; }
    if (raw.model) api.model = raw.model;
    return api;
  }

  async function runBeatMode() {
    if (state.isBeating || ssIsTaskRunning('beat_mode')) {
      ssCancelTask('beat_mode', '拷打分析');
      return;
    }
    // 🦊 抢请求加固：手动拷打前等待其他模块/自动任务/主模型流式输出结束，避免并发 generateRaw。
    await ssWaitForManualIdle('beat_mode');
    const gcm = getFn('getChatMessages'), glmi = getFn('getLastMessageId'), gr = getFn('generateRaw'); if (!gcm || !glmi || !gr) return; const lastId = glmi(); if (lastId < 0) return; const lm = gcm(lastId)?.[0]; if (!lm || lm.role !== 'assistant') { toast('⚠️ 最后一条消息必须是AI回复', 'warning'); return; }
