  // 🆕 从最新 AI 楼层正文提取 <fox_hugou>...</fox_hugou> 标签内容（照抄狐刻 <ft_clock> 解析模式）
  //    解析到则返回大纲正文文本；解析失败返回空字符串，由调用方回退到 AI 修正
  function outlineExtractHugouFromLastMessage(messageId) {
    try {
      const gcm = getFn('getChatMessages');
      if (typeof gcm !== 'function') return '';
      // ✅ 照抄 ssRescueTaggedContent 的调用方式：gcm(messageId, { include_swipes: true })?.[0]
      const m = gcm(messageId, { include_swipes: true })?.[0];
      if (!m || typeof m !== 'object') return '';
      // ✅ 只取 AI 回复（role === 'assistant'）；用户消息直接跳过
      if (m.role !== 'assistant' && m.is_user) return '';
      // ✅ 字段名照抄其他代码：message.message（不是 content/mes）
      const swipeId = m.swipe_id ?? 0;
      const text = (Array.isArray(m.swipes) && typeof m.swipes[swipeId] === 'string')
        ? m.swipes[swipeId]
        : String(m.message || m.mes || m.content || '');
      if (!text) return '';
      // 匹配 <fox_hugou>...</fox_hugou>
      const hugouMatch = text.match(/<fox_hugou>([\s\S]*?)<\/fox_hugou>/i);
      if (!hugouMatch) return '';
      const inner = hugouMatch[1].trim();
      if (!inner) return '';
      // 清理字段标签，转换为大纲正文格式：#字段 内容 → 【字段】内容
      // 容错：把旧的 | 分隔符统一替换为 •（| 是 markdown 表格竖线，会导致渲染/解析 BUG）
      const lines = inner.split('\n').map(l => l.trim()).filter(Boolean);
      const outlineLines = [];
      for (const line of lines) {
        const normalizedLine = line.replace(/\s*\|\s*/g, ' • ');
        const fieldMatch = normalizedLine.match(/^#(.+?)\s+(.+)$/);
        if (fieldMatch) {
          outlineLines.push(`【${fieldMatch[1]}】${fieldMatch[2]}`);
        } else {
          outlineLines.push(normalizedLine);
        }
      }
      return outlineLines.join('\n');
    } catch (e) {
      log('[狐构·解析<fox_hugou>] 失败', e);
      return '';
    }
  }

