  async function ssBuildOutlineCorrectionReferencePrompts(filterSettings, memoryQuery = '', prebuiltHistory) {
    // 狐构生成与动态修正共用的唯一模块顺序：世界书 → 上下文 → 狐搜 → 狐忆 → 狐析。
    const prompts = [
      'world_info_before',
      'world_info_after',
      outlineBuildFixedContextHeader(),
      {
        role: 'system',
        content: '【固定上下文】\n以下依次为角色卡、角色性格、场景、玩家设定与聊天记录。',
      },
      'char_description',
      'char_personality',
      'scenario',
      'persona_description',
    ];
    try {
      // ✅ 性能优化：若上层已构建好过滤后的聊天记录，直接复用，避免重复读取+过滤。
      const history = Array.isArray(prebuiltHistory)
        ? prebuiltHistory
        : ssBuildFilteredChatHistoryPromptsForAnalysis(filterSettings);
      const maxChars = 48000;
      const maxPrompts = 80;
      const kept = [];
      let usedChars = 0;
      for (let i = history.length - 1; i >= 0 && kept.length < maxPrompts; i--) {
        const content = String(history[i]?.content || '');
        if (!content) continue;
        const remaining = maxChars - usedChars;
        if (remaining <= 0) break;
        kept.push(content.length <= remaining ? history[i] : { ...history[i], content: content.slice(-remaining) });
        usedChars += Math.min(content.length, remaining);
      }
      prompts.push(...kept.reverse());
      if (kept.length < history.length) {
        log(`[狐构] 上下文安全限制生效：${history.length} 楼裁为最新 ${kept.length} 楼 / ${usedChars} 字符`);
      }
    } catch (e) {
      log('[狐构] 上下文聊天记录读取失败，保留其余上下文继续生成', e);
    }

    const husouText = ssGetHusouCrossModuleSupplementText().slice(-8000);
    if (husouText) {
      prompts.push({
        role: 'system',
        content: `【狐搜参考】\n以下资料用于补足外部设定与名词；若与角色卡、世界书或聊天记录冲突，以前述上下文为准。\n\n${husouText}`,
      });
    }
    const queryText = String(memoryQuery || '').trim();

    if (queryText) {
      try {
        await foxMemoryPrepareVectorSnapshot(queryText, { profile: 'mainline' });
      } catch (e) {
        log('[狐构] 狐忆向量参考准备失败，继续使用本地召回', e);
      }

      try {
        const memoryBody = foxMemoryBuildMemoryBodyForInject(foxMemoryGetCurrent(), {
          queryText,
          intentText: queryText,
          profile: 'mainline',
          charBudget: 8000,
          maxAtoms: 16,
          maxPlotChunks: 6,
          keywordFilterByContext: true,
        });

        if (memoryBody) {
          prompts.push({
            role: 'system',
            content: `【狐忆召回参考】\n以下是与当前剧情和修正要求相关的长期记忆，仅用于校准大纲，若与最新聊天冲突，以最新聊天为准。\n\n${memoryBody}`,
          });
        }
      } catch (e) {
        log('[狐构] 狐忆参考构建失败，跳过记忆参考继续生成', e);
      }
    }

    const prefsPrompt = ssBuildUserPreferenceContextPrompt();
    if (prefsPrompt?.content?.length > 8000) prefsPrompt.content = prefsPrompt.content.slice(-8000);
    prompts.push(prefsPrompt);
    return prompts;
  }

  function outlineBuildSharedMemoryQuery(filterSettings, correction = '', prebuiltHistory) {
    let chat = '';
    try {
      // ✅ 性能优化：若上层已构建好过滤后的聊天记录，直接复用，避免重复读取+过滤。
      const history = Array.isArray(prebuiltHistory)
        ? prebuiltHistory
        : ssBuildFilteredChatHistoryPromptsForAnalysis(filterSettings);
      chat = history
        .slice(-10)
        .map(item => String(item?.content || ''))
        .join('\n\n');
    } catch (e) {
      log('[狐构] 记忆检索查询读取聊天失败，使用用户补充继续构建', e);
    }
    return [chat, String(correction || '').trim()].filter(Boolean).join('\n\n').slice(-16000);
  }

  async function outlineBuildSharedRequestParams(filterSettings, correction, finalPrompt) {
    // ✅ 性能优化：聊天记录只读取+标签过滤一次，memoryQuery 与 references 共用。
    // 旧实现里 outlineBuildSharedMemoryQuery 与 ssBuildOutlineCorrectionReferencePrompts
    // 各自独立调用 ssBuildFilteredChatHistoryPromptsForAnalysis，造成一次生成/修正
    // 要把全聊天记录读两遍、过滤两遍。
    const _prebuiltHistory = ssBuildFilteredChatHistoryPromptsForAnalysis(filterSettings);
    const memoryQuery = outlineBuildSharedMemoryQuery(filterSettings, correction, _prebuiltHistory);
    const references = await ssBuildOutlineCorrectionReferencePrompts(filterSettings, memoryQuery, _prebuiltHistory);
    const orderedPrompts = [
      ...references,
      { role: 'system', content: finalPrompt },
    ];
    const estimatedChars = orderedPrompts.reduce((sum, item) => sum + (typeof item === 'string' ? 0 : String(item?.content || '').length), 0);
    if (estimatedChars > 90000) {
      throw new Error(`狐构输入仍过大（约 ${estimatedChars} 字符），请降低分析楼层或缩短当前大纲/用户偏好`);
    }
    const orderSummary = orderedPrompts.map(item => {
      if (typeof item === 'string') return item;
      const content = String(item?.content || '');
      if (content.startsWith('【狐搜参考】')) return '狐搜';
      if (content.startsWith('【狐忆召回参考】')) return '狐忆';
      if (content.startsWith('【狐析用户偏好】')) return '狐析';
      if (content.startsWith('【固定上下文】') || content.includes('【上下文开始】')) return '上下文';
      return item?.role || 'prompt';
    });
    console.info(`[狐构请求体] 顺序=${orderSummary.join(' → ')}；memoryQueryChars=${memoryQuery.length}`);
    return {
      user_input: '',
      should_silence: true,
      should_stream: false,
      max_chat_history: 0,
      ordered_prompts: orderedPrompts,
    };
  }

