            ...outlineApiConfig.customApi,
            ...(parsed.customApi || {}),
            extraBodyParamsYaml: parsed.customApi?.extraBodyParamsYaml ?? SS_DEFAULT_EXTRA_BODY_YAML,
          },
        };
      }
    } catch (e) { log('[狐构] 读取 API 配置失败', e); }
    return JSON.parse(JSON.stringify(outlineApiConfig));
  }

  function saveOutlineApiConfig() {
    try {
      localStorage.setItem(CONFIG.OUTLINE_API_CONFIG_KEY, JSON.stringify(outlineApiConfig));
      return true;
    } catch (e) { log('[狐构] 保存 API 配置失败', e); return false; }
  }

  // 构建 custom_api + extraInject，供 outlineGenerate / outlineCorrect 透传给 ssGenerateRaw。
  function outlineBuildCustomApi() {
    const cfg = outlineApiConfig;
    if (cfg.apiType !== 'custom') return { customApi: null, extraInject: null };
    const hasProxy = !!cfg.customApi.proxyPreset;
    const hasDirect = !!(cfg.customApi.apiurl || cfg.customApi.key);
    if (!hasProxy && !hasDirect) return { customApi: null, extraInject: null };

    const customApi = {};
    if (hasProxy) {
      customApi.proxy_preset = cfg.customApi.proxyPreset;
    } else {
      if (cfg.customApi.apiurl) customApi.apiurl = cfg.customApi.apiurl;
      if (cfg.customApi.key) customApi.key = cfg.customApi.key;
    }
    if (cfg.customApi.model) customApi.model = cfg.customApi.model;

    const numFields = [
      ['temperature', parseFloat],
      ['max_tokens', parseInt],
      ['top_p', parseFloat],
      ['frequency_penalty', parseFloat],
      ['presence_penalty', parseFloat],
    ];
    for (const [k, parse] of numFields) {
      const v = cfg.customApi[k];
      if (v !== '' && v != null && !isNaN(parse(v))) customApi[k] = parse(v);
    }

    const extraInject = ssBuildExtraInjectFromCustomApi(cfg.customApi || {});
    return { customApi, extraInject };
  }

