      const text = typeof r === 'string' ? r : (r?.content || '');
      if (!text.trim()) { toast('❌ 生成结果为空', 'error'); return; }
      const cards = [];
      let outlineParseSource = '#行式完整匹配';
      // 1) #行式格式解析：# 大纲方案开始 ... # 大纲方案结束
      const re = /#\s*大纲方案开始\s*\n([\s\S]*?)#\s*大纲方案结束/gi;
      let m;
      while ((m = re.exec(text)) !== null) {
        const blockText = m[1].trim();
        // 提取标题：# 标题\n下一行
        const titleMatch = blockText.match(/#\s*标题\s*\n(.+)/i);
        let title = titleMatch ? titleMatch[1].trim() : '';
        // 提取内容：# 内容\n之后的所有文本
        const contentMatch = blockText.match(/#\s*内容\s*\n([\s\S]*)/i);
