  // 🦊 候选大纲持久化：生成后存 localStorage，退出悬浮窗再进仍可恢复，避免"没选就退出导致丢失"
  function outlineSaveCandidates(cards, rawText) {
    try {
      localStorage.setItem(CONFIG.OUTLINE_CANDIDATES_KEY, JSON.stringify({
        cards: (cards || []).map(c => ({ title: String(c.title || ''), content: String(c.content || '') })),
        rawText: String(rawText || ''),
        savedAt: Date.now(),
      }));
    } catch (e) { log('[狐构] 候选大纲保存失败', e); }
  }
  function outlineLoadCandidates() {
    try {
      const raw = localStorage.getItem(CONFIG.OUTLINE_CANDIDATES_KEY);
      if (!raw) return null;
      const data = JSON.parse(raw);
      if (!data || !Array.isArray(data.cards) || !data.cards.length) return null;
      return data;
    } catch { return null; }
  }
  function outlineClearCandidates() {
    try { localStorage.removeItem(CONFIG.OUTLINE_CANDIDATES_KEY); } catch {}
  }
  // 删除单个候选（按索引），更新存储并重渲染
  function outlineDeleteCandidate(index) {
    const data = outlineLoadCandidates();
    if (!data || !Array.isArray(data.cards)) return;
    const next = data.cards.filter((_, i) => i !== index);
    if (next.length === 0) {
      outlineClearCandidates();
      const container = topDoc.getElementById('ss-outline-candidates');
      if (container) container.innerHTML = '';
      state.outlineSelectedCard = -1;
      try { toast('🗑️ 已删除最后一个待选大纲，待选已清空', 'success'); } catch {}
      return;
    }
    outlineSaveCandidates(next, data.rawText);
    renderOutlineCandidates(next, data.rawText);
    try { toast(`🗑️ 已删除待选大纲，剩余 ${next.length} 个`, 'success'); } catch {}
  }

