          <span class="outline-card-del-btn" data-del="${i}" title="删除该待选大纲">🗑️</span>
        </div>
        <div class="outline-card-preview">${escapeHtml(preview)}${content.length > 90 ? '…' : ''}</div>
        <div class="outline-card-body">${escapeHtml(content)}</div>
      `;

      // 🦊 删除该待选大纲按钮
      const delBtn = el.querySelector('.outline-card-del-btn');
      if (delBtn) {
        delBtn.addEventListener('click', (ev) => {
          ev.preventDefault();
          ev.stopPropagation();
          const ok = topWindow?.confirm ? topWindow.confirm(`确定删除待选大纲「${card.title}」吗？`) : confirm(`确定删除待选大纲「${card.title}」吗？`);
          if (!ok) return;
          outlineDeleteCandidate(i);
        });
      }

      // ✅ “查看完整内容”按钮：默认折叠，点击展开（带剧透确认），再点收起。
      const revealBtn = el.querySelector('.outline-card-reveal-btn');
      if (revealBtn) {
        revealBtn.addEventListener('click', (ev) => {
          ev.preventDefault();
          ev.stopPropagation();

          if (el.classList.contains('revealed')) {
            el.classList.remove('revealed');
            revealBtn.textContent = '👁 查看完整内容';
            return;
          }

          const ok = state.outlineNoSpoilerWarning || (topWindow?.confirm
            ? topWindow.confirm('⚠️ 剧透警告！确定要查看大纲内容吗？')
            : confirm('⚠️ 剧透警告！确定要查看大纲内容吗？'));

          if (!ok) return;

          el.classList.add('revealed');
          revealBtn.textContent = '🔼 收起';
        });
      }

      // ✅ 点击卡片本体（标题/预览区）= 直接注入，不展开全文、不弹剧透警告。
      el.addEventListener('click', async (e) => {
        if (e.target.closest('.outline-card-reveal-btn')) return;

        if (state.outlineSelectedCard === i) {
          toast(`✅ 「${card.title}」已经是当前注入大纲`, 'info');
          return;
        }

        state.outlineSelectedCard = i;

        await outlineSetRawAndInject(content);

        container.querySelectorAll('.outline-card').forEach(c => c.classList.remove('selected'));
        el.classList.add('selected');

        updateOutlineManagement();

        // 从选择大纲这一楼开始重新计数，避免刚选完立刻自动修正。
        state.outlineLastAnalyzedId = getCurrentLastMessageId();
        localStorage.setItem(outlineGetLastAnalyzedKey(), String(state.outlineLastAnalyzedId));

        toast(`✅ 已注入「${card.title}」`, 'success');
      });

      container.appendChild(el);
    });
  }

  function updateOutlineManagement() {
    const ta = topDoc.getElementById('ss-outline-edit-textarea');
    if (!ta) return;
    ta.value = state.outlineText || '';
    const mask = topDoc.getElementById('ss-outline-mgmt-mask');
    const btns = topDoc.getElementById('ss-outline-edit-btns');
    if (state.outlineNoSpoilerWarning) {
      if (mask) mask.style.display = 'none';
      ta.style.display = 'block';
      if (btns) { btns.style.display = 'flex'; btns.style.flexWrap = 'wrap'; }
    } else {
      if (mask) mask.style.display = ta.value ? 'flex' : 'none';
      ta.style.display = 'none';
      if (btns) btns.style.display = 'none';
    }
  }

