      style.id = 'ss-outline-card-styles';
      style.textContent = `
.outline-card{border:1px solid rgba(232,120,74,0.18);border-radius:10px;background:rgba(232,120,74,0.03);padding:10px 12px;cursor:pointer;transition:border-color .18s ease,background .18s ease;margin:0;}
