.outline-card-title{font-weight:600;color:#f0a070;font-size:13px;flex:1 1 auto;min-width:0;word-break:break-word;}
.outline-card-meta{font-size:11px;color:#706058;white-space:nowrap;}
.outline-card-reveal-btn{font-size:11px;color:#f0a070;white-space:nowrap;padding:3px 9px;border:1px solid rgba(232,120,74,0.28);border-radius:6px;cursor:pointer;user-select:none;flex-shrink:0;transition:background .15s ease;}
.outline-card-reveal-btn:hover{background:rgba(232,120,74,0.14);}
.outline-card-del-btn{font-size:13px;color:#d08080;white-space:nowrap;padding:3px 7px;border:1px solid rgba(139,0,0,0.3);border-radius:6px;cursor:pointer;user-select:none;flex-shrink:0;transition:background .15s ease;line-height:1;}
.outline-card-del-btn:hover{background:rgba(139,0,0,0.18);}
.outline-card-preview{font-size:11px;color:#90756a;margin-top:6px;line-height:1.5;overflow:hidden;}
.outline-card-body{display:none;margin-top:8px;padding:10px;background:rgba(0,0,0,0.16);border-radius:8px;font-size:12px;color:#bfd7e5;line-height:1.65;white-space:pre-wrap;word-break:break-word;max-height:60vh;overflow-y:auto;}
