  .outline-card-header{gap:6px;}
  .outline-card-reveal-btn{padding:3px 7px;}
}
`;
      topDoc.head.appendChild(style);
    }
    topDoc.body.appendChild(overlay);
    topDoc.body.appendChild(panel);
    // 🦊 挂载狐构提示词自定义编辑器到配置页
    try {
      const olCfgPane = panel.querySelector('[data-olpane="cfg"]');
      if (olCfgPane) {
        // 先触发一次构建以注册默认值
        if (typeof ssBuildOutlineInject === 'function') ssBuildOutlineInject('__placeholder__');
        if (typeof ssBuildOutlineLinkedSupplementPrompt === 'function') ssBuildOutlineLinkedSupplementPrompt();
        xhMountPromptEditor(olCfgPane, 'fox_outline', '狐构注入');
        xhMountPromptEditor(olCfgPane, 'outline_linked_supplement', '狐构跨模块补充');
        xhMountPromptEditor(olCfgPane, 'outline_cross_supplement', '狐构大纲跨模块补充');
      }
    } catch (e) { log('[狐构] 挂载提示词编辑器失败', e); }
    // 🦊 恢复持久化的待选大纲：退出悬浮窗再进仍可看到上次生成的候选，避免"没选就退出导致丢失"
    try {
      const saved = outlineLoadCandidates();
      if (saved && saved.cards && saved.cards.length) {
        renderOutlineCandidates(saved.cards, saved.rawText || '');
        log(`[狐构] 已恢复 ${saved.cards.length} 个待选大纲`);
      }
    } catch (e) { log('[狐构] 恢复待选大纲失败', e); }
    xhGuideEnhancePanel(panel, 'outline', '狐构');
    // ✅ 自动保存：除了大纲正文输入框（避免半改时被覆盖），其它设置项一改就触发底部保存。
    //    标签过滤行（不被 outline-save-bottom-btn 处理）单独路由到 outline-filter-save。
    ssAttachAutoSave(panel, {
      excludeSelectors: ['#ss-outline-edit-textarea'],
      resolveSaveBtns: (target) => {
        if (target?.closest?.('.outline-inc-tag-module, .outline-exc-tag-module, .outline-inc-tag-row, .outline-exc-tag-row')) {
          return ['outline-filter-save'];
        }
        return ['outline-save-bottom-btn'];
      },
    });

    // ✅ 一键恢复狐构本面板默认（仅清"配置"，不动已保存的大纲内容）
