          outlineApiConfig.customApi.extraBodyParamsYaml = __extra.extraBodyParamsYaml;
          outlineApiConfig.customApi.excludeBodyParamsYaml = __extra.excludeBodyParamsYaml;
          outlineApiConfig.customApi.extraHeadersYaml = __extra.extraHeadersYaml;
          saveOutlineApiConfig();
        }

        toast('✅ 狐构设置已保存，不需要打开剧透管理面板', 'success');
      } catch (e) {
        toast(`❌ 保存失败：${e.message || e}`, 'error');
      }
    };
