  function onOutlineAutoAnalysis(mid) {
    try {
      if (!state.outlineAutoAnalysis) return;
      if (state.outlineIsCorrecting || state.outlineIsGenerating) return;

      const current = outlineLoadCurrentText().trim();
      if (!current) return;

      const interval = Math.max(1, parseInt(state.outlineAutoInterval) || 30);
      const currentId = Number(mid ?? getCurrentLastMessageId());

      if (!Number.isFinite(currentId) || currentId < 0) return;

      // ✅ 统一使用角色卡隔离的 key，避免旧版写到 SPreset_OutlineLastAnalyzedId 后读不到。
      const key = outlineGetLastAnalyzedKey();

      let lastId = Number(state.outlineLastAnalyzedId);

      if (!Number.isFinite(lastId) || lastId < 0) {
        const savedLast = parseInt(localStorage.getItem(key) || '-1');

        if (Number.isFinite(savedLast) && savedLast >= 0) {
          lastId = savedLast;
          state.outlineLastAnalyzedId = savedLast;
        } else {
          // 第一次开启时，以当前楼为起点，不立刻修正。
          state.outlineLastAnalyzedId = currentId;
          localStorage.setItem(key, String(currentId));
          log(`[狐构自动修正] 初始化计数点：第 ${currentId} 楼，间隔 ${interval}`);
          return;
        }
      }

      // ✅ 自动修正间隔按实际楼层计数。
      const diff = outlineCountActualFloorsBetween(lastId, currentId);

      // 📊 楼层推进诊断日志：打印本楼被认为是主AI回复的楼层内容及前300字
      //    用于排查"隔N楼修正"是否计算到了正确的楼层
      let __olPreview = '';
      try {
        const __gcm = getFn('getChatMessages');
        if (__gcm) {
          const __m = __gcm(currentId, { hide_state: 'all', include_swipes: true })?.[0];
          if (__m) {
            const { text } = xhGetAssistantMessageText(__m);
            __olPreview = text.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim().slice(0, 300);
          }
        }
      } catch (e) { log('[狐构·楼层推进] 日志打印失败', e); }
      log(`[狐构·楼层推进] 检测到主AI回复楼层 message_id=${currentId}，计数=${diff}/${interval}，内容前300字：${__olPreview}`);

      if (diff < interval) return;

      // ✅ 达到间隔后先记录，防止连续触发。
      state.outlineLastAnalyzedId = currentId;
      localStorage.setItem(key, String(currentId));

      // 🆕 优先尝试从最新 AI 楼层正文解析 <fox_hugou> 标签（照抄狐刻 <ft_clock> 解析模式）
      //    若解析到，直接更新大纲本地存储，跳过 AI 修正（节省 API 调用 + 零幻觉）
      try {
        const hugouText = outlineExtractHugouFromLastMessage(currentId);
        if (hugouText) {
          log('[狐构自动修正] 检测到 <fox_hugou> 标签，直接解析更新大纲（跳过 AI 修正）');
          xhEnqueueAutoTask(
            'outline_auto_correct',
            '狐构自动解析<fox_hugou>',
            async () => {
              await outlineSetRawAndInject(hugouText);
              updateOutlineManagement();
              toast('📋 狐构已从正文 <fox_hugou> 标签自动解析更新大纲', 'success');
            },
            { dedupe: true }
          );
          return;
        }
      } catch (e) { log('[狐构自动修正] <fox_hugou> 解析失败，回退到 AI 修正', e); }

      if (!state.outlineBackgroundSilent) toast(`🔬 狐构达到 ${interval} 楼间隔，开始自动动态修正大纲……`, 'info');

      setTimeout(() => {
        xhEnqueueAutoTask(
          'outline_auto_correct',
          '狐构自动动态修正',
          () => outlineCorrect({ automatic: true }),
          { dedupe: true }
        );
      }, 800);
    } catch (e) {
      log('[狐构自动修正] 检查失败', e);
    }
  }

  function registerOutlineAutoListener() {
    unregisterOutlineAutoListener();

    const eo = getFn('eventOn');
    const te = getFn('tavern_events') || tavern_events;

    if (typeof eo !== 'function' || !te?.GENERATION_ENDED) {
      log('[狐构自动修正] 注册失败：缺少 eventOn 或 GENERATION_ENDED');
      return;
    }

    outlineAutoHandle = eo(te.GENERATION_ENDED, (messageId) => {
      // 🦊 跳过脚本自身跑的内部生成（狐忆/狐搜/狐裁/平行世界等），
      //    否则每次内部 generateRaw 结束都会触发一次计数，干扰实际楼层间隔。
      if (xhCurrentGenerationIsInternal || xhInternalGenerationDepth > 0) return;
      // AI 回复结束后再检查，给酒馆一点时间写入最后楼层。
      setTimeout(() => {
        onOutlineAutoAnalysis(messageId);
      }, 1800);
    });

    log('[狐构自动修正] 已注册独立 GENERATION_ENDED 监听');
  }

