  function foxMemoryNormalizeExtractionSettings(config = foxMemoryConfig) {
    const detail = ['high', 'medium', 'low'].includes(config?.extractionDetailLevel)
      ? config.extractionDetailLevel
      : 'medium';

    let minWords = parseInt(config?.extractionMinWords);
    let maxWords = parseInt(config?.extractionMaxWords);

    if (!Number.isFinite(minWords)) minWords = 50;
    if (!Number.isFinite(maxWords)) maxWords = 300;

    minWords = Math.max(1, minWords);
    maxWords = Math.max(minWords, maxWords);

    return { detail, minWords, maxWords, preset: FOX_MEMORY_EXTRACTION_DETAIL_PRESETS[detail] };
  }

  function foxMemoryBuildExtractionControlPrompt(config = foxMemoryConfig) {
    const { detail, minWords, maxWords, preset } = foxMemoryNormalizeExtractionSettings(config);
    const dims = preset.characterDimensions.map(x => `   - ${x}`).join('\n');
    const checks = preset.selfCheck.map((x, i) => `${i + 1}. ${x}`).join('\n');

    return `【狐忆提取详细程度控制】
当前详细程度：${preset.label}
单条普通记忆字数范围：${minWords}-${maxWords}字。

总原则：
- 详细程度越高，允许提取的记忆维度和细分维度越多；详细程度越低，只保留最核心、最能影响后续剧情的信息。
- 字数限制主要约束人物、物品、场景、概念、设定等普通记忆的【内容】字段；剧情摘要分块按下方板块规则控制。
- 如果信息不足，宁可写短，不要编造补齐。

剧情摘要控制：
- ${preset.plotRule}
- ${preset.plotWords}

人物记忆控制：
- ${preset.characterIntro}
- 人物维度使用以下范围：
${dims}
- ${preset.adaptive}

物品/场景/概念/设定控制：
- ${preset.extraScope}
- ${preset.contentRule}

输出自检重点：
${checks}`;
  }
  // ==================== 狐忆剧情摘要分块工具 ====================
  const FOX_MEMORY_PLOT_CHUNK_SIZE = 10;
  const FOX_MEMORY_PLOT_CHUNK_PREFIX = 'plot_chunk_';
  const FOX_MEMORY_ATOM_PREFIX = 'plot_atom_';
  const FOX_MEMORY_ATOM_DEFAULT_BUDGET = 999999;

  function foxMemoryV2Log(stage, message, detail = null) {
    const prefix = `[狐忆V2][${stage}]`;
    if (detail === null || detail === undefined) log(prefix, message);
    else log(prefix, message, detail);
  }

  function foxMemoryNormalizeList(value) {
    const source = Array.isArray(value) ? value : String(value || '').split(/[,，、;；\n\r\t]+/);
    return [...new Set(source.map(x => String(x || '').trim()).filter(Boolean))];
  }

  function foxMemoryNormalizeAtomText(value) {
    return String(value || '')
      .replace(/^[-*•\d.、)）\s]+/, '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  // ==================== 🧠 狐忆显著性：强化 / 衰减 / 再激活 ====================
  function foxMemoryNormalizeSalience(raw, fallbackFloor = 0, fallbackStrength = 0.55) {
    const toOptionalNumber = value => value === null || value === undefined || value === '' ? NaN : Number(value);
    const strengthRaw = toOptionalNumber(raw?.strength);
    const countRaw = toOptionalNumber(raw?.mentionCount);
    const mentionFloorRaw = toOptionalNumber(raw?.lastMentionFloor);
    const decayFloorRaw = toOptionalNumber(raw?.lastDecayFloor);
    const floor = Math.max(0, Math.floor(Number(fallbackFloor) || 0));
    return {
      strength: Math.max(0.05, Math.min(1, Number.isFinite(strengthRaw) ? strengthRaw : fallbackStrength)),
      mentionCount: Math.max(1, Math.floor(Number.isFinite(countRaw) ? countRaw : 1)),
      lastMentionFloor: Math.max(0, Math.floor(Number.isFinite(mentionFloorRaw) ? mentionFloorRaw : floor)),
      lastDecayFloor: Math.max(0, Math.floor(Number.isFinite(decayFloorRaw) ? decayFloorRaw : floor)),
      pinned: raw?.pinned === true,
    };
  }

  function foxMemoryNormalizeStoredMemory(raw) {
    if (!raw || typeof raw !== 'object') return null;
    const title = String(raw.title || '').trim();
    const content = String(raw.content || '').trim();
    if (!title || !content) return null;
    const fallbackFloor = Math.max(0, Number(raw.floorEnd) || Number(String(raw.eventTime || '').match(/第?\s*(\d+)\s*楼/)?.[1]) || 0);
    return {
      ...raw,
      id: String(raw.id || `mem_${foxMemoryHashText(`${raw.category || 'concept'}|${title}|${content}`)}`),
      category: String(raw.category || 'concept'),
      title: title.slice(0, 160),
      content,
      keywords: foxMemoryNormalizeList(raw.keywords),
      eventTime: String(raw.eventTime || ''),
      ...foxMemoryNormalizeSalience(raw, fallbackFloor, 0.55),
    };
  }

  function foxMemoryDecaySalience(item, currentFloor) {
    const salience = foxMemoryNormalizeSalience(item, item?.floorEnd || item?.updatedAtFloor || 0, 0.55);
    Object.assign(item, salience);
    const floor = Math.max(0, Math.floor(Number(currentFloor) || 0));
    const delta = Math.max(0, floor - salience.lastDecayFloor);
    if (!item.pinned && delta > 0) item.strength = Math.max(0.05, item.strength * Math.pow(0.997, delta));
    item.lastDecayFloor = Math.max(salience.lastDecayFloor, floor);
    return item;
  }

  function foxMemoryBoostSalience(item, currentFloor, amount = 0.16) {
    foxMemoryDecaySalience(item, currentFloor);
    item.strength = Math.min(1, item.strength + Math.max(0, amount) * (1 - item.strength));
    item.mentionCount = Math.max(1, Number(item.mentionCount) || 1) + 1;
    item.lastMentionFloor = Math.max(0, Math.floor(Number(currentFloor) || 0));
    item.lastDecayFloor = item.lastMentionFloor;
    return item;
  }

  function foxMemoryApplySalienceCycle(data, observed = {}, currentFloor = 0) {
    const groups = [
      ['memories', observed.memories || new Set(), observed.newMemories || new Set()],
      ['plotAtoms', observed.atoms || new Set(), observed.newAtoms || new Set()],
      ['currentStates', observed.states || new Set(), observed.newStates || new Set()],
    ];
    for (const [key, seen, fresh] of groups) {
      for (const item of Array.isArray(data?.[key]) ? data[key] : []) {
        foxMemoryDecaySalience(item, currentFloor);
        const id = String(item.id || item.key || '');
        if (!seen.has(id)) continue;
        if (fresh.has(id)) {
          item.lastMentionFloor = Math.max(0, Number(currentFloor) || 0);
          item.lastDecayFloor = item.lastMentionFloor;
          item.mentionCount = Math.max(1, Number(item.mentionCount) || 1);
        } else {
          // 同一分析终点重复运行（手动重试/协议重建）不算剧情再次提及。
          if (Number(item.lastMentionFloor || 0) < Number(currentFloor || 0)) foxMemoryBoostSalience(item, currentFloor);
        }
      }
    }
  }

  function foxMemoryScheduleRecallReactivation(ids = {}, queryText = '') {
    const atomIds = [...new Set(ids.atoms || [])];
    const stateIds = [...new Set(ids.states || [])];
    const memoryIds = [...new Set(ids.memories || [])];
    if (!atomIds.length && !stateIds.length && !memoryIds.length) return;
    const signature = foxMemoryHashText(`${getFoxMemoryScopeId()}|${String(queryText || '')}|${atomIds.join(',')}|${stateIds.join(',')}|${memoryIds.join(',')}`);
    const now = Date.now();
    if (state.__foxMemoryReactivateSig === signature && now - (state.__foxMemoryReactivateAt || 0) < 5000) return;
    state.__foxMemoryReactivateSig = signature;
    state.__foxMemoryReactivateAt = now;
    setTimeout(() => {
      try {
        // 仅在主生成或内部 API 任务真实运行时提交再激活；单纯预览/重建提示词不加权。
        if (state.isGenerating !== true && !(ssActiveTasks instanceof Map && ssActiveTasks.size > 0)) return;
        const data = loadFoxMemory();
        const floor = foxMemoryDisplayFloorFromMessageId(getCurrentLastMessageId());
        const boost = (list, selectedIds) => {
          const selected = new Set(selectedIds);
          for (const item of Array.isArray(list) ? list : []) if (selected.has(String(item.id || item.key))) foxMemoryBoostSalience(item, floor, 0.08);
        };
        boost(data.plotAtoms, atomIds);
        boost(data.currentStates, stateIds);
        boost(data.memories, memoryIds);
        saveFoxMemory(data);
        foxMemoryV2Log('召回再激活', `atoms=${atomIds.length} states=${stateIds.length} memories=${memoryIds.length} floor=${floor}`);
      } catch (e) { foxMemoryV2Log('召回再激活失败', e?.message || e); }
    }, 0);
  }

  function foxMemoryExtractLocalMetadata(text) {
    const raw = String(text || '');
    const data = loadFoxMemory();
    const entities = [];
    const locations = [];
    for (const mem of data.memories || []) {
      const title = String(mem.title || '').trim();
      if (title && title.length >= 2 && raw.includes(title)) entities.push(title.replace(/（.*?）/g, '').trim());
      for (const keyword of mem.keywords || []) {
        const value = String(keyword || '').trim();
        if (value.length >= 2 && raw.includes(value) && /地点|场景|医院|出租屋|仓库|病房|通道|区域|城市/.test(`${mem.category}${mem.title}`)) locations.push(value);
      }
    }
    for (const snapshot of Object.values(data.characterSnapshots || {})) {
      const name = String(snapshot?.name || '').trim();
      if (name && raw.includes(name)) entities.push(name);
      for (const part of [snapshot?.location?.city, snapshot?.location?.area, snapshot?.location?.building, snapshot?.location?.interior]) if (part && raw.includes(part)) locations.push(part);
    }
    return { entities: [...new Set(entities)], locations: [...new Set(locations)] };
  }

  function foxMemoryNormalizeSummaryLines(value) {
    const raw = String(value || '').replace(/\r\n?/g, '\n').trim();
    if (!raw) return '';
    const lines = raw
      .split(/\n+|(?<=[。！？!?；;])\s*/)
      .map(foxMemoryNormalizeAtomText)
      .filter(Boolean);
    return [...new Set(lines)].join('\n');
  }

  function foxMemoryAtomFingerprint(atom) {
    return foxMemoryNormalizeAtomText(atom?.text || atom?.content || '')
      .toLowerCase()
      .replace(/[\s，。！？；：、,.!?;:'"“”‘’（）()《》【】\[\]]+/g, '');
  }

  function foxMemoryIsPlotAtom(atom) {
    return !!foxMemoryNormalizeStoredAtom(atom);
  }

  function foxMemoryNormalizeStoredAtom(atom) {
    if (!atom || (atom.kind !== 'plot_atom' && !String(atom.id || '').startsWith(FOX_MEMORY_ATOM_PREFIX))) return null;
    const text = foxMemoryNormalizeAtomText(atom.text || atom.content);
    const floorStart = Number(atom.floorStart);
    const floorEnd = Number(atom.floorEnd);
    if (!text || text.length < 12 || text.length > 320) return null;
    if (!Number.isInteger(floorStart) || !Number.isInteger(floorEnd) || floorStart < 0 || floorEnd < floorStart) return null;
    const importanceRaw = Number(atom.importance);
    const salience = foxMemoryNormalizeSalience(atom, floorEnd, 0.45 + 0.3 * (Number.isFinite(importanceRaw) ? Math.max(0, Math.min(1, importanceRaw)) : 0.5));
    return {
      ...atom,
      id: String(atom.id || `${FOX_MEMORY_ATOM_PREFIX}${floorStart}_${floorEnd}_${foxMemoryHashText(foxMemoryAtomFingerprint({ text }))}`),
      kind: 'plot_atom',
      text,
      type: String(atom.type || '事件').trim() || '事件',
      entities: foxMemoryNormalizeList(atom.entities || []),
      locations: foxMemoryNormalizeList(atom.locations || []),
      keywords: foxMemoryNormalizeList(atom.keywords || []),
      importance: Number.isFinite(importanceRaw) ? Math.max(0, Math.min(1, importanceRaw)) : 0.5,
      validity: ['active', 'inactive', 'uncertain'].includes(atom.validity) ? atom.validity : 'active',
      permanence: ['permanent', 'temporary', 'episodic'].includes(atom.permanence) ? atom.permanence : 'episodic',
      unresolved: atom.unresolved === true,
      floorStart,
      floorEnd,
      sourceChunkId: String(atom.sourceChunkId || `${FOX_MEMORY_PLOT_CHUNK_PREFIX}${floorStart}_${floorEnd}`),
      eventTime: String(atom.eventTime || `第${floorStart}-${floorEnd}楼`),
      // 🕰️ 狐刻联动：追加剧情时间戳（从快照查 floorEnd 对应的时钟）
      plotTime: (() => {
        try {
          if (typeof ftGetClockForFloor === 'function') {
            const clock = ftGetClockForFloor(floorEnd);
            if (clock && !clock.unknown) return { abs: ftClockAbs(clock), label: ftClockLabel(clock) };
          }
        } catch { }
        return atom.plotTime || null;
      })(),
      ...salience,
    };
  }

  function foxMemoryNormalizeCurrentState(item) {
    if (!item) return null;
    const subject = String(item.subject || '').trim();
    const field = String(item.field || '').trim();
    const value = String(item.value || '').trim();
    if (!subject || !field || !value || subject.length > 80 || field.length > 80 || value.length > 300) return null;
    const key = `${subject.toLowerCase()}::${field.toLowerCase()}`;
    const importanceRaw = Number(item.importance);
    const floorStartRaw = Number(item.floorStart);
    const floorEndRaw = Number(item.floorEnd);
    if (!Number.isInteger(floorStartRaw) || !Number.isInteger(floorEndRaw) || floorStartRaw < 0 || floorEndRaw < floorStartRaw) return null;
    return {
      ...item,
      id: String(item.id || `state_${foxMemoryHashText(key)}`),
      key,
      subject,
      field,
      value,
      status: item.status === 'inactive' ? 'inactive' : 'active',
      importance: Number.isFinite(importanceRaw) ? Math.max(0, Math.min(1, importanceRaw)) : 0.7,
      floorStart: floorStartRaw,
      floorEnd: floorEndRaw,
      history: (Array.isArray(item.history) ? item.history : []).map(entry => ({
        value: String(entry?.value || ''),
        floorStart: Math.max(0, Number(entry?.floorStart) || 0),
        floorEnd: Math.max(0, Number(entry?.floorEnd) || 0),
        invalidatedAt: String(entry?.invalidatedAt || ''),
      })).filter(entry => entry.value),
      ...foxMemoryNormalizeSalience(item, floorEndRaw, 0.65),
    };
  }

  function foxMemoryEmptyCharacterSnapshot(name = '') {
    return {
      id: `snapshot_${foxMemoryHashText(String(name).trim().toLowerCase())}`,
      name: String(name || '').trim(),
      profile: { age: '', gender: '', identity: '', personality: '' },
      location: { city: '', area: '', building: '', interior: '', posture: '' },
      nearbyCharacters: [],
      physiology: { health: '', fatigue: '', cleanliness: '', pain: '', hunger: '', thirst: '', consciousness: '', mobility: '' },
      appearance: { outerwear: '', upperBody: '', lowerBody: '', underwear: '', footwear: '', accessories: '', exposure: '', condition: '' },
      mind: { emotion: '', currentGoal: '', concern: '' },
      social: { relationToUser: '', attitudeToUser: '' },
      future: { todos: [], commitments: [] },
      active: true,
      updatedAtFloor: 0,
      sourceSwipeId: 0,
      sourceFingerprint: '',
      updatedAt: '',
    };
  }

  function foxMemoryNormalizeCharacterSnapshot(raw, fallbackName = '') {
    const name = String(raw?.name || fallbackName || '').trim();
    if (!name || name.length > 80) return null;
    const base = foxMemoryEmptyCharacterSnapshot(name);
    const text = (value) => String(value || '').trim();
    const list = value => foxMemoryNormalizeList(value);
    return {
      id: String(raw?.id || base.id),
      name,
      profile: {
        age: text(raw?.profile?.age, 40), gender: text(raw?.profile?.gender, 40),
        identity: text(raw?.profile?.identity), personality: text(raw?.profile?.personality),
      },
      location: {
        city: text(raw?.location?.city, 80), area: text(raw?.location?.area, 80), building: text(raw?.location?.building, 100),
        interior: text(raw?.location?.interior, 120), posture: text(raw?.location?.posture, 120),
      },
      nearbyCharacters: list(raw?.nearbyCharacters),
      physiology: Object.fromEntries(Object.keys(base.physiology).map(key => [key, text(raw?.physiology?.[key], 120)])),
      appearance: Object.fromEntries(Object.keys(base.appearance).map(key => [key, text(raw?.appearance?.[key], 160)])),
      mind: Object.fromEntries(Object.keys(base.mind).map(key => [key, text(raw?.mind?.[key], 180)])),
      social: Object.fromEntries(Object.keys(base.social).map(key => [key, text(raw?.social?.[key], 180)])),
      future: { todos: list(raw?.future?.todos), commitments: list(raw?.future?.commitments) },
      active: raw?.active !== false,
      updatedAtFloor: Math.max(0, Number(raw?.updatedAtFloor) || 0),
      sourceSwipeId: Math.max(0, Number(raw?.sourceSwipeId) || 0),
      sourceFingerprint: text(raw?.sourceFingerprint, 80),
      updatedAt: text(raw?.updatedAt, 80),
    };
  }

  function foxMemoryNormalizeSceneSnapshot(raw) {
    return {
      locationKey: String(raw?.locationKey || '').trim(),
      presentCharacters: foxMemoryNormalizeList(raw?.presentCharacters),
      updatedAtFloor: Math.max(0, Number(raw?.updatedAtFloor) || 0),
      sourceSwipeId: Math.max(0, Number(raw?.sourceSwipeId) || 0),
      sourceFingerprint: String(raw?.sourceFingerprint || ''),
    };
  }

  // ==================== 🆕 狐忆 V3：角色认知档案（五层）====================
  // 认知档案（characterProfiles）与状态快照（characterSnapshots）分离：
  //   - 状态快照高频动态（每回合 patch 位置/生理/外貌/情绪）
  //   - 认知档案低频稳定（事实/人格骨架/认知/行为/演化），证据累积才变
  // 事件流复用现有 plotAtoms（见 foxMemoryGetEventStream，不重复存储）；
  // 关系网 relationships 独立成横向跨角色层。

  const FOX_TRAIT_SCORE_KEYS = [
    'openness', 'conscientiousness', 'extraversion', 'agreeableness', 'neuroticism',
    'riskPreference', 'controlDesire', 'competitiveness', 'responsibility',
    'altruism', 'authorityObedience', 'ruleAwareness',
  ];
  const FOX_TRAIT_CATEGORY_DEFS = {
    attachment: ['安全型', '焦虑型', '回避型', '混乱型'],
  };
  const FOX_EVIDENCE_DIRECTION = ['升高', '降低', '稳定', ''];
  const FOX_PROFILE_EVIDENCE_MAX = 60;

  function foxMemoryClampScore(value) {
    const n = Number(value);
    if (!Number.isFinite(n)) return null;
    return Math.max(0, Math.min(100, Math.round(n)));
  }

  function foxMemoryCanonicalCharacterName(value) {
    let name = String(value || '').trim().replace(/\s+/g, ' ');
    if (!name) return '';
    const perspectiveOnly = name.match(/^[（(]?\s*从\s*.+?\s*视角(?:下)?\s*(?:看|看到|观察|认知|理解)(?:的|到)?\s*(.+?)\s*[）)]?$/);
    if (perspectiveOnly?.[1]) {
      name = perspectiveOnly[1].trim();
      if (/^(?:他|她|它|TA|ta|对方|自己)$/.test(name)) return '';
    }
    const perspectiveSuffix = name.match(/^(.+?)\s*[（(]\s*从\s*.+?\s*视角[\s\S]*[）)]$/);
    if (perspectiveSuffix?.[1]) name = perspectiveSuffix[1].trim();
    return name.replace(/^[（(]\s*|\s*[）)]$/g, '').trim();
  }

  function foxMemoryIsPlausibleCharacterName(value) {
    const name = foxMemoryCanonicalCharacterName(value);
    if (!name || name.length > 40 || /[\r\n<>【】\[\]{}#]/.test(name)) return false;
    if (/[：:；;。！？!?]/.test(name) || /^(?:无|未知|暂无|不明|其他|角色|人物|主角|玩家|用户|助手|旁白|作者|系统|角色卡|角色名|人物名|本角色|该角色|对方|自己|他|她|它|TA)$/i.test(name)) return false;
    if (/(?:角色卡|人物设定|角色设定|档案|简介|说明|世界书|聊天记录|上下文|视角|扮演|模板|示例|摘要|剧情|场景|世界观)$/.test(name)) return false;
    if (/^(?:从|以).+(?:视角|角度)/.test(name) || /(?:的|之)(?:视角|认知|理解|看法)$/.test(name)) return false;
    return /[\p{L}\p{N}]/u.test(name);
  }

  function foxMemoryTextMentionsCharacter(text, name) {
    const source = String(text || '');
    const target = String(name || '').trim();
    if (!source || !target) return false;
    if (/^[A-Za-z0-9_.-]+$/.test(target)) {
      const escaped = target.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      return new RegExp(`(^|[^A-Za-z0-9_.-])${escaped}(?=$|[^A-Za-z0-9_.-])`, 'i').test(source);
    }
    return source.includes(target);
  }

  function foxMemoryBuildProfileCharacterEvidence(data, profileFields, chatText, protagonistName) {
    const trusted = new Set();
    const add = value => {
      const name = foxMemoryCanonicalCharacterName(value);
      if (foxMemoryIsPlausibleCharacterName(name)) trusted.add(name.toLowerCase());
    };
    add(protagonistName);
    Object.values(data?.characterProfiles || {}).forEach(profile => add(profile?.name));
    Object.values(data?.characterSnapshots || {}).forEach(snapshot => add(snapshot?.name));
    for (const field of profileFields || []) {
      const name = foxMemoryCanonicalCharacterName(field?.character);
      if (!foxMemoryIsPlausibleCharacterName(name)) continue;
      if (foxMemoryTextMentionsCharacter(chatText, name)) add(name);
    }
    return trusted;
  }

  function foxMemoryEmptyCharacterProfile(name = '', isProtagonist = false) {
    const trimmed = String(name || '').trim();
    return {
      id: `profile_${foxMemoryHashText(trimmed.toLowerCase())}`,
      name: trimmed,
      isProtagonist: !!isProtagonist,
      facts: { name: trimmed, age: '', gender: '', occupation: '', identity: '', skills: [], possessions: [], location: '' },
      traits: { scores: {}, categories: {} },
      cognition: { goal: '', values: '', belief: '', principle: '', boundary: '' },
      behavior: { conflict: '', stress: '', towardLoved: '', danger: '', lyingStyle: '', thinkSpeed: '', speechRhythm: '', emotionRecovery: '' },
      state: {
        location: { city: '', area: '', building: '', interior: '', posture: '' },
        nearbyCharacters: [],
        physiology: { health: '', fatigue: '', cleanliness: '', pain: '', hunger: '', thirst: '', consciousness: '', mobility: '' },
        appearance: { outerwear: '', upperBody: '', lowerBody: '', underwear: '', footwear: '', accessories: '', exposure: '', condition: '' },
        mind: { emotion: '', currentGoal: '', concern: '' },
        social: { relationToUser: '', attitudeToUser: '' },
        future: { todos: [], commitments: [] },
      },
      evolution: { evidence: [], causalChain: '', pendingCount: 0, lastAdjustedFloor: 0 },
      relationRefs: [],
      custom: { fields: [], countedRanges: [], templateSeeded: false },
      _legacyPersonality: '',
      active: true,
      updatedAtFloor: 0,
      updatedAt: '',
    };
  }

  function foxMemoryNormalizeProfileState(raw) {
    const base = foxMemoryEmptyCharacterProfile().state;
    const text = (v, max = 200) => String(v ?? '').trim().slice(0, max);
    return {
      location: {
        city: text(raw?.location?.city, 80), area: text(raw?.location?.area, 80),
        building: text(raw?.location?.building, 100), interior: text(raw?.location?.interior, 120),
        posture: text(raw?.location?.posture, 120),
      },
      nearbyCharacters: foxMemoryNormalizeList(raw?.nearbyCharacters),
      physiology: Object.fromEntries(Object.keys(base.physiology).map(k => [k, text(raw?.physiology?.[k], 120)])),
      appearance: Object.fromEntries(Object.keys(base.appearance).map(k => [k, text(raw?.appearance?.[k], 160)])),
      mind: Object.fromEntries(Object.keys(base.mind).map(k => [k, text(raw?.mind?.[k], 180)])),
      social: Object.fromEntries(Object.keys(base.social).map(k => [k, text(raw?.social?.[k], 180)])),
      future: { todos: foxMemoryNormalizeList(raw?.future?.todos), commitments: foxMemoryNormalizeList(raw?.future?.commitments) },
    };
  }

  function foxMemoryNormalizeEvidence(raw) {
    if (!raw || typeof raw !== 'object') return null;
    const behavior = String(raw.behavior || raw.action || '').trim();
    if (!behavior || behavior.length > 400) return null;
    const direction = FOX_EVIDENCE_DIRECTION.includes(raw.direction) ? raw.direction : '';
    const confidenceRaw = Number(raw.confidence);
    const floor = Math.max(0, Math.floor(Number(raw.floor) || 0));
    return {
      behavior: behavior.slice(0, 400),
      inferredTrait: String(raw.inferredTrait || raw.trait || '').trim().slice(0, 60),
      direction,
      confidence: Number.isFinite(confidenceRaw) ? Math.max(0, Math.min(1, confidenceRaw)) : 0.5,
      causalChain: String(raw.causalChain || '').trim().slice(0, 600),
      floor: Number.isInteger(floor) ? floor : 0,
    };
  }

  function foxMemoryNormalizeCharacterProfile(raw, fallbackName = '') {
    const name = foxMemoryCanonicalCharacterName(raw?.name || fallbackName);
    if (!name || name.length > 80) return null;
    const text = (v, max = 300) => String(v ?? '').trim().slice(0, max);

    const scores = {};
    const rawScoresSrc = (raw?.traits && typeof raw.traits === 'object')
      ? (raw.traits.scores && typeof raw.traits.scores === 'object' ? raw.traits.scores : raw.traits)
      : {};
    for (const key of FOX_TRAIT_SCORE_KEYS) {
      const v = foxMemoryClampScore(rawScoresSrc[key]);
      if (v !== null) scores[key] = v;
    }

    const categories = {};
    const rawCats = (raw?.traits && typeof raw.traits === 'object' && raw.traits.categories) ? raw.traits.categories : {};
    for (const [key, allowed] of Object.entries(FOX_TRAIT_CATEGORY_DEFS)) {
      const v = String(rawCats[key] || '').trim();
      if (v && allowed.includes(v)) categories[key] = v;
    }

    const evidence = Array.isArray(raw?.evolution?.evidence)
      ? raw.evolution.evidence.map(foxMemoryNormalizeEvidence).filter(Boolean)
      : [];
    const trimmedEvidence = evidence.length > FOX_PROFILE_EVIDENCE_MAX
      ? evidence.slice(evidence.length - FOX_PROFILE_EVIDENCE_MAX)
      : evidence;

    return {
      id: String(raw?.id || `profile_${foxMemoryHashText(name.toLowerCase())}`),
      name,
      isProtagonist: raw?.isProtagonist === true,
      facts: {
        name,
        age: text(raw?.facts?.age, 40),
        gender: text(raw?.facts?.gender, 40),
        occupation: text(raw?.facts?.occupation, 80),
        identity: text(raw?.facts?.identity, 120),
        skills: foxMemoryNormalizeList(raw?.facts?.skills),
        possessions: foxMemoryNormalizeList(raw?.facts?.possessions),
        location: text(raw?.facts?.location, 120),
      },
      traits: { scores, categories },
      cognition: {
        goal: text(raw?.cognition?.goal, 200),
        values: text(raw?.cognition?.values, 300),
        belief: text(raw?.cognition?.belief, 300),
        principle: text(raw?.cognition?.principle, 300),
        boundary: text(raw?.cognition?.boundary, 300),
      },
      behavior: {
        conflict: text(raw?.behavior?.conflict, 120),
        stress: text(raw?.behavior?.stress, 120),
        towardLoved: text(raw?.behavior?.towardLoved, 120),
        danger: text(raw?.behavior?.danger, 120),
        lyingStyle: text(raw?.behavior?.lyingStyle, 120),
        thinkSpeed: text(raw?.behavior?.thinkSpeed, 60),
        speechRhythm: text(raw?.behavior?.speechRhythm, 120),
        emotionRecovery: text(raw?.behavior?.emotionRecovery, 120),
      },
      state: foxMemoryNormalizeProfileState(raw?.state),
      evolution: {
        evidence: trimmedEvidence,
        causalChain: text(raw?.evolution?.causalChain, 1000),
        pendingCount: Math.max(0, Math.floor(Number(raw?.evolution?.pendingCount) || 0)),
        lastAdjustedFloor: Math.max(0, Math.floor(Number(raw?.evolution?.lastAdjustedFloor) || 0)),
      },
      relationRefs: foxMemoryNormalizeList(raw?.relationRefs),
      _legacyPersonality: text(raw?._legacyPersonality, 600),
      active: raw?.active !== false,
      updatedAtFloor: Math.max(0, Math.floor(Number(raw?.updatedAtFloor) || 0)),
      updatedAt: text(raw?.updatedAt, 80),
      custom: foxMemoryNormalizeCustomArea(raw?.custom),
    };
  }

  // ==================== 🆕 人物表格：自定义字段 + 楼层账本 ====================
  // 字段类型：state=状态型(AI给绝对值直接覆盖) counter=计数型(AI只报增量+N,脚本累加) list=列表型(AI报+/-项)
  const FOX_TABLE_FIELD_TYPES = ['state', 'counter', 'list'];
  const FOX_TABLE_FIELD_TYPE_LABELS = { state: '状态', counter: '计数', list: '列表' };

  // 默认人物表格模板：覆盖五层档案没有的常见基本属性
  const FOX_MEMORY_DEFAULT_TABLE_TEMPLATE = [
    { key: '身高', type: 'state', hint: '稳定数值。✅168cm ❌看起来很高(无具体数值)' },
    { key: '体重', type: 'state', hint: '稳定数值。✅52kg ❌偏瘦(无具体数值)' },
    { key: '种族', type: 'state', hint: '✅人类/精灵/兽人 ❌亚洲人(现实族裔非奇幻种族)' },
    { key: '发色', type: 'state', hint: '稳定发色发型。✅银色长发 ❌头发凌乱(瞬时状态)' },
    { key: '瞳色', type: 'state', hint: '稳定瞳色。✅深红色 ❌眼神锐利(这是神态非瞳色)' },
    { key: '肤色', type: 'state', hint: '稳定肤色。✅白皙 ❌面色潮红(临时身体状态)' },
    { key: '外貌特征', type: 'state', hint: '永久性外貌标记。✅左脸刀疤、锁骨玫瑰纹身 ❌感染潮红、脱水唇裂、渗血绷带(这些是临时伤势/病征，应写入当前状态块的身体状态字段，不是外貌特征)' },
    { key: '穿着风格', type: 'state', hint: '日常穿着偏好。✅常穿黑色风衣 ❌今天穿了红裙(临时穿着非风格)' },
    { key: '喜好', type: 'list', hint: '✅甜食、古典音乐 ❌喜欢安静看书(过于具体的行为)' },
    { key: '厌恶', type: 'list', hint: '✅谎言、蜘蛛 ❌讨厌被忽视(心理需求非具体事物)' },
  ];

  function foxMemoryDefaultTableTemplate() {
    return FOX_MEMORY_DEFAULT_TABLE_TEMPLATE.map(f => ({ ...f }));
  }

  function foxMemoryNormalizeTableFieldType(v) {
    return FOX_TABLE_FIELD_TYPES.includes(v) ? v : 'state';
  }

  // 模板归一化：非数组（未设置过）→ 默认模板；空数组是合法的用户选择（不建默认字段）
  function foxMemoryNormalizeTableTemplate(raw) {
    if (!Array.isArray(raw)) return foxMemoryDefaultTableTemplate();
    const seen = new Set();
    const out = [];
    for (const item of raw) {
      const key = String(item?.key || '').trim().slice(0, 40);
      if (!key || seen.has(key)) continue;
      seen.add(key);
      out.push({ key, type: foxMemoryNormalizeTableFieldType(item?.type), hint: String(item?.hint || '').trim() });
      if (out.length >= 30) break;
    }
    return out;
  }

  function foxMemoryNormalizeTableField(raw) {
    if (!raw || typeof raw !== 'object') return null;
    const key = String(raw.key || '').trim().slice(0, 40);
    if (!key) return null;
    const type = foxMemoryNormalizeTableFieldType(raw.type);
    let value;
    if (type === 'counter') {
      const n = Number(raw.value);
      value = Number.isFinite(n) ? Math.trunc(n) : 0;
    } else if (type === 'list') {
      value = foxMemoryNormalizeList(Array.isArray(raw.value) ? raw.value : []);
    } else {
      value = String(raw.value ?? '').trim().slice(0, 300);
    }
    return { key, type, value, hint: String(raw.hint || '').trim().slice(0, 120) };
  }

  // 楼层账本：记录哪些楼层区间的计数增量已入账，防止重分析导致重复计数
  function foxMemoryNormalizeCountedRanges(raw) {
    if (!Array.isArray(raw)) return [];
    const out = [];
    for (const item of raw) {
      const s = Math.floor(Number(Array.isArray(item) ? item[0] : item?.start));
      const e = Math.floor(Number(Array.isArray(item) ? item[1] : item?.end));
      if (!Number.isFinite(s) || !Number.isFinite(e) || s < 0 || e < s) continue;
      out.push([s, e]);
      if (out.length >= 200) break;
    }
    return out;
  }

  // 判断 [start,end] 是否已完整入账（被某一已入账区间覆盖）
  function foxMemoryRangeCounted(ranges, start, end) {
    if (!Array.isArray(ranges)) return false;
    return ranges.some(([s, e]) => start >= s && end <= e);
  }

  // 入账并合并重叠/相邻区间，保持账本紧凑
  function foxMemoryAddCountedRange(ranges, start, end) {
    const list = foxMemoryNormalizeCountedRanges(ranges);
    list.push([start, end]);
    list.sort((a, b) => a[0] - b[0]);
    const merged = [];
    for (const [s, e] of list) {
      const last = merged[merged.length - 1];
      if (last && s <= last[1] + 1) last[1] = Math.max(last[1], e);
      else merged.push([s, e]);
    }
    return merged.slice(-200);
  }

  function foxMemoryNormalizeCustomArea(raw) {
    const fields = Array.isArray(raw?.fields)
      ? raw.fields.map(foxMemoryNormalizeTableField).filter(Boolean).slice(0, 40)
      : [];
    return {
      fields,
      countedRanges: foxMemoryNormalizeCountedRanges(raw?.countedRanges),
      templateSeeded: raw?.templateSeeded === true,
    };
  }

  // 独立自定义表（非人物，如“xxx出现次数”）
  function foxMemoryNormalizeCustomTable(raw) {
    if (!raw || typeof raw !== 'object') return null;
    const name = String(raw.name || '').trim().slice(0, 60);
    if (!name) return null;
    return {
      id: String(raw.id || `ctable_${foxMemoryHashText(name.toLowerCase())}`),
      name,
      note: String(raw.note || '').trim().slice(0, 200),
      fields: (Array.isArray(raw.fields) ? raw.fields.map(foxMemoryNormalizeTableField).filter(Boolean) : []).slice(0, 40),
      countedRanges: foxMemoryNormalizeCountedRanges(raw.countedRanges),
      updatedAtFloor: Math.max(0, Math.floor(Number(raw.updatedAtFloor) || 0)),
    };
  }

  // 把默认模板中缺失的字段补进档案 custom 区（不动已有字段的值）
  function foxMemoryEnsureTemplateFields(profile) {
    if (!profile || typeof profile !== 'object') return profile;
    if (!profile.custom) profile.custom = { fields: [], countedRanges: [], templateSeeded: false };
    const template = foxMemoryNormalizeTableTemplate(foxMemoryConfig?.tableTemplate);
    for (const tpl of template) {
      if (!profile.custom.fields.some(f => f.key === tpl.key)) {
        profile.custom.fields.push(foxMemoryNormalizeTableField({ key: tpl.key, type: tpl.type, value: tpl.type === 'counter' ? 0 : (tpl.type === 'list' ? [] : ''), hint: tpl.hint }));
      }
    }
    profile.custom.templateSeeded = true;
    return profile;
  }

  function foxMemoryNormalizeRelationship(raw) {
    if (!raw || typeof raw !== 'object') return null;
    const a = foxMemoryCanonicalCharacterName(raw.a || raw.from);
    const b = foxMemoryCanonicalCharacterName(raw.b || raw.to);
    if (!a || !b || a === b || a.length > 80 || b.length > 80) return null;
    const importanceRaw = Number(raw.importance);
    const floor = Math.max(0, Math.floor(Number(raw.updatedAtFloor) || 0));
    return {
      id: String(raw.id || `rel_${foxMemoryHashText(`${a.toLowerCase()}::${b.toLowerCase()}`)}`),
      a, b,
      type: String(raw.type || '').trim().slice(0, 60),
      summary: String(raw.summary || '').trim().slice(0, 400),
      aView: String(raw.aView || '').trim().slice(0, 300),
      bView: String(raw.bView || '').trim().slice(0, 300),
      importance: Number.isFinite(importanceRaw) ? Math.max(0, Math.min(1, importanceRaw)) : 0.5,
      updatedAtFloor: Number.isInteger(floor) ? floor : 0,
    };
  }

  // 事件流访问器：plotAtoms 即事件流（演进复用，不重复存储）
  function foxMemoryGetEventStream(data) {
    const d = data || loadFoxMemory();
    return Array.isArray(d.plotAtoms) ? d.plotAtoms : [];
  }

  // 角色认知档案迁移（幂等）：把现有 characterSnapshots 的结构化状态一次性复制到 characterProfiles。
  // 阶段1 纯机械迁移，不调用 AI；memories[character] 的字符串档案留待阶段2 AI 解析填充 facts/cognition。
  // characterSnapshots 保留不删（现有快照功能依赖），characterProfiles 为新增并行副本。
  function foxMemoryMigrateToV3(data) {
    if (!data || typeof data !== 'object') return data;
    if (Number(data.profileSchemaVersion) >= 3) return data;
    data.characterProfiles = data.characterProfiles || {};
    for (const [name, snap] of Object.entries(data.characterSnapshots || {})) {
      if (data.characterProfiles[name]) continue;
      const profile = foxMemoryEmptyCharacterProfile(name, false);
      const s = snap || {};
      profile.facts.age = String(s.profile?.age || '').trim();
      profile.facts.gender = String(s.profile?.gender || '').trim();
      profile.facts.identity = String(s.profile?.identity || '').trim();
      if (s.profile?.personality) profile._legacyPersonality = String(s.profile.personality).slice(0, 600);
      profile.state = foxMemoryNormalizeProfileState({
        location: s.location, nearbyCharacters: s.nearbyCharacters,
        physiology: s.physiology, appearance: s.appearance,
        mind: s.mind, social: s.social, future: s.future,
      });
      profile.active = s.active !== false;
      profile.updatedAtFloor = Math.max(0, Number(s.updatedAtFloor) || 0);
      profile.updatedAt = String(s.updatedAt || '').slice(0, 80);
      const normalized = foxMemoryNormalizeCharacterProfile(profile, name);
      if (normalized) data.characterProfiles[name] = normalized;
    }
    data.relationships = Array.isArray(data.relationships)
      ? data.relationships.map(foxMemoryNormalizeRelationship).filter(Boolean)
      : [];
    data.profileSchemaVersion = 3;
    foxMemoryV2Log('V3迁移', `profiles=${Object.keys(data.characterProfiles).length} relationships=${data.relationships.length} schemaVersion=3`);
    return data;
  }

  // ==================== 🆕 V3 认知档案：解析结果应用 ====================
  // 中英文维度名映射（AI 可能输出中文维度名）
  const FOX_TRAIT_SCORE_CN_MAP = {
    '开放性': 'openness', '尽责性': 'conscientiousness', '外向性': 'extraversion',
    '宜人性': 'agreeableness', '神经质': 'neuroticism',
    '风险偏好': 'riskPreference', '控制欲': 'controlDesire', '竞争性': 'competitiveness',
    '责任感': 'responsibility', '利他程度': 'altruism', '利他': 'altruism',
    '权威服从': 'authorityObedience', '规则意识': 'ruleAwareness',
  };
  // 🆕 反向映射：英文键 -> 中文标签，用于 UI 显示
  const FOX_TRAIT_SCORE_LABELS = {
    openness: '开放性', conscientiousness: '尽责性', extraversion: '外向性',
    agreeableness: '宜人性', neuroticism: '神经质',
    riskPreference: '风险偏好', controlDesire: '控制欲', competitiveness: '竞争性',
    responsibility: '责任感', altruism: '利他程度',
    authorityObedience: '权威服从', ruleAwareness: '规则意识',
  };
  const FOX_TRAIT_CATEGORY_CN_MAP = {
    '依恋风格': 'attachment', '依恋': 'attachment',
  };

  // 把 AI 输出的维度名解析为 { type:'score'|'category', key } 或 null
  function foxMemoryResolveTraitKey(dimension) {
    const dim = String(dimension || '').trim();
    if (!dim) return null;
    if (FOX_TRAIT_SCORE_KEYS.includes(dim)) return { type: 'score', key: dim };
    if (FOX_TRAIT_SCORE_CN_MAP[dim]) return { type: 'score', key: FOX_TRAIT_SCORE_CN_MAP[dim] };
    if (FOX_TRAIT_CATEGORY_DEFS[dim]) return { type: 'category', key: dim };
    if (FOX_TRAIT_CATEGORY_CN_MAP[dim]) return { type: 'category', key: FOX_TRAIT_CATEGORY_CN_MAP[dim] };
    return null;
  }

  // 档案字段白名单路径（traits 单独处理）
  const FOX_PROFILE_FIELD_PATHS = {
    facts: ['age', 'gender', 'occupation', 'identity', 'location', 'skills', 'possessions'],
    cognition: ['goal', 'values', 'belief', 'principle', 'boundary'],
    behavior: ['conflict', 'stress', 'towardLoved', 'danger', 'lyingStyle', 'thinkSpeed', 'speechRhythm', 'emotionRecovery'],
    state: ['location.city', 'location.area', 'location.building', 'location.interior', 'location.posture',
      'physiology.health', 'physiology.fatigue', 'physiology.cleanliness', 'physiology.pain', 'physiology.hunger',
      'physiology.thirst', 'physiology.consciousness', 'physiology.mobility',
      'appearance.outerwear', 'appearance.upperBody', 'appearance.lowerBody', 'appearance.underwear',
      'appearance.footwear', 'appearance.accessories', 'appearance.exposure', 'appearance.condition',
      'mind.emotion', 'mind.currentGoal', 'mind.concern',
      'social.relationToUser', 'social.attitudeToUser',
      'future.todos', 'future.commitments', 'nearbyCharacters'],
  };
  const FOX_PROFILE_LIST_FIELDS = new Set(['facts.skills', 'facts.possessions', 'state.future.todos', 'state.future.commitments', 'state.nearbyCharacters']);

  // 取得或创建角色档案（主角用 isProtagonist 标记）
  function foxMemoryGetOrCreateProfile(data, name, isProtagonist = false) {
    name = foxMemoryCanonicalCharacterName(name);
    if (!foxMemoryIsPlausibleCharacterName(name)) return null;
    if (!data.characterProfiles) data.characterProfiles = {};
    const key = Object.keys(data.characterProfiles).find(k => k.toLowerCase() === String(name || '').toLowerCase());
    if (key) {
      if (isProtagonist) data.characterProfiles[key].isProtagonist = true;
      return data.characterProfiles[key];
    }
    const profile = foxMemoryNormalizeCharacterProfile(foxMemoryEmptyCharacterProfile(name, isProtagonist), name);
    if (profile) {
      foxMemoryEnsureTemplateFields(profile); // 🆕 建档即按默认模板播种自定义字段
      data.characterProfiles[String(name)] = profile;
    }
    return profile || null;
  }

  function foxMemoryMergeMissing(target, source) {
    if (!source || typeof source !== 'object') return target;
    for (const [key, value] of Object.entries(source)) {
      if (Array.isArray(value)) {
        const current = Array.isArray(target[key]) ? target[key] : [];
        const seen = new Set(current.map(item => JSON.stringify(item)));
        target[key] = current.concat(value.filter(item => {
          const fp = JSON.stringify(item);
          if (seen.has(fp)) return false;
          seen.add(fp);
          return true;
        }));
      } else if (value && typeof value === 'object') {
        if (!target[key] || typeof target[key] !== 'object' || Array.isArray(target[key])) target[key] = {};
        foxMemoryMergeMissing(target[key], value);
      } else if (target[key] === '' || target[key] === null || target[key] === undefined) {
        target[key] = value;
      }
    }
    return target;
  }

  // 把历史伪名称归并回真实角色，避免“从某人视角看的某人”长期成为第二个人物。
  function foxMemoryCanonicalizeCharacterEntities(data) {
    if (!data || typeof data !== 'object') return data;
    const aliases = [];
    const canonicalizeMap = (source, normalize) => {
      const out = {};
      for (const [oldKey, raw] of Object.entries(source || {})) {
        const canonical = foxMemoryCanonicalCharacterName(raw?.name || oldKey);
        if (!canonical) continue;
        const isAlias = canonical !== oldKey || canonical !== raw?.name;
        if (isAlias) aliases.push(`${oldKey}->${canonical}`);
        const normalized = normalize({ ...raw, name: canonical }, canonical);
        if (!normalized) continue;
        normalized.name = canonical;
        if (normalized.facts) normalized.facts.name = canonical;
        if (out[canonical] && isAlias) foxMemoryMergeMissing(out[canonical], normalized);
        else if (out[canonical]) out[canonical] = foxMemoryMergeMissing(normalized, out[canonical]);
        else out[canonical] = normalized;
      }
      return out;
    };
    data.characterProfiles = canonicalizeMap(data.characterProfiles, foxMemoryNormalizeCharacterProfile);
    data.characterSnapshots = canonicalizeMap(data.characterSnapshots, foxMemoryNormalizeCharacterSnapshot);
    const canonicalList = list => [...new Set(foxMemoryNormalizeList(list).map(foxMemoryCanonicalCharacterName).filter(Boolean))];
    data.sceneSnapshot = foxMemoryNormalizeSceneSnapshot({ ...data.sceneSnapshot, presentCharacters: canonicalList(data.sceneSnapshot?.presentCharacters) });
    for (const p of Object.values(data.characterProfiles)) if (p.state) p.state.nearbyCharacters = canonicalList(p.state.nearbyCharacters);
    for (const s of Object.values(data.characterSnapshots)) s.nearbyCharacters = canonicalList(s.nearbyCharacters);
    data.relationships = (data.relationships || []).map(foxMemoryNormalizeRelationship).filter(Boolean);
    if (aliases.length) foxMemoryV2Log('角色实体归并', aliases.join('；'));
    return data;
  }

  // 应用关系网更新：归一化方向（a<=b）后去重合并
  function foxMemoryApplyRelations(data, relations, floor = 0) {
    if (!data.relationships) data.relationships = [];
    let changed = 0;
    for (const incoming of relations) {
      if (!incoming) continue;
      let { a, b, aView, bView } = incoming;
      // 归一化方向：a <= b（按小写字母序），同时交换视角
      if (String(a).toLowerCase() > String(b).toLowerCase()) { [a, b] = [b, a]; [aView, bView] = [bView, aView]; }
      const aLow = String(a).toLowerCase();
      const bLow = String(b).toLowerCase();
      const merged = foxMemoryNormalizeRelationship({
        a, b, type: incoming.type, summary: incoming.summary,
        aView: aView || '', bView: bView || '',
        importance: incoming.importance, updatedAtFloor: floor || incoming.updatedAtFloor || 0,
      });
      if (!merged) continue;
      const idx = data.relationships.findIndex(r => r.a.toLowerCase() === aLow && r.b.toLowerCase() === bLow);
      if (idx >= 0) {
        const existing = data.relationships[idx];
        data.relationships[idx] = foxMemoryNormalizeRelationship({
          ...existing, ...merged,
          aView: merged.aView || existing.aView,
          bView: merged.bView || existing.bView,
        });
      } else {
        data.relationships.push(merged);
      }
      changed++;
    }
    if (data.relationships.length > 200) {
      data.relationships.sort((x, y) => (y.importance || 0) - (x.importance || 0));
      data.relationships = data.relationships.slice(0, 200);
    }
    return changed;
  }

  // 应用档案字段更新：set/clear/add/remove 到 facts/traits/cognition/behavior/state
  function foxMemoryApplyProfileFields(data, fields, trustedCharacters = null) {
    let changed = 0;
    for (const f of fields) {
      if (!f || !f.character) continue;
      const character = foxMemoryCanonicalCharacterName(f.character);
      if (!foxMemoryIsPlausibleCharacterName(character)) continue;
      const existingKey = Object.keys(data.characterProfiles || {}).find(k => k.toLowerCase() === character.toLowerCase());
      if (!existingKey && trustedCharacters && !trustedCharacters.has(character.toLowerCase())) {
        foxMemoryV2Log('档案拒绝', `reason=unverified_character name=${character}`);
        continue;
      }
      if (f.layer === 'traits') {
        const profile = foxMemoryGetOrCreateProfile(data, character, false);
        if (!profile) continue;
        // 🆕 压缩写法：字段=scores，值="开放性:70, 外向性:40, ..." 一次写完全部维度
        if (/^(scores|评分|打分)$/i.test(String(f.field).trim())) {
          let didChange = false;
          for (const pair of String(f.value || '').split(/[,，;；\n]+/)) {
            const m = pair.match(/^\s*(.+?)\s*[:：]\s*(-?\d+)\s*$/);
            if (!m) continue;
            const resolvedPair = foxMemoryResolveTraitKey(m[1].trim());
            if (!resolvedPair || resolvedPair.type !== 'score') continue;
            const v = foxMemoryClampScore(Number(m[2]));
            if (v === null) continue;
            const old = profile.traits.scores[resolvedPair.key];
            // 演化限速：已有评分单次调整幅度不超过 5 分；初始评分（无旧值）不受限
            const nv = (typeof old === 'number') ? Math.max(old - 5, Math.min(old + 5, v)) : v;
            if (profile.traits.scores[resolvedPair.key] !== nv) { profile.traits.scores[resolvedPair.key] = nv; didChange = true; }
          }
          if (!didChange) continue;
          changed++;
          profile.updatedAtFloor = Math.max(profile.updatedAtFloor || 0, getCurrentLastMessageId());
          profile.updatedAt = new Date().toISOString();
          continue;
        }
        const resolved = foxMemoryResolveTraitKey(f.field);
        if (!resolved) continue;
        let didChange = false;
        if (resolved.type === 'score') {
          if (f.operation === 'clear') { if (resolved.key in profile.traits.scores) { delete profile.traits.scores[resolved.key]; didChange = true; } }
          else {
            const v = foxMemoryClampScore(f.value);
            if (v !== null) {
              const old = profile.traits.scores[resolved.key];
              const nv = (typeof old === 'number') ? Math.max(old - 5, Math.min(old + 5, v)) : v;
              if (profile.traits.scores[resolved.key] !== nv) { profile.traits.scores[resolved.key] = nv; didChange = true; }
            }
          }
        } else {
          if (f.operation === 'clear') { if (resolved.key in profile.traits.categories) { delete profile.traits.categories[resolved.key]; didChange = true; } }
          else if (FOX_TRAIT_CATEGORY_DEFS[resolved.key].includes(String(f.value).trim()) && profile.traits.categories[resolved.key] !== String(f.value).trim()) { profile.traits.categories[resolved.key] = String(f.value).trim(); didChange = true; }
        }
        if (!didChange) continue;
        changed++;
        profile.updatedAtFloor = Math.max(profile.updatedAtFloor || 0, getCurrentLastMessageId());
        profile.updatedAt = new Date().toISOString();
        continue;
      }
      const allowed = FOX_PROFILE_FIELD_PATHS[f.layer];
      if (!allowed || !allowed.includes(f.field)) continue;
      const profile = foxMemoryGetOrCreateProfile(data, character, false);
      if (!profile) continue;
      const fullPath = `${f.layer}.${f.field}`;
      const isList = FOX_PROFILE_LIST_FIELDS.has(fullPath);
      const before = foxMemoryGetPath(profile, fullPath);
      let after = before;
      if (f.operation === 'clear') after = isList ? [] : '';
      else if (isList) {
        const incoming = foxMemoryNormalizeList(f.value);
        const current = foxMemoryNormalizeList(foxMemoryGetPath(profile, fullPath));
        if (f.operation === 'remove') after = current.filter(x => !incoming.includes(x));
        else if (f.operation === 'add') after = [...new Set([...current, ...incoming])];
        else after = incoming;
      } else {
        after = String(f.value || '').trim().slice(0, 300);
      }
      if (JSON.stringify(before ?? (isList ? [] : '')) === JSON.stringify(after)) continue;
      foxMemorySetPath(profile, fullPath, after);
      changed++;
      profile.updatedAtFloor = Math.max(profile.updatedAtFloor || 0, getCurrentLastMessageId());
      profile.updatedAt = new Date().toISOString();
    }
    return changed;
  }

  // ==================== 🆕 人物表格/自定义表：表格块应用（含楼层账本防重复计数）====================
  // range = 本次分析覆盖的楼层区间 {start, end}；计数字段的增量(add)只在区间未入账时应用，
  // 应用后入账；绝对值纠错(set)始终允许且不入账，与增量互不混淆。
  function foxMemoryApplyTableBlocks(data, ops, range, trustedCharacters = null) {
    let changed = 0;
    if (!Array.isArray(ops) || !ops.length) return 0;
    data.customTables = Array.isArray(data.customTables) ? data.customTables : [];
    const validRange = range && Number.isFinite(range?.start) && Number.isFinite(range?.end) && range.end >= range.start;
    for (const op of ops) {
      const targetName = String(op.target || '').trim();
      if (!targetName || !op.field) continue;
      // 解析宿主：优先人物档案，其次独立自定义表（独立表只允许更新用户已建的，AI 不可新建）
      let host = null;
      const canonical = foxMemoryCanonicalCharacterName(targetName);
      const profileKey = Object.keys(data.characterProfiles || {}).find(k => k.toLowerCase() === String(canonical || '').toLowerCase());
      let profile = profileKey ? data.characterProfiles[profileKey] : null;
      if (!profile && foxMemoryIsPlausibleCharacterName(canonical) && (!trustedCharacters || trustedCharacters.has(canonical.toLowerCase()))) {
        profile = foxMemoryGetOrCreateProfile(data, canonical, false);
      }
      if (profile) host = { kind: 'profile', obj: profile };
      else {
        const table = data.customTables.find(t => String(t.name).toLowerCase() === targetName.toLowerCase());
        if (table) host = { kind: 'table', obj: table };
      }
      if (!host) {
        foxMemoryV2Log('表格拒绝', `reason=unknown_target target=${targetName}`);
        continue;
      }
      const container = host.kind === 'profile'
        ? (host.obj.custom = host.obj.custom || { fields: [], countedRanges: [], templateSeeded: false })
        : host.obj;
      if (!Array.isArray(container.fields)) container.fields = [];
      if (!Array.isArray(container.countedRanges)) container.countedRanges = [];
      let field = container.fields.find(f => f.key === op.field);
      if (!field) {
        field = foxMemoryNormalizeTableField({ key: op.field, type: op.type || 'state', value: op.type === 'counter' ? 0 : (op.type === 'list' ? [] : '') });
        if (!field || container.fields.length >= 40) continue;
        container.fields.push(field);
      }
      const rangeCounted = validRange && foxMemoryRangeCounted(container.countedRanges, range.start, range.end);
      let didChange = false;
      let ledgerDirty = false;
      if (field.type === 'counter') {
        if (op.operation === 'add') {
          const delta = Number(String(op.value ?? '').trim().replace(/^＋/, ''));
          if (!Number.isFinite(delta) || delta === 0) continue;
          if (rangeCounted) {
            foxMemoryV2Log('表格拒绝', `reason=range_already_counted target=${targetName} field=${field.key} range=${range.start}-${range.end}`);
            continue;
          }
          field.value = (Number(field.value) || 0) + Math.trunc(delta);
          didChange = true;
          ledgerDirty = true;
        } else if (op.operation === 'set') {
          const v = Number(op.value);
          if (!Number.isFinite(v)) continue;
          const nv = Math.trunc(v);
          if (field.value !== nv) { field.value = nv; didChange = true; }
        } else if (op.operation === 'clear') {
          if (field.value !== 0) { field.value = 0; didChange = true; }
        }
      } else if (field.type === 'list') {
        const items = foxMemoryNormalizeList(String(op.value ?? '').split(/[,，、;；\n]+/));
        const current = foxMemoryNormalizeList(field.value);
        let after = current;
        if (op.operation === 'add') after = [...new Set([...current, ...items])];
        else if (op.operation === 'remove') after = current.filter(x => !items.includes(x));
        else if (op.operation === 'clear') after = [];
        else after = items;
        if (JSON.stringify(after) !== JSON.stringify(current)) { field.value = after; didChange = true; }
      } else {
        if (op.operation === 'clear') {
          if (field.value !== '') { field.value = ''; didChange = true; }
        } else if (op.operation === 'set') {
          const nv = String(op.value ?? '').trim().slice(0, 300);
          if (nv && field.value !== nv) { field.value = nv; didChange = true; }
        }
      }
      if (!didChange) continue;
      if (ledgerDirty && validRange) container.countedRanges = foxMemoryAddCountedRange(container.countedRanges, range.start, range.end);
      host.obj.updatedAtFloor = Math.max(host.obj.updatedAtFloor || 0, getCurrentLastMessageId());
      if (host.kind === 'profile') host.obj.updatedAt = new Date().toISOString();
      changed++;
    }
    return changed;
  }

  // 刷新每个 profile 的 relationRefs（指向关系网的本角色关联）
  function foxMemoryRefreshRelationRefs(data) {
    if (!data.characterProfiles) return;
    const refs = {};
    for (const rel of data.relationships || []) {
      const aLow = String(rel.a).toLowerCase();
      const bLow = String(rel.b).toLowerCase();
      (refs[aLow] ||= new Set()).add(rel.b);
      (refs[bLow] ||= new Set()).add(rel.a);
    }
    for (const p of Object.values(data.characterProfiles)) {
      const set = refs[String(p.name).toLowerCase()];
      p.relationRefs = set ? [...set] : [];
    }
  }

  function foxMemoryBuildProfileSummary(data = loadFoxMemory()) {
    const profiles = Object.values(data.characterProfiles || {});
    const profileRows = profiles.map(profile => ({
      name: profile.name,
      isProtagonist: profile.isProtagonist === true,
      facts: profile.facts || {},
      traits: profile.traits || {},
      cognition: profile.cognition || {},
      behavior: profile.behavior || {},
      evolution: {
        causalChain: profile.evolution?.causalChain || '',
        pendingCount: profile.evolution?.pendingCount || 0,
        evidenceCount: (profile.evolution?.evidence || []).length,
        lastAdjustedFloor: profile.evolution?.lastAdjustedFloor || 0,
      },
    }));
    const relations = (data.relationships || []).map(relation => ({
      a: relation.a,
      b: relation.b,
      type: relation.type || '',
      summary: relation.summary || '',
      aView: relation.aView || '',
      bView: relation.bView || '',
      importance: relation.importance ?? 0.5,
    }));
    return JSON.stringify({ profiles: profileRows, relationships: relations }, null, 2);
  }

  // 🆕 人物表格摘要：注入分析提示词，让 AI 知道各人物已有的自定义字段、计数字段当前值和独立自定义表
  function foxMemoryBuildTableSummary(data = loadFoxMemory()) {
    const fmtFields = fields => (fields || []).map(f => {
      const label = FOX_TABLE_FIELD_TYPE_LABELS[f.type] || '状态';
      const v = f.type === 'list' ? (Array.isArray(f.value) ? f.value.join('、') : '') : f.value;
      return `${f.key}(${label})=${v === '' || v == null ? '（空）' : v}`;
    }).join('；');
    const lines = [];
    for (const p of Object.values(data.characterProfiles || {})) {
      const fields = p.custom?.fields || [];
      if (!fields.length) continue;
      lines.push(`【${p.name}】${fmtFields(fields)}`);
    }
    for (const t of data.customTables || []) {
      lines.push(`【自定义表：${t.name}】${t.note ? `说明：${t.note}｜` : ''}${fmtFields(t.fields) || '（无字段）'}`);
    }
    return lines.length ? lines.join('\n') : '（暂无人物表格字段与自定义表）';
  }

  // 🆕 表格召回注入体：查询文本命中角色名/表名时，注入其自定义字段与自定义表（独立于认知档案开关）
  function foxMemoryBuildTableInjectBody(queryText, memData) {
    const q = String(queryText || '');
    if (!q) return '';
    const data = memData || loadFoxMemory();
    const fmtFields = fields => (fields || [])
      .filter(f => f.type === 'counter' ? Number(f.value) !== 0 : (f.type === 'list' ? (Array.isArray(f.value) && f.value.length) : String(f.value ?? '').trim()))
      .map(f => `${f.key}=${f.type === 'list' ? f.value.join('、') : f.value}`)
      .join('；');
    const lines = [];
    for (const p of Object.values(data.characterProfiles || {})) {
      if (!p.name || p.name.length < 2 || !q.includes(p.name)) continue;
      const text = fmtFields(p.custom?.fields);
      if (text) lines.push(`【${p.name}】${text}`);
    }
    for (const t of data.customTables || []) {
      if (!t.name || t.name.length < 2 || !q.includes(t.name)) continue;
      const text = fmtFields(t.fields);
      lines.push(`【自定义表：${t.name}】${t.note ? `说明：${t.note}｜` : ''}${text || '（无字段）'}`);
    }
    return lines.length ? ('【人物表格】\n' + lines.join('\n')) : '';
  }

  // ==================== 🆕 V3 认知档案：召回链路（L0主角常驻+L1涉事+L2关系扩散+L3详情按需）====================
  // 解决主角吃书：即使主角不在场，涉事角色的关系扩散也会召回主角精简卡，保证连通性。
  function foxMemoryRecallProfiles(queryText) {
    const data = loadFoxMemory();
    const profiles = data.characterProfiles || {};
    const relations = data.relationships || [];
    const protagonistName = pwGraphGetPlayerName();
    const q = String(queryText || '');

    const allProfiles = Object.values(profiles);
    // L0 主角档案（常驻）
    const protagonist = allProfiles.find(p => p.isProtagonist || p.name === protagonistName) || null;
    // L1 涉事：queryText 命中角色名（排除主角，主角走 L0）
    const hit = allProfiles.filter(p => !p.isProtagonist && p.name !== protagonistName && p.name.length >= 2 && q.includes(p.name));
    // L2 关系扩散：L1 角色的一级关系对象，主角优先，排除已在 L0/L1 的
    const already = new Set([
      ...(protagonist ? [protagonist.name.toLowerCase()] : []),
      ...hit.map(p => p.name.toLowerCase()),
    ]);
    const spreadNames = [];
    for (const p of hit) {
      for (const rel of relations) {
        const other = rel.a === p.name ? rel.b : (rel.b === p.name ? rel.a : null);
        if (other && !already.has(other.toLowerCase()) && !spreadNames.includes(other)) {
          if (other === protagonistName) spreadNames.unshift(other); // 主角优先
          else spreadNames.push(other);
        }
      }
    }
    const spread = spreadNames.map(n => profiles[n] || allProfiles.find(p => p.name === n)).filter(Boolean).slice(0, 3);
    // L3 详情按需：命中方面关键词时，涉事角色召回详情层（state+behavior）
    const needDetail = /(受伤|伤势|撒谎|说谎|愤怒|生气|害怕|恐惧|冲突|吵架|危险|压力|紧张|崩溃|情绪|逃跑|战斗)/.test(q);
    foxMemoryV2Log('召回分析', `query="${q.slice(0, 40)}" 总档案=${allProfiles.length} 关系总数=${relations.length} L0主角=${protagonist?.name || '无'} L1涉事=[${hit.map(p => p.name).join(',')}] L2扩散=[${spread.map(p => p.name).join(',')}] L3详情=${needDetail}`);
    return { protagonist, hit, spread, relations, needDetail };
  }

  // 格式化档案核心层（短，保证完整性）：身份+人格分数+因果链+认知
  function foxMemoryFormatProfileCore(p) {
    const parts = [];
    parts.push(`【${p.name}${p.isProtagonist ? '（主角）' : ''}】`);
    if (p.facts?.identity) parts.push(`身份:${p.facts.identity}`);
    if (p.facts?.occupation) parts.push(`职业:${p.facts.occupation}`);
    const scores = Object.entries(p.traits?.scores || {});
    if (scores.length) parts.push(`人格:${scores.map(([k, v]) => `${k}:${v}`).join(',')}`);
    if (p.traits?.categories?.attachment) parts.push(`依恋:${p.traits.categories.attachment}`);
    if (p.cognition?.goal) parts.push(`目标:${p.cognition.goal}`);
    if (p.cognition?.boundary) parts.push(`底线:${p.cognition.boundary}`);
    if (p.evolution?.causalChain) parts.push(`人格成因:${p.evolution.causalChain}`);
    return parts.join('；');
  }

  // 格式化档案详情层（L3 按需）：state + behavior
  function foxMemoryFormatProfileDetail(p) {
    const parts = [];
    const loc = [p.state?.location?.building, p.state?.location?.interior].filter(Boolean).join('·');
    if (loc) parts.push(`位置:${loc}`);
    if (p.state?.physiology?.health) parts.push(`身体:${p.state.physiology.health}`);
    if (p.state?.mind?.emotion) parts.push(`情绪:${p.state.mind.emotion}`);
    if (p.state?.mind?.currentGoal) parts.push(`当前目标:${p.state.mind.currentGoal}`);
    const beh = [p.behavior?.conflict, p.behavior?.stress, p.behavior?.danger].filter(Boolean);
    if (beh.length) parts.push(`行为模式:${beh.join('；')}`);
    return parts.length ? parts.join('；') : '';
  }

  // 构建认知档案注入文本（L0+L1+L2+L3+关系网）
  function foxMemoryBuildProfileInjectBody(queryText) {
    const recall = foxMemoryRecallProfiles(queryText);
    const lines = [];
    if (recall.protagonist) {
      lines.push('【主角认知档案】');
      lines.push(foxMemoryFormatProfileCore(recall.protagonist));
    }
    if (recall.hit.length) {
      lines.push('【涉事角色档案】');
      for (const p of recall.hit.slice(0, 5)) {
        lines.push(foxMemoryFormatProfileCore(p));
        if (recall.needDetail) { const d = foxMemoryFormatProfileDetail(p); if (d) lines.push(`  [状态] ${d}`); }
      }
    }
    if (recall.spread.length) {
      lines.push('【关联角色·关系扩散】');
      for (const p of recall.spread) lines.push(foxMemoryFormatProfileCore(p));
    }
    // 关系网：召回角色之间的关系（含与主角）
    const relNames = new Set([
      ...(recall.protagonist ? [recall.protagonist.name.toLowerCase()] : []),
      ...recall.hit.map(p => p.name.toLowerCase()),
      ...recall.spread.map(p => p.name.toLowerCase()),
    ]);
    const relLines = recall.relations.filter(r => relNames.has(r.a.toLowerCase()) && relNames.has(r.b.toLowerCase()));
    if (relLines.length) {
      lines.push('【人物关系】');
      for (const r of relLines.slice(0, 8)) lines.push(`${r.a}↔${r.b}：${r.type || ''}${r.summary ? '（' + r.summary + '）' : ''}`);
    }
    const body = lines.length ? ('【角色认知档案】\n' + lines.join('\n')) : '';
    // 🆕 记录本次召回摘要到 state，供输入框悬浮窗显示「本次聊天召回的记忆」+ 完备日志
    try {
      state.foxMemoryLastRecall = {
        time: Date.now(),
        queryText: String(queryText || '').slice(0, 120),
        protagonist: recall.protagonist?.name || null,
        hit: recall.hit.slice(0, 5).map(p => p.name),
        spread: recall.spread.map(p => p.name),
        needDetail: recall.needDetail,
        relationCount: relLines.length,
        relationPairs: relLines.slice(0, 8).map(r => `${r.a}↔${r.b}`),
        chars: body.length,
        body: body,
      };
      foxMemoryV2Log('召回注入', `主角=${state.foxMemoryLastRecall.protagonist || '无'} 涉事=${state.foxMemoryLastRecall.hit.length} 扩散=${state.foxMemoryLastRecall.spread.length} 关系=${state.foxMemoryLastRecall.relationCount} 详情=${state.foxMemoryLastRecall.needDetail} 注入字数=${state.foxMemoryLastRecall.chars}`);
    } catch (e) { foxMemoryV2Log('召回记录失败', e?.message || e); }
    // 🆕 刷新输入框上方「本次召回」悬浮窗
    try { foxMemoryEnsureRecallFloat(); foxMemoryRefreshRecallFloat(); foxMemoryRenderProfilesFloat(); } catch { }
    return body;
  }

  // ==================== 🆕 V3 输入框上方「本次召回」悬浮窗 ====================
  // 折叠条钉在 #send_textarea 上方，点击展开显示本次召回的角色档案/关系。认知档案关闭时不显示。
  function foxMemoryEnsureRecallFloat() {
    // 🎴 已统一进「统一底栏」(#xh-dock)：不再创建独立的召回悬浮窗，只确保底栏存在。
    try {
      if (typeof initUnifiedDock === 'function') initUnifiedDock();
