  function foxMemoryFloatSwitchTab(tab) {
    try {
      const float = topDoc.getElementById('foxmem-recall-float');
      if (!float) return;
      float.querySelectorAll('.foxmem-float-tab').forEach(btn => {
        const active = btn.dataset.tab === tab;
        btn.style.background = active ? 'rgba(232,120,74,0.15)' : 'rgba(255,255,255,0.03)';
        btn.style.color = active ? '#ffb06a' : '#a09088';
        btn.style.borderColor = active ? 'rgba(232,120,74,0.3)' : 'rgba(232,120,74,0.2)';
      });
