  function foxMemoryRefreshRecallFloat() {
    // 🎴 召回摘要已统一到底栏状态行；旧悬浮窗元素已不存在，这里只刷新底栏。
    try {
      if (typeof xhDockRefresh === 'function') xhDockRefresh();
    } catch (e) { foxMemoryV2Log('悬浮窗刷新失败', e?.message || e); }
  }

  // 渲染角色档案列表（五层可展开 + 删除 + JSON编辑），主角置顶
  function foxMemoryRenderProfilesFloat() {
    try {
      const pane = topDoc.getElementById('foxmem-float-pane-profiles');
      if (!pane) return;
      const data = loadFoxMemory();
      let profiles = Object.values(data.characterProfiles || {});
      profiles.sort((a, b) => (b.isProtagonist ? 1 : 0) - (a.isProtagonist ? 1 : 0));
      if (!profiles.length) {
        pane.innerHTML = '<div style="color:#706058;padding:10px;line-height:1.6;">暂无角色档案。开启「认知档案」并聊天后，狐忆会自动建立角色认知档案（事实/人格/认知/行为/演化五层）。</div>';
        return;
      }
      pane.innerHTML = '';
      const esc = (s) => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
      for (const p of profiles) {
        const card = topDoc.createElement('div');
        card.style.cssText = 'border:1px solid rgba(232,120,74,0.2);border-radius:6px;margin-bottom:6px;overflow:hidden;';
        const head = topDoc.createElement('div');
        head.style.cssText = 'padding:5px 8px;background:rgba(232,120,74,0.1);display:flex;align-items:center;gap:6px;';
        head.innerHTML = `<span style="color:#f0a070;font-weight:600;">${esc(p.name)}${p.isProtagonist ? '（主角）' : ''}</span><span style="margin-left:auto;font-size:10px;color:#706058;">${p.active ? '在场' : '离场'}｜${p.updatedAtFloor || 0}楼</span>`;
        const editBtn = topDoc.createElement('button');
        editBtn.textContent = '✏️'; editBtn.title = '编辑（JSON）';
        editBtn.style.cssText = 'padding:1px 5px;border:1px solid rgba(232,120,74,0.3);border-radius:4px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:11px;';
        editBtn.onclick = () => foxMemoryEditProfileFloat(p.name, card);
        head.appendChild(editBtn);
        const delBtn = topDoc.createElement('button');
        delBtn.textContent = '🗑'; delBtn.title = '删除';
        delBtn.style.cssText = 'padding:1px 5px;border:1px solid rgba(139,0,0,0.3);border-radius:4px;background:rgba(139,0,0,0.1);color:#d08080;cursor:pointer;font-size:11px;';
        delBtn.onclick = () => {
          if (!confirm(`删除角色档案「${p.name}」？此操作不可撤销。`)) return;
          const d = loadFoxMemory();
          delete d.characterProfiles[p.name];
          saveFoxMemory(d);
          foxMemoryRenderProfilesFloat();
          try { toast(`已删除角色档案「${p.name}」`, 'success'); } catch {}
        };
        head.appendChild(delBtn);
        card.appendChild(head);
        const ev = p.evolution || {};
        const layers = [
          ['①事实 facts', { 年龄: p.facts?.age, 性别: p.facts?.gender, 职业: p.facts?.occupation, 身份: p.facts?.identity, 所在地: p.facts?.location, 技能: (p.facts?.skills || []).join('、'), 持有物: (p.facts?.possessions || []).join('、') }],
          ['②人格 traits', { ...(p.traits?.scores || {}), 依恋: p.traits?.categories?.attachment }],
          ['③认知 cognition', p.cognition],
          ['④行为 behavior', p.behavior],
          ['⑤演化 evolution', (() => {
            const evObj = { 因果链: ev.causalChain, 待处理证据: ev.pendingCount, 证据总数: (ev.evidence || []).length, 上次微调楼: ev.lastAdjustedFloor };
            const evList = (ev.evidence || []).slice(-5);
            for (let i = 0; i < evList.length; i++) {
              const e = evList[i];
              const dirLabel = e.direction ? `[${e.direction}]` : '';
              const confLabel = e.confidence != null ? ` (置信度${e.confidence.toFixed(2)})` : '';
              evObj[`证据${evList.length - i}`] = `${FOX_TRAIT_SCORE_LABELS[e.inferredTrait] || e.inferredTrait}${dirLabel}${confLabel}: ${e.behavior}${e.causalChain ? ' || ' + e.causalChain : ''}`;
            }
            return evObj;
          })()],
          ['状态 state', { 位置: [p.state?.location?.building, p.state?.location?.interior].filter(Boolean).join('·'), 身体: p.state?.physiology?.health, 情绪: p.state?.mind?.emotion, 当前目标: p.state?.mind?.currentGoal, 在场角色: (p.state?.nearbyCharacters || []).join('、') }],
        ];
        for (const [label, obj] of layers) {
          const det = topDoc.createElement('details');
          det.style.cssText = 'border-top:1px solid rgba(232,120,74,0.1);';
          const sum = topDoc.createElement('summary');
          sum.style.cssText = 'cursor:pointer;padding:4px 8px;color:#a09088;font-size:11px;user-select:none;';
          sum.textContent = label;
          det.appendChild(sum);
          const body = topDoc.createElement('div');
          body.style.cssText = 'padding:4px 8px 6px;font-size:11px;color:#90756a;line-height:1.6;';
          for (const [k, v] of Object.entries(obj || {})) {
            if (v === undefined || v === null || v === '' || (Array.isArray(v) && !v.length)) continue;
            const vStr = typeof v === 'object' ? JSON.stringify(v) : String(v);
            body.innerHTML += `<div><span style="color:#706058;">${esc(k)}:</span> ${esc(vStr)}</div>`;
          }
          if (!body.innerHTML) body.innerHTML = '<div style="color:#605048;">（暂无）</div>';
          det.appendChild(body);
          card.appendChild(det);
        }
        pane.appendChild(card);
      }
    } catch (e) { foxMemoryV2Log('档案渲染失败', e?.message || e); }
  }

  // 编辑角色档案（JSON 内联编辑）
  function foxMemoryEditProfileFloat(name, card) {
    try {
      const data = loadFoxMemory();
      const key = Object.keys(data.characterProfiles || {}).find(k => k.toLowerCase() === String(name).toLowerCase());
      const p = key ? data.characterProfiles[key] : null;
      if (!p) { try { toast('档案不存在', 'warning'); } catch {} return; }
      card.innerHTML = '';
      const btnRow = topDoc.createElement('div');
      btnRow.style.cssText = 'display:flex;gap:6px;padding:6px 8px;background:rgba(232,120,74,0.1);';
      const saveBtn = topDoc.createElement('button');
      saveBtn.textContent = '💾保存'; saveBtn.style.cssText = 'flex:1;padding:4px;border:1px solid rgba(232,120,74,0.4);border-radius:5px;background:rgba(232,120,74,0.2);color:#ffb06a;cursor:pointer;font-size:11px;';
      const cancelBtn = topDoc.createElement('button');
      cancelBtn.textContent = '取消'; cancelBtn.style.cssText = 'flex:1;padding:4px;border:1px solid rgba(232,120,74,0.2);border-radius:5px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:11px;';
      cancelBtn.onclick = () => foxMemoryRenderProfilesFloat();
      const ta = topDoc.createElement('textarea');
      ta.value = JSON.stringify(p, null, 2);
      ta.style.cssText = 'width:100%;min-height:200px;box-sizing:border-box;background:rgba(0,0,0,0.2);border:1px solid rgba(232,120,74,0.3);border-radius:5px;color:#e8ddd4;padding:6px;font-size:11px;font-family:monospace;resize:vertical;';
      saveBtn.onclick = () => {
        try {
          const parsed = JSON.parse(ta.value);
          const normalized = foxMemoryNormalizeCharacterProfile(parsed, name);
          if (!normalized) { try { toast('❌ 档案格式无效（name 缺失或过长）', 'error'); } catch {} return; }
          const d = loadFoxMemory();
          const oldKey = Object.keys(d.characterProfiles).find(k => k.toLowerCase() === name.toLowerCase());
          if (oldKey && oldKey !== normalized.name) delete d.characterProfiles[oldKey];
          d.characterProfiles[normalized.name] = normalized;
          saveFoxMemory(d);
          foxMemoryRenderProfilesFloat();
          try { toast(`✅ 已保存「${normalized.name}」`, 'success'); } catch {}
        } catch (e) { try { toast(`❌ JSON 解析失败：${e.message}`, 'error'); } catch {} }
      };
      btnRow.appendChild(saveBtn); btnRow.appendChild(cancelBtn);
      card.appendChild(btnRow); card.appendChild(ta);
    } catch (e) { foxMemoryV2Log('档案编辑失败', e?.message || e); }
  }

  function foxMemoryGetPath(obj, path) {
    return String(path).split('.').reduce((value, key) => value?.[key], obj);
  }

  function foxMemorySetPath(obj, path, value) {
    const keys = String(path).split('.');
    let target = obj;
    for (let i = 0; i < keys.length - 1; i++) target = target[keys[i]] ||= {};
    target[keys[keys.length - 1]] = value;
  }

  function foxMemoryCoreForCheckpoint(data = loadFoxMemory()) {
    const clone = value => {
      try { return typeof structuredClone === 'function' ? structuredClone(value) : JSON.parse(JSON.stringify(value)); }
      catch { return JSON.parse(JSON.stringify(value || null)); }
    };
    return {
      memories: clone(data.memories || []),
      plotAtoms: clone(data.plotAtoms || []),
      currentStates: clone(data.currentStates || []),
      characterSnapshots: clone(data.characterSnapshots || {}),
      characterProfiles: Object.fromEntries(Object.entries(data.characterProfiles || {}).map(([name, p]) => {
        // 检查点瘦身：排除 evolution.evidence 数组（可达数十KB），避免 core 膨胀触发 180000 上限导致回滚失效。
        // evidence 是行为过程记录，回滚状态时不回滚（可重新累积）；traits 分数/因果链/pendingCount 保留。
        const cp = clone(p);
        if (cp?.evolution) cp.evolution.evidence = [];
        return [name, cp];
      })),
      relationships: clone(data.relationships || []),
      profileSchemaVersion: Number(data.profileSchemaVersion) || 0,
      sceneSnapshot: clone(data.sceneSnapshot || foxMemoryNormalizeSceneSnapshot()),
      customTables: clone(data.customTables || []), // 🆕 自定义表随检查点快照/回退
      lastAnalysis: data.lastAnalysis || null,
    };
  }

  function foxMemoryNormalizeCheckpoint(cp) {
    if (!cp || !Number.isInteger(Number(cp.floor)) || !cp.core) return null;
    return {
      id: String(cp.id || `checkpoint_${cp.floor}_${cp.swipeId || 0}`),
      kind: cp.kind === 'chunk' ? 'chunk' : 'turn',
      floor: Number(cp.floor),
      swipeId: Math.max(0, Number(cp.swipeId) || 0),
      fingerprint: String(cp.fingerprint || '').slice(0, 80),
      createdAt: String(cp.createdAt || ''),
      core: {
        memories: Array.isArray(cp.core.memories) ? cp.core.memories : [],
        plotAtoms: Array.isArray(cp.core.plotAtoms) ? cp.core.plotAtoms.map(foxMemoryNormalizeStoredAtom).filter(Boolean) : [],
        currentStates: Array.isArray(cp.core.currentStates) ? cp.core.currentStates.map(foxMemoryNormalizeCurrentState).filter(Boolean) : [],
        characterSnapshots: Object.fromEntries(Object.entries(cp.core.characterSnapshots || {}).map(([name, item]) => [name, foxMemoryNormalizeCharacterSnapshot(item, name)]).filter(([, item]) => !!item)),
        characterProfiles: Object.fromEntries(Object.entries(cp.core.characterProfiles || {}).map(([name, item]) => [name, foxMemoryNormalizeCharacterProfile(item, name)]).filter(([, item]) => !!item)),
        relationships: Array.isArray(cp.core.relationships) ? cp.core.relationships.map(foxMemoryNormalizeRelationship).filter(Boolean) : [],
        profileSchemaVersion: Number(cp.core.profileSchemaVersion) || 0,
        sceneSnapshot: foxMemoryNormalizeSceneSnapshot(cp.core.sceneSnapshot),
        customTables: Array.isArray(cp.core.customTables) ? cp.core.customTables.map(foxMemoryNormalizeCustomTable).filter(Boolean) : [],
        lastAnalysis: cp.core.lastAnalysis || null,
      },
    };
  }

  function foxMemoryGetMessageBranchMeta(messageId) {
    try {
      const message = getFn('getChatMessages')?.(messageId, { hide_state: 'all', include_swipes: true })?.[0];
      if (!message) return { floor: Number(messageId) || 0, swipeId: 0, fingerprint: '' };
      const swipeId = Math.max(0, Number(message.swipe_id) || 0);
      const text = xhGetAssistantMessageText(message).text;
      return { floor: Number(messageId) || 0, swipeId, fingerprint: foxMemoryHashText(text) };
    } catch {
      return { floor: Number(messageId) || 0, swipeId: 0, fingerprint: '' };
    }
  }

  function foxMemorySaveCheckpoint(messageId, core, kind = 'turn') {
    const data = loadFoxMemory();
    const meta = foxMemoryGetMessageBranchMeta(messageId);
    const checkpoint = foxMemoryNormalizeCheckpoint({
      id: `${kind}_${meta.floor}_${meta.swipeId}_${Date.now()}`,
      kind,
      floor: meta.floor,
      swipeId: meta.swipeId,
      fingerprint: meta.fingerprint,
      createdAt: new Date().toISOString(),
      core: core || foxMemoryCoreForCheckpoint(data),
    });
    const checkpointChars = JSON.stringify(checkpoint.core).length;
    if (checkpointChars > 180000) {
      foxMemoryV2Log('检查点跳过', `kind=${kind} floor=${meta.floor} chars=${checkpointChars} reason=too_large`);
      return null;
    }
    data.checkpoints ||= { turns: [], chunks: [] };
    const key = kind === 'chunk' ? 'chunks' : 'turns';
    const limit = kind === 'chunk' ? 2 : 3;
    data.checkpoints[key] = [...(data.checkpoints[key] || []).map(foxMemoryNormalizeCheckpoint).filter(Boolean), checkpoint].slice(-limit);
    if (saveFoxMemory(data)) {
      foxMemoryV2Log('检查点保存', `kind=${kind} floor=${meta.floor} swipe=${meta.swipeId} retained=${data.checkpoints[key].length}`);
    } else {
      foxMemoryV2Log('检查点失败', `kind=${kind} floor=${meta.floor} reason=storage_write_failed`);
      return null;
    }
    return checkpoint;
  }

  function foxMemoryRestoreCheckpoint(checkpoint, reason = 'branch_change') {
    const cp = foxMemoryNormalizeCheckpoint(checkpoint);
    if (!cp) return false;
    const current = loadFoxMemory();
    const clone = value => JSON.parse(JSON.stringify(value || null));
    const core = clone(cp.core);
    // 检查点为控制体积不保存 evolution.evidence；恢复时保留当前证据，避免空数组覆盖共享档案。
    for (const [name, profile] of Object.entries(core.characterProfiles || {})) {
      const currentKey = Object.keys(current.characterProfiles || {}).find(key => key.toLowerCase() === name.toLowerCase());
      if (currentKey && profile?.evolution) profile.evolution.evidence = clone(current.characterProfiles[currentKey]?.evolution?.evidence || []);
    }
    const restored = { ...current, ...core, checkpoints: current.checkpoints };
    const ok = saveFoxMemory(restored);
    if (ok) {
      foxMemoryV2Log('检查点恢复', `reason=${reason} kind=${cp.kind} floor=${cp.floor} swipe=${cp.swipeId}`);
      try { foxMemoryRenderList(); foxMemoryRenderStats(); } catch { }
      if (foxMemoryConfig?.injectToPreset) foxMemorySyncToPreset();
    }
    return ok;
  }

  function foxMemoryRollbackForBranchStart(type = 'swipe') {
    const lastId = getCurrentLastMessageId();
    if (lastId < 0) return false;
    const data = loadFoxMemory();
    const currentMeta = foxMemoryGetMessageBranchMeta(lastId);
    const candidates = (data.checkpoints?.turns || []).map(foxMemoryNormalizeCheckpoint).filter(Boolean)
      .filter(cp => cp.floor === lastId || (type === 'regenerate' && cp.floor === lastId + 1));
    const checkpoint = type === 'regenerate'
      ? candidates.sort((a, b) => {
        const aPriority = a.floor === lastId + 1 ? 1 : 0;
        const bPriority = b.floor === lastId + 1 ? 1 : 0;
        return bPriority - aPriority || String(b.createdAt).localeCompare(String(a.createdAt));
      })[0]
      : candidates.find(cp => cp.floor === currentMeta.floor && cp.swipeId === currentMeta.swipeId && cp.fingerprint && cp.fingerprint === currentMeta.fingerprint);
    if (!checkpoint) {
      foxMemoryV2Log('分支回滚跳过', `type=${type} floor=${lastId} reason=no_exact_checkpoint`);
      return false;
    }
    state.foxMemoryPendingBranchCheckpoint = checkpoint;
    return foxMemoryRestoreCheckpoint(checkpoint, type);
  }

  function foxMemoryFormatAtomForInject(atom) {
    const range = Number.isFinite(Number(atom?.floorStart)) && Number.isFinite(Number(atom?.floorEnd))
      ? `第${atom.floorStart}-${atom.floorEnd}楼`
      : String(atom?.eventTime || '来源楼层未标注');
    // 🕰️ 狐刻联动：给剧情信息句追加剧情时间标注
    let timeTag = '';
    try {
      if (typeof ftGetClockForFloor === 'function' && Number.isFinite(Number(atom?.floorEnd))) {
        const clock = ftGetClockForFloor(Number(atom.floorEnd));
        if (clock && !clock.unknown) timeTag = ` [${ftClockLabel(clock)}]`;
      }
    } catch { }
    return `- ${foxMemoryNormalizeAtomText(atom?.text || atom?.content)}（${range}）${timeTag}`;
  }

  function foxMemoryEstimateBytes(value) {
    try { return new Blob([String(value || '')]).size; } catch { return String(value || '').length * 2; }
  }

  const FOX_MEMORY_VECTOR_DB_NAME = 'XuanhuFoxMemoryVectorCache';
  const FOX_MEMORY_VECTOR_STORE = 'embeddings';

  function foxMemoryWithTimeout(promise, timeoutMs, label) {
    let timer;
    return Promise.race([
      promise,
      new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error(`${label}超时（${timeoutMs}ms）`)), timeoutMs);
      }),
    ]).finally(() => clearTimeout(timer));
  }

  function foxMemoryValidateVector(vector, expectedDimension = 0) {
    if (!Array.isArray(vector) || !vector.length) return null;
    const normalized = vector.map(Number);
    if (!normalized.every(Number.isFinite)) return null;
    if (expectedDimension > 0 && normalized.length !== expectedDimension) return null;
    let norm = 0;
    for (const value of normalized) norm += value * value;
    return norm > 0 ? normalized : null;
  }

  function foxMemoryRedactVectorError(value) {
    const config = foxMemoryNormalizeVectorConfig();
    let text = String(value || '');
    if (config.apiKey) text = text.replaceAll(config.apiKey, '[REDACTED_KEY]');
    text = text.replace(/([?&](?:key|api_key|token|access_token|password)=)[^&\s]+/gi, '$1[REDACTED]');
    text = text.replace(/(authorization\s*[:=]\s*bearer\s+)[^\s,;]+/gi, '$1[REDACTED]');
    return text;
  }

  function foxMemoryNormalizeVectorConfig(config = foxMemoryConfig) {
    const raw = config?.vectorMemory || {};
    const parsedWeight = Number(raw.weight);
    const parsedMinScore = Number(raw.minScore);
    return {
      enabled: raw.enabled === true,
      endpoint: String(raw.endpoint || '').trim().replace(/\/+$/, ''),
      apiKey: String(raw.apiKey || '').trim(),
      model: String(raw.model || '').trim(),
      proxyPreset: String(raw.proxyPreset || '').trim(),
      weight: Math.max(0, Math.min(0.8, Number.isFinite(parsedWeight) ? parsedWeight : 0.42)),
      minScore: Math.max(0, Math.min(1, Number.isFinite(parsedMinScore) ? parsedMinScore : 0.35)),
      timeoutMs: Math.max(3000, Math.min(60000, Number(raw.timeoutMs) || 15000)),
    };
  }

  function foxMemoryVectorConfigReady(config = foxMemoryConfig) {
    const v = foxMemoryResolveVectorConnection(config);
    return v.enabled && !!v.endpoint && !!v.model;
  }

  function foxMemoryResolveVectorConnection(config = foxMemoryConfig) {
    const v = foxMemoryNormalizeVectorConfig(config);
    if (!v.proxyPreset) return v;
    try {
      const preset = getPreset(v.proxyPreset);
      const settings = preset?.settings || {};
      const endpoint = String(settings.apiurl || '').trim().replace(/\/+$/, '');
      if (!endpoint) {
        return { ...v, endpoint: '', apiKey: '', connectionError: `代理预设「${v.proxyPreset}」不存在或没有 API 地址` };
      }
      return {
        ...v,
        endpoint,
        apiKey: String(settings.key || '').trim(),
      };
    } catch (e) {
      foxMemoryV2Log('向量代理预设失败', `preset=${v.proxyPreset} reason=${e?.message || e}`);
      return { ...v, endpoint: '', apiKey: '', connectionError: `代理预设「${v.proxyPreset}」读取失败` };
    }
  }

  function foxMemoryOpenVectorDb() {
    return new Promise((resolve, reject) => {
      if (!topWindow?.indexedDB) return reject(new Error('IndexedDB 不可用'));
      const request = topWindow.indexedDB.open(FOX_MEMORY_VECTOR_DB_NAME, 1);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains(FOX_MEMORY_VECTOR_STORE)) db.createObjectStore(FOX_MEMORY_VECTOR_STORE, { keyPath: 'key' });
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error || new Error('IndexedDB 打开失败'));
      request.onblocked = () => reject(new Error('IndexedDB 升级被其他页面阻塞'));
    });
  }

  async function foxMemoryVectorCacheGetMany(keys) {
    if (!keys.length) return new Map();
    const db = await foxMemoryWithTimeout(foxMemoryOpenVectorDb(), 5000, 'IndexedDB 打开');
    try {
      return await foxMemoryWithTimeout(new Promise((resolve, reject) => {
        const tx = db.transaction(FOX_MEMORY_VECTOR_STORE, 'readonly');
        const store = tx.objectStore(FOX_MEMORY_VECTOR_STORE);
        const result = new Map();
        let pending = keys.length;
        for (const key of keys) {
          const req = store.get(key);
          req.onsuccess = () => {
            const vector = foxMemoryValidateVector(req.result?.vector);
            if (vector) result.set(key, vector);
            if (--pending === 0) resolve(result);
          };
          req.onerror = () => reject(req.error || new Error(`向量缓存读取失败：${key}`));
        }
      }), 5000, 'IndexedDB 读取');
    } finally {
      db.close();
    }
  }

  async function foxMemoryVectorCachePutMany(rows) {
    if (!rows.length) return;
    const db = await foxMemoryWithTimeout(foxMemoryOpenVectorDb(), 5000, 'IndexedDB 打开');
    try {
      await foxMemoryWithTimeout(new Promise((resolve, reject) => {
        const tx = db.transaction(FOX_MEMORY_VECTOR_STORE, 'readwrite');
        const store = tx.objectStore(FOX_MEMORY_VECTOR_STORE);
        for (const row of rows) store.put(row);
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error || new Error('向量缓存写入失败'));
        tx.onabort = () => reject(tx.error || new Error('向量缓存事务中断'));
      }), 5000, 'IndexedDB 写入');
    } finally {
      db.close();
    }
  }

  async function foxMemoryClearVectorCache(scopeOnly = true) {
    foxMemoryInvalidateVectorSnapshot('cache_clear');
    const clearGeneration = state.foxMemoryVectorGeneration;
    const db = await foxMemoryWithTimeout(foxMemoryOpenVectorDb(), 5000, 'IndexedDB 打开');
    const prefix = scopeOnly ? `${getFoxMemoryScopeId()}|` : '';
    try {
      let removed = 0;
      await foxMemoryWithTimeout(new Promise((resolve, reject) => {
        const tx = db.transaction(FOX_MEMORY_VECTOR_STORE, 'readwrite');
        const store = tx.objectStore(FOX_MEMORY_VECTOR_STORE);
        if (!scopeOnly) {
          store.clear();
        } else {
          const request = store.openCursor();
          request.onsuccess = () => {
            const cursor = request.result;
            if (!cursor) return;
            if (String(cursor.key || '').startsWith(prefix)) {
              cursor.delete();
              removed++;
            }
            cursor.continue();
          };
          request.onerror = () => reject(request.error || new Error('向量缓存游标失败'));
        }
        tx.oncomplete = () => resolve();
        tx.onerror = () => reject(tx.error || new Error('向量缓存清理失败'));
      }), 5000, 'IndexedDB 清理');
      if (clearGeneration === state.foxMemoryVectorGeneration) state.foxMemoryVectorSnapshot = null;
      foxMemoryV2Log('向量缓存清理', `scope=${scopeOnly ? getFoxMemoryScopeId() : 'all'} removed=${scopeOnly ? removed : 'all'}`);
    } finally {
      db.close();
    }
  }

  function foxMemoryVectorCacheKey(text, config = foxMemoryConfig) {
    const v = foxMemoryResolveVectorConnection(config);
    if (v.connectionError) throw new Error(v.connectionError);
    return `${getFoxMemoryScopeId()}|${v.endpoint}|${v.model}|${foxMemoryHashText(foxMemoryAtomFingerprint({ text }))}`;
  }

  async function foxMemoryRequestEmbeddings(texts, config = foxMemoryConfig) {
    const v = foxMemoryResolveVectorConnection(config);
    if (!v.enabled) throw new Error('向量召回未开启');
    if (!v.endpoint) throw new Error('未配置 Embedding API 地址');
    if (!v.model) throw new Error('未配置 Embedding 模型');
    if (!/^https:\/\//i.test(v.endpoint) && !/^http:\/\/(?:localhost|127\.0\.0\.1|\[::1\])(?::\d+)?(?:\/|$)/i.test(v.endpoint)) {
      throw new Error('Embedding API 必须使用 HTTPS；仅 localhost 允许 HTTP');
    }
    const input = texts.map(x => String(x || '').trim()).filter(Boolean);
    if (!input.length) return [];
    const endpoint = /\/embeddings$/i.test(v.endpoint) ? v.endpoint : `${v.endpoint}/embeddings`;
    const isLocalEndpoint = (() => {
      try {
        const url = new URL(endpoint);
        return ['localhost', '127.0.0.1', '[::1]'].includes(url.hostname);
      } catch { return false; }
    })();
    const requestUrl = isLocalEndpoint ? endpoint : `/proxy/${endpoint}`;
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), v.timeoutMs);
    const startedAt = Date.now();
    foxMemoryV2Log('向量请求', `transport=${isLocalEndpoint ? 'direct_local' : 'sillytavern_proxy'} endpoint=${foxMemoryRedactVectorError(endpoint)} model=${v.model} inputs=${input.length}`);
    try {
      const headers = { 'Content-Type': 'application/json' };
      if (v.apiKey) headers.Authorization = `Bearer ${v.apiKey}`;
      const response = await fetch(requestUrl, {
        method: 'POST',
        headers,
        body: JSON.stringify({ model: v.model, input }),
        signal: controller.signal,
      });
      if (!response.ok) {
        const detail = await response.text().catch(() => response.statusText);
        if (!isLocalEndpoint && response.status === 404 && /proxy|disabled|not found/i.test(detail)) {
          throw new Error('酒馆 CORS Proxy 未启用：请在 config.yaml 设置 enableCorsProxy: true 并重启酒馆');
        }
        throw new Error(`Embedding HTTP ${response.status}: ${foxMemoryRedactVectorError(detail).slice(0, 500)}`);
      }
      const payload = await response.json();
      const rows = Array.isArray(payload?.data) ? payload.data : [];
      const vectors = new Array(input.length);
      rows.forEach((row, fallbackIndex) => {
        const index = Number.isInteger(row?.index) ? row.index : fallbackIndex;
        if (index < 0 || index >= input.length || vectors[index]) return;
        if (Array.isArray(row?.embedding) && row.embedding.length) {
          const vector = foxMemoryValidateVector(row.embedding);
          if (vector) vectors[index] = vector;
        }
      });
      if (vectors.some(vector => !Array.isArray(vector) || !vector.length)) throw new Error(`Embedding 返回数量不完整：expected=${input.length} actual=${rows.length}`);
      const dimension = vectors[0].length;
      if (!dimension || vectors.some(vector => vector.length !== dimension)) throw new Error('Embedding 向量维度不一致');
      foxMemoryV2Log('向量请求完成', `inputs=${input.length} dimensions=${vectors[0]?.length || 0} ms=${Date.now() - startedAt}`);
      return vectors;
    } catch (e) {
      const message = foxMemoryRedactVectorError(e?.name === 'AbortError' ? `Embedding 请求超时（${v.timeoutMs}ms）` : (e?.message || String(e)));
      foxMemoryV2Log('向量请求失败', message);
      throw new Error(message);
    } finally {
      clearTimeout(timer);
    }
  }

  function foxMemoryCosineSimilarity(left, right) {
    if (!Array.isArray(left) || !Array.isArray(right) || !left.length || left.length !== right.length) return 0;
    let dot = 0, leftNorm = 0, rightNorm = 0;
    for (let i = 0; i < left.length; i++) {
      const a = Number(left[i]) || 0;
      const b = Number(right[i]) || 0;
      dot += a * b;
      leftNorm += a * a;
      rightNorm += b * b;
    }
    return leftNorm > 0 && rightNorm > 0 ? dot / Math.sqrt(leftNorm * rightNorm) : 0;
  }

  async function foxMemoryGetOrCreateVectors(texts, generation = state.foxMemoryVectorGeneration) {
    const uniqueTexts = [...new Set(texts.map(x => String(x || '').trim()).filter(Boolean))];
    const keyed = uniqueTexts.map(text => ({ text, key: foxMemoryVectorCacheKey(text) }));
    let cached = new Map();
    try {
      cached = await foxMemoryVectorCacheGetMany(keyed.map(x => x.key));
    } catch (e) {
      foxMemoryV2Log('向量缓存失败', `operation=read reason=${e?.message || e}`);
    }
    const missing = keyed.filter(x => !cached.has(x.key));
    foxMemoryV2Log('向量缓存', `requested=${keyed.length} hit=${keyed.length - missing.length} missing=${missing.length}`);
    if (missing.length) {
      const vectors = [];
      const batchSize = 64;
      for (let i = 0; i < missing.length; i += batchSize) {
        const batch = missing.slice(i, i + batchSize);
        const batchVectors = await foxMemoryRequestEmbeddings(batch.map(x => x.text));
        batch.forEach((item, index) => {
          cached.set(item.key, batchVectors[index]);
          vectors.push({ key: item.key, vector: batchVectors[index], updatedAt: new Date().toISOString() });
        });
      }
      try {
        if (generation === state.foxMemoryVectorGeneration) {
          await foxMemoryVectorCachePutMany(vectors);
          foxMemoryV2Log('向量缓存写入', `rows=${vectors.length}`);
        } else {
          foxMemoryV2Log('向量缓存跳过', `reason=superseded rows=${vectors.length}`);
        }
      } catch (e) {
        foxMemoryV2Log('向量缓存失败', `operation=write reason=${e?.message || e}`);
      }
    }
    return new Map(keyed.map(item => [item.text, cached.get(item.key)]).filter(([, vector]) => Array.isArray(vector)));
  }

  async function foxMemoryIndexAtoms(atoms = foxMemoryGetCurrentAtoms()) {
    if (!foxMemoryVectorConfigReady()) return { indexed: 0, skipped: true };
    const texts = (Array.isArray(atoms) ? atoms : []).map(atom => atom?.text).filter(Boolean);
    if (!texts.length) return { indexed: 0, skipped: true };
    try {
      const vectors = await foxMemoryGetOrCreateVectors(texts);
      foxMemoryV2Log('向量建索引完成', `atoms=${texts.length} indexed=${vectors.size}`);
      return { indexed: vectors.size, skipped: false };
    } catch (e) {
      foxMemoryV2Log('向量建索引失败', `atoms=${texts.length} reason=${e?.message || e}`, e);
      return { indexed: 0, skipped: false, error: e };
    }
  }

  function foxMemoryBuildVectorQuery(userInput = '', recallFloors = 8) {
    const windowFloors = Math.max(1, parseInt(recallFloors, 10) || 8);
    return `${foxMemoryGetRecentTextForPlotRelevance(windowFloors)}\n${String(userInput || '')}`.trim();
  }

  function foxMemoryGetAtomRevision(atoms = foxMemoryGetCurrentAtoms()) {
    return foxMemoryHashText((Array.isArray(atoms) ? atoms : []).map(atom => `${atom.id}:${foxMemoryAtomFingerprint(atom)}`).sort().join('|'));
  }

  function foxMemoryBuildVectorSignature(queryText, atoms = foxMemoryGetCurrentAtoms()) {
    const v = foxMemoryResolveVectorConnection();
    return foxMemoryHashText(`${getFoxMemoryScopeId()}|${v.endpoint}|${v.model}|${foxMemoryGetAtomRevision(atoms)}|${queryText}`);
  }

  async function foxMemoryPrepareVectorSnapshot(userInput = '', options = {}) {
    foxMemoryConfig = loadFoxMemoryConfig();
    foxMemoryInstallVectorInputListener();
    if (!foxMemoryVectorConfigReady()) {
      state.foxMemoryVectorSnapshot = null;
      foxMemoryV2Log('向量回退', `reason=${foxMemoryConfig?.vectorMemory?.enabled ? 'config_incomplete' : 'disabled'} profile=${options.profile || 'mainline'}`);
      return null;
    }
    const queryText = foxMemoryBuildVectorQuery(userInput, options.recallFloors ?? 8);
    const atoms = foxMemoryGetCurrentAtoms();
    if (!queryText || !atoms.length) {
      state.foxMemoryVectorSnapshot = null;
      foxMemoryV2Log('向量回退', `reason=${!queryText ? 'empty_query' : 'no_atoms'}`);
      return null;
    }
    const signature = foxMemoryBuildVectorSignature(queryText, atoms);
    if (!options.force && state.foxMemoryVectorSnapshot?.signature === signature) {
      foxMemoryV2Log('向量快照复用', `signature=${signature} atoms=${state.foxMemoryVectorSnapshot.scores.size}`);
      return state.foxMemoryVectorSnapshot;
    }
    if (state.foxMemoryVectorPreparePromise?.signature === signature) return state.foxMemoryVectorPreparePromise.promise;
    const generation = ++state.foxMemoryVectorGeneration;

    const operation = (async () => {
      try {
        const vectors = await foxMemoryGetOrCreateVectors(atoms.map(atom => atom.text), generation);
        const queryVector = (await foxMemoryRequestEmbeddings([queryText]))[0];
        if (!queryVector) throw new Error('查询向量为空');
        const scores = new Map();
        for (const atom of atoms) {
          const vector = vectors.get(atom.text);
          if (!vector) continue;
          scores.set(atom.id, Math.max(0, foxMemoryCosineSimilarity(queryVector, vector)));
        }
        const snapshot = { signature, queryText, scores, createdAt: Date.now(), model: foxMemoryNormalizeVectorConfig().model };
        if (generation !== state.foxMemoryVectorGeneration) {
          foxMemoryV2Log('向量快照丢弃', `reason=superseded signature=${signature}`);
          return null;
        }
        state.foxMemoryVectorSnapshot = snapshot;
        foxMemoryV2Log('向量快照完成', `signature=${signature} atoms=${scores.size} model=${snapshot.model}`);
        return snapshot;
      } catch (e) {
        if (generation === state.foxMemoryVectorGeneration) state.foxMemoryVectorSnapshot = null;
        foxMemoryV2Log('向量回退', `reason=request_failed message=${e?.message || e}`);
        return null;
      } finally {
        if (state.foxMemoryVectorPreparePromise?.signature === signature) state.foxMemoryVectorPreparePromise = null;
      }
    })();
    const totalTimeout = Math.max(15000, foxMemoryNormalizeVectorConfig().timeoutMs + 10000);
    const promise = foxMemoryWithTimeout(operation, totalTimeout, '狐忆向量准备').catch(e => {
      if (generation === state.foxMemoryVectorGeneration) {
        state.foxMemoryVectorGeneration++;
        state.foxMemoryVectorSnapshot = null;
      }
      if (state.foxMemoryVectorPreparePromise?.signature === signature) state.foxMemoryVectorPreparePromise = null;
      foxMemoryV2Log('向量回退', `reason=total_timeout message=${foxMemoryRedactVectorError(e?.message || e)}`);
      return null;
    });
    state.foxMemoryVectorPreparePromise = { signature, promise };
    return promise;
  }

  function foxMemoryScheduleVectorSnapshot(userInput) {
    if (state.foxMemoryVectorInputTimer) clearTimeout(state.foxMemoryVectorInputTimer);
    state.foxMemoryVectorInputTimer = setTimeout(() => {
      state.foxMemoryVectorInputTimer = null;
      const isAdvance = foxMemoryConfig?.autoPush === true;
      foxMemoryPrepareVectorSnapshot(userInput, {
        profile: isAdvance ? 'advance' : 'mainline',
        recallFloors: isAdvance ? Math.max(1, parseInt(foxMemoryConfig?.recallFloors, 10) || 8) : 8,
      }).catch(e => foxMemoryV2Log('向量预计算失败', e?.message || e));
    }, 500);
  }

  function foxMemoryInvalidateVectorSnapshot(reason = 'unknown') {
    state.foxMemoryVectorGeneration++;
    state.foxMemoryVectorSnapshot = null;
    state.foxMemoryVectorPreparePromise = null;
    foxMemoryV2Log('向量快照失效', `reason=${reason}`);
  }

  let foxMemoryVectorInputListenerInstalled = false;
  let foxMemoryVectorSendGuardInstalled = false;
  let foxMemoryVectorSendProcessing = false;
  let foxMemoryVectorSendSkipNext = false;
  function foxMemoryInstallVectorInputListener() {
    if (!foxMemoryVectorInputListenerInstalled) {
      topDoc.addEventListener('input', event => {
        const target = event?.target;
        if (!target || target.id !== 'send_textarea') return;
        const value = String(target.value || '').trim();
        state.foxMemoryVectorLastInput = value;
        state.foxMemoryVectorGeneration++;
        state.foxMemoryVectorSnapshot = null;
        if (!value || value.startsWith('/') || !foxMemoryVectorConfigReady()) return;
        foxMemoryScheduleVectorSnapshot(value);
      }, true);
      foxMemoryVectorInputListenerInstalled = true;
      foxMemoryV2Log('向量监听', '已安装输入框防抖预计算监听');
    }

    if (!foxMemoryVectorSendGuardInstalled) {
      const handleSend = async (event, source) => {
        if (!foxMemoryVectorConfigReady() || foxMemoryConfig?.autoPush) return;
        // 🦊 与狐裁互斥：狐裁开启时由狐裁统一负责发送拦截，向量守门直接放行。
        //    否则两者会在同一发送事件上各自拦截、各自回发 click（skipNext ping-pong），
        //    造成重复处理/重复预计算，甚至在交错时把对方的回发误吞掉导致"点了发送没反应"。
        //    向量快照由输入监听持续预计算、统一注入时也会实时读取输入框，跳过发送前预计算不损失召回质量。
        try {
          if (localStorage.getItem(FOX_JUDGE_LS_KEYS.enabled) === 'true') return;
        } catch { }
        if (foxMemoryVectorSendSkipNext) {
          foxMemoryVectorSendSkipNext = false;
          return;
        }
        const ta = topDoc.getElementById('send_textarea');
        const original = String(ta?.value || '').trim();
        if (!ta || !original || original.startsWith('/')) return;
        if (foxMemoryVectorSendProcessing) {
          event.preventDefault();
          event.stopImmediatePropagation();
          toast('⏳ 狐忆正在准备语义召回，请稍候…', 'info');
          return;
        }
        event.preventDefault();
        event.stopImmediatePropagation();
        state.foxMemoryVectorLastInput = original;
        foxMemoryVectorSendProcessing = true;
        foxMemoryV2Log('发送前向量准备', `source=${source} inputChars=${original.length}`);
        try {
          await foxMemoryPrepareVectorSnapshot(original, { profile: 'mainline' });
          if (!ta.isConnected || String(ta.value || '').trim() !== original) {
            foxMemoryV2Log('发送取消', `reason=input_changed source=${source}`);
            toast('⚠️ 语义召回期间输入已修改，请重新发送', 'warning');
            return;
          }
          foxMemoryVectorSendSkipNext = true;
          setTimeout(() => topDoc.getElementById('send_but')?.click(), 0);
        } finally {
          foxMemoryVectorSendProcessing = false;
        }
      };
      topDoc.addEventListener('click', event => {
        if (!event.target?.closest?.('#send_but')) return;
        handleSend(event, 'click');
      }, true);
      topDoc.addEventListener('keydown', event => {
        if (event.key !== 'Enter' || event.shiftKey || !ssGetEnterListenEnabled()) return;
        if (!event.target?.closest?.('#send_textarea')) return;
        handleSend(event, 'keydown');
      }, true);
      foxMemoryVectorSendGuardInstalled = true;
