  function foxMemoryParseChunkRange(mem) {
    if (!mem) return null;

    const fs = Number(mem.floorStart);
    const fe = Number(mem.floorEnd);

    if (Number.isFinite(fs) && Number.isFinite(fe) && fs >= 0 && fe >= fs) {
      return { start: fs, end: fe };
    }

    const raw = `${mem.id || ''} ${mem.title || ''} ${mem.eventTime || ''}`;

    const m =
      raw.match(/plot_chunk_(\d+)_(\d+)/i) ||
      raw.match(/第\s*(\d+)\s*[-_—~～至到]\s*(\d+)\s*楼/);

    if (!m) return null;

    const start = Number(m[1]);
    const end = Number(m[2]);

    if (!Number.isFinite(start) || !Number.isFinite(end)) return null;

    return { start, end };
  }

  function foxMemoryIsPlotChunk(mem) {
    if (!mem || mem.category !== 'plot') return false;

    if (String(mem.id || '').startsWith(FOX_MEMORY_PLOT_CHUNK_PREFIX)) return true;

    return !!foxMemoryParseChunkRange(mem);
  }

  function foxMemorySortPlotChunks(chunks) {
    return [...(chunks || [])].sort((a, b) => {
      const ar = foxMemoryParseChunkRange(a) || { start: 0 };
      const br = foxMemoryParseChunkRange(b) || { start: 0 };
      return ar.start - br.start;
    });
  }

  function foxMemoryGetRecentTextForPlotRelevance(maxFloors = 8) {
    try {
      const glmi = getFn('getLastMessageId');
      const gcm = getFn('getChatMessages');

      if (!glmi || !gcm) return '';

      const lastId = glmi();
      if (lastId < 0) return '';

      const startId = Math.max(0, lastId - maxFloors + 1);
      const ms = gcm(`${startId}-${lastId}`, {
        hide_state: 'all',
        include_swipes: false,
      }) || [];

      return ms
        .map(m => {
          let msg = String(m?.message || '');
          try {
            msg = ssCleanXuanhuInjectedBlocksFromMessage(msg);
          } catch { }
          return `${m?.name || m?.role || ''}\n${msg}`;
        })
        .join('\n\n')
        .toLowerCase();
    } catch {
      return '';
    }
  }

  function foxMemoryRebaseLegacyDynamicSources(data = loadFoxMemory()) {
    if (data.dynamicSourceMigrationV1) return false;
    const lastFloor = foxMemoryDisplayFloorFromMessageId(getCurrentLastMessageId());
    if (!Number.isFinite(lastFloor) || lastFloor <= 0) return false;
    let changed = 0;
    const latestRange = foxMemoryGetPlotChunkRangeByMessageId(lastFloor);
    for (const stateItem of data.currentStates || []) {
      if (Number(stateItem?.floorEnd) <= 9 && latestRange.start > 9) {
        stateItem.floorStart = latestRange.start; stateItem.floorEnd = Math.min(latestRange.end, lastFloor); stateItem.sourceChunkId = latestRange.id; changed++;
      }
    }
    const chunks = (data.memories || []).filter(foxMemoryIsPlotChunk).map(chunk => ({ chunk, range: foxMemoryParseChunkRange(chunk), text: foxMemoryAtomFingerprint({ text: chunk.content || '' }) })).filter(item => item.range && item.text);
    const ngrams = value => {
      const text = foxMemoryAtomFingerprint({ text: value || '' });
      const set = new Set();
      for (const size of [3, 4]) for (let i = 0; i + size <= text.length; i++) set.add(text.slice(i, i + size));
      return set;
    };
    for (const atom of data.plotAtoms || []) {
      if (atom?.source === 'summary_line' || !chunks.length) continue;
      const atomGrams = ngrams(atom.text);
      if (!atomGrams.size) continue;
      const scored = chunks.map(item => {
        const chunkGrams = ngrams(item.chunk.content || '');
        let hits = 0;
        for (const gram of atomGrams) if (chunkGrams.has(gram)) hits++;
        return { ...item, score: hits / atomGrams.size };
      }).sort((a, b) => b.score - a.score);
      const best = scored[0];
      const current = scored.find(item => item.range.start === Number(atom.floorStart));
      if (best?.score >= 0.12 && best.score > Number(current?.score || 0) + 0.08) {
        atom.floorStart = best.range.start; atom.floorEnd = best.range.end; atom.sourceChunkId = best.chunk.id; atom.eventTime = `第${best.range.start}-${best.range.end}楼`; changed++;
        foxMemoryV2Log('原子来源修正', `id=${atom.id} target=${best.range.start}-${best.range.end} score=${best.score.toFixed(2)}`);
      }
    }
    data.dynamicSourceMigrationV1 = true;
    if (changed && saveFoxMemory(data)) foxMemoryV2Log('旧动态来源修正完成', `changed=${changed} target=${latestRange.start}-${Math.min(latestRange.end, lastFloor)}`);
    else if (!changed) saveFoxMemory(data);
    return changed > 0;
  }

  function foxMemoryScorePlotChunk(chunk, refText, currentFloor) {
    const range = foxMemoryParseChunkRange(chunk);
    if (!range) return 0;

    let score = 0;

    if (currentFloor >= range.start && currentFloor <= range.end) {
      score += 1000;
    }

    // 越接近当前楼层，分数越高。
    if (range.end <= currentFloor) {
      score += Math.max(0, 100 - Math.floor((currentFloor - range.end) / FOX_MEMORY_PLOT_CHUNK_SIZE) * 10);
    }

    const ref = String(refText || '').toLowerCase();

    for (const kw of chunk.keywords || []) {
      const k = String(kw || '').trim().toLowerCase();
      if (k && ref.includes(k)) score += 30;
    }

    const title = String(chunk.title || '').toLowerCase();
    if (title && ref.includes(title)) score += 20;

    return score;
  }

  function foxMemorySelectPlotChunksForInjection(memories, options = {}) {
    const maxChunks = Math.max(0, Number(options.maxPlotChunks ?? 999));
    if (maxChunks <= 0) return [];

    const chunks = foxMemorySortPlotChunks(
      (memories || []).filter(foxMemoryIsPlotChunk)
    );

    if (!chunks.length) return [];

    const currentMessageId = getCurrentLastMessageId();
    const currentFloor = foxMemoryDisplayFloorFromMessageId(currentMessageId);
    const refText = foxMemoryGetRecentTextForPlotRelevance(8);

    const selected = [];
    const selectedIds = new Set();

    const push = (m) => {
      if (!m || selectedIds.has(m.id)) return;
      selected.push(m);
      selectedIds.add(m.id);
    };

    // 1. 当前楼层所在板块必须优先。
    const currentChunk = chunks.find(c => {
      const r = foxMemoryParseChunkRange(c);
      return r && currentFloor >= r.start && currentFloor <= r.end;
    });
    push(currentChunk);

    // 2. 最近的板块必须保留，方便承接。
    push(chunks[chunks.length - 1]);

    // 3. 根据关键词相关性补充少量旧板块。
    const scored = chunks
      .map(c => ({
        chunk: c,
        score: foxMemoryScorePlotChunk(c, refText, currentFloor),
      }))
      .filter(x => x.score > 0)
      .sort((a, b) => b.score - a.score);

    for (const item of scored) {
      if (selected.length >= maxChunks) break;
      push(item.chunk);
    }

    return foxMemorySortPlotChunks(selected).slice(0, maxChunks);
  }

  function foxMemoryFormatOneMemoryForInject(m) {
    const cat = FOX_MEMORY_CATEGORIES.find(c => c.id === m.category) || { label: m.category };
    const timeStr = m.eventTime ? `（${m.eventTime}）` : '';
    const kw = m.keywords?.length ? `\n关键词：${m.keywords.join('、')}` : '';
    let content = String(m.content || '');
    if (m.category === 'character') {
      content = content.split(/(?<=[。！？!?])\s*/).filter(sentence => !/^(目前|当前|正在|现位于|现穿着|眼下|此刻)/.test(sentence.trim())).join('').trim() || content;
    }
    return `【${cat.label}】${m.title}${timeStr}\n${content}${kw}`;
  }

  // 🦊 狐忆：用一条记忆的 keywords 作为正则，逐个匹配最近上下文文本。
  // 命中任意一个关键词即视为相关。返回命中的关键词数组（空数组=未命中）。
  function foxMemoryMatchKeywordsAgainstContext(keywords, contextLower) {
    const hits = [];
    if (!Array.isArray(keywords) || !keywords.length) return hits;
    if (!contextLower) return hits;

    for (const raw of keywords) {
      const kw = String(raw || '').trim();
      if (!kw) continue;
      let matched = false;
      try {
        // 关键词本身可能含正则元字符，做一次转义后作为正则匹配（大小写不敏感）。
        const re = new RegExp(kw.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
        matched = re.test(contextLower);
      } catch {
        // 极端情况下转义仍失败则退化为纯字符串包含匹配。
        matched = contextLower.includes(kw.toLowerCase());
      }
      if (matched) hits.push(kw);
    }
    return hits;
  }

  function foxMemoryRetrieveNonPlotMemories(memories, queryText) {
    const query = String(queryText || '').toLowerCase();
    const selected = [];
    for (const mem of Array.isArray(memories) ? memories : []) {
      if (!mem || mem.category === 'plot') continue;
      const terms = foxMemoryNormalizeList([mem.title || '', ...(mem.keywords || [])]);
      const hits = foxMemoryMatchKeywordsAgainstContext(terms, query);
      if (!hits.length) continue;
      const normalized = foxMemoryNormalizeStoredMemory(mem) || mem;
      const titleHit = String(normalized.title || '') && query.includes(String(normalized.title).toLowerCase()) ? 1 : 0;
      const score = hits.length * 0.3 + titleHit * 0.25 + Number(normalized.strength || 0.55) * 0.3 + (normalized.pinned ? 0.15 : 0);
      selected.push({ mem: normalized, score });
      foxMemoryV2Log('长期记忆命中', `id=${mem.id} category=${mem.category} hits=${hits.join(',')}`);
    }
    return selected.sort((a, b) => b.score - a.score || Number(b.mem.lastMentionFloor || 0) - Number(a.mem.lastMentionFloor || 0)).map(item => item.mem);
  }

  function foxMemoryGetCurrentAtoms() {
    const data = loadFoxMemory();
    const currentFloor = foxMemoryDisplayFloorFromMessageId(getCurrentLastMessageId());
    return Array.isArray(data.plotAtoms) ? data.plotAtoms
      .map(foxMemoryNormalizeStoredAtom)
      .filter(Boolean)
      .filter(atom => {
        if (atom.floorStart <= currentFloor) return true;
        foxMemoryV2Log('原子拒绝', `id=${atom.id} reason=future_floor atomStart=${atom.floorStart} currentFloor=${currentFloor}`);
        return false;
      }) : [];
  }

  function foxMemoryDetectQueryIntent(queryText, profile = 'mainline') {
    const query = String(queryText || '').toLowerCase();
    let intent = profile === 'advance' ? 'advance' : 'general';
    if (/哪里|何处|位置|去哪|在哪/.test(query)) intent = 'location';
    else if (/为什么|原因|怎么会|为何|导致|起因/.test(query)) intent = 'cause';
    else if (/以前|之前|曾经|当时|过去|发生过|回忆/.test(query)) intent = 'history';
    else if (/承诺|答应|约定|任务|计划|目标|伏笔|还没|未完成|接下来/.test(query)) intent = 'unresolved';
    else if (/谁|身份|是什么人|关系/.test(query)) intent = 'identity';
    else if (/现在|目前|当前|此刻|如今|还在|还会|能不能|怎么样了/.test(query)) intent = 'current_state';
    const wantsHistory = intent === 'history' || /曾经|过去|当时|之前/.test(query);
    const result = { intent, profile, wantsHistory };
    foxMemoryV2Log('查询意图', `profile=${profile} intent=${intent} wantsHistory=${wantsHistory}`);
    return result;
  }

  function foxMemoryGetIntentWeights(intentInfo) {
    const weights = { entity: 0.28, keyword: 0.17, location: 0.10, lexical: 0.11, importance: 0.10, recency: 0.08, validity: 0.09, unresolved: 0.07 };
    switch (intentInfo.intent) {
      case 'current_state': Object.assign(weights, { recency: 0.15, validity: 0.18, entity: 0.25, unresolved: 0.02 }); break;
      case 'location': Object.assign(weights, { location: 0.24, recency: 0.14, validity: 0.16, entity: 0.22 }); break;
      case 'cause': Object.assign(weights, { lexical: 0.17, keyword: 0.20, importance: 0.14, recency: 0.04 }); break;
      case 'history': Object.assign(weights, { recency: 0.02, validity: 0.03, lexical: 0.17, keyword: 0.20, importance: 0.13 }); break;
      case 'unresolved': Object.assign(weights, { unresolved: 0.24, importance: 0.15, validity: 0.14, recency: 0.08 }); break;
      case 'advance': Object.assign(weights, { unresolved: 0.22, importance: 0.15, recency: 0.12, validity: 0.13 }); break;
      case 'identity': Object.assign(weights, { entity: 0.35, keyword: 0.18, validity: 0.12, recency: 0.03 }); break;
    }
    const sum = Object.values(weights).reduce((a, b) => a + b, 0) || 1;
    for (const key of Object.keys(weights)) weights[key] /= sum;
    return weights;
  }

  function foxMemoryTextSimilarity(leftAtom, rightAtom) {
    const left = new Set(foxMemoryNormalizeList([...(leftAtom?.entities || []), ...(leftAtom?.keywords || []), ...(leftAtom?.locations || [])]).map(x => x.toLowerCase()));
    const right = new Set(foxMemoryNormalizeList([...(rightAtom?.entities || []), ...(rightAtom?.keywords || []), ...(rightAtom?.locations || [])]).map(x => x.toLowerCase()));
    if (!left.size || !right.size) return foxMemoryAtomFingerprint(leftAtom) === foxMemoryAtomFingerprint(rightAtom) ? 1 : 0;
    let intersection = 0;
    for (const value of left) if (right.has(value)) intersection++;
    return intersection / (left.size + right.size - intersection);
  }

  function foxMemoryGetRelevantCurrentStates(queryText, intentInfo, maxStates = 8) {
    const currentFloor = foxMemoryDisplayFloorFromMessageId(getCurrentLastMessageId());
    const states = (loadFoxMemory().currentStates || []).map(foxMemoryNormalizeCurrentState).filter(Boolean).filter(item => item.status === 'active' && item.floorStart <= currentFloor);
    const query = String(queryText || '').toLowerCase();
    const scored = states.map(item => {
      const subjectHit = query.includes(item.subject.toLowerCase()) ? 1 : 0;
      const fieldHit = query.includes(item.field.toLowerCase()) ? 1 : 0;
      const valueTerms = foxMemoryNormalizeList(item.value.split(/[，。；、\s]+/)).filter(term => term.length >= 2);
      const valueHit = foxMemoryMatchKeywordsAgainstContext(valueTerms, query).length ? 1 : 0;
      const intentBoost = intentInfo.intent === 'current_state' ? 0.25 : intentInfo.intent === 'location' && /位置/.test(item.field) ? 0.35 : intentInfo.intent === 'unresolved' && /目标/.test(item.field) ? 0.25 : 0;
      return { item, score: subjectHit * 0.40 + fieldHit * 0.17 + valueHit * 0.13 + item.importance * 0.08 + Number(item.strength || 0.65) * 0.12 + (item.pinned ? 0.08 : 0) + intentBoost };
    }).sort((a, b) => b.score - a.score || b.item.floorEnd - a.item.floorEnd || b.item.importance - a.item.importance);
    const matched = scored.filter(entry => entry.score >= 0.2).slice(0, maxStates).map(entry => entry.item);
    if (matched.length) return matched;
    if (intentInfo.profile === 'advance' || intentInfo.intent === 'advance' || intentInfo.intent === 'current_state') {
      const fallback = [...states].sort((a, b) => b.floorEnd - a.floorEnd || b.importance - a.importance).slice(0, Math.min(maxStates, 4));
      foxMemoryV2Log('状态兜底', `profile=${intentInfo.profile} intent=${intentInfo.intent} selected=${fallback.length}`);
      return fallback;
    }
    return states.length && !foxMemoryGetCurrentAtoms().length
      ? [...states].sort((a, b) => b.importance - a.importance || b.floorEnd - a.floorEnd).slice(0, Math.min(maxStates, 3))
      : [];
  }

  function foxMemoryFormatCurrentState(item) {
    return `- ${item.subject}｜${item.field}：${item.value}（更新于第${item.floorStart}-${item.floorEnd}楼）`;
  }

  function foxMemoryBuildCharacterSnapshotBlock(queryText, intentInfo, budget) {
    const data = loadFoxMemory();
    const scene = foxMemoryNormalizeSceneSnapshot(data.sceneSnapshot);
    const snapshots = Object.values(data.characterSnapshots || {}).map(item => foxMemoryNormalizeCharacterSnapshot(item)).filter(Boolean);
    if (!snapshots.length || budget <= 0) return { text: '', selected: [] };
    const query = String(queryText || '').toLowerCase();
    const present = new Set(scene.presentCharacters.map(name => name.toLowerCase()));
    const ranked = snapshots.map(item => ({
      item,
      score: (present.has(item.name.toLowerCase()) ? 100 : 0) + (query.includes(item.name.toLowerCase()) ? 80 : 0) + (item.active ? 10 : 0) + Math.min(9, item.updatedAtFloor / 1000),
    })).filter(entry => entry.score >= 80 || (intentInfo.profile === 'advance' && entry.item.active)).sort((a, b) => b.score - a.score).slice(0, 8);
    const header = `【🎭 当前场景角色快照】\n场景：${scene.locationKey || '未明确'}\n在场：${scene.presentCharacters.join('、') || '未明确'}`;
    const selected = [];
    const cards = [];
    for (const { item } of ranked) {
      const lines = [];
      const location = [item.location.city, item.location.area, item.location.building, item.location.interior].filter(Boolean).join('·');
      if (location) lines.push(`位置：${location}`);
      if (item.location.posture) lines.push(`姿态：${item.location.posture}`);
      const physiology = Object.entries(item.physiology).filter(([, value]) => value && !/^(无|正常|未知)$/.test(value)).map(([key, value]) => `${({ health: '身体', fatigue: '疲劳', cleanliness: '清洁', pain: '疼痛', hunger: '饥饿', thirst: '口渴', consciousness: '意识', mobility: '行动' })[key]}=${value}`);
      if (physiology.length) lines.push(`生理：${physiology.join('；')}`);
      const appearance = [item.appearance.outerwear, item.appearance.upperBody, item.appearance.lowerBody, item.appearance.underwear, item.appearance.footwear, item.appearance.accessories].filter(value => value && value !== '未知');
      if (appearance.length) lines.push(`着装：${appearance.join('；')}`);
      if (item.appearance.exposure) lines.push(`暴露：${item.appearance.exposure}`);
      if (item.appearance.condition) lines.push(`衣物状态：${item.appearance.condition}`);
      if (item.mind.emotion) lines.push(`情绪：${item.mind.emotion}`);
      if (item.mind.currentGoal) lines.push(`当前目标：${item.mind.currentGoal}`);
      if (item.social.relationToUser || item.social.attitudeToUser) lines.push(`对用户：${[item.social.relationToUser, item.social.attitudeToUser].filter(Boolean).join('；')}`);
      if (item.future.todos.length) lines.push(`待办：${item.future.todos.join('；')}`);
      if (item.future.commitments.length) lines.push(`约定：${item.future.commitments.join('；')}`);
      if (intentInfo.intent === 'identity') {
        const profile = [item.profile.age, item.profile.gender, item.profile.identity, item.profile.personality].filter(Boolean);
        if (profile.length) lines.unshift(`稳定档案：${profile.join('；')}`);
      }
      if (!lines.length) continue;
      const card = `${item.name}：\n- ${lines.join('\n- ')}`;
      const tentative = `${header}\n\n${[...cards, card].join('\n\n')}`;
      if (tentative.length > budget) break;
      cards.push(card);
      selected.push(item);
    }
    const text = cards.length ? `${header}\n\n${cards.join('\n\n')}` : '';
    foxMemoryV2Log('角色快照选择', `profile=${intentInfo.profile} present=${scene.presentCharacters.length} candidates=${ranked.length} selected=${selected.length} chars=${text.length} budget=${budget}`);
    return { text, selected };
  }

  function foxMemoryScoreAtom(atom, queryText, currentFloor, intentInfo) {
    const query = String(queryText || '').toLowerCase();
    const entities = foxMemoryNormalizeList([...(atom.entities || []), ...(atom.subjects || []), ...(atom.objects || [])]);
    const locations = foxMemoryNormalizeList(atom.locations || []);
    const keywords = foxMemoryNormalizeList(atom.keywords || []);
    const entityHits = foxMemoryMatchKeywordsAgainstContext(entities, query);
    const locationHits = foxMemoryMatchKeywordsAgainstContext(locations, query);
    const keywordHits = foxMemoryMatchKeywordsAgainstContext(keywords, query);
    const importance = Math.max(0, Math.min(1, Number(atom.importance) || 0.5));
    const end = Number(atom.floorEnd);
    const distance = Number.isFinite(end) ? Math.max(0, currentFloor - end) : 100;
    const recency = Math.max(0, 1 - distance / 200);
    const text = foxMemoryNormalizeAtomText(atom.text || atom.content).toLowerCase();
    const wordTerms = query.split(/[\s，。！？；：、,.!?;:'"“”‘’（）()《》【】\[\]]+/).map(x => x.trim()).filter(x => x.length >= 2);
    const cjkSource = query.replace(/[^\u3400-\u9fff]/g, '');
    const cjkTerms = [];
    for (const size of [2, 3, 4]) {
      for (let i = 0; i + size <= cjkSource.length; i++) cjkTerms.push(cjkSource.slice(i, i + size));
    }
    const queryTerms = [...new Set([...wordTerms, ...cjkTerms])].slice(0, 400);
    const textTermHits = queryTerms.filter(term => text.includes(term));

    const entityScore = entities.length ? Math.min(1, entityHits.length / Math.min(2, entities.length)) : 0;
    const locationScore = locations.length ? Math.min(1, locationHits.length / locations.length) : 0;
    const keywordScore = keywords.length ? Math.min(1, keywordHits.length / Math.min(3, keywords.length)) : 0;
    const lexicalScore = queryTerms.length ? Math.min(1, textTermHits.length / Math.min(4, queryTerms.length)) : 0;
    const validity = atom.validity === 'inactive' ? (intentInfo.wantsHistory ? 0.65 : 0) : atom.validity === 'uncertain' ? 0.45 : 1;
    const unresolved = atom.unresolved ? 1 : 0;
    const strength = Math.max(0.05, Math.min(1, Number(atom.strength) || 0.55));
    const permanence = atom.permanence === 'permanent' ? 1 : atom.permanence === 'temporary' ? Math.max(0, recency - 0.15) : 0.55;
    const weights = foxMemoryGetIntentWeights(intentInfo);
    let localTotal = entityScore * weights.entity + keywordScore * weights.keyword + locationScore * weights.location
      + lexicalScore * weights.lexical + importance * weights.importance + recency * weights.recency
      + validity * weights.validity + unresolved * weights.unresolved;
    localTotal = Math.min(1, localTotal + strength * 0.09 + (atom.pinned ? 0.04 : 0) + (intentInfo.intent === 'identity' && atom.permanence === 'permanent' ? 0.06 : permanence * 0.02));
    const vectorConfig = foxMemoryNormalizeVectorConfig();
    const vectorScore = vectorConfig.enabled ? Number(state.foxMemoryVectorSnapshot?.scores?.get(atom.id) || 0) : 0;
    const vectorWeight = vectorScore >= vectorConfig.minScore ? vectorConfig.weight : 0;
    const total = localTotal * (1 - vectorWeight) + vectorScore * vectorWeight;

    return {
      atom,
      total,
      scores: { entity: entityScore, keyword: keywordScore, location: locationScore, lexical: lexicalScore, importance, strength, recency, validity, unresolved, permanence, local: localTotal, vector: vectorScore, vectorWeight },
      hits: { entities: entityHits, keywords: keywordHits, locations: locationHits, terms: textTermHits },
      hasDirectHit: entityHits.length > 0 || keywordHits.length > 0 || locationHits.length > 0 || textTermHits.length > 0,
      hasVectorHit: vectorScore >= vectorConfig.minScore,
    };
  }

  function foxMemoryRetrievePlotAtoms(options = {}) {
    const atoms = foxMemoryGetCurrentAtoms();
    const queryText = String(options.queryText || foxMemoryGetRecentTextForPlotRelevance(options.matchContextFloors ?? 8) || '').trim();
    const profile = options.profile || 'mainline';
    const charBudget = options.charBudget === undefined
      ? FOX_MEMORY_ATOM_DEFAULT_BUDGET
      : Math.max(0, Number(options.charBudget) || 0);
    const maxAtoms = Math.max(1, Number(options.maxAtoms) || (profile === 'advance' ? 16 : 12));
    const currentFloor = foxMemoryDisplayFloorFromMessageId(getCurrentLastMessageId());
    const intentInfo = foxMemoryDetectQueryIntent(options.intentText || queryText, profile);
    const expectedVectorSignature = foxMemoryBuildVectorSignature(queryText, atoms);
    if (state.foxMemoryVectorSnapshot && state.foxMemoryVectorSnapshot.signature !== expectedVectorSignature) {
      foxMemoryV2Log('向量回退', `reason=stale_snapshot expected=${expectedVectorSignature} actual=${state.foxMemoryVectorSnapshot.signature}`);
      state.foxMemoryVectorSnapshot = null;
    }

    foxMemoryV2Log('召回查询', `profile=${profile} atoms=${atoms.length} queryChars=${queryText.length} budget=${charBudget} maxAtoms=${maxAtoms}`);
    if (!atoms.length || !queryText || charBudget <= 0) {
      foxMemoryV2Log('召回完成', `candidates=${atoms.length} selected=0 reason=${!atoms.length ? 'no_atoms' : !queryText ? 'empty_query' : 'no_budget'}`);
      return [];
    }

    const scored = atoms.map(atom => foxMemoryScoreAtom(atom, queryText, currentFloor, intentInfo));
    for (const item of scored) {
      const s = item.scores;
      foxMemoryV2Log('候选评分', `id=${item.atom.id} entity=${s.entity.toFixed(2)} keyword=${s.keyword.toFixed(2)} location=${s.location.toFixed(2)} lexical=${s.lexical.toFixed(2)} importance=${s.importance.toFixed(2)} recency=${s.recency.toFixed(2)} validity=${s.validity.toFixed(2)} unresolved=${s.unresolved.toFixed(2)} local=${s.local.toFixed(3)} vector=${s.vector.toFixed(3)} weight=${s.vectorWeight.toFixed(2)} total=${item.total.toFixed(3)}`, item.hits);
    }

    const candidates = scored
      .filter(x => (intentInfo.wantsHistory || x.atom.validity !== 'inactive') && (x.hasDirectHit || x.hasVectorHit || (profile === 'advance' && x.atom.unresolved)))
      .sort((a, b) => b.total - a.total || Number(b.atom.floorEnd || 0) - Number(a.atom.floorEnd || 0));
    const selected = [];
    const seen = new Set();
    let usedChars = 0;

    const remaining = [...candidates];
    while (remaining.length && selected.length < maxAtoms) {
      let bestIndex = 0;
      let bestMmr = -Infinity;
      for (let i = 0; i < remaining.length; i++) {
        const diversityPenalty = selected.length ? Math.max(...selected.map(atom => foxMemoryTextSimilarity(remaining[i].atom, atom))) : 0;
        const mmr = remaining[i].total * 0.78 - diversityPenalty * 0.22;
        if (mmr > bestMmr) { bestMmr = mmr; bestIndex = i; }
      }
      if (bestMmr < 0.05) {
        foxMemoryV2Log('候选停止', `reason=low_mmr best=${bestMmr.toFixed(3)} remaining=${remaining.length}`);
        break;
      }
      const item = remaining.splice(bestIndex, 1)[0];
      if (selected.length >= maxAtoms) break;
      const fingerprint = foxMemoryAtomFingerprint(item.atom);
      if (!fingerprint || seen.has(fingerprint)) {
        foxMemoryV2Log('候选拒绝', `id=${item.atom.id} reason=${fingerprint ? 'duplicate' : 'empty_text'}`);
        continue;
      }
      const formatted = foxMemoryFormatAtomForInject(item.atom);
      if (usedChars + formatted.length > charBudget) {
        foxMemoryV2Log('候选拒绝', `id=${item.atom.id} reason=budget used=${usedChars} next=${formatted.length} budget=${charBudget}`);
        continue;
      }
      selected.push(item.atom);
      seen.add(fingerprint);
      usedChars += formatted.length;
      foxMemoryV2Log('候选选中', `id=${item.atom.id} score=${item.total.toFixed(3)} mmr=${bestMmr.toFixed(3)} chars=${formatted.length} used=${usedChars}`);
    }

    foxMemoryV2Log('召回完成', `candidates=${candidates.length} selected=${selected.length} chars=${usedChars} budget=${charBudget}`);
    return selected;
  }

  function foxMemoryBuildMemoryBodyForInject(memories, options = {}) {
    try { foxMemoryRebaseLegacyDynamicSources(); } catch (e) { foxMemoryV2Log('来源修正失败', e?.message || e); }
    const arr = Array.isArray(memories) ? memories : [];
    const queryText = String(options.queryText || foxMemoryGetRecentTextForPlotRelevance(options.matchContextFloors ?? 8));
    const intentInfo = foxMemoryDetectQueryIntent(options.intentText || queryText, options.profile || 'mainline');
    const totalBudget = Math.max(200, Number(options.charBudget) || FOX_MEMORY_ATOM_DEFAULT_BUDGET);
    const snapshotResult = foxMemoryBuildCharacterSnapshotBlock(queryText, intentInfo, Math.floor(totalBudget * 0.42));
    const snapshotBlock = snapshotResult.text;
    const snapshotChars = snapshotBlock.length;
    const stateHeader = '【📍 当前有效状态】\n以下是最新有效值；若与历史事件冲突，以这里为当前状态：';
    const stateCandidates = foxMemoryGetRelevantCurrentStates(queryText, intentInfo, options.profile === 'advance' ? 10 : 8);
    const currentStates = [];
    let stateBlock = '';
    for (const item of stateCandidates) {
      const tentative = `${stateHeader}\n${[...currentStates, item].map(foxMemoryFormatCurrentState).join('\n')}`;
      if (tentative.length > Math.max(0, totalBudget * 0.45 - snapshotChars)) break;
      currentStates.push(item);
      stateBlock = tentative;
    }
    const stateChars = stateBlock.length;
    const plotWrapperReserve = '【📖 相关剧情信息句】\n以下内容经过实体、关键词、地点、重要度和时间距离联合评分；每行是一条独立事实：\n'.length;
    const retrievalOptions = { ...options, queryText, intentText: options.intentText, charBudget: Math.max(0, totalBudget - snapshotChars - stateChars - plotWrapperReserve) };
    const storedAtomCount = foxMemoryGetCurrentAtoms().length;
    const plotAtoms = foxMemoryRetrievePlotAtoms(retrievalOptions);

    const plotChunks = foxMemorySortPlotChunks(arr.filter(foxMemoryIsPlotChunk));
    const selectedPlotChunks = storedAtomCount > 0 ? [] : foxMemorySelectPlotChunksForInjection(arr, {
      maxPlotChunks: options.maxPlotChunks ?? 999,
    });

    const parts = [];
    if (snapshotBlock) parts.push(snapshotBlock);
    if (stateBlock) {
      parts.push(stateBlock);
      foxMemoryV2Log('状态注入', `profile=${options.profile || 'mainline'} selected=${currentStates.length} chars=${stateChars}`);
    }

    if (plotAtoms.length) {
      const plotBlock = `【📖 相关剧情信息句】
以下内容经过实体、关键词、地点、重要度和时间距离联合评分；每行是一条独立事实：
${plotAtoms.map(foxMemoryFormatAtomForInject).join('\n')}`;
      if (parts.join('\n\n').length + plotBlock.length <= totalBudget) parts.push(plotBlock);
    } else if (plotChunks.length && storedAtomCount === 0) {
      foxMemoryV2Log('旧数据回退', `plotAtoms=0 selectedChunks=${selectedPlotChunks.length}，使用旧十楼摘要块`);
      const indexCandidates = plotChunks.map(c => {
        const r = foxMemoryParseChunkRange(c);
        const rangeText = r ? `第${r.start}-${r.end}楼` : (c.eventTime || '');
        return `- ${rangeText}：${c.title}`;
      });

      const expandedLines = selectedPlotChunks.length
        ? selectedPlotChunks.map(c => c.title).join('、')
        : '无';

      const legacyHeader = `【📖 情节摘要索引】
剧情摘要已按每 ${FOX_MEMORY_PLOT_CHUNK_SIZE} 楼一个板块保存，并严格按时间顺序排列。
不要一次性要求读取全部剧情摘要；只有当前剧情相关时，才参考被展开的板块。

可用剧情摘要板块：
`;
      const legacyFooter = `\n\n本次已展开的相关板块：\n${expandedLines}`;
      const available = Math.max(0, totalBudget - parts.join('\n\n').length - legacyHeader.length - legacyFooter.length);
      const kept = [];
      let used = 0;
      for (const line of [...indexCandidates].reverse()) {
        if (used + line.length + 1 > available) break;
        kept.unshift(line);
        used += line.length + 1;
      }
      const legacyBlock = `${legacyHeader}${kept.length < indexCandidates.length ? `- ……已省略 ${indexCandidates.length - kept.length} 个较旧板块\n` : ''}${kept.join('\n')}${legacyFooter}`;
      if (legacyBlock.length + parts.join('\n\n').length <= totalBudget) parts.push(legacyBlock);
    }

    for (const chunk of selectedPlotChunks) {
      const formatted = foxMemoryFormatOneMemoryForInject(chunk);
      if (parts.join('\n\n').length + formatted.length <= totalBudget) parts.push(formatted);
    }

    // 非剧情摘要类长期记忆：
    // - 默认（注入到预设同步 / 狐推只读回忆等路径）：全量注入，保持"记忆全貌"语义。
    // - 仅当 options.keywordFilterByContext === true（"插入到当前提示词"路径）时：
    //   按关键词正则匹配最近上下文，命中才注入；没填关键词或未命中的跳过。
    // 注意：旧版 plot_summary 和所有未分块 plot 不再默认注入，避免再次塞爆上下文。
    const nonPlotMemories = arr.filter(m => m.category !== 'plot');

    const enableKeywordFilter = options.keywordFilterByContext === true;
    const contextLower = enableKeywordFilter
      ? String(options.queryText || foxMemoryGetRecentTextForPlotRelevance(options.matchContextFloors ?? 8)).toLowerCase()
      : '';

    // 记录命中详情，供调用方弹 toast 使用。
    const matchedHitKeywords = [];
    let matchedCount = 0;

    const filteredNonPlotMemories = enableKeywordFilter
      ? foxMemoryRetrieveNonPlotMemories(nonPlotMemories, contextLower)
      : nonPlotMemories;
    const sharedBudget = totalBudget;
    let usedChars = parts.join('\n\n').length;

    for (const mem of filteredNonPlotMemories) {
      const formatted = foxMemoryFormatOneMemoryForInject(mem);
      if (usedChars + formatted.length > sharedBudget) {
        foxMemoryV2Log('长期记忆拒绝', `id=${mem.id} reason=budget used=${usedChars} next=${formatted.length} budget=${sharedBudget}`);
        continue;
      }
      if (enableKeywordFilter) {
        const hits = foxMemoryMatchKeywordsAgainstContext([mem.title || '', ...(mem.keywords || [])], contextLower);
        parts.push(formatted);
        matchedCount++;
        for (const k of hits) matchedHitKeywords.push(k);
      } else {
        parts.push(formatted);
      }
      usedChars += formatted.length;
    }

    // 把命中信息挂到 options 上回传（不改变返回值类型，保持兼容）。
    if (enableKeywordFilter && options && typeof options === 'object') {
      options.__matchedNonPlotCount = matchedCount;
      options.__matchedNonPlotKeywords = [...new Set(matchedHitKeywords)];
    }
    if (options && typeof options === 'object') options.__selectedPlotAtomCount = plotAtoms.length;
    if (options && typeof options === 'object') options.__selectedCurrentStateCount = currentStates.length;
    if (options && typeof options === 'object') options.__selectedCharacterSnapshotCount = snapshotResult.selected.length;
    if (options && typeof options === 'object') {
      options.__selectedPlotAtomIds = plotAtoms.map(atom => String(atom.id));
      options.__selectedCurrentStateIds = currentStates.map(item => String(item.id || item.key));
      options.__selectedNonPlotMemoryIds = filteredNonPlotMemories
        .filter(mem => parts.includes(foxMemoryFormatOneMemoryForInject(mem)))
        .map(mem => String(mem.id));
    }

    return parts.filter(x => String(x || '').trim()).join('\n\n').trim();
  }
  function foxMemoryGetCurrent() {
    const data = loadFoxMemory();
    return data.memories || [];
  }

  function foxMemorySave(memories) {
    const data = loadFoxMemory();

    data.memories = Array.isArray(memories) ? memories : [];
    data.lastAnalysis = data.lastAnalysis || new Date().toISOString();

    const ok = saveFoxMemory(data);

    // ✅ 狐忆实时同步：
    // 只要用户打开了「注入到预设」，任何新增、编辑、删除、清空、导入都会同步到预留条目5。
    if (ok && foxMemoryConfig?.injectToPreset) {
      try {
        foxMemorySyncToPreset();
      } catch (e) {
        log('[狐忆] 实时同步预设失败:', e);
      }
    }

    return ok;
  }

  // ==================== 狐忆楼层删除/编辑后的自动修复 ====================
  let foxMemoryRepairHandles = [];
  // 🦊 记录上次该楼层"编辑/删除事件触发修复后"的楼层内容指纹；
  //    MESSAGE_EDITED 到达时若指纹相等，说明编辑弹窗开了却没改内容，跳过修复，以免误清正确记忆。
  const foxMemoryLastEditSeenFp = new Map();

  function foxMemoryExtractFloorRefsFromText(text) {
    const raw = String(text || '');
    const refs = [];

    const re = /第\s*(\d+)(?:\s*[-_—~～至到]\s*(\d+))?\s*楼/g;
    let m;

    while ((m = re.exec(raw)) !== null) {
      const start = Number(m[1]);
      const end = Number(m[2] || m[1]);

      if (Number.isFinite(start) && Number.isFinite(end)) {
        refs.push([Math.min(start, end), Math.max(start, end)]);
      }
    }

    return refs;
  }

  function foxMemoryRepairAfterChatChanged(reason = '聊天记录变化', changedFromFloor = null, opts = {}) {
    try {
      const glmi = getFn('getLastMessageId');
      if (!glmi) return;

      const lastId = glmi();
      const affected = Number(changedFromFloor);
      const hasAffected = Number.isFinite(affected) && affected >= 0;

      const memories = foxMemoryGetCurrent();
      const data = loadFoxMemory();
      let removed = 0;

      if (hasAffected) {
        state.foxMemoryBranchEpoch++;
        state.foxMemoryPendingBranchCheckpoint = null;
        const turnCandidate = (data.checkpoints?.turns || []).map(foxMemoryNormalizeCheckpoint).filter(Boolean).filter(cp => cp.floor === affected).sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)))[0];
        const chunkCandidate = (data.checkpoints?.chunks || []).map(foxMemoryNormalizeCheckpoint).filter(Boolean).filter(cp => cp.floor < affected).sort((a, b) => b.floor - a.floor)[0];
        const checkpoint = turnCandidate || chunkCandidate;
        if (checkpoint && foxMemoryRestoreCheckpoint(checkpoint, reason)) {
          const restoredData = loadFoxMemory();
          restoredData.checkpoints = {
            turns: (restoredData.checkpoints?.turns || []).filter(cp => Number(cp.floor) < affected),
            chunks: (restoredData.checkpoints?.chunks || []).filter(cp => Number(cp.floor) < affected),
          };
          saveFoxMemory(restoredData);
          foxMemoryV2Log('楼层修复', `reason=${reason} changedFrom=${affected} mode=checkpoint checkpointFloor=${checkpoint.floor}`);
          if (opts.reanalyze && foxMemoryConfig?.autoMode !== 'manual') {
            setTimeout(() => foxMemoryAnalyzeNow().catch(e => log('[狐忆楼层修复] 自动重分析失败', e)), 1200);
          }
          // 🦊 同样在 checkpoint 回退成功后记录指纹，避免重复回退
          try { const m = foxMemoryGetMessageBranchMeta(affected); foxMemoryLastEditSeenFp.set(String(affected), `${m.swipeId}::${m.fingerprint}::${m.floor}`); } catch {}
          return;
        }
      }

      const next = memories.filter(mem => {
        const range = foxMemoryParseChunkRange(mem);

        // 剧情摘要分块：
        // 如果删除/编辑了某一楼，则从受影响楼层所在分块开始，后面的分块全部删掉，等待重新分析补齐。
        if (range) {
          if (range.start > lastId) {
            removed++;
            return false;
          }

          if (hasAffected && range.end >= affected) {
            removed++;
            return false;
          }

          return true;
        }

        // 其他记忆：如果明确绑定了被删除后的楼层，也删除，避免记忆引用不存在楼层。
        const refs = foxMemoryExtractFloorRefsFromText(
          `${mem.title || ''}\n${mem.eventTime || ''}\n${mem.content || ''}\n${(mem.keywords || []).join('、')}`
        );

        if (refs.some(([s, e]) => s > lastId || e > lastId)) {
          removed++;
          return false;
        }

        if (hasAffected && refs.some(([s, e]) => e >= affected)) {
          removed++;
          return false;
        }

        return true;
      });

      let removedAtoms = 0;
      const nextAtoms = (Array.isArray(data.plotAtoms) ? data.plotAtoms : []).filter(atom => {
        const start = Number(atom.floorStart);
        const end = Number(atom.floorEnd);
        const invalid = !Number.isFinite(start) || !Number.isFinite(end) || start > lastId || end > lastId
          || (hasAffected && end >= affected);
        if (invalid) removedAtoms++;
        return !invalid;
      });
      let removedStates = 0;
      const nextStates = (Array.isArray(data.currentStates) ? data.currentStates : []).filter(item => {
        const start = Number(item.floorStart);
        const end = Number(item.floorEnd);
        const invalid = !Number.isInteger(start) || !Number.isInteger(end) || start < 0 || end < start || start > lastId || end > lastId || (hasAffected && end >= affected);
        if (invalid) removedStates++;
        return !invalid;
      });

      if (removed > 0 || removedAtoms > 0 || removedStates > 0 || hasAffected) {
        data.memories = next;
        data.plotAtoms = nextAtoms;
        data.currentStates = nextStates;
        if (hasAffected) {
          data.characterSnapshots = {};
          data.sceneSnapshot = foxMemoryNormalizeSceneSnapshot();
          data.checkpoints = { turns: [], chunks: [] };
          state.foxMemoryBranchEpoch++;
        }
        if (!saveFoxMemory(data)) throw new Error('楼层修复后的记忆库写入失败');
        if (foxMemoryConfig?.injectToPreset) foxMemorySyncToPreset();
        // 🦊 修复成功后记录该楼层指纹，下次同样的指纹（=内容没再变）就不再触发回退
        try { const m = foxMemoryGetMessageBranchMeta(affected); foxMemoryLastEditSeenFp.set(String(affected), `${m.swipeId}::${m.fingerprint}::${m.floor}`); } catch {}
        foxMemoryV2Log('楼层修复', `reason=${reason} changedFrom=${hasAffected ? affected : '-'} memoriesRemoved=${removed} atomsRemoved=${removedAtoms} statesRemoved=${removedStates}`);

        try { foxMemoryRenderList(); } catch { }
        try { foxMemoryRenderStats(); } catch { }

        if (opts.reanalyze && foxMemoryConfig?.autoMode !== 'manual') {
          setTimeout(() => {
            foxMemoryAnalyzeNow().catch(e => log('[狐忆楼层修复] 自动重分析失败', e));
          }, 1200);
        }
      }
    } catch (e) {
      log('[狐忆楼层修复] 失败', e);
    }
  }

  function registerFoxMemoryRepairListener() {
    unregisterFoxMemoryRepairListener();

    const eo = getFn('eventOn');
    const te = getFn('tavern_events') || tavern_events;

    if (typeof eo !== 'function' || !te) return;

    const add = h => {
      if (h) foxMemoryRepairHandles.push(h);
    };

    // 🦊 删除楼层只做记忆一致性清理（回滚/删除失效记忆），不自动重分析。
    // 狐忆分析只在 AI 回复完成后触发；需要时可手动点"立即分析"。
    if (te.MESSAGE_DELETED) {
      add(eo(te.MESSAGE_DELETED, messageId => {
        setTimeout(() => {
          foxMemoryRepairAfterChatChanged('删除楼层', messageId, { reanalyze: false });
        }, 500);
      }));
    }

    if (te.MESSAGE_EDITED) {
      add(eo(te.MESSAGE_EDITED, messageId => {
        setTimeout(() => {
          if (typeof foxImageState !== 'undefined') {
            const internalAt = foxImageState.internalEdits.get(String(messageId));
            foxImageState.internalEdits.delete(String(messageId));
            if (internalAt && Date.now() - internalAt < 3000) {
              log(`[狐忆楼层修复] 跳过狐映内部写回楼层 ${messageId}`);
              return;
            }
          }
          // 🦊 防呆：点开编辑弹窗什么都不改就关掉，酒馆也会发 MESSAGE_EDITED。
          //    此时楼层内容指纹与"上一次进入该楼层修复时"一致 → 内容没变 → 跳过修复，
          //    避免把未改动的、正确的剧情摘要块误回退清除掉。
          //    逻辑：模块级 Map 记录上次该楼层触发修复后的指纹；若本次指纹相同则跳过。
          try {
            if (typeof foxImageState !== 'undefined' && foxImageState.writeback) {
              log(`[狐忆楼层修复] 跳过狐映内部写回楼层 ${messageId}`);
              return;
            }
            const meta = foxMemoryGetMessageBranchMeta(messageId);
            const fp = `${meta.swipeId}::${meta.fingerprint}::${meta.floor}`;
            if (foxMemoryLastEditSeenFp.get(String(messageId)) === fp) {
              log(`[狐忆楼层修复] 跳过：编辑楼层 ${messageId} 内容未变化（fp=${fp}）`);
              return;
            }
            foxMemoryLastEditSeenFp.set(String(messageId), fp);
          } catch (e) { log('[狐忆楼层修复] 指纹比对失败，回退原逻辑', e); }
          // 🦊 狐忆分析只在 AI 回复完成后触发；编辑楼层只做记忆一致性清理（回滚/删除失效记忆），
          //    不再自动重分析，避免"动一下最新一楼就跳分析"。需要时可手动点"立即分析"。
          foxMemoryRepairAfterChatChanged('编辑楼层', messageId, { reanalyze: false });
        }, 500);
      }));
    }
  }

  function unregisterFoxMemoryRepairListener() {
    for (const h of foxMemoryRepairHandles) {
      ssStopEventHandle(h);
    }

    foxMemoryRepairHandles = [];
  }

  function foxMemoryGetDisplayStoredMemories(data) {
    const atoms = (Array.isArray(data?.plotAtoms) ? data.plotAtoms : [])
      .map(foxMemoryNormalizeStoredAtom)
      .filter(Boolean);
    if (!atoms.length) return Array.isArray(data?.memories) ? data.memories : [];

    const coveredChunkIds = new Set(atoms.map(atom => String(atom.sourceChunkId || '')).filter(Boolean));
    const coveredRanges = new Set(atoms.map(atom => `${atom.floorStart}-${atom.floorEnd}`));
    return (Array.isArray(data?.memories) ? data.memories : []).filter(mem => {
      if (!foxMemoryIsPlotChunk(mem)) return true;
      const range = foxMemoryParseChunkRange(mem);
      return !coveredChunkIds.has(String(mem.id || ''))
        && !(range && coveredRanges.has(`${range.start}-${range.end}`));
    });
  }

  function foxMemoryRenderList() {
    const container = topDoc.getElementById('foxmemory-list');
    if (!container) return;

    const data = loadFoxMemory();
    const memories = [
      ...Object.values(data.characterSnapshots || {}).map(raw => {
        const item = foxMemoryNormalizeCharacterSnapshot(raw);
        if (!item) return null;
        const location = [item.location.city, item.location.area, item.location.building, item.location.interior].filter(Boolean).join('·');
        return {
          ...item,
          category: 'character',
          title: `角色快照｜${item.name}${item.active ? '｜在场' : '｜离场'}`,
          content: [
            location && `位置：${location}`,
            item.location.posture && `姿态：${item.location.posture}`,
            Object.entries(item.physiology).filter(([, value]) => value).map(([key, value]) => `${key}=${value}`).join('；'),
            Object.entries(item.appearance).filter(([, value]) => value).map(([key, value]) => `${key}=${value}`).join('；'),
            item.mind.currentGoal && `当前目标：${item.mind.currentGoal}`,
            item.future.todos.length && `待办：${item.future.todos.join('；')}`,
            item.future.commitments.length && `约定：${item.future.commitments.join('；')}`,
          ].filter(Boolean).join('\n'),
          keywords: [item.name, ...item.nearbyCharacters],
          eventTime: `第${item.updatedAtFloor}楼 / swipe ${item.sourceSwipeId}`,
          __isCharacterSnapshot: true,
        };
      }).filter(Boolean),
      ...(Array.isArray(data.currentStates) ? data.currentStates.map(item => ({
        ...item,
        category: 'character',
        title: `当前状态｜${item.subject}｜${item.field}`,
        content: `${item.value}${item.history?.length ? `\n\n历史值：\n${item.history.map(entry => `- ${entry.value}（第${entry.floorStart}-${entry.floorEnd}楼后失效）`).join('\n')}` : ''}`,
        keywords: [item.subject, item.field],
        eventTime: `第${item.floorStart}-${item.floorEnd}楼`,
        __isCurrentState: true,
      })) : []),
      ...(Array.isArray(data.plotAtoms) ? data.plotAtoms.map(atom => ({
        ...atom,
        category: 'plot',
        title: `信息句｜第${atom.floorStart}-${atom.floorEnd}楼`,
        content: atom.text,
        __isPlotAtom: true,
      })) : []),
      ...foxMemoryGetDisplayStoredMemories(data),
    ];
    const category = foxMemoryEditing.selectedCategory;
    const keyword = (foxMemoryEditing.searchKeyword || '').trim().toLowerCase();

    let filtered = memories;
    if (category === 'locked') {
      filtered = filtered.filter(m => m.pinned === true);
    } else if (category && category !== 'all') {
      filtered = filtered.filter(m => m.category === category);
    }
    if (keyword) {
      filtered = filtered.filter(m =>
        (m.title || '').toLowerCase().includes(keyword) ||
        (m.content || '').toLowerCase().includes(keyword) ||
        (m.keywords || []).some(k => k.toLowerCase().includes(keyword))
      );
    }
    filtered = filtered.slice().sort((a, b) => {
      const aPin = a.pinned === true ? 1 : 0;
      const bPin = b.pinned === true ? 1 : 0;
      return bPin - aPin
        || Number(b.strength ?? 0.55) - Number(a.strength ?? 0.55)
        || Number(b.lastMentionFloor || b.floorEnd || b.updatedAtFloor || 0) - Number(a.lastMentionFloor || a.floorEnd || a.updatedAtFloor || 0)
        || Number(b.mentionCount || 1) - Number(a.mentionCount || 1);
    });

    if (!filtered.length) {
      container.innerHTML = '<div style="text-align:center;color:#706058;padding:20px;font-size:12px;">暂无记忆条目</div>';
      return;
    }

    container.innerHTML = '';
    for (const mem of filtered) {
      const cat = FOX_MEMORY_CATEGORIES.find(c => c.id === mem.category) || { icon: '📝', label: mem.category };
      const el = topDoc.createElement('div');
      const strength = Math.max(0.05, Math.min(1, Number(mem.strength) || 0.55));
      const salienceColor = strength >= 0.72
        ? `rgba(104,190,125,${0.10 + strength * 0.12})`
        : strength <= 0.3
          ? `rgba(125,125,125,${0.05 + strength * 0.08})`
          : `rgba(232,120,74,${0.035 + strength * 0.05})`;
      const borderColor = strength >= 0.72 ? 'rgba(104,190,125,0.38)' : strength <= 0.3 ? 'rgba(130,130,130,0.18)' : 'rgba(232,120,74,0.18)';
      const lockedStyle = mem.pinned ? ';border-color:rgba(255,179,71,0.45);background:rgba(255,179,71,0.05)' : '';
      el.style.cssText = `background:${salienceColor};border:1px solid ${borderColor};border-radius:8px;padding:10px 12px;margin-bottom:8px;opacity:${0.68 + strength * 0.32}${lockedStyle};`;
      el.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:6px;">
          <div>
            <span style="font-size:14px;margin-right:6px;">${cat.icon}</span>
            <span style="font-weight:600;color:#e8ddd4;font-size:13px;">${escapeHtml(mem.title || '（无标题）')}</span>
            ${mem.pinned ? '<span style="font-size:10px;padding:2px 7px;border-radius:99px;color:#ffb347;background:rgba(255,179,71,0.1);border:1px solid rgba(255,179,71,0.3);margin-left:6px;font-weight:600;">🔒 已锁定</span>' : ''}
            <span style="color:#706058;font-size:10px;margin-left:6px;">${escapeHtml(cat.label)}</span>
            ${mem.eventTime ? `<span style="color:#90756a;font-size:10px;margin-left:4px;">🕐 ${escapeHtml(mem.eventTime)}</span>` : ''}
            ${mem.strength != null ? `<span style="color:${strength >= 0.72 ? '#86d89a' : strength <= 0.3 ? '#8b8b8b' : '#d99a78'};font-size:10px;margin-left:5px;">${mem.pinned ? '📌 ' : ''}强度 ${Math.round(strength * 100)}% · 提及 ${Math.max(1, Number(mem.mentionCount) || 1)} 次${mem.lastMentionFloor ? ` · ${mem.lastMentionFloor}楼` : ''}</span>` : ''}
          </div>
          <div style="display:flex;gap:4px;flex-shrink:0;">
            ${mem.__isCharacterSnapshot ? '' : `<button class="foxmem-pin-btn" data-id="${escapeHtml(mem.id)}" title="${mem.pinned ? '取消加固' : '加固记忆'}" style="padding:3px 7px;border:1px solid ${mem.pinned ? 'rgba(104,190,125,0.45)' : 'rgba(232,120,74,0.18)'};border-radius:5px;background:${mem.pinned ? 'rgba(104,190,125,0.18)' : 'rgba(255,255,255,0.03)'};color:${mem.pinned ? '#86d89a' : '#90756a'};cursor:pointer;font-size:11px;">📌</button>`}
            ${(mem.__isPlotAtom || mem.__isCurrentState || mem.__isCharacterSnapshot) ? `<span style="padding:3px 7px;color:#90756a;font-size:10px;">${mem.__isCharacterSnapshot ? '角色快照' : mem.__isCurrentState ? '当前状态' : '只读原子'}</span>` : `<button class="foxmem-edit-btn" data-id="${escapeHtml(mem.id)}" style="padding:3px 8px;border:1px solid rgba(232,120,74,0.2);border-radius:5px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:11px;">✏️</button>`}
            <button class="foxmem-del-btn" data-id="${escapeHtml(mem.id)}" style="padding:3px 8px;border:1px solid rgba(139,0,0,0.3);border-radius:5px;background:rgba(139,0,0,0.15);color:#d08080;cursor:pointer;font-size:11px;">🗑</button>
          </div>
        </div>
        <div style="font-size:12px;color:#a09088;line-height:1.55;white-space:pre-wrap;word-break:break-word;">${escapeHtml(mem.content || '')}</div>
        ${(mem.keywords && mem.keywords.length) ? `<div style="margin-top:6px;font-size:10px;color:#706058;">🏷️ ${mem.keywords.map(k => escapeHtml(k)).join('、')}</div>` : ''}
      `;
      container.appendChild(el);
    }

    container.querySelectorAll('.foxmem-edit-btn').forEach(btn => {
      btn.onclick = async () => {
        const id = btn.dataset.id;
        const mem = memories.find(m => m.id === id);
        if (mem) foxMemoryOpenEditDialog(mem);
      };
    });
    container.querySelectorAll('.foxmem-pin-btn').forEach(btn => {
      btn.onclick = () => {
        const id = String(btn.dataset.id || '');
        const data = loadFoxMemory();
        const collections = [data.memories || [], data.plotAtoms || [], data.currentStates || []];
        let target = null;
        for (const list of collections) {
          target = list.find(item => String(item.id || item.key) === id);
          if (target) break;
        }
        if (!target) return;
        target.pinned = target.pinned !== true;
        if (target.pinned) target.strength = Math.max(Number(target.strength) || 0.55, 0.8);
        saveFoxMemory(data);
        foxMemoryRenderList();
        toast(target.pinned ? '📌 已加固：此记忆不再衰减' : '已取消加固：此记忆恢复正常衰减', 'success');
      };
    });
    container.querySelectorAll('.foxmem-del-btn').forEach(btn => {
      btn.onclick = async () => {
        const id = btn.dataset.id;
        const ok = topWindow?.confirm ? topWindow.confirm('确定要删除这条记忆吗？') : confirm('确定要删除这条记忆吗？');
        if (!ok) return;
        const currentData = loadFoxMemory();
        const isAtom = (currentData.plotAtoms || []).some(atom => atom.id === id);
        const isState = (currentData.currentStates || []).some(item => item.id === id);
        const snapshotKey = Object.keys(currentData.characterSnapshots || {}).find(name => currentData.characterSnapshots[name]?.id === id);
        if (isAtom) currentData.plotAtoms = currentData.plotAtoms.filter(atom => atom.id !== id);
        else if (isState) currentData.currentStates = currentData.currentStates.filter(item => item.id !== id);
        else if (snapshotKey) {
          delete currentData.characterSnapshots[snapshotKey];
          currentData.sceneSnapshot = foxMemoryNormalizeSceneSnapshot({
            ...currentData.sceneSnapshot,
            presentCharacters: (currentData.sceneSnapshot?.presentCharacters || []).filter(name => name.toLowerCase() !== snapshotKey.toLowerCase()),
          });
          for (const snapshot of Object.values(currentData.characterSnapshots || {})) {
            snapshot.nearbyCharacters = (snapshot.nearbyCharacters || []).filter(name => name.toLowerCase() !== snapshotKey.toLowerCase());
          }
        } else currentData.memories = (currentData.memories || []).filter(mem => mem.id !== id);
        currentData.checkpoints = { turns: [], chunks: [] };
        state.foxMemoryBranchEpoch++;
        state.foxMemoryPendingBranchCheckpoint = null;
        if (!saveFoxMemory(currentData)) {
          toast('❌ 删除失败：记忆库写入失败', 'error');
          return;
        }
        if (foxMemoryConfig?.injectToPreset) foxMemorySyncToPreset();
        foxMemoryV2Log('手动删除', `id=${id} type=${isAtom ? 'plot_atom' : isState ? 'current_state' : snapshotKey ? 'character_snapshot' : 'memory'}`);
        foxMemoryRenderList();
        foxMemoryRenderStats();
        toast('🗑️ 已删除', 'success');
      };
    });
  }

  function foxMemoryRenderStats() {
    const el = topDoc.getElementById('foxmemory-stats');
    if (!el) return;
    const data = loadFoxMemory();
    const memories = foxMemoryGetDisplayStoredMemories(data);
    const atomCount = Array.isArray(data.plotAtoms) ? data.plotAtoms.length : 0;
    const stateCount = Array.isArray(data.currentStates) ? data.currentStates.length : 0;
    const snapshotCount = Object.keys(data.characterSnapshots || {}).length;
    const checkpointCount = (data.checkpoints?.turns?.length || 0) + (data.checkpoints?.chunks?.length || 0);
    const counts = {};
    for (const m of memories) counts[m.category] = (counts[m.category] || 0) + 1;

    const catText = FOX_MEMORY_CATEGORIES.map(c => `${c.icon}${counts[c.id] || 0}`).join(' ');
    const lastTime = data.lastAnalysis ? new Date(data.lastAnalysis).toLocaleString('zh-CN') : '从未分析';
    const lockedCount = memories.filter(m => m.pinned === true).length;
    el.innerHTML = `
      <div style="display:flex;gap:16px;flex-wrap:wrap;font-size:11px;color:#a09088;padding:8px 0;">
        <span>📊 总数：<b style="color:#f0a070;">${memories.length}</b></span>
        <span>🔒 已锁定：<b style="color:#ffb347;">${lockedCount}</b></span>
        <span>🧩 信息句：<b style="color:#f0a070;">${atomCount}</b></span>
        <span>📍 当前状态：<b style="color:#f0a070;">${stateCount}</b></span>
        <span>🎭 角色快照：<b style="color:#f0a070;">${snapshotCount}</b></span>
        <span>↩️ 检查点：<b style="color:#f0a070;">${checkpointCount}</b></span>
        <span>${catText}</span>
        <span>🕐 最后分析：${lastTime}</span>
      </div>
    `;
    const railCount = topDoc.getElementById('fm-rail-count');
    if (railCount) railCount.textContent = `${memories.length} 条`;
    const railLocked = topDoc.getElementById('fm-rail-locked');
    if (railLocked) railLocked.textContent = String(lockedCount);
  }

  function foxMemoryOpenEditDialog(existing) {
