      id: 'mem_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8),
      category: 'character',
      title: '',
      content: '',
      keywords: [],
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

