  // 应用当前模式到预设条目（写 enabled + content）
  async function foxStrategyApply() {
    if (novelLocksToggleId(FOX_STRATEGY_ID)) return false; // 小说模式接管，不写
    const mode = foxStrategyReadMode();
    let found = false;
    await updatePresetWith('in_use', (preset) => {
      const p = preset.prompts?.find(p => p.id === FOX_STRATEGY_ID || p.identifier === FOX_STRATEGY_ID);
      if (!p) return preset;
      found = true;
      if (mode === 'off') {
        p.enabled = false;
      } else {
        p.enabled = true;
        p.content = mode === 'simple' ? FOX_STRATEGY_SIMPLE_PROMPT : foxStrategyBuildAdvancedPrompt();
      }
      return preset;
    });
    return found;
  }

  async function foxStrategySetMode(mode) {
    if (novelLocksToggleId(FOX_STRATEGY_ID)) {
      try { toast('📖 小说模式已开启：狐策由小说模式接管，不能手动修改', 'warning'); } catch {}
      return;
    }
    const previous = foxStrategyReadMode();
    foxStrategyWriteMode(mode);
    let applied = false;
    try { applied = await foxStrategyApply(); } catch (e) {
      foxStrategyWriteMode(previous);
      throw e;
    }
    if (!applied) {
      foxStrategyWriteMode(previous);
      try { toast('❌ 当前预设中未找到狐策条目，未修改状态', 'error'); } catch {}
      return false;
    }
    try { toast(mode === 'off' ? '🦊 狐策已关闭' : (mode === 'simple' ? '🦊 狐策：简单模式' : '🦊 狐策：高级模式'), 'success'); } catch {}
    return true;
  }

