    const w = topDoc.createElement('span');
    w.style.cssText = 'display:inline-flex;gap:0;border-radius:6px;overflow:hidden;border:1px solid rgba(232,120,74,0.25);flex-shrink:0;';
    const mk = (label) => { const b = topDoc.createElement('span'); b.textContent = label; b.style.cssText = 'padding:3px 8px;cursor:pointer;font-size:11px;font-weight:600;transition:all 0.15s;'; return b; };
    const offB = mk('关'), simpleB = mk('简单'), advB = mk('高级');
    function up() {
      const mode = foxStrategySyncModeFromPreset();
      const locked = novelLocksToggleId(FOX_STRATEGY_ID);
      const paint = (b, act) => { b.style.background = act ? 'rgba(232,120,74,0.25)' : 'transparent'; b.style.color = act ? '#f0a070' : '#555'; };
      paint(offB, mode === 'off'); paint(simpleB, mode === 'simple'); paint(advB, mode === 'advanced');
      if (locked) { w.style.opacity = '0.45'; w.style.pointerEvents = 'none'; w.title = '小说模式已开启：狐策由小说模式接管'; }
      else { w.style.opacity = '1'; w.style.pointerEvents = 'auto'; w.title = ''; }
    }
    offB.onclick = async () => { await foxStrategySetMode('off'); up(); if (onChange) onChange('off'); };
    simpleB.onclick = async () => { await foxStrategySetMode('simple'); up(); if (onChange) onChange('simple'); };
    advB.onclick = async () => { await foxStrategySetMode('advanced'); up(); if (onChange) onChange('advanced'); };
    w.appendChild(offB); w.appendChild(simpleB); w.appendChild(advB);
    up();
    return { wrapper: w, update: up };
  }

