        const list = (order.length ? order : []).map(id => modules.find(m => m.id === id)).filter(Boolean).map(m => { const n = Math.max(1, parseInt(m.n, 10) || 1); total += n; return `${m.tag}×${n}`; });
        const totalEl = panel.querySelector('#foxstrategy-total');
