    function bindItemEvents() {
      if (!panel.isConnected) return; // 🛡️ 面板已关闭则跳过，防止异步回调绑定到已移除的 DOM
      // 🛡️ 统一读取拖拽 id：优先从 dataTransfer 取（更可靠），回退到 _fsDragId
      const fsReadDragId = (e) => {
        try { const dt = e?.dataTransfer?.getData('text/plain'); if (dt) return dt; } catch {}
        return _fsDragId;
      };
      // 🛡️ 单项操作的安全包装：任何异常都不会中断后续元素的绑定
      const safeOp = (fn) => (e) => { try { fn(e); } catch (err) { try { log('[狐策] bindItemEvents 操作异常', err); } catch {} } };
      try {
        panel.querySelectorAll('.fs-item').forEach(el => {
          if (_fsTouch) return; // 📱 移动端跳过 HTML5 拖拽（draggable 已禁用），改用 ⇢↑↓⇠ 按钮
          el.ondragstart = (e) => { _fsDragId = el.dataset.id; try { e.dataTransfer.effectAllowed = 'move'; e.dataTransfer.setData('text/plain', el.dataset.id); } catch {} };
          // 🛡️ 拖拽结束（无论成功/取消/失败）必须重置 _fsDragId，防止旧值污染下一次 drop 判定
          el.ondragend = () => { _fsDragId = null; };
          el.ondragover = (e) => e.preventDefault();
          el.ondrop = safeOp((e) => {
            e.preventDefault(); e.stopPropagation();
            const dragId = fsReadDragId(e); if (!dragId) return;
            const container = el.parentElement;
            const isActive = container && container.id === 'foxstrategy-active';
            const { modules, order, perspective } = foxStrategyLoadModules();
            if (isActive) {
              let no = order.filter(id => id !== dragId);
              const ti = no.indexOf(el.dataset.id);
              if (ti >= 0) no.splice(ti, 0, dragId); else no.push(dragId);
              foxStrategySaveModules(modules, no, perspective);
            } else {
              foxStrategySaveModules(modules, order.filter(id => id !== dragId), perspective);
            }
            _fsDragId = null;
            fsRerender();
          });
        });
        panel.querySelectorAll('.fs-edit').forEach(el => { el.onclick = safeOp((e) => { e.stopPropagation(); fsOpenEditor(el.dataset.id); }); });
        // 数量输入实时保存：改完即落库 + 更新总数 + 若已高级模式则实时重写提示词
        panel.querySelectorAll('.fs-n-input').forEach(el => {
          const applyN = async (raw) => {
            try {
              const v = Math.max(1, Math.min(20, parseInt(raw, 10) || 1));
              if (String(v) !== String(el.value)) el.value = v;
              const { modules, order, perspective } = foxStrategyLoadModules();
              const idx = modules.findIndex(m => m.id === el.dataset.id);
              if (idx >= 0) { modules[idx].n = v; foxStrategySaveModules(modules, order, perspective); }
              fsUpdateTotal();
              if (foxStrategyReadMode() === 'advanced') { try { await foxStrategyApply(); } catch (e) { try { log('[狐策] applyN 异常', e); } catch {} } }
            } catch (e) { try { log('[狐策] applyN 失败', e); } catch {} }
          };
          el.addEventListener('change', (e) => { e.stopPropagation(); applyN(e.target.value); });
