  function foxJudgeBuildPhase2FromModules() {
    const { modules, order } = foxJudgeLoadThinkModules();
    const parts = [];
    for (const id of order) {
      const m = modules.find(x => x.id === id);
      if (m && m.content && String(m.content).trim()) {
        parts.push(String(m.content).trim());
      }
    }
      // ✅ tail 已删除为独立模块，STOP 收束指令自动追加到拼接末尾
      parts.push('**⛔STOP HERE AND OUTPUT：思考已结束，立刻停止思考，停止输出，禁止二次思考，禁止输出正文！⛔**');
      return parts.join('\n\n');
    }

  // 应用排序预设（点击 OS/导演按钮）：重排 order，保留用户自定义词条于末尾
  function foxJudgeApplyThinkPreset(presetKey) {
    const preset = FOX_JUDGE_THINK_PRESETS[presetKey];
    if (!preset) return;
    const { modules, order: curOrder } = foxJudgeLoadThinkModules();
    // 所有预设内置词条（OS + 导演两套）都不算"用户自定义"：
    //   切换到 OS 时应把导演版词条（director_check_full / plot_scrutiny）从启用顺序里移除（=停用），
    //   切换到导演时同理移除 OS 版词条，而不是把它们当成自定义追加到末尾。
    const allPresetIds = new Set([...FOX_JUDGE_THINK_PRESETS.os.order, ...FOX_JUDGE_THINK_PRESETS.director.order]);
    const customIds = curOrder.filter(id => !allPresetIds.has(id) && id !== 'head' && id !== 'tail');
    let order = preset.order.filter(id => modules.some(m => m.id === id));
    for (const cid of customIds) {
      if (!order.includes(cid)) order.push(cid);
    }
    foxJudgeSaveThinkModules(modules, order);
  }

