        //    用户可在面板自由编辑/删除过滤标签（如删除 <User_latest_request> 让狐裁读到最新输入块）。
        //    默认值仍含这四项（见 FOX_JUDGE_DEFAULT_FILTER_SETTINGS），仅不再强制覆盖用户已删除的。
        if (migrated) {
          filterSettings.excludeTagPairs = filtered;
          localStorage.setItem(FOX_JUDGE_LS_KEYS.filterSettings, JSON.stringify(filterSettings));
          log('[狐裁] 已自动迁移标签过滤配置：强制移除 fox_selc/fox_tip/fox_tip，补齐 think_fox~/thinking_rules/User_latest_request/All_Context');
        }
      } catch (e) { log('[狐裁] 迁移标签过滤配置失败', e); }
    })();

    // 🦊 排除标签版本化"首次覆盖"：确保用户能同步到最新默认排除标签。
    //    旧版脚本下，用户 localStorage 里保存的 excludeTagPairs 会整体覆盖默认值，且此前已改成"不再补齐"，
    //    导致 <User_latest_request>/<All_Context> 等新默认标签无法同步给老用户（他们本地存的旧数组不含这两组）。
    //    用版本标记解决：版本标记未达当前值时，把 excludeTagPairs 整体覆盖为默认四项并写标记；
    //    之后用户在面板里的任意增删改都不再被覆盖（允许删除）。
    //    （fox_selc/fox_tip/fox_tip 的强制移除见上方迁移逻辑，始终执行，不受此版本门槛限制。）
    try {
      const FOXJ_TAG_VER_CUR = '1';
      if (localStorage.getItem(FOX_JUDGE_LS_KEYS.filterTagVer) !== FOXJ_TAG_VER_CUR) {
        filterSettings.excludeTagPairs = [
          { start: '<think_fox~>', end: '</think_fox~>' },
          { start: '<thinking_rules>', end: '</thinking_rules>' },
          { start: '<User_latest_request>', end: '</User_latest_request>' },
          { start: '<All_Context>', end: '</All_Context>' },
        ];
        localStorage.setItem(FOX_JUDGE_LS_KEYS.filterSettings, JSON.stringify(filterSettings));
        localStorage.setItem(FOX_JUDGE_LS_KEYS.filterTagVer, FOXJ_TAG_VER_CUR);
        log(`[狐裁] 已同步最新默认排除标签（v${FOXJ_TAG_VER_CUR}）：覆盖一次本地旧标签过滤配置为默认四项；后续你的增删改不再被覆盖`);
      }
    } catch (e) { log('[狐裁] 同步默认排除标签失败', e); }

    return {
      enabled: localStorage.getItem(FOX_JUDGE_LS_KEYS.enabled) === 'true',
      phase1Prompt: localStorage.getItem(FOX_JUDGE_LS_KEYS.phase1Prompt) || FOX_JUDGE_PHASE1_PROMPT,
      phase2Prompt,
      strength: localStorage.getItem(FOX_JUDGE_LS_KEYS.strength) || 'default',
      cacheEnabled: localStorage.getItem(FOX_JUDGE_LS_KEYS.cacheEnabled) !== 'false',
      // ✅ 默认打开。关闭后 swipe/reroll 不再重跑第二阶段，而是直接复用上一次完整思维链注入新输出楼层顶部。
      swipeRethink: localStorage.getItem(FOX_JUDGE_LS_KEYS.swipeRethink) !== 'false',
      rerollRethink: localStorage.getItem(FOX_JUDGE_LS_KEYS.rerollRethink) !== 'false',
      apiType: localStorage.getItem(FOX_JUDGE_LS_KEYS.apiType) || 'current',
      customApi,
      filterSettings,
      customThinkingReq: localStorage.getItem(FOX_JUDGE_LS_KEYS.customThinkingReq) || '',
      maxRetries: (() => {
        // ✅ 修复：parseInt("0") || 3 = 3 → 用户存入 0 想关闭重试，读出来变 3
        const n = parseInt(localStorage.getItem(FOX_JUDGE_LS_KEYS.maxRetries), 10);
        return Math.max(0, Math.min(5, Number.isFinite(n) ? n : 3));
      })(),
      // 🔄 空回复/报错重试总开关：默认关闭。关闭时不检测空回/报错，思维链只跑一次直接返回结果。
      retryEnabled: localStorage.getItem(FOX_JUDGE_LS_KEYS.retryEnabled) === 'true',
      phase1Only: localStorage.getItem(FOX_JUDGE_LS_KEYS.phase1Only) === 'true',
      phase1Fixed: localStorage.getItem(FOX_JUDGE_LS_KEYS.phase1Fixed) === 'true',
      // 🆕 分析楼层限制：0=全部楼层(默认)，N=只把最新 N 楼聊天记录送进狐裁思考上下文
      //    同时限制第一阶段、第二阶段（两阶段共用同一份 contextText）
      contextFloors: (() => {
        const n = parseInt(localStorage.getItem(FOX_JUDGE_LS_KEYS.contextFloors), 10);
        return Number.isFinite(n) && n >= 0 ? n : 10;
      })(),
    };
  }

