  async function foxJudgeApplyAutoPresetChanges() {
    try {
      const changesToSave = {};
      try {
        const preset = getPreset('in_use');
        for (const p of preset.prompts || []) {
          const ref = p.id || p.identifier || '';
          if (FOX_JUDGE_MODIFIED_IDS.includes(ref)) {
            changesToSave[ref] = !!p.enabled;
          }
        }
      } catch {}
      if (!localStorage.getItem(FOX_JUDGE_PRESET_SNAPSHOT_KEY)) {
        localStorage.setItem(FOX_JUDGE_PRESET_SNAPSHOT_KEY, JSON.stringify(changesToSave));
        log('[狐裁] 已保存被修改条目的原始状态', Object.keys(changesToSave).length, '条');
      }

      await updatePresetWith('in_use', (preset) => {
        for (const p of preset.prompts || []) {
          const ref = p.id || p.identifier || '';
          if (FOX_JUDGE_COT_IDS.includes(ref)) p.enabled = false;
          if (ref === FOX_JUDGE_NO_COT_ID) p.enabled = true;
          // ✅ 用户要求：开启内置思维链时，两个尾部条目都直接关闭，不要打开任意一个
          if (ref === FOX_JUDGE_DIRECT_OUT_THINK_ID) p.enabled = false;
          if (ref === FOX_JUDGE_DIRECT_OUT_ID) p.enabled = false;
          if (FOX_JUDGE_THINKING_STRENGTH_IDS.includes(ref)) p.enabled = false;
        }
        return preset;
      });

      if (!foxJudgeIsPresetAutoApplied()) {
        await updatePresetWith('in_use', (preset) => {
          for (const p of preset.prompts || []) {
            const ref = p.id || p.identifier || '';
            if (FOX_JUDGE_COT_IDS.includes(ref)) p.enabled = false;
            if (ref === FOX_JUDGE_NO_COT_ID) p.enabled = true;
            if (ref === FOX_JUDGE_DIRECT_OUT_THINK_ID) p.enabled = false;
            if (ref === FOX_JUDGE_DIRECT_OUT_ID) p.enabled = false;
            if (FOX_JUDGE_THINKING_STRENGTH_IDS.includes(ref)) p.enabled = false;
          }
          return preset;
        }, { render: 'immediate' });
      }

      if (!foxJudgeIsPresetAutoApplied()) {
        toast('⚠️ 狐裁防呆：预设选项自动修改未完全生效，请重新打开预设确认', 'warning');
      }

      log('[狐裁] 已自动切换：思维链→无思维链，尾部→两个全部关闭，思考强度→关闭');
    } catch (e) {
      log('[狐裁] 自动切换预设失败', e);
    }
  }

  async function foxJudgeRestorePresetFromSnapshot() {
    try {
      const raw = localStorage.getItem(FOX_JUDGE_PRESET_SNAPSHOT_KEY);
      if (!raw) {
        log('[狐裁] 无预设快照，跳过恢复');
        return;
      }
      const changes = JSON.parse(raw);
      const applyChanges = (preset) => {
        for (const p of preset.prompts || []) {
          const ref = p.id || p.identifier || '';
          if (ref in changes) {
            p.enabled = changes[ref];
          }
        }
        return preset;
      };
      await updatePresetWith('in_use', applyChanges);
      // ✅ 与 foxJudgeApplyAutoPresetChanges 对称：第一次写入后立即渲染一次，
      //    确保预设面板 / 仪表盘的条目状态和灰显立刻同步，不会出现"关了狐裁但条目没恢复"。
      await updatePresetWith('in_use', applyChanges, { render: 'immediate' });
      localStorage.removeItem(FOX_JUDGE_PRESET_SNAPSHOT_KEY);
      log('[狐裁] 已从快照恢复被修改的预设条目', Object.keys(changes).length, '条');
    } catch (e) {
      log('[狐裁] 恢复预设快照失败', e);
    }
  }

  async function foxJudgeSetEnabled(next, { notify = true, refreshDashboard = true } = {}) {
    const cfg = foxJudgeReadConfig();
    cfg.enabled = !!next;
    foxJudgeSaveConfig(cfg);
    if (next) {
      await foxJudgeApplyAutoPresetChanges();
      if (!foxJudgeIsPresetAutoApplied()) {
        cfg.enabled = false;
        foxJudgeSaveConfig(cfg);
        await foxJudgeRestorePresetFromSnapshot();
        if (notify) toast('❌ 狐裁开启失败：未能切换为无思维链并关闭思考强度、尾部模块', 'error');
        if (refreshDashboard) ssRefreshDashboardIfOpen();
        return false;
      }
      foxJudgeInterceptProcessing = false;
      foxJudgeInterceptSkipNext = false;
      foxJudgeRethinkPending = false;
      foxJudgeSkipNextReroll = false;
      foxJudgeSkipNextSwipe = false;
      foxJudgeRegisterSwipeRerollListeners();
      foxJudgeRegisterOutputInjectListener();
      try { registerFoxJudgeInterceptListener(); } catch (err) { log('[狐裁] 开启时重挂独立拦截器失败', err); }
      if (notify) toast('✅ 狐裁已启用：无思维链，思考强度与尾部模块已关闭并锁定', 'success');
    } else {
      try { ssCancelTask?.('fox_judge_chain', '关闭狐裁开关'); } catch { }
      await foxJudgeRestorePresetFromSnapshot();
      foxJudgeUnregisterSwipeRerollListeners();
      try { unregisterFoxJudgeInterceptListener(true); } catch (err) { log('[狐裁] 关闭时注销独立拦截器失败', err); }
      try { foxJudgeUninstallDocLevelGuard(); } catch (err) { log('[狐裁] 关闭时拆除 send/Enter 文档级兜底失败', err); }
      try { foxJudgeUninstallSwipeRerollDocGuard(); } catch (err) { log('[狐裁] 关闭时拆除 reroll/swipe 文档级兜底失败', err); }
      foxJudgeInterceptProcessing = false;
