  function foxJudgeGetStaticCache(charId) {
    try {
      const raw = localStorage.getItem(FOX_JUDGE_LS_KEYS.charCachePrefix + charId);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (!parsed || parsed.version !== 2) return null;
      if (parsed.char_id !== charId) return null;
      return parsed;
    } catch { return null; }
  }

  function foxJudgeSaveStaticCache(charId, cache) {
    try {
      const json = JSON.stringify(cache);
      // 🦊 容量保护：如果序列化后超过 2MB，先清理其他角色卡的旧缓存腾出空间
      //    保留最近使用的 3 个角色卡缓存，只删除更旧的，避免一次性丢失全部缓存
      if (json.length > 2 * 1024 * 1024) {
        try {
          const others = [];
          for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (k && k.startsWith(FOX_JUDGE_LS_KEYS.charCachePrefix) && k !== FOX_JUDGE_LS_KEYS.charCachePrefix + charId) {
              let ts = '';
              try { ts = JSON.parse(localStorage.getItem(k) || '{}')?.created_at || ''; } catch {}
              others.push({ key: k, ts });
            }
          }
          // 按创建时间降序排列，保留最近 3 个，删除其余
          others.sort((a, b) => (b.ts || '').localeCompare(a.ts || ''));
          const toDelete = others.slice(3);
          toDelete.forEach(o => { try { localStorage.removeItem(o.key); } catch {} });
          if (toDelete.length) log(`[狐裁] 缓存过大（${(json.length / 1024 / 1024).toFixed(2)}MB），已清理 ${toDelete.length} 个较旧角色卡缓存（保留最近 ${others.length - toDelete.length} 个）`);
        } catch {}
      }
      localStorage.setItem(
        FOX_JUDGE_LS_KEYS.charCachePrefix + charId,
        json
      );
      // 🦊 验证：写完后立刻读回，确认确实落盘
      const verify = localStorage.getItem(FOX_JUDGE_LS_KEYS.charCachePrefix + charId);
      if (!verify) {
        log('[狐裁] 缓存保存失败：写入后读回为空（可能 localStorage 配额已满）');
        try { toast('⚠️ 狐裁缓存保存失败：浏览器存储空间已满，第一阶段将每次重跑。请清理浏览器数据或减少聊天记录', 'warning'); } catch {}
        return false;
      }
      return true;
    } catch (e) {
      log('[狐裁] 缓存保存失败', e);
      try { toast('⚠️ 狐裁缓存保存失败：浏览器存储空间已满，第一阶段将每次重跑', 'warning'); } catch {}
      return false;
    }
  }

  function foxJudgeInvalidateStaticCache() {
