  // ✅ 鲁棒提取：generateRaw 在不同 ST 版本 / custom_api / 推理模型下返回形态不一致：
  //    - 直接 string
  //    - { content: string }
  //    - { text: string } / { message: string } / { output: string }
  //    - { message: { content: string | Array } }（Claude 风格）
  //    - { choices: [{ message: { content }, text }] }（OpenAI 风格）
  //    - { content: [{ type: 'text', text: '...' }] }（Anthropic content blocks）
  //    - 推理模型可能把正文放在 reasoning_content / thinking 字段
  //    任何一种形态没被识别就会导致"明明 AI 回了内容却被判定空回复"。
  function foxJudgeExtractText(r) {
    if (r == null) return '';
    if (typeof r === 'string') {
      // ✅ 部分代理 / 自定义 API 会把整个 JSON 响应体当字符串返回，
      //    直接当纯文本会把 {"choices":[...]} 这种结构误当成"正文"或被判残缺。
      //    仅当看起来像 JSON 对象/数组时才尝试解析，解析失败就按原始字符串处理。
      const s = r.trim();
      if (s && (s[0] === '{' || s[0] === '[') && (s.includes('"content"') || s.includes('"choices"') || s.includes('"reasoning'))) {
        try {
          const parsed = JSON.parse(s);
          const t = foxJudgeExtractText(parsed);
          if (t && t.trim()) return t;
        } catch { }
      }
      return r;
    }
    if (typeof r === 'number' || typeof r === 'boolean') return String(r);
    if (Array.isArray(r)) {
      return r.map(x => foxJudgeExtractText(x)).filter(Boolean).join('\n');
    }
    if (typeof r !== 'object') return '';

    // OpenAI 风格：choices[].message.content / choices[].text / choices[].delta.content
    if (Array.isArray(r.choices) && r.choices.length) {
      const parts = r.choices.map(c => {
        if (!c) return '';
        if (typeof c === 'string') return c;
        return foxJudgeExtractText(c.message)
          || foxJudgeExtractText(c.delta)
          || (typeof c.text === 'string' ? c.text : '')
          || foxJudgeExtractText(c.content);
      }).filter(Boolean);
      if (parts.length) return parts.join('\n');
    }

    // 推理模型：当 reasoning_content/thinking 远长于 content 时优先取思考正文，
    // 避免短 content（如"好的"）把真正的思考丢弃后被判"字数不足"反复重试至失败。
    {
      const _rk = ['reasoning_content', 'reasoning', 'thinking', 'thought'];
      let _best = '';
      for (const _k of _rk) {
        if (typeof r[_k] === 'string' && r[_k].trim().length > _best.length) _best = r[_k].trim();
      }
      const _c = typeof r.content === 'string' ? r.content.trim() : '';
      if (_best && _best.length >= 50 && _best.length > _c.length * 2) return _best;
    }

    // 常见单字段
    const directKeys = ['content', 'text', 'message', 'output', 'output_text', 'response', 'data', 'result'];
    for (const k of directKeys) {
      if (r[k] != null) {
        const t = foxJudgeExtractText(r[k]);
        if (t && t.trim()) return t;
      }
    }

    // Anthropic content blocks: [{ type:'text', text:'...' }]
    if (Array.isArray(r.content)) {
      const t = r.content.map(b => {
        if (!b) return '';
        if (typeof b === 'string') return b;
        return (typeof b.text === 'string' ? b.text : '') || foxJudgeExtractText(b.content);
      }).filter(Boolean).join('\n');
      if (t.trim()) return t;
    }

    // 推理模型兜底：reasoning_content / thinking（避免 content 为空但思考非空时被判空）
    const reasoningKeys = ['reasoning_content', 'reasoning', 'thinking', 'thought'];
    for (const k of reasoningKeys) {
      if (typeof r[k] === 'string' && r[k].trim()) return r[k];
    }

    return '';
  }

  // 截断检测：思维链返回内容是否被截断/不完整
  // - 只用来识别"真·空回复 / 几乎完全没输出"的情况
  // - 默认 minLength=50：模型正常思考即使简短也会远超 50 字符；
  //   之前 300 的阈值过严，会把"模型实际有正常输出"的简短回复误判为空回复并疯狂重试。
  function foxJudgeIsEmptyOrError(result, minLength = 50) {
    // ✅ 只检测字数：空 / 非字符串 / 长度不够都视为需要重试，不再匹配任何文字内容。
    //    避免模型正常输出（含"抱歉/cannot/error"等词或恰好命中拒答正则）被误判重试。
    if (!result || typeof result !== 'string') return true;
    const trimmed = result.trim();
    if (!trimmed) return true;
    if (trimmed.length < minLength) return true;
    return false;
  }

  // ✅ 结构完整性检测改为字数化：长度达标即合格，不再检查具体板块标题，
  //    防止模型正常输出但板块名换了写法时被误判残缺触发重试。
  function foxJudgePhase1IsStructureOk(text) {
    if (!text || typeof text !== 'string') return false;
    return text.trim().length >= 50;
  }

  function foxJudgePhase2IsStructureOk(text) {
    if (!text || typeof text !== 'string') return false;
    return text.trim().length >= 50;
  }

  async function foxJudgeRunPhase1WithRetry(cfg, contextText, maxRetries = 3) {
    foxJudgeDiag('第一阶段:重试器入口', {
      retryEnabled: !!cfg?.retryEnabled,
      maxRetries,
      contextLength: String(contextText || '').length,
    });
    // 🔄 重试总开关关闭时：只跑一次，不检测空回/报错，直接返回结果（报错照常上抛）。
    if (!cfg?.retryEnabled) {
      const startedAt = Date.now();
      try {
        const raw = await foxJudgeRunPhase1(cfg, contextText);
        const cleaned = foxJudgeStripStrayThinkTags(raw);
        foxJudgeDiag('第一阶段:单次完成', { durationMs: Date.now() - startedAt, rawLength: String(raw || '').length, cleanedLength: cleaned.length }, 'info');
        return cleaned;
      } catch (e) {
        foxJudgeDiag('第一阶段:单次异常', { durationMs: Date.now() - startedAt, error: foxJudgeDiagError(e) }, 'error');
        throw e;
      }
      // 🦊 在拼接前清洗 AI 原始输出里的 <think_fox~> / </think_fox~> 杂散标签，
      //    避免 AI 在被要求纯思考时仍然吐出标签，把后续拼接逻辑卡掉。
      //    注意：只清这两个标签本身，绝不清拼接阶段最终包裹的 <think_fox~>...</think_fox~>。
    }
    // 只要识别"真·空回复"即可，正常思考即使简短也会远超 50 字符，避免误伤
    const MIN_LEN = 50;
    let lastError = null;
    for (let attempt = 0; attempt < maxRetries + 1; attempt++) {
      const attemptStartedAt = Date.now();
      foxJudgeDiag('第一阶段:尝试开始', { attempt: attempt + 1, totalAttempts: maxRetries + 1 });
      try {
        const raw = await foxJudgeRunPhase1(cfg, contextText);
        // 🦊 关键：先清洗 AI 原始输出的杂散 <think_fox~> 标签，再做"空回复/字数不足"判断，
        //    这样能避免"AI 整段思考被 <think_fox~></think_fox~> 包裹、清洗后变空"被误判为合格。
        const result = foxJudgeStripStrayThinkTags(raw);
        // 只检测字数：达标即合格，不再匹配文字内容/板块标题
        const emptyOrErr = foxJudgeIsEmptyOrError(result, MIN_LEN);
        if (!emptyOrErr) {
          foxJudgeDiag('第一阶段:尝试成功', { attempt: attempt + 1, durationMs: Date.now() - attemptStartedAt, rawLength: String(raw || '').length, resultLength: result.length }, 'info');
          return result;
        }
        foxJudgeDiag('第一阶段:返回不合格', { attempt: attempt + 1, durationMs: Date.now() - attemptStartedAt, resultLength: result.length, minLength: MIN_LEN }, 'warn');
        if (attempt < maxRetries) {
          const trimmedLen = result?.trim()?.length || 0;
          const reason = trimmedLen === 0 ? '空回复'
            : `字数不足（仅 ${trimmedLen} 字符，要求 ≥ ${MIN_LEN}）`;
          log(`[狐裁] 第一阶段${reason}，第 ${attempt + 1} 次重试……`);
          ssTaskToast('fox_judge_chain', `🦊 狐裁：第一阶段${reason}，重试 ${attempt + 1}/${maxRetries}…`);
          await new Promise(r => setTimeout(r, 1000));
        }
        lastError = new Error('第一阶段返回空或字数不足');
      } catch (e) {
        lastError = e;
        foxJudgeDiag('第一阶段:尝试异常', { attempt: attempt + 1, durationMs: Date.now() - attemptStartedAt, error: foxJudgeDiagError(e) }, 'error');
        if (attempt < maxRetries && !foxJudgeIsUserCancellation(e)) {
          log(`[狐裁] 第一阶段失败，第 ${attempt + 1} 次重试……`, e);
          ssTaskToast('fox_judge_chain', `🦊 狐裁：第一阶段报错，重试 ${attempt + 1}/${maxRetries}…`);
          await new Promise(r => setTimeout(r, 1500));
        } else {
          throw e;
        }
      }
    }
    throw lastError || new Error('第一阶段重试用尽仍为空');
  }

  async function foxJudgeRunPhase2WithRetry(cfg, phase1Result, userInput, contextText, maxRetries = 3) {
    foxJudgeDiag('第二阶段:重试器入口', {
      retryEnabled: !!cfg?.retryEnabled,
