  // 🦊 狐裁修正4：剥掉提示词开头的空行/纯空白行，保证首字符就是有效正文。
  //    部分中转/API 的 prefix cache 按字节精确匹配；开头多一个空行会导致整段缓存命中率为 0。
  //    同时兼容 localStorage 里残留的旧版带空行提示词。
  function foxJudgeStripLeadingBlankLines(text) {
    return String(text || '').replace(/^(?:[ \t]*\r?\n)+/, '');
  }

  function ssNormalizeFoxJudgePhase2Prompt(prompt) {
