      .replace(/（参考第一阶段固定规则确认结果，只做本轮动态判断）/g, '（直接参考完整上下文，只做本轮动态判断）')
      .replace(/预演与部分一分析结论一致？/g, '预演与上下文、设定和规则一致？');
  }

