    //    让 ssCancelTask -> stopGenerationById 能真正中断本阶段的生成
    foxJudgeDiag('第二阶段:请求参数就绪', {
      orderedPromptTypes: ordered.map(x => typeof x === 'string' ? `[占位符]${x}` : `[${x?.role || '?'}]${String(x?.content || '').slice(0, 40)}…`),
      hasWorldInfoBefore: ordered.includes('world_info_before'),
      hasWorldInfoAfter: ordered.includes('world_info_after'),
      systemPromptLengths: ordered.map(x => String(x?.content || '').length),
      totalPromptChars: ordered.reduce((sum, x) => sum + String(x?.content || '').length, 0) + String(params.user_input || '').length,
      contextLength: String(contextText || '').length,
      contextContainsWorldInfo: /【世界书|world_info/i.test(String(contextText || '')),
      contextFirst200: String(contextText || '').slice(0, 200),
      phase1Length: String(phase1Result || '').length,
      userInputLength: String(userInputInject || '').length,
      hasCustomApi: !!customApi,
      customApiSource: customApi?.source || 'current',
      customApiModel: customApi?.model || '',
      hasExtraInject: !!__extra,
      extraInjectFields: __extra ? Object.keys(__extra).filter(k => __extra[k]) : [],
    });
    log('[狐裁·世界书诊断] 第二阶段 ordered_prompts 结构:', params.ordered_prompts.map((p, i) => {
      if (typeof p === 'string') return `[${i}] 占位符: ${p}`;
      const preview = String(p?.content || '').replace(/\n/g, ' ').slice(0, 80);
      return `[${i}] ${p?.role || '?'}: ${preview}…`;
    }));
    const r = await ssGenerateRaw('fox_judge_chain', params, '狐裁第二阶段');
    // 中断时 ssCancelTask 会让 gr 抛 abort，由 foxJudgeRunPhase2WithRetry 的 abort 正则识别后短路；
    // 即使 gr 返回空字符串，foxJudgeIsEmptyOrError 也会兜底重试或上抛。
    // ✅ 用鲁棒提取器，避免不同模型 / custom_api 返回形态（OpenAI choices / Anthropic content blocks /
    //    推理模型 reasoning_content 等）被错判为"空回复"。
    const text = foxJudgeExtractText(r);
    foxJudgeDiag('第二阶段:响应提取完成', {
      durationMs: Date.now() - phaseStartedAt,
      response: foxJudgeResponseSummary(r),
      extractedLength: String(text || '').trim().length,
    }, text && text.trim() ? 'info' : 'warn');
    if (!text || !text.trim()) {
      try { log('[狐裁] 第二阶段 generateRaw 返回未识别形态，原始结构=', r); } catch {}
    }
    return String(text || '').trim();
  }

  function foxJudgeBuildDynamicContext(userInput, lastAssistantText) {
    const lines = [];
    if (userInput) lines.push(`【本轮用户输入】\n${userInput}`);
    if (lastAssistantText) lines.push(`【最新 AI 回复｜参考】\n${lastAssistantText}`);
    lines.push('请基于以上内容进行第二阶段思考。');
    return lines.join('\n\n');
  }

  function foxJudgeStripThinkBlock(text) {
    return String(text || '').replace(/<think_fox~>[\s\S]*?<\/think_fox~>/g, '').trim();
  }

  // ✅ 安全清理：仅移除模型违规输出的杂散 <think_fox~> / </think_fox~> 标签本身，
  //    绝不按位置截断后续内容。
  //    用于单独的 phase1 / phase2 思考文本（纯思考，不含真正的标签语义）。
  //    之前 phase1/phase2 误用 foxJudgeCleanLeakageAfterThinkClose，
  //    一旦模型在思考开头/中部漏写一个 </think_fox~>（提示词禁止但模型常违反），
  //    lastIndexOf 截断会把该标签之后的真实思考内容全部删掉 → 第二阶段被拼成空气。
  //
  // 🦊 同时清理 ``` 代码围栏：部分模型（尤其 Claude / DeepSeek 思考模型）会把思考用
  //    ```think / ```markdown / ``` 之类的代码块包起来输出，拼接到最终 <think_fox~>...</think_fox~>
  //    里之后，```会被酒馆 markdown 渲染识别成代码块起止，导致后续整段正文 / 选项 / 状态栏
  //    被一并渲染成 monospace 黑框 = "格式完全爆炸"。
  //    清理范围：成对/未成对的 ``` 围栏全部去掉，但仅作用于一/二阶段思考原文（拼接前），
  //    不影响外层 <think_fox~>...</think_fox~> 的合法标签。
  function foxJudgeStripStrayThinkTags(text) {
    let s = String(text || '');
    // 1) 清掉 think_fox~ 杂散标签（成对/未成对都清）
    s = s.replace(/<\/?think_fox~>/g, '');
    // 2) 清掉所有 ``` 代码围栏（包括 ```lang 起始行）。
    //    - ```lang 这类带语言标识的起始行：```python / ```think / ```markdown 等 → 整行连同换行一起去掉
    //    - 纯 ``` 行 / 行内 ``` → 直接删除三个反引号
    //    注意：不动单反引号 ` 与双反引号 ``，避免破坏正常文字。
    s = s.replace(/```[a-zA-Z0-9_-]*\s*\n?/g, '');
    s = s.replace(/```/g, '');
    return s.trim();
  }

  // ⚠️ 破坏性：lastIndexOf 之后全部截断。
  //    只可用于"已经成型的、最终要注入楼层的、外层带 <think_fox~>...</think_fox~> 的完整块"，
  //    用来切掉闭合标签之后泄漏的正文。禁止用于单独的 phase1/phase2 思考文本！
  function foxJudgeCleanLeakageAfterThinkClose(text) {
    let s = String(text || '');
    const closeIdx = s.lastIndexOf('</think_fox~>');
    if (closeIdx >= 0) {
      s = s.substring(0, closeIdx + '</think_fox~>'.length);
    }
    return s.trim();
  }

  // ✅ 仅第一阶段注入拼接 + 写入内存缓存。
  //    被两处共用：1) cfg.phase1Only 快速模式； 2) 第二阶段重试用尽时的兜底分支。
  //    抽出来避免两边模板/赋值漂移（之前曾因复制粘贴导致两份逻辑不同步的风险）。
  function foxJudgeBuildPhase1OnlyInjection(phase1Result) {
    // ✅ 先去掉成对的 think 块（若模型把自己包了一层），再去掉杂散标签本身；
    //    绝不对单段思考做 lastIndexOf 截断，避免吞掉真实内容。
    let cleanPhase1 = foxJudgeStripThinkBlock(phase1Result || '');
    cleanPhase1 = foxJudgeStripStrayThinkTags(cleanPhase1);
    const combined = `<think_fox~>
${cleanPhase1}
思考完毕，立刻按要求开始输出正文
</think_fox~>`;
    const cleaned = foxJudgeCleanLeakageAfterThinkClose(combined);
    foxJudgeLastCombined = cleaned;
    foxJudgePendingInject = cleaned;
    foxJudgePreservedChain = cleaned;
    foxJudgeInjectVersion++;
    return combined;
  }

  function foxJudgeStripXmlTags(text) {
    const PH_OPEN = '\x00THINK_FOX_OPEN\x00';
    const PH_CLOSE = '\x00THINK_FOX_CLOSE\x00';
    // 🦊 标签清洗：
    //   旧版正则 <\/?[a-zA-Z_][a-zA-Z0-9_\-]*[^>]*>
    //   只匹配 ASCII 标签名，导致中文标签（例如 <平行世界> / <狐忆> / <人物档案>）
    //   一路漏出来，注入到主模型输出后，被酒馆当成未识别 HTML 渲染，格式爆炸。
    //   现在改成 <\/?[^<>\r\n]*> ：匹配任何 < 开头、> 结尾、且中间不再嵌套 < / > / 换行 的标签，
    //   无视标签名是中文 / 英文 / 数字 / 符号，全部清掉。
    //   排除换行的目的：避免 AI 把 < / > 当数学比较符号、且裸 < 与远处 > 跨行时被整段误吞。
    //   <think_fox~> / </think_fox~> 在清洗前已被占位符替换出去，不会被误删，
    //   清洗后再换回真实标签，所以思维链外层标签完整保留。
    return String(text || '')
      .replace(/<think_fox~>/g, PH_OPEN)
      .replace(/<\/think_fox~>/g, PH_CLOSE)
      .replace(/<\/?[^<>\r\n]*>/g, '')
      .replace(new RegExp(PH_OPEN.replace(/\x00/g, '\\x00'), 'g'), '<think_fox~>')
      .replace(new RegExp(PH_CLOSE.replace(/\x00/g, '\\x00'), 'g'), '</think_fox~>')
      .trim();
  }

  async function foxJudgeInjectIntoMainOutput(targetMessageId) {
    try {
      const rawCombined = foxJudgeLastCombined || foxJudgePendingInject;
      if (!rawCombined) {
        foxJudgeDiag('楼层注入:跳过-无思维链', { targetMessageId }, 'warn');
        return;
      }

      foxJudgeDiag('楼层注入:开始', { targetMessageId, rawCombinedLength: rawCombined.length });

      const combined = foxJudgeStripXmlTags(rawCombined);
      const cleanedCombined = foxJudgeCleanLeakageAfterThinkClose(combined);

      const glmi = getFn('getLastMessageId');
      const gcm = getFn('getChatMessages');
      const scm = getFn('setChatMessages');
      if (!glmi || !gcm || !scm) {
        foxJudgeDiag('楼层注入:跳过-API缺失', { hasGetLastMessageId: !!glmi, hasGetChatMessages: !!gcm, hasSetChatMessages: !!scm }, 'error');
        return;
      }

      const lastId = targetMessageId != null ? targetMessageId : glmi();
      if (lastId < 0) {
        foxJudgeDiag('楼层注入:跳过-楼层ID无效', { lastId }, 'warn');
        return;
      }

      const cm = gcm(lastId, { include_swipes: true })?.[0];
      if (!cm || cm.role !== 'assistant') {
        foxJudgeDiag('楼层注入:跳过-目标不是assistant', { lastId, exists: !!cm, role: cm?.role || '' }, 'warn');
        return;
      }

      const cid = cm.swipe_id ?? 0;
      // 🛟 正文保护：优先读 swipe，缺失时回退到 message/mes，避免读到空正文后用思维链覆盖掉正文
      const original = String(cm.swipes?.[cid] || cm.message || cm.mes || '');

      if (original.includes('<think_fox~>')) {
        foxJudgeDiag('楼层注入:跳过-已存在思维链', { lastId, swipeId: cid, originalLength: original.length });
        return;
      }

      // 🛟 正文保护：正文尚未落盘（空）时绝不覆盖，否则会把"只有思维链"写进去吞掉正文
      if (!original.trim()) {
        foxJudgeDiag('楼层注入:跳过-正文为空(尚未落盘)', { lastId, swipeId: cid }, 'warn');
        return;
      }

      const cleaned = foxJudgeStripThinkBlock(original);
      // 🛟 正文保护：用"仅清杂散标签"的安全清洗，绝不用会截断的 foxJudgeCleanLeakageAfterThinkClose
      //    （后者会按最后一个 </think_fox~> 截断其后内容，正文里若混入杂散闭合标签就会被吞）
      const cleanedOrig = foxJudgeStripStrayThinkTags(cleaned);
      const newContent = `${cleanedCombined}\n\n${cleanedOrig}`;

      const nsa = [...(cm.swipes || [])];
      nsa[cid] = newContent;
      await scm([{ message_id: lastId, swipe_id: cid, swipes: nsa }], { refresh: 'affected' });
      log('[狐裁] 思维链已注入到主模型输出楼层顶部');
      foxJudgeDiag('楼层注入:成功', { lastId, swipeId: cid, originalLength: original.length, newLength: newContent.length }, 'info');
    } catch (e) {
      log('[狐裁] 注入主模型输出失败', e);
      foxJudgeDiag('楼层注入:异常', { targetMessageId, error: foxJudgeDiagError(e) }, 'error');
    }
  }

  let foxJudgeLastCombined = '';
  let foxJudgePendingInject = '';
  // 🦊 保留上一次完整思维链（含 phase1+phase2）。与 foxJudgeLastCombined 不同的是：
  //   - foxJudgeLastCombined / foxJudgePendingInject 是"本轮主请求待注入"的一次性缓存，
  //     MESSAGE_RECEIVED 600ms 后会被清空，避免被下一个主请求误注入。
  //   - foxJudgePreservedChain 不参与"本轮注入"，仅在用户**关闭** swipe/reroll 重新思考时，
  //     由 reroll/swipe 拦截器读取它，原样塞回 foxJudgeLastCombined + foxJudgePendingInject
  //     供本次新的主请求使用——语义即"不重跑第二阶段，沿用上一次完整思维链"。
  //   - 只有 CHAT_CHANGED / 用户主动关闭狐裁开关 / 清空全部缓存按钮 时才清空。
  let foxJudgePreservedChain = '';
  // 🦊 注入版本号：每完成一次两阶段思考就 +1。
  //    用于解决 MESSAGE_RECEIVED 600ms 延迟清理 vs 新一轮思维链已就位的竞态——
  //    旧的 MESSAGE_RECEIVED 清理只能清掉自己那一版的缓存，绝不会误清掉新一版。
  let foxJudgeInjectVersion = 0;
  // 🦊 标记“本次主请求是否已成功把思维链注入到请求体最下方”。
  //    供 toast 防抖：同一次主请求只弹一次“已注入”提示，避免
  //    GENERATE_AFTER_COMBINE_PROMPTS 与 CHAT_COMPLETION_PROMPT_READY 双触发各弹一次。
  let foxJudgeInjectedToastVersion = 0;

  // ==================== 🦊 数据库冲突适配（SP·数据库 III 共存） ====================
  //
  // 背景：SP·数据库 III 脚本会在 GENERATION_AFTER_COMMANDS（发送前剧情规划）和
  // GENERATION_ENDED（发送后表格更新）两个时机发起自己的 AI 生成请求，和狐裁的
  // 一/二阶段思考请求"抢输入"。本模块【只做适配，不抄袭数据库任何代码】：
  //   1) 通过数据库自身公开的互斥标记 __ACU_STAR_DB_III_LOADED__ 判断数据库是否在场；
  //   2) 通过酒馆全局 SillyTavern.generating 判断"是否有生成正在进行"（数据库的
  //      表格更新/剧情规划生成都会置位该标记）；
  //   3) 狐裁一/二阶段开始前，若数据库在场且正在生成，则等待其结束再推进思考；
  //   4) 若检测到数据库在场且狐忆(自动推进)同时开启，弹窗提醒用户二者冲突。
  const SS_DB_ADAPTER = {
    PRESENT_FLAG: '__ACU_STAR_DB_III_LOADED__',
    WARN_DISMISS_KEY: 'SPreset_DbConflict_WarnDismissed',
    waitTimeoutMs: 90000,
    waitIntervalMs: 300,
  };

  let ssDbConflictWarnShownThisSession = false;

  function ssDbAdapterTopWin() {
    try { return topWindow || window; } catch { return window; }
  }

  function ssIsDatabasePresent() {
    try {
      return ssDbAdapterTopWin()[SS_DB_ADAPTER.PRESENT_FLAG] === true;
    } catch { return false; }
  }

  // 是否有"外部生成"正在进行。在狐裁拦截发送的时刻，主模型尚未开始生成，因此该
  // 标记为真通常意味着数据库上一轮的后台生成（表格更新/剧情规划）尚未结束——
  // 正是"抢输入"的源头。仅作适配判断，不读写数据库内部状态。
  function ssIsExternalGenerationBusy() {
    try {
      return ssDbAdapterTopWin().SillyTavern?.generating === true;
    } catch { return false; }
  }

  // 狐裁一/二阶段开始前调用：若数据库在场且有生成在进行，等待其结束再返回。
  async function ssWaitForDatabaseIdle({ reason = '' } = {}) {
    if (!ssIsDatabasePresent()) {
      return { waited: false, present: false, reason: 'db_absent' };
    }
    if (!ssIsExternalGenerationBusy()) {
      return { waited: false, present: true, reason: 'already_idle' };
    }
    const startedAt = Date.now();
    let warned = false;
    while (ssIsExternalGenerationBusy()) {
      if (Date.now() - startedAt > SS_DB_ADAPTER.waitTimeoutMs) {
        log('[狐裁][数据库适配] 等待数据库结束超时，继续推进狐裁思考', { reason, waitedMs: Date.now() - startedAt });
        return { waited: true, present: true, timedOut: true, reason: 'timeout', waitedMs: Date.now() - startedAt };
      }
      if (!warned) {
        warned = true;
        try { toast('⏳ 检测到数据库正在更新，狐裁等待其结束后再思考…', 'info'); } catch {}
      }
      await new Promise(r => setTimeout(r, SS_DB_ADAPTER.waitIntervalMs));
    }
    log('[狐裁][数据库适配] 数据库已结束，开始推进狐裁思考', { reason, waitedMs: Date.now() - startedAt });
    return { waited: true, present: true, reason: 'idle', waitedMs: Date.now() - startedAt };
  }

  // ---- 狐忆 × 数据库 冲突弹窗 ----
  function ssFoxMemoryActive() {
    try { return !!foxMemoryConfig?.autoPush; } catch { return false; }
  }

  function ssMaybeWarnDbFoxMemoryConflict() {
    try {
      if (!ssIsDatabasePresent()) return;
      if (!ssFoxMemoryActive()) return;
      if (ssDbConflictWarnShownThisSession) return;
      try { if (localStorage.getItem(SS_DB_ADAPTER.WARN_DISMISS_KEY) === 'true') return; } catch {}
      ssDbConflictWarnShownThisSession = true;
      ssShowDbFoxMemoryConflictModal();
    } catch (e) { try { log('[狐裁][数据库适配] 冲突弹窗异常', e); } catch {} }
  }

  function ssShowDbFoxMemoryConflictModal() {
    try {
      const doc = topDoc || document;
      const overlayId = 'ss-db-conflict-overlay';
      doc.getElementById(overlayId)?.remove();
      const overlay = doc.createElement('div');
      overlay.id = overlayId;
      overlay.style.cssText = 'position:fixed;inset:0;z-index:10000000;background:rgba(0,0,0,0.55);display:flex;align-items:center;justify-content:center;font-family:system-ui,-apple-system,"Microsoft YaHei",sans-serif;';
      const box = doc.createElement('div');
      box.style.cssText = 'max-width:440px;width:calc(100% - 48px);background:linear-gradient(160deg,rgba(28,20,22,0.98),rgba(18,13,15,0.98));border:1px solid rgba(232,120,74,0.45);border-radius:14px;box-shadow:0 12px 48px rgba(0,0,0,0.6);padding:22px 22px 18px;color:#e8d8d0;';
      box.innerHTML =
        '<div style="display:flex;align-items:center;gap:10px;margin-bottom:12px;">' +
          '<span style="font-size:22px;">⚠️</span>' +
          '<span style="font-size:17px;font-weight:700;color:#f0a070;">检测到冲突：狐忆 × 数据库</span>' +
        '</div>' +
        '<div style="font-size:13.5px;line-height:1.7;color:#cdbcb4;">' +
          '检测到 <b style="color:#f0a070;">SP·数据库 III</b> 与 <b style="color:#f0a070;">狐忆（自动推进）</b> 同时开启。<br>' +
          '两者都会拦截发送并各自发起 AI 请求，会互相"抢输入"，导致冲突、错乱或重复生成。<br><br>' +
          '建议二选一：<b>关闭狐忆自动推进</b>，或 <b>关闭/卸载数据库脚本</b>。<br>' +
          '狐裁（五狐裁决）已做适配：会等待数据库结束再推进一/二阶段思考。' +
        '</div>' +
        '<div style="display:flex;gap:10px;margin-top:18px;justify-content:flex-end;">' +
          '<button id="ss-db-conflict-never" style="cursor:pointer;padding:8px 14px;border-radius:8px;border:1px solid rgba(255,255,255,0.15);background:rgba(255,255,255,0.05);color:#cdbcb4;font-size:13px;">不再提醒</button>' +
          '<button id="ss-db-conflict-ok" style="cursor:pointer;padding:8px 16px;border-radius:8px;border:none;background:linear-gradient(145deg,#e8784a,#d9663a);color:#fff;font-size:13px;font-weight:600;">知道了</button>' +
        '</div>';
      overlay.appendChild(box);
      (doc.body || doc.documentElement).appendChild(overlay);
      const close = () => { try { overlay.remove(); } catch {} };
      overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
      box.querySelector('#ss-db-conflict-ok').onclick = close;
      box.querySelector('#ss-db-conflict-never').onclick = () => {
        try { localStorage.setItem(SS_DB_ADAPTER.WARN_DISMISS_KEY, 'true'); } catch {}
        close();
        try { toast('已关闭"狐忆×数据库"冲突提醒', 'info'); } catch {}
      };
    } catch (e) { try { log('[狐裁][数据库适配] 弹窗构建异常', e); } catch {} }
  }

  async function foxJudgeRunChain({ userInput, lastAssistantText, forceRefresh = false, phase2Only = false, excludeLastAssistant = false, diagnosticSource = 'runChain' } = {}) {
    const cfg = foxJudgeReadConfig();
    if (!cfg.enabled) return { combined: '', phase1: '', phase2: '', skipped: 'disabled' };

    const diag = foxJudgeBeginDiag(diagnosticSource, {
      userInputLength: String(userInput || '').length,
      lastAssistantLength: String(lastAssistantText || '').length,
      forceRefresh,
      phase2Only,
      config: {
        phase1Only: cfg.phase1Only,
        phase1Fixed: cfg.phase1Fixed,
        cacheEnabled: cfg.cacheEnabled,
        retryEnabled: cfg.retryEnabled,
        maxRetries: cfg.maxRetries,
        contextFloors: cfg.contextFloors,
        strength: cfg.strength,
        apiType: cfg.apiType,
        customModel: cfg.customApi?.model || '',
        hasCustomUrl: !!cfg.customApi?.apiurl,
        hasCustomKey: !!cfg.customApi?.key,
        contentFilterEnabled: cfg.filterSettings?.enableContentFilter !== false,
        includeTagPairCount: cfg.filterSettings?.includeTagPairs?.length || 0,
        excludeTagPairCount: cfg.filterSettings?.excludeTagPairs?.length || 0,
      },
      environment: {
        href: (() => { try { return String(topWindow?.location?.href || location.href).replace(/[?#].*$/, ''); } catch { return ''; } })(),
        userAgent: (() => { try { return navigator.userAgent; } catch { return ''; } })(),
        hasGenerateRaw: typeof getFn('generateRaw') === 'function',
        hasStopGenerationById: typeof getFn('stopGenerationById') === 'function',
        activeTaskNames: [...ssActiveTasks.keys()],
      },
    });
    let diagOutcome = 'unknown';
    let diagResult = {};

    // ✅ 重入保护：上一次还在跑就拒绝本次（不强制取消上一次）
    //    上层（foxPushInterceptAndPolish / foxJudgeInterceptAndThink / foxJudgeHandleRerollSwipe）
    //    都已经做了"自身正在思考"的拦截，正常路径下不会有重复调用进来。
    //    这里只做兜底，避免之前"取消上一次又立刻返回 cancelled、上层却继续 fire 主请求"
    //    导致正文一边出、思维链一边在跑的循环。
    if (ssIsTaskRunning('fox_judge_chain')) {
      log('[狐裁] 检测到上一次思维链仍在进行，拒绝本次重入');
      foxJudgeEndDiag('busy', { activeTaskNames: [...ssActiveTasks.keys()] }, diag);
      return { combined: '', phase1: '', phase2: '', skipped: 'busy' };
    }

    // ✅ phase2Only 与 phase1Only 互斥：调用方要"重跑第二阶段"，但配置是"仅第一阶段"，
    //    直接放弃本次思考（外层调用点本就有 cfg.phase1Only return 的前置守卫，这里是兜底）
    if (phase2Only && cfg.phase1Only) {
      log('[狐裁] phase2Only 与 phase1Only 互斥，本次跳过狐裁思考');
      foxJudgeEndDiag('phase1_only_conflict', {}, diag);
      return { combined: '', phase1: '', phase2: '', skipped: 'phase1_only_conflict' };
    }

    const charId = getCurrentCharId();
    let phase1Result;
    let phase1FromCache = false;

    // 🦊 数据库冲突适配：狐裁一/二阶段开始前，若数据库在场且正在生成，
    //    先等待数据库结束，避免和数据库的表格更新/剧情规划生成"抢输入"。
    try {
      const dbWait = await ssWaitForDatabaseIdle({ reason: diagnosticSource });
      foxJudgeDiag('数据库适配:等待结果', {
        present: dbWait.present,
        waited: dbWait.waited,
        timedOut: dbWait.timedOut,
        waitedMs: dbWait.waitedMs,
        reason: dbWait.reason,
      }, dbWait.timedOut ? 'warn' : 'log', diag);
    } catch (e) {
      log('[狐裁][数据库适配] 等待异常（忽略，继续推进）', e);
    }

    ssStartTask('fox_judge_chain', '狐裁思维链');
    foxJudgeDiag('任务已创建', {
      charId,
      taskGenerationId: ssActiveTasks.get('fox_judge_chain')?.generationId,
    }, 'info', diag);

    try {
      const contextFloors = Number.isFinite(cfg.contextFloors) && cfg.contextFloors > 0
        ? Math.floor(cfg.contextFloors)
        : 0;
      const filterSettings = {
        ...(cfg.filterSettings || FOX_JUDGE_DEFAULT_FILTER_SETTINGS),
        contextFloors,
      };
      // 与 V14.8 一致：通过 in_use 预设的 dry-run 捕获完整组合 prompt，使狐裁读取到
      // 当前启用的预设条目、fox_extra、破限、角色卡、世界书和聊天楼层。
      // ssCaptureMainRequestMessages 会在请求发往上游前短路，捕获后再统一执行标签过滤。
      foxJudgeDiag('上下文:构建开始', { contextFloors, filterSettings }, 'log', diag);
      const contextStartedAt = Date.now();
      const contextText = await ssBuildFilteredMainContextText('狐裁', filterSettings, {
        skipRoleLabels: true,
        exactChatFloors: contextFloors,
        requireCaptured: true,
        excludeLastAssistant,
        latestUserInput: userInput,
      });
      foxJudgeDiag('上下文:构建完成', {
        durationMs: Date.now() - contextStartedAt,
        contextLength: contextText.length,
        containsWorldInfo: contextText.includes('【世界书'),
        containsUserInput: !!userInput && contextText.includes(String(userInput).slice(0, Math.min(120, String(userInput).length))),
      }, 'info', diag);

      // Phase 1：phase2Only 模式直接走缓存（必须有缓存才能用，否则跑一次 Phase1）
      if (phase2Only) {
        // ✅ phase2Only 含义就是"复用已有 phase1"，因此读缓存不再受 cacheEnabled 限制：
        //    即使用户关闭了缓存写入，只要存在已保存的非空 phase1_result（例如来自快速模式
        //    或用户手动粘贴保存），就用它；这样能避免无意义地重跑 phase1 并保留用户编辑。
        try { foxJudgeCheckAndInvalidateIfChanged(); } catch {}
        const staticCache = foxJudgeGetStaticCache(charId);
        foxJudgeDiag('缓存:phase2Only检查', {
          exists: !!staticCache,
          version: staticCache?.version,
          stale: staticCache?.stale === true,
          resultLength: String(staticCache?.phase1_result || '').length,
          phase1Fixed: cfg.phase1Fixed,
        }, 'log', diag);
        if (staticCache && (cfg.phase1Fixed || !staticCache.stale) && typeof staticCache.phase1_result === 'string' && staticCache.phase1_result.trim()) {
          phase1Result = staticCache.phase1_result;
          phase1FromCache = true;
          log('[狐裁] phase2Only：命中缓存，跳过第一阶段');
        }
        if (!phase1Result) {
          // 没缓存也只跑一次 Phase1（不强制刷新），跑完缓存起来
          ssTaskToast('fox_judge_chain', '🦊 狐裁：phase2Only 但无缓存，先补跑第一阶段……');
          phase1Result = await foxJudgeRunPhase1WithRetry(cfg, contextText, cfg.maxRetries);
          // ✅ 写入缓存：即使 cfg.cacheEnabled=false 也写入，因为本次是 phase2Only 显式语义，
          //    用户既然走 phase2Only 就一定会复用 phase1，不写缓存等同于每次都重跑。
          if (phase1Result) {
            foxJudgeSaveStaticCache(charId, {
              version: 2,
              char_id: charId,
              phase1_result: phase1Result,
              strength: cfg.strength,
              created_at: new Date().toISOString(),
            });
          }
        }
      } else {
        // 正常模式：优先检查缓存
        if ((cfg.cacheEnabled || cfg.phase1Fixed) && !forceRefresh) {
          foxJudgeCheckAndInvalidateIfChanged();
          const staticCache = foxJudgeGetStaticCache(charId);
          foxJudgeDiag('缓存:正常模式检查', {
            exists: !!staticCache,
            version: staticCache?.version,
            stale: staticCache?.stale === true,
            resultLength: String(staticCache?.phase1_result || '').length,
            forceRefresh,
          }, 'log', diag);
          // ✅ 命中条件：phase1_result 必须是非空字符串、且不是 stale。
          //    避免之前若 cache 存了空字符串（例如保存编辑时被清空）也算"命中缓存"
          //    导致主流程拿到空 phase1 直接进二阶段（外观上"无视第一段"）。
          if (staticCache && (cfg.phase1Fixed || !staticCache.stale) && typeof staticCache.phase1_result === 'string' && staticCache.phase1_result.trim()) {
            phase1Result = staticCache.phase1_result;
            phase1FromCache = true;
            log('[狐裁] 命中缓存，跳过第一阶段');
          }
        }

        if (!phase1Result) {
          ssTaskToast('fox_judge_chain', '🦊 狐裁：正在思考第一阶段……');

          phase1Result = await foxJudgeRunPhase1WithRetry(cfg, contextText, cfg.maxRetries);

          if (phase1Result && (cfg.cacheEnabled || cfg.phase1Fixed)) {
            foxJudgeSaveStaticCache(charId, {
              version: 2,
              char_id: charId,
              phase1_result: phase1Result,
              strength: cfg.strength,
              created_at: new Date().toISOString(),
            });
            log('[狐裁] 第一阶段完成，已缓存');
          } else {
            log('[狐裁] 第一阶段完成（未缓存，缓存已关闭）');
          }
        }
      }

      // phase1Only：仅在非 phase2Only 模式下生效；phase2Only 不允许走 phase1Only 短路
      if (cfg.phase1Only && !phase2Only) {
        const combined = foxJudgeBuildPhase1OnlyInjection(phase1Result);
        log('[狐裁] 仅第一阶段模式：跳过第二阶段，Phase1来自缓存=', phase1FromCache);

        toast('🦊 狐裁思维链完成（仅第一阶段）', 'success');

        diagOutcome = 'success';
        diagResult = { mode: 'phase1_only', phase1Length: String(phase1Result || '').length, combinedLength: combined.length };
        return { combined, phase1: phase1Result, phase2: '', skipped: 'phase1_only' };
      }

      ssTaskToast('fox_judge_chain', '🦊 狐裁：正在思考第二阶段……');

      // ✅ 第二阶段失败兜底：如果第二阶段重试用尽仍失败，但第一阶段已正常输出，
      //    则降级为仅第一阶段注入（等同于快速模式），不要直接放过让主模型在没有思维链下出正文。
      let phase2Result = '';
      let phase2Failed = false;
      let phase2FailMsg = '';
      try {
        phase2Result = await foxJudgeRunPhase2WithRetry(cfg, phase1Result, userInput, contextText, cfg.maxRetries);
      } catch (phase2Err) {
        const m2 = phase2Err?.message || String(phase2Err || '');
        // 中断 / 取消 直接上抛由外层 catch 处理（不要静默吞掉）
        if (foxJudgeIsUserCancellation(phase2Err)) throw phase2Err;
        phase2Failed = true;
        phase2FailMsg = m2;
        log('[狐裁] 第二阶段重试用尽，触发兜底：仅注入第一阶段（等同快速模式）。错误=', phase2Err);
      }

      if (phase2Failed) {
        // 兜底分支：与 phase1Only 一致的拼接 + 注入逻辑（共用 foxJudgeBuildPhase1OnlyInjection）
        if (!phase1Result || !String(phase1Result).trim()) {
          // 第一阶段也没有内容（理论上前面已重试过），直接报错让外层处理
          throw new Error(`第二阶段失败且第一阶段无内容：${phase2FailMsg || '未知原因'}`);
        }
        const combined = foxJudgeBuildPhase1OnlyInjection(phase1Result);
        log('[狐裁] 兜底完成：仅注入第一阶段（length=', combined.length, '），Phase1来自缓存=', phase1FromCache);

        toast('⚠️ 狐裁：第二阶段失败，已兜底仅注入第一阶段', 'warning');

        diagOutcome = 'phase2_failed_fallback';
        diagResult = { phase2FailMsg, phase1Length: String(phase1Result || '').length, combinedLength: combined.length };
        return { combined, phase1: phase1Result, phase2: '', skipped: 'phase2_failed_fallback_phase1' };
      }

      let cleanPhase1 = foxJudgeStripThinkBlock(phase1Result || '');
      let cleanPhase2 = foxJudgeStripThinkBlock(phase2Result || '');
      cleanPhase1 = foxJudgeStripStrayThinkTags(cleanPhase1);
      cleanPhase2 = foxJudgeStripStrayThinkTags(cleanPhase2);
      const combined = `<think_fox~>
${cleanPhase1}
[OS]
${cleanPhase2}
思考完毕，立刻按要求开始输出正文
</think_fox~>`;

      foxJudgeLastCombined = foxJudgeCleanLeakageAfterThinkClose(combined);
      foxJudgePendingInject = foxJudgeCleanLeakageAfterThinkClose(combined);
      foxJudgePreservedChain = foxJudgeCleanLeakageAfterThinkClose(combined);
      foxJudgeInjectVersion++;
      log('[狐裁] 两阶段思考完成，length=', combined.length, 'Phase1来自缓存=', phase1FromCache, '等待主模型输出后注入楼层', 'version=', foxJudgeInjectVersion);

      toast('🦊 狐裁思维链完成', 'success');

      diagOutcome = 'success';
      diagResult = {
        phase1Length: String(phase1Result || '').length,
        phase2Length: String(phase2Result || '').length,
        combinedLength: combined.length,
        phase1FromCache,
        injectVersion: foxJudgeInjectVersion,
      };
      return { combined, phase1: phase1Result, phase2: phase2Result, skipped: null };
    } catch (e) {
      const msg = e?.message || String(e || '');
      foxJudgeDiag('主链:捕获最终异常', {
        message: msg,
        task: (() => {
          const task = ssActiveTasks.get('fox_judge_chain');
          return task ? {
            cancelled: task.cancelled,
            taskGenerationId: task.generationId,
            activeRequestIds: [...(task.generationIds || [])],
            abortControllerCount: task.abortControllers?.size || 0,
          } : null;
        })(),
        error: foxJudgeDiagError(e),
      }, 'error', diag);
      if (foxJudgeIsUserCancellation(e)) {
        diagOutcome = 'cancelled';
        diagResult = { message: msg, error: foxJudgeDiagError(e) };
        toast('⛔ 狐裁已中断', 'warning');
        return { combined: '', phase1: '', phase2: '', skipped: 'cancelled' };
      }
      diagOutcome = 'error';
      diagResult = { message: msg, error: foxJudgeDiagError(e) };
      log('[狐裁] 思维链失败', e);
      toast(`❌ 狐裁失败：${msg}`, 'error');
      return { combined: '', phase1: '', phase2: '', skipped: 'error' };
    } finally {
      foxJudgeDiag('任务:finally清理前', {
        outcome: diagOutcome,
        taskExists: ssActiveTasks.has('fox_judge_chain'),
        taskCancelled: ssActiveTasks.get('fox_judge_chain')?.cancelled === true,
        activeRequestIds: [...(ssActiveTasks.get('fox_judge_chain')?.generationIds || [])],
      }, 'log', diag);
      ssClearTaskToast('fox_judge_chain');
      ssEndTask('fox_judge_chain');
      foxJudgeEndDiag(diagOutcome, diagResult, diag);
    }
  }

  let foxJudgeOutputInjectHandles = [];

  function foxJudgeRegisterOutputInjectListener() {
    foxJudgeUnregisterOutputInjectListener();

    const eo = getFn('eventOn');
    const te = getFn('tavern_events') || tavern_events;
    if (typeof eo !== 'function') return;

    if (te?.MESSAGE_RECEIVED) {
      foxJudgeOutputInjectHandles.push(
        eo(te.MESSAGE_RECEIVED, async (messageId, type) => {
          const cfg = foxJudgeReadConfig();
          if (!cfg.enabled) return;
          if (!foxJudgePendingInject && !foxJudgeLastCombined) return;

          // 🦊 关键：抓取“当前这条 MESSAGE_RECEIVED 关心的”那一版思维链快照。
          //    600ms 之后再清缓存时，必须只清这一版——如果用户在等待期间又跑了
          //    新一轮 swipe/reroll 思考，导致 foxJudgeInjectVersion 已经 +1，
          //    那这条旧 MESSAGE_RECEIVED 就不再清空全局缓存，避免“新思维链被旧
          //    监听器误清空 → 下一次主请求注入失败”这个时好时坏的根因。
          const myVersion = foxJudgeInjectVersion;
          const mySnapshot = foxJudgeLastCombined || foxJudgePendingInject;

          await new Promise(r => setTimeout(r, 600));

          await foxJudgeInjectIntoMainOutput(messageId);

          if (foxJudgeInjectVersion !== myVersion) {
            log('[狐裁] MESSAGE_RECEIVED：检测到新一轮思维链已就位（v', myVersion, '→', foxJudgeInjectVersion, '），跳过清空，保护新缓存');
            return;
          }
          // 仅当全局缓存仍是“我关心的那一版”时才清空，避免误清。
          if (foxJudgeLastCombined === mySnapshot || foxJudgePendingInject === mySnapshot) {
            foxJudgePendingInject = '';
            foxJudgeLastCombined = '';
            log('[狐裁] MESSAGE_RECEIVED：思维链已注入到主模型输出楼层顶部，缓存已清空 v=', myVersion);
          } else {
            log('[狐裁] MESSAGE_RECEIVED：缓存内容已被替换，跳过清空');
          }
        })
      );
    }

    if (te?.MESSAGE_DELETED) {
      foxJudgeOutputInjectHandles.push(
        eo(te.MESSAGE_DELETED, async (messageId) => {
          const cfg = foxJudgeReadConfig();
          if (!cfg.enabled) return;

          try {
            const glmi = getFn('getLastMessageId');
            const gcm = getFn('getChatMessages');
            if (glmi && gcm) {
              const lastId = glmi();
              if (lastId >= 0) {
                const cm = gcm(lastId, { include_swipes: true })?.[0];
                if (cm && cm.role === 'assistant') {
                  const text = String(cm.message || '');
                  if (text.includes('<think_fox~>')) {
                    foxJudgeLastCombined = '';
                    foxJudgePendingInject = '';
                    log('[狐裁] MESSAGE_DELETED：检测到含思维链楼层，已同步清理内存缓存');
                  }
                }
              }
            }
          } catch (e) {
            log('[狐裁] MESSAGE_DELETED 同步清理失败', e);
          }
        })
      );
    }

    if (te?.GENERATION_ENDED) {
      foxJudgeOutputInjectHandles.push(
        eo(te.GENERATION_ENDED, () => {
          try { foxJudgeRegisterSwipeRerollListeners(); } catch { }
          // ✅ 修复：发送按钮 / Enter 监听也可能因为 DOM 被酒馆重建而丢失
          //         导致用户点发送或按 Enter 时狐裁完全不触发。
          //         这里跟 swipe/reroll 一起重新注册，保证监听始终在 DOM 上。
          try { registerFoxJudgeInterceptListener(); } catch { }
          // 🦊 生成结束后同步平滑流式 UI + 强制 should_stream 与开关一致
          try { syncSmoothStreamState('generation_ended'); } catch { }
        })
      );
    }

    // ✅ 切换聊天/角色卡时酒馆也会重建输入区域 DOM，需要重新挂载拦截器
    // 注：狐裁思维链缓存 / 拦截锁的清空统一在 husouRegisterListeners 的 CHAT_CHANGED 中枢处理，
    //     那里始终注册，能覆盖狐裁监听未激活的情况。
    if (te?.CHAT_CHANGED) {
      foxJudgeOutputInjectHandles.push(
        eo(te.CHAT_CHANGED, () => {
          try { foxJudgeRegisterSwipeRerollListeners(); } catch { }
          try { registerFoxJudgeInterceptListener(); } catch { }
        })
      );
    }
  }

  function foxJudgeUnregisterOutputInjectListener() {
    for (const h of foxJudgeOutputInjectHandles) {
      try { if (typeof h?.stop === 'function') h.stop(); } catch { }
    }
    foxJudgeOutputInjectHandles = [];
  }

  let foxJudgeRethinkPending = false;
  // ✅ reroll/swipe 保护窗口：从狐裁重新思考开始，到真正的 reroll/swipe 生成开始（GENERATION_STARTED）为止。
  //    在此窗口内，狐忆的 MESSAGE_RECEIVED 监听器应跳过，避免在"清除楼层准备发送"阶段误触发分析。
  let foxJudgeRerollSwipeGuard = false;
  let foxJudgeRerollSwipeGuardHandle = null;
  let foxJudgeRerollBtnHandle = null;
  let foxJudgeSwipeBtnHandle = null;
  let foxJudgeSkipNextReroll = false;
  let foxJudgeSkipNextSwipe = false;

  function foxJudgeActivateRerollSwipeGuard() {
    foxJudgeRerollSwipeGuard = true;
    // 注册一次性 GENERATION_STARTED 监听：真正的 reroll/swipe 生成开始时清除保护
    try {
      const eo = getFn('eventOn');
      const te = getFn('tavern_events') || tavern_events;
      if (foxJudgeRerollSwipeGuardHandle) { try { foxJudgeRerollSwipeGuardHandle?.stop?.(); } catch {} foxJudgeRerollSwipeGuardHandle = null; }
      if (typeof eo === 'function' && te?.GENERATION_STARTED) {
        const handler = (type, _option, dryRun) => {
          if (dryRun) return;
          // 内部生成（狐裁自己的 ssGenerateRaw）不清除保护
          if (ssActiveTasks?.size > 0) return;
          foxJudgeRerollSwipeGuard = false;
          try { foxJudgeRerollSwipeGuardHandle?.stop?.(); } catch {}
          foxJudgeRerollSwipeGuardHandle = null;
          log(`[狐裁] reroll/swipe 保护窗口已清除（GENERATION_STARTED type=${type || 'normal'}）`);
        };
        foxJudgeRerollSwipeGuardHandle = eo(te.GENERATION_STARTED, handler);
      }
    } catch {}
    // 兜底：10 秒后自动清除，避免监听器未触发导致永久保护
    setTimeout(() => { foxJudgeRerollSwipeGuard = false; }, 10000);
  }

  async function foxJudgeHandleRerollSwipe(source) {
    const cfg = foxJudgeReadConfig();
    if (!cfg.enabled) return;
    if (foxJudgeRethinkPending) {
      toast('⏳ 狐裁思考中，请稍候…', 'info');
      return;
    }

    if (ssActiveTasks.size > 0 || state.husouIsRunning || state.foxAnalyzing || state.outlineIsCorrecting || state.outlineIsGenerating || state.hushenIsAnalyzing || pwState?.running) return;

    foxJudgeRethinkPending = true;

    try {
      log(`[狐裁] ${source} 拦截：开始重跑第二阶段`);

      // 注意：理论上前置守卫（`foxJudgeOnRerollClick`/`OnSwipeClick` 在 ssActiveTasks.size > 0 时早返回）
      // 已经过滤掉了"上一次还在跑"的情况，这里走不到。`foxJudgeRunChain` 内部也有重入保护会返回 busy。
      // 之前这里的 ssCancelTask + await 300ms 是兜底防御，但与新版"重入返回 busy"语义冲突，
      // 反而会让上一次跑到一半的思考被中断却不让本次启动，故移除。

      foxJudgeLastCombined = '';
      foxJudgePendingInject = '';

      const glmi = getFn('getLastMessageId');
      const gcm = getFn('getChatMessages');
      let userInput = '';
      let lastAssistantText = '';
      if (glmi && gcm) {
        const lastId = glmi();
        if (lastId >= 0) {
          for (let i = lastId; i >= Math.max(0, lastId - 5); i--) {
            const m = gcm(i, { hide_state: 'all', include_swipes: false })?.[0];
            if (!m) continue;
            if (!userInput && m.role === 'user') {
              userInput = String(m.message || '').trim();
            }
            if (!lastAssistantText && m.role === 'assistant') {
              lastAssistantText = String(m.message || '').trim();
              try { lastAssistantText = ssCleanXuanhuInjectedBlocksFromMessage(lastAssistantText); } catch { }
              lastAssistantText = foxJudgeStripThinkBlock(lastAssistantText);
            }
            if (userInput && lastAssistantText) break;
          }
        }
      }

      const usePhase2Only = (() => {
        // phase1Only 快速模式 → 不存在第二阶段，必须走完整 phase1 流程（forced from foxJudgeRunChain）
        if (cfg.phase1Only) return false;
        // ✅ 修复 BUG：只有当 phase1 缓存确实存在且非空时才走 phase2Only。
        //    避免用户手动清空缓存后 reroll 仍按 phase2Only 走，
        //    内部虽有"phase2Only 但无缓存就补跑 phase1"的兜底，
        //    但 cacheEnabled=false 时该兜底分支条件是 `!phase1Result`，
        //    依然能走，这里再加一层显式判断让流程语义更稳。
        try {
          const charId = getCurrentCharId();
          // 先做一次指纹失效检查，避免读到已失效但残留的 cache
          try { foxJudgeCheckAndInvalidateIfChanged?.(); } catch {}
          const sc = foxJudgeGetStaticCache?.(charId);
          // ✅ phase1Fixed 时跳过 stale 检查：用户已明确"固定第一阶段"，即便缓存被标 stale 也应复用，
          //    否则 reroll/swipe 每次都因残留 stale 标记走完整 phase1+phase2，违背固定语义。
          const has = !!(sc && (cfg.phase1Fixed || !sc.stale) && typeof sc.phase1_result === 'string' && sc.phase1_result.trim());
          if (!has) {
            log(`[狐裁] reroll/swipe：缓存不存在或为空（phase1Fixed=${cfg.phase1Fixed}），走完整 phase1+phase2 流程`);
            return false;
          }
        } catch (e) {
          log('[狐裁] reroll/swipe：检查缓存失败，回退完整流程', e);
          return false;
        }
        return true;
      })();
      const result = await foxJudgeRunChain({ userInput, lastAssistantText, phase2Only: usePhase2Only, excludeLastAssistant: true, diagnosticSource: `reroll-swipe:${source}` });
      if (result.combined) {
        foxJudgeLastCombined = result.combined;
        foxJudgePendingInject = result.combined;
        log(`[狐裁] ${source} 重新思考完成，准备释放按钮（phase1Only=${cfg.phase1Only}）`);
      } else if (result.skipped === 'busy') {
        log(`[狐裁] ${source} 上一次思维链仍在进行，本次跳过狐裁注入`);
      }
    } catch (err) {
      log(`[狐裁] ${source} 重新思考失败:`, err);
    } finally {
      foxJudgeRethinkPending = false;
    }
  }

  function foxJudgeOnRerollClick(e) {
    // 🦊 双绑定去重：避免文档级和元素级监听都跑一次。
    // ⚠️ 只在确实进入处理路径时才打标记，no-op 不污染事件对象。
    if (e && e.__foxJudgeRerollHandled) return;
    const cfg = foxJudgeReadConfig();
    if (!cfg.enabled) return;
    if (e) { try { e.__foxJudgeRerollHandled = true; } catch { } }

    if (foxJudgeSkipNextReroll) {
      foxJudgeSkipNextReroll = false;
      return;
    }

    // 🦊 关闭"Reroll 时重新思考"分支：不重跑思维链，直接复用上一次保留的完整思维链
    //    塞回 foxJudgeLastCombined/Pending，然后放行原生 reroll 让主请求按原流程注入。
    //    若没有保留思维链（首次使用 / 切聊天后 / 用户主动清空），则什么都不做，
    //    让 reroll 不带思维链原生跑——这是用户明确的意图："就别再思考了"。
    if (!cfg.rerollRethink) {
      if (foxJudgePreservedChain) {
        foxJudgeLastCombined = foxJudgePreservedChain;
        foxJudgePendingInject = foxJudgePreservedChain;
        foxJudgeInjectVersion++;
        log('[狐裁] Reroll：已沿用上一次完整思维链，跳过重新思考');
      } else {
        log('[狐裁] Reroll：未启用重新思考且无保留思维链，本次裸 reroll');
      }
      return;
    }

    if (foxJudgeRethinkPending) {
      e.stopImmediatePropagation();
      e.preventDefault();
      toast('⏳ 狐裁思考中，请稍候…', 'info');
      return;
    }
    // ✅ 关键修复：自己上一轮的 fox_judge_chain 任务还在跑（例如发送/Enter 拦截
    //    触发的思维链还没结束），reroll 不能"让出"——必须挡住，否则 SillyTavern
    //    会在 phase2 还没拼完时就发出 reroll 请求。
    if (ssIsTaskRunning('fox_judge_chain')) {
      e.stopImmediatePropagation();
      e.preventDefault();
      toast('⏳ 狐裁思维链未结束，请稍候再 reroll…', 'info');
      return;
    }
    // 其他后台任务在跑：让出 reroll，同时清空旧思维链避免误注入
    if (ssActiveTasks.size > 0 || state.husouIsRunning || state.foxAnalyzing || state.outlineIsCorrecting || state.outlineIsGenerating || state.hushenIsAnalyzing || pwState?.running) {
      try {
        const reasons = [];
        if (ssActiveTasks.size > 0) reasons.push(`ssActiveTasks=${[...ssActiveTasks.keys()].join(',')}`);
        if (state.husouIsRunning) reasons.push('husouIsRunning');
        if (state.foxAnalyzing) reasons.push('foxAnalyzing');
        if (state.outlineIsCorrecting) reasons.push('outlineIsCorrecting');
        if (state.outlineIsGenerating) reasons.push('outlineIsGenerating');
        if (state.hushenIsAnalyzing) reasons.push('hushenIsAnalyzing');
        if (pwState?.running) reasons.push('pwState.running');
        log('[狐裁] reroll 拦截被其他后台任务挡住，本次让出原生 reroll：', reasons.join(' | '));
      } catch { }
      // 🦊 修复：背景任务挡路无法重跑，但必须把上一次保留的完整思维链恢复到
      //    待注入缓存，否则原生 reroll 出来的新输出会完全缺失狐裁思维链注入。
      //    这是"第一次重roll狐裁跳过、第二次才生效"的根因。
      if (foxJudgePreservedChain) {
        foxJudgeLastCombined = foxJudgePreservedChain;
        foxJudgePendingInject = foxJudgePreservedChain;
        foxJudgeInjectVersion++;
        log('[狐裁] Reroll：背景任务阻挡重跑，已沿用上一次完整思维链');
      } else {
        foxJudgeLastCombined = '';
        foxJudgePendingInject = '';
        log('[狐裁] Reroll：背景任务阻挡重跑且无保留思维链，本次裸 reroll');
      }
      return;
    }

    e.stopImmediatePropagation();
    e.preventDefault();
    foxJudgeActivateRerollSwipeGuard();

    foxJudgeHandleRerollSwipe('reroll').then(() => {
      foxJudgeSkipNextReroll = true;
      const btn = topDoc.getElementById('option_regenerate') || topDoc.getElementById('regenerate');
      if (btn) btn.click();
    });
  }

