          <button type="button" id="foxjudge-think-preset-os" style="padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.12);color:#f0a070;cursor:pointer;font-size:12px;font-weight:600;">🎭 排序成 OS 思维链</button>
          <button type="button" id="foxjudge-think-preset-director" style="padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.12);color:#f0a070;cursor:pointer;font-size:12px;font-weight:600;">🎬 排序成导演思维链</button>
          <button type="button" id="foxjudge-think-add" style="padding:8px 12px;border:1px solid rgba(232,120,74,0.2);border-radius:8px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:12px;">➕ 新增自定义模块</button>
        </div>
        <div id="foxjudge-think-grid" style="display:grid;grid-template-columns:1fr 1.3fr;gap:10px;">
          <div style="display:flex;flex-direction:column;gap:4px;">
            <div style="font-size:11px;color:#706058;">未启用模块（拖到右侧启用，或点 ⇢）</div>
            <div id="foxjudge-think-pool" style="min-height:200px;background:rgba(0,0,0,0.18);border:1px dashed rgba(232,120,74,0.18);border-radius:8px;padding:8px;display:flex;flex-direction:column;gap:6px;"></div>
          </div>
          <div style="display:flex;flex-direction:column;gap:4px;">
            <div style="font-size:11px;color:#706058;">启用排序区（从上到下 = 拼接顺序，拖动或用 ↑↓ 排序）</div>
            <div id="foxjudge-think-active" style="min-height:200px;background:rgba(232,120,74,0.06);border:1px dashed rgba(232,120,74,0.25);border-radius:8px;padding:8px;display:flex;flex-direction:column;gap:6px;"></div>
          </div>
        </div>
      </div>
      </section>

      <section class="fj-pane" data-pane="api">
      <div class="fj-pane-h"><span class="fj-mico" style="width:32px;height:32px;border-radius:9px;font-size:15px">🌐</span><h2>API 配置 · 模型与参数</h2></div>
      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">
        <div style="font-weight:700;color:#f0a070;font-size:14px;">🤖 分析 API 配置</div>
        <div style="font-size:11px;color:#a09088;line-height:1.55;">

        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;">
          <div>
            <label style="font-size:11px;color:#706058;">API 来源</label>
            <select id="foxjudge-api-type" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">
              <option value="current" ${cfg.apiType === 'current' ? 'selected' : ''}>酒馆当前 API</option>
              <option value="custom" ${cfg.apiType === 'custom' ? 'selected' : ''}>自定义 OpenAI 兼容 API</option>
            </select>
          </div>
        </div>

        <div id="foxjudge-custom-api-section" style="display:${cfg.apiType === 'custom' ? 'block' : 'none'};margin-top:10px;">
          <div id="foxjudge-direct-section" style="display:block;">
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;">
              <div>
                <label style="font-size:11px;color:#706058;">API 地址</label>
                <input id="foxjudge-api-url" type="text" value="${escapeHtml(cfg.customApi.apiurl || '')}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">
              </div>
              <div>
                <label style="font-size:11px;color:#706058;">API Key</label>
                <input id="foxjudge-api-key" type="password" value="${escapeHtml(cfg.customApi.key || '')}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">
              </div>
            </div>
          </div>

          <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;margin-top:8px;">
            <div>
              <label style="font-size:11px;color:#706058;">模型</label>
              <div style="display:flex;gap:6px;">
                <input id="foxjudge-api-model" type="text" value="${escapeHtml(cfg.customApi.model || '')}" style="flex:1;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">
                <button id="foxjudge-fetch-models" style="padding:5px 10px;border:1px solid rgba(232,120,74,0.2);border-radius:6px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:11px;white-space:nowrap;">获取模型</button>
              </div>
            </div>
            <div>
              <label style="font-size:11px;color:#706058;">模型列表</label>
              <select id="foxjudge-api-model-select" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"><option value="">（从列表选择）</option></select>
            </div>
          </div>

          <details style="margin-top:10px;border:1px solid rgba(232,120,74,0.12);border-radius:8px;background:rgba(255,255,255,0.02);">
            <summary style="cursor:pointer;padding:8px 10px;color:#f0a070;font-size:12px;font-weight:600;user-select:none;">⚙️ 高级参数</summary>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px 12px;padding:10px;">
              <div><label style="font-size:11px;color:#706058;">温度</label><input id="foxjudge-api-temp" type="number" min="0" max="2" step="0.1" value="${escapeHtml(cfg.customApi.temperature ?? '')}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>
              <div><label style="font-size:11px;color:#706058;">最大 token</label><input id="foxjudge-api-max-tokens" type="number" min="0" step="128" value="${escapeHtml(cfg.customApi.max_tokens ?? '')}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>
              <div><label style="font-size:11px;color:#706058;">Top P</label><input id="foxjudge-api-top-p" type="number" min="0" max="1" step="0.01" value="${escapeHtml(cfg.customApi.top_p ?? '')}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>
              <div><label style="font-size:11px;color:#706058;">频率惩罚</label><input id="foxjudge-api-freq-pen" type="number" min="-2" max="2" step="0.01" value="${escapeHtml(cfg.customApi.frequency_penalty ?? '')}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>
              <div><label style="font-size:11px;color:#706058;">存在惩罚</label><input id="foxjudge-api-pres-pen" type="number" min="-2" max="2" step="0.01" value="${escapeHtml(cfg.customApi.presence_penalty ?? '')}" style="width:100%;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;"></div>
            </div>
          </details>
          ${ssRenderExtraParamsPanelHtml('foxjudge', {
            extraBodyParamsYaml: cfg.customApi.extraBodyParamsYaml,
            excludeBodyParamsYaml: cfg.customApi.excludeBodyParamsYaml,
            extraHeadersYaml: cfg.customApi.extraHeadersYaml,
          })}
          <div style="display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;align-items:center;">
            <select id="foxjudge-saved-api-select" style="flex:1;min-width:160px;box-sizing:border-box;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.15);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;">${ssGetCustomApiPresetOptionsHtml()}</select>
            <button id="foxjudge-saved-api-apply" style="padding:5px 10px;border:1px solid rgba(232,120,74,0.25);border-radius:6px;background:rgba(232,120,74,0.08);color:#f0a070;cursor:pointer;font-size:11px;">填入</button>
            <button id="foxjudge-saved-api-save" style="padding:5px 10px;border:1px solid rgba(232,120,74,0.25);border-radius:6px;background:rgba(255,255,255,0.03);color:#a09088;cursor:pointer;font-size:11px;">保存</button>
            <button id="foxjudge-saved-api-delete" style="padding:5px 10px;border:1px solid rgba(139,0,0,0.3);border-radius:6px;background:rgba(139,0,0,0.12);color:#d08080;cursor:pointer;font-size:11px;">删除</button>
          </div>
        </div>
      </div>
      </section>

      <section class="fj-pane" data-pane="set">
      <div class="fj-pane-h"><span class="fj-mico" style="width:32px;height:32px;border-radius:9px;font-size:15px">🔧</span><h2>设置 · 过滤 · 缓存 · 重试</h2></div>

      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">
        <details>
          <summary style="cursor:pointer;font-weight:700;color:#f0a070;font-size:14px;user-select:none;">🏷️ 上下文标签过滤</summary>
          <div style="font-size:11px;color:#90756a;line-height:1.6;margin:8px 0;">
            狐裁读取上下文时的标签过滤规则。<br>
            chatHistory 中用户消息不做标签过滤，AI/char 消息才会按这里的规则过滤。<br>
            默认排除 <code>&lt;think_fox~&gt;&lt;/think_fox~&gt;</code>、<code>&lt;thinking_rules&gt;&lt;/thinking_rules&gt;</code>、<code>&lt;User_latest_request&gt;&lt;/User_latest_request&gt;</code>、<code>&lt;All_Context&gt;&lt;/All_Context&gt;</code> 内的全部内容。<br>
            <span style="color:#70a0d0;">💡 狐裁先过滤静态上下文，再追加稳定 N 楼 + 最多 10 楼连续弹性聊天；弹性满后整段推进，以提高前缀缓存命中。</span><br>
            <span style="color:#d08080;">⚠️ fox_selc / fox_tip 已从默认排除中移除：这两个标签名会作为字面文本出现在预设指令中，导致误过滤截断上下文。</span><br>
            <span style="color:#a0c890;">🔁 升级新版后会在首次加载时自动把排除标签同步为上述默认四项一次；之后你在此处的增删改都不会再被覆盖。</span>
          </div>

          <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:#a09088;cursor:pointer;margin-bottom:8px;">
            <input type="checkbox" id="foxjudge-content-filter" ${(cfg.filterSettings || FOX_JUDGE_DEFAULT_FILTER_SETTINGS).enableContentFilter !== false ? 'checked' : ''}>
            启用狐裁标签过滤
          </label>

          ${ssCreateTagPairsEditorHtml(
            'foxjudge-inc',
            '✅ 包含标签：只保留这些标签范围内的内容',
            (cfg.filterSettings || FOX_JUDGE_DEFAULT_FILTER_SETTINGS).includeTagPairs,
            '一行是一组。左边开始标签，右边结束标签。'
          )}

          ${ssCreateTagPairsEditorHtml(
            'foxjudge-exc',
            '❌ 排除标签：删除这些标签范围内的内容',
            (cfg.filterSettings || FOX_JUDGE_DEFAULT_FILTER_SETTINGS).excludeTagPairs,
            '功能与包含标签相反。允许只填结束标签。'
          )}

          <button type="button" id="foxjudge-filter-save" style="width:100%;padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.1);color:#f0a070;cursor:pointer;font-size:12px;">💾 保存上下文设置</button>
        </details>
      </div>

      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">
        <div style="font-weight:700;color:#f0a070;font-size:14px;">💾 缓存与重跑</div>
        <div style="font-size:11px;color:#a09088;line-height:1.55;">
          第一阶段结果按角色卡缓存，换卡或改预设自动失效
        </div>
        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">
          <span>
            <strong style="color:#f0a070;">💾 启用第一阶段缓存</strong>
            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">关闭后第一阶段每次都重新思考</span>
          </span>
          <input id="foxjudge-cache-enabled" type="checkbox" ${cfg.cacheEnabled ? 'checked' : ''} style="cursor:pointer;width:18px;height:18px;">
        </label>
        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">
          <span>
            <strong style="color:#f0a070;">📌 固定第一阶段思考</strong>
            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">开启后第一阶段缓存不会因角色卡/预设变化自动失效，会一直使用当前保存内容。</span>
          </span>
          <input id="foxjudge-phase1-fixed" type="checkbox" ${cfg.phase1Fixed ? 'checked' : ''} style="cursor:pointer;width:18px;height:18px;">
        </label>
        <div style="display:flex;gap:8px;flex-wrap:wrap;">
          <button type="button" id="foxjudge-clear-cache" style="flex:1;padding:8px 12px;border:1px solid rgba(139,0,0,0.3);border-radius:8px;background:rgba(139,0,0,0.13);color:#d08080;cursor:pointer;font-size:12px;">🧹 清空全部缓存</button>
          <button type="button" id="foxjudge-force-refresh" style="flex:1;padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.1);color:#f0a070;cursor:pointer;font-size:12px;">🔄 强制重跑第一阶段</button>
          <button type="button" id="foxjudge-run-phase1-now" style="flex:1;padding:8px 12px;border:1px solid rgba(255,170,90,0.42);border-radius:8px;background:rgba(232,120,74,0.16);color:#ffb06a;cursor:pointer;font-size:12px;font-weight:700;">🧠 立即思考第一阶段</button>
        </div>
      </div>

      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">
        <div style="font-weight:700;color:#f0a070;font-size:14px;">📋 第一阶段缓存内容</div>
        <div style="font-size:11px;color:#a09088;line-height:1.55;">
          当前角色卡的第一阶段思考结果。可直接编辑并保存，编辑后下次发送时使用编辑后的内容。
        </div>
        <textarea id="foxjudge-phase1-cache-viewer" style="width:100%;min-height:150px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:8px;color:#e8ddd4;padding:10px;font-size:12px;font-family:monospace;resize:vertical;box-sizing:border-box;white-space:pre-wrap;">${(() => { try { const c = foxJudgeGetStaticCache(getCurrentCharId()); return escapeHtml(c?.phase1_result || '（无缓存，下次发送时自动生成）'); } catch { return '（读取失败）'; } })()}</textarea>
        <div style="display:flex;gap:8px;flex-wrap:wrap;">
          <button type="button" id="foxjudge-phase1-cache-save" style="flex:1;padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.1);color:#f0a070;cursor:pointer;font-size:12px;">💾 保存编辑</button>
          <button type="button" id="foxjudge-phase1-cache-refresh" style="flex:1;padding:8px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.1);color:#f0a070;cursor:pointer;font-size:12px;">🔄 刷新显示</button>
        </div>
      </div>

      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">
        <div style="font-weight:700;color:#f0a070;font-size:14px;">🔁 Swipe / Reroll 重新思考</div>
        <div style="font-size:11px;color:#a09088;line-height:1.55;">
           默认开启。开启时：swipe / reroll 会先拦截按钮、重跑第二阶段思维链，再释放按钮触发生成。<br>
           关闭时：swipe / reroll 不再重跑思维链，而是<strong>沿用上一次已经思考完的完整思维链</strong>注入到新输出楼层顶部，保持一二阶段不变（适合：你已经满意当前思考，只想换一个正文版本）。
        </div>
        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">
          <span>
            <strong style="color:#f0a070;">🔁 Swipe 时重新思考</strong>
            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">默认开启。开启=重跑第二阶段并注入新思维链；关闭=沿用上一次完整思维链直接注入。</span>
          </span>
          <input id="foxjudge-swipe-rethink" type="checkbox" ${cfg.swipeRethink ? 'checked' : ''} style="cursor:pointer;width:18px;height:18px;">
        </label>
        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">
          <span>
            <strong style="color:#f0a070;">🔁 Reroll 时重新思考</strong>
            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">默认开启。开启=重跑第二阶段并注入新思维链；关闭=沿用上一次完整思维链直接注入。</span>
          </span>
          <input id="foxjudge-reroll-rethink" type="checkbox" ${cfg.rerollRethink ? 'checked' : ''} style="cursor:pointer;width:18px;height:18px;">
        </label>
      </div>

      <div style="background:rgba(232,120,74,0.025);border:1px solid rgba(232,120,74,0.1);border-radius:12px;padding:14px;display:flex;flex-direction:column;gap:10px;">
        <div style="font-weight:700;color:#f0a070;font-size:14px;">🔄 空回复/报错重试</div>
        <div style="font-size:11px;color:#a09088;line-height:1.55;">
           当思维链阶段返回空内容、报错、被拒答或结构残缺时自动重试。0=不重试（一报错就空思维链），1~5=重试次数。
        </div>
        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">
          <span>
            <strong style="color:#f0a070;">🔘 启用空回复/报错重试</strong>
            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">默认关闭。关闭后思维链只跑一次，不检测空回/报错，直接使用结果。</span>
          </span>
          <input id="foxjudge-retry-enabled" type="checkbox" ${cfg.retryEnabled ? 'checked' : ''} style="width:18px;height:18px;cursor:pointer;accent-color:#f0a070;">
        </label>
        <label style="display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#ffd8b8;cursor:pointer;padding:8px 12px;border:1px solid rgba(232,120,74,0.15);border-radius:8px;background:rgba(255,255,255,0.02);">
          <span>
            <strong style="color:#f0a070;">🔄 最大重试次数</strong>
            <span style="display:block;font-size:11px;color:#a09088;margin-top:2px;">思维链空回复/拒答/结构残缺时自动重试（推荐 3 次）；仅在上方开关开启时生效</span>
          </span>
          <input id="foxjudge-max-retries" type="number" min="0" max="5" value="${cfg.maxRetries ?? 3}" style="width:50px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:6px;color:#e8ddd4;padding:5px 8px;font-size:12px;text-align:center;">
        </label>
      </div>
      </section>
        </main>
      </div>
      <nav class="fj-dock">
        <div class="fj-dock-item fj-cur" data-tab="main"><div class="fj-d-ic">⚖️</div><div class="fj-d-t">主控</div></div>
        <div class="fj-dock-item" data-tab="phase1"><div class="fj-d-ic">📜</div><div class="fj-d-t">一阶段</div></div>
        <div class="fj-dock-item" data-tab="phase2"><div class="fj-d-ic">🧩</div><div class="fj-d-t">二阶段</div></div>
        <div class="fj-dock-item" data-tab="api"><div class="fj-d-ic">🌐</div><div class="fj-d-t">API</div></div>
        <div class="fj-dock-item" data-tab="set"><div class="fj-d-ic">⚙️</div><div class="fj-d-t">设置</div></div>
      </nav>
    `;

    topDoc.body.appendChild(overlay);
    topDoc.body.appendChild(panel);
    xhGuideEnhancePanel(panel, 'foxjudge', '狐裁');

    // 🦊 挂载狐裁提示词自定义编辑器到设置页
    try {
      const fjSetPane = panel.querySelector('[data-pane="set"]');
      if (fjSetPane) {
        // 触发一次构建以注册默认值（狐裁标记常量在顶层已注册）
        xhMountPromptEditor(fjSetPane, 'fox_judge', '狐裁思维链注入标记');
      }
    } catch (e) { log('[狐裁] 挂载提示词编辑器失败', e); }

    // ✅ 自动保存：狐裁面板大多数控件已挂 onchange 即时保存，
    //    我们只需要补上"普通设置项 input/change 时强制 blur 一下"，让 onchange 回调立刻触发，
    //    以及为分区里的"💾 保存"按钮加自动触发：
    //      - phase1/phase2 prompt textarea 改动 → 触发自身的 change（onchange 内已保存）
    //      - 标签过滤区改动 → 触发 foxjudge-filter-save
    //      - 缓存编辑区改动 → 触发 foxjudge-phase1-cache-save
    //      - 尾部锚点输入 → 触发 foxjudge-tail-anchor-save
    ssAttachAutoSave(panel, {
      resolveSaveBtns: (target) => {
        if (!target) return [];
        // 标签过滤区里的子输入：通过 closest 命中 ssBindTagPairsEditor 实际生成的 class
        // （`.foxjudge-inc-tag-module / .foxjudge-inc-tag-row / .foxjudge-inc-tag-add` 等）
        const tagWrap = target.closest?.(
          '.foxjudge-inc-tag-module, .foxjudge-exc-tag-module, ' +
          '.foxjudge-inc-tag-row, .foxjudge-exc-tag-row'
        );
        if (tagWrap) return ['foxjudge-filter-save'];
        const id = target.id;
        if (!id) return [];
        if (id === 'foxjudge-phase1-cache-viewer') return ['foxjudge-phase1-cache-save'];
        // 其他常规设置项：onchange 内部已经自存，无需触发额外按钮
        return [];
      },
    });

    // ✅ 一键恢复狐裁本面板默认（清空所有 FOX_JUDGE_LS_KEYS + 角色卡缓存索引），关闭并重开
    ssAttachPanelResetButton(panel, {
      label: '↩ 恢复狐裁默认设置',
      confirm: '确定要恢复狐裁本面板的全部设置为默认吗？\n\n这会清掉：第一/二阶段提示词、强度、缓存开关、自定义思考要求、自定义 API、标签过滤和聊天楼层限制等。\n\n角色卡静态缓存会标记失效，避免继续复用旧楼层范围生成的第一阶段思考。\n\n此操作不可撤销。',
      onReset: () => {
        try {
          for (const k of Object.values(FOX_JUDGE_LS_KEYS)) {
            // charCachePrefix 是前缀，跳过；仅清纯设置 key
            if (k === FOX_JUDGE_LS_KEYS.charCachePrefix) continue;
            try { localStorage.removeItem(k); } catch {}
          }
          try { foxJudgeInvalidateStaticCache(); } catch {}
        } finally {
          try { _fjTkCloseEditor(); } catch { }
          topDoc.getElementById('ss-foxjudge-overlay')?.remove();
          panel.remove();
          setTimeout(() => { try { openFoxJudgePanel(); } catch {} }, 50);
        }
      },
    });

    ssBindTagPairsEditor('foxjudge-inc', panel);
    ssBindTagPairsEditor('foxjudge-exc', panel);

    // 事件绑定
    let foxJudgeToggleGuard = false;

    panel.querySelector('#foxjudge-enabled').onchange = async (e) => {
      if (foxJudgeToggleGuard) { e.target.checked = !e.target.checked; return; }
      foxJudgeToggleGuard = true;
      const next = e.target.checked;
      const applied = await foxJudgeSetEnabled(next);
      e.target.checked = next && applied;
      setTimeout(() => { foxJudgeToggleGuard = false; }, 800);
    };

    panel.querySelector('#foxjudge-phase1-only').onchange = async (e) => {
      const newCfg = foxJudgeReadConfig();
      newCfg.phase1Only = e.target.checked;
      // 🦊 修复：启用快速模式时必须连锁启用内置思维链，否则快速模式完全无效。
      if (newCfg.phase1Only && !newCfg.enabled) {
        newCfg.enabled = true;
        foxJudgeSaveConfig(newCfg);
        await foxJudgeApplyAutoPresetChanges();
        foxJudgeInterceptProcessing = false;
        foxJudgeInterceptSkipNext = false;
        foxJudgeRethinkPending = false;
        foxJudgeSkipNextReroll = false;
        foxJudgeSkipNextSwipe = false;
        foxJudgeRegisterSwipeRerollListeners();
        foxJudgeRegisterOutputInjectListener();
        try { registerFoxJudgeInterceptListener(); } catch (err) { log('[狐裁] 快速模式连锁启用时重挂拦截器失败', err); }
        const enabledCb = panel.querySelector('#foxjudge-enabled');
        if (enabledCb) enabledCb.checked = true;
        toast('🚀 已启用快速模式并连锁开启内置思维链', 'success');
        ssRefreshDashboardIfOpen();
        return;
      }
      foxJudgeSaveConfig(newCfg);
      if (newCfg.enabled) {
        foxJudgeRegisterSwipeRerollListeners();
      }
      if (newCfg.phase1Only) {
        toast('🚀 已启用仅第一阶段模式（只跑第一阶段并注入 think_fox~ 块，跳过第二阶段思考与[OS]拼接）', 'success');
      } else {
        toast('🎬 已恢复完整两阶段思维链', 'info');
      }
    };

    panel.querySelector('#foxjudge-phase1-reset').onclick = () => {
      const ta = panel.querySelector('#foxjudge-phase1-prompt');
      ta.value = FOX_JUDGE_PHASE1_PROMPT;
      const newCfg = foxJudgeReadConfig();
      newCfg.phase1Prompt = FOX_JUDGE_PHASE1_PROMPT;
      foxJudgeSaveConfig(newCfg);
      foxJudgeInvalidateStaticCache();
      toast('↩️ 第一阶段已恢复默认，缓存已清空', 'success');
    };

    panel.querySelector('#foxjudge-phase1-prompt').onchange = (e) => {
      const newCfg = foxJudgeReadConfig();
      newCfg.phase1Prompt = e.target.value;
      foxJudgeSaveConfig(newCfg);
      foxJudgeInvalidateStaticCache();
      toast('✅ 第一阶段提示词已保存，缓存已清空', 'success');
    };

    // 🧩 思维链模块化：渲染 + 拖拽 + 编辑绑定
    const _fjConfirm = (msg) => (topWindow?.confirm || confirm)(msg);
    let _fjTkDragId = null;
    let _fjTkEditId = null;

    // 📱 移动端适配：两栏改单栏 + 放大触摸目标（一次性注入）
    if (!topDoc.getElementById('foxjudge-think-mobile-style')) {
      const _s = topDoc.createElement('style');
      _s.id = 'foxjudge-think-mobile-style';
      _s.textContent = `
@media (max-width: 768px) {
  #foxjudge-think-grid { grid-template-columns: 1fr !important; }
   .fj-tk-item { padding: 11px 12px !important; font-size: 13px !important; min-height: 44px; flex-wrap:wrap !important; }
   /* 📱 标题 flex-basis:0% 时可一直缩到 min-width，flex-wrap 永不触发，窄屏标题只剩省略号；
      改成 1 1 auto + min-width:8em：一行放不下时按钮组整体换到第二行（margin-left:auto 右对齐），标题独占首行完整可读 */
   .fj-tk-item > span:first-child { min-width:8em !important; flex:1 1 auto !important; }
   .fj-tk-item > span:last-child { flex-wrap:wrap !important; justify-content:flex-end !important; min-width:0 !important; gap:3px !important; margin-left:auto !important; }
   .fj-tk-btn { font-size: 14px !important; padding: 2px 5px; min-width: 26px; min-height: 26px; display: inline-flex; align-items: center; justify-content: center; }
  #foxjudge-think-pool, #foxjudge-think-active { min-height: 120px !important; }
  /* 📱 编辑层：顶对齐 + 可滚动，避免软键盘弹出后模态被居中到屏幕上方只剩半截可见 */
  #foxjudge-think-edit-layer { align-items: flex-start !important; overflow-y: auto !important; -webkit-overflow-scrolling: touch; padding: 8px 0 !important; box-sizing: border-box !important; }
  #foxjudge-think-edit-layer > div { width: calc(100vw - 24px) !important; max-width: 560px !important; max-height: none !important; margin: 0 auto !important; flex-shrink: 0 !important; }
  #foxjudge-think-edit-content { min-height: 120px !important; flex: 0 0 auto !important; }
}
`;
      topDoc.head.appendChild(_s);
    }

    function foxJudgeThinkRerender() {
      const { modules, order } = foxJudgeLoadThinkModules();
      const poolEl = panel.querySelector('#foxjudge-think-pool');
      const activeEl = panel.querySelector('#foxjudge-think-active');
      if (!poolEl || !activeEl) return;

      // 📱 触摸设备检测：移动端禁用 HTML5 拖拽。draggable=true 会拦截 touchstart，
      //    导致 ⇢↑↓⇠✏️🗑️ 等子按钮的 click 完全无法触发（PC 端拖拽不受影响，仍可用）。
      //    移动端模块移动/排序改用 ⇢↑↓⇠ 按钮（按钮逻辑本就存在，见下方绑定）。
      const _fjTkTouch = _fjTkIsMobile();

      const itemHtml = (m, ctx) => {
        const lockMark = m.locked ? ' 🔒' : '';
        const delBtn = m.locked ? '' : `<span class="fj-tk-del fj-tk-btn" data-id="${escapeHtml(m.id)}" title="删除" style="cursor:pointer;opacity:0.6;">🗑️</span>`;
        // 触摸/通用控制按钮：弥补移动端无法 HTML5 拖拽（桌面端仍可拖拽）
        let ctrl = '';
        if (!m.locked) {
          if (ctx === 'pool') {
            ctrl = `<span class="fj-tk-enable fj-tk-btn" data-id="${escapeHtml(m.id)}" title="启用（移到右侧）" style="cursor:pointer;opacity:0.85;">⇢</span>`;
          } else {
            ctrl = `<span class="fj-tk-up fj-tk-btn" data-id="${escapeHtml(m.id)}" title="上移" style="cursor:pointer;opacity:0.85;">↑</span>`
                  + `<span class="fj-tk-down fj-tk-btn" data-id="${escapeHtml(m.id)}" title="下移" style="cursor:pointer;opacity:0.85;">↓</span>`
                  + `<span class="fj-tk-disable fj-tk-btn" data-id="${escapeHtml(m.id)}" title="停用（移到左侧）" style="cursor:pointer;opacity:0.85;">⇠</span>`;
          }
        }
        return `<div class="fj-tk-item" draggable="${_fjTkTouch ? 'false' : 'true'}" data-id="${escapeHtml(m.id)}" style="display:flex;justify-content:space-between;align-items:center;gap:4px;padding:8px 10px;border:1px solid rgba(232,120,74,0.2);border-radius:8px;background:rgba(255,255,255,0.04);cursor:grab;font-size:12px;color:#e8ddd4;min-width:0;overflow:hidden;">
          <span style="flex:1;min-width:3em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(m.name)}${lockMark}</span>
          <span style="display:flex;gap:4px;flex-shrink:0;align-items:center;max-width:100%;">
            ${ctrl}
            <span class="fj-tk-edit fj-tk-btn" data-id="${escapeHtml(m.id)}" title="编辑" style="cursor:pointer;opacity:0.7;">✏️</span>
            ${delBtn}
          </span>
        </div>`;
      };

      const poolItems = modules.filter(m => !order.includes(m.id));
      poolEl.innerHTML = poolItems.length ? poolItems.map(m => itemHtml(m, 'pool')).join('') : '<div style="font-size:11px;color:#555;padding:8px;">（无未启用模块）</div>';
      const activeItems = order.map(id => modules.find(m => m.id === id)).filter(Boolean);
      activeEl.innerHTML = activeItems.length ? activeItems.map(m => itemHtml(m, 'active')).join('') : '<div style="font-size:11px;color:#555;padding:8px;">（无启用模块）</div>';

      panel.querySelectorAll('.fj-tk-item').forEach(el => {
        if (_fjTkTouch) return; // 📱 移动端跳过 HTML5 拖拽绑定（draggable 已禁用），改用 ⇢↑↓⇠ 按钮
        el.ondragstart = (e) => { _fjTkDragId = el.dataset.id; e.dataTransfer.effectAllowed = 'move'; try { e.dataTransfer.setData('text/plain', el.dataset.id); } catch { } };
        el.ondragover = (e) => { e.preventDefault(); };
        el.ondrop = (e) => {
          e.preventDefault(); e.stopPropagation();
          const dragId = _fjTkDragId; if (!dragId) return;
          if (dragId === 'head' || dragId === 'tail') { foxJudgeThinkRerender(); return; }
          const container = el.parentElement;
          const isActive = container.id === 'foxjudge-think-active';
          const { modules, order } = foxJudgeLoadThinkModules();
          if (isActive) {
            let newOrder = order.filter(id => id !== dragId);
            const ti = newOrder.indexOf(el.dataset.id);
            if (ti >= 0) newOrder.splice(ti, 0, dragId); else newOrder.push(dragId);
            newOrder = ['head', ...newOrder.filter(x => x !== 'head' && x !== 'tail'), 'tail'];
            foxJudgeSaveThinkModules(modules, newOrder);
          } else {
            foxJudgeSaveThinkModules(modules, order.filter(id => id !== dragId));
          }
          foxJudgeThinkRerender();
        };
      });
      panel.querySelectorAll('.fj-tk-edit').forEach(el => {
        el.onclick = (e) => { e.stopPropagation(); foxJudgeThinkOpenEditor(el.dataset.id); };
      });
      panel.querySelectorAll('.fj-tk-del').forEach(el => {
        el.onclick = (e) => {
          e.stopPropagation();
          if (!_fjConfirm('确定删除这个自定义模块？')) return;
          const id = el.dataset.id;
          const { modules, order } = foxJudgeLoadThinkModules();
          foxJudgeSaveThinkModules(modules.filter(m => m.id !== id), order.filter(x => x !== id));
          toast('🗑️ 已删除模块', 'success');
          foxJudgeThinkRerender();
        };
      });
      // 触摸/通用控制：启用 / 停用 / 上移 / 下移（弥补移动端无法拖拽）
      panel.querySelectorAll('.fj-tk-enable').forEach(el => {
        el.onclick = (e) => {
          e.stopPropagation();
          const id = el.dataset.id;
          const { modules, order } = foxJudgeLoadThinkModules();
          if (order.includes(id)) { foxJudgeThinkRerender(); return; }
          let no = order.filter(x => x !== 'head' && x !== 'tail');
          no.push(id);
          foxJudgeSaveThinkModules(modules, ['head', ...no, 'tail']);
          foxJudgeThinkRerender();
        };
      });
      panel.querySelectorAll('.fj-tk-disable').forEach(el => {
        el.onclick = (e) => {
          e.stopPropagation();
          const id = el.dataset.id;
          const { modules, order } = foxJudgeLoadThinkModules();
          foxJudgeSaveThinkModules(modules, order.filter(x => x !== id));
          foxJudgeThinkRerender();
        };
      });
      panel.querySelectorAll('.fj-tk-up').forEach(el => {
        el.onclick = (e) => {
          e.stopPropagation();
          const id = el.dataset.id;
          const { modules, order } = foxJudgeLoadThinkModules();
          let no = order.filter(x => x !== 'head' && x !== 'tail');
          const i = no.indexOf(id);
          if (i > 0) { no.splice(i, 1); no.splice(i - 1, 0, id); }
          foxJudgeSaveThinkModules(modules, ['head', ...no, 'tail']);
          foxJudgeThinkRerender();
        };
      });
      panel.querySelectorAll('.fj-tk-down').forEach(el => {
        el.onclick = (e) => {
          e.stopPropagation();
          const id = el.dataset.id;
          const { modules, order } = foxJudgeLoadThinkModules();
          let no = order.filter(x => x !== 'head' && x !== 'tail');
          const i = no.indexOf(id);
          if (i >= 0 && i < no.length - 1) { no.splice(i, 1); no.splice(i + 1, 0, id); }
          foxJudgeSaveThinkModules(modules, ['head', ...no, 'tail']);
          foxJudgeThinkRerender();
        };
      });
    }

    // 容器级 drop：拖到空白处 = 移入该区
    const _fjPoolEl = panel.querySelector('#foxjudge-think-pool');
    const _fjActiveEl = panel.querySelector('#foxjudge-think-active');
    if (_fjPoolEl) {
      _fjPoolEl.ondragover = (e) => e.preventDefault();
      _fjPoolEl.ondrop = (e) => {
        e.preventDefault();
        const dragId = _fjTkDragId; if (!dragId) return;
        if (dragId === 'head' || dragId === 'tail') { foxJudgeThinkRerender(); return; }
        const { modules, order } = foxJudgeLoadThinkModules();
        foxJudgeSaveThinkModules(modules, order.filter(id => id !== dragId));
        foxJudgeThinkRerender();
      };
    }
    if (_fjActiveEl) {
      _fjActiveEl.ondragover = (e) => e.preventDefault();
      _fjActiveEl.ondrop = (e) => {
        e.preventDefault();
        const dragId = _fjTkDragId; if (!dragId) return;
        if (dragId === 'head' || dragId === 'tail') { foxJudgeThinkRerender(); return; }
        const { modules, order } = foxJudgeLoadThinkModules();
        if (!order.includes(dragId)) {
          let newOrder = [...order];
          const ti = newOrder.indexOf('tail');
          if (ti >= 0) newOrder.splice(ti, 0, dragId); else newOrder.push(dragId);
          newOrder = ['head', ...newOrder.filter(x => x !== 'head' && x !== 'tail'), 'tail'];
          foxJudgeSaveThinkModules(modules, newOrder);
        }
        foxJudgeThinkRerender();
      };
    }

    // 📱 移动端软键盘遮挡修复：让编辑层高度跟随可视视口（键盘弹出后的可见区域），
    //    避免模态按 layout viewport 居中后下半截被键盘遮挡、只剩半截可见。
    //    VV 监听句柄存在 layer._fjTkVvHandler 上（编辑层会被移到 topDoc.body 并跨面板会话复用），
    //    这样任意关闭路径都能可靠拆除上一次的监听，避免泄漏/累积。
    function _fjTkIsMobile() {
      try { return !!(topWindow.matchMedia && topWindow.matchMedia('(max-width: 768px), (pointer: coarse)').matches); } catch { return false; }
    }
    function _fjTkApplyVvHeight() {
      const layer = topDoc.getElementById('foxjudge-think-edit-layer');
      const vv = topWindow.visualViewport;
      if (!layer || !vv) return;
      if (layer.style.display === 'none') return; // 编辑层未显示则不调整，确保任何残留监听都不再产生副作用
      layer.style.top = vv.offsetTop + 'px';
      layer.style.height = vv.height + 'px';
      layer.style.bottom = 'auto';
    }
    function _fjTkDetachVv() {
      const layer = topDoc.getElementById('foxjudge-think-edit-layer');
      const vv = topWindow.visualViewport;
      const h = layer && layer._fjTkVvHandler;
      if (vv && h) {
        try { vv.removeEventListener('resize', h); } catch { }
        try { vv.removeEventListener('scroll', h); } catch { }
      }
      if (layer) { layer._fjTkVvHandler = null; layer.style.top = ''; layer.style.height = ''; layer.style.bottom = ''; }
    }
    function _fjTkAttachVv() {
      if (!_fjTkIsMobile()) return;
      const vv = topWindow.visualViewport;
      if (!vv) return;
      _fjTkDetachVv(); // 先拆除上一次（可能是上一个面板会话）残留的监听
      const layer = topDoc.getElementById('foxjudge-think-edit-layer');
      if (!layer) return;
      _fjTkApplyVvHeight();
      const h = () => _fjTkApplyVvHeight();
      layer._fjTkVvHandler = h;
      vv.addEventListener('resize', h);
      vv.addEventListener('scroll', h);
    }
    // 统一关闭编辑层：拆 VV 监听 + 移除弹层。编辑器关闭/保存、面板整体关闭均复用。
    function _fjTkCloseEditor() {
      _fjTkDetachVv();
      const layer = topDoc.getElementById('foxjudge-think-edit-layer');
      if (layer) layer.remove();
    }
    function foxJudgeThinkOpenEditor(id) {
      const { modules } = foxJudgeLoadThinkModules();
      const m = modules.find(x => x.id === id);
      if (!m) return;
      _fjTkEditId = id;

      // ✅ 每次打开编辑器都创建全新的编辑层，直接挂在 topDoc.body 下。
      //    不再从面板内移动（move）编辑层——移动方案在同一面板会话内二次打开时会出 BUG。
      //    创建后绑定 close/save 处理器，关闭时直接 remove()，零残留。
      _fjTkCloseEditor(); // 先清理上一次可能残留的编辑层

      const layer = topDoc.createElement('div');
      layer.id = 'foxjudge-think-edit-layer';
      layer.style.cssText = 'display:flex;position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:10000010;align-items:center;justify-content:center;';
      layer.innerHTML = `
        <div style="width:560px;max-width:90vw;max-height:80vh;background:rgba(22,18,20,0.98);border:1px solid rgba(232,120,74,0.3);border-radius:16px;padding:18px;display:flex;flex-direction:column;gap:10px;color:#e8ddd4;font-size:13px;">
          <div style="display:flex;justify-content:space-between;align-items:center;">
            <span id="foxjudge-think-edit-title" style="font-weight:600;font-size:14px;color:#f0a070;">${m.locked ? '编辑模块：' + escapeHtml(m.name) + '（锁定，可改内容）' : '编辑模块'}</span>
            <span id="foxjudge-think-edit-close" style="cursor:pointer;font-size:16px;color:#706058;">✕</span>
          </div>
          <input id="foxjudge-think-edit-name" placeholder="模块名称" value="${escapeHtml(m.name || '')}" ${m.locked ? 'disabled' : ''} style="background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:8px;color:#e8ddd4;padding:8px 10px;font-size:13px;font-family:inherit;box-sizing:border-box;" />
          <textarea id="foxjudge-think-edit-content" placeholder="模块提示词内容（会按顺序拼接到思维链）" style="flex:1;min-height:240px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.2);border-radius:8px;color:#e8ddd4;padding:10px;font-size:12px;font-family:monospace;resize:vertical;box-sizing:border-box;white-space:pre-wrap;">${escapeHtml(m.content || '')}</textarea>
          <div style="display:flex;gap:8px;">
            <button id="foxjudge-think-edit-save" style="flex:1;padding:9px;border:none;border-radius:8px;background:rgba(232,120,74,0.2);color:#f0a070;cursor:pointer;font-size:13px;">💾 保存</button>
          </div>
        </div>`;
      topDoc.body.appendChild(layer);

      // 绑定 close/save
      layer.querySelector('#foxjudge-think-edit-close').onclick = () => { _fjTkCloseEditor(); };
      layer.querySelector('#foxjudge-think-edit-save').onclick = () => {
        const name = layer.querySelector('#foxjudge-think-edit-name').value.trim();
        const content = layer.querySelector('#foxjudge-think-edit-content').value;
        const { modules: ms, order } = foxJudgeLoadThinkModules();
        const target = ms.find(x => x.id === _fjTkEditId);
        if (target) { if (!target.locked && name) target.name = name; target.content = content; }
        foxJudgeSaveThinkModules(ms, order);
        _fjTkCloseEditor();
        toast('✅ 模块已保存', 'success');
        foxJudgeThinkRerender();
      };

      _fjTkAttachVv();
      const contentInp = layer.querySelector('#foxjudge-think-edit-content');
      const nameInp = layer.querySelector('#foxjudge-think-edit-name');
      const focusScroll = () => { setTimeout(() => { try { contentInp.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch { } }, 300); };
      nameInp.onfocus = focusScroll;
      contentInp.onfocus = focusScroll;
    }

    panel.querySelector('#foxjudge-think-preset-os').onclick = () => {
      foxJudgeApplyThinkPreset('os');
      toast('🎭 已排序成 OS 思维链', 'success');
      foxJudgeThinkRerender();
    };
    panel.querySelector('#foxjudge-think-preset-director').onclick = () => {
      foxJudgeApplyThinkPreset('director');
      toast('🎬 已排序成导演思维链', 'success');
      foxJudgeThinkRerender();
    };
    panel.querySelector('#foxjudge-think-add').onclick = () => {
      const newId = 'custom_' + Date.now() + '_' + Math.random().toString(36).slice(2, 6);
      const { modules, order } = foxJudgeLoadThinkModules();
      modules.push({ id: newId, name: '新模块', content: '', locked: false });
      let newOrder = [...order];
      const ti = newOrder.indexOf('tail');
      if (ti >= 0) newOrder.splice(ti, 0, newId); else newOrder.push(newId);
      foxJudgeSaveThinkModules(modules, newOrder);
      foxJudgeThinkRerender();
      foxJudgeThinkOpenEditor(newId);
    };

    panel.querySelector('#foxjudge-phase2-reset').onclick = () => {
      if (!_fjConfirm('确定恢复默认思维链模块配置？所有自定义模块和排序将被重置为 OS 默认。')) return;
      try { localStorage.removeItem(FOX_JUDGE_THINK_MODULES_LS_KEY); } catch { }
      try { localStorage.removeItem(FOX_JUDGE_THINK_ORDER_LS_KEY); } catch { }
      toast('↩️ 思维链模块已恢复默认（OS）', 'success');
      foxJudgeThinkRerender();
    };

    foxJudgeThinkRerender();

    // （自定义思考要求已删除，改用思维链模块化编辑）

    panel.querySelectorAll('[data-strength]').forEach((btn) => {
      btn.onclick = () => {
        const v = btn.dataset.strength;
        const newCfg = foxJudgeReadConfig();
        newCfg.strength = v;
        foxJudgeSaveConfig(newCfg);
        foxJudgeInvalidateStaticCache();

        panel.querySelectorAll('[data-strength]').forEach((b) => {
          const active = b === btn;
          b.style.borderColor = active ? 'rgba(255,170,90,0.55)' : 'rgba(232,120,74,0.2)';
          b.style.background = active ? 'rgba(232,120,74,0.22)' : 'rgba(255,255,255,0.03)';
          b.style.color = active ? '#ffb06a' : '#a09088';
        });
        toast(`✅ 思考强度：${v}，缓存已清空`, 'success');
      };
    });

    // （旧的 phase2 预设切换按钮已删除，改为上方模块化拖拽系统）

    panel.querySelector('#foxjudge-clear-cache').onclick = () => {
      foxJudgeInvalidateStaticCache();
      toast('🧹 已清空全部缓存', 'success');
    };

    panel.querySelector('#foxjudge-force-refresh').onclick = () => {
      foxJudgeInvalidateStaticCache();
      toast('🔄 缓存已清空，下次发送时第一阶段会重跑', 'success');
    };

    panel.querySelector('#foxjudge-phase1-cache-save').onclick = () => {
      const ta = panel.querySelector('#foxjudge-phase1-cache-viewer');
      const edited = (ta?.value || '').trim();
      const charId = getCurrentCharId();

      // ✅ 若保存空内容 = 等同清空当前角色卡缓存，避免在 cache 里留下"空 phase1_result"
      //    导致下次主流程要么误命中、要么连续触发补跑路径。
      if (!edited) {
        try {
          const FOX_JUDGE_LS_KEYS_REF = (typeof FOX_JUDGE_LS_KEYS !== 'undefined') ? FOX_JUDGE_LS_KEYS : null;
          if (FOX_JUDGE_LS_KEYS_REF?.charCachePrefix) {
            localStorage.removeItem(FOX_JUDGE_LS_KEYS_REF.charCachePrefix + charId);
          }
        } catch {}
        toast('🧹 第一阶段缓存已清空（保存内容为空）；下次发送时第一阶段会重跑', 'success');
        return;
      }

      const existingCache = foxJudgeGetStaticCache(charId);
      foxJudgeSaveStaticCache(charId, {
        version: 2,
        char_id: charId,
        phase1_result: edited,
        strength: existingCache?.strength || foxJudgeReadConfig().strength,
        created_at: existingCache?.created_at || new Date().toISOString(),
        edited_at: new Date().toISOString(),
      });
      toast('✅ 第一阶段缓存已保存编辑', 'success');
    };

    panel.querySelector('#foxjudge-phase1-cache-refresh').onclick = () => {
      const ta = panel.querySelector('#foxjudge-phase1-cache-viewer');
      if (ta) {
        try {
          const c = foxJudgeGetStaticCache(getCurrentCharId());
          ta.value = c?.phase1_result || '（无缓存，下次发送时自动生成）';
        } catch { ta.value = '（读取失败）'; }
      }
      toast('🔄 已刷新第一阶段缓存显示', 'success');
    };

    panel.querySelector('#foxjudge-cache-enabled').onchange = (e) => {
      const newCfg = foxJudgeReadConfig();
      newCfg.cacheEnabled = e.target.checked;
      foxJudgeSaveConfig(newCfg);
      toast(e.target.checked ? '✅ 已启用第一阶段缓存' : '📴 已关闭缓存，每次都重跑第一阶段', e.target.checked ? 'success' : 'info');
    };

    panel.querySelector('#foxjudge-phase1-fixed').onchange = (e) => {
      const newCfg = foxJudgeReadConfig();
      newCfg.phase1Fixed = !!e.target.checked;
      if (newCfg.phase1Fixed) newCfg.cacheEnabled = true;
      foxJudgeSaveConfig(newCfg);
      const cacheCb = panel.querySelector('#foxjudge-cache-enabled');
      if (cacheCb && newCfg.phase1Fixed) cacheCb.checked = true;
      // 🦊 修复：开启 phase1Fixed 时，主动清除当前角色卡缓存的残留 stale 标记。
      //    之前若在 phase1Fixed=false 时被标过 stale，开启后该标记会残留，导致 reroll/swipe
      //    路径误判"缓存失效"每次重跑第一阶段。这里重写缓存清除 stale，让固定语义立即生效。
      if (newCfg.phase1Fixed) {
        try {
          const charId = getCurrentCharId();
          const sc = foxJudgeGetStaticCache(charId);
          if (sc && sc.phase1_result && typeof sc.phase1_result === 'string' && sc.phase1_result.trim()) {
            sc.stale = false;
            delete sc.stale_fingerprint_seen_at;
            sc.fingerprint = foxJudgeCalcCharFingerprint();
            foxJudgeSaveStaticCache(charId, sc);
            log('[狐裁] phase1Fixed 开启：已清除缓存残留 stale 标记');
          }
        } catch (err) { log('[狐裁] phase1Fixed 开启：清除 stale 标记失败', err); }
      }
      toast(newCfg.phase1Fixed ? '📌 已固定第一阶段思考：不会自动重置缓存' : '📴 已取消固定第一阶段思考', newCfg.phase1Fixed ? 'success' : 'info');
    };

    const runPhase1NowBtn = panel.querySelector('#foxjudge-run-phase1-now');
    if (runPhase1NowBtn) {
      runPhase1NowBtn.onclick = async () => {
        if (ssIsTaskRunning('fox_judge_chain')) {
          ssCancelTask('fox_judge_chain', '狐裁第一阶段');
          return;
        }
        const oldText = runPhase1NowBtn.textContent;
        let taskToast = null;
        let diag = null;
        let diagOutcome = 'error';
        let diagResult = {};
        try {
          runPhase1NowBtn.textContent = '⛔ 思考中，点击中断';
          const newCfg = foxJudgeReadConfig();
          diag = foxJudgeBeginDiag('manual-phase1', {
            contextFloors: newCfg.contextFloors,
            retryEnabled: newCfg.retryEnabled,
            maxRetries: newCfg.maxRetries,
            apiType: newCfg.apiType,
            customModel: newCfg.customApi?.model || '',
          });
          const contextFloors = Number.isFinite(newCfg.contextFloors) && newCfg.contextFloors > 0
            ? Math.floor(newCfg.contextFloors)
            : 0;
          const filterSettings = {
            ...(newCfg.filterSettings || FOX_JUDGE_DEFAULT_FILTER_SETTINGS),
            contextFloors,
          };
          ssStartTask('fox_judge_chain', '狐裁第一阶段');
          taskToast = ssTaskToast('fox_judge_chain', '🦊 狐裁：正在立即思考第一阶段……点击可中断');
          const contextText = await ssBuildFilteredMainContextText('狐裁', filterSettings, {
            skipRoleLabels: true,
            exactChatFloors: contextFloors,
            requireCaptured: true,
          });
          const phase1Result = await foxJudgeRunPhase1WithRetry(newCfg, contextText, newCfg.maxRetries);
          if (!phase1Result || !String(phase1Result).trim()) throw new Error('第一阶段返回空内容');
          const charId = getCurrentCharId();
          foxJudgeSaveStaticCache(charId, {
            version: 2,
            char_id: charId,
            phase1_result: phase1Result,
            strength: newCfg.strength,
            created_at: new Date().toISOString(),
            manual_run_at: new Date().toISOString(),
          });
          const ta = panel.querySelector('#foxjudge-phase1-cache-viewer');
          if (ta) ta.value = phase1Result;
          diagOutcome = 'success';
          diagResult = { phase1Length: phase1Result.length, contextLength: contextText.length };
          toast('✅ 第一阶段思考完成并已保存缓存', 'success');
        } catch (err) {
          const msg = err?.message || String(err || '未知错误');
          diagOutcome = foxJudgeIsUserCancellation(err) ? 'cancelled' : 'error';
          diagResult = { message: msg, error: foxJudgeDiagError(err) };
          foxJudgeDiag('手动第一阶段:异常', diagResult, 'error', diag);
          if (foxJudgeIsUserCancellation(err)) toast('⛔ 第一阶段思考已中断', 'warning');
          else {
            log('[狐裁] 立即思考第一阶段失败', err);
            toast(`❌ 第一阶段思考失败：${msg}`, 'error');
          }
        } finally {
          try { taskToast?.remove?.(); } catch { }
          ssEndTask('fox_judge_chain');
          if (diag) foxJudgeEndDiag(diagOutcome, diagResult, diag);
          runPhase1NowBtn.textContent = oldText;
        }
      };
    }

    panel.querySelector('#foxjudge-swipe-rethink').onchange = (e) => {
      const newCfg = foxJudgeReadConfig();
      newCfg.swipeRethink = e.target.checked;
      foxJudgeSaveConfig(newCfg);
      foxJudgeRegisterSwipeRerollListeners();
      toast(e.target.checked ? '✅ Swipe 时将重跑第二阶段' : '📴 Swipe 时不重跑，沿用上一次完整思维链', e.target.checked ? 'success' : 'info');
    };

    panel.querySelector('#foxjudge-reroll-rethink').onchange = (e) => {
      const newCfg = foxJudgeReadConfig();
      newCfg.rerollRethink = e.target.checked;
      foxJudgeSaveConfig(newCfg);
      foxJudgeRegisterSwipeRerollListeners();
      toast(e.target.checked ? '✅ Reroll 时将重跑第二阶段' : '📴 Reroll 时不重跑，沿用上一次完整思维链', e.target.checked ? 'success' : 'info');
    };

    const foxjudgeRetryEnabled = topDoc.getElementById('foxjudge-retry-enabled');
    if (foxjudgeRetryEnabled) {
      foxjudgeRetryEnabled.onchange = (e) => {
        const newCfg = foxJudgeReadConfig();
        newCfg.retryEnabled = !!e.target.checked;
        foxJudgeSaveConfig(newCfg);
        toast(e.target.checked ? '✅ 已开启空回复/报错重试' : '📴 已关闭空回复/报错重试（思维链只跑一次）', e.target.checked ? 'success' : 'info');
      };
    }

    const foxjudgeMaxRetries = topDoc.getElementById('foxjudge-max-retries');
    if (foxjudgeMaxRetries) {
      foxjudgeMaxRetries.onchange = () => {
        // ✅ 修复：parseInt(0) || 3 会把用户输入的 0 改写成 3，导致无法关闭重试
        const n = parseInt(foxjudgeMaxRetries.value, 10);
        const val = Math.max(0, Math.min(5, Number.isFinite(n) ? n : 3));
        foxjudgeMaxRetries.value = val;
        const newCfg = foxJudgeReadConfig();
        newCfg.maxRetries = val;
        foxJudgeSaveConfig(newCfg);
        toast(`🔄 空回复重试次数已设为 ${val}${val === 0 ? '（已关闭重试）' : ''}`, 'info');
      };
    }

    // ✅ 尾部锚点配置
    const foxjudgeApiTypeSel = topDoc.getElementById('foxjudge-api-type');
    const foxjudgeModelSel = topDoc.getElementById('foxjudge-api-model-select');
    const foxjudgeModelInp = topDoc.getElementById('foxjudge-api-model');

    const foxjudgeSaveApiConfig = () => {
      const newCfg = foxJudgeReadConfig();
      newCfg.apiType = foxjudgeApiTypeSel?.value || 'current';
      if (newCfg.apiType === 'custom') {
        newCfg.customApi.proxyPreset = '';
        newCfg.customApi.apiurl = topDoc.getElementById('foxjudge-api-url')?.value?.trim() || '';
        newCfg.customApi.key = topDoc.getElementById('foxjudge-api-key')?.value?.trim() || '';
        newCfg.customApi.model = foxjudgeModelInp?.value?.trim() || '';
        newCfg.customApi.source = newCfg.customApi.source || 'openai';
        newCfg.customApi.temperature = topDoc.getElementById('foxjudge-api-temp')?.value || '';
        newCfg.customApi.max_tokens = topDoc.getElementById('foxjudge-api-max-tokens')?.value || '';
        newCfg.customApi.top_p = topDoc.getElementById('foxjudge-api-top-p')?.value || '';
        newCfg.customApi.frequency_penalty = topDoc.getElementById('foxjudge-api-freq-pen')?.value || '';
        newCfg.customApi.presence_penalty = topDoc.getElementById('foxjudge-api-pres-pen')?.value || '';
      }
      // 🦊 附加参数（YAML）：无论 apiType 都保存，避免切换 API 类型后丢失（实际仅 custom 模式生效）
      {
        const __extra = ssReadExtraParamsFromPanel('foxjudge', topDoc);
        newCfg.customApi.extraBodyParamsYaml = __extra.extraBodyParamsYaml;
        newCfg.customApi.excludeBodyParamsYaml = __extra.excludeBodyParamsYaml;
        newCfg.customApi.extraHeadersYaml = __extra.extraHeadersYaml;
      }
      foxJudgeSaveConfig(newCfg);
    };

    if (foxjudgeApiTypeSel) {
      foxjudgeApiTypeSel.onchange = () => {
        const isC = foxjudgeApiTypeSel.value === 'custom';
        const caSection = topDoc.getElementById('foxjudge-custom-api-section');
        if (caSection) caSection.style.display = isC ? 'block' : 'none';
        foxjudgeSaveApiConfig();
      };
    }

    if (foxjudgeModelSel && foxjudgeModelInp) {
      foxjudgeModelSel.onchange = () => {
        if (foxjudgeModelSel.value) {
          foxjudgeModelInp.value = foxjudgeModelSel.value;
          foxjudgeSaveApiConfig();
        }
      };
    }

    const foxjudgeFetchBtn = topDoc.getElementById('foxjudge-fetch-models');
    if (foxjudgeFetchBtn) {
      foxjudgeFetchBtn.onclick = async () => {
        const apiurl = topDoc.getElementById('foxjudge-api-url')?.value?.trim() || '';
        const key = topDoc.getElementById('foxjudge-api-key')?.value?.trim() || '';
        if (!apiurl) {
          toast('请先填写 API 地址', 'warning');
          return;
        }

        const oldText = foxjudgeFetchBtn.textContent;
        foxjudgeFetchBtn.textContent = '加载中…';
        foxjudgeFetchBtn.disabled = true;
        state.foxJudgeLoading = true;

        try {
          const getModelList = getFn('getModelList');
          let models = [];

          if (typeof getModelList === 'function') {
            models = await getModelList({
              apiurl: apiurl.replace(/\/+$/, ''),
              key: key || '',
            });
          } else {
            // 兜底：直接调用酒馆的 chat-completions/status
            const headers = SillyTavern?.getRequestHeaders?.() || {};
            const resp = await fetch('/api/backends/chat-completions/status', {
              method: 'POST',
              headers,
              body: JSON.stringify({
                reverse_proxy: apiurl,
                proxy_password: key || '',
                chat_completion_source: 'openai',
              }),
            });
            const json = await resp.json();
            models = (json?.data || []).map(x => String(x?.id ?? '').trim()).filter(Boolean);
          }

          models = [...new Set(models)].sort();
          state.foxJudgeModels = models;

          const selEl = topDoc.getElementById('foxjudge-api-model-select');
          if (selEl) {
            const currentModel = topDoc.getElementById('foxjudge-api-model')?.value?.trim() || '';
            selEl.innerHTML = '<option value="">（从列表选择）</option>' +
              models.map(m => `<option value="${escapeHtml(m)}" ${m === currentModel ? 'selected' : ''}>${escapeHtml(m)}</option>`).join('');
          }

          toast(
            models.length ? `✅ 已获取 ${models.length} 个模型` : '⚠️ 模型列表为空',
            models.length ? 'success' : 'warning'
          );
        } catch (err) {
          log('[狐裁] 获取模型失败', err);
          toast(`❌ 获取模型失败：${err?.message || err}`, 'error');
        } finally {
          state.foxJudgeLoading = false;
          foxjudgeFetchBtn.textContent = oldText;
          foxjudgeFetchBtn.disabled = false;
        }
      };
    }

    ssAttachCustomApiPresetControls('foxjudge', {
      onApply: () => {
        const sec = topDoc.getElementById('foxjudge-custom-api-section');
        if (foxjudgeApiTypeSel) foxjudgeApiTypeSel.value = 'custom';
        if (sec) sec.style.display = 'block';
        foxjudgeSaveApiConfig();
      },
      onSave: foxjudgeSaveApiConfig,
    });

    const foxjudgeApiInputs = [
      '#foxjudge-api-url', '#foxjudge-api-key', '#foxjudge-api-model',
      '#foxjudge-api-temp', '#foxjudge-api-max-tokens', '#foxjudge-api-top-p',
      '#foxjudge-api-freq-pen', '#foxjudge-api-pres-pen',
      // 🦊 附加参数（YAML）三个文本框：input/change 时自动保存
      '#foxjudge-extra-body-yaml', '#foxjudge-exclude-body-yaml', '#foxjudge-extra-headers-yaml',
    ];
    foxjudgeApiInputs.forEach(id => {
      const el = topDoc.getElementById(id.replace('#', ''));
      if (el) {
        el.onchange = foxjudgeSaveApiConfig;
        // textarea 改动后用户常常不 blur 就关面板，补一个 input 监听确保即时保存
        if (el.tagName === 'TEXTAREA') el.oninput = foxjudgeSaveApiConfig;
      }
    });

    const foxjudgeFilterCheckbox = panel.querySelector('#foxjudge-content-filter');
    if (foxjudgeFilterCheckbox) {
      foxjudgeFilterCheckbox.onchange = () => {
        const newCfg = foxJudgeReadConfig();
        if (!newCfg.filterSettings) newCfg.filterSettings = { ...FOX_JUDGE_DEFAULT_FILTER_SETTINGS };
        newCfg.filterSettings.enableContentFilter = !!foxjudgeFilterCheckbox.checked;
        foxJudgeSaveConfig(newCfg);
        foxJudgeInvalidateStaticCache();
      };
    }

    const foxjudgeFilterSave = () => {
      const newCfg = foxJudgeReadConfig();
      const previousContextFloors = newCfg.contextFloors;
      const previousFilterSettings = JSON.stringify(ssNormalizeTagFilterSettings(newCfg.filterSettings || {}));
      if (!newCfg.filterSettings) newCfg.filterSettings = { ...FOX_JUDGE_DEFAULT_FILTER_SETTINGS };
      newCfg.filterSettings.enableContentFilter = !!panel.querySelector('#foxjudge-content-filter')?.checked;
      newCfg.filterSettings.includeTagPairs = ssReadTagPairsEditor('foxjudge-inc', panel);
      newCfg.filterSettings.excludeTagPairs = ssReadTagPairsEditor('foxjudge-exc', panel);
      const floorInput = panel.querySelector('#foxjudge-context-floors');
      const floorValue = parseInt(floorInput?.value ?? '0', 10);
      newCfg.contextFloors = Number.isFinite(floorValue)
        ? Math.max(0, Math.min(9999, floorValue))
        : 0;
      if (floorInput) floorInput.value = String(newCfg.contextFloors);
      foxJudgeSaveConfig(newCfg);
      const filterChanged = previousFilterSettings !== JSON.stringify(ssNormalizeTagFilterSettings(newCfg.filterSettings || {}));
      if (previousContextFloors !== newCfg.contextFloors || filterChanged) {
        foxJudgeInvalidateStaticCache();
        log('[狐裁] 上下文设置变更；已清空第一阶段缓存与聊天窗口锚点');
      }
    };

    panel.querySelectorAll('.foxjudge-inc-tag-start, .foxjudge-inc-tag-end, .foxjudge-exc-tag-start, .foxjudge-exc-tag-end').forEach(el => {
      el.onchange = foxjudgeFilterSave;
    });

    const foxjudgeContextFloors = panel.querySelector('#foxjudge-context-floors');
    if (foxjudgeContextFloors) foxjudgeContextFloors.onchange = foxjudgeFilterSave;

    panel.querySelector('#foxjudge-filter-save')?.addEventListener('click', () => {
      foxjudgeFilterSave();
      const saved = foxJudgeReadConfig();
      toast(`✅ 狐裁上下文设置已保存：${saved.contextFloors > 0 ? `稳定 ${saved.contextFloors} 楼 + 最多 10 楼弹性缓冲` : '全部楼层'}`, 'success');
    });

    panel.querySelector('#foxjudge-close').onclick = () => {
      xhGuideEnd();
      overlay.remove();
      panel.remove();
    };
    // ✅ 移动端关闭按钮
    const closeMb = panel.querySelector('#foxjudge-close-mb');
    if (closeMb) closeMb.onclick = () => {
      xhGuideEnd();
      overlay.remove();
      panel.remove();
    };

    // 📑 Tab switching: PC rail + mobile dock
    const fjSubMap = { main: '主控 · 总开关 · 强度', phase1: '一阶段 · 规则审查', phase2: '二阶段 · 思维链模块', api: 'API · 模型 · 参数', set: '设置 · 过滤 · 缓存 · 重试' };
    const fjSwitchTab = (tabName) => {
