    topDoc.getElementById('foxmem-import-btn').onclick = () => {
      const inp = topDoc.createElement('input');
      inp.type = 'file'; inp.accept = 'application/json';
      inp.onchange = async (e) => {
        const file = e.target.files?.[0];
        if (!file) return;
        try {
          const text = await file.text();
          const data = JSON.parse(text);
          if (!data.memories || !Array.isArray(data.memories)) { toast('❌ 格式错误', 'error'); return; }
          const ok = topWindow?.confirm ? topWindow.confirm(`导入 ${data.memories.length} 条？\n\n确定：合并到当前记忆\n取消：放弃导入`) : true;
          if (!ok) { toast('已取消导入', 'info'); return; }
          const currentData = loadFoxMemory();
          if (data.charId && data.charId !== getCurrentCharId()) {
            const confirmed = topWindow?.confirm ? topWindow.confirm(`导出文件属于角色「${data.charId}」，当前角色是「${getCurrentCharId()}」。仍要导入吗？`) : false;
            if (!confirmed) return;
          }
          const memoryMap = new Map();
          for (const mem of [...(currentData.memories || []), ...(data.memories || [])]) {
            const key = mem?.id || `${mem?.category || ''}::${String(mem?.title || '').trim().toLowerCase()}`;
            if (key) memoryMap.set(key, mem);
          }
          const merged = [...memoryMap.values()];
          const atomMap = new Map((currentData.plotAtoms || []).map(atom => [atom.id || foxMemoryAtomFingerprint(atom), atom]));
          for (const atom of Array.isArray(data.plotAtoms) ? data.plotAtoms : []) {
            if (!foxMemoryIsPlotAtom(atom)) continue;
            atomMap.set(atom.id || foxMemoryAtomFingerprint(atom), atom);
          }
          currentData.memories = merged;
          currentData.plotAtoms = [...atomMap.values()];
          const stateMap = new Map((currentData.currentStates || []).map(item => {
            const normalized = foxMemoryNormalizeCurrentState(item);
            return normalized ? [normalized.key, normalized] : null;
          }).filter(Boolean));
          for (const item of Array.isArray(data.currentStates) ? data.currentStates : []) {
            const normalized = foxMemoryNormalizeCurrentState(item);
            if (!normalized) continue;
            const existing = stateMap.get(normalized.key);
            if (!existing || normalized.floorEnd > existing.floorEnd || (normalized.floorEnd === existing.floorEnd && String(normalized.updatedAt || '') > String(existing.updatedAt || ''))) {
              normalized.history = [...(existing?.history || []), ...(normalized.history || [])].slice(-10);
              stateMap.set(normalized.key, normalized);
            } else if (existing) {
              existing.history = [...(existing.history || []), ...(normalized.history || [])].slice(-10);
            }
          }
          currentData.currentStates = [...stateMap.values()];
          for (const [name, rawProfile] of Object.entries(data.characterProfiles || {})) {
            const incoming = foxMemoryNormalizeCharacterProfile(rawProfile, name);
            if (!incoming) continue;
            const existingKey = Object.keys(currentData.characterProfiles || {}).find(key => key.toLowerCase() === incoming.name.toLowerCase());
            if (existingKey && existingKey !== incoming.name) delete currentData.characterProfiles[existingKey];
            const existing = existingKey ? foxMemoryNormalizeCharacterProfile(currentData.characterProfiles[existingKey], existingKey) : null;
            currentData.characterProfiles[incoming.name] = existing
              ? foxMemoryMergeMissing(existing, incoming)
              : incoming;
          }
          foxMemoryApplyRelations(currentData, Array.isArray(data.relationships) ? data.relationships : [], getCurrentLastMessageId());
          foxMemoryRefreshRelationRefs(currentData);
          for (const [name, rawSnapshot] of Object.entries(data.characterSnapshots || {})) {
            const incoming = foxMemoryNormalizeCharacterSnapshot(rawSnapshot, name);
            if (!incoming) continue;
            const existingKey = Object.keys(currentData.characterSnapshots || {}).find(key => key.toLowerCase() === incoming.name.toLowerCase());
            const existing = existingKey ? foxMemoryNormalizeCharacterSnapshot(currentData.characterSnapshots[existingKey], existingKey) : null;
            if (!existing || incoming.updatedAtFloor > existing.updatedAtFloor || (incoming.updatedAtFloor === existing.updatedAtFloor && incoming.updatedAt > existing.updatedAt)) {
              if (existingKey && existingKey !== incoming.name) delete currentData.characterSnapshots[existingKey];
              currentData.characterSnapshots[incoming.name] = incoming;
