          const importedScene = foxMemoryNormalizeSceneSnapshot(data.sceneSnapshot);
          if (importedScene.updatedAtFloor >= Number(currentData.sceneSnapshot?.updatedAtFloor || 0)) currentData.sceneSnapshot = importedScene;
          currentData.checkpoints = { turns: [], chunks: [] };
          state.foxMemoryBranchEpoch++;
          state.foxMemoryPendingBranchCheckpoint = null;
          if (!saveFoxMemory(currentData)) throw new Error('导入数据写入失败');
          foxMemoryV2Log('导入完成', `memories=${merged.length} atoms=${currentData.plotAtoms.length} states=${currentData.currentStates.length}`);
          if (foxMemoryConfig.injectToPreset) foxMemorySyncToPreset();
