      const cur = panel.querySelector('.fm-pane.active');
      if (cur && cur.dataset.pane === tabKey) return;
      fmTabSwitching = true;
      panel.querySelectorAll('.fm-mitem, .fm-dock-item').forEach(x => x.classList.remove('cur'));
      panel.querySelectorAll(`.fm-mitem[data-tab="${tabKey}"], .fm-dock-item[data-tab="${tabKey}"]`).forEach(x => x.classList.add('cur'));
