  function foxMemoryNormalizeTextProtocolLabel(label) {
    const raw = String(label || '')
      .replace(/^[#\s]+/, '')
      .trim()
      .replace(/[：:]\s*$/, '')
      .trim();
    if (!raw) return '';
    const upper = raw.toUpperCase().replace(/[\s\-]+/g, '_');
    return FOX_MEMORY_TP_LABEL_MAP[raw] || FOX_MEMORY_TP_LABEL_MAP[upper] || '';
  }

  function foxMemoryReadTextProtocolTag(line) {
    const m = String(line || '').match(/^[ \t]*#{1,6}[ \t]*([^#\r\n]+?)[ \t]*$/);
    return m ? foxMemoryNormalizeTextProtocolLabel(m[1]) : '';
  }

  function foxMemoryStripTextProtocolFence(text) {
    const raw = String(text || '').trim();
    const lines = raw.replace(/\r\n?/g, '\n').split('\n');
    if (lines.length >= 2 && /^\s*```[^\n]*$/.test(lines[0]) && /^\s*```\s*$/.test(lines[lines.length - 1])) {
      return lines.slice(1, -1).join('\n');
    }
    return raw;
  }

  function foxMemoryExtractTextProtocolBlocks(fullText, beginNorm, endNorm) {
    const lines = foxMemoryStripTextProtocolFence(fullText).replace(/\r\n?/g, '\n').split('\n');
    const blocks = [];
    let collecting = false;
    let depth = 0;
    let buf = [];

    for (const line of lines) {
      const norm = foxMemoryReadTextProtocolTag(line);

      if (norm === beginNorm) {
        if (collecting) {
          depth++;
          buf.push(line);
        } else {
          collecting = true;
          depth = 1;
          buf = [];
        }
        continue;
      }

      if (collecting && norm === endNorm) {
        depth--;
        if (depth <= 0) {
          const block = buf.join('\n').trim();
          if (block) blocks.push(block);
          collecting = false;
          depth = 0;
          buf = [];
        } else {
          buf.push(line);
        }
        continue;
      }

      if (collecting) buf.push(line);
    }

    if (collecting) {
      foxMemoryV2Log('协议拒绝', `reason=unterminated_block begin=${beginNorm} bufferedLines=${buf.length}`);
    }

    return blocks;
  }

  function foxMemoryExtractTextProtocolField(block, label) {
    const target = foxMemoryNormalizeTextProtocolLabel(label);
    if (!target) return '';

    const lines = String(block || '').replace(/\r\n?/g, '\n').split('\n');
    const buf = [];
    let found = false;

    for (const line of lines) {
      const norm = foxMemoryReadTextProtocolTag(line);
      if (norm === target) {
        if (found) break;
        found = true;
        continue;
      }
      if (found && norm) break;
      if (found) buf.push(line);
    }

    return foxMemoryCleanParsedField(buf.join('\n'));
  }

  function foxMemoryExtractTextProtocolPlotBlocks(fullText) {
    return foxMemoryExtractTextProtocolBlocks(fullText, 'plot_begin', 'plot_end')
      .filter(x => foxMemoryExtractTextProtocolField(x, '内容') && (foxMemoryExtractTextProtocolField(x, '板块') || foxMemoryExtractTextProtocolField(x, '范围起点')));
  }

  function foxMemoryExtractTextProtocolAtomBlocks(fullText) {
    return foxMemoryExtractTextProtocolBlocks(fullText, 'atom_begin', 'atom_end');
  }

  function foxMemoryExtractTextProtocolStateBlocks(fullText) {
