  // ==================== 认知档案协议解析 ====================
  // 解析「关系」块：跨角色关系网更新
  function foxMemoryParseRelationBlocks(fullText, floorFallback = 0) {
    const blocks = foxMemoryExtractTextProtocolBlocks(fullText, 'relation_begin', 'relation_end');
    const results = [];
    for (const block of blocks) {
      const rel = foxMemoryNormalizeRelationship({
        a: foxMemoryExtractField(block, '角色A'),
        b: foxMemoryExtractField(block, '角色B'),
        type: foxMemoryExtractField(block, '关系类型'),
        summary: foxMemoryExtractField(block, '关系概述'),
        aView: foxMemoryExtractField(block, 'A看法'),
        bView: foxMemoryExtractField(block, 'B看法'),
        importance: foxMemoryExtractField(block, '重要度'),
        updatedAtFloor: floorFallback,
      });
      if (rel && foxMemoryIsPlausibleCharacterName(rel.a) && foxMemoryIsPlausibleCharacterName(rel.b)) results.push(rel);
    }
    return results;
  }

  // 解析「档案字段」块：facts/traits/cognition/behavior/state 的结构化字段更新
  function foxMemoryParseProfileFieldBlocks(fullText) {
    const blocks = foxMemoryExtractTextProtocolBlocks(fullText, 'field_begin', 'field_end');
    const results = [];
    for (const block of blocks) {
      const character = foxMemoryCanonicalCharacterName(foxMemoryExtractField(block, '角色'));
      const layer = foxMemoryExtractField(block, '层级').trim();
      const field = foxMemoryExtractField(block, '字段').trim();
      if (!foxMemoryIsPlausibleCharacterName(character) || !layer || !field) continue;
      const op = foxMemoryExtractField(block, '操作').trim().toLowerCase();
      results.push({
        character,
        layer,
        field,
        value: foxMemoryExtractField(block, '值'),
        operation: ['set', 'clear', 'add', 'remove'].includes(op) ? op : 'set',
      });
    }
    return results;
  }

  // 🆕 解析「证据」块：从 AI 输出中提取人格证据
  // 块结构：# 证据开始 / # 角色 / # 行为观察 / # 推断特质 / # 变化方向 / # 置信度 / # 因果推理 / # 楼层 / # 证据结束
  function foxMemoryParseEvidenceBlocks(fullText, floorFallback = 0) {
    const blocks = foxMemoryExtractTextProtocolBlocks(fullText, 'evidence_begin', 'evidence_end');
    const results = [];
    for (const block of blocks) {
      const character = foxMemoryCanonicalCharacterName(foxMemoryExtractField(block, '角色'));
      if (!foxMemoryIsPlausibleCharacterName(character)) continue;
      const behavior = foxMemoryExtractField(block, '行为观察');
      if (!behavior || behavior.length > 400) continue;
      const traitRaw = foxMemoryExtractField(block, '推断特质');
      const resolved = foxMemoryResolveTraitKey(traitRaw);
      if (!resolved || resolved.type !== 'score') continue;
      const directionRaw = foxMemoryExtractField(block, '变化方向').trim();
      const direction = FOX_EVIDENCE_DIRECTION.includes(directionRaw) ? directionRaw : '';
      const confidenceRaw = Number(foxMemoryExtractField(block, '置信度'));
      const confidence = Number.isFinite(confidenceRaw) ? Math.max(0, Math.min(1, confidenceRaw)) : 0.5;
      const causalChain = foxMemoryExtractField(block, '因果推理');
      const floorRaw = foxMemoryExtractField(block, '楼层');
      const floor = /^\d+$/.test(String(floorRaw).trim()) ? Number(floorRaw) : floorFallback;
      const evidence = foxMemoryNormalizeEvidence({
        behavior,
        inferredTrait: resolved.key,
        direction,
        confidence,
        causalChain,
        floor,
      });
      if (evidence) results.push({ character, evidence });
    }
    return results;
  }

  // 🆕 应用证据到角色档案：push 到 evidence 数组并递增 pendingCount
  function foxMemoryApplyEvidence(data, evidenceEntries, trustedCharacters = null) {
    let changed = 0;
    for (const entry of evidenceEntries) {
      if (!entry?.character || !entry?.evidence) continue;
      const character = foxMemoryCanonicalCharacterName(entry.character);
      if (!foxMemoryIsPlausibleCharacterName(character)) continue;
      if (trustedCharacters && !trustedCharacters.has(character.toLowerCase())) {
        foxMemoryV2Log('证据拒绝', `reason=unverified_character name=${character}`);
        continue;
      }
      const profile = foxMemoryGetOrCreateProfile(data, character, false);
      if (!profile) continue;
      if (!profile.evolution) profile.evolution = { evidence: [], causalChain: '', pendingCount: 0, lastAdjustedFloor: 0 };
      // 去重：同行为+同特质+同方向不重复添加
      const dup = (profile.evolution.evidence || []).some(ev =>
        ev.behavior === entry.evidence.behavior && ev.inferredTrait === entry.evidence.inferredTrait
      );
      if (dup) continue;
      profile.evolution.evidence.push(entry.evidence);
      if (profile.evolution.evidence.length > FOX_PROFILE_EVIDENCE_MAX) {
        profile.evolution.evidence = profile.evolution.evidence.slice(profile.evolution.evidence.length - FOX_PROFILE_EVIDENCE_MAX);
      }
      profile.evolution.pendingCount = (profile.evolution.pendingCount || 0) + 1;
      changed++;
      foxMemoryV2Log('证据累积', `character=${character} trait=${entry.evidence.inferredTrait} direction=${entry.evidence.direction} confidence=${entry.evidence.confidence} pending=${profile.evolution.pendingCount}`);
    }
    return changed;
  }

  // 🆕 证据消费管线：当 pendingCount >= 阈值时，按置信度加权调整 trait 并消费证据
  const FOX_EVIDENCE_CONSUME_THRESHOLD = 3; // 同一特质方向累积 3 条证据后触发微调
  const FOX_EVIDENCE_MAX_ADJUST = 5;        // 单次最大调整幅度（与现有 ±5 限速一致）
  const FOX_EVIDENCE_LOW_CONFIDENCE = 0.4;  // 低于此平均置信度触发预警

  function foxMemoryProcessEvolution(data, currentFloor = 0) {
    let adjusted = 0;
    const profiles = Object.values(data.characterProfiles || {});
    const warnings = []; // 收集低置信度预警，返回给调用方
    for (const profile of profiles) {
      if (!profile?.evolution?.evidence?.length) continue;
      const ev = profile.evolution;
      foxMemoryV2Log('演化检查', `character=${profile.name} evidence_count=${ev.evidence.length} pendingCount=${ev.pendingCount} lastAdjustedFloor=${ev.lastAdjustedFloor}`);

      // 按 inferredTrait + direction 分组统计
      const groups = {};
      for (const evidence of ev.evidence) {
        const key = `${evidence.inferredTrait}::${evidence.direction}`;
        if (!groups[key]) groups[key] = [];
        groups[key].push(evidence);
      }
      // 打印分组详情
      const groupSummary = Object.entries(groups).map(([k, items]) => `${k}(${items.length}条)`).join(', ');
      foxMemoryV2Log('证据分组', `character=${profile.name} groups={${groupSummary}}`);

      let traitChanged = false;
      const consumedIndices = new Set();
      for (const [groupKey, items] of Object.entries(groups)) {
        const [traitKey, direction] = groupKey.split('::');
        const traitLabel = FOX_TRAIT_SCORE_LABELS[traitKey] || traitKey;

        // ── 分支1：证据数量不足 ──
        if (items.length < FOX_EVIDENCE_CONSUME_THRESHOLD) {
          foxMemoryV2Log('证据不足', `character=${profile.name} trait=${traitLabel} direction=${direction} count=${items.length}/${FOX_EVIDENCE_CONSUME_THRESHOLD} -> 保留待累积`);

          // 低置信度预警：即使证据不足，也检查平均置信度
          const avgConf = items.reduce((s, e) => s + (e.confidence || 0.5), 0) / items.length;
          if (avgConf < FOX_EVIDENCE_LOW_CONFIDENCE && items.length >= 1) {
            const warnMsg = `${profile.name} 的 ${traitLabel}(${direction}) 有 ${items.length} 条证据但平均置信度仅 ${avgConf.toFixed(2)}（低于${FOX_EVIDENCE_LOW_CONFIDENCE}），建议观察更多行为后再判断`;
            foxMemoryV2Log('低置信度预警', warnMsg);
            warnings.push({ character: profile.name, trait: traitKey, direction, count: items.length, avgConfidence: avgConf, message: warnMsg });
          }
          continue;
        }

        // ── 分支2：特质键不合法 ──
        if (!traitKey || !FOX_TRAIT_SCORE_KEYS.includes(traitKey)) {
          foxMemoryV2Log('特质跳过', `character=${profile.name} reason=invalid_trait_key traitKey=${traitKey}`);
          continue;
        }

        // ── 分支3：方向为"稳定"不触发调整 ──
        if (direction !== '升高' && direction !== '降低') {
          foxMemoryV2Log('方向跳过', `character=${profile.name} trait=${traitLabel} direction=${direction} -> 仅"升高/降低"触发微调`);
          continue;
        }

        // ── 分支4：无基准分数 ──
        const oldScore = profile.traits?.scores?.[traitKey];
        if (typeof oldScore !== 'number') {
          foxMemoryV2Log('基准缺失', `character=${profile.name} trait=${traitLabel} -> 无现有评分，跳过（需先通过档案字段块初始化）`);
          continue;
        }

        // ── 核心计算：置信度加权调整 ──
        const avgConfidence = items.reduce((sum, e) => sum + (e.confidence || 0.5), 0) / items.length;
        const sign = direction === '升高' ? 1 : -1;
        const magnitude = Math.round(avgConfidence * FOX_EVIDENCE_MAX_ADJUST);

        foxMemoryV2Log('演化计算', `character=${profile.name} trait=${traitLabel} direction=${direction} oldScore=${oldScore} evidence=${items.length} avgConf=${avgConfidence.toFixed(3)} sign=${sign} magnitude=${magnitude}`);

        // ── 分支5：调整幅度为0 ──
        if (magnitude === 0) {
          foxMemoryV2Log('幅度为零', `character=${profile.name} trait=${traitLabel} avgConf=${avgConfidence.toFixed(3)} -> magnitude=0, 跳过`);
          continue;
        }

        const newScore = Math.max(0, Math.min(100, oldScore + sign * magnitude));

        // ── 分支6：分数无变化（已到边界）──
        if (newScore === oldScore) {
          foxMemoryV2Log('分数未变', `character=${profile.name} trait=${traitLabel} oldScore=${oldScore} newScore=${newScore} -> 已到边界(0或100)，跳过`);
          continue;
        }

        // ── 应用调整 ──
        profile.traits.scores[traitKey] = newScore;
        traitChanged = true;
        adjusted++;
        foxMemoryV2Log('演化应用', `character=${profile.name} trait=${traitLabel} ${oldScore}->${newScore} (Δ${sign * magnitude}) evidence=${items.length} avgConf=${avgConfidence.toFixed(3)}`);

        // 追加因果链（非覆盖）
        const causalParts = items.map(e => e.causalChain).filter(Boolean);
        if (causalParts.length) {
          const chainEntry = `[${currentFloor}楼] ${traitLabel}${direction}:${oldScore}->${newScore} | ${causalParts.join('；')}`;
          const existingChain = ev.causalChain || '';
          ev.causalChain = (existingChain + '\n' + chainEntry).slice(0, 1000);
          foxMemoryV2Log('因果链追加', `character=${profile.name} entry=${chainEntry.slice(0, 120)}...`);
        }

        // 标记已消费
        for (const item of items) {
          const idx = ev.evidence.indexOf(item);
          if (idx >= 0) consumedIndices.add(idx);
        }
        foxMemoryV2Log('证据消费', `character=${profile.name} trait=${traitLabel} consumed=${items.length} indices=[${[...consumedIndices].join(',')}]`);
      }

      if (traitChanged) {
        profile.updatedAtFloor = Math.max(profile.updatedAtFloor || 0, currentFloor);
        profile.updatedAt = new Date().toISOString();
        ev.lastAdjustedFloor = currentFloor;
        foxMemoryV2Log('档案更新', `character=${profile.name} updatedAtFloor=${currentFloor} lastAdjustedFloor=${currentFloor}`);
      }

      // 消费已用证据：保留未消费的，重置 pendingCount
      if (consumedIndices.size > 0) {
        const beforeCount = ev.evidence.length;
        ev.evidence = ev.evidence.filter((_, idx) => !consumedIndices.has(idx));
        ev.pendingCount = ev.evidence.length;
        foxMemoryV2Log('证据清理', `character=${profile.name} before=${beforeCount} after=${ev.evidence.length} consumed=${consumedIndices.size} pendingNow=${ev.pendingCount}`);
      } else {
        foxMemoryV2Log('证据保留', `character=${profile.name} -> 无消费, 全部${ev.evidence.length}条证据保留待后续累积`);
      }
    }
    if (adjusted > 0) {
      foxMemoryV2Log('演化完成', `adjusted=${adjusted} profiles=${profiles.length}`);
    } else {
      foxMemoryV2Log('演化无变化', `profiles=${profiles.length} adjusted=0`);
    }
    // 返回调整数和预警信息
    return { adjusted, warnings };
  }

  function foxMemoryExtractField(block, label) {
    const raw = String(block || '');
    const tp = foxMemoryExtractTextProtocolField(raw, label);
    if (tp) return tp;
    const re = new RegExp(`【${label}】\\s*([\\s\\S]*?)(?=\\n【[^】]+】|\\n===|\\n---+|\\n=+\\s*$|$)`);
    const m = raw.match(re);
    return foxMemoryCleanParsedField(m?.[1] || '');
  }

  // 🆕 解析「表格」块：人物表格自定义字段与独立自定义表更新
  // 块结构：# 表格开始 / # 对象 / # 字段 / # 操作(set|add|remove|clear) / # 值 / [# 类型 状态|计数|列表] / # 表格结束
  function foxMemoryParseTableBlocks(fullText) {
    const blocks = foxMemoryExtractTextProtocolBlocks(fullText, 'table_begin', 'table_end');
    const results = [];
    const TYPE_CN_MAP = { '状态': 'state', '计数': 'counter', '列表': 'list' };
    for (const block of blocks) {
      const target = String(foxMemoryExtractField(block, '对象') || '').trim().slice(0, 60);
      const field = String(foxMemoryExtractField(block, '字段') || '').trim().slice(0, 40);
      if (!target || !field) continue;
      const opRaw = foxMemoryExtractField(block, '操作').trim().toLowerCase();
      const typeRaw = foxMemoryExtractField(block, '类型').trim();
      results.push({
        target,
        field,
        type: TYPE_CN_MAP[typeRaw] || (FOX_TABLE_FIELD_TYPES.includes(typeRaw) ? typeRaw : ''),
        value: foxMemoryExtractField(block, '值'),
        operation: ['set', 'add', 'remove', 'clear'].includes(opRaw) ? opRaw : 'set',
      });
    }
    return results;
  }

  function foxMemoryExtractKeywords(block) {
    const kwText = foxMemoryExtractField(block, '关键词');

    if (!kwText) return [];

    return kwText
      .split(/[,，、;；\n\r\t ]+/)
      .map(x => x.trim())
      .filter(Boolean)
      .filter(x => {
        // 过滤明显不是关键词的污染内容
        if (/^=+$/.test(x)) return false;
        if (/^任务[一二三四五六七八九十]+[:：]?/.test(x)) return false;
        if (/新增记忆|修正指令|情节摘要|物品\/场景|世界观设定/.test(x)) return false;
        if (x.length > 40) return false;
        return true;
      });
  }

  function foxMemoryExtractAllNewMemoryBlocks(fullText) {
    const raw = String(fullText || '');
    const textProtocolBlocks = foxMemoryExtractTextProtocolBlocks(raw, 'memory_begin', 'memory_end')
      .filter(x => foxMemoryExtractField(x, '标题') && foxMemoryExtractField(x, '内容'));
    const isV2Response = /^[ \t]*#{1,6}[ \t]*(?:信息句开始|剧情信息句开始|ATOM_START|ATOM_BEGIN)[ \t]*$/im.test(raw);
    if (textProtocolBlocks.length || isV2Response) return textProtocolBlocks;

    const blocks = [];

    // 直接按每个【类别】条目抓，而不是依赖旧版分区标题的大区间。
    // 这样即使 AI 输出多个新增记忆区，也不会把任务说明吃进去。
    const re = /【类别】[\s\S]*?(?=\n---+|\n【类别】|\n===\s*修正指令\s*===|\n===\s*情节摘要[\s\S]*?===|\n===\s*新增记忆\s*===|$)/g;

    let m;
    while ((m = re.exec(raw)) !== null) {
      const block = String(m[0] || '').trim();

      if (!block) continue;
      if (!/【标题】/.test(block)) continue;
      if (!/【内容】/.test(block)) continue;

      blocks.push(block);
    }

    return blocks;
  }

  function foxMemoryExtractFixBlocks(fullText) {
    const raw = String(fullText || '');
    const textProtocolBlocks = foxMemoryExtractTextProtocolBlocks(raw, 'fix_begin', 'fix_end')
      .filter(x => foxMemoryExtractField(x, '修正类型') && foxMemoryExtractField(x, '目标标题'));
    const isV2Response = /^[ \t]*#{1,6}[ \t]*(?:信息句开始|剧情信息句开始|ATOM_START|ATOM_BEGIN)[ \t]*$/im.test(raw);
    if (textProtocolBlocks.length || isV2Response) return textProtocolBlocks;

    const fixSection = raw.split(/===\s*修正指令\s*===/).pop() || '';

    if (!fixSection || /无需修正/.test(fixSection)) return [];

    const blocks = fixSection
      .split(/---+/)
      .map(x => x.trim())
      .filter(Boolean)
      .filter(x => /【修正类型】/.test(x) && /【目标标题】/.test(x));

    return blocks;
  }

  function foxMemoryHashText(value) {
    const text = String(value || '');
    let hash = 2166136261;
    for (let i = 0; i < text.length; i++) {
      hash ^= text.charCodeAt(i);
      hash = Math.imul(hash, 16777619);
    }
    return (hash >>> 0).toString(36);
  }

  function foxMemoryResolveTargetRange(floorStart, floorEnd, title, targetRanges = []) {
    const targets = Array.isArray(targetRanges) ? targetRanges : [];
    const titleMatch = String(title || '').match(/第\s*(\d+)\s*[-_—~～至到]\s*(\d+)\s*楼/);
    const titleStart = titleMatch ? Number(titleMatch[1]) : NaN;
    const start = Number(floorStart);
    const end = Number(floorEnd);
    const anchor = Number.isFinite(titleStart) ? titleStart : start;
    if (!Number.isFinite(anchor)) return null;

    const target = targets.find(range => range.start === anchor)
      || targets.find(range => anchor >= range.start && anchor <= range.end)
      || targets.find(range => Number.isFinite(start) && Number.isFinite(end) && start <= range.end && end >= range.start);
    return target || null;
  }

  function foxMemoryBuildAtomsFromPlotBlocks(plotBlocks, targetRanges = []) {
    const atoms = [];
    const rejected = [];
    const now = new Date().toISOString();

    (Array.isArray(plotBlocks) ? plotBlocks : []).forEach((block, blockIndex) => {
      const startRaw = foxMemoryExtractField(block, '范围起点');
      const endRaw = foxMemoryExtractField(block, '范围终点');
      const title = foxMemoryExtractField(block, '板块');
      const start = /^\d+$/.test(String(startRaw).trim()) ? Number(startRaw) : NaN;
      const end = /^\d+$/.test(String(endRaw).trim()) ? Number(endRaw) : NaN;
      const target = foxMemoryResolveTargetRange(start, end, title, targetRanges);
      const content = foxMemoryNormalizeSummaryLines(foxMemoryExtractField(block, '内容'));
      const keywords = foxMemoryExtractKeywords(block);

      if (!target || !content) {
        rejected.push({ blockIndex, reason: !target ? 'unresolved_range' : 'empty_summary' });
        foxMemoryV2Log('摘要原子拒绝', `block=${blockIndex} reason=${!target ? 'unresolved_range' : 'empty_summary'} reported=${startRaw || '?'}-${endRaw || '?'}`);
        return;
      }

      if (start !== target.start || end !== target.end) {
        foxMemoryV2Log('范围归一', `source=summary reported=${startRaw || '?'}-${endRaw || '?'} target=${target.start}-${target.end}`);
      }

      const lines = content.split('\n').map(foxMemoryNormalizeAtomText).filter(Boolean);
      lines.forEach((text, lineIndex) => {
        if (text.length < 12 || text.length > 320) {
          rejected.push({ blockIndex, lineIndex, reason: text.length < 12 ? 'too_short' : 'too_long', text });
          foxMemoryV2Log('摘要原子拒绝', `block=${blockIndex} line=${lineIndex} reason=${text.length < 12 ? 'too_short' : 'too_long'} text=${text.slice(0, 100)}`);
          return;
        }
        const fingerprint = foxMemoryAtomFingerprint({ text });
        const localMeta = foxMemoryExtractLocalMetadata(text);
        const lineKeywords = keywords.filter(keyword => text.toLowerCase().includes(String(keyword).toLowerCase()));
        atoms.push({
          id: `${FOX_MEMORY_ATOM_PREFIX}${target.start}_${target.end}_${foxMemoryHashText(fingerprint)}`,
          kind: 'plot_atom',
          text,
          type: '事件',
          entities: localMeta.entities,
          locations: localMeta.locations,
          keywords: foxMemoryNormalizeList(lineKeywords),
          importance: 0.6,
          validity: 'active',
          permanence: 'episodic',
          unresolved: false,
          floorStart: target.start,
          floorEnd: target.end,
          sourceChunkId: target.id,
          eventTime: `第${target.start}-${Math.min(target.end, Number.isFinite(end) ? end : target.end)}楼`,
          source: 'summary_line',
          createdAt: now,
          updatedAt: now,
        });
      });
    });

    foxMemoryV2Log('摘要原子化', `blocks=${plotBlocks?.length || 0} atoms=${atoms.length} rejected=${rejected.length}`);
    return { atoms, rejected };
  }

  function foxMemoryParsePlotAtoms(fullText, targetRanges = []) {
    const blocks = foxMemoryExtractTextProtocolAtomBlocks(fullText);
    const accepted = [];
    const rejected = [];
    const seen = new Set();
    const targets = Array.isArray(targetRanges) ? targetRanges : [];

    foxMemoryV2Log('协议解析', `atomBlocks=${blocks.length} targetRanges=${targets.length}`);

    blocks.forEach((block, index) => {
      const rawText = foxMemoryExtractField(block, '信息句');
      const text = foxMemoryNormalizeAtomText(rawText);
      const startRaw = foxMemoryExtractField(block, '范围起点');
      const endRaw = foxMemoryExtractField(block, '范围终点');
      const reportedStart = /^\d+$/.test(String(startRaw).trim()) ? Number(startRaw) : NaN;
      const reportedEnd = /^\d+$/.test(String(endRaw).trim()) ? Number(endRaw) : NaN;
      const target = foxMemoryResolveTargetRange(reportedStart, reportedEnd, '', targets);
      const floorStart = target?.start ?? reportedStart;
      const floorEnd = target?.end ?? reportedEnd;
      const entities = foxMemoryNormalizeList(foxMemoryExtractField(block, '相关实体'));
      const locations = foxMemoryNormalizeList(foxMemoryExtractField(block, '地点'));
      const keywords = foxMemoryExtractKeywords(block);
      const localMeta = foxMemoryExtractLocalMetadata(text);
      const type = foxMemoryExtractField(block, '信息类型') || '事件';
      const importanceRaw = Number(foxMemoryExtractField(block, '重要度'));
      const importance = Number.isFinite(importanceRaw) ? Math.max(0, Math.min(1, importanceRaw)) : 0.5;
      const validityRaw = foxMemoryExtractField(block, '有效性').toLowerCase();
      const permanenceRaw = foxMemoryExtractField(block, '持久性').toLowerCase();
      const unresolvedRaw = foxMemoryExtractField(block, '未解决').toLowerCase();
      const validity = /失效|过期|inactive|expired/.test(validityRaw) ? 'inactive' : /存疑|uncertain/.test(validityRaw) ? 'uncertain' : 'active';
      const permanence = /永久|稳定|permanent|semantic/.test(permanenceRaw) ? 'permanent' : /当前|临时|temporary|state/.test(permanenceRaw) ? 'temporary' : 'episodic';
      const unresolved = validity === 'inactive'
        ? false
        : unresolvedRaw
          ? /^(是|true|yes|1|未解决)$/.test(unresolvedRaw)
          : /承诺|任务|伏笔|计划|倒计时/.test(type);
      const fingerprint = foxMemoryAtomFingerprint({ text });
      let reason = '';

      if (!text) reason = 'empty_text';
      else if (text.length < 12) reason = 'too_short';
      else if (text.length > 320) reason = 'too_long';
      else if (/\n/.test(String(rawText || '').trim())) reason = 'multiple_lines';
      else if (!Number.isFinite(floorStart) || !Number.isFinite(floorEnd) || floorStart < 0 || floorEnd < floorStart) reason = 'invalid_floor_range';
      else if (targets.length && !target) reason = 'range_not_requested';
      else if (!entities.length && !locations.length && !keywords.length) reason = 'no_retrieval_metadata';
      else if (!fingerprint) reason = 'empty_fingerprint';
      else if (seen.has(fingerprint)) reason = 'duplicate_in_response';

      if (reason) {
        rejected.push({ index, reason, text, floorStart, floorEnd });
        foxMemoryV2Log('原子拒绝', `index=${index} reason=${reason} floors=${startRaw || '?'}-${endRaw || '?'} text=${text.slice(0, 100)}`);
        return;
      }

      seen.add(fingerprint);
      if (target && (reportedStart !== target.start || reportedEnd !== target.end)) {
        foxMemoryV2Log('范围归一', `source=atom reported=${startRaw || '?'}-${endRaw || '?'} target=${target.start}-${target.end}`);
      }
      const now = new Date().toISOString();
      const atom = {
        id: `${FOX_MEMORY_ATOM_PREFIX}${floorStart}_${floorEnd}_${foxMemoryHashText(fingerprint)}`,
        kind: 'plot_atom',
        text,
        type,
        entities: foxMemoryNormalizeList([...entities, ...localMeta.entities]),
        locations: foxMemoryNormalizeList([...locations, ...localMeta.locations]),
        keywords: foxMemoryNormalizeList([...keywords, ...entities, ...locations]),
        importance,
        validity,
        permanence,
        unresolved,
        floorStart,
        floorEnd,
        sourceChunkId: `${FOX_MEMORY_PLOT_CHUNK_PREFIX}${floorStart}_${floorEnd}`,
        eventTime: `第${floorStart}-${floorEnd}楼`,
        createdAt: now,
        updatedAt: now,
      };
      accepted.push(atom);
      foxMemoryV2Log('原子接受', `id=${atom.id} type=${type} floors=${floorStart}-${floorEnd} entities=${entities.join(',') || '-'} locations=${locations.join(',') || '-'} importance=${importance.toFixed(2)}`);
    });

    foxMemoryV2Log('协议解析完成', `accepted=${accepted.length} rejected=${rejected.length}`);
    return { accepted, rejected, blockCount: blocks.length };
  }

  function foxMemoryParseCurrentStates(fullText, targetRanges = []) {
    const blocks = foxMemoryExtractTextProtocolStateBlocks(fullText);
    const accepted = [];
    const rejected = [];
    const acceptedByKey = new Map();
    const now = new Date().toISOString();
    blocks.forEach((block, index) => {
      const subject = foxMemoryExtractField(block, '主体').trim();
      const field = foxMemoryExtractField(block, '状态字段').trim();
      const value = foxMemoryExtractField(block, '当前值').trim();
      const startText = foxMemoryExtractField(block, '范围起点');
      const endText = foxMemoryExtractField(block, '范围终点');
      const startRaw = /^\d+$/.test(startText) ? Number(startText) : NaN;
      const endRaw = /^\d+$/.test(endText) ? Number(endText) : NaN;
      const target = targetRanges.length ? targetRanges[targetRanges.length - 1] : foxMemoryResolveTargetRange(startRaw, endRaw, '', targetRanges);
      const operationRaw = foxMemoryExtractField(block, '状态操作').toLowerCase();
      const operation = /失效|删除|结束|inactive|remove/.test(operationRaw) ? 'invalidate' : 'set';
      const importanceRaw = Number(foxMemoryExtractField(block, '重要度'));
      const importance = Number.isFinite(importanceRaw) ? Math.max(0, Math.min(1, importanceRaw)) : 0.7;
      const key = `${subject.toLowerCase()}::${field.toLowerCase()}`;
      let reason = '';
      if (!subject) reason = 'empty_subject';
      else if (!field) reason = 'empty_field';
      else if (!value && operation !== 'invalidate') reason = 'empty_value';
      else if (!target) reason = 'range_not_requested';
      else if (subject.length > 80 || field.length > 80 || value.length > 300) reason = 'field_too_long';
      if (reason) {
        rejected.push({ index, reason, subject, field });
        foxMemoryV2Log('状态拒绝', `index=${index} reason=${reason} subject=${subject || '-'} field=${field || '-'}`);
        return;
      }
      const item = {
        id: `state_${foxMemoryHashText(key)}`,
        key,
        subject,
        field,
        value: value || '（状态已结束）',
        status: operation === 'invalidate' ? 'inactive' : 'active',
        operation,
        importance,
        floorStart: target.start,
        floorEnd: target.end,
        sourceChunkId: target.id,
        createdAt: now,
        updatedAt: now,
        history: [],
      };
      const previous = acceptedByKey.get(key);
      if (!previous || item.floorEnd > previous.floorEnd || (item.floorEnd === previous.floorEnd && item.floorStart >= previous.floorStart)) {
        acceptedByKey.set(key, item);
      }
      foxMemoryV2Log('状态接受', `id=${item.id} subject=${subject} field=${field} value=${value.slice(0, 100)} floors=${target.start}-${target.end}`);
    });
    accepted.push(...acceptedByKey.values());
    foxMemoryV2Log('状态解析完成', `blocks=${blocks.length} accepted=${accepted.length} rejected=${rejected.length}`);
    return { accepted, rejected, blockCount: blocks.length };
  }

  function foxMemoryGetHusouContext() {
    try {
      // 推进时结合狐搜，只读取当前角色卡 localStorage。
      // 不再读取 char.personality，避免用户清空 localStorage 后仍然读到旧残留。
      if (typeof husouLoadLocalText === 'function') {
        const localText = husouLoadLocalText();

        if (localText?.trim()) {
          return ssBuildSearchResultsInject(localText.trim());
        }
      }
    } catch (e) {
      log('[狐忆推进] 读取狐搜 localStorage 失败', e);
    }

    return '';
  }

  function foxMemoryExtractText(r) {
    return foxJudgeExtractText(r);
  }

  function foxMemoryIsEmptyResponse(text) {
    return !String(text || '').trim();
  }

  async function foxMemoryCallAnalyzeWithRetry(generateParams, isValid = null) {
    const retryEnabled = foxMemoryConfig.emptyRetryEnabled === true;
    const maxRetries = retryEnabled ? foxMemoryNormalizeRetryCount(foxMemoryConfig.emptyRetryCount) : 0;
    let lastText = '';

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      const r = await ssGenerateRaw('fox_memory_analyze', generateParams, '狐忆分析');
      const text = String(foxMemoryExtractText(r) || '').trim();
      const valid = !foxMemoryIsEmptyResponse(text) && (typeof isValid !== 'function' || isValid(text));
      if (valid) return text;
      lastText = text;

      if (attempt < maxRetries) {
        log(`[狐忆] 分析返回空内容或格式不可解析，第 ${attempt + 1}/${maxRetries} 次重试……`);
        ssTaskToast('fox_memory_analyze', `🦊 狐忆返回为空或格式不可解析，重试 ${attempt + 1}/${maxRetries}…`);
        await new Promise(r => setTimeout(r, 1000));
      }
    }

    return lastText;
  }

  async function foxMemoryAnalyzeNow(options = {}) {
    const automatic = options?.automatic === true;
    if (state.foxAnalyzing || ssIsTaskRunning('fox_memory_analyze')) {
      if (automatic) {
        foxMemoryV2Log('长期分析跳过', 'reason=analysis_already_running');
        return false;
      }
      ssCancelTask('fox_memory_analyze', '狐忆分析');
      return false;
    }

    // 🦊 抢请求加固：手动立即分析前等待其他模块/自动任务/主模型流式输出结束（自动路径已由队列等待）。
    if (!automatic) await ssWaitForManualIdle('fox_memory_analyze');

    const glmi = getFn('getLastMessageId');
    if (!glmi) {
      toast('❌ 缺少 getLastMessageId', 'error');
      return false;
    }

    const latestId = glmi();
    const requestedId = Number(options?.targetMessageId);
    const lastId = Number.isFinite(requestedId)
      ? Math.max(0, Math.min(latestId, Math.floor(requestedId)))
      : latestId;

    if (lastId < 0) {
      toast('⚠️ 无聊天记录', 'warning');
      return false;
    }
    const analysisScope = getFoxMemoryScopeId();
    const analysisEpoch = state.foxMemoryBranchEpoch;
    const analysisMeta = foxMemoryGetMessageBranchMeta(lastId);
    const ensureAnalysisBranchCurrent = stage => {
      const currentMeta = foxMemoryGetMessageBranchMeta(lastId);
      const valid = analysisScope === getFoxMemoryScopeId() && analysisEpoch === state.foxMemoryBranchEpoch
        && analysisMeta.swipeId === currentMeta.swipeId && analysisMeta.fingerprint === currentMeta.fingerprint;
      if (!valid) foxMemoryV2Log('长期分析丢弃', `stage=${stage} floor=${lastId} reason=stale_branch epoch=${analysisEpoch}->${state.foxMemoryBranchEpoch}`);
      return valid;
    };

    state.foxAnalyzing = true;
    ssStartTask('fox_memory_analyze', '狐忆分析');

    let analyzeToast = null;

    try {
      const t = topWindow?.toastr || window.toastr;
      if (t?.info) {
        if (!(automatic && foxMemoryConfig.backgroundSilent)) analyzeToast = ssTaskToast('fox_memory_analyze', '🦊 狐忆分析中……');
      }
    } catch { }


    try {
      // 狐忆和狐构完全一致：固定插入以下上下文
      // char_description → persona_description → world_info_before → world_info_after → chatHistory
      // 插入位置就是【上下文开始】和【上下文结束】中间。
      const fixedContextPrompts = ssBuildFixedContextOrderedPrompts({
        ...foxMemoryConfig,
        targetLastId: lastId,
      });

      const memorySourceFloor = memory => {
        if (Number.isFinite(Number(memory?.floorStart))) return Number(memory.floorStart);
        const match = String(memory?.eventTime || '').match(/第?\s*(\d+)\s*(?:楼|[-_—~～至到])/);
        return match ? Number(match[1]) : null;
      };
      const memories = foxMemoryGetCurrent().filter(memory => {
        const sourceFloor = memorySourceFloor(memory);
        return sourceFloor == null || sourceFloor <= lastId;
      });
      const allPlotRanges = foxMemoryGetPlotChunkRangesUpToMessageId(lastId);

      const plotChunks = foxMemorySortPlotChunks(
        memories.filter(foxMemoryIsPlotChunk)
      );

      // 修复：otherMemories 未定义。
      // 这里只放人物/物品/场景/概念/设定等非剧情摘要记忆。
      const otherMemories = memories.filter(m => m.category !== 'plot');

      const existingPlotIds = new Set(plotChunks.map(m => m.id));

      const currentRangeByLastId = foxMemoryGetPlotChunkRangeByMessageId(lastId);

      let targetPlotRanges = allPlotRanges.filter(r => !existingPlotIds.has(r.id));

      // 关键：
      // 1. 第一次中途开启狐忆时，必须从 0-9、10-19、20-29……一路补齐。
      // 2. 如果前面都已经有了，也必须持续更新当前所在块，例如 30-39。
      // 3. 当前块没满也允许更新，后续聊天继续刷新这个块。
      if (!targetPlotRanges.some(r => r.id === currentRangeByLastId.id)) {
        targetPlotRanges.push(currentRangeByLastId);
      }

      targetPlotRanges = [...new Map(targetPlotRanges.map(r => [r.id, r])).values()]
        .sort((a, b) => a.start - b.start);

      const currentChunkRange = targetPlotRanges[0] || currentRangeByLastId;

      const previousPlotChunks = plotChunks
        .filter(m => {
          const r = foxMemoryParseChunkRange(m);
          return r && r.end < currentChunkRange.start;
        })
        .slice(-3);

      const legacyPlotMemory = memories.find(m => m.id === 'plot_summary');

      const plotIndexText = plotChunks.length
        ? plotChunks.map(m => {
          const r = foxMemoryParseChunkRange(m);
          return `- ${r ? `第${r.start}-${r.end}楼` : (m.eventTime || '')}：${m.title}`;
        }).join('\n')
        : '（暂无剧情摘要分块）';

      const targetRangesText = targetPlotRanges.length
        ? targetPlotRanges.map(r => {
