          content: foxMemoryExtractField(block, '修正内容'),
        })),
      };

      log('[狐忆] 已从标签纯文本解析并包裹为固定结构', parsedPayload);

      if (!plotBlocks.length && !parsedPlotAtoms.length && !newBlocks.length && !fixBlocks.length) {
        throw new Error('模型有返回，但未识别到有效的狐忆协议块，记忆库未写入');
      }

      // 保存
      const data = loadFoxMemory();
      data.memories = memories;
      let profileFieldChanged = 0;
      let profileRelationChanged = 0;
      let tableChanged = 0;
      if (foxMemoryConfig.cognitionArchEnabled || tableOps.length) {
        let profileEvidenceText = '';
        try {
          const getChatMessages = getFn('getChatMessages');
          // 🦊 修复：从全量读取改为限制到 contextFloors，防止 token 爆炸
          const evidenceFloors = Number.isFinite(foxMemoryConfig.contextFloors) && foxMemoryConfig.contextFloors > 0
            ? foxMemoryConfig.contextFloors : 10;
          const evidenceStartId = Math.max(0, lastId - evidenceFloors + 1);
          const chatMessages = getChatMessages ? getChatMessages(`${evidenceStartId}-${lastId}`) : [];
          profileEvidenceText = (Array.isArray(chatMessages) ? chatMessages : []).map(message =>
            String(message?.message ?? message?.mes ?? message?.content ?? '')
          ).join('\n');
        } catch (e) {
          foxMemoryV2Log('档案证据读取失败', e?.message || e);
        }
        if (foxMemoryConfig.cognitionArchEnabled) foxMemoryGetOrCreateProfile(data, protagonistName, true);
        const trustedProfileCharacters = foxMemoryBuildProfileCharacterEvidence(data, profileFields, profileEvidenceText, protagonistName);
        if (foxMemoryConfig.cognitionArchEnabled) {
          const verifiedRelations = profileRelations.filter(relation =>
            trustedProfileCharacters.has(relation.a.toLowerCase()) && trustedProfileCharacters.has(relation.b.toLowerCase())
          );
          profileFieldChanged = foxMemoryApplyProfileFields(data, profileFields, trustedProfileCharacters);
          profileRelationChanged = foxMemoryApplyRelations(data, verifiedRelations, lastId);
          foxMemoryRefreshRelationRefs(data);
          // 🆕 证据驱动演化：解析证据块 -> 累积到档案 -> 消费管线微调 traits
          const evidenceEntries = foxMemoryParseEvidenceBlocks(text, lastId);
          if (evidenceEntries.length) {
            const evidenceChanged = foxMemoryApplyEvidence(data, evidenceEntries, trustedProfileCharacters);
            if (evidenceChanged > 0) {
              const evolutionResult = foxMemoryProcessEvolution(data, lastId);
              if (evolutionResult.adjusted > 0) {
                profileFieldChanged += evolutionResult.adjusted;
                foxMemoryV2Log('演化触发', `evidence_applied=${evidenceChanged} traits_adjusted=${evolutionResult.adjusted}`);
              }
              // 低置信度预警 toast
              if (evolutionResult.warnings?.length) {
                for (const w of evolutionResult.warnings) {
                  try { toast(`⚠️ ${w.message}`, 'warning'); } catch {}
                }
              }
            }
          }
        }
        // 🆕 应用表格块：楼层区间取本次目标范围的并集，用于计数账本
        if (tableOps.length) {
          const tableRange = targetPlotRanges.length
            ? { start: Math.min(...targetPlotRanges.map(r => r.start)), end: Math.max(...targetPlotRanges.map(r => r.end)) }
            : null;
          tableChanged = foxMemoryApplyTableBlocks(data, tableOps, tableRange, trustedProfileCharacters);
        }
      }
      const targetRangeKeys = new Set(targetPlotRanges.map(r => `${r.start}-${r.end}`));
      const retainedAtoms = (Array.isArray(data.plotAtoms) ? data.plotAtoms : []).filter(atom =>
        !targetRangeKeys.has(`${Number(atom.floorStart)}-${Number(atom.floorEnd)}`)
      );
      const previousAtomsById = new Map((Array.isArray(data.plotAtoms) ? data.plotAtoms : []).map(atom => [atom.id, atom]));
      const previousAtomsByFingerprint = new Map((Array.isArray(data.plotAtoms) ? data.plotAtoms : []).map(atom => [foxMemoryAtomFingerprint(atom), atom]).filter(([fingerprint]) => !!fingerprint));
      const retainedByFingerprint = new Map(retainedAtoms.map(atom => [foxMemoryAtomFingerprint(atom), atom]).filter(([fingerprint]) => !!fingerprint));
      for (const resolution of parsedPlotAtoms.filter(atom => atom.validity === 'inactive')) {
        const resolutionEntities = new Set((resolution.entities || []).map(x => x.toLowerCase()));
        const matches = retainedAtoms.filter(oldAtom => oldAtom.unresolved && oldAtom.validity !== 'inactive').map(oldAtom => {
          const sharedEntity = (oldAtom.entities || []).some(entity => resolutionEntities.has(String(entity).toLowerCase()));
          const similarity = foxMemoryTextSimilarity(resolution, oldAtom);
          const textOverlap = foxMemoryAtomFingerprint(resolution).includes(foxMemoryAtomFingerprint(oldAtom).slice(0, 12))
            || foxMemoryAtomFingerprint(oldAtom).includes(foxMemoryAtomFingerprint(resolution).slice(0, 12));
          return { oldAtom, similarity, qualified: sharedEntity && (similarity >= 0.45 || textOverlap) };
        }).filter(item => item.qualified).sort((a, b) => b.similarity - a.similarity);
        const best = matches[0];
        if (best) {
          best.oldAtom.validity = 'inactive';
          best.oldAtom.unresolved = false;
          best.oldAtom.resolvedBy = resolution.id;
          best.oldAtom.updatedAt = new Date().toISOString();
          foxMemoryV2Log('事项解决', `old=${best.oldAtom.id} resolution=${resolution.id} similarity=${best.similarity.toFixed(2)}`);
        }
      }
      const handledRangeKeys = new Set();
      const uniqueParsedAtoms = parsedPlotAtoms.filter(atom => {
        const fingerprint = foxMemoryAtomFingerprint(atom);
        if (!fingerprint) return false;
        const existing = retainedByFingerprint.get(fingerprint);
        if (existing) {
          existing.entities = [...new Set([...(existing.entities || []), ...(atom.entities || [])])];
          existing.locations = [...new Set([...(existing.locations || []), ...(atom.locations || [])])];
          existing.keywords = [...new Set([...(existing.keywords || []), ...(atom.keywords || [])])];
          existing.importance = Math.max(Number(existing.importance) || 0.5, Number(atom.importance) || 0.5);
          existing.updatedAt = new Date().toISOString();
          salienceObserved.atoms.add(String(existing.id));
          handledRangeKeys.add(`${atom.floorStart}-${atom.floorEnd}`);
          foxMemoryV2Log('原子强化', `existing=${existing.id} incoming=${atom.id} text=${atom.text.slice(0, 100)}`);
          return false;
        }
        const previousSameFact = previousAtomsByFingerprint.get(fingerprint);
        if (previousSameFact) {
          atom.id = previousSameFact.id;
          Object.assign(atom, foxMemoryNormalizeSalience(previousSameFact, previousSameFact.floorEnd, 0.55));
        }
        retainedByFingerprint.set(fingerprint, atom);
        handledRangeKeys.add(`${atom.floorStart}-${atom.floorEnd}`);
        salienceObserved.atoms.add(String(atom.id));
        if (!previousSameFact) salienceObserved.newAtoms.add(String(atom.id));
        return true;
      });
      const emptiedRanges = targetPlotRanges.filter(range => !handledRangeKeys.has(`${range.start}-${range.end}`));
      if (emptiedRanges.length) {
        const missing = emptiedRanges.map(range => `${range.start}-${range.end}`).join(',');
        foxMemoryV2Log('保存拒绝', `reason=range_empty_after_dedupe missing=${missing}`);
        throw new Error(`信息句去重后以下范围没有可保存内容：${missing}；为保护旧记忆，本次不写入`);
      }
      data.plotAtoms = [...retainedAtoms, ...uniqueParsedAtoms.map(atom => ({
        ...atom,
        createdAt: previousAtomsById.get(atom.id)?.createdAt || atom.createdAt,
        updatedAt: new Date().toISOString(),
      }))].sort((a, b) => Number(a.floorStart || 0) - Number(b.floorStart || 0));
      const stateMap = new Map((Array.isArray(data.currentStates) ? data.currentStates : []).map(item => {
        const normalized = foxMemoryNormalizeCurrentState(item);
        return normalized ? [normalized.key, normalized] : null;
      }).filter(Boolean));
      let stateChanged = 0;
      for (const nextState of stateParseResult.accepted) {
        const previous = stateMap.get(nextState.key);
        if (previous && Number(previous.floorEnd) > Number(nextState.floorEnd)) {
          foxMemoryV2Log('状态拒绝', `reason=older_than_current key=${nextState.key} incoming=${nextState.floorEnd} current=${previous.floorEnd}`);
          continue;
        }
        if (nextState.operation === 'invalidate' || nextState.status === 'inactive') {
          if (previous) {
            previous.status = 'inactive';
            previous.history = [...(previous.history || []), {
              value: previous.value,
              floorStart: previous.floorStart,
              floorEnd: previous.floorEnd,
              invalidatedAt: nextState.updatedAt,
            }].slice(-10);
            previous.floorStart = nextState.floorStart;
            previous.floorEnd = nextState.floorEnd;
            previous.updatedAt = nextState.updatedAt;
            stateMap.set(nextState.key, previous);
            stateChanged++;
            foxMemoryV2Log('状态失效', `key=${nextState.key} previous=${previous.value.slice(0, 80)}`);
          }
          continue;
        }
        salienceObserved.states.add(String(nextState.id || nextState.key));
        if (previous && previous.value !== nextState.value) {
          Object.assign(nextState, foxMemoryNormalizeSalience(previous, previous.floorEnd, 0.65));
          nextState.history = [
            ...(previous.history || []),
            { value: previous.value, floorStart: previous.floorStart, floorEnd: previous.floorEnd, invalidatedAt: nextState.updatedAt },
          ].slice(-10);
          nextState.createdAt = previous.createdAt || nextState.createdAt;
          stateChanged++;
          foxMemoryV2Log('状态替代', `key=${nextState.key} old=${previous.value.slice(0, 80)} new=${nextState.value.slice(0, 80)}`);
        } else if (previous) {
          nextState.history = previous.history || [];
          nextState.createdAt = previous.createdAt || nextState.createdAt;
          Object.assign(nextState, foxMemoryNormalizeSalience(previous, previous.floorEnd, 0.65));
        } else {
          stateChanged++;
          salienceObserved.newStates.add(String(nextState.id || nextState.key));
        }
        stateMap.set(nextState.key, nextState);
      }
      data.currentStates = [...stateMap.values()].sort((a, b) => a.subject.localeCompare(b.subject, 'zh-CN') || a.field.localeCompare(b.field, 'zh-CN'));
      foxMemoryApplySalienceCycle(data, salienceObserved, lastId);
      data.lastAnalysis = new Date().toISOString();
      if (!ensureAnalysisBranchCurrent('before_save')) return;
      if (!saveFoxMemory(data)) throw new Error('狐忆记忆库写入失败');
      foxMemoryV2Log('保存完成', `atoms=${data.plotAtoms.length} states=${data.currentStates.length} stateChanged=${stateChanged} replacedRanges=${targetRangeKeys.size} parsedAtoms=${parsedPlotAtoms.length} savedAtoms=${uniqueParsedAtoms.length}`);
      if (lastId % FOX_MEMORY_PLOT_CHUNK_SIZE === FOX_MEMORY_PLOT_CHUNK_SIZE - 1) foxMemorySaveCheckpoint(lastId, foxMemoryCoreForCheckpoint(data), 'chunk');
      if (foxMemoryConfig.injectToPreset) foxMemorySyncToPreset();
      try { foxMemoryRenderList(); } catch (e) { foxMemoryV2Log('界面刷新失败', 'target=memory_list', e); }
      try { foxMemoryRenderStats(); } catch (e) { foxMemoryV2Log('界面刷新失败', 'target=memory_stats', e); }
      try { if (typeof xhDockRefresh === 'function') xhDockRefresh(); } catch { }
      foxMemoryV2Log('界面刷新完成', `memories=${data.memories.length} atoms=${data.plotAtoms.length}`);
      if (foxMemoryVectorConfigReady()) {
        foxMemoryIndexAtoms(uniqueParsedAtoms).catch(e => foxMemoryV2Log('向量建索引失败', e?.message || e));
      }

      const parts = [];
      if (plotUpdated) parts.push('剧情摘要分块已更新');
      if (uniqueParsedAtoms.length > 0) parts.push(`信息句 ${uniqueParsedAtoms.length} 条`);
      if (added > 0) parts.push(`新增 ${added} 条`);
      if (fixed > 0) parts.push(`修正 ${fixed} 条`);
      if (profileFieldChanged > 0) parts.push(`档案字段 ${profileFieldChanged} 项`);
      if (profileRelationChanged > 0) parts.push(`关系 ${profileRelationChanged} 项`);
      if (tableChanged > 0) parts.push(`表格 ${tableChanged} 项`);
      // 🆕 证据演化摘要
      let totalEvidence = 0;
      let totalPending = 0;
      let totalAdjusted = 0;
      for (const p of Object.values(data.characterProfiles || {})) {
        totalEvidence += (p.evolution?.evidence || []).length;
        totalPending += (p.evolution?.pendingCount || 0);
      }
      if (totalEvidence > 0) parts.push(`证据 ${totalEvidence} 条${totalPending > 0 ? `（待处理 ${totalPending}）` : '（已消费）'}`);
      toast(automatic && foxMemoryConfig.backgroundSilent
        ? `✅ 狐忆后台静默更新完成${parts.length ? `：${parts.join('，')}` : '，无变化'}`
        : (parts.length ? `✅ ${parts.join('，')}` : '✅ 分析完成，无变化'), 'success');
      return true;

    } catch (e) {
      const msg = e?.message || String(e || '未知错误');

      if (/abort|aborted|cancel|取消|中断/i.test(msg)) {
        log('[狐忆] 分析已中断:', e);
        if (!(automatic && foxMemoryConfig.backgroundSilent)) toast('⛔ 狐忆分析已中断', 'warning');
      } else {
        log('[狐忆] 分析失败:', e);
        if (!(automatic && foxMemoryConfig.backgroundSilent)) toast(`❌ 狐忆分析失败：${msg}`, 'error');
      }
      return false;
    } finally {
      state.foxAnalyzing = false;
      ssEndTask('fox_memory_analyze');
      try { if (analyzeToast?.remove) analyzeToast.remove(); } catch { }
    }
  }

  // ============= 🆕 批次 3C 修复 v5：推进自动模式（捕获阶段拦截版）=============

  let foxPushStartHandle = null; // { clickStop, keyStop }
  let foxPushIsProcessing = false;
let foxPushSkipNext = false;
  // 🦊 推进模式打开时，润色->重发产生的 normal 回复不算独立的一层分析周期。
  //    改为"基线 messageId 绑定"：重发前记录当前 lastMessageId 作为基线，
  //    狐忆监听命中 messageId > 基线 的第一条 normal 回复才跳过分析并清空；
  //    不匹配（如中断/swipe/并发产生的旧楼）则不消费，避免误吃。
  let foxPushSuppressAutoAnalyzeAfterBaseline = -1;

  function unregisterFoxPushListener() {
    try {
      foxPushStartHandle?.clickStop?.();
      foxPushStartHandle?.keyStop?.();
    } catch (e) { }
    foxPushStartHandle = null;
    foxPushIsProcessing = false;
    foxPushSkipNext = false;
  }

  function foxMemorySetAutoPushEnabled(enabled) {
    foxMemoryConfig = loadFoxMemoryConfig();
    foxMemoryConfig.autoPush = enabled === true;
    if (foxMemoryConfig.autoPush) {
      foxMemoryConfig.injectCurrentPrompt = false;
      localStorage.setItem(CONFIG.FOX_MEMORY_INJECT_CURRENT_KEY, 'false');
      registerFoxPushListener();
    } else unregisterFoxPushListener();
    saveFoxMemoryConfig();
    return foxMemoryConfig.autoPush;
  }

  function foxMemorySetCurrentPromptEnabled(enabled) {
    foxMemoryConfig = loadFoxMemoryConfig();
    foxMemoryConfig.injectCurrentPrompt = enabled === true;
    if (foxMemoryConfig.injectCurrentPrompt) {
      foxMemoryConfig.autoPush = false;
      unregisterFoxPushListener();
    }
    // 独立 key 是 load/save 的最终准值，必须在保存完整配置之前写入。
    localStorage.setItem(CONFIG.FOX_MEMORY_INJECT_CURRENT_KEY, foxMemoryConfig.injectCurrentPrompt ? 'true' : 'false');
    saveFoxMemoryConfig();
    return foxMemoryConfig.injectCurrentPrompt;
  }

  // 🆕 记忆自动分析：GENERATION_ENDED 监听器
  let foxMemoryAutoHandle = null;
  let foxMemoryAutoListenerEpoch = 0;
  let foxMemorySnapshotHandle = null;
  let foxMemoryBranchStartHandle = null;
  let foxMemoryGenCounter = 0;
  let foxMemoryLastAutoAnalyzeMessageId = null;
  const foxMemoryAutoScheduledReplies = new Set();
  function xhReserveReply(set, key, maxSize = 300) {
    if (!key || set.has(key)) return false;
    set.add(key);
    while (set.size > maxSize) set.delete(set.values().next().value);
    return true;
  }
  function foxMemoryAutoCounterKey() { return `SPreset_FoxMemoryAutoCounter_${encodeURIComponent(getFoxMemoryScopeId())}`; }
  function foxMemoryLoadAutoCounter() { try { const v=JSON.parse(localStorage.getItem(foxMemoryAutoCounterKey())||'{}'); foxMemoryGenCounter=Math.max(0,Number(v.count)||0); foxMemoryLastAutoAnalyzeMessageId=v.lastId == null ? null : String(v.lastId); } catch {} }
  function foxMemorySaveAutoCounter() { try { localStorage.setItem(foxMemoryAutoCounterKey(),JSON.stringify({count:foxMemoryGenCounter,lastId:foxMemoryLastAutoAnalyzeMessageId})); } catch {} }

  function xhGetAssistantMessageText(message) {
    if (!message || message.role !== 'assistant') return { text: '', source: 'none' };
    const swipeId = Math.max(0, Number(message.swipe_id) || 0);
    if (Array.isArray(message.swipes) && typeof message.swipes[swipeId] === 'string' && message.swipes[swipeId].trim()) {
      return { text: message.swipes[swipeId], source: `swipes[${swipeId}]` };
    }
    for (const key of ['message', 'mes', 'content']) {
      if (typeof message[key] === 'string' && message[key].trim()) return { text: message[key], source: key };
      if (Array.isArray(message[key])) {
        const text = message[key].map(block => typeof block === 'string' ? block : String(block?.text || block?.content || '')).join('\n').trim();
        if (text) return { text, source: `${key}[]` };
      }
    }
    return { text: '', source: 'none' };
  }

  function xhResolveAssistantMessage(candidateId) {
    const gcm = getFn('getChatMessages');
    const glmi = getFn('getLastMessageId');
    if (typeof gcm !== 'function') return { id: -1, message: null, source: 'missing_api' };
    const directMessage = candidateId && typeof candidateId === 'object' && candidateId.role ? candidateId : null;
    const numericCandidate = Number(candidateId && typeof candidateId === 'object'
      ? (candidateId.message_id ?? candidateId.messageId ?? candidateId.id)
      : candidateId);
    if (directMessage?.role === 'assistant' && Number.isFinite(numericCandidate)) {
      return { id: numericCandidate, message: directMessage, source: 'event_object' };
    }
    if (Number.isFinite(numericCandidate) && numericCandidate >= 0) {
      try {
        const message = gcm(numericCandidate, { hide_state: 'all', include_swipes: true })?.[0];
        return { id: numericCandidate, message: message?.role === 'assistant' ? message : null, source: message ? 'event_non_assistant' : 'event_pending' };
      } catch { }
      return { id: numericCandidate, message: null, source: 'event_pending' };
    }
    let latest = -1;
    try { latest = typeof glmi === 'function' ? Number(glmi()) : -1; } catch { }
    if (Number.isFinite(latest) && latest >= 0) {
      try {
        const message = gcm(latest, { hide_state: 'all', include_swipes: true })?.[0];
        return { id: latest, message: message?.role === 'assistant' ? message : null, source: 'latest' };
      } catch { }
    }
    return { id: -1, message: null, source: 'none' };
  }

  function foxMemoryGetAssistantVisibleTextForAutoCheck(messageId) {
    try {
      const gcm = getFn('getChatMessages');
      if (!gcm) return '';

      const m = gcm(messageId, {
        hide_state: 'all',
        include_swipes: true,
      })?.[0];

      if (!m || m.role !== 'assistant') return '';

      let text = xhGetAssistantMessageText(m).text.trim();

      if (!text) return '';

      // 合格回复判断只检查主 AI 是否真实输出，不能套用狐忆的 <All_Context> 提取过滤。
      // 也不能整段删除 <think_fox~>，正文可能仍嵌在其中；这里只剥离标签后判断是否有字符。
      text = text
        .replace(/<[^>]+>/g, '')
        .replace(/\s+/g, '')
        .trim();

      return text;
    } catch {
      return '';
    }
  }

  function foxMemoryIsTruncatedMessage(messageId) {
    try {
      const gcm = getFn('getChatMessages');
      if (!gcm) return false;

      const m = gcm(messageId, {
        hide_state: 'all',
        include_swipes: true,
      })?.[0];

      if (!m) return false;

      const raw = JSON.stringify({
        data: m.data || {},
        extra: m.extra || {},
        swipes_data: m.swipes_data || [],
        swipes_info: m.swipes_info || [],
      }).toLowerCase();

      if (raw.includes('"finish_reason":"length"')) return true;
      if (raw.includes('"finishreason":"length"')) return true;
      if (raw.includes('"stop_reason":"max_tokens"')) return true;
      if (raw.includes('"truncated":true')) return true;
      if (raw.includes('"is_truncated":true')) return true;

      return false;
    } catch {
      return false;
    }
  }

  function foxMemoryShouldAutoAnalyze(messageId, type) {
    // 只允许完整主模型回复。reroll/swipe/regenerate 已在生成开始时回滚，
    // 等新分支完整落盘后重新分析；quiet/continue/impersonate 等一律跳过。
    const effType = (type && typeof type === 'string')
      ? type
      : (xhGetLastGenerationType() || null);
    const allowedTypes = new Set(['normal', 'regenerate', 'swipe', 'reroll']);
    if (effType && !allowedTypes.has(String(effType).toLowerCase())) {
      log(`[记忆自动分析] 跳过：非完整主模型回复 type=${effType}${type ? '' : '（来自 GENERATION_STARTED 追踪）'}`);
      return false;
    }

    if (foxMemoryIsTruncatedMessage(messageId)) {
      log('[记忆自动分析] 跳过：检测到截断');
      return false;
    }

    const text = foxMemoryGetAssistantVisibleTextForAutoCheck(messageId);

    if (!text.trim()) {
      const resolved = xhResolveAssistantMessage(messageId);
      const raw = xhGetAssistantMessageText(resolved.message);
      log(`[记忆自动分析] 跳过：AI 回复为空 message_id=${messageId} source=${raw.source} raw_chars=${raw.text.length} role=${resolved.message?.role || 'missing'}`);
      return false;
    }

    return true;
  }

  // MESSAGE_RECEIVED 在部分酒馆版本中会早于流式正文完全落盘。
  // 自动狐忆必须等目标楼层停止变化，否则快照和长期分析会读到半截正文。
  async function foxMemoryWaitForStableAssistantMessage(messageId, options = {}) {
    const expectedScope = options.scope || getFoxMemoryScopeId();
    const expectedEpoch = Number.isFinite(options.epoch) ? options.epoch : state.foxMemoryBranchEpoch;
    const timeoutMs = Math.max(5000, Number(options.timeoutMs) || 120000);
    const stableMs = Math.max(800, Number(options.stableMs) || 1800);
    const pollMs = Math.max(200, Number(options.pollMs) || 400);
    const startedAt = Date.now();
    let stableSince = 0;
    let lastSignature = '';

    while (Date.now() - startedAt < timeoutMs) {
      if (expectedScope !== getFoxMemoryScopeId() || expectedEpoch !== state.foxMemoryBranchEpoch) return null;

      const message = getFn('getChatMessages')?.(Number(messageId), {
        hide_state: 'all',
        include_swipes: true,
      })?.[0];
      const text = message?.role === 'assistant'
        ? foxMemoryGetAssistantVisibleTextForAutoCheck(Number(messageId))
        : '';
      const meta = foxMemoryGetMessageBranchMeta(Number(messageId));
      const signature = text.trim()
        ? `${meta.swipeId}::${meta.fingerprint}::${text.length}`
        : '';

      if (signature && signature === lastSignature) {
        if (!stableSince) stableSince = Date.now();
      } else {
        lastSignature = signature;
        stableSince = signature ? Date.now() : 0;
      }

      if (signature && !state.isGenerating && Date.now() - stableSince >= stableMs) {
        return { message, text, meta };
      }
      await new Promise(resolve => setTimeout(resolve, pollMs));
    }

    foxMemoryV2Log('自动分析跳过', `floor=${messageId} reason=message_not_stable timeout=${timeoutMs}`);
    return null;
  }

  function registerFoxMemoryAutoListener() {
    unregisterFoxMemoryAutoListener();
    foxMemoryLoadAutoCounter();

    const eo = getFn('eventOn');
    const te = getFn('tavern_events') || tavern_events;

    if (typeof eo !== 'function' || !te?.GENERATION_ENDED) {
      log('[记忆自动分析] 注册失败：缺少 GENERATION_ENDED');
      return;
    }

    foxMemoryAutoHandle = eo(te.GENERATION_ENDED, (eventMessageId, eventType) => {
      const mode = foxMemoryConfig.autoMode || 'manual';
      if (mode === 'manual') return;

      const resolved = xhResolveAssistantMessage(eventMessageId);
      const messageId = resolved.id;
      const type = (eventType && typeof eventType === 'string') ? eventType : (xhGetLastGenerationType() || 'normal');
      const eventDiag = ssModuleDiagBegin('狐忆', 'GENERATION_ENDED 自动分析判定', {
        eventMessageId: foxJudgeDiagValue(eventMessageId),
        resolvedMessageId: messageId,
        resolvedFrom: resolved.source,
        eventType: eventType || '',
        trackedType: xhGetLastGenerationType() || '',
        mode,
      });
      if (messageId < 0) return;

      // 🦊 跳过脚本内部生成。需要区分：合法用户操作（normal/swipe/regenerate/reroll）
      // 即使发生在 xhRecentInternalGenerationUntil 窗口内也应放行；其余一律拦截。
      // 必须加入 xhRecentInternalGenerationUntil 宽限期，因为 ssGenerateRaw 的 finally
      // 先执行 xhMarkInternalGeneration(false) 清掉深度计数器，然后 GENERATION_ENDED
      // 才异步触发，导致仅靠 xhCurrentGenerationIsInternal / xhInternalGenerationDepth
      // 无法拦截——这是"删除楼层/编辑楼层 居然会触发自动分析"的真正根因。
      const isInternalGeneration = xhCurrentGenerationIsInternal || xhInternalGenerationDepth > 0 || Date.now() < xhRecentInternalGenerationUntil;
      const isUserGeneration = type && typeof type === 'string'
        && ['normal', 'swipe', 'regenerate', 'reroll'].includes(String(type).toLowerCase());
      if (isInternalGeneration && !isUserGeneration) {
        log(`[记忆自动分析] 跳过：脚本内部生成结束 message_id=${messageId} type=${type}${Date.now() < xhRecentInternalGenerationUntil ? ' (withinRecentUntil)' : ''}`);
        ssModuleDiag(eventDiag, '跳过:内部生成', { messageId, type, isInternalGeneration, isUserGeneration }, 'warn');
        return;
      }

      const receivedMessage = resolved.message;
      if (receivedMessage && receivedMessage.role !== 'assistant') {
        ssModuleDiag(eventDiag, '跳过:非assistant', { messageId, role: receivedMessage?.role || 'missing' }, 'warn');
        log(`[记忆自动分析] 跳过：message_id=${messageId} 不是 assistant 回复`);
        return;
      }

      const snapshotType = type;
      const scheduledEpoch = state.foxMemoryBranchEpoch;
      const scheduledScope = getFoxMemoryScopeId();
      const initialMeta = foxMemoryGetMessageBranchMeta(Number(messageId));
      const replyKey = `${scheduledScope}::${messageId}::${initialMeta.swipeId}::${initialMeta.fingerprint}`;
      if (!xhReserveReply(foxMemoryAutoScheduledReplies, replyKey)) {
        log(`[记忆自动分析] 跳过：同一真实回复已调度 key=${replyKey}`);
        return;
      }

      const runIfCurrentBranch = async stableMeta => {
        const currentMeta = foxMemoryGetMessageBranchMeta(Number(messageId));
        if (scheduledEpoch !== state.foxMemoryBranchEpoch || scheduledScope !== getFoxMemoryScopeId()
          || stableMeta.swipeId !== currentMeta.swipeId || stableMeta.fingerprint !== currentMeta.fingerprint) {
          foxMemoryV2Log('长期分析丢弃', `floor=${messageId} reason=stale_branch epoch=${scheduledEpoch}->${state.foxMemoryBranchEpoch}`);
          return;
        }
        return foxMemoryAnalyzeNow({ targetMessageId: Number(messageId), automatic: true });
      };

      setTimeout(async () => {
        try {
          if (scheduledEpoch !== state.foxMemoryBranchEpoch || scheduledScope !== getFoxMemoryScopeId()) return;
          // 🦊 狐裁×狐忆 互斥：狐裁正在思考则跳过本次长期分析，避免抢输入冲突
          if (ssIsTaskRunning('fox_judge_chain') || foxJudgeInterceptProcessing || foxJudgeRethinkPending) {
            log('[记忆自动分析] 跳过：狐裁正在思考');
            return;
          }
          // 🦊 修复重roll/swipe触发的竞态：旧楼层的 GENERATION_ENDED 可能在新一轮生成
          // 过程中被事件源回放，导致狐忆分析与主线模型并发，弹出不该出现的 toast。
          // state.isGenerating 由宿主在 GENERATION_STARTED 置 true、GENERATION_ENDED 置 false，
          // 若此时仍为 true 说明有另一轮主线生成正在进行，必须跳过本次分析。
          if (state.isGenerating) {
            log('[记忆自动分析] 跳过：主模型正在生成中（可能来自重roll/旧事件回放）');
            ssModuleDiag(eventDiag, '跳过:主模型生成中', { messageId }, 'warn');
            foxMemoryAutoScheduledReplies.delete(replyKey);
            return;
          }
          const stable = await foxMemoryWaitForStableAssistantMessage(messageId, {
            scope: scheduledScope,
            epoch: scheduledEpoch,
          });
          if (!stable) {
            ssModuleDiag(eventDiag, '跳过:消息未稳定', { messageId }, 'warn');
            foxMemoryAutoScheduledReplies.delete(replyKey);
            return;
          }
          if (!foxMemoryShouldAutoAnalyze(messageId, type)) {
            ssModuleDiag(eventDiag, '跳过:回复不合格', { messageId, type, stableTextLength: stable.text.length }, 'warn');
            return;
          }
          ssModuleDiag(eventDiag, '回复合格', {
            messageId,
            type,
            textSource: xhGetAssistantMessageText(stable.message).source,
            visibleTextLength: stable.text.length,
            swipeId: stable.meta.swipeId,
          }, 'info');

          if (mode === 'auto') {
            if (foxMemoryLastAutoAnalyzeMessageId === String(messageId)) {
              log(`[记忆自动分析] 跳过：楼层已成功分析 current=${messageId}`);
              return;
            }
            // auto 模式每条合格回复都分析，计数器对它无意义；
            // 这里清零，避免之后切到 interval 模式时带入脏计数导致首次偏早触发。
            foxMemoryGenCounter = 0;
             xhEnqueueAutoTask(
               `fox_memory_auto_analyze_${messageId}`,
              '狐忆自动分析',
              async () => {
                const committed = await runIfCurrentBranch(stable.meta);
                if (committed) {
                  foxMemoryLastAutoAnalyzeMessageId = String(messageId);
                  foxMemorySaveAutoCounter();
                }
              },
              { dedupe: true }
            );
            return;
          }

          if (mode === 'interval') {
            // 🦊 修复：兜底值与面板默认值保持一致（10），避免配置缺失时按30楼运行
            const interval = Math.max(1, parseInt(foxMemoryConfig.autoInterval) || 10);
            const currentId = String(messageId);
            if (foxMemoryLastAutoAnalyzeMessageId === currentId) {
              log(`[记忆自动分析] 跳过：楼层已计数 current=${currentId}`);
              return;
            }
            // 🦊 修复楼层计算：按真实楼层差计数（user楼也计入），
            // 使"隔N楼"直观对应聊天楼层数，而非"合格AI回复条数"（旧算法实际需要约2N楼才触发）。
            {
              const __lastN = parseInt(foxMemoryLastAutoAnalyzeMessageId);
              const __curN = parseInt(messageId);
              foxMemoryGenCounter += (Number.isFinite(__lastN) && Number.isFinite(__curN) && __curN > __lastN) ? (__curN - __lastN) : 1;
            }
            foxMemoryLastAutoAnalyzeMessageId = currentId;
            foxMemorySaveAutoCounter();

            // 📊 楼层推进诊断日志：打印本楼被认为是主AI回复的楼层内容及前300字
            //    用于排查"隔N楼分析"是否计算到了正确的楼层
            let __fmPreview = '';
            try {
              const __gcm = getFn('getChatMessages');
              if (__gcm) {
                const __m = __gcm(messageId, { hide_state: 'all', include_swipes: true })?.[0];
                if (__m) {
                  const { text } = xhGetAssistantMessageText(__m);
                  __fmPreview = text.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim().slice(0, 300);
                }
              }
            } catch (e) { log('[狐忆·楼层推进] 日志打印失败', e); }
            log(`[狐忆·楼层推进] 检测到主AI回复楼层 message_id=${messageId}，计数=${foxMemoryGenCounter}/${interval}，内容前300字：${__fmPreview}`);

           if (foxMemoryGenCounter >= interval) {
               foxMemoryGenCounter = Math.max(0, foxMemoryGenCounter - interval);
               foxMemorySaveAutoCounter();
               const queued = xhEnqueueAutoTask(
                `fox_memory_auto_analyze_${messageId}`,
               '狐忆自动分析',
               async () => {
                  const committed = await runIfCurrentBranch(stable.meta);
                 if (!committed) foxMemoryV2Log('周期分析未提交', `floor=${messageId}; next_cycle_continues_normally`);
               },
               { dedupe: true }
              );
               if (queued?.queued === false) log('[记忆自动分析] 已有同消息任务，保留计数等待重试');
            }
          }
        } catch (e) {
          log('[记忆自动分析] 检查失败:', e);
        }
      }, 1200);
    });

    log('[记忆自动分析] 已注册 GENERATION_ENDED 监听，仅完整主模型回复（含 reroll/swipe）触发');
  }

