          pass: !li.traits.scores?.extraversion,
          detail: `李四extraversion是否存在: ${li.traits.scores?.extraversion ?? '不存在'}` },
        { name: 'F. 已消费证据被清除（神经质3条应被消费）',
          pass: !zhang.evolution.evidence.some(e => e.inferredTrait === 'neuroticism'),
          detail: `剩余证据中是否还有neuroticism: ${zhang.evolution.evidence.some(e => e.inferredTrait === 'neuroticism')}` },
        { name: 'G. 未消费证据保留（责任感2条+外向性1条+尽责性1条=4条）',
          pass: zhang.evolution.evidence.length === 4,
          detail: `期望4, 实际${zhang.evolution.evidence.length}` },
        { name: 'H. 因果链被追加（非覆盖）',
          pass: zhang.evolution.causalChain?.includes('神经质降低:50->46'),
          detail: `因果链是否包含调整记录: ${zhang.evolution.causalChain?.includes('神经质降低:50->46')}` },
      ];
      let passCount = 0;
      for (const check of checks) {
        console.log(`${check.pass ? '✅' : '❌'} ${check.name}: ${check.detail}`);
        if (check.pass) passCount++;
      }
      console.log(`\n通过: ${passCount}/${checks.length}`);
      delete testEvidencePipeline.__testData; // 清理临时数据
      console.groupEnd();
      console.groupEnd();
      return { result, checks, passCount, total: checks.length };
    } catch (e) {
      console.error('❌ 步骤4 验证失败:', e?.message || e, '\n', e?.stack || '');
      console.groupEnd();
      throw new Error(`步骤4 预期结果验证失败: ${e?.message || e}`);
    }
    } catch (e) {
      console.error('❌ 测试中断:', e?.message || e, '\n', e?.stack || '');
      return { error: e?.message || String(e), stack: e?.stack };
    } finally {
      try { console.groupEnd(); } catch {}
      try { delete testEvidencePipeline.__testData; } catch {}
    }
  }
  // 暴露到全局供控制台调用
  try { topWindow.testEvidencePipeline = testEvidencePipeline; } catch {}

  // 统一狐忆自动分析配置与运行态监听，避免只保存配置但本轮页面未真正生效。
  function foxMemoryApplyAutoMode(mode, interval, enableBackgroundSilent = false) {
    const prevMode = foxMemoryConfig?.autoMode;
    foxMemoryConfig = loadFoxMemoryConfig();
    foxMemoryConfig.autoMode = ['manual', 'auto', 'interval'].includes(mode) ? mode : 'manual';
    if (interval != null) foxMemoryConfig.autoInterval = Math.max(1, parseInt(interval, 10) || 1);
    if (foxMemoryConfig.autoMode !== 'manual' && enableBackgroundSilent) foxMemoryConfig.backgroundSilent = true;
    // 🆕 联动：从 manual 切换到非 manual（打开总开关）时，自动启用隐藏远楼层并应用默认阈值（30楼）
    if (prevMode === 'manual' && foxMemoryConfig.autoMode !== 'manual' && !foxMemoryConfig.hideFarFloorsEnabled) {
      foxMemoryConfig.hideFarFloorsEnabled = true;
      const savedThreshold = parseInt(localStorage.getItem(CONFIG.FOX_MEMORY_HIDE_FAR_FLOORS_THRESHOLD_KEY));
      foxMemoryConfig.hideFarFloorsThreshold = Number.isFinite(savedThreshold) && savedThreshold > 0 ? savedThreshold : 10;
      localStorage.setItem(CONFIG.FOX_MEMORY_HIDE_FAR_FLOORS_KEY, 'true');
      localStorage.setItem(CONFIG.FOX_MEMORY_HIDE_FAR_FLOORS_THRESHOLD_KEY, String(foxMemoryConfig.hideFarFloorsThreshold));
    }
    // 🆕 联动：从非 manual 切换回 manual（关闭总开关）时，自动关闭隐藏远楼层
    if (prevMode !== 'manual' && foxMemoryConfig.autoMode === 'manual' && foxMemoryConfig.hideFarFloorsEnabled) {
      foxMemoryConfig.hideFarFloorsEnabled = false;
      localStorage.setItem(CONFIG.FOX_MEMORY_HIDE_FAR_FLOORS_KEY, 'false');
    }
    saveFoxMemoryConfig();
    // 🆕 联动：打开总开关时，自动开启自动推进
    // 注意必须在 saveFoxMemoryConfig 之后调用：foxMemorySetAutoPushEnabled 内部会重新 load 配置
    if (prevMode === 'manual' && foxMemoryConfig.autoMode !== 'manual' && !foxMemoryConfig.autoPush) {
      foxMemorySetAutoPushEnabled(true);
      try {
        const apCb = topDoc.getElementById('foxmem-autopush-toggle');
        if (apCb) apCb.checked = true;
      } catch {}
    }
    // 🆕 联动：关闭总开关时，自动关闭自动推进
    if (prevMode !== 'manual' && foxMemoryConfig.autoMode === 'manual' && foxMemoryConfig.autoPush) {
      foxMemorySetAutoPushEnabled(false);
      try {
        const apCb = topDoc.getElementById('foxmem-autopush-toggle');
        if (apCb) apCb.checked = false;
      } catch {}
    }
    if (foxMemoryConfig.autoMode === 'manual') unregisterFoxMemoryAutoListener();
    else registerFoxMemoryAutoListener();
    // 🆕 联动生效：异步应用隐藏远楼层到正则脚本
    if (prevMode === 'manual' && foxMemoryConfig.autoMode !== 'manual' && foxMemoryConfig.hideFarFloorsEnabled) {
      foxMemoryApplyHideFarFloors(true, foxMemoryConfig.hideFarFloorsThreshold).catch(e => log('[狐忆] 联动启用隐藏远楼层失败:', e));
      // 🆕 同步更新面板UI（如果面板已打开）
      try {
        const cb = topDoc.getElementById('foxmem-hide-far-floors-toggle');
        const cfgEl = topDoc.getElementById('foxmem-hide-far-floors-config');
        const thrInp = topDoc.getElementById('foxmem-hide-far-floors-threshold');
        if (cb) cb.checked = true;
        if (cfgEl) cfgEl.style.display = 'flex';
        if (thrInp) thrInp.value = foxMemoryConfig.hideFarFloorsThreshold;
      } catch {}
    }
    // 🆕 联动生效：关闭总开关时，关闭隐藏远楼层正则
    if (prevMode !== 'manual' && foxMemoryConfig.autoMode === 'manual') {
      foxMemoryApplyHideFarFloors(false, foxMemoryConfig.hideFarFloorsThreshold || 10).catch(e => log('[狐忆] 联动关闭隐藏远楼层失败:', e));
      // 🆕 同步更新面板UI（如果面板已打开）
      try {
        const cb = topDoc.getElementById('foxmem-hide-far-floors-toggle');
        const cfgEl = topDoc.getElementById('foxmem-hide-far-floors-config');
        if (cb) cb.checked = false;
        if (cfgEl) cfgEl.style.display = 'none';
      } catch {}
    }
    return foxMemoryConfig;
  }

  function registerFoxMemorySnapshotListener() {
    unregisterFoxMemorySnapshotListener();
    const eo = getFn('eventOn');
    const te = getFn('tavern_events') || tavern_events;
    if (typeof eo !== 'function' || !te?.MESSAGE_RECEIVED) {
      foxMemoryV2Log('快照监听失败', 'reason=missing_events');
      return;
    }
    if (te.GENERATION_STARTED) {
      foxMemoryBranchStartHandle = eo(te.GENERATION_STARTED, (type, _option, dryRun) => {
        if (dryRun) return;
        if (!['swipe', 'regenerate', 'reroll'].includes(String(type || '').toLowerCase())) return;
        state.foxMemoryBranchEpoch++;
        if (ssIsTaskRunning('fox_memory_analyze')) ssCancelTask('fox_memory_analyze', '狐忆分支变化', { silent: true });
        try { foxMemoryRollbackForBranchStart(String(type).toLowerCase() === 'reroll' ? 'regenerate' : String(type).toLowerCase()); }
        catch (e) { foxMemoryV2Log('分支回滚失败', `type=${type} reason=${e?.message || e}`, e); }
      });
    }
    foxMemorySnapshotHandle = eo(te.MESSAGE_RECEIVED, (messageId, type) => {
      if (xhIsInternalMessageEvent(type)) return;
      // 狐裁 reroll/swipe 保护窗口：避免在分支切换中保存错误检查点。
      if (foxJudgeRerollSwipeGuard) {
        foxMemoryV2Log('快照更新跳过', `floor=${messageId} reason=foxjudge_reroll_swipe_guard`);
        return;
      }
      foxMemoryConfig = loadFoxMemoryConfig();
      const generationType = String(type || xhGetLastGenerationType() || 'normal').toLowerCase();
      if (!['normal', 'swipe', 'regenerate', 'reroll'].includes(generationType)) return;
      if (!foxMemoryGetAssistantVisibleTextForAutoCheck(messageId)) return;
      if (foxMemoryIsTruncatedMessage(messageId)) {
        foxMemoryV2Log('快照更新跳过', `floor=${messageId} reason=truncated`);
        return;
      }
      const queueEpoch = state.foxMemoryBranchEpoch;
      const queueScope = getFoxMemoryScopeId();
      setTimeout(async () => {
        if (queueEpoch !== state.foxMemoryBranchEpoch || queueScope !== getFoxMemoryScopeId()) return;
        // 狐裁正在思考时跳过检查点，避免记录未稳定分支。
        if (ssIsTaskRunning('fox_judge_chain') || foxJudgeInterceptProcessing || foxJudgeRethinkPending) {
          foxMemoryV2Log('快照更新跳过', `floor=${messageId} reason=foxjudge_thinking`);
          return;
        }
        const stable = await foxMemoryWaitForStableAssistantMessage(messageId, {
          scope: queueScope,
          epoch: queueEpoch,
        });
        if (!stable) return;
        const queueMeta = stable.meta;
        const snapshotReplyKey = `snapshot::${queueScope}::${messageId}::${queueMeta.swipeId}::${queueMeta.fingerprint}::${queueEpoch}`;
        if (!xhReserveReply(foxMemoryAutoScheduledReplies, snapshotReplyKey)) {
          foxMemoryV2Log('快照更新跳过', `floor=${messageId} reason=already_scheduled`);
          return;
        }
        const beforeCore = state.foxMemoryPendingBranchCheckpoint?.core || foxMemoryCoreForCheckpoint();
        const savedCheckpoint = foxMemorySaveCheckpoint(Number(messageId), beforeCore, 'turn');
        if (savedCheckpoint) state.foxMemoryPendingBranchCheckpoint = null;
        else {
          foxMemoryAutoScheduledReplies.delete(snapshotReplyKey);
          foxMemoryV2Log('快照更新跳过', `floor=${messageId} reason=checkpoint_save_failed`);
          return;
        }
      }, 700);
    });
    foxMemoryV2Log('分支监听', '已注册 normal/swipe/regenerate 检查点与分支回滚（不调用角色快照 API）');
  }

  function unregisterFoxMemorySnapshotListener() {
    ssStopEventHandle(foxMemorySnapshotHandle);
    ssStopEventHandle(foxMemoryBranchStartHandle);
    foxMemorySnapshotHandle = null;
    foxMemoryBranchStartHandle = null;
  }

  // 🆕 记忆占位符系统
  let foxMemoryPlaceholders = {};  // { '<memory0000>': '完整记忆文本', ... }

  /**
   * 将记忆列表转为占位符映射 + 占位符列表文本
   */
  function foxMemoryBuildPlaceholders(memories) {
    foxMemoryPlaceholders = {};
    if (!memories.length) return '（当前记忆库为空）';

    const lines = [];
    memories.forEach((m, i) => {
      const tag = `<memory${String(i).padStart(4, '0')}>`;
      const cat = FOX_MEMORY_CATEGORIES.find(c => c.id === m.category) || { label: m.category };
      const fullText = `【${cat.label}】${m.title}${m.eventTime ? `（${m.eventTime}）` : ''}\n${m.content}${m.keywords?.length ? `\n关键词：${m.keywords.join('、')}` : ''}`;
      foxMemoryPlaceholders[tag] = fullText;
      lines.push(`${tag} = ${cat.label}：${m.title}`);
    });

    return lines.join('\n');
  }

  function foxMemoryBuildPushRecallItems(memories, userInput) {
    // ✅ 召回查询窗口跟随面板"召回楼层数"（旧版硬编码 8 楼，面板设置形同虚设）
    const recallWindow = Math.max(1, parseInt(foxMemoryConfig?.recallFloors, 10) || 8);
    const queryText = `${foxMemoryGetRecentTextForPlotRelevance(recallWindow)}\n${String(userInput || '')}`.trim();
    const atoms = foxMemoryRetrievePlotAtoms({
      queryText,
      intentText: userInput,
      profile: 'advance',
      charBudget: 999999,
      maxAtoms: 16,
    });
    const queryLower = queryText.toLowerCase();
    const nonPlotCandidates = foxMemoryRetrieveNonPlotMemories(memories, queryLower);
    const atomCandidates = atoms.map(atom => ({
      id: atom.id,
      category: 'plot',
      title: `剧情信息句｜第${atom.floorStart}-${atom.floorEnd}楼`,
      content: atom.text,
      keywords: atom.keywords || [],
      eventTime: atom.eventTime || `第${atom.floorStart}-${atom.floorEnd}楼`,
      kind: 'plot_atom',
    }));
    const intentInfo = foxMemoryDetectQueryIntent(userInput, 'advance');
    const stateCandidates = foxMemoryGetRelevantCurrentStates(queryText, intentInfo, 10).map(item => ({
      id: item.id,
      category: 'character',
      title: `当前状态｜${item.subject}｜${item.field}`,
      content: item.value,
      keywords: [item.subject, item.field],
      eventTime: `第${item.floorStart}-${item.floorEnd}楼`,
      kind: 'current_state',
    }));
    const budget = 2200;
    let usedChars = 0;
    const stateItems = [];
    for (const item of stateCandidates) {
      const chars = foxMemoryFormatOneMemoryForInject(item).length;
      if (usedChars + chars > budget * 0.45) break;
      stateItems.push(item);
      usedChars += chars;
    }
    const atomItems = [];
    for (const item of atomCandidates) {
      const chars = foxMemoryFormatOneMemoryForInject(item).length;
      if (usedChars + chars > budget) {
        foxMemoryV2Log('候选拒绝', `id=${item.id} target=auto_push reason=final_budget used=${usedChars} next=${chars} budget=${budget}`);
        continue;
      }
      atomItems.push(item);
      usedChars += chars;
    }
    const nonPlot = [];
    for (const mem of nonPlotCandidates) {
      const chars = foxMemoryFormatOneMemoryForInject(mem).length;
      if (usedChars + chars > budget) {
        foxMemoryV2Log('长期记忆拒绝', `id=${mem.id} target=auto_push reason=budget used=${usedChars} next=${chars} budget=${budget}`);
        continue;
      }
      nonPlot.push(mem);
      usedChars += chars;
    }
    const items = [...stateItems, ...atomItems, ...nonPlot];
    foxMemoryV2Log('推进召回', `states=${stateItems.length} atoms=${atomItems.length} nonPlot=${nonPlot.length} total=${items.length} chars=${usedChars} budget=${budget}`);
    return items;
  }

  /**
   * 将 AI 输出中的占位符替换为完整记忆文本
   */
  function foxMemoryReplacePlaceholders(text) {
    if (!text || !Object.keys(foxMemoryPlaceholders).length) return text;
    let result = text;
    for (const [tag, fullText] of Object.entries(foxMemoryPlaceholders)) {
      result = result.replaceAll(tag, fullText);
    }
    return result;
  }

  function foxPushGetBeatBadMemoryText() {
    try {
      const raw = getPromptContentById(CONFIG.BEAT_BAD_ID) || '';
      const inner = ssUnwrapTaggedContent(raw, 'fox_beat_memory');
      return String(inner || '').trim();
    } catch (e) {
      log('[推进注意事项] 读取长期踩坑记录失败', e);
      return '';
    }
  }

  const FOX_PUSH_REFERENCE_REMINDER = `【续写提醒】
以上【回忆】、【原始输入】、【润色后大纲】/【思考方向】和【注意事项】仅供主模型接下来进行正文续写时参考，不是已经发生的剧情。你必须以当前聊天上下文中真实已经发生到的位置为准，从当前剧情进度继续写；参考以上资料安排后续发展，禁止把它们当成已经完成或已经发生过的剧情，禁止直接跳到大纲结尾之后续写。`;

  function foxPushAppendReferenceReminder(text) {
    const raw = String(text || '').trim();
    const cleaned = raw.replace(/\n*【续写提醒】\s*以上【回忆】[\s\S]*$/g, '').trim();
    return `${cleaned}\n\n${FOX_PUSH_REFERENCE_REMINDER}`.trim();
  }

  function foxPushNormalizePolishedOutput(text, originalInput, recalledMemoryText = '') {
    const raw = String(text || '').trim();
    const original = String(originalInput || '');
    const recall = String(recalledMemoryText || '').trim() || '（暂无回忆内容）';

    if (!raw) return '';

    let next = raw;

    const fixedTorture = String(state.foxPushTortureDraft || localStorage.getItem(CONFIG.FOX_PUSH_TORTURE_KEY) || '').trim();

    const normalizeNotice = (notice) => {
      let n = String(notice || '').trim();

      if (!n || n === fixedTorture) {
        if (fixedTorture) {
          n = `需遵守用户本轮固定提醒：${fixedTorture}`;
        } else {
          n = '暂无注意事项';
        }
      }

      n = n.replace(/^\s*[（(]/, '').replace(/[）)]\s*$/, '').trim();

      return `（${n || '暂无注意事项'}）`;
    };

    const hasRecall = /【回忆】/.test(next);
    const hasOriginal = /【原始输入】/.test(next);
    const hasOutline = /【润色后大纲】/.test(next);
    const hasGuide = /【思考方向】/.test(next);
    const hasNotice = /【注意事项】/.test(next);

    const originalSectionPattern = /【原始输入】\s*[\s\S]*?(?=【(?:润色后大纲|思考方向)】)/;
    if (hasRecall && hasOriginal && (hasOutline || hasGuide) && hasNotice && originalSectionPattern.test(next)) {
      next = next
        // 最终回忆由脚本的确定性召回结果覆盖，禁止推进 AI 二次筛选/改写时引入遗漏或幻觉。
        .replace(/【回忆】\s*[\s\S]*?(?=【原始输入】)/, `【回忆】\n${recall}\n\n`)
        .replace(originalSectionPattern, () => `【原始输入】\n${original}\n\n`)
        .replace(/【注意事项】\s*([\s\S]*?)$/g, (_, notice) => {
          return `【注意事项】\n${normalizeNotice(notice)}`;
        })
        .trim();

      return foxPushAppendReferenceReminder(next);
    }

    return foxPushAppendReferenceReminder(`【回忆】
${recall}

【原始输入】
${original || '（暂无原始输入）'}

【润色后大纲】
${next}

【注意事项】
${normalizeNotice('')}`.trim());
  }
  /**
   * 单独调用 API 做润色（带脚本预筛后的记忆全文）
   */

  function foxPushIsAlreadyFoxInput(text) {
    return /^\s*<fox_input>[\s\S]*?<\/fox_input>\s*$/i.test(String(text || ''));
  }

  function foxPushBuildFoxInput(text, originalInput, recalledMemoryText = '') {
    const raw = String(text || '').trim();

    if (!raw) return '';

    // 即使模型自行包了 <fox_input>，也必须拆开并重新规范化，防止绕过脚本对
    // 【原始输入】和【回忆】的确定性覆盖。
    const cleaned = raw
      .replace(/^\s*<fox_input>\s*/i, '')
      .replace(/\s*<\/fox_input>\s*$/i, '')
      .trim();

    const normalized = foxPushNormalizePolishedOutput(cleaned, originalInput, recalledMemoryText);

    if (!normalized.trim()) return '';

    return `<fox_input>
${normalized}
</fox_input>`;
  }

  function foxPushTriggerSend(delay = 0) {
    setTimeout(() => {
      const sendBtn = topDoc.getElementById('send_but');
      if (!sendBtn) {
        foxPushSkipNext = false;
        toast('⚠️ 发送按钮暂不可用，内容已保留在输入框，请重新发送', 'warning');
        return;
      }
      // 只有确实要同步触发 click 时才置位，避免 DOM 重建导致标志残留并漏处理下一次真实发送。
      foxPushSkipNext = true;
      sendBtn.click();
    }, Math.max(0, Number(delay) || 0));
  }


  function foxPushBuildReadonlyInput(userInput) {
    const memories = foxMemoryGetCurrent();
    const recallWindow = Math.max(1, parseInt(foxMemoryConfig?.recallFloors, 10) || 8);
    const queryText = `${foxMemoryGetRecentTextForPlotRelevance(recallWindow)}\n${String(userInput || '')}`.trim();
    const recallItems = foxMemoryBuildPushRecallItems(memories, userInput);
    foxMemoryScheduleRecallReactivation({
      atoms: recallItems.filter(item => item.kind === 'plot_atom').map(item => item.id),
      states: recallItems.filter(item => item.kind === 'current_state').map(item => item.id),
      memories: recallItems.filter(item => item.kind !== 'plot_atom' && item.kind !== 'current_state').map(item => item.id),
    }, userInput);
    const profileText = foxMemoryConfig.cognitionArchEnabled
      ? foxMemoryBuildProfileInjectBody(queryText)
      : '';
    const memoryText = [
      profileText,
      ...recallItems.map(item => foxMemoryFormatOneMemoryForInject(item)),
    ].filter(Boolean).join('\n\n') || '（暂无回忆内容）';
    const userFixedTorture = String(state.foxPushTortureDraft || localStorage.getItem(CONFIG.FOX_PUSH_TORTURE_KEY) || '').trim();
    const pushWorldbook = ssBuildFixedContextOrderedPrompts({ ...ssNormalizeTagFilterSettings(foxMemoryConfig), contextFloors: Math.max(0, Number(foxMemoryConfig.pushContextFloors ?? 10) || 0) })
      .map(item => typeof item === 'object' && item?.content ? item.content : typeof item === 'string' ? `【宿主上下文占位符】${item}` : '').filter(Boolean).join('\n\n');
    const notice = userFixedTorture ? `需遵守用户本轮固定提醒：${userFixedTorture}` : '暂无注意事项';
    foxMemoryV2Log('注入完成', `target=auto_push_readonly chars=${memoryText.length}`);

    return `<fox_input>
【回忆】
${memoryText}

【原始输入】
${String(userInput || '').trim() || '（暂无原始输入）'}

【注意事项】
（${notice}）

【角色卡、世界书与上下文设定】
${pushWorldbook || '（暂无）'}

${FOX_PUSH_REFERENCE_REMINDER}
</fox_input>`;
  }

  function foxMemoryBuildCustomApiRequest(apiConfig) {
    const ca = foxMemoryNormalizeCustomApiConfig(apiConfig);
    const hasProxy = !!ca.proxyPreset;
    const hasDirect = !!(ca.apiurl || ca.key);
    if (!hasProxy && !hasDirect) return null;
    const customApi = { source: ca.source || 'openai' };
    if (hasProxy) customApi.proxy_preset = ca.proxyPreset;
    else {
      if (ca.apiurl) customApi.apiurl = ca.apiurl;
      if (ca.key) customApi.key = ca.key;
    }
    if (ca.model) customApi.model = ca.model;
    const numeric = [['temperature', parseFloat], ['max_tokens', parseInt], ['top_p', parseFloat], ['frequency_penalty', parseFloat], ['presence_penalty', parseFloat]];
    for (const [key, parse] of numeric) {
      const value = ca[key];
      if (value !== '' && value != null && !isNaN(parse(value))) customApi[key] = parse(value);
    }
    return customApi;
  }

  function foxMemoryResolvePushApi() {
    const mode = ['main', 'analysis', 'custom'].includes(foxMemoryConfig.pushApiType)
      ? foxMemoryConfig.pushApiType
      : 'analysis';
    if (mode === 'main') return { customApi: null, extraInject: null, sourceConfig: null };
    if (mode === 'analysis') {
      if (foxMemoryConfig.apiType !== 'custom') return { customApi: null, extraInject: null, sourceConfig: null };
      const sourceConfig = foxMemoryConfig.customApi || {};
      const customApi = foxMemoryBuildCustomApiRequest(sourceConfig);
      return { customApi, extraInject: customApi ? ssBuildExtraInjectFromCustomApi(sourceConfig) : null, sourceConfig };
    }
    const sourceConfig = foxMemoryConfig.pushCustomApi || {};
    const customApi = foxMemoryBuildCustomApiRequest(sourceConfig);
    if (!customApi) throw new Error('狐忆推进自定义 API 未配置，请填写 API 地址或选择代理预设');
    return { customApi, extraInject: ssBuildExtraInjectFromCustomApi(sourceConfig), sourceConfig };
  }

  async function foxPushGenerate(userInput) {
    if (!userInput?.trim()) return null;

    await foxMemoryPrepareVectorSnapshot(userInput, {
      profile: 'advance',
      recallFloors: Math.max(1, parseInt(foxMemoryConfig?.recallFloors, 10) || 8),
    });
    if (!ssIsTaskRunning('fox_push')) {
      const error = new Error('aborted');
      error.__ssUserCancelled = true;
      throw error;
    }

    const pushMode = foxMemoryConfig.pushMode || 'guide';

    if (pushMode === 'readonly') {
      return foxPushBuildReadonlyInput(userInput);
    }

    const memories = foxMemoryGetCurrent();
    const recallItems = foxMemoryBuildPushRecallItems(memories, userInput);
    foxMemoryScheduleRecallReactivation({
      atoms: recallItems.filter(item => item.kind === 'plot_atom').map(item => item.id),
      states: recallItems.filter(item => item.kind === 'current_state').map(item => item.id),
      memories: recallItems.filter(item => item.kind !== 'plot_atom' && item.kind !== 'current_state').map(item => item.id),
    }, userInput);
    const husouText = foxMemoryConfig.combineWithHusou ? foxMemoryGetHusouContext() : '';
    const recallWindow = Math.max(1, parseInt(foxMemoryConfig?.recallFloors, 10) || 8);
    const recallQueryText = `${foxMemoryGetRecentTextForPlotRelevance(recallWindow)}\n${String(userInput || '')}`.trim();
    const profileRecallText = foxMemoryConfig.cognitionArchEnabled
      ? foxMemoryBuildProfileInjectBody(recallQueryText)
      : '';

    // ✅ 记忆召回已由脚本按相关性评分+预算完成筛选，直接给 AI 看全文。
    //    旧版只给"标题索引"让 AI 盲选占位符（一堆同名"剧情信息句｜第30-39楼"根本无法区分），
    //    选中全靠运气，还经常输出畸形占位符导致记忆丢失。
    //    占位符映射仍保留构建：万一模型按旧习惯输出 <memoryNNNN>，输出后兜底替换为全文。
    foxMemoryBuildPlaceholders(recallItems);
    const memoryFullText = [
      profileRecallText,
      ...recallItems.map(item => foxMemoryFormatOneMemoryForInject(item)),
    ].filter(Boolean).join('\n\n');
    const hasRecallContent = !!memoryFullText;
    foxMemoryV2Log('注入准备', `target=auto_push_ai placeholders=${recallItems.length} queryChars=${String(userInput || '').length}`);
    const guideMode = pushMode !== 'polish';
    const planTitle = guideMode ? '【思考方向】' : '【润色后大纲】';
    const planInstruction = guideMode
      ? '（把用户输入整理成给正文 AI 的思考方向。重点写“主模型应如何理解用户意图、角色状态、情绪走向、节奏取向、冲突重心”，不要替用户写死具体事件。允许用“可考虑、倾向于、重点理解为、避免理解成”的表达，让正文保留随机性。）'
      : '（把用户输入润色成剧情推进大纲。只能整理大纲，不许写正文。）';

    const systemPrompt = `你是剧情大纲润色、记忆召回与注意事项整理助手。

你的任务：
把用户原始输入整理成“可发送给主模型的推进指令”。

【强制读取上下文与世界书】
你必须综合角色卡、人物性格、场景、玩家设定、世界书和聊天上下文判断推进方向。世界书内容不是普通参考，而是当前世界规则与角色设定的一部分；不得只根据用户这一句输入推断人物。若世界书、当前上下文与记忆冲突，优先级为当前上下文事实 > 世界书设定 > 狐忆历史记忆 > 用户对未发生事件的暗示。

绝对禁止：
- 禁止续写正文
- 禁止角色扮演
- 禁止写小说正文
- 禁止输出对白
- 禁止把【用户固定拷打输入】原样复制到【注意事项】
- 禁止把【长期踩坑记录】原样复制到【注意事项】
- 禁止在【注意事项】中直接粘贴原素材

你必须严格输出以下四段，顺序固定：

【回忆】
（固定写「（由脚本注入）」；不要复制、筛选或改写记忆。脚本会在输出后把本段替换为已按相关性筛选好的记忆原文。你只需阅读下方【记忆库召回内容】，用它校准思考方向/推进大纲。）

【原始输入】
（原样保留用户输入，不要篡改，不要省略）

${planTitle}
${planInstruction}

【注意事项】
（这里必须由你根据【注意事项原素材】重新整理生成，必须用括号包裹。不是复制原素材。）`;

    // 🦊 狐忆记忆召回（独立成段）：脚本已完成相关性评分与筛选，直接给全文
    const foxMemoryMaterialsPrompt = `===== 记忆数据 =====

【记忆库召回内容】
（以下记忆由脚本按当前剧情相关性自动评分筛选，直接作为参考；若与聊天上下文冲突，以聊天上下文为准。）
${hasRecallContent ? memoryFullText : '（当前记忆库为空）'}${husouText ? `

【狐搜内容】
${husouText}` : ''}`;

    // 🦊 狐构大纲联动：读取当前角色卡大纲，仅作为推进方向参考（不照抄、不超前撰写未发生剧情）
    let foxOutlinePrompt = '';
    try {
      const outlineRaw = typeof outlineLoadLocalRaw === 'function' ? outlineLoadLocalRaw() : '';
      if (outlineRaw && outlineRaw.trim()) {
        foxOutlinePrompt = `===== 狐构大纲（用户撰写） =====
这是用户撰写的剧情大纲。它只作为你整理${guideMode ? '思考方向' : '推进大纲'}的参考依据，不是已经发生的剧情：

- 大纲里列出的事件未必都已发生。你必须先对照上方聊天上下文、角色卡与用户最新输入，判断剧情当前真实推进到了哪一步。
- 参考大纲给出${guideMode ? '思考方向' : '推进大纲'}，但禁止照抄大纲原文，禁止把大纲原话塞进${planTitle}。
- 严禁超前撰写：不得把大纲中尚未发生的事件当成当前时间线已经发生的事去推进，也不得替用户跳到尚未到达的剧情节点。${planTitle}只能覆盖“从当前真实进度往后一小段”的范围。
- 必须以正文最新进度和用户最新输入为准：先确认当前剧情位置，再参考大纲里与之相邻的后续走向，给出贴合当前进度的方向。
- 若大纲与当前上下文冲突，以当前上下文为准，只能温和地把方向引回大纲，不得强行改写已发生剧情。

大纲开始：

${outlineRaw.trim()}`;
      }
    } catch (e) {
      log('[狐忆自动推进] 获取狐构大纲失败', e);
    }

    const userPrompt = `
【用户最新输入】
${userInput}

禁止思考，禁止寒暄，禁止自我介绍，禁止写小说，立刻严格按照四段结构输出：`;

    const gr = getFn('generateRaw');
    if (typeof gr !== 'function') throw new Error('无 generateRaw');

    const { customApi, extraInject } = foxMemoryResolvePushApi();

    // 🦊 注入顺序：角色卡/世界书 → 聊天记录 → 狐忆记忆召回 → 狐构大纲 → 用户输入
    //    聊天记录跟随狐忆面板的标签过滤（默认保留 <content> 正文、剔除思维链/检查块），
    //    不再强制关闭过滤——旧版无过滤会把每楼上万字的思维链一起发出，上下文直接爆炸。
    //    楼层范围用独立的"推进楼层限制"（默认 10 楼），与分析楼层限制互不影响。
    const orderedPrompts = [
      {
        role: 'system',
        content: systemPrompt,
      },
      ...ssBuildFixedContextOrderedPrompts({
        ...ssNormalizeTagFilterSettings(foxMemoryConfig),
        contextFloors: Math.max(0, Number(foxMemoryConfig.pushContextFloors ?? 10) || 0),
      }),
      {
        role: 'system',
        content: foxMemoryMaterialsPrompt,
      },
    ];

    if (foxOutlinePrompt) {
      orderedPrompts.push({
        role: 'system',
        content: foxOutlinePrompt,
      });
    }

    orderedPrompts.push({
      role: 'user',
      content: userPrompt,
    });

    const params = {
      should_silence: true,
      should_stream: false,
      max_chat_history: 0,
      ordered_prompts: orderedPrompts,
    };

    if (customApi) params.custom_api = customApi;
    if (extraInject) params.__ssExtraInject = extraInject;
    if (!ssIsTaskRunning('fox_push')) {
      const error = new Error('aborted');
      error.__ssUserCancelled = true;
      throw error;
    }
    const r = await ssGenerateRaw('fox_push', params, '狐忆自动推进');
    let polished = String(typeof r === 'string' ? r : (r?.content || '')).trim();

    // 将占位符替换为完整记忆文本
    polished = foxMemoryReplacePlaceholders(polished);

    // 防媚user已改为提示词内联注入，不再需要额外API调用或关闭预设条目

    const finalInput = foxPushBuildFoxInput(polished, userInput, memoryFullText);

    if (finalInput && (finalInput.includes('【润色后大纲】') || finalInput.includes('【思考方向】'))) {
      return finalInput;
    }

    return null;
  }
  /**
   * 核心：在 capture 阶段拦截发送按钮 / Enter 键
   * 
   * 流程：
   * 1. 阻止酒馆自己的 handler 执行（stopImmediatePropagation + preventDefault）
   * 2. 异步调用分析 API 润色用户输入
   * 3. 把润色结果写回 textarea
   * 4. 设置跳过标记，触发一次新的 click
   * 5. 新的 click 进入我们的 handler 时被跳过标记放行，酒馆正常处理
   */
  async function foxPushInterceptAndPolish(e, source) {
    if (!foxMemoryConfig?.autoPush) return;

    try { ssMaybeWarnDbFoxMemoryConflict(); } catch {}

    // 已经在处理中：阻止重复发送
    if (foxPushIsProcessing) {
      e.stopImmediatePropagation();
      e.preventDefault();
      toast('⏳ 推进润色中，请稍候…', 'info');
      return;
    }

    // 跳过标记：放行这一次（用于润色完成后重新触发发送）
    if (foxPushSkipNext) {
      foxPushSkipNext = false;
      return;
    }

    const ta = topDoc.getElementById('send_textarea');
    if (!ta) return;

    // 捕获阶段先拦住发送，再等输入组件完成本轮 DOM/框架状态同步。
    // 狐策选项、输入法或受控输入框可能在发送事件前后异步提交 value；过早快照会读到选项刚注入时的旧文本。
    e.stopImmediatePropagation();
    e.preventDefault();
    await new Promise(resolve => {
      const raf = topWindow?.requestAnimationFrame || window.requestAnimationFrame;
      if (typeof raf === 'function') raf(() => resolve());
      else setTimeout(resolve, 0);
    });

    const liveTa = topDoc.getElementById('send_textarea');
    if (!liveTa) return;
    const original = String(liveTa.value || '');
    const normalizedOriginal = original.trim();

    const fixedTortureTa = topDoc.getElementById('foxmem-fixed-torture');
    if (fixedTortureTa) {
      state.foxPushTortureDraft = fixedTortureTa.value || '';
      localStorage.setItem(CONFIG.FOX_PUSH_TORTURE_KEY, state.foxPushTortureDraft);
    } else {
      state.foxPushTortureDraft = localStorage.getItem(CONFIG.FOX_PUSH_TORTURE_KEY) || state.foxPushTortureDraft || '';
    }

    const shouldPassThrough = !normalizedOriginal
      || normalizedOriginal.startsWith('/')
      || foxPushIsAlreadyFoxInput(normalizedOriginal)
      || normalizedOriginal.includes('【润色后大纲】')
      || normalizedOriginal.includes('【思考方向】')
      || normalizedOriginal.includes('【润色后的大纲】');
    if (shouldPassThrough) {
      foxPushTriggerSend(0);
      return;
    }

    foxPushIsProcessing = true;
    ssStartTask('fox_push', '狐忆自动推进');
    try { ssTaskToast('fox_push', '🦊 狐忆推进润色中……'); } catch { }

    try {
      const polished = await foxPushGenerate(original);
      if (!ssIsTaskRunning('fox_push')) {
        const error = new Error('aborted');
        error.__ssUserCancelled = true;
        throw error;
      }

      if (!liveTa.isConnected || String(liveTa.value || '') !== original) {
        foxMemoryV2Log('推进取消', `reason=input_changed source=${source}`);
        toast('⚠️ 检测到处理期间输入已修改，本次不会覆盖或自动发送，请重新点击发送', 'warning');
        return;
      }

      if (polished) {
        liveTa.value = polished;
        liveTa.dispatchEvent(new Event('input', { bubbles: true }));
        log('[推进] 处理完成，准备发送');
      } else {
        liveTa.value = original;
        log('[推进] 未返回有效内容，发送原文');
        toast('⚠️ 推进处理未返回有效内容，发送原文', 'warning');
      }

      try {
        const judgeCfg = foxJudgeReadConfig();
        if (judgeCfg.enabled) {
          // ✅ 进入新一轮前先清空旧思维链缓存，避免上一轮残留被本次主请求误注入
          foxJudgeLastCombined = '';
          foxJudgePendingInject = '';
          log('[狐裁] 开始发送前思维链思考');
          const glmi = getFn('getLastMessageId');
          const gcm = getFn('getChatMessages');
          let userInput = polished || original;
          let lastAssistantText = '';
          if (glmi && gcm) {
            const lastId = glmi();
            if (lastId >= 0) {
              for (let i = lastId; i >= Math.max(0, lastId - 5); i--) {
                const m = gcm(i, { hide_state: 'all', include_swipes: false })?.[0];
                if (!m) continue;
                if (!lastAssistantText && m.role === 'assistant') {
                  lastAssistantText = String(m.message || '').trim();
                  try { lastAssistantText = ssCleanXuanhuInjectedBlocksFromMessage(lastAssistantText); } catch { }
                  lastAssistantText = foxJudgeStripThinkBlock(lastAssistantText);
                }
                if (lastAssistantText) break;
              }
            }
          }
          const result = await foxJudgeRunChain({ userInput, lastAssistantText, diagnosticSource: `autoPush:${source}` });
          foxJudgeDiag('推进链路:狐裁返回', {
            source,
            skipped: result?.skipped ?? null,
            combinedLength: String(result?.combined || '').length,
            phase1Length: String(result?.phase1 || '').length,
            phase2Length: String(result?.phase2 || '').length,
          }, result?.combined ? 'info' : 'warn');
          if (result?.skipped === 'cancelled') {
            liveTa.value = original;
            liveTa.dispatchEvent(new Event('input', { bubbles: true }));
            log('[推进] 用户中断狐裁，本轮停止发送并恢复原始输入');
            return;
          }
          if (result.combined) {
            foxJudgeLastCombined = result.combined;
            foxJudgePendingInject = result.combined;
            log('[狐裁] 思维链完成，已缓存，待主请求注入');
          } else if (result.skipped === 'busy') {
            log('[狐裁] 上一次思维链仍在进行，本次跳过狐裁注入');
          }
        }
      } catch (e) {
        log('[狐裁] 发送前思维链失败，继续发送', e);
      }

      if (!ssIsTaskRunning('fox_push')) {
        liveTa.value = original;
        liveTa.dispatchEvent(new Event('input', { bubbles: true }));
        log('[推进] 用户在发送前中断狐忆推进，本轮停止发送并恢复原始输入');
        return;
      }

      // ✅ 根据 autoSend 设置决定是自动发送还是手动发送。最终主模型回复会在 GENERATION_ENDED 后正常进入狐忆分析。
      if (foxMemoryConfig.autoSend !== false) {
        // 自动发送模式：延迟后点击发送
        foxPushTriggerSend(300);
      } else {
        // 手动发送模式：润色结果已写入 textarea，提示用户手动发送
        // 手动发送同样属于"推进轮"，用户发送后产生的回复（messageId > 基线）跳过本轮计数
        toast('✅ 推进处理完成，请手动点击发送', 'success');
      }

    } catch (err) {
      const msg = err?.message || String(err || '');
      const userCancelled = err?.__ssUserCancelled === true || /abort|aborted|cancel|取消|中断/i.test(msg);
      if (userCancelled) {
        log('[推进] 用户已中断狐忆推进', err);
        liveTa.value = original;
        liveTa.dispatchEvent(new Event('input', { bubbles: true }));
        return;
      }
      log('[推进] 失败:', err);
      toast(`⚠️ 推进失败：${msg}`, 'error');
      // 失败时发送原文
      liveTa.value = original;
      liveTa.dispatchEvent(new Event('input', { bubbles: true }));
      if (foxMemoryConfig.autoSend !== false) {
        foxPushTriggerSend(300);
      } else {
        toast('⚠️ 推进处理失败，原文已填入，请手动发送', 'warning');
      }
    } finally {
      ssEndTask('fox_push');
      setTimeout(() => { foxPushIsProcessing = false; }, 200);
    }
  }

  /**
   * 注册 capture 阶段拦截器
   */
  function registerFoxPushListener() {
    unregisterFoxPushListener();

    const sendBtn = topDoc.getElementById('send_but');
    const ta = topDoc.getElementById('send_textarea');

    let clickStop = null;
    let keyStop = null;

    if (sendBtn) {
      const clickHandler = (e) => foxPushInterceptAndPolish(e, 'click');
      // ✅ 第三个参数 true = capture 阶段，确保在酒馆自己的 handler 之前执行
      sendBtn.addEventListener('click', clickHandler, true);
      clickStop = () => sendBtn.removeEventListener('click', clickHandler, true);
    }

    if (ta) {
      const keyHandler = (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
          // ✨ 总开关：关闭后 Enter 直接放行，让用户正常换行/发送
          if (!ssGetEnterListenEnabled()) return;
          foxPushInterceptAndPolish(e, 'keydown');
        }
      };
      ta.addEventListener('keydown', keyHandler, true);
      keyStop = () => ta.removeEventListener('keydown', keyHandler, true);
    }

    foxPushStartHandle = { clickStop, keyStop };

    if ((!sendBtn || !ta) && !window.__foxPushRetryScheduled) {
      window.__foxPushRetryScheduled = true;
      setTimeout(() => {
        window.__foxPushRetryScheduled = false;
        registerFoxPushListener();
      }, 1500);
    }

    // 🦊 修复：监控 #send_but 被 DOM 重建替换，自动重新注册 capture 监听器
    //    防止切聊天/UI刷新后监听器随旧 DOM 丢失导致"自动推进只触发一次"
    if (!window.__foxPushObserverInstalled) {
      window.__foxPushObserverInstalled = true;
      try {
        const obs = new MutationObserver(() => {
          if (!foxMemoryConfig.autoPush) return;
          if (window.__foxPushRebindScheduled) return;
          window.__foxPushRebindScheduled = true;
          setTimeout(() => {
            window.__foxPushRebindScheduled = false;
            if (foxMemoryConfig.autoPush) registerFoxPushListener();
          }, 300);
        });
        const host = topDoc.getElementById('send_textarea')?.parentElement || topDoc.body;
        // 🦊 性能优化：subtree:true -> false，仅监听直接子节点变化（send_but 被重建）
        obs.observe(host, { childList: true });
      } catch (e) { log('[推进] MutationObserver 安装失败', e); }
    }

    log('[推进] capture 阶段拦截器已注册');
  }

  let foxJudgeInterceptHandle = null;
  let foxJudgeInterceptProcessing = false;
  let foxJudgeInterceptSkipNext = false;
  // 🦊 文档级捕获兜底：仅安装一次，安装后即使元素直接绑定失败也能命中。
  let foxJudgeDocLevelGuardInstalled = false;
  let foxJudgeDocLevelGuardStops = [];

  async function foxJudgeInterceptAndThink(e, source) {
    // 🦊 文档级 + 元素级双绑定的去重保护：同一 event 在 capture 阶段会先后被
    // doc-level 和 element-level 各拿到一次，必须避免双重处理（否则 skip-next
    // 标记会被先到的吃掉，后到的仍然拦截一次，导致死循环）。
    // ⚠️ 注意：只在"确实进入狐裁处理路径"时才打标记，避免在 no-op 路径上
    // 污染事件对象 / 影响其他模块在 capture 阶段的事件代理。
    if (e && e.__foxJudgeHandled) return;
    const cfg = foxJudgeReadConfig();
    if (!cfg.enabled) return;
    if (foxMemoryConfig?.autoPush) return;
    if (e) {
      try { e.__foxJudgeHandled = true; } catch { }
    }
    foxJudgeDiag('发送拦截:命中', {
      source,
      eventType: e?.type || '',
      processing: foxJudgeInterceptProcessing,
      skipNext: foxJudgeInterceptSkipNext,
      foxJudgeTaskRunning: ssIsTaskRunning('fox_judge_chain'),
      allActiveTasks: [...ssActiveTasks.keys()],
      autoPush: !!foxMemoryConfig?.autoPush,
    });

    // ✅ 必须最先检查"自身正在思考"，并显式拦截事件，
    //    否则用户在思考过程中再次点击发送会让酒馆原生 send 直接发出主请求，
    //    出现"思考没结束就跑正文 + 思考完毕又自动重新发送"的循环。
    if (foxJudgeInterceptProcessing) {
      foxJudgeDiag('发送拦截:被processing阻止', { source }, 'warn');
      e.stopImmediatePropagation();
      e.preventDefault();
      toast('⏳ 狐裁思考中，请稍候…', 'info');
      return;
    }

    // 跳过标记：放行（用于思考完成后我们重新触发的发送）
    if (foxJudgeInterceptSkipNext) {
      foxJudgeDiag('发送拦截:skipNext放行主请求', { source });
      foxJudgeInterceptSkipNext = false;
      return;
    }

    // ✅ 关键修复：自己上一轮的 fox_judge_chain 任务还在跑（例如 swipe/reroll 拦截
    //    或前一次发送的思维链还没结束），新一次发送绝不能"让出"原生 send——
    //    必须挡住，否则 SillyTavern 会在 phase2 还没拼完时就发出主请求，
    //    出现"上面思考第二阶段、下面已出正文"的并行错乱。
    if (ssIsTaskRunning('fox_judge_chain')) {
      foxJudgeDiag('发送拦截:已有狐裁任务', { source, task: foxJudgeDiagValue(ssActiveTasks.get('fox_judge_chain')) }, 'warn');
      e.stopImmediatePropagation();
      e.preventDefault();
      toast('⏳ 狐裁思维链未结束，请稍候再发送…', 'info');
      return;
    }

    // ✅ 多开模块修复：其他后台任务在跑时，不再"让出原生发送"（这会导致主请求
    //    无思维链直接发出，用户被迫 reroll 才注入）。改为拦截原生发送后入队，
    //    由 xhEnqueueAutoTask 的 xhWaitForIdleBeforeAuto 等待其他模块结束后再跑思考。
    //    捕获上下文必须在入队前完成，避免队列等待期间聊天已被切换。
    const otherModulesBusy = ssActiveTasks.size > 0 || state.husouIsRunning || state.foxAnalyzing || state.outlineIsCorrecting || state.outlineIsGenerating || state.hushenIsAnalyzing || pwState?.running;
    if (otherModulesBusy) {
      try {
        const reasons = [];
        if (ssActiveTasks.size > 0) reasons.push(`ssActiveTasks=${[...ssActiveTasks.keys()].join(',')}`);
        if (state.husouIsRunning) reasons.push('husouIsRunning');
        if (state.foxAnalyzing) reasons.push('foxAnalyzing');
        if (state.outlineIsCorrecting) reasons.push('outlineIsCorrecting');
        if (state.outlineIsGenerating) reasons.push('outlineIsGenerating');
        if (state.hushenIsAnalyzing) reasons.push('hushenIsAnalyzing');
        if (pwState?.running) reasons.push('pwState.running');
        log('[狐裁] 其他后台任务运行中，本次拦截发送并延迟思考到队列空闲：', reasons.join(' | '));
      } catch { }
    }

    const ta = topDoc.getElementById('send_textarea');
    if (!ta) return;
    const original = String(ta.value || '').trim();
    if (!original) return;
    if (original.startsWith('/')) return;

    e.stopImmediatePropagation();
    e.preventDefault();

    foxJudgeInterceptProcessing = true;

    // ✅ 多开模块修复：上下文必须在入队前捕获，避免队列等待期间聊天/楼层变化。
    //    foxJudgeRunChain 内部会重新构建完整 context，但 userInput / lastAssistantText
    //    是用户点发送那一刻的快照，必须此刻取。
    const glmi = getFn('getLastMessageId');
    const gcm = getFn('getChatMessages');
    let userInput = original;
    let lastAssistantText = '';
    if (glmi && gcm) {
      const lastId = glmi();
      if (lastId >= 0) {
        for (let i = lastId; i >= Math.max(0, lastId - 5); i--) {
          const m = gcm(i, { hide_state: 'all', include_swipes: false })?.[0];
          if (!m) continue;
          if (!lastAssistantText && m.role === 'assistant') {
            lastAssistantText = String(m.message || '').trim();
            try { lastAssistantText = ssCleanXuanhuInjectedBlocksFromMessage(lastAssistantText); } catch { }
            lastAssistantText = foxJudgeStripThinkBlock(lastAssistantText);
          }
          if (lastAssistantText) break;
        }
      }
    }

    // ✅ 入队：xhEnqueueAutoTask 内部会先调用 xhWaitForIdleBeforeAuto 等待
    //    狐忆/平行世界/狐构/狐刻等模块结束，再执行思考。多开模块时不再丢思考。
    xhEnqueueAutoTask('fox_judge_send_thinking', '狐裁发送思考', async () => {
      try {
        log('[狐裁] 独立拦截：开始思维链思考', otherModulesBusy ? '(队列等待后)' : '(立即)');
        // ✅ 进入新一轮前先清空旧思维链缓存，避免上一轮残留被本次主请求误注入
        foxJudgeLastCombined = '';
        foxJudgePendingInject = '';

        const result = await foxJudgeRunChain({ userInput, lastAssistantText, diagnosticSource: `send:${source}` });
        foxJudgeDiag('发送拦截:主链返回', {
          source,
          skipped: result?.skipped ?? null,
          combinedLength: String(result?.combined || '').length,
          phase1Length: String(result?.phase1 || '').length,
          phase2Length: String(result?.phase2 || '').length,
        }, result?.combined ? 'info' : 'warn');
        if (result.combined) {
          foxJudgeLastCombined = result.combined;
          foxJudgePendingInject = result.combined;
          log('[狐裁] 独立拦截：思维链完成，等待主模型输出后注入楼层');
        } else if (result.skipped === 'busy') {
          log('[狐裁] 上一次思维链仍在进行，本次跳过狐裁注入');
        }

        foxJudgeInterceptSkipNext = true;
        foxJudgeDiag('发送拦截:安排重新点击发送', { source, delayMs: 300 });
        setTimeout(() => {
          const sendBtn = topDoc.getElementById('send_but');
          if (sendBtn) sendBtn.click();
        }, 300);
      } catch (err) {
        foxJudgeDiag('发送拦截:外层异常', { source, error: foxJudgeDiagError(err) }, 'error');
        log('[狐裁] 独立拦截失败:', err);
        toast(`⚠️ 狐裁思考失败：${err.message || err}`, 'error');
        foxJudgeInterceptSkipNext = true;
        setTimeout(() => {
          topDoc.getElementById('send_but')?.click();
        }, 300);
      } finally {
        setTimeout(() => { foxJudgeInterceptProcessing = false; }, 200);
      }
    }, { dedupe: true });
  }

  // 🦊 文档级捕获兜底：把狐裁拦截器同时挂在 topDoc 的 click/keydown 上（capture 阶段）。
  //    这是 send_but/send_textarea 直接绑定的"兜底层"——即使原始元素被酒馆替换、
  //    或在模型生成期间 DOM 抖动导致直接绑定失效，文档级监听都不会丢，
  //    每次事件都会重新从 localStorage 读取 cfg.enabled 实时判断是否拦截。
  //    解决用户反馈："狐裁开关打开了但第一次不生效，必须跑一楼或刷新才行"。
  function foxJudgeEnsureDocLevelGuard() {
    if (foxJudgeDocLevelGuardInstalled) return;
    try {
      const docClickHandler = (e) => {
        // 实时读取（不缓存），保证开关一旦切换立即生效，不必等健康检查
        const enabled = localStorage.getItem(FOX_JUDGE_LS_KEYS.enabled) === 'true';
        if (!enabled) return;
        // 命中送出按钮（按钮自身或其内部 DOM 都算）
        const target = e.target;
        if (!target || !target.closest) return;
        if (!target.closest('#send_but')) return;
        foxJudgeInterceptAndThink(e, 'doc-click');
      };
      const docKeyHandler = (e) => {
        if (e.key !== 'Enter' || e.shiftKey) return;
        const enabled = localStorage.getItem(FOX_JUDGE_LS_KEYS.enabled) === 'true';
        if (!enabled) return;
        // 必须发生在 send_textarea 上才拦截，避免误伤其他输入框
        const target = e.target;
        if (!target || !target.closest) return;
        if (!target.closest('#send_textarea')) return;
        if (!ssGetEnterListenEnabled()) return;
        if (foxMemoryConfig?.autoPush) return;
        foxJudgeInterceptAndThink(e, 'doc-keydown');
      };
      topDoc.addEventListener('click', docClickHandler, true);
      topDoc.addEventListener('keydown', docKeyHandler, true);
      foxJudgeDocLevelGuardInstalled = true;
      foxJudgeDocLevelGuardStops = [
        () => { try { topDoc.removeEventListener('click', docClickHandler, true); } catch { } },
        () => { try { topDoc.removeEventListener('keydown', docKeyHandler, true); } catch { } },
      ];
      log('[狐裁] 文档级捕获兜底已安装（click + Enter 都会实时检查开关状态）');
    } catch (e) {
      log('[狐裁] 安装文档级兜底失败', e);
    }
  }

  // 与 foxJudgeEnsureDocLevelGuard 对称的卸载入口：unregister 时把文档级监听一并拆掉。
  function foxJudgeUninstallDocLevelGuard() {
    for (const fn of foxJudgeDocLevelGuardStops) {
      try { fn(); } catch { }
    }
    foxJudgeDocLevelGuardStops = [];
    foxJudgeDocLevelGuardInstalled = false;
  }

  function registerFoxJudgeInterceptListener() {
    // 普通重绑只替换 DOM 监听，不得清空 processing / skipNext。
    // 狐裁内部阶段和正文生成都会触发 GENERATION_ENDED；若重绑时清状态，
    // 已安排的正文放行 click 会被再次拦截，造成重复思考或误报中断。
    unregisterFoxJudgeInterceptListener(false);

    // 🦊 兜底层：无论后续直接绑定成功与否，文档级捕获总是生效。
    foxJudgeEnsureDocLevelGuard();

    const sendBtn = topDoc.getElementById('send_but');
    const ta = topDoc.getElementById('send_textarea');

    let clickStop = null;
    let keyStop = null;

    if (sendBtn) {
      const clickHandler = (e) => foxJudgeInterceptAndThink(e, 'click');
      sendBtn.addEventListener('click', clickHandler, true);
      clickStop = () => sendBtn.removeEventListener('click', clickHandler, true);
    }

    // ✅ 修复：Enter 键也必须走狐裁拦截。
    // 之前只挂 send_but click，导致用户按 Enter 时酒馆原生发送直接发出，
    // 第一阶段秒空、第二阶段根本没思考。
    // 注意：autoPush 开启时，foxPush 已经监听 Enter 并在内部调用 foxJudgeRunChain，
    //       这里需要避免双重监听冲突——只在 autoPush 关闭时才监听 Enter。
    if (ta) {
      const keyHandler = (e) => {
        if (e.key !== 'Enter' || e.shiftKey) return;
        // 总开关：关闭后 Enter 直接放行，让用户正常换行/发送
        if (!ssGetEnterListenEnabled()) return;
        // autoPush 开启时让位给 foxPush 监听器（它会在润色完成后调用狐裁）
        if (foxMemoryConfig?.autoPush) return;
        foxJudgeInterceptAndThink(e, 'keydown');
      };
      ta.addEventListener('keydown', keyHandler, true);
      keyStop = () => ta.removeEventListener('keydown', keyHandler, true);
    }

    // ✅ 把绑定的元素记下来，让健康检查能识别 send_but / send_textarea 是否被酒馆替换
    //    关键修复：只有当真正绑定到了 send_but 或 send_textarea 时才记录 handle；
    //    否则保持 handle = null，让健康检查能通过 handleMissing 分支识别出"初始注册失败"
    //    并自动重挂，避免出现"狐裁开关明明开着却完全不思考"——这是部分用户反馈
    //    "总开关打开却完全不生效"的根因（DOM 还没就绪时初始化跑了一次，
    //    handle 被记成 { sendBtn: null, ta: null }，健康检查因为 handle 不为 null
    //    而永远不会触发 handleMissing 分支重挂）。
    if (sendBtn || ta) {
      foxJudgeInterceptHandle = { clickStop, keyStop, sendBtn: sendBtn || null, ta: ta || null };
    } else {
      foxJudgeInterceptHandle = null;
    }

    // ✅ 修复 retry timer 堆叠：用变量跟踪，cancel 时清掉
    if ((!sendBtn || !ta) && !window.__foxJudgeInterceptRetryTimerId) {
      window.__foxJudgeInterceptRetryTimerId = setTimeout(() => {
        window.__foxJudgeInterceptRetryTimerId = null;
        registerFoxJudgeInterceptListener();
      }, 2000);
    }

    // ✅ 启动周期性健康检查：如果 send_but / send_textarea 被酒馆重建过，
    //    或者从 DOM 上脱离了，就主动重挂监听器。
    //    这是兜底机制——正常情况下 GENERATION_ENDED / CHAT_CHANGED 会先触发重挂，
    //    但有些场景（设备旋转、其他插件操作）不发那两个事件，监听就会悄悄失效，
    //    用户表现就是"狐裁开关明明开着却完全不思考"。
    foxJudgeStartInterceptHealthCheck();

    log('[狐裁] 独立拦截器已注册（click + Enter）');
  }

  // ✅ 拦截器健康检查：每 4 秒确认一次绑定的 send_but / send_textarea / 重抽 / swipe 按钮还在 DOM 里，
  //    一旦发现失效就重挂。timer 只在 cfg.enabled 时跑，关闭/注销时会被清理。
  let foxJudgeInterceptHealthTimer = null;
  function foxJudgeStartInterceptHealthCheck() {
    foxJudgeStopInterceptHealthCheck();
    foxJudgeInterceptHealthTimer = setInterval(() => {
      try {
        // ✅ 健康检查走轻量字段读取，不调用 foxJudgeReadConfig()——
        //    后者会在每次调用时跑 proxyPreset / filterSettings 一次性迁移分支
        //    （含 JSON.parse + 正则 + 偶发 localStorage.setItem），
        //    对一个 4 秒一跑的兜底定时器来说没必要承担那个开销。
        const enabled = localStorage.getItem(FOX_JUDGE_LS_KEYS.enabled) === 'true';
        if (!enabled) {
          // 配置已关闭：直接停掉健康检查，避免空转
          foxJudgeStopInterceptHealthCheck();
          return;
        }

        // ----- send / Enter 拦截器 -----
        const handle = foxJudgeInterceptHandle;
        const liveSend = topDoc.getElementById('send_but');
        const liveTa = topDoc.getElementById('send_textarea');

        // 任一条件触发重挂：
        // (1) 绑定的元素已经不在 DOM 里（被替换/移除）
        // (2) 当前 DOM 上的 send_but / send_textarea 与 handle 记录的不是同一个对象
        // (3) handle 自身丢失（包括初始注册失败时 handle=null，但 DOM 已就绪）
        // (4) handle 部分丢失：handle 存在但其中 sendBtn 或 ta 为 null，而当前 DOM 已有
        //     —— 这是"狐裁开关明明开着却完全不思考"的关键修复：之前 handle 被设成
        //     { sendBtn: null, ta: null }，handleMissing 永远是 false，sendDead/taDead
        //     依赖 `handle.sendBtn &&` 短路，也永远是 false，导致初始注册失败的用户
        //     必须手动开关一次开关才能恢复，部分用户因此完全感知不到狐裁。
        const sendDead = handle?.sendBtn && (!handle.sendBtn.isConnected || handle.sendBtn !== liveSend);
        const taDead = handle?.ta && (!handle.ta.isConnected || handle.ta !== liveTa);
        const handleMissing = !handle && (liveSend || liveTa);
        const handlePartial = !!handle && (
          (!handle.sendBtn && liveSend) ||
          (!handle.ta && liveTa)
        );

        if (sendDead || taDead || handleMissing || handlePartial) {
          log('[狐裁] 健康检查发现 send/Enter 拦截器失效，自动重挂', { sendDead, taDead, handleMissing, handlePartial });
          registerFoxJudgeInterceptListener();
        }

        // ----- swipe / reroll 拦截器 -----
        // 🦊 不再依赖 rethink 开关：不论 swipeRethink / rerollRethink 是否开启，
        //    handler 都要保留绑定，关闭时走"复用 preserved 思维链"分支。
        let swipeRerollNeedsRebind = false;
        {
          const liveRegen = topDoc.getElementById('option_regenerate') || topDoc.getElementById('regenerate');
          const rerollHandleEl = foxJudgeRerollBtnHandle?.el;
          if (liveRegen && (!rerollHandleEl || !rerollHandleEl.isConnected || rerollHandleEl !== liveRegen)) {
            swipeRerollNeedsRebind = true;
          }
        }
        if (!swipeRerollNeedsRebind) {
          const swipeBtns = topDoc.querySelectorAll('.swipe_right, #swipe_right');
          const liveSwipe = swipeBtns.length ? swipeBtns[swipeBtns.length - 1] : null;
          const swipeHandleEl = foxJudgeSwipeBtnHandle?.el;
          if (liveSwipe && (!swipeHandleEl || !swipeHandleEl.isConnected || swipeHandleEl !== liveSwipe)) {
            swipeRerollNeedsRebind = true;
          }
        }
        if (swipeRerollNeedsRebind) {
          log('[狐裁] 健康检查发现 swipe/reroll 拦截器失效，自动重挂');
          foxJudgeRegisterSwipeRerollListeners();
        }
      } catch (e) {
        try { log('[狐裁] 拦截器健康检查异常', e); } catch { }
      }
    }, 4000);
  }
  function foxJudgeStopInterceptHealthCheck() {
    if (foxJudgeInterceptHealthTimer) {
      try { clearInterval(foxJudgeInterceptHealthTimer); } catch { }
      foxJudgeInterceptHealthTimer = null;
    }
  }

  function unregisterFoxJudgeInterceptListener(resetState = false) {
    try { foxJudgeInterceptHandle?.clickStop?.(); } catch { }
    try { foxJudgeInterceptHandle?.keyStop?.(); } catch { }
    foxJudgeInterceptHandle = null;
    if (resetState) {
      foxJudgeInterceptProcessing = false;
      foxJudgeInterceptSkipNext = false;
    }
    // 清掉 pending 的重试定时器，避免连续 GENERATION_ENDED/CHAT_CHANGED 堆叠
    if (window.__foxJudgeInterceptRetryTimerId) {
      try { clearTimeout(window.__foxJudgeInterceptRetryTimerId); } catch { }
      window.__foxJudgeInterceptRetryTimerId = null;
    }
    // 停掉健康检查（toggle off / cleanup 都会走到这里）
    foxJudgeStopInterceptHealthCheck();
  }

  function openHushenPanel() {
