当然，你也可以自己描述你想要的氛围呢……不过，你就算描述了，我们聪明绝顶的AI估计大概率也会有自己的“想法”吧……（笑）`);
      hushenConversationActive = true;
      // 🆕 自动开始对话后保存激活状态
      saveHushenSession();
    } else {
      hushenRenderChat();
    }
  }


  function hushenRecalcModuleIndex() {
    // 根据已有用户消息数量估算当前模块进度
    const userCount = hushenConversation.filter(m => m.role === 'user').length;
    hushenModuleIndex = Math.min(userCount, HUSHEN_ANALYSIS_MODULES.length);
    // 🆕 编辑/回退/重roll 均会触发此处，统一保存会话状态（含进度与对话变化）
    saveHushenSession();
  }

  function hushenEditMessage(index) {
    const msg = hushenConversation[index];
    if (!msg) return;

    const next = topWindow?.prompt
      ? topWindow.prompt(msg.role === 'ai' ? '编辑狐神抚回复：' : '编辑用户回复：', msg.text)
      : prompt(msg.role === 'ai' ? '编辑狐神抚回复：' : '编辑用户回复：', msg.text);

    if (next == null) return;

    // 🆕 编辑前自动快照：保留编辑前的原始内容，避免直接覆盖丢失优质回复
    hushenCreateSnapshot('edit', '编辑：' + (msg.text || '').slice(0, 40));

    msg.text = String(next);
    hushenRecalcModuleIndex();
    hushenRenderChat();
    toast('✅ 已编辑', 'success');
  }

  function hushenRollbackTo(index) {
    const ok = topWindow?.confirm
      ? topWindow.confirm('确定回退到这一步吗？后面的狐析对话会被删除。')
      : confirm('确定回退到这一步吗？');

    if (!ok) return;

    hushenConversation = hushenConversation.slice(0, index + 1);
    hushenRecalcModuleIndex();
    hushenRenderChat();
    toast('↩️ 已回退', 'success');
  }

  async function hushenRerollFrom(index) {
    const msg = hushenConversation[index];
    if (!msg) return;

    let userIndex = index;

    if (msg.role === 'ai') {
      userIndex = -1;
      for (let i = index - 1; i >= 0; i--) {
        if (hushenConversation[i].role === 'user') {
          userIndex = i;
          break;
        }
      }
    }

    if (userIndex < 0 || !hushenConversation[userIndex]) {
      toast('⚠️ 找不到可重roll的用户输入', 'warning');
      return;
    }

    const ok = topWindow?.confirm
      ? topWindow.confirm('确定从这一步重roll吗？这一步之后的内容会被删除哦🦊')
      : confirm('确定从这一步重roll吗？');

    if (!ok) return;

    // 🆕 破坏性操作前自动快照：保留即将被删除的 AI 回复，便于事后回退到这版优质回复
    hushenCreateSnapshot('reroll', '重roll：' + (hushenConversation[index]?.text || '').slice(0, 40));

    const userText = hushenConversation[userIndex].text;

    // 保留到用户消息为止，删除后面的 AI 和后续步骤
    hushenConversation = hushenConversation.slice(0, userIndex + 1);
    hushenRecalcModuleIndex();
    hushenRenderChat();

    await hushenGenerateReplyForExistingUser(userText);
  }

  function hushenBuildSystemPromptForCurrentStep() {
    const isLastModule = hushenModuleIndex >= HUSHEN_ANALYSIS_MODULES.length;

    if (!isLastModule) {
      const mod = HUSHEN_ANALYSIS_MODULES[hushenModuleIndex];
      const done = HUSHEN_ANALYSIS_MODULES.slice(0, hushenModuleIndex).map(m => m.label);
      const s = state.hushenSettings || {};
      const style = s.style || 'detailed';
      const minW = Math.max(10, parseInt(s.minWords) || 100);
      const maxW = Math.max(minW + 10, parseInt(s.maxWords) || 250);

      return `你是狐神抚。以下是你的语言风格：
说话：慵懒软糯妩媚，尾音拖长。爱用“～”“呢”“嘛”“啦”。话不用多，点到为止，偶尔穿插两句吐槽。
动作：歪头、托腮、伸懒腰、眯眼。耳朵抖，尾巴晃，节奏越慢掌控越强。
态度：不解释，不争辩，不认真表态。被戳穿就眯眼笑，不承认也不否认。

你的任务：引导用户完成写作偏好分析。你正在和用户对话，一个模块一个模块地问清楚。

当前正在分析的模块：【${mod.label}】
提示问题：${mod.hint}

已经分析过的模块：${done.length ? done.join('、') : '暂无'}

你需要：
1. 根据用户刚才的回复，进行分析总结（${style === 'concise' ? '简洁，1-3个要点' : '详细，2-5个要点，展开说明'}，${minW}-${maxW}字）
2. 然后用一句自然过渡问下一个模块的问题，给出3-4个参考选项引导用户
3. 语气轻松自然，像在聊天
4. 禁止续写正文，禁止进入角色扮演剧情，禁止写小说正文。`;
    }

    return `你是狐神抚。说话慵懒软糯，尾音拖长，爱用“～”“呢”“嘛”“啦”。

你已经和用户聊完了所有偏好模块。用户刚才说的是最后补充。
请只做狐析偏好对话回应。
禁止续写正文，禁止角色扮演剧情，禁止写小说正文。`;
  }

  async function hushenGenerateReplyForExistingUser(userText) {
    if (hushenIsSending || ssIsTaskRunning('hushen_chat')) {
      ssCancelTask('hushen_chat', '狐析重roll');
      return;
    }

    // 🦊 抢请求加固：狐析对话发送前等待其他模块/自动任务/主模型流式输出结束，避免并发 generateRaw。
    await ssWaitForManualIdle('hushen_chat');

    hushenIsSending = true;

    const sendBtn = topDoc.getElementById('hushen-chat-send');
    if (sendBtn) {
      sendBtn.textContent = '⛔';
      sendBtn.disabled = false;
    }

    try {
      const system = hushenBuildSystemPromptForCurrentStep();

      const ordered = [{ role: 'system', content: system }];

      for (const m of hushenConversation) {
        ordered.push({
          role: m.role === 'ai' ? 'assistant' : 'user',
          content: m.text,
        });
      }

      const r = await ssGenerateRaw('hushen_chat', {
        user_input: '',
        should_silence: true,
        should_stream: false,
        max_chat_history: 0,
        ordered_prompts: ordered,
      }, '狐析对话');

      const aiText = String(typeof r === 'string' ? r : (r?.content || '')).trim();

      if (aiText) {
        hushenAddMessage('ai', aiText);
        if (hushenModuleIndex < HUSHEN_ANALYSIS_MODULES.length) hushenModuleIndex++;
        // 🆕 模块进度推进后立即保存（hushenAddMessage 保存的是 ++ 前的进度）
        saveHushenSession();
      } else {
        hushenAddMessage('ai', '唔……AI没返回内容，再试一次？');
      }
    } catch (e) {
      if (!String(e?.message || e).includes('中断')) {
        hushenAddMessage('ai', `❌ 出错了：${e.message || e}`);
      }
    } finally {
      hushenIsSending = false;
      ssEndTask('hushen_chat');

      if (sendBtn) {
        sendBtn.textContent = '发送';
        sendBtn.disabled = false;
      }
    }
  }
  function readHushenConfigFromPanel() { const styleEl = topDoc.getElementById('ss-hushen-style'); const minEl = topDoc.getElementById('ss-hushen-min'); const maxEl = topDoc.getElementById('ss-hushen-max'); if (styleEl) state.hushenSettings.style = styleEl.value; if (minEl) state.hushenSettings.minWords = Math.max(10, parseInt(minEl.value) || 100); if (maxEl) state.hushenSettings.maxWords = Math.max((state.hushenSettings.minWords || 100) + 10, parseInt(maxEl.value) || 250); saveHushenSettings(); }
  function loadHushenSettings() { try { const raw = localStorage.getItem(CONFIG.HUSHEN_STORAGE_KEY); return raw ? { firstRun: false, analyzed: {}, drafts: {}, minWords: 100, maxWords: 250, style: 'detailed', ...JSON.parse(raw) } : { firstRun: true, analyzed: {}, drafts: {}, minWords: 100, maxWords: 250, style: 'detailed' }; } catch { return { firstRun: true, analyzed: {}, drafts: {}, minWords: 100, maxWords: 250, style: 'detailed' }; } }
  function saveHushenSettings() { localStorage.setItem(CONFIG.HUSHEN_STORAGE_KEY, JSON.stringify(state.hushenSettings)); }

  // ==================== 🆕 狐析会话状态持久化 ====================
  // 目的：保存 AI 分析过程中产生的临时结果（对话历史、模块进度、总结预览），
  //       使其能在用户刷新浏览器、重新进入模块后被正确恢复。
  // 存储方案：localStorage（与 hushen_profile_settings 同源，同步快、容量充足）。
  // 性能优化：saveHushenSession 使用微任务合并连续写入，避免高频阻塞主线程。
  let __hushenSessionSaveScheduled = false;
  let __hushenSessionSaveTimer = null;

  // 立即写入（带错误处理，绝不抛出影响主流程）
  function saveHushenSessionNow() {
    try {
      const payload = {
        conversation: hushenConversation || [],
        moduleIndex: hushenModuleIndex || 0,
        conversationActive: !!hushenConversationActive,
        summaryText: hushenSummaryText || '',
        savedAt: Date.now(),
        v: 1,
      };
      localStorage.setItem(CONFIG.HUSHEN_SESSION_KEY, JSON.stringify(payload));
    } catch (e) {
      // 存储失败（如配额超限、隐私模式）只记录日志，不影响分析流程
      log('[狐析会话] 保存失败', e);
    }
  }

  // 异步防抖保存：高频调用时（如连续添加消息）合并为一次写入，避免阻塞主线程
  function saveHushenSession() {
    if (__hushenSessionSaveScheduled) return;
    __hushenSessionSaveScheduled = true;
    // 优先用微任务（最快），并辅以 150ms 防抖兜底，确保不丢失且不阻塞 UI
    if (typeof queueMicrotask === 'function') {
      queueMicrotask(() => {
        __hushenSessionSaveScheduled = false;
        saveHushenSessionNow();
      });
    } else if (typeof Promise === 'function') {
      Promise.resolve().then(() => {
        __hushenSessionSaveScheduled = false;
        saveHushenSessionNow();
      });
    } else {
      // 极少数环境降级为 setTimeout
      if (__hushenSessionSaveTimer) clearTimeout(__hushenSessionSaveTimer);
      __hushenSessionSaveTimer = setTimeout(() => {
        __hushenSessionSaveScheduled = false;
        __hushenSessionSaveTimer = null;
        saveHushenSessionNow();
      }, 150);
    }
  }

  // 读取会话状态；损坏或不存在时返回 null，绝不抛出
  function loadHushenSession() {
    try {
      const raw = localStorage.getItem(CONFIG.HUSHEN_SESSION_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (!parsed || typeof parsed !== 'object') return null;
      // 基本校验，避免脏数据导致后续渲染崩溃
      const conversation = Array.isArray(parsed.conversation) ? parsed.conversation : [];
      const moduleIndex = Number.isFinite(parsed.moduleIndex) ? parsed.moduleIndex : 0;
      const conversationActive = !!parsed.conversationActive;
      const summaryText = typeof parsed.summaryText === 'string' ? parsed.summaryText : '';
      return { conversation, moduleIndex, conversationActive, summaryText };
    } catch (e) {
      log('[狐析会话] 读取失败，已忽略旧数据', e);
      return null;
    }
  }

  // 清除会话状态（用于重置/清除全部注入等场景）
  function clearHushenSession() {
    try {
      localStorage.removeItem(CONFIG.HUSHEN_SESSION_KEY);
    } catch (e) {
      log('[狐析会话] 清除失败', e);
    }
    if (__hushenSessionSaveTimer) { clearTimeout(__hushenSessionSaveTimer); __hushenSessionSaveTimer = null; }
    __hushenSessionSaveScheduled = false;
  }

  // ==================== 🆕 狐析快照回退机制 ====================
  // 目的：在破坏性操作（reroll/edit/重生成总结/回退）前自动保存完整对话状态快照，
  //       并支持用户手动存档优质回复。当 AI 优质回复被意外覆盖或替换时，
  //       可通过快照管理面板恢复到任一历史版本，实现类似"消息撤回"的功能。
  // 存储方案：localStorage（SPreset_HushenSnapshots），与狐析会话同源。
  // 容量控制：最多保留 30 个快照，超出丢弃最旧；总体积超 2MB 时跳过保存并告警。
  const HUSHEN_SNAPSHOT_MAX_COUNT = 30;
  const HUSHEN_SNAPSHOT_MAX_SIZE = 2 * 1024 * 1024;

  function hushenLoadSnapshots() {
    try {
      const raw = localStorage.getItem(CONFIG.HUSHEN_SNAPSHOTS_KEY);
      if (!raw) return [];
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      log('[狐析快照] 读取失败，已忽略旧数据', e);
      return [];
    }
  }

  function hushenSaveSnapshots() {
    try {
      const payload = JSON.stringify(hushenSnapshots || []);
      if (payload.length > HUSHEN_SNAPSHOT_MAX_SIZE) {
        log('[狐析快照] 快照总体积超阈值，跳过本次保存');
        return false;
      }
      localStorage.setItem(CONFIG.HUSHEN_SNAPSHOTS_KEY, payload);
      return true;
    } catch (e) {
      log('[狐析快照] 保存失败', e);
      return false;
    }
  }

  // 创建快照：捕获当前完整对话状态。reason 标记来源，label 用于列表展示。
  function hushenCreateSnapshot(reason, label) {
    try {
      const conv = hushenConversation || [];
      const snap = {
        id: Date.now() + '_' + Math.random().toString(36).slice(2, 7),
        reason: reason || 'manual',                 // manual / reroll / edit / summary / rollback / restore
        label: label || '',
        conversation: conv.map(m => ({ role: m.role, text: m.text })),
        moduleIndex: hushenModuleIndex || 0,
        summaryText: hushenSummaryText || '',
        msgCount: conv.length,
        savedAt: Date.now(),
        v: 1,
      };
      hushenSnapshots.unshift(snap);                 // 最新的排在最前
      if (hushenSnapshots.length > HUSHEN_SNAPSHOT_MAX_COUNT) {
        hushenSnapshots = hushenSnapshots.slice(0, HUSHEN_SNAPSHOT_MAX_COUNT);
      }
      hushenSaveSnapshots();
      return snap;
    } catch (e) {
      log('[狐析快照] 创建失败', e);
      return null;
    }
  }

  // 恢复快照：用快照内容覆盖当前状态并刷新 UI
  function hushenRestoreSnapshot(index) {
    const snap = hushenSnapshots[index];
    if (!snap || !Array.isArray(snap.conversation)) {
      toast('⚠️ 快照无效', 'warning');
      return false;
    }
    // 恢复前先把当前状态存一份快照（便于反悔），标记为 restore
    hushenCreateSnapshot('restore', '恢复前自动存档');

    hushenConversation = snap.conversation.map(m => ({ role: m.role, text: m.text }));
    hushenModuleIndex = Number.isFinite(snap.moduleIndex) ? snap.moduleIndex : 0;
    hushenSummaryText = typeof snap.summaryText === 'string' ? snap.summaryText : '';
    hushenConversationActive = hushenConversation.length > 0;
    hushenIsSending = false;

    saveHushenSession();
    hushenRenderChat();

    // 同步总结预览区
    const preview = topDoc.getElementById('hushen-summary-preview');
    const area = topDoc.getElementById('hushen-summary-area');
    if (preview) preview.value = hushenSummaryText;
    if (area) area.style.display = hushenSummaryText ? 'block' : 'none';

    // 同步进度
    const prog = topDoc.getElementById('hushen-progress-text');
    if (prog) prog.textContent = `进度：${Math.min(hushenModuleIndex, HUSHEN_ANALYSIS_MODULES.length)}/${HUSHEN_ANALYSIS_MODULES.length} 模块`;

    return true;
  }

  function hushenDeleteSnapshot(index) {
    if (index < 0 || index >= hushenSnapshots.length) return;
    hushenSnapshots.splice(index, 1);
    hushenSaveSnapshots();
  }

  function hushenFormatSnapshotTime(ts) {
    try {
      const d = new Date(ts);
      const pad = n => String(n).padStart(2, '0');
      return `${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
    } catch { return ''; }
  }

  function hushenSnapshotReasonText(reason) {
    switch (reason) {
      case 'manual': return '📸 手动存档';
      case 'reroll': return '🔁 重roll前';
      case 'edit': return '✏️ 编辑前';
      case 'summary': return '📋 重生成总结前';
      case 'rollback': return '↩️ 回退前';
      case 'restore': return '🔄 恢复前';
      default: return '💾 快照';
    }
  }

  // 打开快照管理浮层
  function hushenOpenSnapshotManager() {
    topDoc.getElementById('ss-hushen-snap-overlay')?.remove();

    const overlay = topDoc.createElement('div');
    overlay.id = 'ss-hushen-snap-overlay';
