  function loadHusouSettings() {
    try {
      const raw = localStorage.getItem(CONFIG.HUSOU_STORAGE_KEY);
      const parsed = raw ? JSON.parse(raw) : {};

      const cfg = ssNormalizeTagFilterSettings({
        ...HUSOU_DEFAULTS,
        ...parsed,
      });
      // ✅ 迁移旧版 enableAutoSearch 布尔 -> autoMode（和狐忆/平行世界同款三档：manual/auto/interval）
      if (parsed.autoMode == null) {
        cfg.autoMode = parsed.enableAutoSearch ? 'auto' : 'manual';
      }
      if (!['manual', 'auto', 'interval'].includes(cfg.autoMode)) cfg.autoMode = 'manual';
      cfg.autoInterval = Math.max(1, parseInt(cfg.autoInterval) || 5);
      // 保持旧字段同步，避免别处读 enableAutoSearch 出错
      cfg.enableAutoSearch = cfg.autoMode !== 'manual';
      return cfg;
    } catch (e) {
      return ssNormalizeTagFilterSettings({ ...HUSOU_DEFAULTS });
    }
  }

  function saveHusouSettings() {
    state.husouSettings = ssNormalizeTagFilterSettings(
