  // ✅ 狐搜自动搜索计数器（interval 模式用，和狐忆/平行世界同款，按 char+chat 持久化）
  let husouGenCounter = 0;
  let husouLastAutoSearchMessageId = null;
  let husouActiveDiag = null;
  let husouLastDiag = null;
  function husouDiag(stage, data = {}, level = 'log') {
    const diag = husouActiveDiag || husouLastDiag;
    if (diag) ssModuleDiag(diag, stage, data, level);
    else {
      const method = level === 'error' ? 'error' : (level === 'warn' ? 'warn' : 'log');
      try { console[method](`[狐搜诊断][NO-SESSION][${stage}] ${JSON.stringify(foxJudgeDiagValue(data))}`); } catch {}
    }
  }
  function husouSafeUrl(rawUrl) {
    try {
      const url = new URL(String(rawUrl || ''), topWindow?.location?.href || window.location.href);
      const queryKeys = [...url.searchParams.keys()];
      const path = url.pathname
        .split('/')
        .map(part => /(?:key|token|secret|password)/i.test(part) || part.length > 80 ? '[已隐藏]' : part)
        .join('/');
      return `${url.origin}${path}${queryKeys.length ? `?参数=${queryKeys.join(',')}` : ''}`;
    } catch {
      return `[无法解析URL，长度=${String(rawUrl || '').length}]`;
    }
  }
  function husouMakeError(code, message, detail = {}) {
    const error = new Error(`[${code}] ${message}`);
    error.code = code;
    error.detail = detail;
    return error;
  }
  function husouErrorInfo(error) {
    return {
      code: error?.code || error?.name || 'HUSOU_UNKNOWN',
      message: error?.message || String(error || '未知错误'),
      detail: error?.detail || {},
    };
  }
  function husouSearchSummaryText(summary) {
    if (!summary) return '没有搜索任务明细';
    const failed = (summary.details || []).filter(x => x.status === 'error');
    const failureText = failed.slice(0, 8).map(item =>
      `${item.source}/${item.keyword}：${item.error?.code || 'ERROR'} ${item.error?.message || '未知错误'}`
    ).join('\n');
    return `任务=${summary.taskCount || 0}，成功=${summary.successCount || 0}，正常空结果=${summary.emptyCount || 0}，失败=${summary.errorCount || 0}${failureText ? `\n失败明细：\n${failureText}` : ''}`;
  }
  function husouAutoCounterKey() { return `Xuanhu_HusouAutoCounter_${encodeURIComponent(getCurrentCharId())}_${encodeURIComponent(getCurrentChatScopeId())}`; }
  function husouLoadAutoCounter() { try { const v = JSON.parse(localStorage.getItem(husouAutoCounterKey()) || '{}'); husouGenCounter = Math.max(0, Number(v.count) || 0); husouLastAutoSearchMessageId = v.lastId == null ? null : String(v.lastId); } catch {} }
  function husouSaveAutoCounter() { try { localStorage.setItem(husouAutoCounterKey(), JSON.stringify({ count: husouGenCounter, lastId: husouLastAutoSearchMessageId })); } catch {} }

  function husouNormalizeKeywords(input) {
    if (Array.isArray(input)) {
      return [...new Set(
        input
          .map(x => String(x || '').trim())
          .filter(Boolean)
      )];
    }

    return [...new Set(
      String(input || '')
        .split(/[\n,，、;；|]+/g)
        .map(x => x.trim())
        .filter(Boolean)
    )];
  }

  function husouKeywordsLine(keywords) {
