  async function husouSearchCustom(keyword, signal, s) {
    const url = s.searchApiUrl?.trim();
    if (!url) throw husouMakeError('CUSTOM_CONFIG_URL_EMPTY', '自定义搜索已启用，但 API 地址为空');
    const method = (s.searchApiMethod || 'GET').toUpperCase();
    const key = s.searchApiKey?.trim() || '';
    const language = s.searchApiLanguage?.trim() || 'zh-CN';
    const shouldUseLanguage = language && language !== 'auto';
    const headers = { 'Accept': 'application/json' };
    if (key && s.searchApiKeyHeaderName?.trim()) {
      const template = s.searchApiKeyHeaderTemplate?.trim() || '{key}';
      headers[s.searchApiKeyHeaderName.trim()] = template.replace(/\{key\}/g, key);
    }
    try {
      let finalUrl = url.replace('{keyword}', encodeURIComponent(keyword)).replace('{language}', encodeURIComponent(language));
      let body = null;
      if (method === 'POST') {
        if (!headers['Content-Type']) headers['Content-Type'] = 'application/json';
        const tpl = s.searchApiBodyTemplate?.trim() || '{"query":"{keyword}"}';
        body = tpl.replace('{keyword}', keyword.replace(/\\/g, '\\\\').replace(/"/g, '\\"')).replace('{language}', language.replace(/\\/g, '\\\\').replace(/"/g, '\\"'));
      } else {
        if (key && s.searchApiQueryParam?.trim()) {
          const sep = finalUrl.includes('?') ? '&' : '?';
          finalUrl += `${sep}${encodeURIComponent(s.searchApiQueryParam.trim())}=${encodeURIComponent(key)}`;
        }
        if (s.searchApiExtraParams?.trim()) {
          let extra = s.searchApiExtraParams.trim().replace('{keyword}', encodeURIComponent(keyword)).replace('{language}', encodeURIComponent(language));
          if (!extra.startsWith('&') && !extra.startsWith('?')) extra = (finalUrl.includes('?') ? '&' : '?') + extra;
          finalUrl += extra;
        }
        if (shouldUseLanguage && !finalUrl.includes('language=') && !finalUrl.includes('lang=')) {
          const sep = finalUrl.includes('?') ? '&' : '?';
          finalUrl += `${sep}language=${encodeURIComponent(language)}`;
        }
      }
      const fetchOpts = { method, headers, signal };
      if (body) fetchOpts.body = body;
      const startedAt = Date.now();
      husouDiag('搜索源:自定义:请求', {
        keyword, method, url: husouSafeUrl(finalUrl), timeoutMs: Number(s.searchTimeout) || 20000,
        hasApiKey: !!key, headerNames: Object.keys(headers), hasBody: !!body,
        resultPath: s.searchApiResultPath?.trim() || 'results',
      });
      const resp = await fetch(finalUrl, fetchOpts);
      const responseText = await resp.text();
      husouDiag('搜索源:自定义:响应', {
        keyword, status: resp.status, statusText: resp.statusText, ok: resp.ok,
        durationMs: Date.now() - startedAt, contentType: resp.headers.get('content-type') || '',
        responseLength: responseText.length, responsePreview: responseText.slice(0, 500),
      }, resp.ok ? 'log' : 'error');
      if (!resp.ok) throw husouMakeError('CUSTOM_HTTP_ERROR', `自定义搜索 HTTP ${resp.status} ${resp.statusText || ''}`.trim(), {
        status: resp.status, url: husouSafeUrl(finalUrl), responsePreview: responseText.slice(0, 500),
      });
      let data;
      try { data = JSON.parse(responseText); }
      catch (e) {
        throw husouMakeError('CUSTOM_JSON_INVALID', '自定义搜索响应不是合法 JSON', {
          contentType: resp.headers.get('content-type') || '', responsePreview: responseText.slice(0, 500), parseError: e.message,
        });
      }
      const path = s.searchApiResultPath?.trim() || 'results';
      let list = data;
      for (const k of path.split('.')) {
        if (list == null) break;
        list = /^\d+$/.test(k) ? list[parseInt(k)] : list[k];
      }
      if (!Array.isArray(list)) throw husouMakeError('CUSTOM_RESULT_PATH_INVALID', `结果路径“${path}”没有得到数组`, {
        path, resolvedType: list === null ? 'null' : typeof list, topLevelKeys: data && typeof data === 'object' ? Object.keys(data).slice(0, 30) : [],
      });
      const titleF = s.searchApiTitleField?.trim() || 'title';
      const snipF = s.searchApiSnippetField?.trim() || 'content';
      const linkF = s.searchApiLinkField?.trim() || 'url';
      const limit = s.searchResultsCount || 10;
      const maxLen = s.maxExtractLength || 40000;
      const results = [];
      for (const item of list) {
        const title = (item[titleF] || '').toString();
        const snippet = (item[snipF] || '').toString()
          .replace(/<[^>]+>/g, '')
          .replace(/\n+/g, ' ')
          .replace(/\s+/g, ' ')
          .trim();
        const link = (item[linkF] || '').toString();
        if (!snippet && !title) continue;
        let text = title ? `【${title}】` : '';
        text += snippet;
        if (link) text += `\n🔗 ${link}`;
        if (text) results.push(text);
        if (results.length >= limit) break;
      }
      husouDiag('搜索源:自定义:映射', {
        keyword, inputItems: list.length, usableItems: results.length, titleField: titleF, snippetField: snipF, linkField: linkF,
      }, results.length ? 'log' : 'warn');
      if (list.length && !results.length) throw husouMakeError('CUSTOM_FIELDS_EMPTY', '结果数组不为空，但标题/摘要字段映射后全部为空', {
        titleField: titleF, snippetField: snipF, linkField: linkF,
        sampleKeys: list[0] && typeof list[0] === 'object' ? Object.keys(list[0]).slice(0, 30) : [],
      });
      return results.length ? results.join('\n') : null;
    } catch (e) {
      husouDiag('搜索源:自定义:失败', { keyword, error: husouErrorInfo(e) }, e?.name === 'AbortError' ? 'warn' : 'error');
      throw e;
    }
  }

  async function husouFetchWithTimeout(url, options = {}, timeoutMs = 20000) {
    const controller = new AbortController();
    let timedOut = false;
    const timer = setTimeout(() => { timedOut = true; controller.abort(); }, timeoutMs);

    const parentSignal = options.signal;

    if (parentSignal) {
      if (parentSignal.aborted) {
        clearTimeout(timer);
        throw new DOMException('Aborted', 'AbortError');
      }

      parentSignal.addEventListener('abort', () => {
        controller.abort();
      }, { once: true });
    }

    try {
      try {
        return await fetch(url, {
          ...options,
          signal: controller.signal,
        });
      } catch (e) {
        if (timedOut) throw husouMakeError('FETCH_TIMEOUT', `网络请求超过 ${timeoutMs}ms`, { url: husouSafeUrl(url), timeoutMs });
        throw e;
      }
    } finally {
      clearTimeout(timer);
    }
  }

  function husouCleanJinaText(text) {
    let t = String(text || '');

    // 删除 Jina Reader 自带元信息
    t = t.replace(/^Title:\s*.*$/gmi, '');
    t = t.replace(/^URL Source:\s*https?:\/\/\S+.*$/gmi, '');
    t = t.replace(/^Published Time:\s*.*$/gmi, '');
    t = t.replace(/^Markdown Content:\s*$/gmi, '');

    // 删除 Markdown 图片：![xxx](url)
    t = t.replace(/!\[[^\]]*?\]\((?:https?:\/\/|data:image\/)[^)]+\)/gi, '');

    // 删除 HTML 图片标签
    t = t.replace(/<img\b[^>]*>/gi, '');

    // Markdown 链接：[文本](url) => 文本
    // 保留可读文本，删除 URL
    t = t.replace(/\[([^\]]{0,120})\]\((?:https?:\/\/|\/)[^)]+\)/gi, '$1');

    // 删除裸露 http/https URL
    t = t.replace(/https?:\/\/[^\s"'<>，。！？、；：）)\]}【】]+/gi, '');

    // 删除 www 开头的网址
    t = t.replace(/\bwww\.[^\s"'<>，。！？、；：）)\]}【】]+/gi, '');

    // 删除常见图片/静态资源残留路径
    t = t.replace(/\S+\.(?:png|jpg|jpeg|gif|webp|svg|ico|avif|bmp)(?:\?\S*)?/gi, '');
    t = t.replace(/\S+\.(?:css|js|map|woff2?|ttf|otf)(?:\?\S*)?/gi, '');

    // 删除 data:image
    t = t.replace(/data:image\/[a-zA-Z]+;base64,[A-Za-z0-9+/=]+/g, '');

    // 删除空括号、空链接、过多竖线
    t = t.replace(/\(\s*\)/g, '');
    t = t.replace(/\[\s*\]/g, '');
    t = t.replace(/\|{2,}/g, '|');

    // 删除明显无用的纯资源行/导航噪音行
    const badLinePatterns = [
      /^!\[.*?\]$/i,
      /^Image\s*\d*$/i,
      /^图片\s*\d*$/i,
      /^点击下载$/i,
      /^立即下载$/i,
      /^Download$/i,
      /^Loading/i,
      /^Copyright/i,
      /^©/,
    ];

    t = t
      .split('\n')
      .map(line => line.trim())
      .filter(line => {
        if (!line) return true;

        if (badLinePatterns.some(re => re.test(line))) return false;

        // 一行里如果几乎全是符号，也删掉
        const readable = line.replace(/[|_\-—=~·.,，。:：;；!！?？()[\]（）【】<>《》"'“”‘’\s]/g, '');
        if (line.length > 20 && readable.length < 3) return false;

        return true;
      })
      .join('\n');

    // 清理多余空格和空行
    t = t.replace(/[ \t]+\n/g, '\n');
    t = t.replace(/\n{3,}/g, '\n\n');
    t = t.replace(/[ \t]{2,}/g, ' ');

    return t.trim();
  }

  // ==================== 狐搜：Jina 抓取前 AI 预筛选 ====================
  // 目的：
  // - 先让 AI 看搜索结果标题、摘要、URL；
  // - 结合完整固定上下文判断哪些网页值得抓全文；
  // - 过滤字典、翻译、下载页、官网入口、纯图片页、登录页、无正文页面；
  // - 不限制上下文字数，不限制候选数量，不截断输出。

  function husouNormalizeJinaUrl(url) {
    return String(url || '')
      .trim()
      .replace(/[)\]）】。,.，；;]+$/g, '');
  }

  function husouExtractJinaCandidates(searchResults) {
    const candidates = [];
    const seen = new Set();

    const pushCandidate = (obj) => {
      const url = husouNormalizeJinaUrl(obj.url);

      if (!/^https?:\/\//i.test(url)) return;
      if (seen.has(url)) return;

      seen.add(url);

      candidates.push({
        index: candidates.length + 1,
        keyword: String(obj.keyword || '').trim(),
        title: String(obj.title || '').trim(),
        snippet: String(obj.snippet || '').trim(),
        url,
      });
    };

    for (const [keyword, text] of searchResults || []) {
      const lines = String(text || '').split('\n');

      let current = {
        keyword,
        title: '',
        snippet: '',
        url: '',
      };

      const flush = () => {
        if (current.url) {
          pushCandidate(current);
        }

        current = {
          keyword,
          title: '',
          snippet: '',
          url: '',
        };
      };

      for (const lineRaw of lines) {
        const line = String(lineRaw || '').trim();
        if (!line) continue;

        const titleMatch = line.match(/^【([^】]{1,300})】\s*([\s\S]*)$/);

        if (titleMatch) {
          if (current.url) flush();

          current.title = titleMatch[1].trim();
          current.snippet = titleMatch[2].trim();
          current.url = '';
          continue;
        }

        const urlMatch = line.match(/^🔗\s*(https?:\/\/\S+)/i);

        if (urlMatch) {
          current.url = husouNormalizeJinaUrl(urlMatch[1]);
          flush();
          continue;
        }

        if (current.title || current.snippet) {
          current.snippet = current.snippet
            ? `${current.snippet}\n${line}`
            : line;
        }
      }

      flush();
    }

    return candidates;
  }

  function husouParseJinaPrefilterJson(text) {
    const raw = String(text || '').trim();

    const fence = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
    const src = fence ? fence[1].trim() : raw;

    try {
      return JSON.parse(src);
    } catch { }

    const s = src.indexOf('{');
    const e = src.lastIndexOf('}');

    if (s >= 0 && e > s) {
      return JSON.parse(src.slice(s, e + 1));
    }

    throw new Error('Jina 前置筛选没有返回可解析 JSON');
  }

  function husouStripRejectedJinaUrlsFromMap(searchResults, approvedUrls) {
    const map = new Map();

    for (const [kw, text] of searchResults || []) {
      const cleaned = String(text || '')
        .split('\n')
        .filter(line => {
          const m = String(line || '').match(/^🔗\s*(https?:\/\/\S+)/i);

          if (!m) return true;

          const url = husouNormalizeJinaUrl(m[1]);

          return approvedUrls.has(url);
        })
        .join('\n')
        .replace(/\n{3,}/g, '\n\n')
        .trim();

      map.set(kw, cleaned);
    }

    return map;
  }

  async function husouPrefilterJinaFetchTargets(searchResults, s, keywords = []) {
    const candidates = husouExtractJinaCandidates(searchResults);
    husouDiag('Jina前筛选:候选提取', {
      rawKeywordCount: searchResults?.size || 0,
      candidateCount: candidates.length,
      candidates: candidates.slice(0, 30).map(item => ({ index: item.index, keyword: item.keyword, title: item.title, url: husouSafeUrl(item.url) })),
    });

    if (!candidates.length) {
      log('[Jina前置筛选] 没有可筛选 URL，跳过');
      husouDiag('Jina前筛选:跳过', { reason: 'no_url_candidates', rawKeywordCount: searchResults?.size || 0 }, 'warn');
      return new Map(searchResults);
    }

    const candidateText = candidates.map(c => {
      return `【候选 ${c.index}】
关键词：${c.keyword || '未知'}
标题：${c.title || '无标题'}
摘要：${c.snippet || '无摘要'}
URL：${c.url}`;
    }).join('\n\n');

    const taskPrompt = `【上下文结束】

【身份】
你是狐搜的 Jina 抓取前置筛选器。

你不会抓网页全文。
你只阅读完整上下文、当前搜索关键词，以及“原始搜索结果候选”的标题、摘要、URL。
你的任务是判断：哪些候选网页值得继续调用 Jina 抓取全文。

【判断目标】
只批准真正可能包含有效人物信息、作品设定、世界观信息、角色资料、组织资料、物品资料、剧情资料的网页。

【优先批准】
1. wiki、wikipedia、萌娘百科、百度百科、fandom、wiki.gg、专门的作品百科、角色资料页。
2. 标题和摘要明显包含角色身份、经历、性格、能力、剧情、世界观、组织、地点、物品、设定。
3. 与当前角色卡、世界书、聊天上下文、搜索关键词明显相关。
4. 虽然不是百科，但摘要显示有足够文字信息，且和当前上下文相关。
5. 即使和当前角色不相关，但有具体世界观、其他信息的网页，批准，可作为信息、世界观补充

【必须拒绝】
1. 字典、翻译、词语解释、成语解释、普通汉语释义页面。
2. 官网首页、下载页、启动器页面、登录页、注册页、商店页、购买页、新闻列表页。
3. 纯图片、图库、壁纸、头像、表情包、视频、短视频、直播、音乐播放、无正文页面。
4. 搜索结果页、标签页、目录页、导航页、聚合页。
5. 摘要为空、只有广告词、只有按钮文字、只有“下载/进入官网/立即体验”等无信息内容。
6. 和当前世界书、角色卡、聊天上下文明显无关的同名词条。
7. 抓了也只能得到大量图片、按钮、导航、下载提示的网站。

【特别规则】
- 如果标题是百科，直接抓取，特别是wiki、百度百科，人物介绍等网页，即使摘要里没有正文，也必须抓取！
- 如果是官网，但摘要只是宣传、下载、购买、注册，不要抓。
- 如果是官网里的具体角色资料/设定资料页，批准。
- 如果不确定，但摘要里已经出现部分人物设定、剧情设定、世界观资料，批准。
- 如果只是在解释一个普通词语，如字典，不要批准。
- 尽可能抓有任何关联信息的网页，即使是标题里出现也要抓取，但不要乱抓完全无关的网页。

【本次搜索关键词】
${husouNormalizeKeywords(keywords).join('、') || '（未知）'}

【原始搜索结果候选】
${candidateText}

【输出格式】
必须只输出合法 JSON。
禁止 Markdown。
禁止代码块。
禁止解释。

格式：
{
  "approved": [
    {
      "index": 1,
      "url": "https://example.com/xxx",
      "reason": "批准原因"
    }
  ],
  "rejected": [
    {
      "index": 2,
      "url": "https://example.com/yyy",
      "reason": "拒绝原因"
    }
  ]
}

如果没有任何值得抓取的网页：
{
  "approved": [],
  "rejected": []
}`;

    try {
      const startedAt = Date.now();
      const r = await husouGenerateTaskOrdered([
        husouBuildFixedContextHeader(),
        ...husouBuildFixedContextOrderedPrompts(),

        // 身份、候选结果、判断规则放底部，防止模型忽略任务
        {
          role: 'system',
          content: taskPrompt,
        },
      ], s, 'husou_jina_prefilter');

      husouDiag('Jina前筛选:模型响应', {
        durationMs: Date.now() - startedAt,
        responseLength: String(r || '').length,
        responsePreview: String(r || '').slice(0, 500),
      });
      const parsed = husouParseJinaPrefilterJson(r);

      const approvedList = Array.isArray(parsed.approved)
        ? parsed.approved
        : Array.isArray(parsed.approved_urls)
          ? parsed.approved_urls
          : Array.isArray(parsed.urls)
            ? parsed.urls
            : [];

      const approvedUrls = new Set();

      for (const item of approvedList) {
        if (typeof item === 'number') {
          const c = candidates[item - 1];
          if (c?.url) approvedUrls.add(c.url);
          continue;
        }

        if (typeof item === 'string') {
          const url = husouNormalizeJinaUrl(item);
          if (/^https?:\/\//i.test(url)) approvedUrls.add(url);
          continue;
        }

        if (item && typeof item === 'object') {
          if (item.should_fetch === false || item.approved === false) continue;

          const idx = Number(item.index ?? item.id ?? item.no);
          if (Number.isFinite(idx) && idx >= 1 && candidates[idx - 1]?.url) {
            approvedUrls.add(candidates[idx - 1].url);
          }

          const url = husouNormalizeJinaUrl(item.url || '');
          if (/^https?:\/\//i.test(url)) approvedUrls.add(url);
        }
      }

      const passed = [...approvedUrls];

      log(`[Jina前置筛选] 候选 ${candidates.length} 个，通过 ${passed.length} 个`, passed);
      husouDiag('Jina前筛选:完成', {
        candidateCount: candidates.length,
        approvedCount: passed.length,
        rejectedCount: Math.max(0, candidates.length - passed.length),
        approvedUrls: passed.map(husouSafeUrl),
      }, passed.length ? 'info' : 'warn');

      try {
        if (state.husouDebug) {
          state.husouDebug.rawText = `${state.husouDebug.rawText || ''}

===== Jina前置筛选 =====
候选数量：${candidates.length}
通过数量：${passed.length}
通过URL：
${passed.join('\n') || '（无）'}`;

          husouUpdateQuickPanel();
        }
      } catch { }

      return husouStripRejectedJinaUrlsFromMap(searchResults, approvedUrls);
    } catch (e) {
      log('[Jina前置筛选] 失败，回退为原始 Jina 抓取逻辑:', e?.message || e);
      husouDiag('Jina前筛选:失败并回退', { error: husouErrorInfo(e), candidateCount: candidates.length }, 'error');

      // 失败时不阻断搜索，直接回退原始搜索结果。
      return new Map(searchResults);
    }
  }

  // ==================== Jina Reader：原版狐搜网页全文抓取逻辑 ====================
  async function husouFetchPageWithJina(url, signal, s) {
    const maxLen = Number(s.maxExtractLength || 40000);
    const timeoutMs = Number(s.jinaPageTimeout || 20000);

    const cleanUrl = String(url || '')
      .trim()
      .replace(/[)\]）】。,.，；;]+$/g, '');

    if (!/^https?:\/\//i.test(cleanUrl)) {
      husouDiag('Jina:URL非法', { url: husouSafeUrl(cleanUrl) }, 'error');
      return null;
    }

    const jinaUrl = `https://r.jina.ai/${cleanUrl}`;

    try {
      const startedAt = Date.now();
      husouDiag('Jina:请求', { sourceUrl: husouSafeUrl(cleanUrl), readerUrl: husouSafeUrl(jinaUrl), timeoutMs });

      const resp = await husouFetchWithTimeout(jinaUrl, {
        signal,
        headers: {
          'Accept': 'text/plain',
        },
      }, timeoutMs);

      const rawText = await resp.text();
      husouDiag('Jina:响应', {
        sourceUrl: husouSafeUrl(cleanUrl), status: resp.status, ok: resp.ok,
        durationMs: Date.now() - startedAt, rawLength: rawText.length, responsePreview: rawText.slice(0, 500),
      }, resp.ok ? 'log' : 'error');

      if (!resp.ok) {
        husouDiag('Jina:HTTP失败', { sourceUrl: husouSafeUrl(cleanUrl), status: resp.status, responsePreview: rawText.slice(0, 500) }, 'error');
        return null;
      }

      const cleaned = husouCleanJinaText(rawText);

      husouDiag('Jina:清洗完成', { sourceUrl: husouSafeUrl(cleanUrl), rawLength: rawText.length, cleanedLength: cleaned.length, cleanedPreview: cleaned.slice(0, 500) });

      if (!cleaned) {
        husouDiag('Jina:清洗后为空', { sourceUrl: husouSafeUrl(cleanUrl), rawLength: rawText.length }, 'warn');
        return null;
      }

      if (cleaned.length < 200) {
        husouDiag('Jina:正文过短', { sourceUrl: husouSafeUrl(cleanUrl), cleanedLength: cleaned.length, cleanedPreview: cleaned }, 'warn');
      }

      return cleaned.trim() || null;
    } catch (e) {
      husouDiag(e?.name === 'AbortError' ? 'Jina:超时或取消' : 'Jina:抓取失败', {
        sourceUrl: husouSafeUrl(cleanUrl), timeoutMs, error: husouErrorInfo(e),
      }, e?.name === 'AbortError' ? 'warn' : 'error');

      return null;
    }
  }
  async function husouSearchAll(keywords, s, externalSignal = null) {
    const ctrl = new AbortController();

    if (externalSignal) {
      if (externalSignal.aborted) ctrl.abort();
      externalSignal.addEventListener('abort', () => ctrl.abort(), { once: true });
    }

    const tid = setTimeout(() => ctrl.abort(), s.searchTimeout || 20000);

    try {
      const tasks = [];
      husouDiag('搜索源:调度开始', {
        keywordCount: keywords.length, keywords,
        enabledSources: { wikipedia: !!s.enableWikipedia, moegirl: !!s.enableMoegirl, custom: !!s.enableCustomSearch },
        timeoutMs: Number(s.searchTimeout) || 20000,
      }, 'info');

      const pushTask = (source, kw, promise) => {
        tasks.push({ source, kw, promise });
      };

      for (const kw of keywords) {
        if (s.enableWikipedia) {
          pushTask('Wikipedia', kw, husouSearchWiki(kw, ctrl.signal, s));
        }

        if (s.enableMoegirl) {
          pushTask('Moegirl', kw, husouSearchMoegirl(kw, ctrl.signal, s));
        }

        if (s.enableCustomSearch) {
          pushTask('CustomSearch', kw, husouSearchCustom(kw, ctrl.signal, s));
        }

        // 注意：
        // Jina 不再作为独立搜索源。
        // Jina 会在拿到搜索结果 URL 后，由 husouFilterResults() 内部抓网页全文。
      }

      log(`[狐搜] 搜索任务已创建：关键词 ${keywords.length} 个，任务 ${tasks.length} 个`);

      if (!tasks.length) {
        const empty = new Map();
        empty._husouSummary = { taskCount: 0, successCount: 0, emptyCount: 0, errorCount: 0, details: [] };
        husouDiag('搜索源:配置错误', { code: 'NO_BASE_SOURCE', message: '没有启用任何基础搜索源' }, 'error');
        return empty;
      }

      const results = await Promise.allSettled(tasks.map(t => t.promise));

      log('[狐搜] 搜索源返回完成，开始整理 raw map');

      const map = new Map();
      const detailLines = [];
      const detailRecords = [];

      for (let i = 0; i < tasks.length; i++) {
        const task = tasks[i];
        const r = results[i];

        if (!task || !r) continue;

        if (r.status === 'fulfilled') {
          const value = typeof r.value === 'string'
            ? r.value.trim()
            : '';

          if (value) {
            const old = map.get(task.kw) || '';
            map.set(task.kw, old ? `${old}\n${value}` : value);

            detailLines.push(`✅ ${task.source} / ${task.kw}：${value.length} 字`);
            detailRecords.push({ source: task.source, keyword: task.kw, status: 'success', length: value.length });
          } else {
            detailLines.push(`⚪ ${task.source} / ${task.kw}：空结果`);
            detailRecords.push({ source: task.source, keyword: task.kw, status: 'empty' });
          }
        } else {
          const reason = r.reason?.message || r.reason?.name || String(r.reason || '未知错误');
          detailLines.push(`❌ ${task.source} / ${task.kw}：${reason}`);
          detailRecords.push({ source: task.source, keyword: task.kw, status: 'error', error: husouErrorInfo(r.reason) });
        }
      }

      map._husouSummary = {
        taskCount: tasks.length,
        successCount: detailRecords.filter(x => x.status === 'success').length,
        emptyCount: detailRecords.filter(x => x.status === 'empty').length,
        errorCount: detailRecords.filter(x => x.status === 'error').length,
        aborted: ctrl.signal.aborted,
        details: detailRecords,
      };

      log(
        `[狐搜] raw map 整理完成：有效关键词 ${map.size} / ${keywords.length}，任务 ${tasks.length}`,
        detailLines
      );
      husouDiag('搜索源:汇总', map._husouSummary, map._husouSummary.errorCount ? 'warn' : 'info');

      return map;
    } finally {
      clearTimeout(tid);
    }
  }


  async function husouSearchWiki(keyword, signal, s) {
    try {
      const limit = s.searchResultsCount || 10;
      const maxLen = s.maxExtractLength || 40000;

      let term = keyword;

      try {
        const startedAt = Date.now();
        const sr = await fetch(
          `https://zh.wikipedia.org/w/api.php?action=opensearch&search=${encodeURIComponent(keyword)}&limit=1&format=json&origin=*`,
          { signal }
        );

        husouDiag('搜索源:Wikipedia:词条解析响应', { keyword, status: sr.status, ok: sr.ok, durationMs: Date.now() - startedAt }, sr.ok ? 'log' : 'warn');
        if (sr.ok) {
          const sd = await sr.json();

          if (Array.isArray(sd[1]) && sd[1].length > 0 && sd[1][0] !== keyword) {
            term = sd[1][0];
          }
        }
      } catch (e) {
        if (e?.name === 'AbortError') throw e;
        husouDiag('搜索源:Wikipedia:词条解析失败', { keyword, error: husouErrorInfo(e), fallbackTerm: keyword }, 'warn');
      }

      const searchStartedAt = Date.now();
      const sResp = await fetch(
        `https://zh.wikipedia.org/w/api.php?action=query&list=search&srsearch=${encodeURIComponent(term)}&format=json&origin=*&srlimit=${limit}`,
        { signal }
      );

      husouDiag('搜索源:Wikipedia:搜索响应', { keyword, term, status: sResp.status, ok: sResp.ok, durationMs: Date.now() - searchStartedAt }, sResp.ok ? 'log' : 'error');
      if (!sResp.ok) throw husouMakeError('WIKI_SEARCH_HTTP_ERROR', `Wikipedia 搜索 HTTP ${sResp.status}`, { keyword, term, status: sResp.status });

      const sData = await sResp.json();
      const pages = sData?.query?.search;

      if (!pages?.length) {
        husouDiag('搜索源:Wikipedia:正常空结果', { keyword, term, responseKeys: Object.keys(sData || {}) }, 'warn');
        return null;
      }

      const pids = pages.map(p => p.pageid);

      const extractStartedAt = Date.now();
      const eResp = await fetch(
        `https://zh.wikipedia.org/w/api.php?action=query&prop=extracts&exintro&explaintext&pageids=${pids.join('|')}&format=json&origin=*`,
        { signal }
      );

      husouDiag('搜索源:Wikipedia:摘要响应', { keyword, pageCount: pids.length, status: eResp.status, ok: eResp.ok, durationMs: Date.now() - extractStartedAt }, eResp.ok ? 'log' : 'error');
      if (!eResp.ok) throw husouMakeError('WIKI_EXTRACT_HTTP_ERROR', `Wikipedia 摘要 HTTP ${eResp.status}`, { keyword, status: eResp.status, pageCount: pids.length });

      const eData = await eResp.json();
      const extracts = [];

      for (const pid of pids) {
        const page = eData?.query?.pages?.[pid];

        if (page?.extract) {
          const clean = page.extract
            .replace(/\n+/g, ' ')
            .replace(/\s+/g, ' ')
            .trim();

          if (clean) {
            const wikiUrl = `https://zh.wikipedia.org/wiki/${encodeURIComponent(String(page.title).replace(/\s+/g, '_'))}`;
            extracts.push(`【${page.title}】${clean}\n🔗 ${wikiUrl}`);
          }
        }
      }

      husouDiag('搜索源:Wikipedia:完成', { keyword, matchedPages: pages.length, usableExtracts: extracts.length }, extracts.length ? 'info' : 'warn');
      return extracts.length ? extracts.join('\n') : null;
    } catch (e) {
      husouDiag('搜索源:Wikipedia:失败', { keyword, error: husouErrorInfo(e) }, e?.name === 'AbortError' ? 'warn' : 'error');
      throw e;
    }
  }


  async function husouSearchMoegirl(keyword, signal, s) {
    try {
      const limit = s.searchResultsCount || 10;
      const maxLen = s.maxExtractLength || 40000;

      const startedAt = Date.now();
      const resp = await fetch(
        `https://zh.moegirl.org.cn/api.php?action=query&list=search&srsearch=${encodeURIComponent(keyword)}&format=json&origin=*&srlimit=${limit}`,
        { signal }
      );

      husouDiag('搜索源:Moegirl:响应', { keyword, status: resp.status, ok: resp.ok, durationMs: Date.now() - startedAt }, resp.ok ? 'log' : 'error');
      if (!resp.ok) throw husouMakeError('MOEGIRL_HTTP_ERROR', `萌娘百科搜索 HTTP ${resp.status}`, { keyword, status: resp.status });

      const data = await resp.json();
      const pages = data?.query?.search;

      if (!pages?.length) {
        husouDiag('搜索源:Moegirl:正常空结果', { keyword, responseKeys: Object.keys(data || {}) }, 'warn');
        return null;
      }

      const results = pages
        .map(p => {
          const snippet = String(p.snippet || '')
            .replace(/<[^>]+>/g, '')
            .replace(/\s+/g, ' ')
            .trim();

          const moegirlUrl = `https://zh.moegirl.org.cn/${encodeURIComponent(String(p.title).replace(/\s+/g, '_'))}`;

          return `【萌娘百科：${p.title}】${snippet}\n🔗 ${moegirlUrl}`;
        })
        .filter(Boolean);

      husouDiag('搜索源:Moegirl:完成', { keyword, matchedPages: pages.length, usableResults: results.length }, results.length ? 'info' : 'warn');
      return results.length ? results.join('\n') : null;
    } catch (e) {
      husouDiag('搜索源:Moegirl:失败', { keyword, error: husouErrorInfo(e) }, e?.name === 'AbortError' ? 'warn' : 'error');
      throw e;
    }
  }


  function husouGetFullContext(mid) {
    const parts = [];

    try {
      const ctx = SillyTavern?.getContext?.();
      const char = ctx?.characters?.[ctx?.characterId];

      if (char) {
        parts.push(`【角色名】${char.name || ''}`);

        if (char.description?.trim()) {
          parts.push(`【角色描述】${char.description}`);
        }

        if (char.personality?.trim()) {
          parts.push(`【性格】${char.personality}`);
        }

        if (char.scenario?.trim()) {
          parts.push(`【场景】${char.scenario}`);
        }
      }
    } catch (e) {
      husouDiag('上下文:角色卡读取失败', { messageId: mid, error: husouErrorInfo(e) }, 'error');
    }

    try {
      const glmi = getFn('getLastMessageId');
      const gcm = getFn('getChatMessages');

      if (glmi && gcm) {
        const lid = mid ?? glmi();

        if (lid >= 0) {
          const ms = gcm(`0-${lid}`, {
            hide_state: 'all',
            include_swipes: false,
          }) || [];

          parts.push(`【完整聊天记录】
${ms.map(m => {
            const role = m.role === 'user'
              ? '用户'
              : (m.role === 'assistant' ? 'AI' : '系统');

            const name = m.name ? `/${m.name}` : '';
            const hidden = m.is_hidden ? '（隐藏楼层）' : '';

            return `【第${m.message_id}楼 ${role}${name}${hidden}】
${m.message || ''}`;
          }).join('\n\n')}`);
        }
      }
    } catch (e) {
      husouDiag('上下文:聊天记录读取失败', { messageId: mid, error: husouErrorInfo(e) }, 'error');
    }

    const result = parts.join('\n\n');
    husouDiag('上下文:构建完成', { messageId: mid, sectionCount: parts.length, totalLength: result.length }, result ? 'info' : 'warn');
    return result;
  }

