      api.temperature = parseFloat(s.customTemperature);
    }

    if (s.customTopP !== '' && !isNaN(parseFloat(s.customTopP))) {
      api.top_p = parseFloat(s.customTopP);
    }

    if (s.customTopK !== '' && !isNaN(parseFloat(s.customTopK))) {
      api.top_k = parseFloat(s.customTopK);
    }

    if (s.customFrequencyPenalty !== '' && !isNaN(parseFloat(s.customFrequencyPenalty))) {
