  async function husouGenerateTaskOrdered(ordered_prompts, s, taskName = 'husou_ai_task') {
    const gr = getFn('generateRaw');
    if (typeof gr !== 'function') throw new Error('无 generateRaw');

    const oldTopBusy = topWindow.__searchEngineBusy;
    const oldWinBusy = window.__searchEngineBusy;

    topWindow.__searchEngineBusy = true;
    window.__searchEngineBusy = true;

    try {
      const activeTaskName = ssActiveTasks.has('husou_search')
        ? 'husou_search'
        : taskName;

      // 🦊 附加参数（YAML）：仅 analysisApi === 'custom' 时附加
      const __extraInject = (s && s.analysisApi === 'custom')
        ? ssBuildExtraInjectFromCustomApi({
          extraBodyParamsYaml: s.customExtraBodyParamsYaml,
          excludeBodyParamsYaml: s.customExcludeBodyParamsYaml,
          extraHeadersYaml: s.customExtraHeadersYaml,
        })
        : null;

      const customApi = husouBuildAiCustomApi(s);
      // 🦊 修复：从 'all' 改为限制 10 楼，防止 token 爆炸
      const husouContextFloors = (() => {
        const v = parseInt(localStorage.getItem('SPreset_HusouContextFloors'));
        return Number.isFinite(v) && v > 0 ? v : 10;
      })();
      const r = await ssGenerateRaw(activeTaskName, {
        user_input: '',
        should_silence: true,
        should_stream: false,
        max_chat_history: husouContextFloors,

        ordered_prompts: ordered_prompts.filter(Boolean),

        // 不限制狐搜 AI 分析输出长度
        ...(customApi ? { custom_api: customApi } : {}),

        ...(__extraInject ? { __ssExtraInject: __extraInject } : {}),
      }, '狐搜 AI 分析');

      return typeof r === 'string' ? r : r?.content || '';
    } finally {
      topWindow.__searchEngineBusy = oldTopBusy;
      window.__searchEngineBusy = oldWinBusy;
    }
  }

