  async function husouFilterResults(searchResults, s, keywords = [], externalSignal = null) {
    if (!searchResults.size) {
      husouDiag('过滤:跳过', { reason: 'raw_search_map_empty' }, 'warn');
      return new Map();
    }

    const currentKeywordLine = husouKeywordsLine(
      keywords?.length ? keywords : [...searchResults.keys()]
    );

    let enrichedResults = new Map(searchResults);
    husouDiag('过滤:开始', {
      rawCount: searchResults.size, keywords,
      aiFilter: s.aiFilter !== false, jinaFetch: !!s.enableJinaFetch, jinaPrefilter: s.enableJinaPrefilter !== false,
      rawCharacters: [...searchResults.values()].reduce((sum, value) => sum + String(value || '').length, 0),
    }, 'info');

    // ==================== Jina 抓取网页全文逻辑：先 AI 预筛选，再抓全文 ====================
    if (s.enableJinaFetch) {
      try {
        const pageTimeout = Number(s.jinaPageTimeout || 20000);

        // 1. 先让 AI 看原始搜索摘要，判断哪些 URL 值得 Jina 抓全文
        //    只有开启 AI过滤时才进行前置筛选；如果用户关闭 AI过滤，则保持旧逻辑。
        let jinaSourceResults = enrichedResults;

        if (s.aiFilter !== false && s.enableJinaPrefilter !== false) {
          jinaSourceResults = await husouPrefilterJinaFetchTargets(enrichedResults, s, keywords);
          enrichedResults = new Map(jinaSourceResults);
        }

        // 2. 只抓 AI 批准后仍保留的 URL
        for (const [kw, text] of jinaSourceResults) {
          const urls = [...String(text || '').matchAll(/🔗\s+(https?:\/\/[^\s]+)/g)]
            .map(m => husouNormalizeJinaUrl(m[1]))
            .filter(Boolean);

          log(`Jina 准备抓取「${kw}」URL数量:`, urls.length, urls, `单页超时=${pageTimeout}ms`);

          const fetchedTexts = [];

          for (const url of urls) {
            const content = await husouFetchPageWithJina(url, externalSignal, s);

            if (content) {
              const clean = content
                .replace(/\n{3,}/g, '\n\n')
                .trim();

              fetchedTexts.push(`--- 来自 ${url} ---\n${clean}`);
            } else {
              log(`Jina 未抓到内容：${url}`);
            }
          }

          if (fetchedTexts.length) {
            enrichedResults.set(
              kw,
              text + '\n\n【网页全文】\n' + fetchedTexts.join('\n\n')
            );

            log(`Jina 已追加全文「${kw}」全文段数:`, fetchedTexts.length);
          } else {
            log(`Jina 没有抓到可用全文「${kw}」`);
          }
        }
      } catch (e) {
        husouDiag('Jina:抓取阶段失败并回退', { error: husouErrorInfo(e) }, 'error');
      }
    }

    // 如果不开 AI过滤，也返回 Jina 增强后的结果，而不是原始搜索摘要。
    if (!s.aiFilter) {
      husouDiag('过滤:跳过AI过滤', { outputCount: enrichedResults.size }, 'info');
      return enrichedResults;
    }
    let existing = '';

    try {
      existing = husouGetExistingInjection();


    } catch (e) {
      husouDiag('过滤:已有资料读取失败', { error: husouErrorInfo(e) }, 'error');
