- 然后按顺序输出各维度，格式：**维度名称**：内容
- 无新增信息的维度写：（本次无新增）
- 最后不要加总结或解释`;

    const user = `请对比新旧内容，只输出本次新增的信息。
只允许输出以下两种格式之一：

如果有新信息，输出：
# 知识库开始
# 条目开始
# 名称
角色名
# 说明
新增的核心信息...
# 条目结束

# 条目开始
# 名称
角色名
# 说明
新增的核心信息...
# 条目结束

（多内容以此类推，禁止跳过！只要出现角色、设定、未知名词，都必须进行总结！）
# 知识库结束

如果没有任何新信息，必须严格输出：
# 知识库开始
# 无新增
# 知识库结束

不要解释，不要输出旧内容。`;

    try {
      husouDiag('过滤:AI请求开始', { inputCharacters: raw.length, existingKnowledgeLength: existing.length, keywordCount: husouNormalizeKeywords(keywords).length }, 'info');
      const text = await husouGenerateTask({ system, user }, s);
      const normalized = String(text || '').trim();
      husouDiag('过滤:AI响应', { responseLength: normalized.length, responsePreview: normalized.slice(0, 500) });

      if (!normalized) throw husouMakeError('FILTER_MODEL_EMPTY', 'AI 过滤模型返回空文本');

      // 提取 # 知识库开始 ... # 知识库结束 之间的内容
      const kbMatch = normalized.match(/#\s*知识库开始\s*\n([\s\S]*?)(?:#\s*知识库结束|$)/i);
      if (!kbMatch) {
        throw husouMakeError('FILTER_PROTOCOL_MISSING', 'AI 过滤响应缺少"# 知识库开始"标记', { responsePreview: normalized.slice(0, 500) });
      }
      const content = kbMatch[1].trim();
      // 检查无新增
      if (!content || /#\s*无新增/i.test(content)) {
        husouDiag('过滤:正常无新增', { reason: !content ? 'empty_content' : 'model_declared_no_new_info', rawCount: searchResults.size }, 'warn');
        return new Map();
      }
      // 解析 # 条目开始 ... # 条目结束 块
      const itemRe = /#\s*条目开始\s*\n([\s\S]*?)#\s*条目结束/gi;
      const map = new Map();
      let im;
      while ((im = itemRe.exec(content)) !== null) {
        const blockText = im[1].trim();
        const nameMatch = blockText.match(/#\s*名称\s*\n(.+)/i);
        const descMatch = blockText.match(/#\s*说明\s*\n([\s\S]*)/i);
        const name = nameMatch ? nameMatch[1].trim() : '';
        const body = descMatch ? descMatch[1].trim() : '';
        if (!name || !body) continue;
        if (/无可用信息|无相关信息|全部无关|完全无关|discard|irrelevant/i.test(body)) continue;
        map.set(name, body);
      }

      if (!map.size) {
        throw husouMakeError('FILTER_SECTIONS_EMPTY', 'AI 过滤有内容但没有可解析的“关于某项的说明”条目', { responsePreview: normalized.slice(0, 500) });
      }

      husouDiag('过滤:完成', { rawCount: searchResults.size, outputCount: map.size, outputNames: [...map.keys()] }, 'info');
      return map;
    } catch (e) {
      husouDiag('过滤:失败', { error: husouErrorInfo(e) }, 'error');
      throw e;
    }
  }
  async function husouSaveToChar(filtered) {
    if (!filtered?.size) {
      husouDiag('保存:跳过', { reason: 'filtered_map_empty' }, 'warn');
      return { localSaved: false, personalitySaved: false };
    }
    const ts = new Date().toISOString().split('T')[0];
    const s = state.husouSettings || (state.husouSettings = loadHusouSettings());
    const result = { localSaved: false, personalitySaved: false };
    husouDiag('保存:开始', {
      entryCount: filtered.size, entryNames: [...filtered.keys()],
      saveToLocal: !!s.saveToHusouLocal, saveToPersonality: !!s.saveToPersonality,
    }, 'info');

    // 🆕 批次 3C：先存到 localStorage（按角色卡隔离）
    if (s.saveToHusouLocal) {
      try {
        const charId = getCurrentCharId();
        const key = `SPreset_HusouLocal_${encodeURIComponent(charId)}`;
        const existing = JSON.parse(localStorage.getItem(key) || '{"blocks":[]}');
        const blockText = husouMapToPlainText(filtered);
        existing.blocks.push({ ts, content: blockText });
        if (existing.blocks.length > 30) existing.blocks = existing.blocks.slice(-30);
        localStorage.setItem(key, JSON.stringify(existing));
        log(`[狐搜] 已存到 localStorage（${charId}），共 ${existing.blocks.length} 块`);
        result.localSaved = true;
        husouDiag('保存:localStorage完成', { charId, storageKey: key, blockCount: existing.blocks.length, addedCharacters: blockText.length }, 'info');
      } catch (e) {
        husouDiag('保存:localStorage失败', { error: husouErrorInfo(e) }, 'error');
        throw husouMakeError('SAVE_LOCAL_FAILED', '狐搜结果写入 localStorage 失败', { cause: e.message });
      }
    }

    // 原行为：保存到 personality
    if (!s.saveToPersonality) {
      husouDiag('保存:完成', result, 'info');
      return result;
    }
    try {
      const ctx = SillyTavern?.getContext?.(); const char = ctx?.characters?.[ctx?.characterId];
      if (!char) throw husouMakeError('SAVE_CHARACTER_MISSING', '无法取得当前角色卡，不能写入 personality');
      const entries = [...filtered].map(([n, c]) => `【关于「${n}」的说明】\n${c}`);
      const keywordLine = husouKeywordsLine(
        state.husouCurrentKeywords?.length
          ? state.husouCurrentKeywords
          : [...filtered.keys()]
      );

      const blockBody = `${entries.join('\n\n')}${keywordLine ? `\n\n${keywordLine}` : ''}`;
      const block = `\n\n${ssBuildSearchResultsInject(blockBody)}`; let newP = char.personality || ''; newP = (newP ? newP + '\n' : '') + block; char.personality = newP; const ee = getFn('eventEmit'); const evt = tavern_events?.CHARACTER_EDITED; if (ee && evt) await ee(evt, { detail: { id: ctx.characterId, character: char } });
      result.personalitySaved = true;
      husouDiag('保存:personality完成', { characterId: ctx.characterId, appendedCharacters: block.length, eventEmitted: !!(ee && evt) }, 'info');
    } catch (e) {
      husouDiag('保存:personality失败', { error: husouErrorInfo(e) }, 'error');
      throw e?.code ? e : husouMakeError('SAVE_PERSONALITY_FAILED', '狐搜结果写入角色卡 personality 失败', { cause: e.message });
    }
    husouDiag('保存:完成', result, 'info');
    return result;
  }

  function husouFormatMapForDebug(map) {
    if (!map?.size) return '';

    return [...map]
      .map(([k, v]) => `===== ${k} =====\n${v}`)
      .join('\n\n');
