  function husouUpdateKeywordPanel(keywords) {
    const panel = topDoc.getElementById('husou_keyword_panel');
    const list = topDoc.getElementById('husou_keyword_list');
    const count = topDoc.getElementById('husou_keyword_count');

    if (!panel || !list || !count) return;

    if (!keywords || !keywords.length) {
      panel.style.display = 'none';
      return;
    }

    panel.style.display = 'block';
    count.textContent = `共 ${keywords.length} 个`;
    list.textContent = keywords.join('、');

    clearTimeout(panel._hideTimer);
    panel._hideTimer = setTimeout(() => {
      panel.style.display = 'none';
    }, 8000);
  }

  function husouHasBaseSearchSource(s) {
    return !!(s.enableWikipedia || s.enableMoegirl || s.enableCustomSearch);
  }

  async function husouManualSearch(messageId, opts = {}) {
    state.husouLastHandledId = null;
    return husouExecuteSearch(messageId, {
      manual: true,
      triggerButton: opts.triggerButton || null,
    });
  }

  async function husouManualKeywordSearch(keywordText = '', opts = {}) {
    let input = String(keywordText || '').trim();

    if (!input) {
      input = topWindow?.prompt
        ? topWindow.prompt('请输入要搜索的关键词，可用逗号、顿号、换行分隔：\n例如：原神 可莉、原神 琴')
        : prompt('请输入要搜索的关键词，可用逗号、顿号、换行分隔：\n例如：原神 可莉、原神 琴');
    }

    const keywords = husouNormalizeKeywords(input);

    if (!keywords.length) {
      toast('未输入关键词', 'warning');
      return;
    }

    const lastId = getFn('getLastMessageId')?.();

    state.husouLastHandledId = null;

    return husouExecuteSearch(lastId, {
      manual: true,
      keywords,
      triggerButton: opts.triggerButton || null,
    });
  }

  function husouMapToPlainText(map) {
    if (!map?.size) return '';

    const secs = [...map].map(([n, c]) => `【关于「${n}」的说明】\n${c}`);

    const keywordLine = husouKeywordsLine(
      state.husouPendingKeywords?.length
        ? state.husouPendingKeywords
        : state.husouCurrentKeywords
    );

    return `${secs.join('\n\n')}${keywordLine ? `\n\n${keywordLine}` : ''}`.trim();
  }

  function husouBuildInjectBlock(map) {
    const body = husouMapToPlainText(map);

    if (!body) return '';

    return `\n\n${ssBuildSearchResultsInject(body)}\n`;
  }

  function husouInjectIntoPromptArray(arr) {
    // 旧狐搜独立注入废弃，改走统一注入系统。
    // 统一系统会自动处理顺序：狐搜 → 狐忆 → 狐构，并插入到 </fox_extra> 后。
    ssInjectIntoPromptArrayByFoxExtra(arr);
  }

  async function husouRunSearchFlow(messageId) {
    return xhEnqueueAutoTask(
      'husou_auto_search',
      '狐搜自动搜索',
      () => husouExecuteSearch(messageId, { manual: false }),
      { dedupe: true }
    );
  }

  function husouUnbindListeners() {
    state.husouRegisteredListeners.forEach(h => {
      try {
        if (typeof h === 'function') h();
        else h?.stop?.();
      } catch { }
    });

    state.husouRegisteredListeners = [];
  }

  function husouRegisterListeners() {
    const eo = getFn('eventOn');
    const emf = getFn('eventMakeFirst');
    const te = getFn('tavern_events') || tavern_events;

    if (typeof eo !== 'function' || !te) return;

    husouUnbindListeners();
    try { husouLoadAutoCounter(); } catch {}

    const add = h => {
      if (h) state.husouRegisteredListeners.push(h);
    };

    if (te.GENERATION_ENDED) {
      add(eo(te.GENERATION_ENDED, (eventMessageId, eventType) => {
        if (xhCurrentGenerationIsInternal || xhInternalGenerationDepth > 0) return;
        const resolved = xhResolveAssistantMessage(eventMessageId);
        const messageId = resolved.id;
        const type = String(eventType || xhGetLastGenerationType() || 'normal').toLowerCase();
        if (messageId < 0 || !['normal', 'regenerate', 'swipe', 'reroll'].includes(type)) return;
        setTimeout(async () => {
          const stable = await foxMemoryWaitForStableAssistantMessage(messageId, {
            scope: getFoxMemoryScopeId(),
            epoch: state.foxMemoryBranchEpoch,
          });
          if (stable) husouRunSearchFlow(messageId);
        }, 900);
      }));
    }

    if (te.CHAT_COMPLETION_PROMPT_READY) {
      add(eo(te.CHAT_COMPLETION_PROMPT_READY, d => {
        if (Array.isArray(d?.chat) && ssShouldInjectForPromptEvent(d, d.chat)) {
          husouInjectIntoPromptArray(d.chat);
        }
      }));
    }

    if (te.GENERATE_AFTER_DATA) {
      const fn = (d, dry) => {
        if (Array.isArray(d?.prompt) && ssShouldInjectForPromptEvent(d, d.prompt, dry)) {
          husouInjectIntoPromptArray(d.prompt);
        }
      };

      if (typeof emf === 'function') {
        emf(te.GENERATE_AFTER_DATA, fn);

        state.husouRegisteredListeners.push({
          stop: () => getFn('eventRemoveListener')?.(te.GENERATE_AFTER_DATA, fn),
        });
      } else {
        add(eo(te.GENERATE_AFTER_DATA, fn));
      }
    }

    if (te.GENERATE_AFTER_COMBINE_PROMPTS) {
      add(eo(te.GENERATE_AFTER_COMBINE_PROMPTS, r => {
        if (!ssShouldInjectForPromptEvent(r, r?.prompt)) return;

        if (Array.isArray(r?.prompt)) {
          ssInjectIntoPromptArrayByFoxExtra(r.prompt);
        } else if (typeof r?.prompt === 'string') {
          r.prompt = ssInjectIntoPromptStringByFoxExtra(r.prompt);
        }
      }));
    }

    if (te.GENERATION_ENDED) {
      add(eo(te.GENERATION_ENDED, () => {
        if (pwState.internalGenerating || (xhGetLastGenerationType?.() || 'normal') !== 'normal') {
          pwState.pendingInjectedModuleIds = [];
          pwState.pendingOneShotInjectConsume = false;
        }
        // 本次生成结束后，清理只用于“下一次请求”的 pending 搜索内容。
        // localStorage 内容不清理，后续仍可按角色卡注入。
        if (state.husouPendingConsumed) {
          state.husouPendingInject = null;
          state.husouPendingKeywords = [];
          state.husouPendingConsumed = false;
          log('[狐搜] 本次 pending 搜索注入已在生成结束后清理');
        }
      }));
    }

    if (te.MESSAGE_RECEIVED) {
      add(eo(te.MESSAGE_RECEIVED, (messageId, type) => {
        if (xhIsInternalMessageEvent(type)) return;
        try { pwCommitPendingInjectedModules(messageId, type); } catch (e) { log('[平行世界·轮次生命周期] 提交失败', e); }
      }));
    }

    if (te.CHAT_CHANGED) {
      add(eo(te.CHAT_CHANGED, () => {
        // ✅ 流式恢复已迁移到 ssRestoreStreamPreferenceIfNeeded（基于 localStorage 偏好）
        state.foxMemoryBranchEpoch++;
        state.foxMemoryPendingBranchCheckpoint = null;
        state.husouPendingInject = null;
        state.husouPendingKeywords = [];
        state.husouPendingConsumed = false;
        state.husouCurrentKeywords = [];
        state.husouLastHandledId = null;
        state.husouIsRunning = false;

        foxPushIsProcessing = false;
        foxPushSkipNext = false;
        foxMemoryGenCounter = 0;
        foxMemoryLastAutoAnalyzeMessageId = null;
        foxMemoryAutoScheduledReplies.clear();
        // 🦊 修复：清零后立刻持久化旧作用域计数器，避免旧值之后被重新读回导致计数"回跳"
        try { foxMemorySaveAutoCounter(); } catch {}
        husouGenCounter = 0;
        husouLastAutoSearchMessageId = null;
        try { husouSaveAutoCounter(); } catch {}

        // 🦊 切聊天/角色时清空狐裁思维链缓存与拦截锁，防止旧聊天思维链注入新聊天 / 卡发送。
        try {
          foxJudgeLastCombined = '';
          foxJudgePendingInject = '';
          // 🦊 切聊天必清 preserved——上一聊天的思维链显然不能复用到新聊天里
          foxJudgePreservedChain = '';
          foxJudgeRethinkPending = false;
          foxJudgeInterceptProcessing = false;
          foxJudgeInterceptSkipNext = false;
        } catch { }

        // 🦊 狐忆注入 toast 去重签名按聊天作用域失效，避免新聊天误判为重复而漏弹。
        state.__foxMemInjectToastSig = '';
        state.__foxMemInjectToastTs = 0;

        pwState.autoCounter = 0;
        pwState.lastAutoMessageId = null;
        try { pwSaveAutoCounter(); } catch {}
        pwState.branchEpoch++;
        pwState.runGuard = null;
        pwState.autoScheduledReplies?.clear?.();

        // 🦊 关键修复：换聊天/新聊天后，狐忆切换到新的聊天隔离库。
        // 如果关闭"注入到预设"，就立刻关闭预设条目，防止旧聊天记忆残留。
        setTimeout(async () => {
          try {
            foxMemoryConfig = loadFoxMemoryConfig();
            foxMemoryLoadAutoCounter();
            try { foxMemoryRebaseLegacyDynamicSources(); } catch (migrationError) { foxMemoryV2Log('旧动态来源修正失败', migrationError?.message || migrationError); }

            if (foxMemoryConfig.injectToPreset) {
              await foxMemorySyncToPreset(true);
            } else {
              await foxMemoryDisablePresetInject();
            }

            try { foxMemoryRenderList(); } catch { }
            try { foxMemoryRenderStats(); } catch { }
          } catch (e) {
            log('[狐忆] CHAT_CHANGED 后同步失败', e);
          }

          try {
    state.outlineText = outlineLoadCurrentText();

    // 按角色卡恢复动态修正状态：大纲为空则强制关闭
    {
      const hasOutline = !!outlineLoadLocalRaw().trim();
      if (!hasOutline) {
        state.outlineAutoAnalysis = false;
      } else {
        state.outlineAutoAnalysis = localStorage.getItem(outlineGetAutoKey()) === 'true';
      }
    }
            state.outlineLastAnalyzedId = -1;
            log(`[狐构] CHAT_CHANGED 后已重新加载聊天隔离大纲，动态修正=${state.outlineAutoAnalysis}`);
            // 📌 切聊天后同步 <fox_hugou> 条目状态（照抄狐刻 ftSyncPromptEntry 模式）
            try {
              outlineSyncPromptEntry(state.outlineAutoAnalysis, '');
            } catch (e) { log('[狐构] CHAT_CHANGED 后同步 <fox_hugou> 条目失败', e); }
          } catch (e) {
            log('[狐构] CHAT_CHANGED 后重载大纲失败', e);
          }

          try {
            // ✅ 切聊天瞬间，先把内存中的旧数据立刻清空，避免在 chatId 还没到位前
            //    渲染层读到上一聊天的"幽灵"内容；随后由 pwLoadData() 重新按当前
            //    (charId, chatId) 加载，并由 boundCharId/boundChatId 校验。
            pwState.data = null;
            pwState.autoCounter = 0;
            pwState.lastAutoMessageId = null;
            pwState.pendingOneShotInjectConsume = false;

            // 清理 localStorage 里早期 chatId 不就绪导致残留的 __PENDING__ key
            try { pwCleanupPendingKeys?.(); } catch { }

            pwState.data = pwLoadData();
            pwLoadAutoCounter();

            // 重新渲染面板和状态浮窗（如果存在的话），让显示与新聊天数据一致
            try { pwRenderPanel?.(); } catch { }
            try { pwRenderStateFloat?.(); } catch { }

            log('[平行世界] CHAT_CHANGED 后已重新加载聊天隔离数据');
          } catch (e) {
            log('[平行世界] CHAT_CHANGED 后重载数据失败', e);
          }

          // 🕰️ 狐刻：切聊天/角色卡后重新加载聊天隔离数据，重注册监听器，重挂悬浮窗
          //    之前缺失这段导致"切换角色卡后狐刻状态全丢、悬浮窗不恢复、自动解析不触发"
          try {
            // 先卸载旧悬浮窗（旧 DOM 可能已被酒馆重建）
            try { if (typeof ftTimelineUnmount === 'function' && ftTL.el) ftTimelineUnmount(); } catch {}

            // 重新加载当前聊天的配置和数据
            ftState.config = ftLoadConfig();
            ftState.data = ftLoadData();
            ftState.autoCounter = 0;
            ftState.lastCorrectFloor = 0;
            ftState.branchEpoch = 0;

            // 重新注册自动监听器（enabled 时注册，否则跳过）
            try { ftRegisterAutoListener(); } catch (e) { log('[狐刻] CHAT_CHANGED 后注册监听失败', e); }

            // 如果狐刻启用且悬浮窗没被手动关闭，重新挂载悬浮窗
            if (ftState.config?.enabled && localStorage.getItem('ft-tl-closed') !== '1') {
              try { if (typeof ftTimelineMount === 'function' && !ftTL.el) ftTimelineMount(); } catch (e) { log('[狐刻] CHAT_CHANGED 后重挂悬浮窗失败', e); }
            }

            // 如果面板打开着，刷新一下
            try { if (topDoc.getElementById('ft-panel')) ftRenderPanel(); } catch {}

            log('[狐刻] CHAT_CHANGED 后已重新加载聊天隔离数据');
          } catch (e) {
            log('[狐刻] CHAT_CHANGED 后重载失败', e);
          }

          // 🦊 修复流式传输：新预设加载后检查 should_stream 是否被重置为关
          //    若切换前是开的、切换后变成关，自动恢复并提示用户
          // ✅ 改为使用 ssRestoreStreamPreferenceIfNeeded：覆盖"用户有偏好但被预设重置"的所有场景
          try {
            await ssRestoreStreamPreferenceIfNeeded('切换角色卡/聊天');
          } catch (e) { log('[流式修复] 恢复失败', e); }
          // ✅ 二次延迟检查：350ms 可能早于新预设完全加载，800ms 再检查一次
          setTimeout(() => { ssRestoreStreamPreferenceIfNeeded('切换角色卡/聊天(延迟)'); }, 800);

          // 🦊 修复狐忆自动推进：切聊天后酒馆重建 #send_but / #send_textarea，
          //    capture 阶段监听器随旧 DOM 丢失导致"只触发一次"。这里重新注册。
          try {
            if (foxMemoryConfig.autoPush) {
              registerFoxPushListener();
              log('[推进] CHAT_CHANGED 后已重新注册 capture 拦截器');
            }
          } catch (e) { log('[推进] CHAT_CHANGED 后重注册失败', e); }
        }, 350);
      }));
    }
  }


  async function husouClearInjection() {
    try {
      const beforeLocal = husouLoadLocalText();

      // 1. 清当前角色卡 localStorage + 所有狐搜 localStorage 残留
      husouClearLocalStorage();
      husouClearAllLocalStorageKeys();

      // 2. 清 char personality 里的新版/旧版/孤儿残留
      const clearedChar = await husouClearCharPersonalityInjection();

      // 3. 清下一次 prompt pending
      state.husouPendingInject = null;
      state.husouPendingKeywords = [];
      state.husouCurrentKeywords = [];
      state.husouPendingConsumed = false;
      state.husouLastHandledId = null;

      // 4. 清监控显示
      state.husouDebug.injectText = '';
      state.husouDebug.filteredText = '';
      state.husouDebug.rawText = '';
      state.husouDebug.keywords = [];
      state.husouDebug.status = 'idle';
      state.husouDebug.lastError = '';

      try { husouUpdateQuickPanel(); } catch { }

      refreshAnyHusouPanel();

      if (beforeLocal || clearedChar) {
        toast('🧹 已清除狐搜：localStorage + char personality 残留 + 本次待注入内容', 'success');
      } else {
        toast('🧹 没有 localStorage 内容，但已检查并清理 char personality 残留', 'info');
      }
    } catch (e) {
      log('[狐搜] 清除失败', e);
      toast(`清除失败：${e.message || e}`, 'error');
    }
  }


  async function husouInjectCustom(text) {
    const value = String(text || '').trim();

    if (!value) {
      toast('内容为空', 'warning');
      return;
    }

    try {
      const s = state.husouSettings || (state.husouSettings = loadHusouSettings());

      // 1. 默认保存到当前角色卡 localStorage
      husouSaveLocalText(value);

      // 2. 如果用户手动打开“保存结果到 char personality”，才写角色卡
      if (s.saveToPersonality) {
        const ctx = SillyTavern?.getContext?.();
        const char = ctx?.characters?.[ctx?.characterId];

        if (char) {
          const cleaned = husouStripSearchInjectionFromPersonality(char.personality || '');
          const block = `\n\n${ssBuildSearchResultsInject(value)}`;

          char.personality = `${cleaned ? cleaned + '\n' : ''}${block}`.trim();

          const ee = getFn('eventEmit');
          const evt = tavern_events?.CHARACTER_EDITED;

          if (ee && evt) {
            await ee(evt, {
              detail: {
                id: ctx.characterId,
                character: char,
              },
            });
          }
        }
      } else {
        // 如果关闭保存到 personality，顺手清掉旧残留，避免你看到上一个角色卡的搜索内容
        await husouClearCharPersonalityInjection();
      }

      // 3. 手动保存的内容也作为下一次 prompt 可注入内容
      state.husouPendingInject = new Map([['手动注入', value]]);
      state.husouPendingKeywords = ['手动注入'];

      refreshAnyHusouPanel();

      toast(
        s.saveToPersonality
          ? '✅ 已保存狐搜内容到 localStorage，并同步到 char personality'
          : '✅ 已保存狐搜内容到当前角色卡 localStorage',
        'success'
      );
    } catch (e) {
      log('[狐搜] 保存/注入失败', e);
      toast(`注入失败：${e.message || e}`, 'error');
    }
  }

  function getHusouModelOptionsHtml(selected) {
    if (!state.husouRuntimeModels.length) return `<option value="">暂无模型列表</option>`;
    return [`<option value="">（从列表选择）</option>`, ...state.husouRuntimeModels.map(m => `<option value="${escapeHtml(m)}" ${m === selected ? 'selected' : ''}>${escapeHtml(m)}</option>`)].join('');
  }
  function getHusouPresetOptionsHtml(selected) {
    try { const fn = getFn('getPresetNames'); if (typeof fn !== 'function') return `<option value="">无可用预设</option>`; const names = fn().filter(x => x !== 'in_use').sort((a, b) => a.localeCompare(b, 'zh-Hans-CN')); if (!names.length) return `<option value="">无可用预设</option>`; return names.map(n => `<option value="${escapeHtml(n)}" ${n === selected ? 'selected' : ''}>${escapeHtml(n)}</option>`).join(''); } catch { return `<option value="">无可用预设</option>`; }
  }
  function refreshHusouInjectionManager(panel) {
    const ta = panel.querySelector('#injection_manager_textarea');
    if (!ta) return;

    const localText = husouLoadLocalText();

