    // 3. 狐搜监控里的过滤后内容
    const displayText = localText || pendingText || debugFilteredText || '';

    ta.value = displayText;

    const st = panel.querySelector('#injection_manager_status');
    if (st) {
      if (localText) {
        st.textContent = `已从当前角色卡 localStorage 加载 ${localText.length} 字符`;
      } else if (pendingText) {
        st.textContent = `当前显示的是本轮待注入内容，尚未写入 localStorage。点击“保存修改”即可保存到当前角色卡 localStorage。`;
