    function paint(btn, active) {
      btn.style.background = active ? 'rgba(232,120,74,0.25)' : 'transparent';
      btn.style.color = active ? '#f0a070' : '#555';
    }

    function up() {
      const lOn = isPromptEnabledInPreset(lId);
      const rOn = isPromptEnabledInPreset(rId);

      paint(lB, lOn);
      paint(rB, rOn);
    }

    lB.onclick = async () => {
      await togglePromptById(lId, true);
      await togglePromptById(rId, false);
      up();
      if (onChange) onChange('left');
