html.xh-perf :is(#ss-dashboard,#ss-float-bubble,#ss-hushen-panel,#ss-husou-panel,#ss-foxmemory-panel,#ss-novel-panel,#ss-outline-panel,#ss-foxjudge-panel,#ss-style-analysis-panel,#ss-beat-memory-panel,#ss-custom-edit-panel,#ss-hushen-mgr-panel,#pw-panel,#ft-panel,.fox-image-panel,#xh-dock,#ss-dash-overlay) *::before,
