#ss-dashboard.xh-workbench .xh-mobile-util-row small{display:block;color:#706058;font-size:10px!important;margin-top:3px;line-height:1.4;}
#ss-dashboard.xh-workbench .xh-mobile-ios-switch{position:relative;width:44px;height:24px;flex:0 0 44px;border:1px solid rgba(255,255,255,.09);border-radius:99px;padding:0;background:rgba(255,255,255,.08);cursor:pointer;transition:all .25s;}
