#ss-dashboard.xh-workbench .xh-mobile-tab{flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;padding:5px 0 3px;color:#706058;font-size:10px;border-radius:11px;cursor:pointer;position:relative;transition:color .2s;}
