#ss-dashboard.xh-workbench .xh-mobile-tab.act::after{content:"";position:absolute;bottom:-1px;width:16px;height:3px;border-radius:3px;background:linear-gradient(90deg,#f0a070,#e8784a);box-shadow:0 0 8px rgba(232,120,74,.7);}
}
`;

      // ---- 收集 header 控件与 section 标题/内容对 ----
      const headerEl = dash.firstElementChild;
      const secPairs = [];
      {
        const kids = [...dash.children];
        for (let i = 1; i < kids.length; i++) {
          const t = kids[i];
          if (!t.classList || !t.classList.contains('ss-dashboard-section-title')) continue;
          const box = (kids[i + 1] && kids[i + 1].classList && kids[i + 1].classList.contains('ss-dashboard-section-box')) ? kids[i + 1] : null;
          secPairs.push({ title: t, box, text: String(t.dataset.sectionTitle || t.textContent || '').trim() });
          if (box) i++;
        }
      }

      // ---- 页面定义（方案A：核心 / 狐系模块 / 高级）----
      const XH_PAGES = [
        { id: 'think', icon: '📡', name: '思维链流式控制', en: 'THOUGHT CHAIN', grp: '核心', dot: () => !!state.enabled },
        { id: 'quick', icon: '🔧', name: '快捷开关', en: 'QUICK TOGGLES', grp: '核心' },
        { id: 'preset', icon: '⚙️', name: '预设选项', en: 'PRESET OPTIONS', grp: '核心' },
        { id: 'mod', icon: '🦊', name: '模块中心', en: 'FOX MODULES', grp: '狐系模块', dot: () => { try { return (pwState.config || pwLoadConfig()).autoMode !== 'manual' || loadFoxMemoryConfig().autoMode !== 'manual'; } catch { return false; } } },
        { id: 'summary', icon: '📋', name: '大总结', en: 'SUMMARY', grp: '高级' },
        { id: 'misc', icon: '🧰', name: '实用工具', en: 'UTILITIES', grp: '高级' },
        { id: 'backup', icon: '💾', name: '配置备份', en: 'BACKUP', grp: '高级' },
      ];
      const xhPageOf = (text) => {
        const t = String(text || '');
        if (/思维链/.test(t)) return 'think';
        if (/快捷开关|杀八股/.test(t)) return 'quick';
        if (/预设选项/.test(t)) return 'preset';
        if (/狐构|狐忆|狐裁|狐析|狐搜|平行世界/.test(t)) return 'mod';
        if (/总结/.test(t)) return 'summary';
        if (/备份|文件存储/.test(t)) return 'backup';
        return 'misc';
      };

      // ---- 骨架：侧栏 + 主区（顶栏 + 页面内容）----
      const sideNav = topDoc.createElement('div'); sideNav.className = 'xh-dash-side';
      const navHtml = [];
      let lastGrp = '';
      for (const p of XH_PAGES) {
        if (p.grp !== lastGrp) { lastGrp = p.grp; navHtml.push(`<div class="xh-dash-nav-grp">${p.grp}</div>`); }
        navHtml.push(`<div class="xh-dash-nav-item" data-page="${p.id}"><span class="xh-dash-nav-ico">${p.icon}</span><span class="xh-dash-nav-name">${p.name}</span>${p.dot ? '<span class="xh-dash-sdot"></span>' : ''}</div>`);
      }
      sideNav.innerHTML = `<div class="xh-dash-brand"><div class="xh-dash-logo">🦊</div><div class="xh-dash-brand-t"><b>玄狐中控</b><small>XUANHU CONSOLE</small></div></div><div class="xh-dash-nav">${navHtml.join('')}</div><div class="xh-dash-side-foot"><div class="xh-perf-switch" id="xh-perf-switch"><div class="xh-perf-label"><span class="xh-perf-ico">⚡</span><div class="xh-perf-t"><b class="xh-perf-name">性能模式</b><small class="xh-perf-desc">完整美化体验</small></div></div><div class="xh-perf-toggle"><input type="checkbox" id="xh-perf-check"><i></i></div></div></div>`;
      const refreshNavDots = () => {
        sideNav.querySelectorAll('.xh-dash-nav-item').forEach(n => {
          const def = XH_PAGES.find(p => p.id === n.dataset.page);
          const dot = n.querySelector('.xh-dash-sdot');
          if (def && def.dot && dot) { try { dot.classList.toggle('on', !!def.dot()); } catch {} }
        });
      };

      const mainEl = topDoc.createElement('div'); mainEl.className = 'xh-dash-main';
      const topbar = topDoc.createElement('div'); topbar.className = 'xh-dash-topbar';
      topbar.innerHTML = `<div class="xh-crumb"><b class="xh-crumb-t">思维链控制</b><small class="xh-crumb-s">THOUGHT CHAIN</small></div><div class="xh-search">🔍<input placeholder="搜索具体功能，如：狐策"><kbd>⌘K</kbd></div>`;
      const mobileBrand = topDoc.createElement('div'); mobileBrand.className = 'xh-mobile-brand'; mobileBrand.innerHTML = '<div class="xh-mobile-logo">🦊</div><div><b>玄狐中控</b><small>XUANHU CONSOLE</small></div>';
      topbar.insertBefore(mobileBrand, topbar.firstChild);
      const contentWrap = topDoc.createElement('div'); contentWrap.className = 'xh-dash-content';
      mainEl.appendChild(topbar); mainEl.appendChild(contentWrap);

      // ---- 迁入 header 控件（字体 / Enter / 关闭→顶栏），旧大标题整体移除（避免残留遮挡侧栏）----
      if (headerEl) {
        const closeBtn = headerEl.querySelector('.ss-panel-close');
        const rangeInput = headerEl.querySelector('input[type="range"]');
        const fontCtrl = rangeInput ? rangeInput.parentElement : null;
        const enterInput = headerEl.querySelector('#ss-enter-listen-toggle');
        const enterCtrl = enterInput ? enterInput.parentElement : null;
        if (fontCtrl) { fontCtrl.classList.add('xh-topbar-font'); topbar.appendChild(fontCtrl); }
        if (enterCtrl) { enterCtrl.classList.add('xh-topbar-enter'); topbar.appendChild(enterCtrl); }
        if (closeBtn) { closeBtn.classList.add('xh-xclose'); topbar.appendChild(closeBtn); }
        headerEl.remove();
      }

      // ---- 分配各 section 到对应页面（狐系六模块不搬旧分区，由模块卡片取代，旧分区须从 dash 移除，否则残留横排挤爆布局）----
      const XH_MOD_SECTION_RE = /狐构|狐忆|狐裁|狐析|狐搜|平行世界/;
      const pageEls = {};
      for (const p of XH_PAGES) { const pg = topDoc.createElement('div'); pg.className = 'xh-page'; pg.dataset.page = p.id; contentWrap.appendChild(pg); pageEls[p.id] = pg; }
      for (const pr of secPairs) {
        if (XH_MOD_SECTION_RE.test(pr.text)) { try { pr.title.remove(); if (pr.box) pr.box.remove(); } catch {} continue; }
        const pg = pageEls[xhPageOf(pr.text)] || pageEls.misc;
        pg.appendChild(pr.title);
        if (pr.box) pg.appendChild(pr.box);
      }

      // ---- 模块中心：方案A 模块卡片 + iOS 开关（狐裁首位，平行世界蓝色）----
      try {
        const modPage = pageEls.mod;
        const modGrid = topDoc.createElement('div'); modGrid.className = 'xh-mod-grid';
        const xhSw = (on) => { const d = topDoc.createElement('div'); d.className = 'xh-sw' + (on ? ' on' : ''); return d; };
        const xhModCard = (opt) => {
          const card = topDoc.createElement('div'); card.className = 'xh-mod' + (opt.pw ? ' pw' : ''); card.dataset.mod = opt.id;
          card.innerHTML = `<div class="glow"></div><div class="top"><div class="mico">${opt.icon}</div><b>${opt.name}</b><span class="st off"></span></div><p>${opt.desc}</p><div class="ft"><span class="open">打开面板 <i>→</i></span></div>`;
          card.addEventListener('mousemove', (e) => { const r = card.getBoundingClientRect(); card.style.setProperty('--mx', (e.clientX - r.left) + 'px'); card.style.setProperty('--my', (e.clientY - r.top) + 'px'); });
          card.querySelector('.open').onclick = (e) => { e.stopPropagation(); try { opt.open(); } catch (err) { log('[模块中心] 打开面板失败:', opt.id, err); } };
          card.onclick = (e) => { if (e.target.closest('.xh-sw')) return; try { opt.open(); } catch (err) { log('[模块中心] 打开面板失败:', opt.id, err); } };
          const sw = xhSw(false); sw.onclick = (e) => { e.stopPropagation(); opt.onFlip(sw, card); };
          card.querySelector('.ft').appendChild(sw);
          card._xhRefresh = () => {
            const st = card.querySelector('.st');
            try {
              const info = opt.status();
              sw.classList.toggle('on', !!info.on);
              sw.classList.toggle('gray', !!info.gray && !info.on);
              st.textContent = info.text;
              st.classList.toggle('on', !!info.on);
              st.classList.toggle('off', !info.on);
              refreshNavDots();
            } catch {}
          };
          card._xhRefresh();
          return card;
        };

        // ⚖️ 狐裁（首位）：开关=启用内置思维链；配置了快速模式则标记 🚀快速模式
        modGrid.appendChild(xhModCard({
          id: 'foxjudge', icon: '⚖️', name: '狐裁', desc: '五狐裁决 · 额外思维链大幅提升正文质量',
          open: () => openFoxJudgePanel(),
          status: () => { const c = foxJudgeReadConfig() || {}; return { on: !!c.enabled, text: c.enabled ? (c.phase1Only ? '🚀快速模式' : '已启用') : '未启用' }; },
          onFlip: async () => { const c = foxJudgeReadConfig() || {}; await foxJudgeSetEnabled(!c.enabled); },
        }));

        // 📋 狐构：开关=动态修正；未注入大纲时闪红振动 + 递进提醒 + 连点锁死
        const outlineDenyToasts = ['🦊你还没有生成大纲哦~先进入面板注入一份大纲再打开吧……', '🦊别点啦……先进面板生成大纲后才能启用修正呀……', '🦊喂喂……先去面板里生成大纲好吗？', '🦊嗯……', '🦊……你是故意找茬，是不是？', '🦊别点啦！！！', '🦊好吧好吧……你就点吧', '🦊……', '🦊……', '🦊……'];
        let outlineDenyCount = 0, outlineLocked = false;
        modGrid.appendChild(xhModCard({
          id: 'outline', icon: '📋', name: '狐构', desc: '剧情大纲 · 长线叙事不乱编',
          open: () => openOutlinePanel(),
          status: () => { const has = !!outlineLoadLocalRaw().trim(); return { on: !!state.outlineAutoAnalysis, gray: !has, text: state.outlineAutoAnalysis ? '动态修正中' : (has ? '未启用' : '无大纲') }; },
          onFlip: (sw, card) => {
            // 🦊 若大纲已注入则自动解除连点锁死（无感恢复，无需重开工作台）
            if (outlineLocked) {
              if (outlineLoadLocalRaw().trim()) { outlineLocked = false; outlineDenyCount = 0; sw.classList.remove('locked'); }
              else { toast('🦊点不动了吧？哼哼……下次脚本出BUG了我就告诉G一串是你点按钮点坏的~( *︾▽︾)', 'warning'); return; }
            }
            const has = !!outlineLoadLocalRaw().trim();
            if (!has) {
              outlineDenyCount++;
              sw.classList.remove('deny'); void sw.offsetWidth; sw.classList.add('deny');
              if (outlineDenyCount > outlineDenyToasts.length) {
                outlineLocked = true; sw.classList.add('locked');
                toast('🦊点不动了吧？哼哼……下次脚本出BUG了我就告诉G一串是你点按钮点坏的~( *︾▽︾)', 'warning');
              } else {
                toast(outlineDenyToasts[outlineDenyCount - 1], 'warning');
              }
              return;
            }
            state.outlineAutoAnalysis = !state.outlineAutoAnalysis;
            try { localStorage.setItem(outlineGetAutoKey(), state.outlineAutoAnalysis ? 'true' : 'false'); } catch {}
            if (state.outlineAutoAnalysis) {
              state.outlineBackgroundSilent = true;
              try { localStorage.setItem(CONFIG.OUTLINE_BACKGROUND_SILENT_KEY, 'true'); } catch {}
              try { registerOutlineAutoListener(); } catch {}
              // 📌 狐构启用时自动开启并写入"大纲阶段输出"预设条目（照抄狐刻 ftSyncPromptEntry 模式）
              try { outlineSyncPromptEntry(true, ''); } catch (e) { log('[狐构] 开启大纲阶段条目失败', e); }
              toast('📋 狐构动态修正已开启 + 后台静默更新 + <fox_hugou>条目已自动开启', 'success');
            } else {
              // 📌 狐构关闭时自动关闭"大纲阶段输出"预设条目
              try { outlineSyncPromptEntry(false, ''); } catch (e) { log('[狐构] 关闭大纲阶段条目失败', e); }
              toast('📋 狐构动态修正已关闭 + <fox_hugou>条目已自动关闭', 'info');
            }
            card._xhRefresh();
          },
        }));

        // 🧠 狐忆：开关=自动分析（默认每次回复）；面板配置隔N楼则标记 隔N楼分析
        modGrid.appendChild(xhModCard({
          id: 'foxmem', icon: '🧠', name: '狐忆', desc: '长期记忆库 · 自动提炼关键事件，跨楼层记住你的故事',
          open: () => openFoxMemoryPanel(),
          status: () => { const c = loadFoxMemoryConfig(); if (c.autoMode === 'auto') return { on: true, text: '自动分析' }; if (c.autoMode === 'interval') return { on: true, text: `隔${c.autoInterval || 10}楼分析` }; return { on: false, text: '未启用' }; },
          onFlip: (sw, card) => { const cur = loadFoxMemoryConfig(); const next = cur.autoMode === 'manual' ? 'auto' : 'manual'; foxMemoryApplyAutoMode(next, null, next !== 'manual'); toast(next === 'auto' ? '🧠 狐忆自动分析已开启（每次回复）+ 后台静默更新' : '🧠 狐忆自动分析已关闭', next === 'auto' ? 'success' : 'info'); card._xhRefresh(); },
        }));

        // 🎯 狐析：开关=一键启用/关闭全部偏好模块
        modGrid.appendChild(xhModCard({
          id: 'hushen', icon: '🎯', name: '狐析', desc: '用户偏好分析 · 文风/节奏/雷区，越聊越懂你',
          open: () => openHushenPanel(),
          status: () => { const st = getPreferenceStates(); const n = HUSHEN_MODULES.filter(m => st[m.id]).length; return { on: n > 0, text: n > 0 ? `${n} 项偏好` : '未启用' }; },
          onFlip: async (sw, card) => {
            const st = getPreferenceStates();
            const anyOn = HUSHEN_MODULES.some(m => st[m.id]);
            const target = !anyOn;
            sw.style.pointerEvents = 'none';
            try { for (const m of HUSHEN_MODULES) { try { await toggleModulePreference(m.identifier, target, m.label); } catch (e) { log('[狐析] 批量切换失败:', m.id, e); } } } finally { sw.style.pointerEvents = ''; }
            toast(target ? `🎯 已一键启用全部 ${HUSHEN_MODULES.length} 个偏好模块` : '🎯 已一键关闭全部偏好模块', target ? 'success' : 'info');
            card._xhRefresh();
          },
        }));

        // 🌐 狐搜：开关=自动搜索（默认隔15楼一次）
        modGrid.appendChild(xhModCard({
          id: 'husou', icon: '🌐', name: '狐搜', desc: '外部搜索 · 实时检索注入，设定考据不再瞎编',
          open: () => openHusouPanel(),
          status: () => { const c = state.husouSettings || loadHusouSettings(); if (c.autoMode === 'auto') return { on: true, text: '每次回复搜索' }; if (c.autoMode === 'interval') return { on: true, text: `隔${c.autoInterval || 15}楼搜索` }; return { on: false, text: '手动模式' }; },
          onFlip: (sw, card) => { const c = state.husouSettings || (state.husouSettings = loadHusouSettings()); if (c.autoMode === 'manual') { c.autoMode = 'interval'; c.autoInterval = 15; c.backgroundSilent = true; toast('🌐 狐搜已开启：隔15楼 + 后台静默更新', 'success'); } else { c.autoMode = 'manual'; toast('🌐 狐搜自动搜索已关闭', 'info'); } c.enableAutoSearch = c.autoMode !== 'manual'; saveHusouSettings(); card._xhRefresh(); },
        }));

        // 🖼️ 狐映：现代通讯（手机悬浮窗）+ 通用前端，开关控制总开关
        modGrid.appendChild(xhModCard({
          id: 'foximage', icon: '🖼️', name: '狐映', desc: '现代通讯手机 + 通用前端 · 社交互动与精美前端渲染',
          open: () => foxImageOpenConfigPanel(),
          status: () => { const c = foxImageState.config || foxImageLoadConfig(); const n = [c.phone?.enabled, c.front?.enabled].filter(Boolean).length; return { on: !!c.enabled, text: c.enabled ? `启用 ${n} 个模块` : '未启用' }; },
          onFlip: async (sw, card) => { const c = foxImageState.config || foxImageLoadConfig(); c.enabled = !c.enabled; foxImageSaveConfig(c); await foxImageApplyPrompt(); foxImageRenderAll(); foxImageEnsureLauncher(); card._xhRefresh(); toast(c.enabled ? '🖼️ 狐映已启用' : '🖼️ 狐映已关闭', c.enabled ? 'success' : 'info'); },
        }));

        // 🌌 平行世界（蓝色）：开关=自动推进（默认每次回复）
        modGrid.appendChild(xhModCard({
          id: 'pw', icon: '🌌', name: '平行世界', desc: '动态世界 · 没有你，世界照常运转', pw: true,
          open: () => pwOpenPanel(),
          status: () => { const c = pwState.config || pwLoadConfig(); if (c.autoMode === 'auto') return { on: true, text: '每次回复推进' }; if (c.autoMode === 'interval') return { on: true, text: `隔${c.autoInterval || 5}楼推进` }; return { on: false, text: '未启用' }; },
          onFlip: (sw, card) => { const c = pwState.config || (pwState.config = pwLoadConfig()); if (c.autoMode === 'manual') { c.autoMode = 'auto'; c.enabled = true; c.backgroundSilent = true; let switchedToQuality = false; if (c.generationMode !== 'quality') { c.generationMode = 'quality'; switchedToQuality = true; } toast(switchedToQuality ? '🌌 平行世界自动推进已开启（每次回复）+ 主线注入已开启 + 后台静默更新 + 已自动切换为质量模式' : '🌌 平行世界自动推进已开启（每次回复）+ 主线注入已开启 + 后台静默更新', 'success'); } else { c.autoMode = 'manual'; toast('🌌 平行世界自动推进已关闭', 'info'); } c.autoAdvance = c.autoMode !== 'manual'; pwState.config = c; pwSaveConfig(); try { if (typeof pwRenderPanel === 'function') pwRenderPanel(); } catch (e) { log('[平行世界·模块中心] 重新渲染面板失败', e); } card._xhRefresh(); },
        }));

        // 🕰️ 狐刻：开关=启用时刻表（时间权威 + 事件闸机 + 正文强制注入）
        modGrid.appendChild(xhModCard({
          id: 'foxtime', icon: '🕰️', name: '狐刻', desc: '时刻表 · 时间权威，到点强制注入正文',
          open: () => { try { ftOpenPanel(); } catch (e) { log('[狐刻] 面板打开失败', e); } },
          status: () => { const c = ftState.config || ftLoadConfig(); if (!c.enabled) return { on: false, text: '未启用' }; const d = ftState.data || ftLoadData(); const nodeCount = (d.nodes || []).filter(n => n.status === 'pending').length; return { on: true, text: d.clock?.unknown ? '时间未知' : `${d.clock?.label || '未初始化'}${nodeCount ? ` · ${nodeCount}节点` : ''}` }; },
          onFlip: (sw, card) => { const c = ftState.config || (ftState.config = ftLoadConfig()); c.enabled = !c.enabled; ftSaveConfig(c); ftState.config = c; if (c.enabled) { try { ftRegisterAutoListener(); } catch (e) { log('[狐刻] 注册监听失败', e); } try { if (typeof ftTimelineMount === 'function' && !ftTL.el && localStorage.getItem('ft-tl-closed') !== '1') ftTimelineMount(); } catch (e) { log('[狐刻] 自动打开悬浮窗失败', e); } try { ftSyncPromptEntry(true, FT_PROMPT_ENTRY_CONTENT); } catch (e) { log('[狐刻] 开启位置信息条目失败', e); } toast('🕰️ 狐刻已启用：时间追踪 + 正文注入 + 平行世界门闩 + 位置信息条目已自动开启', 'success'); } else { try { ftUnregisterAutoListener(); } catch (e) { log('[狐刻] 注销监听失败', e); } try { if (typeof ftTimelineUnmount === 'function' && ftTL.el) ftTimelineUnmount(); } catch (e) { log('[狐刻] 关闭悬浮窗失败', e); } try { ftSyncPromptEntry(false, ''); } catch (e) { log('[狐刻] 关闭位置信息条目失败', e); } toast('🕰️ 狐刻已关闭：位置信息条目已自动关闭', 'info'); } card._xhRefresh(); },
        }));

        modPage.appendChild(modGrid);

        // 🦊 狐构锁定自动解除：实时刷新检测到大纲已注入即恢复按钮（无需重开工作台）
        try {
          const oc = modGrid.querySelector('.xh-mod[data-mod="outline"]');
          if (oc && oc._xhRefresh) {
            const _ocBaseRefresh = oc._xhRefresh;
            oc._xhRefresh = () => {
              if (outlineLocked && outlineLoadLocalRaw().trim()) {
                outlineLocked = false; outlineDenyCount = 0;
                const _sw = oc.querySelector('.xh-sw'); if (_sw) _sw.classList.remove('locked');
                try { toast('🦊检测到大纲已注入~狐构按钮解锁啦', 'success'); } catch {}
              }
              _ocBaseRefresh();
            };
          }
        } catch {}

        // 🦊 无感实时同步：工作台打开期间每 0.8s 轻量重读最新状态
        //    （模块卡片状态/快捷开关/导航绿点/状态胶囊），子面板改动（狐裁快速模式、注入大纲等）退出后立即体现
        try {
          if (xhDashLiveTimer) { clearInterval(xhDashLiveTimer); xhDashLiveTimer = null; }
          const xhLiveCards = [...modGrid.querySelectorAll('.xh-mod')];
          xhDashLiveTimer = setInterval(() => {
            if (!topDoc.getElementById('ss-dashboard')) { try { clearInterval(xhDashLiveTimer); xhDashLiveTimer = null; } catch {} return; }
            try { for (const c of xhLiveCards) { if (c && c._xhRefresh) c._xhRefresh(); } } catch {}
            try { allUpdates.forEach(fn => fn()); } catch {}
            try { refreshNavDots(); } catch {}
            try { updateStatusChip(); } catch {}
          }, 800);
        } catch (e) { log('[中控] 实时同步启动失败:', e); }
      } catch (e) { log('[中控] 模块中心卡片构建失败:', e); }

      // ---- 页面切换（模块化显示，而非滚动）----
      const crumbT = topbar.querySelector('.xh-crumb-t'), crumbS = topbar.querySelector('.xh-crumb-s');
      const mobileTabs = topDoc.createElement('div');
      mobileTabs.className = 'xh-mobile-tabs';
      mobileTabs.innerHTML = [
        ['think','📡','中控'],['quick','🔧','开关'],['mod','🦊','模块'],['preset','⚙️','预设'],['advanced','🧰','高级']
      ].map(([id, icon, name]) => `<div class="xh-mobile-tab" data-page="${id}"><span class="ico">${icon}</span>${name}</div>`).join('');
      const isMobileWorkbench = () => { try { return topWindow.innerWidth <= 720; } catch { return false; } };
      const go = (pid) => {
        const mobileAdvanced = pid === 'advanced' && isMobileWorkbench();
        const def = mobileAdvanced ? { id: 'advanced', name: '高级', en: 'ADVANCED' } : (XH_PAGES.find(p => p.id === pid) || XH_PAGES[0]);
        contentWrap.querySelectorAll('.xh-page').forEach(pg => pg.classList.remove('show'));
        if (mobileAdvanced) {
          ['summary','misc','backup'].forEach(id => { const pg = pageEls[id]; if (pg) pg.classList.add('show','xh-mobile-advanced'); });
        } else {
          Object.values(pageEls).forEach(pg => pg.classList.remove('xh-mobile-advanced'));
          const pg = pageEls[def.id]; if (pg) { void pg.offsetHeight; pg.classList.add('show'); }
        }
        sideNav.querySelectorAll('.xh-dash-nav-item').forEach(n => n.classList.toggle('act', n.dataset.page === def.id));
        const mobileGroup = ['summary','misc','backup'].includes(def.id) ? 'advanced' : def.id;
        mobileTabs.querySelectorAll('.xh-mobile-tab').forEach(n => n.classList.toggle('act', n.dataset.page === mobileGroup));
        crumbT.textContent = def.name; crumbS.textContent = def.en;
        contentWrap.scrollTop = 0;
        try { localStorage.setItem(CONFIG.DASHBOARD_LAST_PAGE_KEY, def.id); } catch {}
      };
      dash._xhGo = go;
      sideNav.querySelectorAll('.xh-dash-nav-item').forEach(n => { n.onclick = () => go(n.dataset.page); });
      mobileTabs.querySelectorAll('.xh-mobile-tab').forEach(n => { n.onclick = () => go(n.dataset.page); });
      try {
        const mq = topWindow.matchMedia?.('(max-width: 720px)');
        if (mq) {
          const onWorkbenchBreakpoint = (event) => {
            if (!dash.isConnected) { try { mq.removeEventListener('change', onWorkbenchBreakpoint); } catch {} return; }
            const currentMobilePage = mobileTabs.querySelector('.xh-mobile-tab.act')?.dataset.page;
            const currentDesktopPage = sideNav.querySelector('.xh-dash-nav-item.act')?.dataset.page;
            if (event.matches) {
              const target = ['summary','misc','backup'].includes(currentDesktopPage) ? 'advanced' : (currentDesktopPage || currentMobilePage || 'think');
              go(target);
            } else {
              go(currentMobilePage === 'advanced' ? 'misc' : (currentMobilePage || currentDesktopPage || 'think'));
            }
          };
          mq.addEventListener('change', onWorkbenchBreakpoint);
        }
      } catch {}
      // 状态小绿点
      refreshNavDots();

      // ---- 顶栏搜索：条目级定位（开关行/模块卡片优先，分区标题兜底），自动切页+展开+滚动+高亮 ----
      const searchInput = topbar.querySelector('.xh-search input');
      const xhNorm = (s) => String(s || '').replace(/\s+/g, '').toLowerCase();
      const xhSearchIndex = [];
      // ① 分区标题（狐系六模块旧分区已被卡片取代，跳过避免跳到空壳）
      for (const pr of secPairs) {
        if (XH_MOD_SECTION_RE.test(pr.text)) continue;
        xhSearchIndex.push({ text: pr.text, page: xhPageOf(pr.text), el: pr.title, kind: 'section' });
      }
      // ② 递归收集各分区内的具体条目行（含按钮/下拉/输入框/span开关 的行）
      const xhIndexRows = (root, page) => {
        if (!root) return;
        const seen = new Set();
        const isCtrlRow = (el) => {
          if (!el || !el.querySelector) return false;
          if (el.querySelector('button,select,input,textarea')) return true;
          const spans = el.querySelectorAll('span');
          for (const sp of spans) { if (sp.style && sp.style.borderRadius === '6px' && sp.style.overflow === 'hidden') return true; } // 开/关、三联开关的 span 开关
          return false;
        };
        const walk = (el, depth) => {
          if (depth > 4) return;
          for (const child of el.children) {
            if (child.classList && child.classList.contains('xh-mod')) continue;
            if (isCtrlRow(child)) {
              const txt = String(child.textContent || '').replace(/\s+/g, ' ').trim();
              if (txt && xhNorm(txt).length <= 60 && !seen.has(child)) { seen.add(child); xhSearchIndex.push({ text: txt, page, el: child, kind: 'item' }); }
            } else {
              walk(child, depth + 1);
            }
          }
        };
        walk(root, 0);
      };
      for (const pr of secPairs) {
        if (XH_MOD_SECTION_RE.test(pr.text)) continue;
        if (pr.box) xhIndexRows(pr.box, xhPageOf(pr.text));
      }
      // ③ 模块中心卡片（狐构/狐裁/狐忆/狐析/狐搜/平行世界）
      try { pageEls.mod.querySelectorAll('.xh-mod').forEach(card => { const nm = card.querySelector('b')?.textContent || ''; const ds = card.querySelector('p')?.textContent || ''; xhSearchIndex.push({ text: `${nm} ${ds}`.trim(), page: 'mod', el: card, kind: 'item' }); }); } catch {}
      const xhRevealEntry = (entry) => {
        go(entry.page);
        // 若条目所在分区被折叠，先自动展开
        try {
          const pair = secPairs.find(p => p.box && p.box.contains(entry.el));
          if (pair && pair.box.style.display === 'none' && typeof pair.title.onclick === 'function') pair.title.onclick();
        } catch {}
        setTimeout(() => {
          try { entry.el.scrollIntoView({ block: 'center', behavior: 'smooth' }); } catch { try { entry.el.scrollIntoView(); } catch {} }
          try {
            entry.el.classList.remove('xh-search-hit'); void entry.el.offsetWidth; entry.el.classList.add('xh-search-hit');
            setTimeout(() => { try { entry.el.classList.remove('xh-search-hit'); } catch {} }, 1900);
          } catch {}
        }, 80);
        const short = String(entry.text || '').replace(/\s+/g, ' ').trim();
        toast(`🔍 已定位「${short.length > 22 ? short.slice(0, 22) + '…' : short}」`, 'success');
        searchInput.blur();
      };
      const doSearch = () => {
        const raw = String(searchInput.value || '').trim(); if (!raw) return;
        const q = xhNorm(raw);
        let best = null, bestScore = 99;
        for (const e of xhSearchIndex) {
          const t = xhNorm(e.text);
          let s = -1;
          if (t.includes(q)) s = (e.kind === 'item' ? 0 : 1) + (t.startsWith(q) ? 0 : 0.5); // 条目优先，前缀命中更优
          else if ([...q].every(ch => t.includes(ch))) s = (e.kind === 'item' ? 2 : 3);    // 散字模糊匹配兜底
          if (s >= 0 && s < bestScore) { bestScore = s; best = e; }
        }
        if (best) { xhRevealEntry(best); return; }
        toast(`🔍 没有找到「${raw}」相关功能`, 'warning');
      };
      searchInput.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); doSearch(); } e.stopPropagation(); });
      searchInput.addEventListener('click', (e) => e.stopPropagation());

      dash.appendChild(sideNav);
      dash.appendChild(mainEl);
      dash.appendChild(mobileTabs);
      // 🧹 兜底清理：保留桌面侧栏、主区和 M1 手机底栏。
      for (const child of [...dash.children]) { if (child !== sideNav && child !== mainEl && child !== mobileTabs) { try { child.remove(); } catch {} } }
      dash.classList.add('xh-workbench');
      let savedPage = 'think';
      try { savedPage = localStorage.getItem(CONFIG.DASHBOARD_LAST_PAGE_KEY) || 'think'; } catch {}
      const validSavedPage = savedPage === 'advanced' || XH_PAGES.some(p => p.id === savedPage);
      if (!validSavedPage) savedPage = 'think';
      if (savedPage === 'advanced' && !isMobileWorkbench()) savedPage = 'misc';
      go(savedPage);
      // 🦊 打开工作台时隐藏悬浮狐狐气泡，避免遮挡侧栏品牌区（关闭面板时恢复，见 closeDashboard）
      try { const bb = topDoc.getElementById('ss-float-bubble'); if (bb && bb.dataset.xhHidden == null) { bb.dataset.xhHidden = bb.style.display || ''; bb.style.display = 'none'; } } catch {}
    } catch (e) {
      log('[中控] 工作台构建失败:', e);
      try { dash.classList.remove('xh-workbench'); dash.style.height = 'auto'; dash.style.maxHeight = '85vh'; dash.style.overflowY = 'auto'; dash.style.padding = '24px 28px'; dash.style.flexDirection = 'column'; dash.style.gap = '18px'; } catch {}
    }

    topDoc.body.appendChild(overlay);
    topDoc.body.appendChild(dash);
    setTimeout(() => { allUpdates.forEach(fn => fn()); }, 50);
  }

  function updateStatusChip() { const chip = topDoc.getElementById('ss-dash-status'); if (chip) chip.textContent = buildStatusText(); }
  // ✅ 统一模态关闭：叠加淡出动画后再移除，避免"瞬间消失"的生硬感。
  //    overlay/panel 可传元素、ID 字符串或 null；动画时长与 .ss-overlay-closing/.ss-panel-closing 对齐。
  //    立即清空 id：防止"关闭动画期间用户重开"被 openXxx 的 getElementById 守卫误判为已存在而拒绝打开。
  function ssCloseModal(overlay, panel) {
    const ov = typeof overlay === 'string' ? topDoc.getElementById(overlay) : overlay;
    const pn = typeof panel === 'string' ? topDoc.getElementById(panel) : panel;
    if (ov) { ov.classList.add('ss-overlay-closing'); ov.style.pointerEvents = 'none'; ov.id = ''; }
    if (pn) { pn.classList.add('ss-panel-closing'); pn.style.pointerEvents = 'none'; pn.id = ''; }
    // 兜底定时移除：与动画时长一致，确保即使 animationend 不触发也能清理。
    setTimeout(() => { try { ov?.remove(); } catch {} try { pn?.remove(); } catch {} }, 210);
  }

  // 🦊 工作台无感实时同步定时器（工作台构建时启动；关闭/重建时清理；用 var 声明避免提升时序问题）
  var xhDashLiveTimer = null;
  function closeDashboard() { xhGuideEnd(); try { if (xhDashLiveTimer) { clearInterval(xhDashLiveTimer); xhDashLiveTimer = null; } } catch {} ssCloseModal('ss-dash-overlay', 'ss-dashboard'); try { const bb = topDoc.getElementById('ss-float-bubble'); if (bb && bb.dataset.xhHidden != null) { bb.style.display = bb.dataset.xhHidden; delete bb.dataset.xhHidden; } } catch {} }

  // 🦊 仪表盘刷新：狐裁/小说模式等会修改预设条目，但已打开的仪表盘不会自动更新，
  //    导致预设选项看起来还是老样子。这里在开关这些功能后调用，若仪表盘开着则关掉重开，
  //    重新读取最新预设状态并恢复滚动位置。
  function ssRefreshDashboardIfOpen() {
    const dash = topDoc.getElementById('ss-dashboard');
    if (!dash) return;
    const scroller = dash.querySelector('.xh-dash-content') || dash;
    const scrollTop = scroller.scrollTop || 0;
    try { closeDashboard(); } catch {}
    requestAnimationFrame(() => {
      try { openDashboard(); } catch {}
      const newDash = topDoc.getElementById('ss-dashboard');
      const newScroller = newDash && (newDash.querySelector('.xh-dash-content') || newDash);
      if (newScroller) newScroller.scrollTop = scrollTop;
    });
  }

  // 🦊 仪表盘模块折叠：和"自定义内容编辑"同款，点标题展开/收起。状态持久化到 localStorage。
  const SS_DASH_COLLAPSE_KEY = 'SPreset_DashboardCollapse';
  function ssLoadCollapseStates() {
    try { return JSON.parse(localStorage.getItem(SS_DASH_COLLAPSE_KEY) || '{}'); } catch { return {}; }
  }
  function ssSaveCollapseState(key, open) {
    try {
      const all = ssLoadCollapseStates();
      all[key] = open;
      localStorage.setItem(SS_DASH_COLLAPSE_KEY, JSON.stringify(all));
    } catch {}
  }
  function ssMakeCollapsible(titleEl, boxEl, defaultOpen) {
    if (!titleEl || !boxEl) return;
    const sectionKey = (titleEl.textContent || '').trim();
    const saved = ssLoadCollapseStates();
    const hasSaved = Object.prototype.hasOwnProperty.call(saved, sectionKey);
    let open = hasSaved ? !!saved[sectionKey] : !!defaultOpen;
    titleEl.style.cssText += 'cursor:pointer;user-select:none;';
    const origDisplay = boxEl.style.display || 'block';
    const baseText = sectionKey;
    const setLabel = () => { titleEl.textContent = (open ? '▼ ' : '▶ ') + baseText; };

    // ✨ 展开/收起动画：max-height + opacity 过渡（替代生硬的 display 切换）
    boxEl.style.overflow = 'hidden';
    boxEl.style.transition = 'max-height .38s cubic-bezier(.22,1,.36,1),opacity .28s ease';
    const applyState = (animate) => {
      if (open) {
        boxEl.style.display = origDisplay;
        boxEl.style.opacity = '1';
        boxEl.style.maxHeight = 'none';
      } else {
        boxEl.style.opacity = '0';
        boxEl.style.maxHeight = '0px';
        if (!animate) boxEl.style.display = 'none';
      }
    };
    applyState(false);
    setLabel();

    let animTimer = null;
    titleEl.onclick = () => {
      open = !open;
      if (animTimer) { clearTimeout(animTimer); animTimer = null; }
      if (open) {
        boxEl.style.display = origDisplay;
        const target = boxEl.scrollHeight;
        boxEl.style.maxHeight = '0px';
        boxEl.style.opacity = '0';
        requestAnimationFrame(() => {
          boxEl.style.maxHeight = target + 'px';
          boxEl.style.opacity = '1';
        });
        animTimer = setTimeout(() => { if (open) boxEl.style.maxHeight = 'none'; animTimer = null; }, 400);
      } else {
        boxEl.style.maxHeight = boxEl.scrollHeight + 'px';
        requestAnimationFrame(() => {
          boxEl.style.maxHeight = '0px';
          boxEl.style.opacity = '0';
        });
        animTimer = setTimeout(() => { if (!open) boxEl.style.display = 'none'; animTimer = null; }, 400);
      }
      setLabel();
      ssSaveCollapseState(sectionKey, open);
    };
  }

  // 🦊 仪表盘模块状态小绿点：和小说模式同款，绿灯=已开启自动更新，暗=未开启。
  function ssAddStatusDot(titleEl, checkFn, tooltip) {
    if (!titleEl) return;
    titleEl.style.cssText += 'display:flex;align-items:center;justify-content:space-between;';
    const dot = topDoc.createElement('span');
    dot.title = tooltip || '绿灯=已开启自动更新，暗=未开启';
    dot.style.cssText = 'display:inline-block;width:9px;height:9px;border-radius:50%;flex-shrink:0;transition:all 0.3s;';
    const update = () => {
      try {
        const on = !!checkFn();
        dot.style.background = on ? '#3ad07a' : '#4a3a36';
        dot.style.boxShadow = on ? '0 0 7px rgba(58,208,122,0.85)' : 'none';
      } catch {}
    };
    update();
    titleEl.appendChild(dot);
    return update;
  }

