#xh-dock-panel.show{max-height:min(660px,calc(100dvh - 100px));opacity:1;margin-top:6px;}
#xh-dock-flipper{transition:transform .28s cubic-bezier(.4,0,.2,1),opacity .28s;transform-style:preserve-3d;position:relative;}
#xh-dock-flipper.turning{transform:rotateY(88deg) scale(.97);opacity:0;}
.xd-face{display:none;}.xd-face.show{display:block;animation:xdFade .35s ease;}
@keyframes xdFade{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:translateY(0)}}
.xd-body{display:flex;height:min(560px,calc(100dvh - 220px));min-height:0;border-radius:16px;overflow:hidden;background:linear-gradient(155deg,rgba(26,20,22,.97),rgba(14,11,13,.98));border:1px solid rgba(var(--xd-acc-rgb),.26);box-shadow:0 -18px 60px rgba(0,0,0,.6),inset 0 1px 0 rgba(255,255,255,.05);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);}
.xd-side{width:176px;flex-shrink:0;display:flex;flex-direction:column;border-right:1px solid rgba(255,255,255,.055);background:rgba(255,255,255,.012);padding:12px 9px 9px;}
.xd-brand{display:flex;align-items:center;gap:8px;padding:0 6px 11px;border-bottom:1px solid rgba(255,255,255,.05);margin-bottom:9px;}
.xd-bl{width:30px;height:30px;border-radius:9px;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:15px;background:linear-gradient(145deg,rgba(var(--xd-acc-rgb),.3),rgba(var(--xd-acc-rgb),.08));border:1px solid rgba(var(--xd-acc-rgb),.42);box-shadow:0 0 12px rgba(var(--xd-acc-rgb),.25);}
.xd-brand b{font-size:12.5px;display:block;color:var(--xd-acc-text);}.xd-brand small{color:#706058;font-size:9px;letter-spacing:.1em;display:block;margin-top:1px;}
.xd-brand .xd-fm2{margin-left:auto;width:24px;height:24px;border-radius:7px;display:flex;align-items:center;justify-content:center;color:var(--xd-acc-text);background:rgba(var(--xd-acc-rgb),.1);border:1px solid rgba(var(--xd-acc-rgb),.3);cursor:pointer;transition:transform .5s cubic-bezier(.34,1.56,.64,1);flex-shrink:0;}
.xd-brand .xd-fm2:hover{transform:rotate(180deg);}
.xd-nav{flex:1;overflow-y:auto;display:flex;flex-direction:column;gap:2px;min-height:0;}
.xd-nav::-webkit-scrollbar{width:4px}.xd-nav::-webkit-scrollbar-thumb{background:rgba(var(--xd-acc-rgb),.3);border-radius:4px;}
.xd-grp{font-size:9px;color:#706058;letter-spacing:.12em;padding:8px 8px 3px;text-transform:uppercase;}
.xd-ni{display:flex;align-items:center;gap:9px;padding:7px 9px;border-radius:8px;cursor:pointer;color:#a09088;font-size:12px;position:relative;transition:all .18s;border:1px solid transparent;white-space:nowrap;}
.xd-ni .xd-bg{margin-left:auto;font-size:9.5px;background:rgba(var(--xd-acc-rgb),.14);color:var(--xd-acc-text);border:1px solid rgba(var(--xd-acc-rgb),.28);padding:0 6px;border-radius:99px;flex-shrink:0;}
.xd-ni:hover{background:rgba(255,255,255,.04);color:#e8ddd4;}
.xd-ni.act{background:linear-gradient(90deg,rgba(var(--xd-acc-rgb),.16),rgba(var(--xd-acc-rgb),.04));color:var(--xd-acc-text);border-color:rgba(var(--xd-acc-rgb),.25);}
.xd-ni.act::before{content:"";position:absolute;left:-9px;top:20%;bottom:20%;width:3px;border-radius:3px;background:linear-gradient(180deg,var(--xd-acc-lt),var(--xd-acc));box-shadow:0 0 10px rgba(var(--xd-acc-rgb),.6);}
.xd-foot{padding-top:8px;border-top:1px solid rgba(255,255,255,.05);}
.xd-foot .xd-fr{display:flex;align-items:center;justify-content:space-between;padding:5px 7px;font-size:11px;color:#a09088;}
.xd-mb{height:4px;border-radius:4px;background:rgba(255,255,255,.06);overflow:hidden;margin:2px 7px;}
.xd-mb i{display:block;height:100%;background:linear-gradient(90deg,var(--xd-acc),var(--xd-acc-lt));border-radius:4px;box-shadow:0 0 6px rgba(var(--xd-acc-rgb),.5);transition:width .5s;}
.xd-main{flex:1;display:flex;flex-direction:column;min-width:0;}
.xd-ph{display:flex;align-items:center;gap:11px;padding:11px 16px;border-bottom:1px solid rgba(255,255,255,.055);flex-shrink:0;}
.xd-ph .xd-t{font-size:13.5px;font-weight:700;}
.xd-ph .xd-t small{display:block;font-size:9.5px;color:#706058;font-weight:400;margin-top:1px;letter-spacing:.1em;}
.xd-ptg{margin-left:auto;display:flex;gap:12px;align-items:center;}
.xd-tg{display:flex;align-items:center;gap:7px;font-size:11px;color:#a09088;cursor:pointer;user-select:none;white-space:nowrap;}
.xd-sw{position:relative;width:34px;height:19px;border-radius:99px;cursor:pointer;flex-shrink:0;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.09);transition:all .25s;}
.xd-sw::after{content:"";position:absolute;top:2px;left:2px;width:13px;height:13px;border-radius:50%;background:#8a7f78;transition:all .28s cubic-bezier(.34,1.56,.64,1);box-shadow:0 2px 6px rgba(0,0,0,.4);}
.xd-sw.on{background:linear-gradient(90deg,rgba(var(--xd-acc-rgb),.85),rgba(var(--xd-acc-lt-rgb),.85));border-color:rgba(var(--xd-acc-lt-rgb),.6);box-shadow:0 0 12px rgba(var(--xd-acc-rgb),.35);}
.xd-sw.on::after{left:16px;background:#fff;}
.xd-ct{flex:1;overflow-y:auto;padding:15px 17px;scrollbar-gutter:stable;min-height:0;}
.xd-ct::-webkit-scrollbar{width:7px}.xd-ct::-webkit-scrollbar-thumb{background:rgba(var(--xd-acc-rgb),.25);border-radius:7px;background-clip:content-box;border:2px solid transparent;}
.xd-pg{display:none;}.xd-pg.show{display:block;}
.xd-pg.show>*{animation:xdRise .4s cubic-bezier(.22,1,.36,1) both;}
.xd-pg.show>*:nth-child(1){animation-delay:.02s}.xd-pg.show>*:nth-child(2){animation-delay:.06s}.xd-pg.show>*:nth-child(3){animation-delay:.1s}.xd-pg.show>*:nth-child(4){animation-delay:.14s}.xd-pg.show>*:nth-child(5){animation-delay:.18s}
@keyframes xdRise{from{opacity:0;transform:translateY(11px)}to{opacity:1;transform:translateY(0)}}
.xd-cd{min-width:0;max-width:100%;box-sizing:border-box;overflow:hidden;background:rgba(255,255,255,.028);border:1px solid rgba(255,255,255,.065);border-radius:11px;padding:13px 15px;margin-bottom:11px;transition:border-color .25s,box-shadow .25s;}
.xd-cd:hover{border-color:rgba(var(--xd-acc-rgb),.25);box-shadow:0 10px 30px rgba(0,0,0,.25);}
.xd-cd h3{font-size:11.5px;color:var(--xd-acc-text);letter-spacing:.08em;margin-bottom:10px;display:flex;align-items:center;gap:8px;}
.xd-cd h3 small{color:#706058;font-weight:400;margin-left:auto;font-size:10px;letter-spacing:0;}
.xd-sg{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-bottom:11px;}
.xd-st{background:linear-gradient(160deg,rgba(255,255,255,.04),rgba(255,255,255,.012));border:1px solid rgba(255,255,255,.065);border-radius:11px;padding:11px 13px;transition:all .22s;position:relative;}
.xd-st:hover{transform:translateY(-2px);border-color:rgba(var(--xd-acc-rgb),.3);}
.xd-st .xd-si{position:absolute;top:11px;right:12px;color:rgba(var(--xd-acc-rgb),.4);}
.xd-st b{font-size:20px;color:var(--xd-acc-text);font-variant-numeric:tabular-nums;display:block;}
.xd-st small{color:#706058;font-size:10px;}
.xd-btn{display:inline-flex;align-items:center;gap:6px;padding:7px 13px;border-radius:9px;border:1px solid rgba(var(--xd-acc-rgb),.32);cursor:pointer;font-size:11.5px;font-weight:600;background:linear-gradient(180deg,rgba(var(--xd-acc-rgb),.16),rgba(var(--xd-acc-rgb),.07));color:var(--xd-acc-text);transition:all .16s;font-family:inherit;}
.xd-btn:hover{transform:translateY(-1px);box-shadow:0 6px 16px rgba(var(--xd-acc-rgb),.2);border-color:rgba(var(--xd-acc-lt-rgb),.5);}
.xd-btn:active{transform:scale(.97);}
.xd-btn.gh{background:rgba(255,255,255,.03);border-color:rgba(255,255,255,.09);color:#a09088;}
.xd-btn.gh:hover{color:#e8ddd4;border-color:rgba(255,255,255,.18);}
.xd-btn.dn{border-color:rgba(200,80,80,.4);color:#e8a0a0;background:rgba(139,0,0,.08);}
.xd-btn.dn:hover{border-color:rgba(220,100,100,.6);box-shadow:0 6px 16px rgba(180,60,60,.2);}
.xd-sp{display:flex;align-items:center;gap:10px;padding:9px 13px;margin-bottom:11px;border-radius:11px;font-size:11.5px;background:linear-gradient(90deg,rgba(var(--xd-acc-rgb),.13),rgba(var(--xd-acc-rgb),.03) 60%,transparent);border:1px solid rgba(var(--xd-acc-rgb),.22);min-width:0;max-width:100%;box-sizing:border-box;overflow:hidden;}
.xd-sp>span{min-width:0;overflow-wrap:anywhere;word-break:break-word;}
.xd-sp b{color:var(--xd-acc-text);}
.xd-cr{display:flex;align-items:center;justify-content:space-between;padding:8px 2px;border-bottom:1px dashed rgba(255,255,255,.045);gap:10px;min-width:0;}
.xd-cr:last-child{border:none;}
.xd-cr .xd-lb{font-size:12px;color:#a09088;display:flex;flex:1 1 auto;min-width:0;flex-direction:column;gap:2px;overflow-wrap:anywhere;}
.xd-cr .xd-lb small{color:#706058;font-size:10px;line-height:1.5;}
.xd-cr-field{display:flex;flex-direction:column;padding:8px 2px;border-bottom:1px dashed rgba(255,255,255,.045);gap:4px;min-width:0;}
.xd-cr-field:last-child{border:none;}
.xd-cr-field .xd-lb{font-size:12px;color:#a09088;display:flex;flex:1 1 auto;min-width:0;flex-direction:column;gap:2px;overflow-wrap:anywhere;word-break:break-word;}
.xd-cr-field .xd-lb small{color:#706058;font-size:10px;line-height:1.5;}
.xd-cr-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;min-width:0;max-width:100%;box-sizing:border-box;overflow:hidden;}
.xd-cr-val{font-size:11.5px;color:var(--xd-acc-text);line-height:1.55;overflow-wrap:anywhere;word-break:break-word;min-width:0;max-width:100%;box-sizing:border-box;width:100%;display:block;}
.xd-row2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 18px;}
.xd-ip{max-width:52%;min-width:0;box-sizing:border-box;background:rgba(255,255,255,.04);border:1px solid rgba(var(--xd-acc-rgb),.2);border-radius:8px;color:#e8ddd4;padding:5px 9px;font-size:12px;font-family:inherit;outline:none;transition:all .18s;}
.xd-ip:focus{border-color:rgba(var(--xd-acc-lt-rgb),.55);box-shadow:0 0 0 3px rgba(var(--xd-acc-rgb),.12);}
select.xd-ip{cursor:pointer;}
.xd-empty{padding:26px 16px;text-align:center;color:#706058;font-size:12px;line-height:1.8;}
.xd-chart{display:flex;align-items:flex-end;gap:5px;height:60px;padding-top:6px;}
.xd-chart i{flex:1;border-radius:3px 3px 0 0;display:block;min-height:2px;}
.xd-ly{border:1px solid rgba(255,255,255,.065);border-radius:11px;margin-bottom:9px;overflow:hidden;}
.xd-lyh{display:flex;align-items:center;gap:9px;padding:9px 12px;cursor:pointer;user-select:none;transition:background .18s;min-width:0;}
.xd-lyh:hover{background:rgba(var(--xd-acc-rgb),.06);}
.xd-lyh .xd-lt{font-size:9.5px;font-weight:800;padding:2px 8px;border-radius:6px;letter-spacing:.05em;flex-shrink:0;}
.xd-l0 .xd-lt{background:rgba(240,160,112,.18);color:#ffc89a;border:1px solid rgba(240,160,112,.4);}
.xd-l1 .xd-lt{background:rgba(232,120,74,.14);color:#f0a070;border:1px solid rgba(232,120,74,.35);}
.xd-l2 .xd-lt{background:rgba(140,180,220,.12);color:#a8c8e8;border:1px solid rgba(140,180,220,.3);}
.xd-l3 .xd-lt{background:rgba(200,160,220,.12);color:#cfa8e0;border:1px solid rgba(200,160,220,.3);}
.xd-lyh b{font-size:12px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}.xd-lyh small{color:#706058;margin-left:auto;font-size:10px;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.xd-lyh .xd-ar{color:#706058;font-size:10px;transition:transform .3s;}
.xd-ly.open .xd-ar{transform:rotate(90deg);}
.xd-lyb{display:grid;grid-template-rows:0fr;transition:grid-template-rows .35s cubic-bezier(.22,1,.36,1);}
.xd-ly.open .xd-lyb{grid-template-rows:1fr;}
.xd-lyb>div{overflow:hidden;min-height:0;}
.xd-lyc{padding:2px 12px 11px;font-size:11.5px;color:#a09088;line-height:1.7;min-width:0;overflow-wrap:anywhere;word-break:break-word;}.xd-lyc pre{max-width:100%;overflow-wrap:anywhere;word-break:break-word;}
.xd-kv{display:flex;gap:8px;padding:2px 0;min-width:0;}.xd-kv b{color:var(--xd-acc-text);font-weight:600;min-width:60px;flex-shrink:0;font-size:11px;}.xd-kv span{min-width:0;overflow-wrap:anywhere;word-break:break-word;}
.xd-cc{min-width:0;max-width:100%;box-sizing:border-box;border:1px solid rgba(255,255,255,.07);border-radius:11px;margin-bottom:9px;overflow:hidden;background:linear-gradient(165deg,rgba(255,255,255,.035),rgba(255,255,255,.01));transition:border-color .25s;}
.xd-cc:hover{border-color:rgba(var(--xd-acc-rgb),.3);}
.xd-cch{display:flex;align-items:center;gap:10px;padding:11px 13px;cursor:pointer;user-select:none;min-width:0;}
.xd-cch>div:not(.xd-av){min-width:0;max-width:100%;}
.xd-cch .xd-nm{font-size:12.5px;font-weight:600;display:block;max-width:100%;white-space:normal;overflow-wrap:anywhere;word-break:break-word;}
.xd-cch .xd-mt{font-size:10px;color:#706058;white-space:normal;overflow-wrap:anywhere;word-break:break-word;}
.xd-av{width:34px;height:34px;border-radius:11px;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:14px;font-weight:700;background:linear-gradient(145deg,rgba(var(--xd-acc-rgb),.24),rgba(var(--xd-acc-rgb),.06));border:1px solid rgba(var(--xd-acc-rgb),.4);color:var(--xd-acc-lt);}
.xd-tp{font-size:9px;padding:2px 7px;border-radius:99px;background:rgba(240,160,112,.16);color:#ffc89a;border:1px solid rgba(240,160,112,.4);}
.xd-cch .xd-sx{margin-left:auto;font-size:10px;color:#a09088;display:flex;gap:5px;flex-wrap:wrap;justify-content:flex-end;min-width:0;max-width:48%;overflow:hidden;}
.xd-sx span{max-width:100%;padding:2px 7px;border-radius:99px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.07);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.xd-cacts{display:flex;gap:5px;flex-shrink:0;margin-left:3px;}
.xd-cact{width:30px;height:30px;padding:0;display:flex;align-items:center;justify-content:center;border-radius:8px;cursor:pointer;color:var(--xd-acc-text);background:rgba(var(--xd-acc-rgb),.1);border:1px solid rgba(var(--xd-acc-rgb),.28);transition:all .18s;}
.xd-cact:hover{transform:translateY(-1px);background:rgba(var(--xd-acc-rgb),.2);box-shadow:0 4px 12px rgba(var(--xd-acc-rgb),.2);}
.xd-cact.del{color:#e8a0a0;background:rgba(139,0,0,.08);border-color:rgba(200,80,80,.32);}
.xd-edit-mask{position:absolute;inset:0;z-index:30;display:flex;align-items:center;justify-content:center;padding:14px;background:rgba(5,4,5,.78);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);}
.xd-edit-box{width:min(620px,100%);max-height:calc(100% - 10px);display:flex;flex-direction:column;overflow:hidden;border-radius:14px;background:linear-gradient(155deg,rgba(31,23,26,.99),rgba(14,11,13,.995));border:1px solid rgba(var(--xd-acc-rgb),.38);box-shadow:0 20px 60px rgba(0,0,0,.65);}
.xd-edit-head{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid rgba(var(--xd-acc-rgb),.18);}
.xd-edit-head b{font-size:13px;color:var(--xd-acc-text);}.xd-edit-head small{display:block;margin-top:2px;font-size:9.5px;color:#706058;}
.xd-edit-close{margin-left:auto;width:32px;height:32px;padding:0;display:flex;align-items:center;justify-content:center;border-radius:8px;cursor:pointer;color:#a09088;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.08);}
.xd-edit-ta{flex:1;min-height:260px;margin:12px 14px 10px;padding:11px;box-sizing:border-box;resize:none;outline:none;border-radius:10px;color:#e8ddd4;background:rgba(0,0,0,.24);border:1px solid rgba(var(--xd-acc-rgb),.25);font:11px/1.55 Consolas,monospace;white-space:pre;overflow:auto;}
.xd-edit-ta:focus{border-color:rgba(var(--xd-acc-lt-rgb),.58);box-shadow:0 0 0 3px rgba(var(--xd-acc-rgb),.12);}
.xd-edit-actions{display:flex;justify-content:flex-end;gap:8px;padding:0 14px 13px;}
.xd-ccb{display:grid;grid-template-rows:0fr;transition:grid-template-rows .4s cubic-bezier(.22,1,.36,1);}
.xd-cc.open .xd-ccb{grid-template-rows:1fr;}
.xd-ccb>div{overflow:hidden;min-width:0;min-height:0;}
.xd-ccc{min-width:0;max-width:100%;box-sizing:border-box;padding:0 13px 12px;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:11px;}
.xd-ccc>*{min-width:0;max-width:100%;}
.xd-fv{min-width:0;overflow:hidden;border:1px solid rgba(255,255,255,.06);border-radius:9px;padding:10px 12px;background:rgba(255,255,255,.015);}
.xd-fv h4{font-size:10.5px;color:var(--xd-acc-text);margin:0 0 8px;letter-spacing:.05em;}
.xd-tr{display:flex;align-items:center;gap:7px;margin-bottom:5px;font-size:10.5px;}
.xd-tr span{width:40px;color:#a09088;flex-shrink:0;}
.xd-tr .xd-br2{flex:1;height:4px;border-radius:4px;background:rgba(255,255,255,.06);overflow:hidden;}
.xd-tr .xd-br2 i{display:block;height:100%;background:linear-gradient(90deg,var(--xd-acc),var(--xd-acc-lt));border-radius:4px;}
.xd-tr b{width:20px;text-align:right;color:var(--xd-acc-text);font-size:10px;}
.xd-l5{display:flex;min-width:0;max-width:100%;flex-direction:column;gap:5px;}
.xd-l5 .xd-li{min-width:0;max-width:100%;box-sizing:border-box;padding:7px 10px;border-radius:8px;border:1px solid rgba(255,255,255,.055);background:rgba(255,255,255,.015);font-size:11px;color:#a09088;line-height:1.55;white-space:normal;overflow-wrap:anywhere;word-break:break-word;}
.xd-l5 .xd-li b{color:var(--xd-acc-text);font-size:10px;display:block;margin-bottom:2px;}
/* ✅ 修复档案摘要字体不换行：.xd-ccc 内的 .xd-li 不在 .xd-l5 下，需单独添加换行规则 */
.xd-ccc .xd-li{min-width:0;max-width:100%;box-sizing:border-box;font-size:11px;color:#a09088;line-height:1.55;white-space:normal;overflow-wrap:anywhere;word-break:break-word;}
.xd-ccc .xd-li b{color:var(--xd-acc-text);font-size:10px;display:block;margin-bottom:2px;}
.xd-cc2{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:11px;align-items:center;}
.xd-cp{display:inline-flex;align-items:center;gap:5px;padding:5px 11px;border-radius:99px;font-size:11px;cursor:pointer;user-select:none;background:rgba(255,255,255,.03);border:1px solid rgba(255,255,255,.08);color:#a09088;transition:all .18s;}
.xd-cp:hover{border-color:rgba(var(--xd-acc-rgb),.35);color:#e8ddd4;}
.xd-cp.sel{background:linear-gradient(135deg,rgba(var(--xd-acc-rgb),.26),rgba(var(--xd-acc-lt-rgb),.12));border-color:rgba(var(--xd-acc-lt-rgb),.5);color:#fff;}
.xd-mm{display:flex;gap:10px;padding:9px 12px;border-radius:10px;border:1px solid rgba(255,255,255,.05);background:rgba(255,255,255,.018);margin-bottom:7px;transition:all .2s;align-items:flex-start;min-width:0;max-width:100%;box-sizing:border-box;overflow:hidden;}
.xd-mm:hover{border-color:rgba(var(--xd-acc-rgb),.28);transform:translateX(3px);}
.xd-mm .xd-mc{width:30px;height:30px;border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0;color:var(--xd-acc-text);background:rgba(var(--xd-acc-rgb),.1);border:1px solid rgba(var(--xd-acc-rgb),.22);}
.xd-mm p{font-size:11.5px;line-height:1.6;color:#e8ddd4;margin:0;overflow-wrap:anywhere;word-break:break-word;}
.xd-mm small{color:#706058;font-size:10px;display:block;margin-top:2px;overflow-wrap:anywhere;word-break:break-word;}
