      return '<div class="xd-cc"><div class="xd-cch"><div class="xd-av" style="background:linear-gradient(145deg,rgba(200,160,220,.22),rgba(200,160,220,.06));border-color:rgba(200,160,220,.4);color:#cfa8e0">📊</div><div><span class="xd-nm">' + xdEsc(t.name) + '</span><div class="xd-mt">自定义表 · 更新于 ' + (t.updatedAtFloor || 0) + ' 楼' + (t.note ? ' · ' + xdEsc(t.note) : '') + '</div></div><span class="xd-cacts"><button class="xd-cact" data-tfield-add="' + xdEsc(t.name) + '" title="添加属性"><span style="font-size:13px">+</span></button><button class="xd-cact del" data-ctable-del="' + xdEsc(t.name) + '" title="删除表格">' + xdI('tr', 13) + '</button></span></div><div class="xd-ccb"><div><div class="xd-ccc" style="grid-template-columns:minmax(0,1fr)">' + (t.fields.length ? '<div class="xd-fv"><h4>字段</h4>' + t.fields.map(f => fmtField(f, t.name)).join('') + '</div>' : '<div class="xd-li" style="color:#706058">暂无字段</div>') + '</div></div></div></div>';
    }).join('') : '';
