      '<div class="xd-cd"><h3>' + xdI('sl', 14) + '更多设置</h3><div style="font-size:11px;color:#a09088;line-height:1.7;margin-bottom:10px">标签过滤、向量服务、API 等高级项在完整面板中配置。</div><button class="xd-btn gh" data-act="foxPanel">' + xdI('grid', 14) + '打开狐忆完整面板</button></div>';
  }

  function xhDockPwHomeHtml() {
    const d = xdPwData(), c = xdPwCfg();
    const mods = d.modules || [], npcs = d.npcs || [];
    const active = mods.filter(x => !['aftermath_judged'].includes(x.lifecycleState)).length;
    const high = mods.filter(x => xdImpClass(x) === 'risk').length;
    const auto = c.autoMode && c.autoMode !== 'manual';
    const stats = [[active, '活跃事件', 'act'], [npcs.length, '后台 NPC', 'users'], [high, '高危事件', 'al'], [d.turn || 0, '已推进(轮)', 'ck']];
    const urgent = mods.filter(x => xdImpClass(x) === 'risk').sort((a, b) => (b.progress || 0) - (a.progress || 0))[0] || mods.slice().sort((a, b) => (b.progress || 0) - (a.progress || 0))[0];
    return '<div class="xd-sp"><div class="xd-pulse"></div><span>' + (auto ? '自动推进中' : '手动模式') + ' · 第 <b>' + (d.turn || 0) + '</b> 轮' + (d.worldClock ? ' · <b>' + xdEsc(d.worldClock) + '</b>' : '') + (d.globalState && d.globalState.title ? ' · ' + xdEsc(d.globalState.title) : '') + '</span><button class="xd-btn" style="margin-left:auto;padding:4px 12px;font-size:11px" data-act="pwDynamic">' + xdI('zp', 13) + '动态推进</button></div>' +
      '<div class="xd-sg">' + stats.map(s => '<div class="xd-st"><span class="xd-si">' + xdI(s[2], 15) + '</span><b class="xd-cnt" data-n="' + s[0] + '">0</b><small>' + s[1] + '</small></div>').join('') + '</div>' +
      '<div class="xd-cd"><h3>' + xdI('zp', 14) + '快捷操作<small>单请求动态推进 · 更省 token</small></h3><div style="display:flex;flex-wrap:wrap;gap:7px">' +
      '<button class="xd-btn" data-act="pwRun">' + xdI('play', 14) + '推进所有事件</button>' +
      '<button class="xd-btn gh" data-act="pwDynamic">' + xdI('zp', 14) + '动态推进</button>' +
      '<button class="xd-btn gh" data-go="world">' + xdI('box', 14) + '3D 世界</button>' +
      '<button class="xd-btn gh" data-act="pwSummary">' + xdI('file', 14) + '生成摘要</button>' +
      '<button class="xd-btn dn" data-act="pwClear">' + xdI('tr', 14) + '清空数据</button></div></div>' +
      (urgent ? '<div class="xd-cd"><h3>' + xdI('al', 14) + '最紧急事件<small>更多在「后台事件」/「3D世界」</small></h3><div class="xd-ev2 ' + (xdImpClass(urgent) === 'risk' ? 'rk' : '') + '" style="margin-bottom:0"><div class="xd-eh"><b>' + xdEsc(urgent.title || '未命名事件') + '</b><span class="xd-et2 ' + xdImpClass(urgent) + '">' + xdImpText(urgent) + '</span><span class="xd-ac"><button type="button" class="xd-item-toggle" data-item-toggle aria-expanded="false"><span class="xd-item-arrow">▼</span><span data-item-label>展开</span></button><button class="xd-eb pw-module-advance" data-pw-id="' + xdEsc(urgent.id || '') + '">' + xdI('play', 12) + '推进</button></span></div><p class="xd-clamp" data-item-clamp>' + xdEsc(xdEventFullText(urgent)) + '</p><div class="xd-pg2"><i style="width:' + Math.max(0, Math.min(100, urgent.progress || 0)) + '%"></i></div><small>进度 ' + (urgent.progress || 0) + '%' + (urgent.remainingTurns ? ' · 剩余 ' + urgent.remainingTurns + ' 轮' : '') + '</small></div></div>' : '<div class="xd-cd"><div class="xd-empty">当前还没有平行世界事件<br><small>点「推进所有事件」后，后台世界开始独立运转</small></div></div>');
  }

  function xhDockPwWorldHtml() {
    return '<div class="xd-cd" style="padding:10px"><h3>' + xdI('box', 14) + '3D 关系网格<small>真3D · 拖拽旋转 · 滚轮缩放 · 点节点看档案</small></h3><div class="xd-stg" id="xh-stg-pw"><canvas></canvas><div class="xd-p3-labels"></div><div class="xd-p3-load" style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#706058;font-size:11px;pointer-events:none">🌐 加载 3D 引擎…</div><button class="xd-btn" data-act="pw3d" style="position:absolute;top:10px;right:10px;z-index:9;padding:4px 10px;font-size:10.5px">' + xdI('full', 12) + '全屏</button><div class="xd-dr" id="xh-dr-pw"></div></div></div>' +
      '<div class="xd-cd"><h3>' + xdI('net', 14) + '3D 网格说明</h3><div style="font-size:11px;color:#a09088;line-height:1.7">主角与 NPC 按所在地点排布在 3D 圆周上；节点颜色=对主角看法，连线=关系，◆珠子=关联事件。小窗为缩小版 3D，点「全屏」展开即完整 3D 网格。</div></div>';
  }

  function xhDockPwEventsHtml() {
    const d = xdPwData();
    const mods = (d.modules || []).slice(0, 12);
    if (!mods.length) return '<div class="xd-cd"><div class="xd-empty">当前平行世界为空<br><small>点「世界总览 → 推进所有事件」做整轮初始化</small></div></div>';
    return mods.map(m => {
      const cls = xdImpClass(m);
      return '<div class="xd-ev2' + (cls === 'risk' ? ' rk' : cls === 'dice' ? ' dc' : '') + '"><div class="xd-eh"><b>' + xdEsc(m.title || '未命名事件') + '</b><span class="xd-et2 ' + cls + '">' + xdImpText(m) + '</span><span class="xd-ac"><button type="button" class="xd-item-toggle" data-item-toggle aria-expanded="false"><span class="xd-item-arrow">▼</span><span data-item-label>展开</span></button><button class="xd-eb pw-module-advance" data-pw-id="' + xdEsc(m.id || '') + '">' + xdI('play', 12) + '推进</button><button class="xd-eb del pw-module-delete" data-pw-id="' + xdEsc(m.id || '') + '">' + xdI('tr', 12) + '</button></span></div><p class="xd-clamp" data-item-clamp>' + xdEsc(xdEventFullText(m)) + '</p><div class="xd-pg2"><i style="width:' + Math.max(0, Math.min(100, m.progress || 0)) + '%"></i></div><small class="xd-clamp" data-item-clamp>进度 ' + (m.progress || 0) + '%' + (m.remainingTurns ? ' · 剩余 ' + m.remainingTurns + ' 轮' : '') + (m.currentLocation ? ' · ' + xdEsc(m.currentLocation) : '') + '</small></div>';
    }).join('');
  }

  function xhDockPwNpcsHtml() {
    const d = xdPwData();
    const npcs = (d.npcs || []).slice(0, 10);
    if (!npcs.length) return '<div class="xd-cd"><div class="xd-empty">还没有后台 NPC<br><small>推进平行世界后自动生成</small></div></div>';
    return npcs.map(n => {
      let al = -1; try { al = pwResolveNpcAttitudeLevel(n); } catch { al = n.attitudeLevel == null ? -1 : n.attitudeLevel; }
      const mv = [
        n.status && ('状态：' + n.status),
        n.currentThought && ('当前想法：' + n.currentThought),
        (n.shortTermGoal || n.goals) && ('短期目标：' + (n.shortTermGoal || n.goals)),
        n.longTermGoal && ('长期目标：' + n.longTermGoal),
        n.currentTask && ('正在进行：' + n.currentTask),
        n.autonomousIntent && ('自主意图：' + n.autonomousIntent),
        n.detail && ('档案：' + n.detail),
      ].filter(Boolean).join('\n') || '暂无动态';
      return '<div class="xd-nc"><div class="xd-a3">' + xdEsc(String(n.name || '?').slice(0, 1)) + '</div><div style="flex:1;min-width:0"><b>' + xdEsc(n.name) + '</b><small class="xd-clamp" data-item-clamp>' + xdEsc(n.location || '') + (n.location ? ' · ' : '') + '<span style="color:' + xdAttColor(al) + '">' + xdAttLabel(al) + '</span></small></div><div class="xd-mv xd-clamp" data-item-clamp>' + xdEsc(String(mv)) + '</div><button type="button" class="xd-item-toggle" data-item-toggle aria-expanded="false"><span class="xd-item-arrow">▼</span><span data-item-label>展开</span></button><span style="display:flex;gap:5px;flex-shrink:0"><button class="xd-eb pw-npc-btn" data-pw-npc-edit="' + xdEsc(n.name || '') + '" title="编辑此角色">' + xdI('ed', 12) + '</button><button class="xd-eb del pw-npc-btn" data-pw-npc-del="' + xdEsc(n.name || '') + '" title="删除此角色">' + xdI('tr', 12) + '</button></span></div>';
    }).join('') + '<div class="xd-cd"><h3>' + xdI('users', 14) + '后台演化规则</h3><div style="font-size:11px;color:#a09088;line-height:1.7">NPC 动向由推进引擎按「动机 + 当前目标」自动演化；在场 NPC 优先受主线事件影响，离场 NPC 按自身目标独立推进。</div></div>';
  }

  function xhDockPwSetHtml() {
    const c = xdPwCfg();
    const sw = (on, tg) => '<div class="xd-sw' + (on ? ' on' : '') + '" data-tg="' + tg + '"></div>';
    const intervalMode = c.autoMode === 'interval';
    return '<div class="xd-cd"><h3>' + xdI('inj', 14) + '注入与推进</h3><div class="xd-row2">' +
      '<div class="xd-cr"><span class="xd-lb">启用主线注入<small>摘要注入当前提示词</small></span>' + sw(!!c.enabled, 'pwInj') + '</div>' +
      '<div class="xd-cr"><span class="xd-lb">自动推进模式<small>与完整面板逻辑一致</small></span><select class="xd-ip" data-set-sel="autoMode"><option value="manual"' + (c.autoMode === 'manual' || !c.autoMode ? ' selected' : '') + '>纯手动</option><option value="auto"' + (c.autoMode === 'auto' ? ' selected' : '') + '>每次回复自动推进</option><option value="interval"' + (intervalMode ? ' selected' : '') + '>每隔 N 楼推进</option></select></div>' +
      '<div class="xd-cr"><span class="xd-lb">后台静默更新<small>完成后供后续对话注入</small></span>' + sw(!!c.backgroundSilent, 'pwSilent') + '</div>' +
      '<div class="xd-cr" style="opacity:' + (intervalMode ? '1' : '.42') + '"><span class="xd-lb">每隔 N 次回复推进<small>' + (intervalMode ? '当前可编辑' : '仅“每隔 N 楼”模式可编辑') + '</small></span><input class="xd-ip" data-set-num="autoInterval" value="' + (c.autoInterval ?? 5) + '"' + (intervalMode ? '' : ' disabled') + ' style="width:64px;text-align:right;cursor:' + (intervalMode ? 'text' : 'not-allowed') + '"></div>' +
      '<div class="xd-cr"><span class="xd-lb">平行思考<small>质量模式输出审查块</small></span><select class="xd-ip" data-set-sel="generationMode"><option value="fast"' + (c.generationMode !== 'quality' ? ' selected' : '') + '>快速模式</option><option value="quality"' + (c.generationMode === 'quality' ? ' selected' : '') + '>质量模式</option></select></div>' +
      '<div class="xd-cr"><span class="xd-lb">推进模式<small>单请求动态推进更省 token</small></span><select class="xd-ip" data-set-sel="advanceMode"><option value="two_phase"' + (c.advanceMode !== 'legacy_full' ? ' selected' : '') + '>单请求动态推进（默认）</option><option value="legacy_full"' + (c.advanceMode === 'legacy_full' ? ' selected' : '') + '>每次更新所有事件（旧）</option></select></div>' +
      '<div class="xd-cr"><span class="xd-lb">单次动态推进最多更新</span><input class="xd-ip" data-set-num="dynamicMaxModules" value="' + (c.dynamicMaxModules ?? 4) + '" style="width:64px;text-align:right"></div>' +
      '<div class="xd-cr"><span class="xd-lb">一次推进发送楼层<small>留空 = 全部</small></span><input class="xd-ip" data-set-str="chatHistoryLimit" value="' + (c.chatHistoryLimit ?? '') + '" placeholder="all" style="width:80px;text-align:right"></div>' +
      '<div class="xd-cr"><span class="xd-lb">命运骰<small>随机环境/威胁事件</small></span>' + sw(c.diceEnabled !== false, 'pwDice') + '</div>' +
      '</div></div>' +
      '<div class="xd-cd"><h3>' + xdI('sl', 14) + '生成规模与影响</h3><div class="xd-row2">' +
      '<div class="xd-cr"><span class="xd-lb">每事件字数范围</span><span><input class="xd-ip" data-set-num="eventWordMin" value="' + (c.eventWordMin ?? 100) + '" style="width:56px;text-align:right"> - <input class="xd-ip" data-set-num="eventWordMax" value="' + (c.eventWordMax ?? 800) + '" style="width:56px;text-align:right"></span></div>' +
      '<div class="xd-cr"><span class="xd-lb">最大注入模块数</span><input class="xd-ip" data-set-num="maxInjectModules" value="' + (c.maxInjectModules ?? 10) + '" style="width:64px;text-align:right"></div>' +
      '<div class="xd-cr"><span class="xd-lb">最大紧急事件数</span><input class="xd-ip" data-set-num="maxUrgentEvents" value="' + (c.maxUrgentEvents ?? 3) + '" style="width:64px;text-align:right"></div>' +
      '<div class="xd-cr"><span class="xd-lb">更多配置<small>API/骰子/标签过滤</small></span><button class="xd-btn gh" data-act="pwPanel">' + xdI('grid', 14) + '打开完整面板</button></div>' +
      '</div></div>';
  }

  function xhDockPageHtml(face, pg) {
    try {
      if (face === 'fox') {
        if (pg === 'home') return xhDockFoxHomeHtml();
        if (pg === 'recall') return xhDockFoxRecallHtml();
        if (pg === 'chars') return xhDockFoxCharsHtml();
        if (pg === 'table') return xhDockFoxTableHtml();
        if (pg === 'mem') return xhDockFoxMemHtml();
        if (pg === 'star') return xhDockFoxStarHtml();
        if (pg === 'set') return xhDockFoxSetHtml();
      } else {
        if (pg === 'home') return xhDockPwHomeHtml();
        if (pg === 'world') return xhDockPwWorldHtml();
        if (pg === 'events') return xhDockPwEventsHtml();
        if (pg === 'npcs') return xhDockPwNpcsHtml();
        if (pg === 'set') return xhDockPwSetHtml();
      }
    } catch (e) { log('[底栏] 页面渲染失败:', face, pg, e); }
    return '<div class="xd-cd"><div class="xd-empty">页面渲染失败</div></div>';
  }

  // ==================== 时间轴（真实数据） ====================
  function xhDockTimelineHtml(face) {
    const cfg = xdFaceCfg(face);
    const evs = [];
    let max = 48, unit = cfg.tlu;
    if (face === 'fox') {
      const m = xdFoxData();
      const atoms = (m.plotAtoms || []).slice(-8);
      max = Math.max(10, ...atoms.map(a => Number(a.floorEnd) || Number(a.floorStart) || 0));
      atoms.forEach(a => evs.push({ f: Math.max(1, Number(a.floorEnd) || Number(a.floorStart) || 1), t: (a.eventTime || ('第' + a.floorStart + '楼')) + ' · ' + String(a.text || '').slice(0, 18), c: '' }));
    } else {
      const d = xdPwData();
      max = Math.max(7, Number(d.turn) || 0);
      (d.modules || []).slice(-8).forEach(m => evs.push({ f: Math.max(1, Number(m.createdTurn) || max), t: String(m.title || '事件').slice(0, 22), c: xdImpClass(m) === 'risk' ? '#e87878' : xdImpClass(m) === 'dice' ? '#cfa8e0' : '' }));
    }
    return '<div class="xd-th"><b>' + xdI('ck', 14) + cfg.tlt + '</b><span style="font-size:10px;color:#706058">拖动回看 · 点光点看事件</span><span class="xd-fl">回看至第 <b class="xd-tln">' + max + '</b> ' + unit + '</span></div>' +
      '<div class="xd-track" data-tl="' + face + '" data-max="' + max + '"><div class="xd-fill" style="width:100%"></div>' + evs.map(e => '<div class="xd-ev" data-f="' + e.f + '" style="left:' + Math.min(99, e.f / max * 100) + '%;' + (e.c ? 'background:' + e.c + ';box-shadow:0 0 7px ' + e.c + ';' : '') + '"><div class="xd-et">' + xdEsc(e.t) + '</div></div>').join('') + '</div>';
  }

  function xhDockHealth(face) {
    if (face === 'fox') {
      const m = xdFoxData();
      const atoms = (m.plotAtoms || []).length, profs = Object.keys(m.characterProfiles || {}).length;
      const pct = Math.max(8, Math.min(98, Math.round(profs * 14 + (m.relationships || []).length * 4 + Math.min(atoms, 40) * 1.4)));
      return { val: profs ? '良好' : (atoms ? '积累中' : '待分析'), pct };
    }
    const d = xdPwData();
    const pct = Math.max(8, Math.min(98, 30 + (d.modules || []).length * 6 + (d.npcs || []).length * 4));
    return { val: pct + '%', pct };
  }

  function xhDockFaceHtml(face) {
    const cfg = xdFaceCfg(face);
    const cur = face === 'fox' ? XH_DOCK.foxPage : XH_DOCK.pwPage;
    const t = cfg.titles[cur] || ['', ''];
    const h = xhDockHealth(face);
    const navHtml = cfg.nav.map(n => n[0] === 'grp'
      ? '<div class="xd-grp">' + n[1] + '</div>'
      : '<div class="xd-ni' + (n[0] === cur ? ' act' : '') + '" data-page="' + n[0] + '"><span style="display:flex">' + xdI(n[1], 15) + '</span>' + n[2] + (n[3] ? '<span class="xd-bg">' + n[3] + '</span>' : '') + '</div>').join('');
    let ptg = '';
    if (face === 'fox') {
      const c = xdFoxCfg();
      ptg = '<span class="xd-tg">认知档案<span class="xd-sw' + (c.cognitionArchEnabled ? ' on' : '') + '" data-tg="cog"></span></span><span class="xd-tg">召回<span class="xd-sw' + (c.recallFloatEnabled ? ' on' : '') + '" data-tg="rec"></span></span>';
    } else {
      const c = xdPwCfg();
      const autoLabel = c.autoMode === 'auto' ? '每次回复' : (c.autoMode === 'interval' ? `隔${c.autoInterval || 5}楼` : '纯手动');
      ptg = '<span class="xd-tg">主线注入<span class="xd-sw' + (c.enabled ? ' on' : '') + '" data-tg="pwInj"></span></span><span style="font-size:10.5px;color:var(--xd-acc-text);white-space:nowrap">推进：' + autoLabel + '</span>';
    }
    return '<div class="xd-body"><div class="xd-side">' +
      '<div class="xd-brand"><div class="xd-bl">' + cfg.ico + '</div><div><b>' + cfg.stitle + '</b><small>' + cfg.ssub + '</small></div></div>' +
      '<div class="xd-nav">' + navHtml + '</div>' +
      '<div class="xd-foot"><div class="xd-fr"><span>' + cfg.flbl + '</span><b style="color:#3ad07a">' + h.val + '</b></div><div class="xd-mb"><i style="width:' + h.pct + '%"></i></div></div>' +
      '</div>' +
      '<div class="xd-main">' +
      '<div class="xd-ph"><div class="xd-t"><span class="xd-crumb">' + t[0] + '</span><small>' + t[1] + '</small></div><div class="xd-ptg">' + ptg + '</div></div>' +
      '<div class="xd-ct"><div class="xd-pg show">' + xhDockPageHtml(face, cur) + '</div></div>' +
      '<div class="xd-tl">' + xhDockTimelineHtml(face) + '</div>' +
      '</div></div>';
  }

  function xhDockRenderFaces() {
    const f = XH_DOCK.flipper; if (!f) return;
    const face = XH_DOCK.face;
    xhDockDisposeP3();
    f.innerHTML = '<div class="xd-face show" id="xh-face-' + face + '">' + xhDockFaceHtml(face) + '</div>';
    xhDockWireFace(face);
    xhDockRenderBarButtons();
  }

  function xhDockRenderBarButtons() {
    const el = topDoc.getElementById('xh-dock-bbs'); if (!el) return;
    const face = XH_DOCK.face, cfg = xdFaceCfg(face);
    // 折叠条右侧：单个「打开面板」按钮（展开后的页面导航已足够，不再重复放图标）
    el.innerHTML = '<span class="xd-bb-open" title="' + cfg.panelName + '">' + xdI('grid', 13) + '<span>' + cfg.panelName + '</span></span>';
    el.querySelector('.xd-bb-open').onclick = (e) => { e.stopPropagation(); xhDockAction(cfg.panelAct); };
  }

  function xhDockWireFace(face) {
    const el = topDoc.getElementById('xh-face-' + face); if (!el) return;
    el.querySelectorAll('.xd-ni').forEach(ni => { ni.onclick = (e) => { e.stopPropagation(); xhDockGoPage(face, ni.dataset.page); }; });
    el.querySelectorAll('[data-flip]').forEach(b => { b.onclick = (e) => { e.stopPropagation(); xhDockFlipFace(); }; });
    xhDockWireContent(el, face);
    // 时间轴拖动回看
    el.querySelectorAll('.xd-track').forEach(tr => {
      const max = Number(tr.dataset.max) || 48;
      const label = el.querySelector('.xd-tln');
      const setFloor = (cx) => {
        const r = tr.getBoundingClientRect();
        const p = Math.max(0, Math.min(1, (cx - r.left) / r.width));
        const f = Math.max(1, Math.round(p * max));
        tr.querySelector('.xd-fill').style.width = (f / max * 100) + '%';
        if (label) label.textContent = f;
        tr.querySelectorAll('.xd-ev').forEach(ev => { ev.style.opacity = Number(ev.dataset.f) <= f ? '1' : '.18'; });
      };
      let scrub = false;
      tr.addEventListener('pointerdown', (e) => { scrub = true; setFloor(e.clientX); try { tr.setPointerCapture(e.pointerId); } catch {} });
      tr.addEventListener('pointermove', (e) => { if (scrub) setFloor(e.clientX); });
      tr.addEventListener('pointerup', () => { scrub = false; });
    });
  }

  // 页面内容交互绑定（goPage 重建内容后也要调用）
  function xhDockWireContent(el, face) {
    el.querySelectorAll('[data-act]').forEach(b => { b.onclick = (e) => { e.stopPropagation(); xhDockAction(b.dataset.act); }; });
    el.querySelectorAll('[data-go]').forEach(b => { b.onclick = (e) => { e.stopPropagation(); xhDockGoPage(face, b.dataset.go); }; });
    el.querySelectorAll('.xd-sw').forEach(sw => { sw.onclick = (e) => { e.stopPropagation(); xhDockToggle(sw.dataset.tg, sw); }; });
    el.querySelectorAll('.xd-tg').forEach(tg => { tg.onclick = (e) => { e.stopPropagation(); const sw = tg.querySelector('.xd-sw'); if (sw && e.target !== sw) xhDockToggle(sw.dataset.tg, sw); }; });
    el.querySelectorAll('.xd-lyh').forEach(h => { h.onclick = (e) => { e.stopPropagation(); h.parentElement.classList.toggle('open'); }; });
    el.querySelectorAll('.xd-cch').forEach(h => { h.onclick = (e) => { e.stopPropagation(); h.parentElement.classList.toggle('open'); }; });
    el.querySelectorAll('[data-profile-edit]').forEach(b => {
      b.onclick = (e) => {
        e.stopPropagation();
        xhDockEditProfile(b.dataset.profileEdit);
      };
    });
    el.querySelectorAll('[data-profile-del]').forEach(b => {
      b.onclick = (e) => {
        e.stopPropagation();
        xhDockDeleteProfile(b.dataset.profileDel);
      };
    });
    // 🆕 人物表格：添加属性 / 编辑属性 / 删除属性 / 删除自定义表
    el.querySelectorAll('[data-tfield-add]').forEach(b => {
      b.onclick = (e) => { e.stopPropagation(); xhDockTableFieldAdd(b.dataset.tfieldAdd); };
    });
    el.querySelectorAll('[data-tfield-edit]').forEach(b => {
      b.onclick = (e) => { e.stopPropagation(); xhDockTableFieldEdit(b.dataset.tfieldTarget, b.dataset.tfieldEdit); };
    });
    el.querySelectorAll('[data-ctable-del]').forEach(b => {
      b.onclick = (e) => { e.stopPropagation(); xhDockDeleteCustomTable(b.dataset.ctableDel); };
    });
    el.querySelectorAll('[data-item-toggle]').forEach(button => {
      button.onclick = (e) => {
        e.stopPropagation();
        const item = button.closest('.xd-mm, .xd-ev2, .xd-nc');
        if (!item) return;
        const expanded = item.classList.toggle('xd-item-expanded');
        button.setAttribute('aria-expanded', String(expanded));
        const label = button.querySelector('[data-item-label]');
        if (label) label.textContent = expanded ? '收起' : '展开';
      };
    });
    el.querySelectorAll('.xd-clamp:not([data-item-clamp])').forEach(text => {
      const expandBtn = topDoc.createElement('button');
      expandBtn.type = 'button';
      expandBtn.className = 'xd-expand-btn';
      expandBtn.textContent = '点击展开';
      text.insertAdjacentElement('afterend', expandBtn);
      const recalc = () => {
        try {
          if (text.classList.contains('xd-expanded')) return;
          text.classList.toggle('xd-can-expand', text.scrollHeight > text.clientHeight + 2);
        } catch { }
      };
      const toggle = (e) => {
        e.stopPropagation();
        if (!text.classList.contains('xd-can-expand') && !text.classList.contains('xd-expanded')) return;
        text.classList.toggle('xd-expanded');
        expandBtn.textContent = text.classList.contains('xd-expanded') ? '点击收起' : '点击展开';
      };
      text.onclick = toggle;
      expandBtn.onclick = toggle;
      requestAnimationFrame(recalc);
      try {
        const observer = new ResizeObserver(recalc);
        observer.observe(text);
      } catch { }
    });
    // 数字滚动
    el.querySelectorAll('.xd-cnt').forEach(cn => {
      const n = Number(cn.dataset.n) || 0; let v = 0; const step = Math.max(1, Math.ceil(n / 22));
      cn.textContent = '0';
      const t = setInterval(() => { v += step; if (v >= n) { v = n; clearInterval(t); } cn.textContent = v; }, 28);
    });
    // 记忆库：分类筛选 + 搜索
    const q = el.querySelector('#xh-mem-q');
    if (q) {
      q.onclick = (e) => e.stopPropagation();
      q.oninput = () => xhDockMemFilter(el);
      q.onkeydown = (e) => e.stopPropagation();
    }
    el.querySelectorAll('.xd-cp[data-cat]').forEach(cp => {
      cp.onclick = (e) => {
        e.stopPropagation();
        el.querySelectorAll('.xd-cp[data-cat]').forEach(x => x.classList.remove('sel'));
        cp.classList.add('sel');
        xhDockMemFilter(el);
      };
    });
    // 设置项：输入框 / 下拉
    el.querySelectorAll('[data-set-num]').forEach(inp => {
      inp.onclick = (e) => e.stopPropagation();
      inp.onkeydown = (e) => e.stopPropagation();
      inp.onchange = () => xhDockSetNum(face, inp.dataset.setNum, inp.value);
    });
    el.querySelectorAll('[data-set-str]').forEach(inp => {
      inp.onclick = (e) => e.stopPropagation();
      inp.onkeydown = (e) => e.stopPropagation();
      inp.onchange = () => xhDockSetStr(face, inp.dataset.setStr, inp.value);
    });
    el.querySelectorAll('[data-set-sel]').forEach(sel => {
      sel.onclick = (e) => e.stopPropagation();
      sel.onchange = () => xhDockSetStr(face, sel.dataset.setSel, sel.value);
    });
    // 狐忆记忆条目：编辑 / 删除
    el.querySelectorAll('[data-mem-edit]').forEach(b => {
      b.onclick = (e) => {
        e.stopPropagation();
        try {
          const id = b.dataset.memEdit;
          const mem = (loadFoxMemory().memories || []).find(x => String(x.id) === String(id));
          if (mem) foxMemoryOpenEditDialog(mem);
          else toast('⚠️ 未找到该记忆', 'warning');
        } catch (err) { log('[底栏] 编辑记忆失败:', err); toast(`❌ 失败：${err?.message || err}`, 'error'); }
      };
    });
    el.querySelectorAll('[data-mem-del]').forEach(b => {
      b.onclick = async (e) => {
        e.stopPropagation();
        try {
          const id = b.dataset.memDel;
          const ok = topWindow?.confirm ? topWindow.confirm('确定要删除这条记忆吗？') : confirm('确定要删除这条记忆吗？');
          if (!ok) return;
          const data = loadFoxMemory();
          data.memories = (data.memories || []).filter(x => String(x.id) !== String(id));
          data.checkpoints = { turns: [], chunks: [] };
          state.foxMemoryBranchEpoch++;
          state.foxMemoryPendingBranchCheckpoint = null;
          if (!saveFoxMemory(data)) { toast('❌ 删除失败：记忆库写入失败', 'error'); return; }
          try { if (foxMemoryConfig?.injectToPreset) foxMemorySyncToPreset(); } catch {}
          try { foxMemoryRenderList(); foxMemoryRenderStats(); } catch {}
          toast('🗑️ 已删除', 'success');
          xhDockGoPage('fox', 'mem');
        } catch (err) { log('[底栏] 删除记忆失败:', err); toast(`❌ 失败：${err?.message || err}`, 'error'); }
      };
    });
    // 平行世界事件/NPC按钮（复用既有绑定器）
    if (face === 'pw') { try { pwBindModuleActionButtons(el); } catch {} try { pwBindNpcActionButtons(el); } catch {} }
    // 3D 页：挂载迷你 3D
    const stg = el.querySelector('.xd-stg');
    if (stg) xhDockMountP3(face, stg);
  }

  function xhDockMemFilter(el) {
    const q = String(el.querySelector('#xh-mem-q')?.value || '').trim().toLowerCase();
    const cat = el.querySelector('.xd-cp.sel[data-cat]')?.dataset.cat || '';
    el.querySelectorAll('#xh-mem-list .xd-mm').forEach(mm => {
      const okCat = !cat || mm.dataset.cat === cat;
      const okQ = !q || (mm.dataset.txt || '').includes(q);
      mm.style.display = okCat && okQ ? '' : 'none';
    });
  }

  function xhDockEditProfile(name) {
    try {
      const data = loadFoxMemory();
      const key = Object.keys(data.characterProfiles || {}).find(k => k.toLowerCase() === String(name || '').toLowerCase());
      if (!key) { toast('⚠️ 未找到该角色档案', 'warning'); return; }
      const current = data.characterProfiles[key];
      XH_DOCK.el?.querySelector('.xd-edit-mask')?.remove();
      const mask = topDoc.createElement('div');
      mask.className = 'xd-edit-mask';
      mask.innerHTML = '<div class="xd-edit-box"><div class="xd-edit-head"><div class="xd-av">' + xdEsc(String(current.name || '?').slice(0, 1)) + '</div><div><b>编辑「' + xdEsc(current.name) + '」</b><small>JSON 档案 · 保存时自动校验</small></div><button class="xd-edit-close" type="button" title="关闭">' + xdI('x', 15) + '</button></div><textarea class="xd-edit-ta" spellcheck="false"></textarea><div class="xd-edit-actions"><button class="xd-btn gh" type="button" data-edit-cancel>取消</button><button class="xd-btn" type="button" data-edit-save>' + xdI('ed', 14) + '保存档案</button></div></div>';
      const textarea = mask.querySelector('.xd-edit-ta');
      textarea.value = JSON.stringify(current, null, 2);
      const close = () => mask.remove();
      mask.querySelector('.xd-edit-close').onclick = close;
      mask.querySelector('[data-edit-cancel]').onclick = close;
      mask.onclick = e => { if (e.target === mask) close(); };
      mask.querySelector('[data-edit-save]').onclick = () => {
        try {
          const latest = loadFoxMemory();
          const normalized = foxMemoryNormalizeCharacterProfile(JSON.parse(textarea.value), current.name);
          if (!normalized || !foxMemoryIsPlausibleCharacterName(normalized.name)) {
            toast('❌ 档案格式无效：角色名称缺失或不合法', 'error');
            return;
          }
          const latestKey = Object.keys(latest.characterProfiles || {}).find(k => k.toLowerCase() === key.toLowerCase());
          if (!latestKey) { toast('⚠️ 原档案已不存在，请重新打开', 'warning'); close(); return; }
          const duplicateKey = Object.keys(latest.characterProfiles || {}).find(k => k !== latestKey && k.toLowerCase() === normalized.name.toLowerCase());
          if (duplicateKey) { toast(`❌ 已存在同名角色档案「${duplicateKey}」`, 'error'); return; }
          if (latestKey !== normalized.name) delete latest.characterProfiles[latestKey];
          latest.characterProfiles[normalized.name] = normalized;
          latest.relationships = (latest.relationships || []).map(relation => foxMemoryNormalizeRelationship({
            ...relation,
            a: String(relation.a).toLowerCase() === latestKey.toLowerCase() ? normalized.name : relation.a,
            b: String(relation.b).toLowerCase() === latestKey.toLowerCase() ? normalized.name : relation.b,
          })).filter(Boolean);
          foxMemoryRefreshRelationRefs(latest);
          if (!saveFoxMemory(latest)) { toast('❌ 保存失败：记忆库写入失败', 'error'); return; }
          try { if (foxMemoryConfig?.injectToPreset) foxMemorySyncToPreset(); } catch {}
          close();
          toast(`✅ 已保存角色档案「${normalized.name}」`, 'success');
          xhDockGoPage('fox', 'chars');
        } catch (e) {
          toast(`❌ 档案 JSON 解析失败：${e?.message || e}`, 'error');
        }
      };
      XH_DOCK.el?.appendChild(mask);
      requestAnimationFrame(() => textarea.focus());
    } catch (e) {
      log('[底栏] 编辑角色档案失败:', e);
      toast(`❌ 打开档案编辑器失败：${e?.message || e}`, 'error');
    }
  }

  function xhDockDeleteProfile(name) {
    try {
      const data = loadFoxMemory();
      const key = Object.keys(data.characterProfiles || {}).find(k => k.toLowerCase() === String(name || '').toLowerCase());
      if (!key) { toast('⚠️ 未找到该角色档案', 'warning'); return; }
      const ok = topWindow?.confirm
        ? topWindow.confirm(`确定删除角色档案「${key}」吗？\n\n与该角色相连的关系记录也会一并删除。`)
        : confirm(`确定删除角色档案「${key}」吗？`);
      if (!ok) return;
      delete data.characterProfiles[key];
      data.relationships = (data.relationships || []).filter(relation =>
        String(relation.a).toLowerCase() !== key.toLowerCase() && String(relation.b).toLowerCase() !== key.toLowerCase()
      );
      foxMemoryRefreshRelationRefs(data);
      if (!saveFoxMemory(data)) { toast('❌ 删除失败：记忆库写入失败', 'error'); return; }
      try { if (foxMemoryConfig?.injectToPreset) foxMemorySyncToPreset(); } catch {}
      toast(`🗑 已删除角色档案「${key}」`, 'success');
      xhDockGoPage('fox', 'chars');
    } catch (e) {
      log('[底栏] 删除角色档案失败:', e);
      toast(`❌ 删除失败：${e?.message || e}`, 'error');
    }
  }

  // 🆕 人物表格操作：查找自定义字段宿主（人物档案 custom 或独立自定义表）
  function xhDockFindTableHost(data, targetName) {
    const canonical = foxMemoryCanonicalCharacterName(targetName);
    const profileKey = Object.keys(data.characterProfiles || {}).find(k => k.toLowerCase() === String(canonical || '').toLowerCase());
    if (profileKey) {
      const profile = data.characterProfiles[profileKey];
      if (!profile.custom) profile.custom = { fields: [], countedRanges: [], templateSeeded: false };
      return { kind: 'profile', obj: profile, container: profile.custom, name: profileKey };
    }
    const table = (data.customTables || []).find(t => String(t.name).toLowerCase() === String(targetName || '').toLowerCase());
    if (table) return { kind: 'table', obj: table, container: table, name: table.name };
    return null;
  }

  function xhDockTableFieldAdd(targetName) {
    try {
      const mask = topDoc.createElement('div');
      mask.className = 'xd-edit-mask';
      mask.innerHTML = '<div class="xd-edit-box" style="max-width:420px"><div class="xd-edit-head"><div class="xd-av" style="font-size:13px">+</div><div><b>添加属性</b><small>目标：' + xdEsc(targetName) + '</small></div><button class="xd-edit-close" type="button">' + xdI('x', 15) + '</button></div><div style="padding:12px 14px;display:flex;flex-direction:column;gap:10px">' +
        '<div><label style="font-size:10.5px;color:#a09088;display:block;margin-bottom:4px">属性名</label><input class="xd-ip" id="xd-tf-key" style="width:100%" placeholder="如：身高 / 出现次数" maxlength="40"></div>' +
        '<div><label style="font-size:10.5px;color:#a09088;display:block;margin-bottom:4px">类型</label><select class="xd-ip" id="xd-tf-type" style="width:100%"><option value="state">状态（直接覆盖）</option><option value="counter">计数（AI报增量累加）</option><option value="list">列表（加减条目）</option></select></div>' +
        '<div><label style="font-size:10.5px;color:#a09088;display:block;margin-bottom:4px">初始值</label><input class="xd-ip" id="xd-tf-val" style="width:100%" placeholder="状态型填文本；计数型填数字；列表型用顿号分隔"></div>' +
        '<div><label style="font-size:10.5px;color:#a09088;display:block;margin-bottom:4px">提示（可选）</label><input class="xd-ip" id="xd-tf-hint" style="width:100%" placeholder="给AI的填写提示" maxlength="120"></div>' +
        '</div><div class="xd-edit-actions"><button class="xd-btn gh" type="button" data-edit-cancel>取消</button><button class="xd-btn" type="button" data-edit-save>添加</button></div></div>';
      XH_DOCK.el?.appendChild(mask);
      const close = () => mask.remove();
      mask.querySelector('.xd-edit-close').onclick = close;
      mask.querySelector('[data-edit-cancel]').onclick = close;
      mask.onclick = e => { if (e.target === mask) close(); };
      mask.querySelector('[data-edit-save]').onclick = () => {
        const key = String(mask.querySelector('#xd-tf-key').value || '').trim();
        if (!key) { toast('⚠️ 请输入属性名', 'warning'); return; }
        const type = mask.querySelector('#xd-tf-type').value;
        const valRaw = String(mask.querySelector('#xd-tf-val').value || '').trim();
        const hint = String(mask.querySelector('#xd-tf-hint').value || '').trim();
        const data = loadFoxMemory();
        const host = xhDockFindTableHost(data, targetName);
        if (!host) { toast('⚠️ 未找到目标', 'warning'); close(); return; }
        if (host.container.fields.some(f => f.key === key)) { toast('⚠️ 该属性已存在', 'warning'); return; }
        if (host.container.fields.length >= 40) { toast('⚠️ 字段数已达上限 40', 'warning'); return; }
        let value;
        if (type === 'counter') { const n = Number(valRaw); value = Number.isFinite(n) ? Math.trunc(n) : 0; }
        else if (type === 'list') value = valRaw ? valRaw.split(/[,，、;；]+/).map(s => s.trim()).filter(Boolean) : [];
        else value = valRaw;
        host.container.fields.push(foxMemoryNormalizeTableField({ key, type, value, hint }));
        host.obj.updatedAtFloor = Math.max(host.obj.updatedAtFloor || 0, getCurrentLastMessageId());
        if (host.kind === 'profile') host.obj.updatedAt = new Date().toISOString();
        if (!saveFoxMemory(data)) { toast('❌ 保存失败', 'error'); return; }
        close();
        toast(`✅ 已添加属性「${key}」`, 'success');
        xhDockGoPage('fox', 'table');
      };
      requestAnimationFrame(() => mask.querySelector('#xd-tf-key').focus());
    } catch (e) { log('[底栏] 添加表格属性失败:', e); toast(`❌ ${e?.message || e}`, 'error'); }
  }

  function xhDockTableFieldEdit(targetName, fieldKey) {
    // targetName 为空时需在所有宿主里搜索（简化：从当前页面数据找）
    try {
      const data = loadFoxMemory();
      let host = null;
      if (targetName) host = xhDockFindTableHost(data, targetName);
      else {
        for (const p of Object.values(data.characterProfiles || {})) {
          if ((p.custom?.fields || []).some(f => f.key === fieldKey)) { host = { kind: 'profile', obj: p, container: p.custom, name: p.name }; break; }
        }
        if (!host) for (const t of data.customTables || []) {
          if ((t.fields || []).some(f => f.key === fieldKey)) { host = { kind: 'table', obj: t, container: t, name: t.name }; break; }
        }
      }
      if (!host) { toast('⚠️ 未找到该属性', 'warning'); return; }
      const field = host.container.fields.find(f => f.key === fieldKey);
      if (!field) { toast('⚠️ 未找到该属性', 'warning'); return; }
      const mask = topDoc.createElement('div');
      mask.className = 'xd-edit-mask';
      const curVal = field.type === 'list' ? (Array.isArray(field.value) ? field.value.join('、') : '') : String(field.value ?? '');
      mask.innerHTML = '<div class="xd-edit-box" style="max-width:420px"><div class="xd-edit-head"><div class="xd-av" style="font-size:13px">✎</div><div><b>编辑属性</b><small>' + xdEsc(host.name) + ' · ' + xdEsc(fieldKey) + '</small></div><button class="xd-edit-close" type="button">' + xdI('x', 15) + '</button></div><div style="padding:12px 14px;display:flex;flex-direction:column;gap:10px">' +
        '<div><label style="font-size:10.5px;color:#a09088;display:block;margin-bottom:4px">类型</label><select class="xd-ip" id="xd-tf-type" style="width:100%"><option value="state"' + (field.type === 'state' ? ' selected' : '') + '>状态</option><option value="counter"' + (field.type === 'counter' ? ' selected' : '') + '>计数</option><option value="list"' + (field.type === 'list' ? ' selected' : '') + '>列表</option></select></div>' +
        '<div><label style="font-size:10.5px;color:#a09088;display:block;margin-bottom:4px">值</label><input class="xd-ip" id="xd-tf-val" style="width:100%" value="' + xdEsc(curVal) + '"></div>' +
        '<div><label style="font-size:10.5px;color:#a09088;display:block;margin-bottom:4px">提示</label><input class="xd-ip" id="xd-tf-hint" style="width:100%" value="' + xdEsc(field.hint || '') + '" maxlength="120"></div>' +
        '</div><div class="xd-edit-actions"><button class="xd-btn dn" type="button" data-edit-del style="margin-right:auto">删除属性</button><button class="xd-btn gh" type="button" data-edit-cancel>取消</button><button class="xd-btn" type="button" data-edit-save>保存</button></div></div>';
      XH_DOCK.el?.appendChild(mask);
      const close = () => mask.remove();
      mask.querySelector('.xd-edit-close').onclick = close;
      mask.querySelector('[data-edit-cancel]').onclick = close;
      mask.onclick = e => { if (e.target === mask) close(); };
      mask.querySelector('[data-edit-del]').onclick = () => {
        host.container.fields = host.container.fields.filter(f => f.key !== fieldKey);
        host.obj.updatedAtFloor = Math.max(host.obj.updatedAtFloor || 0, getCurrentLastMessageId());
        if (!saveFoxMemory(data)) { toast('❌ 保存失败', 'error'); return; }
        close();
        toast(`🗑 已删除属性「${fieldKey}」`, 'success');
        xhDockGoPage('fox', 'table');
      };
      mask.querySelector('[data-edit-save]').onclick = () => {
        const newType = mask.querySelector('#xd-tf-type').value;
        const valRaw = String(mask.querySelector('#xd-tf-val').value || '').trim();
        const hint = String(mask.querySelector('#xd-tf-hint').value || '').trim();
        let value;
        if (newType === 'counter') { const n = Number(valRaw); value = Number.isFinite(n) ? Math.trunc(n) : 0; }
        else if (newType === 'list') value = valRaw ? valRaw.split(/[,，、;；]+/).map(s => s.trim()).filter(Boolean) : [];
        else value = valRaw;
        const idx = host.container.fields.findIndex(f => f.key === fieldKey);
        host.container.fields[idx] = foxMemoryNormalizeTableField({ key: fieldKey, type: newType, value, hint });
        host.obj.updatedAtFloor = Math.max(host.obj.updatedAtFloor || 0, getCurrentLastMessageId());
        if (host.kind === 'profile') host.obj.updatedAt = new Date().toISOString();
        if (!saveFoxMemory(data)) { toast('❌ 保存失败', 'error'); return; }
        close();
        toast(`✅ 已保存属性「${fieldKey}」`, 'success');
        xhDockGoPage('fox', 'table');
      };
