  function xhDockAction(act) {
    try {
      if (act === 'fox3d') foxGraphOpen();
      else if (act === 'pw3d') pwGraphOpen();
      else if (act === 'foxPanel') openFoxMemoryPanel();
      else if (act === 'pwPanel') pwOpenPanel();
      else if (act === 'foxAnalyze') { if (typeof foxMemoryAnalyzeNow === 'function') foxMemoryAnalyzeNow(); }
      else if (act === 'pwRun') { if (typeof pwRunCycle === 'function') pwRunCycle(false); }
      else if (act === 'pwDynamic') {
        const c = xdPwCfg();
        if (c.advanceMode === 'legacy_full') { toast('⚠️ 当前推进模式为「每次更新所有事件（旧）」，无法使用动态推进，请到「配置」切换', 'warning'); return; }
        if (typeof pwRunDynamicCycle === 'function') pwRunDynamicCycle(false);
      }
      else if (act === 'pwSummary') { if (typeof pwSummarizeOnly === 'function') pwSummarizeOnly(); }
      else if (act === 'foxTableTpl') xhDockEditTableTemplate();
      else if (act === 'foxTableNew') xhDockNewCustomTable();
      else if (act === 'foxTableNewChar') xhDockNewCharacterProfile();
      else if (act === 'foxTableSeed') xhDockSeedTemplateToAll();
      else if (act === 'pwClear') {
        const ok = topWindow?.confirm ? topWindow.confirm('确定清空当前聊天的平行世界数据吗？') : confirm('确定清空当前聊天的平行世界数据吗？');
        if (!ok) return;
        pwSaveData(pwEmptyData());
        xhDockRenderFaces(); xhDockRefresh();
        toast('🗑 已清空平行世界数据', 'info');
      }
    } catch (e) { log('[底栏] 动作失败:', act, e); toast(`❌ 失败：${e?.message || e}`, 'error'); }
  }
