    try {
      const v = parseInt(raw, 10);
      if (!Number.isFinite(v) || v < 0) { toast('⚠️ 请输入有效数字', 'warning'); return; }
      if (face === 'fox') { foxMemoryConfig = loadFoxMemoryConfig(); foxMemoryConfig[key] = v; saveFoxMemoryConfig(); }
      else { const c = xdPwCfg(); c[key] = v; pwState.config = c; pwSaveConfig(); }
      toast('✅ 已保存', 'success');
    } catch (e) { log('[底栏] 设置失败:', key, e); toast(`❌ 保存失败：${e?.message || e}`, 'error'); }
  }
