    try {
      if (face === 'fox' && key === 'autoMode') foxMemoryApplyAutoMode(val);
      else if (face === 'fox') { foxMemoryConfig = loadFoxMemoryConfig(); foxMemoryConfig[key] = val; saveFoxMemoryConfig(); }
      else { const c = xdPwCfg(); c[key] = val; if (key === 'autoMode' && val !== 'manual') c.enabled = true; pwState.config = c; pwSaveConfig(); if (key === 'autoMode') xhDockGoPage('pw', 'set'); }
