  function xhDockFlipFace() {
    if (XH_DOCK.flipping) return;
    const target = XH_DOCK.face === 'fox' ? 'pw' : 'fox';
    XH_DOCK.flipping = true;
    const flipper = XH_DOCK.flipper, badge = topDoc.getElementById('xh-dock-badge'), btn = topDoc.getElementById('xh-dock-flip');
    if (btn) { btn.classList.add('spin'); setTimeout(() => btn.classList.remove('spin'), 520); }
    const swap = () => {
      XH_DOCK.face = target;
      XH_DOCK.el.dataset.face = target;
      badge.classList.toggle('flipped', target === 'pw');
      if (XH_DOCK.open) xhDockRenderFaces();
      xhDockRefresh();
      XH_DOCK.flipping = false;
      toast(target === 'pw' ? '🌌 已切换到平行世界' : '🦊 已切换到狐忆', 'info');
    };
    if (XH_DOCK.open) { flipper.classList.add('turning'); setTimeout(() => { swap(); flipper.classList.remove('turning'); }, 250); }
    else { badge.style.transform = 'rotateY(90deg)'; setTimeout(() => { swap(); badge.style.transform = ''; }, 250); }
  }

