  // ==================== 悬浮窗 显示/关闭 ====================
  // face：打开时定位到指定面（'fox'|'pw'），不影响后续自由切换；关闭时忽略。
  function xhDockSetVisible(v, face) {
    try { if (typeof initUnifiedDock === 'function') initUnifiedDock(); } catch {}
    if (!XH_DOCK.created || !XH_DOCK.el) return;
    XH_DOCK.visible = !!v;
    try { localStorage.setItem(XH_DOCK_VISIBLE_KEY, String(XH_DOCK.visible)); } catch {}
    if (v) {
      XH_DOCK.el.classList.remove('xh-dock-hidden');
      if (face && XH_DOCK.face !== face) {
        // 静默切到指定面（不弹 toast、不播翻转动画）
        XH_DOCK.face = face;
        XH_DOCK.el.dataset.face = face;
        const badge = topDoc.getElementById('xh-dock-badge');
        if (badge) badge.classList.toggle('flipped', face === 'pw');
        if (XH_DOCK.open) xhDockRenderFaces();
        xhDockRefresh();
      }
      if (!XH_DOCK.open) xhDockToggleOpen();
      else xhDockRefresh();
    } else {
      XH_DOCK.el.classList.add('xh-dock-hidden');
      xhDockDisposeP3();
    }
    const foxBtn = topDoc.getElementById('foxmem-dock-btn');
    const pwBtn = topDoc.getElementById('pw-dock-btn');
    if (foxBtn) foxBtn.title = XH_DOCK.visible ? '关闭底栏悬浮窗' : '打开底栏悬浮窗（狐忆面）';
    if (pwBtn) pwBtn.title = XH_DOCK.visible ? '关闭底栏悬浮窗' : '打开底栏悬浮窗（平行世界面）';
  }
