  function xhDockToggleVisibility(face) {
    if (XH_DOCK.created && XH_DOCK.visible) {
      xhDockSetVisible(false);
      toast('🦊 底栏悬浮窗已关闭，点击面板顶部「底栏悬浮窗」可再次打开', 'info');
    } else {
      xhDockSetVisible(true, face);
    }
