  }

  function xdP3Mount(canvas, labelLayer, data, onPick) {
    const T = topWindow.THREE;
    const p = { T, canvas, labelLayer, nodes: [], edges: [], beads: [], autoRotate: true, dragging: false, dragStart: { x: 0, y: 0 }, dragRot: { x: 0, y: 0 }, camDist: 16, camDistTarget: 16, time: 0, sv: new T.Vector3(), onPick };
    const w = canvas.clientWidth || 600, h = canvas.clientHeight || 300;
    p.renderer = new T.WebGLRenderer({ canvas, antialias: true });
    p.renderer.setPixelRatio(Math.min(2, topWindow.devicePixelRatio || 1));
    p.renderer.setSize(w, h, false);
    p.renderer.setClearColor(0x08060a, 1);
    p.scene = new T.Scene(); p.scene.fog = new T.Fog(0x08060a, 20, 50);
    p.camera = new T.PerspectiveCamera(55, w / h, 0.1, 200); p.camera.position.set(0, 4, p.camDist); p.camera.lookAt(0, 0, 0);
    p.group = new T.Group(); p.group.rotation.x = 0.42; p.scene.add(p.group);
    p.scene.add(new T.AmbientLight(0x4a3a2a, 0.6));
    const pl = new T.PointLight(0xf0a070, 1.2, 40, 1.5); pl.position.set(0, 0, 0); p.scene.add(pl);
    const fl = new T.PointLight(0x4a6a8a, 0.4, 50, 2); fl.position.set(10, 8, 12); p.scene.add(fl);
    try { const sg = new T.BufferGeometry(), N = 220, F32 = topWindow.Float32Array || Float32Array, pos = new F32(N * 3); for (let i = 0; i < N; i++) { const r = 30 + Math.random() * 20, t = Math.random() * 6.283, p2 = Math.acos(2 * Math.random() - 1); pos[i * 3] = r * Math.sin(p2) * Math.cos(t); pos[i * 3 + 1] = r * Math.sin(p2) * Math.sin(t); pos[i * 3 + 2] = r * Math.cos(p2); } sg.setAttribute('position', new T.BufferAttribute(pos, 3)); p.scene.add(new T.Points(sg, new T.PointsMaterial({ color: 0x9a8a7a, size: 0.14, transparent: true, opacity: 0.45, fog: false }))); } catch {}
    try { const grid = new T.GridHelper(50, 25, 0x2a1a14, 0x1a120e); grid.position.y = -14; grid.material.transparent = true; grid.material.opacity = 0.12; p.scene.add(grid); } catch {}
    p.raycaster = new T.Raycaster(); p.pointer = new T.Vector2(-2, -2);
    // ---- 构建节点/连线/珠子 ----
    const makeNodeMesh = (r, colorStr, isPlayer) => {
      const color = new T.Color(colorStr);
      const core = new T.Mesh(new T.SphereGeometry(r, 32, 32), new T.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: isPlayer ? 0.6 : 0.35, metalness: 0.4, roughness: 0.45 }));
      const g1 = new T.Mesh(new T.SphereGeometry(r * 1.3, 18, 18), new T.MeshBasicMaterial({ color, transparent: true, opacity: 0.18, blending: T.AdditiveBlending, depthWrite: false }));
      const ring = new T.Mesh(new T.TorusGeometry(r * (isPlayer ? 2.2 : 1.9), Math.max(0.015, r * 0.04), 8, 32), new T.MeshBasicMaterial({ color, transparent: true, opacity: isPlayer ? 0.35 : 0.2, blending: T.AdditiveBlending, depthWrite: false }));
      ring.rotation.x = 1.57;
      return { core, g1, ring };
    };
    const locMap = new Map();
    (data.npcs || []).forEach(n => { const l = n.location || '未知地点'; if (!locMap.has(l)) locMap.set(l, []); locMap.get(l).push(n); });
    const locs = Array.from(locMap.keys()), total = locs.length + 1, mapR = Math.max(10, total * 2.8);
    const meshByName = new Map();
    const playerPos = new T.Vector3(mapR, 0, 0);
    const pm = makeNodeMesh(1.3, '#f0a070', true);
    [pm.core, pm.g1, pm.ring].forEach(mm => { mm.position.copy(playerPos); p.group.add(mm); });
    pm.core.userData = { isPlayer: true };
    p.nodes.push({ mesh: pm.core, g1: pm.g1, ring: pm.ring, label: null, isPlayer: true, name: data.player, npc: null, ringRot: 0 });
    meshByName.set(data.player, pm.core);
    const locPos = new Map();
    locs.forEach((l, i) => { const ang = ((i + 1) / total) * 6.283, yv = Math.sin(i * 2.3) * 1.5; locPos.set(l, new T.Vector3(mapR * Math.cos(ang), yv, mapR * Math.sin(ang))); });
    const makeNode = (n, pos) => {
      const cs = (n.attitudeLevel == null || n.attitudeLevel < 0) ? 'rgb(136,136,136)' : xdAttColor(n.attitudeLevel);
      const mm = makeNodeMesh(0.65, cs, false);
      [mm.core, mm.g1, mm.ring].forEach(x => { x.position.copy(pos); p.group.add(x); });
      mm.core.userData = { isPlayer: false, name: n.name, npc: n };
      let ld = null;
      if (labelLayer) {
        ld = topDoc.createElement('div');
        ld.className = 'xd-p3-label';
        ld.innerHTML = '<span class="xd-p3-label-dot" style="background:' + cs + ';color:' + cs + '"></span>' + xdEsc(n.name);
        ld.onclick = (e) => { e.stopPropagation(); onPick(n); };
        labelLayer.appendChild(ld);
      }
      p.nodes.push({ mesh: mm.core, g1: mm.g1, ring: mm.ring, label: ld, isPlayer: false, name: n.name, npc: n, ringRot: Math.random() * 6.283 });
      return mm.core;
    };
    locMap.forEach((npcs, loc) => {
      const lp = locPos.get(loc), cr = Math.max(1.2, npcs.length * 0.6);
      npcs.forEach((n, i) => { const ang = (i / Math.max(npcs.length, 1)) * 6.283; meshByName.set(n.name, makeNode(n, lp.clone().add(new T.Vector3(cr * Math.cos(ang), 0, cr * Math.sin(ang))))); });
    });
    const makeEdge = (fm, tm, level) => {
      if (!fm || !tm) return;
      const g = new T.BufferGeometry().setFromPoints([fm.position, tm.position]);
      const lv = level == null ? 50 : level;
      const o = 0.2 + Math.abs(lv - 50) / 50 * 0.35;
      p.group.add(new T.Line(g, new T.LineBasicMaterial({ color: new T.Color(xdAttColor(lv)), transparent: true, opacity: o })));
    };
    p.nodes.forEach(nm => { if (!nm.isPlayer && nm.npc && nm.npc.attitudeLevel >= 0) makeEdge(p.nodes[0].mesh, nm.mesh, nm.npc.attitudeLevel); });
    (data.rels || []).forEach(r => { const fm = meshByName.get(r.from), tm = meshByName.get(r.to); if (fm && tm && (r.relationLevel == null || r.relationLevel >= 0)) makeEdge(fm, tm, r.relationLevel == null ? 50 : r.relationLevel); });
    const addBead = (evt, pos) => {
      const cs = xdP3ImpColor(evt.impact || 'low');
      const color = new T.Color(cs);
      const core = new T.Mesh(new T.IcosahedronGeometry(0.3, 0), new T.MeshStandardMaterial({ color, emissive: color, emissiveIntensity: 0.5, metalness: 0.6, roughness: 0.3, flatShading: true }));
      const glow = new T.Mesh(new T.SphereGeometry(0.5, 12, 12), new T.MeshBasicMaterial({ color, transparent: true, opacity: 0.22, blending: T.AdditiveBlending, depthWrite: false }));
      core.position.copy(pos); glow.position.copy(pos);
      core.userData = { isBead: true, evt };
      p.group.add(core); p.group.add(glow);
      p.beads.push({ mesh: core, glow, evt, phase: Math.random() * 6.283 });
    };
    (data.evts || []).forEach(evt => {
      const linked = evt.linkedNpcs || [];
      if (linked.length < 2) { const mesh = meshByName.get(linked[0]); if (!mesh) return; const pos = mesh.position.clone(); pos.y += 1.2; addBead(evt, pos); }
      else for (let i = 0; i < linked.length; i++) for (let j = i + 1; j < linked.length; j++) { const fm = meshByName.get(linked[i]), tm = meshByName.get(linked[j]); if (fm && tm) addBead(evt, fm.position.clone().lerp(tm.position, 0.5)); }
    });
    p.meshArr = p.nodes.map(n => n.mesh); p.beadArr = p.beads.map(b => b.mesh);
    // ---- 交互 ----
    const updatePointer = (e) => {
      const rect = p.canvas.getBoundingClientRect();
      const rw = rect.width || p.canvas.clientWidth || 600;
      const rh = rect.height || p.canvas.clientHeight || 300;
      p.pointer.x = ((e.clientX - rect.left) / rw) * 2 - 1;
      p.pointer.y = -((e.clientY - rect.top) / rh) * 2 + 1;
    };
    canvas.style.cursor = 'grab';
    canvas.addEventListener('pointerdown', (e) => { updatePointer(e); p.dragging = true; p.dragStart = { x: e.clientX, y: e.clientY }; p.dragRot = { x: p.group.rotation.x, y: p.group.rotation.y }; canvas.style.cursor = 'grabbing'; });
    const onMove = (e) => {
      if (!p.canvas || !p.canvas.isConnected) { topWindow.removeEventListener('pointermove', onMove); return; }
      updatePointer(e);
      if (p.dragging && p.group) { p.group.rotation.y = p.dragRot.y + (e.clientX - p.dragStart.x) * 0.006; p.group.rotation.x = Math.max(-1.4, Math.min(1.4, p.dragRot.x + (e.clientY - p.dragStart.y) * 0.006)); }
    };
    const onUp = (e) => {
      if (!p.dragging) return;
      p.dragging = false; canvas.style.cursor = 'grab';
      if (Math.abs(e.clientX - p.dragStart.x) < 5 && Math.abs(e.clientY - p.dragStart.y) < 5) {
        updatePointer(e);
        p.raycaster.setFromCamera(p.pointer, p.camera);
