        if (hits.length) { const o = hits[0].object; if (o.userData.isBead) onPick(o.userData.evt); else if (o.userData.isPlayer) onPick({ isPlayer: true }); else if (o.userData.npc) onPick(o.userData.npc); }
      }
    };
    const onCancel = () => { p.dragging = false; canvas.style.cursor = 'grab'; };
    topWindow.addEventListener('pointermove', onMove);
    topWindow.addEventListener('pointerup', onUp);
    topWindow.addEventListener('pointercancel', onCancel);
    p.disposeEvents = () => { topWindow.removeEventListener('pointermove', onMove); topWindow.removeEventListener('pointerup', onUp); topWindow.removeEventListener('pointercancel', onCancel); };
    canvas.addEventListener('wheel', (e) => { e.preventDefault(); p.camDistTarget = Math.max(8, Math.min(45, p.camDistTarget + e.deltaY * 0.02)); return false; }, { passive: false });
    p.resize = () => { const w2 = canvas.clientWidth || 600, h2 = canvas.clientHeight || 300; p.camera.aspect = w2 / h2; p.camera.updateProjectionMatrix(); p.renderer.setSize(w2, h2, false); };
    // ---- 动画 ----
    const anim = () => {
      if (!p.renderer || !p.canvas.isConnected) { try { if (p.renderer) p.renderer.dispose(); } catch {} return; }
