          nm.label.style.display = '';
          nm.label.style.transform = 'translate(-50%,-50%) translate(' + x + 'px,' + (y + 14) + 'px)';
        });
      }
    };
    anim();
    return p;
  }

  function xhDockP3Drawer(face, picked, data) {
