      XH_DOCK.el = null; XH_DOCK.bar = null; XH_DOCK.panel = null; XH_DOCK.flipper = null;
    }
    const ta = topDoc.getElementById('send_textarea');
    if (!ta) {
      if (!XH_DOCK.retryTimer && XH_DOCK.retryCount < 30) {
        XH_DOCK.retryCount++;
