          XH_DOCK.retryTimer = null;
          initUnifiedDock();
        }, 600);
      }
      return;
    }
    if (XH_DOCK.retryTimer) clearTimeout(XH_DOCK.retryTimer);
    XH_DOCK.retryTimer = null;
    XH_DOCK.retryCount = 0;
    xhDockInjectCss();
