  <div id="xh-dock-badge" title="点击切换 狐忆 / 平行世界"><span class="xb">🦊</span><span class="xb b">🌌</span></div>
  <div class="xd-pulse"></div>
  <span class="xd-bt" id="xh-dock-title">狐忆</span>
  <span id="xh-dock-status">🦊 狐忆待命 · 点击展开</span>
