  <span id="xh-dock-arrow">${xdI('cu', 16)}</span>
</div>
<div id="xh-dock-panel"><div id="xh-dock-flipper"></div></div>`;
    const host = ta.parentElement;
    if (host?.parentElement) host.parentElement.insertBefore(dock, host);
    else host.insertBefore(dock, ta);
    XH_DOCK.el = dock; XH_DOCK.bar = dock.querySelector('#xh-dock-bar'); XH_DOCK.panel = dock.querySelector('#xh-dock-panel'); XH_DOCK.flipper = dock.querySelector('#xh-dock-flipper'); XH_DOCK.created = true;
    xhDockRenderFaces();
    XH_DOCK.bar.addEventListener('click', (e) => { if (e.target.closest('#xh-dock-badge,#xh-dock-flip,#xh-dock-bbs,#xh-dock-close')) return; xhDockToggleOpen(); });
    dock.querySelector('#xh-dock-badge').addEventListener('click', (e) => { e.stopPropagation(); xhDockFlipFace(); });
    dock.querySelector('#xh-dock-flip').addEventListener('click', (e) => { e.stopPropagation(); xhDockFlipFace(); });
    dock.querySelector('#xh-dock-close').addEventListener('click', (e) => {
