    topDoc.getElementById('foxmem-recall-float')?.remove();
    xhDockRefresh();
    // 底栏载入时默认折叠，用户点击折叠栏后再展开面板。
    log('[底栏] 统一底栏已创建');
  }
  // ==================== 🎴 统一底栏 END ====================

  async function initUI() {
    if (topDoc.getElementById('ss-float-bubble')) return;

    topDoc.head.insertAdjacentHTML('beforeend', BUBBLE_CSS);
    topDoc.head.insertAdjacentHTML('beforeend', MODERN_CSS);
    topDoc.body.insertAdjacentHTML('beforeend', buildBubbleHTML());

    const bubble = topDoc.getElementById('ss-float-bubble');
    if (!bubble) return;
    ssApplyUiMode();
    try { initUnifiedDock(); } catch (e) { log('[底栏] 初始化失败:', e); }

    let dragging = false;
    let dragMoved = false;
    let dragJustEnded = false;

    let startX = 0;
    let startY = 0;
    let startLeft = 0;
    let startTop = 0;

    const DRAG_THRESHOLD = 8;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    bubble.addEventListener('pointerdown', (e) => {
      dragging = true;
      dragMoved = false;

      startX = e.clientX;
      startY = e.clientY;

      const rect = bubble.getBoundingClientRect();
      startLeft = rect.left;
      startTop = rect.top;

      bubble.setPointerCapture?.(e.pointerId);
      bubble.style.transition = 'none';

      e.preventDefault();
      e.stopPropagation();
    });

    bubble.addEventListener('pointermove', (e) => {
      if (!dragging) return;

      const dx = e.clientX - startX;
      const dy = e.clientY - startY;

      if (Math.abs(dx) > DRAG_THRESHOLD || Math.abs(dy) > DRAG_THRESHOLD) {
        dragMoved = true;
      }

      if (!dragMoved) return;

      const vw = topWindow.innerWidth || topDoc.documentElement.clientWidth || 800;
      const vh = topWindow.innerHeight || topDoc.documentElement.clientHeight || 600;

      const nextLeft = clamp(startLeft + dx, 4, vw - 52);
      const nextTop = clamp(startTop + dy, 4, vh - 52);

      bubble.style.left = `${nextLeft}px`;
      bubble.style.right = 'auto';
      bubble.style.top = `${nextTop}px`;
    });

    bubble.addEventListener('pointerup', (e) => {
      if (!dragging) return;

      dragging = false;
      bubble.style.transition = '';

      try {
        bubble.releasePointerCapture?.(e.pointerId);
      } catch { }

      if (dragMoved) {
        const rect = bubble.getBoundingClientRect();
        const vw = topWindow.innerWidth || topDoc.documentElement.clientWidth || 800;

        const side = (rect.left + rect.width / 2) < vw / 2 ? 'left' : 'right';
        const top = clamp(rect.top, 4, (topWindow.innerHeight || 600) - 52);

        bubble.style.top = `${top}px`;

        if (side === 'left') {
          bubble.style.left = '12px';
          bubble.style.right = 'auto';
        } else {
          bubble.style.right = '12px';
          bubble.style.left = 'auto';
        }

        savePanelConfig({
          bubbleTop: `${top}px`,
          bubbleSide: side,
        });
        try { pwPositionMiniBubble?.(); } catch { }
        dragJustEnded = true;
        setTimeout(() => {
          dragJustEnded = false;
        }, 180);
      }

      try { topDoc.body.focus(); } catch { }
    });

    bubble.addEventListener('pointercancel', () => {
      dragging = false;
      dragMoved = false;
      bubble.style.transition = '';
      try { topDoc.body.focus(); } catch { }
    });

    bubble.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();

      if (dragJustEnded || dragMoved) return;

      if (topDoc.getElementById('ss-dashboard')) {
        closeDashboard();
      } else {
        openDashboard();
      }
    });
  }


  // ============= 🆕 批次 3A：🦊 狐忆 工具函数 =============

  /**
   * 获取当前角色卡唯一标识
   * 优先用 characterId，没有则用 avatar 文件名
   */
  function getCurrentChatScopeId() {
    try {
      const fn = getFn('getCurrentChatId');
      if (typeof fn === 'function') { const id = fn(); if (id) return String(id); }
    } catch { }

    try {
      const ctx = SillyTavern?.getContext?.();
      if (ctx?.chatId) return String(ctx.chatId);
      if (ctx?.chat?.file_name) return String(ctx.chat.file_name);
      if (ctx?.chatMetadata?.file_name) return String(ctx.chatMetadata.file_name);
      if (ctx?.chatMetadata?.chat_id) return String(ctx.chatMetadata.chat_id);
    } catch { }

    try {
      const tw = topWindow || window;
      if (tw?.chat_metadata?.file_name) return String(tw.chat_metadata.file_name);
      if (tw?.chat_metadata?.chat_id) return String(tw.chat_metadata.chat_id);
    } catch { }

    return `__PENDING__${encodeURIComponent(getCurrentCharId())}`;
  }

  /**
   * 获取当前角色卡唯一标识
   * 优先用 characterId，没有则用 avatar 文件名
   */
  function getCurrentCharId() {
    try {
      const ctx = SillyTavern.getContext();
      if (ctx) {
        if (ctx.characterId !== undefined && ctx.characters) {
          const char = ctx.characters[ctx.characterId];
          if (char) {
            if (char.avatar) return char.avatar.replace(/\.[^.]+$/, '');
            if (char.name) return char.name;
          }
        }
      }
    } catch (e) {
      console.warn('[狐忆] 获取角色卡 ID 失败:', e);
    }
    return 'unknown_char';
  }

  function getFoxMemoryScopeId() {
    return `${getCurrentCharId()}__chat_${getCurrentChatScopeId()}`;
  }

  function getFoxMemoryStorageKey() {
    return `SPreset_FoxMemory_${encodeURIComponent(getFoxMemoryScopeId())}`;
  }

  // ==================== 🦊 狐档：狐忆 / 平行世界共享角色档案库 ====================
  // 独立物理存储，但沿用当前角色卡+聊天作用域，避免不同 AU / 分支的同名角色互相污染。
  // 狐忆主数据仍保留兼容镜像，供旧面板、检查点和旧导出格式继续工作。
  function getFoxProfileStorageKey() {
    return `SPreset_FoxProfile_${encodeURIComponent(getFoxMemoryScopeId())}`;
  }

  function foxProfileClone(value) {
    try { return JSON.parse(JSON.stringify(value)); } catch { return value; }
  }

  function foxProfileNormalizeStore(raw = {}) {
    const store = {
      schemaVersion: 1,
      scopeId: getFoxMemoryScopeId(),
      characterProfiles: Object.fromEntries(
        Object.entries(raw?.characterProfiles || {})
          .map(([name, item]) => [name, foxMemoryNormalizeCharacterProfile(item, name)])
          .filter(([, item]) => !!item)
      ),
      relationships: Array.isArray(raw?.relationships)
        ? raw.relationships.map(foxMemoryNormalizeRelationship).filter(Boolean)
        : [],
      revision: Math.max(0, Math.floor(Number(raw?.revision) || 0)),
      migratedFromFoxMemory: raw?.migratedFromFoxMemory === true,
      createdAt: String(raw?.createdAt || new Date().toISOString()),
      updatedAt: String(raw?.updatedAt || new Date().toISOString()),
    };
    try {
      // 复用角色归并逻辑，但只取回稳定档案和关系，动态快照/场景不进入共享库。
      const canonical = {
        characterProfiles: store.characterProfiles,
        characterSnapshots: {},
        relationships: store.relationships,
        sceneSnapshot: foxMemoryNormalizeSceneSnapshot(),
      };
      foxMemoryCanonicalizeCharacterEntities(canonical);
      foxMemoryRefreshRelationRefs(canonical);
      store.characterProfiles = canonical.characterProfiles;
      store.relationships = canonical.relationships;
    } catch (e) { foxMemoryV2Log('共享档案归并失败', e?.message || e); }
    return store;
  }

  function saveFoxProfileStore(raw, { mirrorMemory = null } = {}) {
    try {
      let existing = null;
      try {
        const saved = localStorage.getItem(getFoxProfileStorageKey());
        if (saved) existing = foxProfileNormalizeStore(JSON.parse(saved));
      } catch { }
      const normalized = foxProfileNormalizeStore({
        ...(existing || {}),
        ...(raw || {}),
        createdAt: existing?.createdAt || raw?.createdAt,
      });
      const unchanged = existing
        && JSON.stringify(existing.characterProfiles) === JSON.stringify(normalized.characterProfiles)
        && JSON.stringify(existing.relationships) === JSON.stringify(normalized.relationships);
      if (unchanged) {
        if (mirrorMemory && typeof mirrorMemory === 'object') {
          mirrorMemory.characterProfiles = foxProfileClone(existing.characterProfiles);
          mirrorMemory.relationships = foxProfileClone(existing.relationships);
          mirrorMemory.profileSchemaVersion = 3;
        }
        return existing;
      }
      if (String(getCurrentChatScopeId()).startsWith('__PENDING__')) {
        foxMemoryV2Log('共享档案写入跳过', 'chatId 尚未就绪，避免创建 PENDING 孤儿 key');
        return normalized;
      }
      normalized.revision = Math.max(0, Number(existing?.revision) || Number(normalized.revision) || 0) + 1;
      normalized.updatedAt = new Date().toISOString();
      localStorage.setItem(getFoxProfileStorageKey(), JSON.stringify(normalized));
      if (mirrorMemory && typeof mirrorMemory === 'object') {
        mirrorMemory.characterProfiles = foxProfileClone(normalized.characterProfiles);
        mirrorMemory.relationships = foxProfileClone(normalized.relationships);
        mirrorMemory.profileSchemaVersion = 3;
      }
      foxMemoryV2Log('共享档案写入', `profiles=${Object.keys(normalized.characterProfiles).length} rels=${normalized.relationships.length} revision=${normalized.revision}`);
      return normalized;
    } catch (e) {
      foxMemoryV2Log('共享档案写入失败', e?.message || e, e);
      return null;
    }
  }

  function loadFoxProfileStore(seedMemory = null) {
    try {
      const raw = localStorage.getItem(getFoxProfileStorageKey());
      if (raw) return foxProfileNormalizeStore(JSON.parse(raw));
    } catch (e) { foxMemoryV2Log('共享档案读取失败', e?.message || e); }

    // 首次升级只迁移当前聊天已有的稳定档案/关系，不扫描其他聊天，不删除旧数据。
    const seeded = foxProfileNormalizeStore({
      characterProfiles: seedMemory?.characterProfiles || {},
      relationships: seedMemory?.relationships || [],
      migratedFromFoxMemory: true,
    });
    return saveFoxProfileStore(seeded) || seeded;
  }

  function foxProfileApplySharedView(memoryData) {
    if (!memoryData || typeof memoryData !== 'object') return memoryData;
    const shared = loadFoxProfileStore(memoryData);
    memoryData.characterProfiles = foxProfileClone(shared.characterProfiles);
    memoryData.relationships = foxProfileClone(shared.relationships);
    memoryData.profileSchemaVersion = 3;
    return memoryData;
  }

  /**
   * 读取当前角色卡 + 当前聊天的记忆库
   */
  function loadFoxMemory() {
    const key = getFoxMemoryStorageKey();

    try {
      const raw = localStorage.getItem(key);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && parsed.memories) {
          parsed.memories = Array.isArray(parsed.memories) ? parsed.memories.map(foxMemoryNormalizeStoredMemory).filter(Boolean) : [];
          parsed.plotAtoms = Array.isArray(parsed.plotAtoms) ? parsed.plotAtoms.map(foxMemoryNormalizeStoredAtom).filter(Boolean) : [];
          parsed.currentStates = Array.isArray(parsed.currentStates) ? parsed.currentStates.map(foxMemoryNormalizeCurrentState).filter(Boolean) : [];
          parsed.characterSnapshots = Object.fromEntries(Object.entries(parsed.characterSnapshots || {}).map(([name, item]) => [name, foxMemoryNormalizeCharacterSnapshot(item, name)]).filter(([, item]) => !!item));
          parsed.characterProfiles = Object.fromEntries(Object.entries(parsed.characterProfiles || {}).map(([name, item]) => [name, foxMemoryNormalizeCharacterProfile(item, name)]).filter(([, item]) => !!item));
          parsed.relationships = Array.isArray(parsed.relationships) ? parsed.relationships.map(foxMemoryNormalizeRelationship).filter(Boolean) : [];
          parsed.sceneSnapshot = foxMemoryNormalizeSceneSnapshot(parsed.sceneSnapshot);
          parsed.customTables = Array.isArray(parsed.customTables) ? parsed.customTables.map(foxMemoryNormalizeCustomTable).filter(Boolean) : [];
          parsed.checkpoints = {
            turns: (parsed.checkpoints?.turns || []).map(foxMemoryNormalizeCheckpoint).filter(Boolean).slice(-3),
            chunks: (parsed.checkpoints?.chunks || []).map(foxMemoryNormalizeCheckpoint).filter(Boolean).slice(-2),
          };
          // 🆕 V3 迁移（幂等）：首次读到无 profileSchemaVersion 的旧库时，把 characterSnapshots 机械复制到 characterProfiles。
          //    仅在内存中完成，下次任意 saveFoxMemory 时自然持久化。
          //    包 try-catch：迁移失败不影响读取（退化为旧版结构），绝不因迁移抛错而返回空库。
          try { foxMemoryMigrateToV3(parsed); }
          catch (migrateErr) { console.warn('[狐忆] V3 迁移失败，本次跳过（不影响读取）:', migrateErr); }
          try { foxMemoryCanonicalizeCharacterEntities(parsed); }
          catch (canonicalErr) { console.warn('[狐忆] 角色实体归并失败，本次跳过（不影响读取）:', canonicalErr); }
          // 🦊 狐档共享视图：独立共享库为档案真值，狐忆对象保留兼容镜像。
          try { foxProfileApplySharedView(parsed); }
          catch (profileErr) { console.warn('[狐档] 共享档案读取失败，本次沿用狐忆镜像:', profileErr); }
          return parsed;
        }
      }
    } catch (e) {
      console.warn('[狐忆] 读取记忆库失败:', e);
    }

    const fallback = { memories: [], plotAtoms: [], currentStates: [], characterSnapshots: {}, characterProfiles: {}, relationships: [], profileSchemaVersion: 0, sceneSnapshot: foxMemoryNormalizeSceneSnapshot(), customTables: [], checkpoints: { turns: [], chunks: [] }, snapshotRevision: 0, lastAnalysis: null };
    try { foxProfileApplySharedView(fallback); } catch { }
    return fallback;
  }

  /**
   * 保存当前角色卡 + 当前聊天的记忆库
   */
  function saveFoxMemory(memoryData) {
    const key = getFoxMemoryStorageKey();
    const profileKey = getFoxProfileStorageKey();
    let previousProfileRaw = null;

    try {
      if (String(getCurrentChatScopeId()).startsWith('__PENDING__')) {
        foxMemoryV2Log('保存跳过', 'chatId 尚未就绪，避免创建 PENDING 狐忆孤儿 key');
        return false;
      }
      previousProfileRaw = localStorage.getItem(profileKey);
      foxMemoryCanonicalizeCharacterEntities(memoryData);
      const normalized = {
        ...(memoryData || {}),
        memories: Array.isArray(memoryData?.memories) ? memoryData.memories.map(foxMemoryNormalizeStoredMemory).filter(Boolean) : [],
        plotAtoms: Array.isArray(memoryData?.plotAtoms) ? memoryData.plotAtoms.map(foxMemoryNormalizeStoredAtom).filter(Boolean) : [],
        currentStates: Array.isArray(memoryData?.currentStates) ? memoryData.currentStates.map(foxMemoryNormalizeCurrentState).filter(Boolean) : [],
        characterSnapshots: Object.fromEntries(Object.entries(memoryData?.characterSnapshots || {}).map(([name, item]) => [name, foxMemoryNormalizeCharacterSnapshot(item, name)]).filter(([, item]) => !!item)),
        characterProfiles: Object.fromEntries(Object.entries(memoryData?.characterProfiles || {}).map(([name, item]) => [name, foxMemoryNormalizeCharacterProfile(item, name)]).filter(([, item]) => !!item)),
        relationships: Array.isArray(memoryData?.relationships) ? memoryData.relationships.map(foxMemoryNormalizeRelationship).filter(Boolean) : [],
        profileSchemaVersion: Number(memoryData?.profileSchemaVersion) >= 3 ? 3 : (Number(memoryData?.profileSchemaVersion) || 0),
        sceneSnapshot: foxMemoryNormalizeSceneSnapshot(memoryData?.sceneSnapshot),
        customTables: Array.isArray(memoryData?.customTables) ? memoryData.customTables.map(foxMemoryNormalizeCustomTable).filter(Boolean) : [],
        checkpoints: {
          turns: (memoryData?.checkpoints?.turns || []).map(foxMemoryNormalizeCheckpoint).filter(Boolean).slice(-3),
          chunks: (memoryData?.checkpoints?.chunks || []).map(foxMemoryNormalizeCheckpoint).filter(Boolean).slice(-2),
        },
      };
      // 先提交独立共享档案，再把规范化结果镜像回狐忆主数据。
      const shared = saveFoxProfileStore({
        characterProfiles: normalized.characterProfiles,
        relationships: normalized.relationships,
      });
      if (shared) {
        normalized.characterProfiles = foxProfileClone(shared.characterProfiles);
        normalized.relationships = foxProfileClone(shared.relationships);
        normalized.profileSchemaVersion = 3;
      }
      const serialized = JSON.stringify(normalized);
      localStorage.setItem(key, serialized);
      foxMemoryInvalidateVectorSnapshot('memory_saved');
      foxMemoryV2Log('存储写入', `key=${key} memories=${normalized.memories.length} atoms=${normalized.plotAtoms.length} states=${normalized.currentStates.length} snapshots=${Object.keys(normalized.characterSnapshots).length} profiles=${Object.keys(normalized.characterProfiles).length} rels=${normalized.relationships.length} checkpoints=${normalized.checkpoints.turns.length + normalized.checkpoints.chunks.length} bytes=${foxMemoryEstimateBytes(serialized)}`);
      return true;
    } catch (e) {
      // 双写补偿：共享档案已成功但狐忆主库失败时，恢复共享档案旧值，避免永久分裂。
      try {
        if (previousProfileRaw === null) localStorage.removeItem(profileKey);
        else localStorage.setItem(profileKey, previousProfileRaw);
      } catch { }
      console.error('[狐忆] 保存记忆库失败:', e);
      let estimatedBytes = 0;
      try { estimatedBytes = foxMemoryEstimateBytes(JSON.stringify(memoryData || {})); } catch { }
      foxMemoryV2Log('保存失败', `name=${e?.name || 'Error'} key=${key} memories=${memoryData?.memories?.length || 0} atoms=${memoryData?.plotAtoms?.length || 0} states=${memoryData?.currentStates?.length || 0} estimatedBytes=${estimatedBytes}`, e);
      return false;
    }
  }

  /**
   * 读取 🦊 狐忆 配置
   */
  function foxMemoryNormalizeRetryCount(value, fallback = 1) {
    const n = parseInt(value, 10);
    return Math.max(0, Math.min(5, Number.isFinite(n) ? n : fallback));
  }

  function loadFoxMemoryConfig() {
    // 🦊 狐忆保留标签版本化"首次覆盖"：确保用户能同步到最新默认保留标签。
    //    v2 事故修复：v1 曾把保留标签强制成仅 <All_Context>，但聊天楼层的正文只存在于
    //    <content> 中（<All_Context> 只包裹请求体，楼层内根本没有），导致 assistant 楼层
    //    全部匹配失败被整条丢弃，分析模型完全看不见正文——这是"狐忆瞎编、主客体颠倒"的根因。
    //    v2 把保留标签一次性覆盖为 <All_Context> + <content> 并持久化+写标记；
    //    之后用户在面板里的任意增删改都不再被覆盖。
    const _FOX_MEM_TAG_VER_KEY = 'SPreset_FoxMemory_TagFilterVer';
    const _FOX_MEM_TAG_VER_CUR = '3';
    const _foxMemMigrateTagPairsOnce = (obj) => {
      try {
        if (localStorage.getItem(_FOX_MEM_TAG_VER_KEY) === _FOX_MEM_TAG_VER_CUR) return obj;
        obj.includeTagPairs = ssDefaultIncludeTagPairs();
        obj.includeTagStarts = '<All_Context>\n<content>';
        obj.includeTagEnds = '</All_Context>\n</content>';
        const requiredExcludePairs = [
          { start: '<fox_selc>', end: '</fox_selc>' },
          { start: '<fox_tip>', end: '</fox_tip>' },
        ];
        const existingExcludePairs = Array.isArray(obj.excludeTagPairs)
          ? obj.excludeTagPairs
          : ssLinesToPairs(obj.excludeTagStarts || '', obj.excludeTagEnds || '');
        obj.excludeTagPairs = [...existingExcludePairs];
        for (const pair of requiredExcludePairs) {
          if (!obj.excludeTagPairs.some(item => item?.start === pair.start && item?.end === pair.end)) {
            obj.excludeTagPairs.push(pair);
          }
        }
        obj.excludeTagStarts = ssPairsToLines(obj.excludeTagPairs, 'start');
        obj.excludeTagEnds = ssPairsToLines(obj.excludeTagPairs, 'end');
        localStorage.setItem('SPreset_FoxMemoryConfig', JSON.stringify(obj));
        localStorage.setItem(_FOX_MEM_TAG_VER_KEY, _FOX_MEM_TAG_VER_CUR);
        console.log(`[狐忆] 已同步最新默认保留标签（v${_FOX_MEM_TAG_VER_CUR}）：覆盖一次本地旧保留标签为 <All_Context> + <content>（修复 assistant 楼层被整条丢弃、正文对分析不可见的问题）；后续你的增删改不再被覆盖`);
      } catch (e) { console.warn('[狐忆] 同步默认保留标签失败', e); }
      return obj;
    };

    // 🦊 楼层限制版本化迁移（一次性）：
    //    分析楼层限制旧默认 0（全部楼层）→ 10；新增推进楼层限制默认 10（独立于分析）。
    //    只迁移一次并写标记，之后用户手动改成任何值（包括 0=全部）都不再被覆盖。
    const _FOX_MEM_FLOORS_VER_KEY = 'SPreset_FoxMemory_FloorsVer';
    const _FOX_MEM_FLOORS_VER_CUR = '1';
    const _foxMemMigrateFloorsOnce = (obj) => {
      try {
        if (localStorage.getItem(_FOX_MEM_FLOORS_VER_KEY) === _FOX_MEM_FLOORS_VER_CUR) return obj;
        const ctx = parseInt(obj.contextFloors, 10);
        if (!Number.isFinite(ctx) || ctx <= 0) {
          obj.contextFloors = 10;
          localStorage.setItem(CONFIG.FOX_MEMORY_CONTEXT_FLOORS_KEY, '10');
        }
        const pushCtx = parseInt(obj.pushContextFloors, 10);
        if (!Number.isFinite(pushCtx) || pushCtx < 0) {
          obj.pushContextFloors = 10;
          localStorage.setItem(CONFIG.FOX_MEMORY_PUSH_CONTEXT_FLOORS_KEY, '10');
        }
        // 标签迁移先执行、楼层迁移后执行；这里统一覆盖一次配置 JSON，确保两种迁移结果
        // 同时持久化，避免旧 JSON 里的 contextFloors:0 在下次加载时重新覆盖独立 key。
        localStorage.setItem('SPreset_FoxMemoryConfig', JSON.stringify(obj));
        localStorage.setItem(_FOX_MEM_FLOORS_VER_KEY, _FOX_MEM_FLOORS_VER_CUR);
        console.log(`[狐忆] 已同步楼层限制默认值（v${_FOX_MEM_FLOORS_VER_CUR}）：分析楼层限制=${obj.contextFloors}（仅狐忆分析生效），推进楼层限制=${obj.pushContextFloors}（仅自动推进生效）；后续你的修改不再被覆盖`);
      } catch (e) { console.warn('[狐忆] 同步楼层限制默认值失败', e); }
      return obj;
    };
    const _foxMemMigrateOnce = (obj) => _foxMemMigrateFloorsOnce(_foxMemMigrateTagPairsOnce(obj));

    try {
      const raw = localStorage.getItem('SPreset_FoxMemoryConfig');

      if (raw) {
        const parsed = JSON.parse(raw);

        const merged = ssNormalizeTagFilterSettings({
          ...foxMemoryConfig,
          ...parsed,
          customApi: {
            ...(foxMemoryConfig.customApi || {}),
            ...(parsed.customApi || {}),
          },
        });
        merged.customApi = foxMemoryNormalizeCustomApiConfig(merged.customApi);
        merged.pushCustomApi = foxMemoryNormalizeCustomApiConfig(merged.pushCustomApi);

        // 关键修复：
