    if (appliedVersion < PW_THINK_MODULES_VERSION) {
      userModules = userModules.map(um => {
        const def = PW_THINK_MODULES_DEFAULT.find(m => m.id === um?.id);
        return def ? { ...um, content: def.content, name: def.name, locked: def.locked } : um;
      });
      for (const def of PW_THINK_MODULES_DEFAULT) {
        if (!userModules.some(um => um.id === def.id)) userModules.push({ ...def });
      }
      try {
        localStorage.setItem(PW_THINK_MODULES_LS_KEY, JSON.stringify(userModules.map(m => ({ id: m.id, name: m.name, content: m.content, locked: m.locked }))));
        localStorage.setItem(PW_THINK_MODULES_VERSION_KEY, String(PW_THINK_MODULES_VERSION));
      } catch {}
      log(`[平行世界·思维链] 默认词条已强制更新到 v${PW_THINK_MODULES_VERSION}（用户自定义词条与排序保留）`);
    }

    // 合并：默认词条为基础，用户同名词条覆盖 content/name，用户新增词条追加
    const merged = PW_THINK_MODULES_DEFAULT.map(m => ({ ...m }));
    for (const um of userModules) {
      if (!um || !um.id) continue;
      const idx = merged.findIndex(m => m.id === um.id);
      if (idx >= 0) {
        merged[idx] = { ...merged[idx], ...um, locked: merged[idx].locked };
      } else {
        merged.push({ ...um });
      }
    }

    if (!Array.isArray(order) || !order.length) {
      order = [...PW_THINK_PRESETS.default.order];
    }
    order = order.filter(id => merged.some(m => m.id === id));
    if (!order.includes('head')) order.unshift('head');
    order = ['head', ...order.filter(id => id !== 'head')];

    return { modules: merged, order };
  }

  function pwSaveThinkModules(modules, order) {
    try {
      const toSave = (modules || []).map(m => ({ id: m.id, name: m.name, content: m.content, locked: m.locked }));
      localStorage.setItem(PW_THINK_MODULES_LS_KEY, JSON.stringify(toSave));
    } catch { }
    try {
      localStorage.setItem(PW_THINK_ORDER_LS_KEY, JSON.stringify(order || []));
    } catch { }
  }

  // 按 order 拼接启用词条，生成"平行世界思考"模块的完整提示词
  // 严格参照 foxJudgeBuildPhase2FromModules 实现，仅去除狐忆联动召回（平行世界无该机制）
  // 🎯 质量模式自动启用思维链模块，无需单独开关；快速模式返回空字符串。
  function pwBuildThinkModulesPrompt() {
    const cfg = pwState.config || pwLoadConfig();
    if (cfg.generationMode !== 'quality') return ''; // 仅质量模式生效
    const { modules, order } = pwLoadThinkModules();
    const parts = [];
    for (const id of order) {
      const m = modules.find(x => x.id === id);
      if (m && m.content && String(m.content).trim()) {
        parts.push(String(m.content).trim());
      }
    }
    // ✅ 平行世界为单次输出（思考+正文），不需要"禁止输出正文"的收束尾句。
    //    思维链模块内容由 pwBuildGenerationThoughtOutputTemplate 统一注入到输出模板位置。
    return parts.join('\n\n');
  }

  // 应用默认排序预设：重排 order，保留用户自定义词条于末尾
  function pwApplyThinkPreset(presetKey) {
    const preset = PW_THINK_PRESETS[presetKey];
    if (!preset) return;
    const { modules, order: curOrder } = pwLoadThinkModules();
    const allPresetIds = new Set(PW_THINK_PRESETS.default.order);
    const customIds = curOrder.filter(id => !allPresetIds.has(id) && id !== 'head');
    let order = preset.order.filter(id => modules.some(m => m.id === id));
    for (const cid of customIds) {
      if (!order.includes(cid)) order.push(cid);
    }
    pwSaveThinkModules(modules, order);
  }

  // ==================== 🧩 平行世界思维链模块 UI 面板 ====================
  // 严格照搬狐裁思维链 UI（foxJudgeThinkRerender / foxJudgeThinkOpenEditor）实现：
