      if (!_pwTkConfirm('确定恢复默认思维链模块配置？所有自定义模块和排序将被重置。')) return;
      try { localStorage.removeItem(PW_THINK_MODULES_LS_KEY); } catch {}
      try { localStorage.removeItem(PW_THINK_ORDER_LS_KEY); } catch {}
      toast('↩️ 思维链模块已恢复默认', 'success');
