  function pwThinkRerender() {
    const panel = topDoc.getElementById('pw-think-panel');
    if (!panel) return;
    const { modules, order } = pwLoadThinkModules();
    const poolEl = panel.querySelector('#pw-think-pool');
    const activeEl = panel.querySelector('#pw-think-active');
    if (!poolEl || !activeEl) return;

    const _pwTkTouch = _pwTkIsMobile();

    const itemHtml = (m, ctx) => {
      const lockMark = m.locked ? ' 🔒' : '';
      const delBtn = m.locked ? '' : `<span class="pw-tk-del pw-tk-btn" data-id="${escapeHtml(m.id)}" title="删除" style="cursor:pointer;opacity:0.6;">🗑️</span>`;
      let ctrl = '';
      if (!m.locked) {
        if (ctx === 'pool') {
          ctrl = `<span class="pw-tk-enable pw-tk-btn" data-id="${escapeHtml(m.id)}" title="启用（移到右侧）" style="cursor:pointer;opacity:0.85;">⇢</span>`;
        } else {
          ctrl = `<span class="pw-tk-up pw-tk-btn" data-id="${escapeHtml(m.id)}" title="上移" style="cursor:pointer;opacity:0.85;">↑</span>`
                + `<span class="pw-tk-down pw-tk-btn" data-id="${escapeHtml(m.id)}" title="下移" style="cursor:pointer;opacity:0.85;">↓</span>`
                + `<span class="pw-tk-disable pw-tk-btn" data-id="${escapeHtml(m.id)}" title="停用（移到左侧）" style="cursor:pointer;opacity:0.85;">⇠</span>`;
        }
      }
      return `<div class="pw-tk-item" draggable="${_pwTkTouch ? 'false' : 'true'}" data-id="${escapeHtml(m.id)}" style="display:flex;justify-content:space-between;align-items:center;gap:4px;padding:8px 10px;border:1px solid rgba(96,210,255,0.2);border-radius:8px;background:rgba(255,255,255,0.04);cursor:grab;font-size:12px;color:#dbeef6;min-width:0;overflow:hidden;">
        <span style="flex:1;min-width:3em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtml(m.name)}${lockMark}</span>
        <span style="display:flex;gap:4px;flex-shrink:0;align-items:center;max-width:100%;">
          ${ctrl}
          <span class="pw-tk-edit pw-tk-btn" data-id="${escapeHtml(m.id)}" title="编辑" style="cursor:pointer;opacity:0.7;">✏️</span>
          ${delBtn}
        </span>
      </div>`;
    };

    const poolItems = modules.filter(m => !order.includes(m.id));
    poolEl.innerHTML = poolItems.length ? poolItems.map(m => itemHtml(m, 'pool')).join('') : '<div style="font-size:11px;color:#555;padding:8px;">（无未启用模块）</div>';
    const activeItems = order.map(id => modules.find(m => m.id === id)).filter(Boolean);
    activeEl.innerHTML = activeItems.length ? activeItems.map(m => itemHtml(m, 'active')).join('') : '<div style="font-size:11px;color:#555;padding:8px;">（无启用模块）</div>';

    panel.querySelectorAll('.pw-tk-item').forEach(el => {
      if (_pwTkTouch) return;
      el.ondragstart = (e) => { _pwTkDragId = el.dataset.id; e.dataTransfer.effectAllowed = 'move'; try { e.dataTransfer.setData('text/plain', el.dataset.id); } catch {} };
      el.ondragover = (e) => { e.preventDefault(); };
      el.ondrop = (e) => {
        e.preventDefault(); e.stopPropagation();
        const dragId = _pwTkDragId; if (!dragId) return;
        if (dragId === 'head') { pwThinkRerender(); return; }
        const container = el.parentElement;
        const isActive = container.id === 'pw-think-active';
        const { modules, order } = pwLoadThinkModules();
        if (isActive) {
          let newOrder = order.filter(id => id !== dragId);
          const ti = newOrder.indexOf(el.dataset.id);
          if (ti >= 0) newOrder.splice(ti, 0, dragId); else newOrder.push(dragId);
          newOrder = ['head', ...newOrder.filter(x => x !== 'head')];
          pwSaveThinkModules(modules, newOrder);
        } else {
          pwSaveThinkModules(modules, order.filter(id => id !== dragId));
        }
        pwThinkRerender();
      };
    });
    panel.querySelectorAll('.pw-tk-edit').forEach(el => {
      el.onclick = (e) => { e.stopPropagation(); pwThinkOpenEditor(el.dataset.id); };
    });
    panel.querySelectorAll('.pw-tk-del').forEach(el => {
      el.onclick = (e) => {
        e.stopPropagation();
        if (!_pwTkConfirm('确定删除这个自定义模块？')) return;
        const id = el.dataset.id;
        const { modules, order } = pwLoadThinkModules();
        pwSaveThinkModules(modules.filter(m => m.id !== id), order.filter(x => x !== id));
        toast('🗑️ 已删除模块', 'success');
        pwThinkRerender();
      };
    });
    panel.querySelectorAll('.pw-tk-enable').forEach(el => {
      el.onclick = (e) => {
        e.stopPropagation();
        const id = el.dataset.id;
        const { modules, order } = pwLoadThinkModules();
        if (order.includes(id)) { pwThinkRerender(); return; }
        let no = order.filter(x => x !== 'head');
        no.push(id);
        pwSaveThinkModules(modules, ['head', ...no]);
        pwThinkRerender();
      };
    });
    panel.querySelectorAll('.pw-tk-disable').forEach(el => {
      el.onclick = (e) => {
        e.stopPropagation();
        const id = el.dataset.id;
        const { modules, order } = pwLoadThinkModules();
        if (id === 'head') { pwThinkRerender(); return; }
        pwSaveThinkModules(modules, order.filter(x => x !== id));
        pwThinkRerender();
      };
    });
    panel.querySelectorAll('.pw-tk-up').forEach(el => {
      el.onclick = (e) => {
        e.stopPropagation();
        const id = el.dataset.id;
        const { modules, order } = pwLoadThinkModules();
        let no = order.filter(x => x !== 'head');
        const i = no.indexOf(id);
        if (i > 0) { no.splice(i, 1); no.splice(i - 1, 0, id); pwSaveThinkModules(modules, ['head', ...no]); }
        pwThinkRerender();
      };
    });
    panel.querySelectorAll('.pw-tk-down').forEach(el => {
      el.onclick = (e) => {
        e.stopPropagation();
        const id = el.dataset.id;
        const { modules, order } = pwLoadThinkModules();
        let no = order.filter(x => x !== 'head');
        const i = no.indexOf(id);
        if (i >= 0 && i < no.length - 1) { no.splice(i, 1); no.splice(i + 1, 0, id); pwSaveThinkModules(modules, ['head', ...no]); }
        pwThinkRerender();
      };
    });
  }

  function pwThinkOpenEditor(id) {
