        <div style="display:flex;justify-content:space-between;align-items:center;">
          <span style="font-weight:600;font-size:14px;color:#7fdcff;">${m.locked ? '编辑模块：' + escapeHtml(m.name) + '（锁定，可改内容）' : '编辑模块'}</span>
          <span id="pw-think-edit-close" style="cursor:pointer;font-size:16px;color:#7891a2;">✕</span>
        </div>
        <input id="pw-think-edit-name" placeholder="模块名称" value="${escapeHtml(m.name || '')}" ${m.locked ? 'disabled' : ''} style="background:rgba(255,255,255,0.04);border:1px solid rgba(96,210,255,0.2);border-radius:8px;color:#dbeef6;padding:8px 10px;font-size:13px;font-family:inherit;box-sizing:border-box;" />
        <textarea id="pw-think-edit-content" placeholder="模块提示词内容（会按顺序拼接到思维链）" style="flex:1;min-height:240px;background:rgba(255,255,255,0.04);border:1px solid rgba(96,210,255,0.2);border-radius:8px;color:#dbeef6;padding:10px;font-size:12px;font-family:monospace;resize:vertical;box-sizing:border-box;white-space:pre-wrap;">${escapeHtml(m.content || '')}</textarea>
        <div style="display:flex;gap:8px;">
          <button id="pw-think-edit-save" style="flex:1;padding:9px;border:none;border-radius:8px;background:rgba(96,210,255,0.2);color:#7fdcff;cursor:pointer;font-size:13px;">💾 保存</button>
