      </div>`;
    topDoc.body.appendChild(layer);

    layer.querySelector('#pw-think-edit-close').onclick = () => _pwTkCloseEditor();
    layer.querySelector('#pw-think-edit-save').onclick = () => {
      const name = layer.querySelector('#pw-think-edit-name').value.trim();
      const content = layer.querySelector('#pw-think-edit-content').value;
      const { modules: ms, order } = pwLoadThinkModules();
