      if (target) { if (!target.locked && name) target.name = name; target.content = content; }
      pwSaveThinkModules(ms, order);
      _pwTkCloseEditor();
      toast('✅ 模块已保存', 'success');
      pwThinkRerender();
    };
    layer.onclick = (e) => { if (e.target === layer) _pwTkCloseEditor(); };
  }

  const pwState = {
    config: null,
    data: null,
    running: false,
    // ✅ 单条事件推进的独立 running 标志，避免占用整轮的 running/中断按钮
    singleRunning: false,
    internalGenerating: false,
    autoHandle: null,
    branchHandle: null,
    deleteHandle: null,
    editHandle: null,
    branchEpoch: 0,
    runGuard: null,

    // 自动推进计数：只统计合格的 normal AI 回复
    autoCounter: 0,
    lastAutoMessageId: null,
    pendingOneShotInjectConsume: false,
    pendingInjectedModuleIds: [],

    models: [],
    loadingModels: false,
    status: '待机',
  };
  function pwAutoCounterKey() { return `Xuanhu_ParallelWorld_AutoCounter_${encodeURIComponent(getCurrentCharId())}_${encodeURIComponent(pwGetChatId())}`; }
  function pwLoadAutoCounter() { try { const v=JSON.parse(localStorage.getItem(pwAutoCounterKey())||'{}'); pwState.autoCounter=Math.max(0,Number(v.count)||0); pwState.lastAutoMessageId=v.lastId == null ? null : String(v.lastId); } catch {} }
  function pwSaveAutoCounter() { try { localStorage.setItem(pwAutoCounterKey(),JSON.stringify({count:pwState.autoCounter,lastId:pwState.lastAutoMessageId})); } catch {} }

  function pwLoadConfig() {
    // 防御性深拷贝：避免 PW_DEFAULT_CONFIG 中的 tag pair 数组被外部代码 push/splice 污染
    const clonePairs = (arr) => Array.isArray(arr) ? arr.map(p => ({ start: p?.start || '', end: p?.end || '' })) : [];
    const freshDefault = () => ({
      ...PW_DEFAULT_CONFIG,
      customApi: { ...PW_DEFAULT_CONFIG.customApi },
      includeTagPairs: clonePairs(PW_DEFAULT_CONFIG.includeTagPairs),
      excludeTagPairs: clonePairs(PW_DEFAULT_CONFIG.excludeTagPairs),
    });

    try {
      const raw = localStorage.getItem(PW.CONFIG_KEY);

      if (!raw) {
        return freshDefault();
      }

      const parsed = JSON.parse(raw) || {};

      const cfg = {
        ...PW_DEFAULT_CONFIG,
        ...parsed,
        customApi: {
          ...PW_DEFAULT_CONFIG.customApi,
          ...(parsed.customApi || {}),
        },
        includeTagPairs: Array.isArray(parsed.includeTagPairs)
          ? clonePairs(parsed.includeTagPairs)
          : clonePairs(PW_DEFAULT_CONFIG.includeTagPairs),
        excludeTagPairs: Array.isArray(parsed.excludeTagPairs)
          ? clonePairs(parsed.excludeTagPairs)
          : clonePairs(PW_DEFAULT_CONFIG.excludeTagPairs),
      };

      // ✅ 兼容旧版 autoAdvance:boolean
      // 如果旧配置里没有 autoMode，就根据 autoAdvance 自动迁移
      if (parsed.autoMode == null) {
        cfg.autoMode = parsed.autoAdvance ? 'auto' : 'manual';
      }

      // 保持旧字段同步，避免旧 UI/旧逻辑读取出错
      cfg.autoAdvance = cfg.autoMode !== 'manual';

      cfg.autoInterval = Math.max(1, parseInt(cfg.autoInterval) || 5);
      cfg.generationMode = cfg.generationMode === 'quality' ? 'quality' : 'fast';
      cfg.detailLevel = ['extreme_concise', 'concise', 'normal', 'detailed'].includes(cfg.detailLevel) ? cfg.detailLevel : 'normal';
      cfg.backgroundSilent = cfg.backgroundSilent === true;
      cfg.diceEnabled = cfg.diceEnabled !== false;
      cfg.diceIntervalMode = cfg.diceIntervalMode === 'fixed' ? 'fixed' : 'range';
      cfg.diceFixedInterval = Math.max(1, Math.min(999, parseInt(cfg.diceFixedInterval) || 6));
      cfg.diceRangeMin = Math.max(1, Math.min(999, parseInt(cfg.diceRangeMin) || 4));
      cfg.diceRangeMax = Math.max(cfg.diceRangeMin, Math.min(999, parseInt(cfg.diceRangeMax) || 10));
      cfg.diceStoryteller = ['linhu', 'huihu', 'xuanhu'].includes(cfg.diceStoryteller) ? cfg.diceStoryteller : 'xuanhu';
      cfg.diceDifficulty = ['relaxed', 'normal', 'hard', 'extreme'].includes(cfg.diceDifficulty) ? cfg.diceDifficulty : 'normal';
      cfg.eventDifficulty = ['easy', 'normal', 'hard'].includes(cfg.eventDifficulty) ? cfg.eventDifficulty : 'normal';
      cfg.diceStorytellerImages = { ...PW_DEFAULT_CONFIG.diceStorytellerImages, ...(cfg.diceStorytellerImages || {}) };

      // ✅ 推进模式校验：只允许 two_phase / legacy_full
      if (cfg.advanceMode !== 'legacy_full' && cfg.advanceMode !== 'two_phase') {
        cfg.advanceMode = 'two_phase';
      }

      // ✅ 动态推进单次最多更新模块数：默认 4，限制在 [1, 24]
      cfg.dynamicMaxModules = Math.max(1, Math.min(24, parseInt(cfg.dynamicMaxModules) || 4));

      // ✅ chatHistoryLimit 规整：
      //   - 不是 'all' 关键字、不是空、必须是正整数才生效；其它一律视为全部
      if (cfg.chatHistoryLimit == null) {
        cfg.chatHistoryLimit = '';
      } else if (typeof cfg.chatHistoryLimit === 'number') {
        cfg.chatHistoryLimit = Number.isFinite(cfg.chatHistoryLimit) && cfg.chatHistoryLimit > 0
          ? Math.floor(cfg.chatHistoryLimit)
          : '';
      } else {
        const s = String(cfg.chatHistoryLimit).trim();
        if (!s || /^all$/i.test(s)) {
          cfg.chatHistoryLimit = '';
        } else {
          const n = parseInt(s);
          cfg.chatHistoryLimit = Number.isFinite(n) && n > 0 ? n : '';
        }
      }

      // 旧版“注入摘要字数”不再作为用户选项；新版直接约束每个事件 DETAIL。
      cfg.eventWordMin = Math.max(20, Math.min(5000, parseInt(cfg.eventWordMin) || 100));
      cfg.eventWordMax = Math.max(20, Math.min(5000, parseInt(cfg.eventWordMax) || 800));
      if (cfg.eventWordMax < cfg.eventWordMin) cfg.eventWordMax = cfg.eventWordMin;
      // 注入裁剪保留内部安全上限，不再与面板字数选项绑定。
      cfg.summaryMaxChars = Math.max(300, Math.min(2000, parseInt(cfg.summaryMaxChars) || 800));
      delete cfg.summaryWordMin;
      delete cfg.summaryWordMax;
      delete cfg.maxInjectChars;
      cfg.maxInjectModules = Math.max(1, Math.min(50, parseInt(cfg.maxInjectModules) || 10));
      cfg.maxUrgentEvents = Math.max(1, parseInt(cfg.maxUrgentEvents) || 3);

      // 🏷️ 标签过滤：使用统一标签过滤工具规整字段
      const tagFilter = ssNormalizeTagFilterSettings({
        enableContentFilter: cfg.enableContentFilter !== false,
        includeTagPairs: cfg.includeTagPairs,
        excludeTagPairs: cfg.excludeTagPairs,
        includeTagStarts: cfg.includeTagStarts,
        includeTagEnds: cfg.includeTagEnds,
        excludeTagStarts: cfg.excludeTagStarts,
        excludeTagEnds: cfg.excludeTagEnds,
      });
      cfg.enableContentFilter = tagFilter.enableContentFilter;
      cfg.includeTagPairs = tagFilter.includeTagPairs;
      cfg.excludeTagPairs = tagFilter.excludeTagPairs;
      cfg.includeTagStarts = tagFilter.includeTagStarts;
      cfg.includeTagEnds = tagFilter.includeTagEnds;
      cfg.excludeTagStarts = tagFilter.excludeTagStarts;
      cfg.excludeTagEnds = tagFilter.excludeTagEnds;

      // 旧用户没有 fox_tip / fox_selc 时自动补一组（用户要求新增的默认排除标签）
      const ensureExcludePair = (start, end) => {
        const exists = (cfg.excludeTagPairs || []).some(p => p && p.start === start && p.end === end);
        if (!exists) {
          cfg.excludeTagPairs = [
            ...(cfg.excludeTagPairs || []),
            { start, end },
          ];
        }
      };
      const before = JSON.stringify(cfg.excludeTagPairs || []);
      ensureExcludePair('<fox_tip>', '</fox_tip>');
      ensureExcludePair('<fox_selc>', '</fox_selc>');
      if (before !== JSON.stringify(cfg.excludeTagPairs || [])) {
        cfg.excludeTagStarts = ssPairsToLines(cfg.excludeTagPairs, 'start');
        cfg.excludeTagEnds = ssPairsToLines(cfg.excludeTagPairs, 'end');
      }

      return cfg;
    } catch {
      return freshDefault();
    }
  }

  function pwSaveConfig() {
    try {
      localStorage.setItem(PW.CONFIG_KEY, JSON.stringify(pwState.config || PW_DEFAULT_CONFIG));
    } catch { }
  }

  // ✅ 统一解析 max_chat_history：所有 pwGenerateRaw 都通过它拿值
  function pwResolveChatHistoryLimit() {
    const cfg = pwState.config || pwLoadConfig();
    const raw = cfg.chatHistoryLimit;

    if (raw === '' || raw == null) return 'all';
    if (typeof raw === 'number') {
      return raw > 0 ? Math.floor(raw) : 'all';
    }

    const s = String(raw).trim();
    if (!s || /^all$/i.test(s)) return 'all';

    const n = parseInt(s);
    return Number.isFinite(n) && n > 0 ? n : 'all';
  }

  // ✅ 把"AI 返回的新模块"安全合并到"旧模块"上：
  //    - 旧字段为底（不丢历史信息）
  //    - 新字段覆盖（推进结果）
  //    - 关键叙事字段若新值为空字符串则保留旧值，避免 AI 漏返回时把历史清空
  //    - id 强制保留旧值
  function pwMergeModuleUpdate(oldModule, newModule) {
    if (!oldModule) return newModule;
    if (!newModule) return oldModule;

    const fallbackKeys = [
      'roleAudit', 'perspective', 'progressNote', 'dangerLevel',
      'currentLocation', 'currentState', 'nextTendency', 'independence', 'detail',
      'origin', 'sourceGoal', 'sourceStake', 'initiativeReason',
    ];

    const merged = { ...oldModule, ...newModule };

    for (const k of fallbackKeys) {
      const nv = newModule[k];
      const ov = oldModule[k];
      if (nv == null || (typeof nv === 'string' && nv.trim() === '')) {
        if (ov != null && ov !== '') merged[k] = ov;
      }
    }
    if (newModule.initiatorNpcIds == null && Array.isArray(oldModule.initiatorNpcIds)) merged.initiatorNpcIds = oldModule.initiatorNpcIds;

    merged.id = oldModule.id;
    return merged;
  }

  // ✅ 同样的 merge 思路用于 module_summary
  function pwMergeSummaryUpdate(oldSummary, newSummary) {
    if (!oldSummary) return newSummary;
    if (!newSummary) return oldSummary;

    const fallbackKeys = [
      'summary', 'progressNote', 'dangerLevel', 'time',
    ];

    const merged = { ...oldSummary, ...newSummary };

    for (const k of fallbackKeys) {
      const nv = newSummary[k];
      const ov = oldSummary[k];
      if (nv == null || (typeof nv === 'string' && nv.trim() === '')) {
        if (ov != null && ov !== '') merged[k] = ov;
      }
    }

    merged.id = oldSummary.id;
    return merged;
  }

  // ✅ 推进流程入口统一前置检查：chatId 仍处于 __PENDING__ 时不允许触发
  //    任何会调用 AI 的推进流程，避免用户消耗 AI 调用却看不到结果。
  function pwGuardChatReady() {
    const chatId = pwGetChatId();
    if (typeof chatId === 'string' && chatId.startsWith('__PENDING__')) {
      toast('⏳ 聊天 ID 尚未就绪（可能刚切换聊天），请稍后再触发平行世界推进', 'warning');
      log('[平行世界] 推进入口拦截：chatId 仍处于 __PENDING__');
      return false;
    }
    return true;
  }

  function pwGetChatId() {
    // 严格按"角色卡 + 聊天文件"做隔离。下面的查找顺序按可靠度从高到低：
    // 1) 酒馆助手公开 API getCurrentChatId() —— 一切场景下最稳
    // 2) SillyTavern.getContext().chatId / chat.file_name / chat_metadata
    // 3) 从酒馆 DOM/全局 chid + chat 变量兜底
    // 4) 实在拿不到，就返回带角色卡前缀的 __PENDING__，避免和别的角色卡撞 key。
    try {
      const fn = getFn('getCurrentChatId');
      if (typeof fn === 'function') {
        const id = fn();
        if (id) return String(id);
      }
    } catch { }

    try {
      const ctx = SillyTavern?.getContext?.();
      if (ctx) {
        if (ctx.chatId) return String(ctx.chatId);
        // chat 是消息数组，没有 id；但部分版本会带 file_name
        if (ctx.chat?.file_name) return String(ctx.chat.file_name);
        if (ctx.chatMetadata?.file_name) return String(ctx.chatMetadata.file_name);
        if (ctx.chatMetadata?.chat_id) return String(ctx.chatMetadata.chat_id);
        // 兜底再用一次 name（旧逻辑，可能为空）
        if (ctx.chat?.name) return String(ctx.chat.name);
      }
    } catch { }

    try {
      const tw = topWindow || window;
      // 酒馆全局变量 chat_metadata.file_name 或 selected_group/chat 文件名
      if (tw?.chat_metadata?.file_name) return String(tw.chat_metadata.file_name);
      if (tw?.chat_metadata?.chat_id) return String(tw.chat_metadata.chat_id);
    } catch { }

    // 拿不到聊天 ID 时，至少挂在当前角色卡下，避免不同角色/不同聊天共用 default_chat。
    return `__PENDING__${encodeURIComponent(getCurrentCharId())}`;
  }

  function pwDataKey() {
    return `${PW.DATA_PREFIX}${encodeURIComponent(getCurrentCharId())}_${encodeURIComponent(pwGetChatId())}`;
  }

  function pwSnapshotKey() {
    return `${PW.SNAPSHOT_PREFIX}${encodeURIComponent(getCurrentCharId())}_${encodeURIComponent(pwGetChatId())}`;
  }

  function pwLoadSnapshots() {
    try {
      const list = JSON.parse(localStorage.getItem(pwSnapshotKey()) || '[]');
      if (!Array.isArray(list)) return [];
      // ✅ 加载时清理旧版本遗留的空快照，避免回退时命中空快照导致数据被清空
      const filtered = list.filter(item => item && Number.isFinite(Number(item.floor)) && item.data && !pwIsDataEmpty(item.data));
      if (filtered.length !== list.length) {
        try { localStorage.setItem(pwSnapshotKey(), JSON.stringify(filtered.slice(-10))); } catch { }
      }
      return filtered.slice(-10);
    } catch { return []; }
  }

  // ✅ 判断平行世界数据是否为"空"（无实质内容）。
  // 空数据快照是回退陷阱的根因：保存空快照后，删楼/重roll回退时会命中空快照，
  // 把空数据写回 localStorage，导致平行世界被"清空"。
  function pwIsDataEmpty(data) {
    if (!data || data.cleared === true) return true;
    const hasModules = Array.isArray(data.modules) && data.modules.length > 0;
    const hasNpcs = Array.isArray(data.npcs) && data.npcs.length > 0;
    const hasGlobalState = data.globalState && (String(data.globalState.title || '').trim() || String(data.globalState.detail || '').trim());
    const hasInject = data.inject && (String(data.inject.global_summary || '').trim() || (Array.isArray(data.inject.module_summaries) && data.inject.module_summaries.length > 0));
    const hasNpcRelations = Array.isArray(data.npcRelations) && data.npcRelations.length > 0;
    return !hasModules && !hasNpcs && !hasGlobalState && !hasInject && !hasNpcRelations;
  }

  function pwSaveSnapshot(messageId) {
    const meta = foxMemoryGetMessageBranchMeta(Number(messageId));
    const data = pwLoadData();
    // ✅ 不保存空数据快照，避免空快照成为回退陷阱。
    // 但仍返回 truthy 值（true），让调用方（自动推进流程）不会因"跳过保存"而中止推进。
    // 只有 localStorage 写入失败时才返回 null。
    if (pwIsDataEmpty(data)) {
      log('[平行世界快照] 跳过保存：当前数据为空，避免空快照成为回退陷阱');
      return true;
    }
    const snapshot = {
      floor: meta.floor,
      swipeId: meta.swipeId,
      fingerprint: meta.fingerprint,
      createdAt: new Date().toISOString(),
      data: JSON.parse(JSON.stringify(data)),
    };
    const list = pwLoadSnapshots().filter(item => !(Number(item.floor) === meta.floor && Number(item.swipeId) === meta.swipeId && item.fingerprint === meta.fingerprint));
    list.push(snapshot);
    try { localStorage.setItem(pwSnapshotKey(), JSON.stringify(list.slice(-10))); return snapshot; }
    catch (e) { log('[平行世界快照] 保存失败', e); return null; }
  }

  function pwRestoreSnapshotForFloor(floor, reason = '分支变化') {
    const target = Number(floor);
    const list = pwLoadSnapshots();
    const meta = foxMemoryGetMessageBranchMeta(target);
    const exact = list.find(item => Number(item.floor) === target && Number(item.swipeId) === meta.swipeId && item.fingerprint && item.fingerprint === meta.fingerprint);
    // ✅ 关键修复：回退匹配时跳过空快照（cleared:true 或无实质内容）。
    // 旧版本可能已存入空快照，这里必须过滤，否则回退后会用空数据覆盖现有数据。
    const snapshot = exact || list.filter(item => Number(item.floor) <= target && !pwIsDataEmpty(item.data)).sort((a, b) => Number(b.floor) - Number(a.floor))[0];
    if (!snapshot) {
      // ✅ 无可用快照时什么都不做，绝不清空现有数据。
      log(`[平行世界快照] 无可用快照（已跳过空快照），保持现状：reason=${reason} floor=${target}`);
      return false;
    }
    const restored = JSON.parse(JSON.stringify(snapshot.data));
    if (!pwSaveData(restored, { syncProfiles: false })) return false;
    try { localStorage.setItem(pwSnapshotKey(), JSON.stringify(list.filter(item => Number(item.floor) < target).slice(-10))); } catch { }
    pwState.pendingInjectedModuleIds = [];
    pwState.pendingOneShotInjectConsume = false;
    try { pwRenderPanel?.(); pwRenderStateFloat?.(); xhDockRefresh?.(); } catch { }
    log(`[平行世界快照] 已回退：reason=${reason} checkpointFloor=${snapshot.floor}`);
    return true;
  }

  function pwRunGuardIsCurrent(guard = pwState.runGuard) {
    if (!guard) return true;
    if (guard.epoch !== pwState.branchEpoch || guard.scope !== `${getCurrentCharId()}::${pwGetChatId()}`) return false;
    const current = foxMemoryGetMessageBranchMeta(guard.floor);
    return current.swipeId === guard.swipeId && current.fingerprint === guard.fingerprint;
  }

  // 当前 (charId, chatId) 的稳定标识，写到 data 里用于校验
  function pwGetBoundScope() {
    return {
      charId: String(getCurrentCharId() || ''),
      chatId: String(pwGetChatId() || ''),
    };
  }

  function pwEmptyData() {
    const scope = pwGetBoundScope();
    return {
      version: 2,
      cleared: true,
      // 绑定信息：用来防止"跨聊天/跨角色卡幽灵"——加载时一旦不匹配就丢弃
      boundCharId: scope.charId,
      boundChatId: scope.chatId,
      turn: 0,
      worldClock: '',
      globalState: {
        title: '',
        detail: '',
      },
      modules: [],
      retiredEventIds: [],
      npcs: [],
      npcRelations: [],
      // 🎲 P2/P3 新增：骰子日志 / 势力声望 / 上轮骰子状态 / 冷却
      diceLog: [],
      factionReputation: {},
      lastDice: null,
      cooldownUntilTurn: 0,
      nextDiceTurn: 0,
      diceSchedule: null,
      latestGenerationThought: '',
      latestGenerationThoughtAt: '',
      latestGenerationThoughtSource: '',
      inject: {
        global_summary: '',
        module_summaries: [],
        manual_text: '',
        consumed: true,
      },
      raw: null,
      updatedAt: '',
    };
  }

  function pwLoadData() {
    try {
      const raw = localStorage.getItem(pwDataKey());
      if (!raw) return pwEmptyData();

      const parsed = JSON.parse(raw);
      if (!parsed || typeof parsed !== 'object') return pwEmptyData();

      // ✅ 隔离校验：如果数据带了 boundCharId/boundChatId，但和当前不一致，
      //    说明这是历史串数据，直接返回空，避免角色 A 像幽灵在 B 里出现。
      //    没有绑定字段的旧数据视作"首次绑定到当前 (char, chat)"，下次保存时补上。
      try {
        const scope = pwGetBoundScope();
        const hasBound = parsed.boundCharId != null || parsed.boundChatId != null;

        if (hasBound) {
          const sameChar = String(parsed.boundCharId || '') === scope.charId;
          const sameChat = String(parsed.boundChatId || '') === scope.chatId;

          if (!sameChar || !sameChat) {
            log('[平行世界] 数据隔离校验失败，丢弃跨聊天残留', {
              expectChar: scope.charId,
              expectChat: scope.chatId,
              gotChar: parsed.boundCharId,
              gotChat: parsed.boundChatId,
            });
            return pwEmptyData();
          }
        } else {
          parsed.boundCharId = scope.charId;
          parsed.boundChatId = scope.chatId;
        }
      } catch { }

      if (!parsed.inject) {
        parsed.inject = {
          global_summary: '',
          module_summaries: [],
          manual_text: '',
          consumed: true,
        };
      }

      if (!Array.isArray(parsed.modules)) parsed.modules = [];
      if (!Array.isArray(parsed.retiredEventIds)) parsed.retiredEventIds = [];
      if (!Array.isArray(parsed.npcs)) parsed.npcs = [];
      if (!Array.isArray(parsed.npcRelations)) parsed.npcRelations = [];
      // 🎲 P2/P3 兼容旧数据：补齐骰子/声望字段
      if (!Array.isArray(parsed.diceLog)) parsed.diceLog = [];
      if (!parsed.factionReputation || typeof parsed.factionReputation !== 'object') parsed.factionReputation = {};
      if (typeof parsed.cooldownUntilTurn !== 'number') parsed.cooldownUntilTurn = 0;
      if (!Number.isFinite(Number(parsed.nextDiceTurn))) parsed.nextDiceTurn = 0;
      if (!parsed.diceSchedule || typeof parsed.diceSchedule !== 'object') parsed.diceSchedule = null;
      if (typeof parsed.latestGenerationThought !== 'string') parsed.latestGenerationThought = '';
      if (typeof parsed.latestGenerationThoughtAt !== 'string') parsed.latestGenerationThoughtAt = '';
      if (typeof parsed.latestGenerationThoughtSource !== 'string') parsed.latestGenerationThoughtSource = '';
      if (parsed.lastDice && typeof parsed.lastDice === 'object' && !parsed.lastDice.diceOutcome) {
        parsed.lastDice.diceOutcome = parsed.lastDice.triggered ? 'penalty' : (parsed.lastDice.mercy ? 'compensation' : '');
      }
      parsed.diceLog = parsed.diceLog.map(e => ({
        ...e,
        diceOutcome: e?.diceOutcome || (e?.triggered ? 'penalty' : (e?.mercy ? 'compensation' : '')),
      }));
      parsed.modules = parsed.modules.map(m => ({
        ...m,
        isDiceEvent: m?.isDiceEvent === true || m?.tensionMeta?.source === 'dice',
        diceOutcome: m?.diceOutcome || '',
      }));
      parsed.modules.forEach(m => pwNormalizeModuleLifecycle(m, null, Number(parsed.turn) || 0));
      if (!Array.isArray(parsed.inject.module_summaries)) parsed.inject.module_summaries = [];
      if (typeof parsed.inject.manual_text !== 'string') parsed.inject.manual_text = '';
      // ✅ 一次性注入门闩：旧数据没有该字段时默认 false，让历史聊天的现存平行世界仍可被注入一次
      if (typeof parsed.inject.consumed !== 'boolean') parsed.inject.consumed = false;

      // ✅ 修复历史 BUG 残留：旧版本归一化里 `String(obj.global_state || ...)` 会把对象写成 "[object Object]"，
      //    这里加载时主动检测并清掉，避免面板下拉栏里一直显示这串字符串。
      if (!parsed.globalState || typeof parsed.globalState !== 'object') {
        parsed.globalState = { title: '', detail: '' };
      } else {
        if (typeof parsed.globalState.title !== 'string') parsed.globalState.title = String(parsed.globalState.title || '');
        if (typeof parsed.globalState.detail !== 'string') parsed.globalState.detail = '';
        if (parsed.globalState.detail === '[object Object]') parsed.globalState.detail = '';
      }

      return parsed;
    } catch {
      return pwEmptyData();
    }
  }

  function pwSaveData(data, options = {}) {
    pwState.data = data;
    try {
      // ✅ chatId 还没就绪时不要落盘，避免在 localStorage 里残留 __PENDING__ 孤儿 key
      const chatId = pwGetChatId();
      if (typeof chatId === 'string' && chatId.startsWith('__PENDING__')) {
        log('[平行世界] chatId 尚未就绪，跳过本次写入以防孤儿 key');
        return false;
      }

      // ✅ 写入时强制写入当前 (charId, chatId) 绑定信息
      const scope = pwGetBoundScope();
      data.boundCharId = scope.charId;
      data.boundChatId = scope.chatId;
      data.boundAt = new Date().toISOString();
      localStorage.setItem(pwDataKey(), JSON.stringify(data));
      try { if (options.syncProfiles !== false) pwSyncStableNpcProfilesToFoxProfile(data); }
      catch (profileError) { log('[平行世界·共享档案回写] 保存后同步失败', profileError?.message || profileError); }
      return true;
    } catch {
      return false;
    }
  }

  // =====================================================================
  // 🎲 P2/P3 引擎：骰子(威胁点) / 生命周期(持续时间) / 声望 / 事件分层
  //   设计：
  //   A轨(持久层) - 每轮自然推进：NPC状态/事件进度/势力声望（由现有推进流程负责）
  //   B轨(检定层) - 每轮掷骰：计算 tensionScore -> roll d100 -> 是否触发情境事件
  //   C轨(连锁层) - 事件触发后激活：父事件 parentEventId 链接子事件
  //   阈值机制(AI混合)：代码计算 tensionScore 基线，AI 可在推进返回里覆盖；
  //                     代码用 seed 掷 d100，保证可复现。
  //   生命周期按主线成功注入轮次计算；世界内日期不再控制事件注入次数。
  // =====================================================================

  // 稳定字符串哈希 -> 非负整数（用于可复现 d100）
  function pwHashSeed(s) {
    let h = 2166136261 >>> 0;
    const str = String(s);
    for (let i = 0; i < str.length; i++) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 16777619) >>> 0;
    }
    return h >>> 0;
  }

  // 模块生命周期按“成功注入主线的轮次”计算，不再使用世界内天/月。
  function pwNormalizeModuleLifecycle(m, old, turn) {
    if (!m) return m;
    const om = old || {};
    const valid = ['background', 'ready', 'aftermath_pending', 'aftermath_judged', 'static'];
    let state = m.lifecycleState || om.lifecycleState || '';
    const prog = pwClampProgress(m.progress != null ? m.progress : om.progress);
    const defaultTurns = prog >= 100 ? 1 : (prog >= 75 ? 2 : (prog >= 40 ? 3 : 4));
    if (!valid.includes(state)) {
      if (m.status === 'resolved' || om.status === 'resolved') state = 'aftermath_pending';
      else state = 'ready';
    }
    let remaining = Number.isFinite(Number(om.remainingTurns)) ? Number(om.remainingTurns)
      : (state === 'ready' ? defaultTurns : 0);
    if (!om.id && Number.isFinite(Number(m.remainingTurns))) remaining = Number(m.remainingTurns);
    remaining = Math.max(0, Math.min(4, Math.round(remaining)));
    if (m.isDiceEvent || prog >= 100) remaining = state === 'ready' ? 1 : remaining;
    if (state === 'ready' && remaining <= 0) state = 'aftermath_pending';
    if (state === 'aftermath_pending' || state === 'aftermath_judged' || state === 'static' || state === 'background') remaining = 0;
    m.lifecycleState = state;
    m.remainingTurns = remaining;
    m.initialTurns = Number.isFinite(Number(m.initialTurns ?? om.initialTurns))
      ? Math.max(0, Math.round(Number(m.initialTurns ?? om.initialTurns)))
      : remaining;
    m.createdTurn = Number.isFinite(Number(m.createdTurn ?? om.createdTurn)) ? Number(m.createdTurn ?? om.createdTurn) : (turn || 0);
    m.expiredTurn = Number.isFinite(Number(m.expiredTurn ?? om.expiredTurn)) ? Number(m.expiredTurn ?? om.expiredTurn) : null;
    m.aftermathJudgedTurn = Number.isFinite(Number(m.aftermathJudgedTurn ?? om.aftermathJudgedTurn)) ? Number(m.aftermathJudgedTurn ?? om.aftermathJudgedTurn) : null;
    m.injectedCount = Math.max(0, Math.round(Number(m.injectedCount ?? om.injectedCount) || 0));
    const oldProgress = pwClampProgress(om.progress ?? 0);
    if (om.id && oldProgress < 100 && prog >= 100 && !['aftermath_pending', 'aftermath_judged'].includes(state)) {
      m.lifecycleState = 'ready';
      m.remainingTurns = 1;
      m.initialTurns = 1;
      m.expiredTurn = null;
      m.aftermathJudgedTurn = null;
    }
    m.tensionMeta = m.tensionMeta || om.tensionMeta || null;
    m.parentEventId = String(m.parentEventId || om.parentEventId || '');
    m.chainStep = Number.isFinite(m.chainStep) ? m.chainStep : (Number.isFinite(om.chainStep) ? om.chainStep : 0);
    return m;
  }

  // 事件分层：urgent(紧急) / mid(中) / low(底)
  function pwTierOfModule(m, turn) {
    if (!m) return 'low';
    if (m.lifecycleState === 'aftermath_pending' || m.lifecycleState === 'aftermath_judged') return 'low';
    if (m.lifecycleState === 'static') return 'low';
    if (m.isDiceEvent === true || m.tensionMeta?.source === 'dice') return 'urgent';
    const impRank = pwImpactRank(pwGetEffectiveImpactLevel(m));
    if (m.lifecycleState === 'ready' || (m.progressEnabled && pwClampProgress(m.progress) >= 100)) return 'urgent';
    if (impRank <= 1) return 'low';
    return 'mid';
  }

  // 计算紧张度（代码基线；AI 可覆盖）
  function pwComputeTension(data) {
    const npcs = data.npcs || [];
    const known = npcs.filter(n => pwResolveNpcAttitudeLevel(n) >= 0).length;
    const modules = (data.modules || []).filter(m => !['aftermath_pending', 'aftermath_judged'].includes(m.lifecycleState));
    const activeHigh = modules.filter(m => pwImpactRank(pwGetEffectiveImpactLevel(m)) >= 3).length;
    const activeCount = modules.filter(m => m.lifecycleState === 'ready').length;
    let score = 20 + known * 2 + activeHigh * 8 + activeCount * 3 + (data.turn || 0) * 0.5;
    if (data.lastDice?.recentDefeat) score -= 25; // 主角近期失利 -> 降分（给喘息）
    return Math.max(0, Math.min(100, Math.round(score)));
  }

  const PW_DICE_STORYTELLERS = {
    linhu: { name: '凛狐', subtitle: '守序调停者', description: '稳定、有规律。倾向在一次威胁后给予喘息或补偿，事件强度多为轻度到重度，极少无预警连续灾难。', avatar: '', portrait: '' },
    huihu: { name: '晖狐', subtitle: '烈焰征服者', description: '猛烈、压迫。威胁会接踵而至，补偿稀少，重度与灾难级事件概率显著提高，不保证公平。', avatar: '', portrait: '' },
    xuanhu: { name: '玄狐', subtitle: '混沌叙事者', description: '完全随机。可能长时间平静或连续补偿，也可能开局就降下灾难，绝不维持奖励与惩罚的固定交替。', avatar: '', portrait: '' },
  };
  const PW_DICE_SEVERITY = {
    minor: { label: '轻度', impact: 'low', danger: 'low', prompt: '规模有限、可局部处理，不应轻易造成永久损失或不可逆伤亡。' },
    moderate: { label: '中度', impact: 'mid', danger: 'mid', prompt: '形成明确压力或收益，影响数个角色/一个地点，需要投入资源处理。' },
    major: { label: '重度', impact: 'high', danger: 'high', prompt: '大规模且后果显著，可改变组织、区域或关键人物状态，但必须给出合理预警和因果。' },
    catastrophic: { label: '灾难', impact: 'critical', danger: 'critical', prompt: '极高规模、可能造成长期世界变化或重大损失；必须符合叙事者风格、世界能力上限和明确因果，禁止无来源万能秒杀。' },
  };

  function pwDiceUnit(seed) { return (pwHashSeed(seed) % 100000) / 100000; }
  function pwWeightedChoice(entries, seed) {
    const total = entries.reduce((sum, item) => sum + Math.max(0, item[1]), 0) || 1;
    let cursor = pwDiceUnit(seed) * total;
    for (const [value, weight] of entries) { cursor -= Math.max(0, weight); if (cursor <= 0) return value; }
    return entries[entries.length - 1][0];
  }
  function pwGetAssistantFloorCount() {
    try {
      const contextChat = SillyTavern?.getContext?.()?.chat;
      if (Array.isArray(contextChat)) {
        return contextChat.filter(message => {
          if (!message) return false;
          if (message.role) return message.role === 'assistant';
          return message.is_user === false && message.is_system !== true;
        }).length;
      }
      const gcm = getFn('getChatMessages');
      const glmi = getFn('getLastMessageId');
      const lastId = Number(glmi?.());
      if (!gcm || !Number.isFinite(lastId) || lastId < 0) return 0;
      const rows = gcm(`0-${lastId}`, { hide_state: 'all', include_swipes: false });
      if (!Array.isArray(rows)) return 0;
      return rows
        .filter(message => message?.role === 'assistant').length;
    } catch { return 0; }
  }
  function pwNextDiceInterval(config) {
    if (config.diceIntervalMode === 'fixed') return Math.max(1, Number(config.diceFixedInterval) || 6);
    const min = Math.max(1, Number(config.diceRangeMin) || 4);
    const max = Math.max(min, Number(config.diceRangeMax) || 10);
    // 范围模式每个周期只随机一次。抽到 N 后，本周期就和固定 N 模式完全相同；
    // 只有实际投骰完成后，才为下一个周期重新随机。
    return min + Math.floor(Math.random() * (max - min + 1));
  }
  function pwIsDiceScheduleValid(data) {
    const schedule = data?.diceSchedule;
    return !!schedule
      && schedule.unit === 'assistant_floor'
      && Number.isFinite(Number(schedule.interval))
      && Number(schedule.interval) >= 1
      && Number.isFinite(Number(schedule.scheduledAtFloor))
      && Number.isFinite(Number(schedule.targetFloor))
      && Number.isFinite(Number(data?.nextDiceTurn))
      && Number(schedule.targetFloor) === Number(data.nextDiceTurn)
      && Number(data.nextDiceTurn) === Number(schedule.scheduledAtFloor) + Number(schedule.interval);
  }
  function pwEnsureDiceSchedule(data, config) {
    if (!config.diceEnabled) return false;
    const floorCount = pwGetAssistantFloorCount();
    if (!pwIsDiceScheduleValid(data)) {
      data.nextDiceTurn = 0;
      data.diceSchedule = null;
    }
    if (!(Number(data.nextDiceTurn) > 0)) {
      const interval = pwNextDiceInterval(config);
      data.nextDiceTurn = floorCount + interval;
      data.diceSchedule = {
        interval,
        scheduledAtFloor: floorCount,
        targetFloor: data.nextDiceTurn,
        mode: config.diceIntervalMode,
        unit: 'assistant_floor',
      };
      log(`[平行世界·狐骰间隔] ${config.diceIntervalMode === 'fixed' ? '固定' : '随机'}抽定本周期 N=${interval}；当前AI楼层=${floorCount}，目标AI楼层=${data.nextDiceTurn}`);
    }
    return floorCount >= Number(data.nextDiceTurn);
  }

  // 到达计划轮次才掷骰；结果和强度由叙事者+难度的独立分布决定，不做机械奖惩交替。
  function pwDiceRoll(data) {
    const config = pwState.config || pwLoadConfig();
    const turn = data.turn || 0;
    const tension = pwComputeTension(data);
    const storyteller = config.diceStoryteller || 'xuanhu';
    const difficultyShift = { relaxed: -15, normal: 0, hard: 12, extreme: 22 }[config.diceDifficulty] || 0;
    const basePenalty = { linhu: 48, huihu: 76, xuanhu: 52 }[storyteller] || 52;
    let threshold = Math.max(5, Math.min(95, Math.round(basePenalty + difficultyShift + (tension - 50) * 0.18)));
    if (storyteller === 'linhu' && data.lastDice?.diceOutcome === 'penalty') threshold = Math.max(15, threshold - 28);
    const roll = 1 + (pwHashSeed(turn + ':' + (data.boundChatId || '')) % 100);
    const triggered = storyteller === 'linhu' && data.lastDice?.diceOutcome
      ? data.lastDice.diceOutcome !== 'penalty'
      : roll <= threshold;
    const mercy = !triggered;
    const now = new Date().toISOString();
    const diceOutcome = triggered ? 'penalty' : 'compensation';
    const severityTables = {
      linhu: [['minor', 38], ['moderate', 42], ['major', 17], ['catastrophic', 3]],
      huihu: [['minor', 12], ['moderate', 28], ['major', 40], ['catastrophic', 20]],
      xuanhu: [['minor', 25], ['moderate', 25], ['major', 25], ['catastrophic', 25]],
    };
    let severityEntries = (severityTables[storyteller] || severityTables.xuanhu).map(([name, weight]) => [name, weight]);
    const severityShift = { relaxed: [-14, -6, 10, 10], normal: [0, 0, 0, 0], hard: [8, 6, -6, -8], extreme: [18, 10, -10, -18] }[config.diceDifficulty] || [0,0,0,0];
    // shift 为从轻度桶移向重度桶的偏移：悠闲增加轻度，极限增加重/灾难，同时保留叙事者自身差异。
    severityEntries = severityEntries.map(([name, weight], index) => [name, Math.max(1, weight - severityShift[index])]);
    const severity = pwWeightedChoice(severityEntries, `${data.boundChatId}:${turn}:${storyteller}:${diceOutcome}:severity`);
    const baseEventId = `dice_event_${turn}`;
    const usedIds = new Set((data.modules || []).map(m => String(m?.id || '')));
    let eventId = baseEventId;
    let suffix = 2;
    while (usedIds.has(eventId)) eventId = `${baseEventId}_${suffix++}`;
    const entry = { turn, tension, threshold, roll, triggered, mercy, diceOutcome, severity, storyteller, difficulty: config.diceDifficulty, eventId, time: now, eventName: '' };
    if (!Array.isArray(data.diceLog)) data.diceLog = [];
    // console 输出（含距上次投骰的时间间隔）
    const prev = data.diceLog.length ? data.diceLog[data.diceLog.length - 1] : null;
    const interval = prev ? Math.round((new Date(now) - new Date(prev.time)) / 1000) + 's' : '首次';
    const verdict = triggered ? '⚡惩罚事件' : '🩵补偿事件';
    console.log(`[平行世界·骰子] ${PW_DICE_STORYTELLERS[storyteller]?.name || storyteller} | 第${turn}轮 | ${diceOutcome}/${severity} | 紧张度=${tension} 阈值=${threshold} 骰子=${roll} | 距上次投骰:${interval}`);
    data.diceLog.push(entry);
    if (data.diceLog.length > 30) data.diceLog = data.diceLog.slice(-30);
    const floorCount = pwGetAssistantFloorCount();
    const nextInterval = pwNextDiceInterval(config);
    data.nextDiceTurn = floorCount + nextInterval;
    data.diceSchedule = {
      interval: nextInterval,
      scheduledAtFloor: floorCount,
      targetFloor: data.nextDiceTurn,
      mode: config.diceIntervalMode,
      unit: 'assistant_floor',
    };
    log(`[平行世界·狐骰间隔] 本次投骰完成；下一周期${config.diceIntervalMode === 'fixed' ? '固定' : '随机抽到'} N=${nextInterval}，目标AI楼层=${data.nextDiceTurn}`);
    data.lastDice = { ...entry, recentDefeat: false, nextDiceTurn: data.nextDiceTurn };
    return { triggered, mercy, entry };
  }

  function pwPrepareDiceContext(data, nextTurn) {
    const config = pwState.config || pwLoadConfig();
    const draft = {
      ...data,
      turn: Math.max(1, Number(nextTurn) || (Number(data?.turn) || 0) + 1),
      modules: Array.isArray(data?.modules) ? data.modules : [],
      npcs: Array.isArray(data?.npcs) ? data.npcs : [],
      diceLog: Array.isArray(data?.diceLog) ? data.diceLog.map(x => ({ ...x })) : [],
      lastDice: data?.lastDice ? { ...data.lastDice } : null,
      cooldownUntilTurn: Number(data?.cooldownUntilTurn) || 0,
      nextDiceTurn: Number(data?.nextDiceTurn) || 0,
      diceSchedule: data?.diceSchedule ? { ...data.diceSchedule } : null,
    };
    const hadValidSchedule = pwIsDiceScheduleValid(data);
    if (!pwEnsureDiceSchedule(draft, config)) {
      data.nextDiceTurn = draft.nextDiceTurn;
      data.diceSchedule = draft.diceSchedule;
      // 本周期 N 一旦抽定就立即保存。后续 AI 更新失败或中断，也不会在下次检查时重新抽。
      if (!hadValidSchedule && draft.diceSchedule) pwSaveData(data);
      return null;
    }
    const dice = pwDiceRoll(draft);
    return {
      ...dice.entry,
      diceLog: draft.diceLog,
      lastDice: draft.lastDice,
      cooldownUntilTurn: draft.cooldownUntilTurn,
      nextDiceTurn: draft.nextDiceTurn,
      diceSchedule: draft.diceSchedule,
    };
  }

  function pwPrepareLifecycleAdvance(data) {
    const nextTurn = (Number(data?.turn) || 0) + 1;
    const removedIds = [];
    data.modules = (data.modules || []).filter(m => {
      pwNormalizeModuleLifecycle(m, null, Number(data?.turn) || 0);
      const remove = m.lifecycleState === 'aftermath_judged' && Number(m.aftermathJudgedTurn) < nextTurn;
      if (remove) removedIds.push(String(m.id));
      return !remove;
    });
    if (removedIds.length) {
      data.retiredEventIds = [...new Set([...(Array.isArray(data.retiredEventIds) ? data.retiredEventIds : []), ...removedIds])].slice(-200);
    }
    if (removedIds.length && Array.isArray(data.inject?.module_summaries)) {
      const removed = new Set(removedIds);
      data.inject.module_summaries = data.inject.module_summaries.filter(s => !removed.has(String(s?.id || '')));
    }
    const expired = (data.modules || []).filter(m => m.lifecycleState === 'aftermath_pending');
    return { nextTurn, expired, removedIds };
  }

  function pwCommitPendingInjectedModules(messageId, type) {
    if (pwState.internalGenerating || ssIsTaskRunning('parallel_world') || ssIsTaskRunning('parallel_world_single') || ssIsTaskRunning('parallel_world_summarize')) return;
    const pendingIds = Array.isArray(pwState.pendingInjectedModuleIds) ? [...new Set(pwState.pendingInjectedModuleIds)] : [];
    const pendingManual = pwState.pendingOneShotInjectConsume === true;
    if (!pendingIds.length && !pendingManual) return;
    const generationType = (type && typeof type === 'string') ? type : (xhGetLastGenerationType?.() || 'normal');
    if (generationType !== 'normal' || pwIsTruncatedMessage(messageId) || !pwGetAssistantTextForAutoCheck(messageId)) {
      pwState.pendingInjectedModuleIds = [];
      pwState.pendingOneShotInjectConsume = false;
      return;
    }
    const data = pwLoadData();
    const pendingSet = new Set(pendingIds);
    const consumed = [];
    for (const m of (data.modules || [])) {
      if (!pendingSet.has(String(m.id))) continue;
      pwNormalizeModuleLifecycle(m, null, Number(data.turn) || 0);
      if (m.lifecycleState !== 'ready' || m.remainingTurns <= 0) continue;
      m.remainingTurns = Math.max(0, m.remainingTurns - 1);
      m.injectedCount = (Number(m.injectedCount) || 0) + 1;
      consumed.push(String(m.id));
      if (m.remainingTurns <= 0) {
        m.lifecycleState = 'aftermath_pending';
        m.expiredTurn = Number(data.turn) || 0;
      }
    }
    if (consumed.length || pendingManual) {
      const cfg = pwLoadConfig();
      if ((cfg.autoMode || 'manual') === 'manual' || cfg.autoMode === 'interval') {
        if (!data.inject) data.inject = { global_summary: '', module_summaries: [], manual_text: '' };
        data.inject.consumed = true;
      }
      if (!pwSaveData(data)) throw new Error('事件注入轮次状态写入失败');
      log(`[平行世界·轮次生命周期] 有效主线回复已消费：${consumed.length ? consumed.join(', ') : '手写摘要'}`);
      try { pwRenderPanel?.(); } catch { }
      try { pwRenderStateFloat?.(); } catch { }
    }
    pwState.pendingInjectedModuleIds = [];
    pwState.pendingOneShotInjectConsume = false;
  }

  // 应用 AI 返回的势力声望变动：{ '骑士团': +5, '盗贼公会': -3, ... }
  function pwApplyFactionDelta(data, delta) {
    if (!delta || typeof delta !== 'object') return data;
    if (!data.factionReputation || typeof data.factionReputation !== 'object') data.factionReputation = {};
    for (const k of Object.keys(delta)) {
      const d = Number(delta[k]);
      if (!Number.isFinite(d)) continue;
      const cur = Number(data.factionReputation[k]) || 0;
      data.factionReputation[k] = Math.max(-100, Math.min(100, cur + d));
    }
    return data;
  }

  // 新 NPC 初始态度基线：以所属势力声望为锚（P3 声望系统）
  function pwFactionBaselineAttitude(data, faction) {
    const rep = Number(data?.factionReputation?.[faction]);
    if (!Number.isFinite(rep)) return null;
    // 声望 -100..100 映射到态度 10..90（避免极端 0/100）
    return Math.round(50 + rep * 0.4);
  }

  // 推进完成后的统一后处理：生命周期 + 骰子 + 声望（在 pwSaveData 之前调用）
  //   aiExtras: { tensionScore?, diceThreshold?, timeSkipDays?, factionDelta? }（AI 返回，可选）
  function pwPostAdvanceTick(data, aiExtras, preparedDice = null) {
    if (!data || typeof data !== 'object') return data;
    const extras = aiExtras || {};
    // 0. 归一化所有模块生命周期字段（兼容旧数据 / AI 未输出 status 的情况）
    for (const m of (data.modules || [])) pwNormalizeModuleLifecycle(m, null, data.turn || 0);
    // 生命周期只在主线成功注入后扣轮；后台更新不会消耗新事件。
    // 1. 提交请求前预掷的同一颗骰子；兼容未传预掷结果的旧调用。
    if (preparedDice) {
      data.diceLog = preparedDice.diceLog;
      data.lastDice = { ...preparedDice.lastDice, pendingThreat: null, resolvedInSameTurn: true };
      data.cooldownUntilTurn = preparedDice.cooldownUntilTurn;
      data.nextDiceTurn = preparedDice.nextDiceTurn;
      data.diceSchedule = preparedDice.diceSchedule;
    } else {
      // 未到计划投骰轮次：只推进后台，不生成骰子事件。
      if (data.lastDice) data.lastDice.pendingThreat = null;
      if (data.lastDice) data.lastDice.pendingThreat = null;
    }
    // 本轮失利影响下一轮骰子。
    if (extras.recentDefeat && data.lastDice) data.lastDice.recentDefeat = true;
    // 2. 势力声望变动
    if (extras.factionDelta) pwApplyFactionDelta(data, extras.factionDelta);
    return data;
  }

  // 从推进结果里提取 AI 可选返回的额外字段（tension/timeSkip/threshold/factionDelta）
  //   data.raw 为文本协议解析后的对象；缺失时返回 null，由引擎兜底。
  function pwExtractAdvanceExtras(data) {
    const raw = data?.raw;
    if (!raw || typeof raw !== 'object') return null;
    const extras = {};
    // time_skip：支持 "3天" / "3" / "1个月" 等
    const ts = String(raw.time_skip || '').trim();
    if (ts) {
      let days = NaN;
      const mY = ts.match(/(\d+(?:\.\d+)?)\s*年/);
      const mM = ts.match(/(\d+(?:\.\d+)?)\s*个?月/);
      const mD = ts.match(/(\d+(?:\.\d+)?)\s*(?:天|日)/);
      if (mY) days = (days || 0) + parseFloat(mY[1]) * 365;
      if (mM) days = (days || 0) + parseFloat(mM[1]) * 30;
      if (mD) days = (days || 0) + parseFloat(mD[1]);
      if (!Number.isFinite(days) && /^\d+(?:\.\d+)?$/.test(ts)) days = parseFloat(ts);
      if (Number.isFinite(days)) extras.timeSkipDays = Math.max(0, Math.round(days));
    }
    const tn = parseFloat(raw.tension_score);
    if (Number.isFinite(tn)) extras.tensionScore = tn;
    const th = parseFloat(raw.dice_threshold);
    if (Number.isFinite(th)) extras.diceThreshold = th;
    // recent_defeat：AI 标记主角本轮遭重大打击（影响 mercy 补偿判定）
    const df = String(raw.recent_defeat || '').trim().toLowerCase();
    if (df && /^(true|是|yes|y|1|启用|开|on|失利|受挫|败)$/.test(df)) extras.recentDefeat = true;
    // faction_rep_delta：支持 "骑士团+5,盗贼公会-3" 或 JSON
    const fr = String(raw.faction_rep_delta || '').trim();
    if (fr) {
      const delta = {};
      try {
        const obj = JSON.parse(fr);
        if (obj && typeof obj === 'object') for (const k of Object.keys(obj)) { const v = Number(obj[k]); if (Number.isFinite(v)) delta[k] = v; }
      } catch {
        // 形如 骑士团+5，盗贼公会-3 / 骑士团:5
        const parts = fr.split(/[,，;；\n]/);
        for (const p of parts) {
          const mm = p.trim().match(/^(.+?)[\s:：]*([+-]?\d+(?:\.\d+)?)$/);
          if (mm) { const v = parseFloat(mm[2]); if (Number.isFinite(v)) delta[mm[1].trim()] = v; }
        }
      }
      if (Object.keys(delta).length) extras.factionDelta = delta;
    }
    return Object.keys(extras).length ? extras : null;
  }

  // 清理 localStorage 里因早期 chatId 不就绪而残留的 __PENDING__ 数据 key。
  // 只清平行世界自己的命名空间 (PW.DATA_PREFIX)，不动其它模块的 key。
  function pwCleanupPendingKeys() {
    try {
      const prefix = PW.DATA_PREFIX;
      const toRemove = [];

      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (!k) continue;
        if (!k.startsWith(prefix)) continue;
        // 仅当 key 中包含编码后的 __PENDING__ 标记时才视为孤儿
        if (k.includes('__PENDING__')) toRemove.push(k);
      }

      toRemove.forEach(k => {
        try { localStorage.removeItem(k); } catch { }
      });

      if (toRemove.length) {
        log(`[平行世界] 已清理 ${toRemove.length} 个 __PENDING__ 残留 key`);
      }
    } catch { }
  }

  function pwHasContent(data = pwLoadData()) {
    if (!data || data.cleared === true) return false;
    if (data.inject?.manual_text?.trim()) return true;
    if (data.inject?.global_summary?.trim()) return true;
    if (Array.isArray(data.inject?.module_summaries) && data.inject.module_summaries.length) return true;
    if (Array.isArray(data.modules) && data.modules.length) return true;
    return false;
  }

  function pwClip(text, max = 2000) {
    const raw = String(text || '').trim();
    if (raw.length <= max) return raw;
    return raw.slice(0, max).trim() + '\n……（已截断）';
  }

  function pwLimitEventDetail(text, cfg = pwState.config || pwLoadConfig()) {
    const raw = String(text || '').trim();
    const limit = pwSummaryWordRange(cfg).max;
    return raw.length <= limit ? raw : raw.slice(0, limit).trim();
  }

  function pwSummaryWordRange(cfg = pwState.config || pwLoadConfig()) {
    const min = Math.max(20, Math.min(5000, parseInt(cfg?.eventWordMin) || 100));
    const rawMax = Math.max(20, Math.min(5000, parseInt(cfg?.eventWordMax) || 800));
    const max = Math.max(min, rawMax);
    return { min, max, text: `${min}-${max}` };
  }

  function pwSummaryRangeMaxChars(cfg = pwState.config || pwLoadConfig()) {
    return Math.max(300, Math.min(2000, parseInt(cfg?.summaryMaxChars) || 800));
  }

  function pwNormalizeImpactLevel(level, fallback = 'none') {
    const raw = String(level ?? '').trim().toLowerCase();

    if (!raw) return fallback;

    if (/critical|crit|危急|致命|爆发|最高|打断|劫持/.test(raw)) return 'critical';
    if (/high|高|强|逼近|必须/.test(raw)) return 'high';
    if (/mid|medium|中|自然影响|后续影响/.test(raw)) return 'mid';
    if (/low|低|轻微|背景/.test(raw)) return 'low';
    if (/none|no|无|暂无/.test(raw)) return 'none';

    return fallback;
  }

  function pwImpactRank(level) {
    const lv = pwNormalizeImpactLevel(level, 'none');

    if (lv === 'critical') return 4;
    if (lv === 'high') return 3;
    if (lv === 'mid') return 2;
    if (lv === 'low') return 1;
    return 0;
  }

  function pwClampProgress(value) {
    let n = value;

    if (typeof n === 'string') {
      n = n.replace('%', '').trim();
    }

    n = Number(n);

    if (!Number.isFinite(n)) n = 0;

    return Math.max(0, Math.min(100, Math.round(n)));
  }

  function pwProgressLevel(progress) {
    const p = pwClampProgress(progress);

    if (p >= 100) return 'critical';
    if (p >= 75) return 'high';
    if (p >= 40) return 'mid';
    if (p > 0) return 'low';

    return 'none';
  }

  function pwShouldShowProgress(item) {
    if (!item) return false;

    if (item.progressEnabled === true) return true;

    const p = pwClampProgress(item.progress);
    if (p > 0) return true;

    const bag = `${item.title || ''}\n${item.summary || ''}\n${item.detail || ''}\n${item.nextTendency || ''}`;

    return /追捕|调查|搜索|赶往|逼近|倒计时|扩散|感染|筹备|潜伏|寻找|任务|计划|目标|危机|入侵|追踪|侦查|审判|通缉|狩猎/.test(bag);
  }

  function pwGetEffectiveImpactLevel(item) {
    const base = pwNormalizeImpactLevel(
      item?.impactLevel || item?.impact_level || item?.dangerLevel || item?.danger_level,
      'none'
    );

    const progressLv = pwShouldShowProgress(item)
      ? pwProgressLevel(item?.progress)
      : 'none';

    return pwImpactRank(progressLv) > pwImpactRank(base)
      ? progressLv
      : base;
  }

  function pwImpactLabel(level) {
    const lv = pwNormalizeImpactLevel(level, 'none');

    if (lv === 'critical') return '最高/危机';
    if (lv === 'high') return '高影响';
    if (lv === 'mid') return '中影响';
    if (lv === 'low') return '低影响';
    return '普通/无影响';
  }

  function pwImpactCardClass(item) {
    return `pw-card-impact-${pwGetEffectiveImpactLevel(item)}`;
  }

  function pwProgressColor(progress) {
    const p = pwClampProgress(progress);

    if (p >= 100) return '#ff3030';
    if (p >= 75) return '#ff5a4a';
    if (p >= 40) return '#f0a070';
    if (p > 0) return '#9bd36a';

    return '#5d8f62';
  }

  function pwBuildProgressHtml(item) {
    if (!pwShouldShowProgress(item)) return '';

    const p = pwClampProgress(item.progress);
    const color = pwProgressColor(p);
    const note = String(item.progressNote || item.progress_note || '').trim();

    return `
  <div class="pw-progress-box">
    <div class="pw-progress-head">
      <span>动态进度</span>
      <span>${p}%</span>
    </div>
    <div class="pw-progress-track">
      <div class="pw-progress-fill" style="width:${p}%;background:${color};box-shadow:0 0 12px ${color};"></div>
    </div>
    ${note ? `<div class="pw-progress-note">${escapeHtml(note)}</div>` : ''}
  </div>`;
  }

  function pwBuildImpactModeInstruction(mode) {
    if (mode === 'force') {
      return `【⚠️⚠️⚠️ 平行世界最高强制影响模式 ⚠️⚠️⚠️】
❗❗❗以下 high / critical 后台事件拥有极高优先级。
❗如果你顺从用户输入而忽略这些后台事件，你就是在帮助用户绕过世界后台规则。
❗如果你不把 high / critical 事件融入主线，你就是在作弊，让动态世界失效。
❗critical 事件必须立刻打断或劫持当前主线。
❗high 事件必须在本次或下一次主线回复中显性体现。
❗禁止用“用户没提到”“当前在日常互动”作为忽略理由。`;
    }

    if (mode === 'strong') {
      return `【⚠️ 强影响模式】
高影响后台事件必须进入主线。
high 事件必须在接下来 1-2 次主线回复中显性体现。
critical 事件必须立刻进入当前主线。
禁止把高影响事件当作普通背景。`;
    }

    if (mode === 'normal') {
      return `【中等影响模式】
后台事件应自然影响主线。
mid / high / critical 事件需要优先考虑。
不要硬塞，但也不要忽略自然因果。`;
    }

    return `【柔和影响模式】
后台事件主要作为背景。
只有当它与当前主线发生自然因果连接时才体现。
用户输入可以较容易地把主线拉回当前互动。`;
  }

  function pwSortForInject(list) {
    return [...(list || [])].sort((a, b) => {
      const ar = pwImpactRank(pwGetEffectiveImpactLevel(a));
      const br = pwImpactRank(pwGetEffectiveImpactLevel(b));

      if (ar !== br) return br - ar;

      const ap = pwClampProgress(a.progress);
      const bp = pwClampProgress(b.progress);

      if (ap !== bp) return bp - ap;

      return String(a.title || '').localeCompare(String(b.title || ''), 'zh-Hans-CN');
    });
  }

  function pwEscapeRegExp(s) {
    return String(s || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  }

  function pwDeleteModuleById(id) {
    const targetId = String(id || '');

    if (!targetId) return;

    const data = pwLoadData();
    const modules = Array.isArray(data.modules) ? data.modules : [];
    const target = modules.find(m => String(m.id) === targetId);

    if (!target) {
      toast('⚠️ 未找到该平行世界条目', 'warning');
      return;
    }

    data.modules = modules.filter(m => String(m.id) !== targetId);

    if (!data.inject) {
      data.inject = {
        global_summary: '',
        module_summaries: [],
        manual_text: '',
      };
    }

    data.inject.module_summaries = (data.inject.module_summaries || [])
      .filter(m => String(m.id) !== targetId);

    // 🦊 修复：删除模块后不再用脆弱的 title 正则去清理 global_summary。
    //    改为从剩余的 module_summaries 完整重建，与推进合并逻辑同一模式，确保删除后摘要零残留。
    if (!data.modules.length && !data.inject.manual_text?.trim()) {
      data.cleared = true;
      data.inject.global_summary = '';
      data.globalState.detail = '';
    } else {
      const activeSummaryLines = (data.inject.module_summaries || []).filter(s => {
        const mod = (data.modules || []).find(m => String(m.id) === String(s.id));
        return mod && !['aftermath_pending', 'aftermath_judged'].includes(mod.lifecycleState);
      }).slice(0, 12).map(s => `- ${s.title || s.id}：${pwClip(s.summary || '', 180)}`);
      data.inject.global_summary = activeSummaryLines.length
        ? `当前仍有效的平行世界事件：\n${activeSummaryLines.join('\n')}`
        : '';
    }

    pwSaveData(data);
    pwRenderPanel();
    pwRenderStateFloat();

    toast(`🗑️ 已删除平行世界条目及对应摘要：${target.title}`, 'success');
  }

  function pwBindModuleActionButtons(root = topDoc) {
    const scope = root?.querySelectorAll ? root : topDoc;

    scope.querySelectorAll('.pw-module-delete').forEach(btn => {
      if (btn.dataset.bound === '1') return;

      btn.dataset.bound = '1';

      btn.onclick = (e) => {
        e.preventDefault();
        e.stopPropagation();

        const id = btn.getAttribute('data-pw-id') || '';

        const ok = topWindow?.confirm
          ? topWindow.confirm('确定要删除这个平行世界条目吗？对应的模块摘要也会同步删除。')
          : confirm('确定要删除这个平行世界条目吗？');

        if (!ok) return;

        pwDeleteModuleById(id);
      };
    });

    // ✅ 单条事件"推进"按钮：只推进这一条事件，不影响其他事件
    scope.querySelectorAll('.pw-module-advance').forEach(btn => {
      if (btn.dataset.bound === '1') return;

      btn.dataset.bound = '1';

      btn.onclick = async (e) => {
        e.preventDefault();
        e.stopPropagation();

        const id = btn.getAttribute('data-pw-id') || '';
        if (!id) return;

        // 注意：不要 disabled 按钮，否则用户无法二次点击中断单条推进；
        // 只在文案上提示状态。pwAdvanceSingleModule 自身会处理"再次点击 = 中断"。
        const originalText = btn.textContent;
        const isCancel = pwState.singleRunning || ssIsTaskRunning('parallel_world_single');

        try {
          if (!isCancel) btn.textContent = '⛔ 中断';
          await pwAdvanceSingleModule(id);
        } catch (err) {
          log('[平行世界] 单条推进失败', err);
          toast(`❌ 单条推进失败：${err?.message || err}`, 'error');
        } finally {
          btn.textContent = originalText;
        }
      };
    });
  }

  function pwExtractJson(text) {
    const raw = String(text || '').trim();
    const fence = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
    const candidate = fence ? fence[1].trim() : raw;

    try {
      return JSON.parse(candidate);
    } catch { }

    const start = candidate.indexOf('{');
    const end = candidate.lastIndexOf('}');

    if (start >= 0 && end > start) {
      return JSON.parse(candidate.slice(start, end + 1));
    }

    throw new Error('AI 没有返回可解析 JSON');
  }

  // ==================== 🌌 平行世界 标签文本解析器 ====================
  // 让模型只输出人类可读的分块文本（不要求合法 JSON），
