    'TRUST': 'trust', '信任': 'trust',
    'INTIMACY': 'intimacy', '亲密': 'intimacy',
    'FEAR': 'fear', '恐惧': 'fear',
    'RESPECT': 'respect', '尊敬': 'respect',
    'JEALOUSY': 'jealousy', '嫉妒': 'jealousy',
    'INTEREST': 'interest', '利益关联': 'interest',
    'DEPENDENCE': 'dependence', '依赖': 'dependence',
    // 关系字段
    'FROM': 'from', '起点': 'from', 'NPC_A': 'from',
    'TO': 'to', '终点': 'to', 'NPC_B': 'to',
    'VALENCE': 'valence', '关系性质': 'valence',
    'RELATION_LEVEL': 'relation_level', '关系值': 'relation_level', '关系刻度': 'relation_level', '关系强度': 'relation_level',
    'NOTE': 'note', '备注': 'note', '关系说明': 'note',
    // 事件关联NPC
    'LINKED_NPC_IDS': 'linked_npc_ids', '关联NPC': 'linked_npc_ids', '关联人物': 'linked_npc_ids',
    'ORIGIN': 'origin', '事件来源': 'origin',
    'INITIATOR_NPC_IDS': 'initiator_npc_ids', '发起NPC': 'initiator_npc_ids',
    'SOURCE_GOAL': 'source_goal', '来源目标': 'source_goal',
    'SOURCE_STAKE': 'source_stake', '来源牵挂': 'source_stake',
    'INITIATIVE_REASON': 'initiative_reason', '自主发起理由': 'initiative_reason',
  };

  // 归一化辅助：忽略大小写、下划线、空白后的查找表（英文键）
  const PW_TP_KEY_MAP_LOOSE = (() => {
    const m = {};
    for (const k of Object.keys(PW_TP_KEY_MAP)) {
      const loose = k.toUpperCase().replace(/[_\s]/g, '');
      if (!(loose in m)) m[loose] = PW_TP_KEY_MAP[k];
    }
    return m;
  })();

  function pwTpNormalizeKey(rawKey) {
    if (!rawKey) return '';
    // 去掉标签外壳字符（# < > 【】［］ 冒号 空白），保留核心键名
    const cleaned = String(rawKey).trim().replace(/[#<>【】\[\]：:\s]/g, '');
    if (!cleaned) return '';
    // 1) 中文/原样键直接查表
    if (PW_TP_KEY_MAP[cleaned]) return PW_TP_KEY_MAP[cleaned];
    // 2) 英文键大写后查表
    const upper = cleaned.toUpperCase();
    if (PW_TP_KEY_MAP[upper]) return PW_TP_KEY_MAP[upper];
    // 3) 忽略下划线/空白的宽松匹配（兼容 # WORLD CLOCK / WORLDCLOCK 等写法）
    const loose = upper.replace(/[_\s]/g, '');
    if (PW_TP_KEY_MAP_LOOSE[loose]) return PW_TP_KEY_MAP_LOOSE[loose];
    // 4) 兜底：返回小写英文键
    return upper.toLowerCase();
  }

  function pwTpToBool(v) {
    const s = String(v || '').trim();
    if (!s) return false;
    if (PW_TP_BOOL_TRUE.test(s)) return true;
    if (PW_TP_BOOL_FALSE.test(s)) return false;
    return false;
  }

  function pwTpToNumber(v) {
    const s = String(v || '').trim();
    const m = s.match(/-?\d+(?:\.\d+)?/);
    return m ? parseFloat(m[0]) : 0;
  }

  function pwTpToOptionalNumber(v) {
    if (v == null || String(v).trim() === '') return undefined;
    return pwTpToNumber(v);
  }

  function pwTpToLineList(v) {
    return String(v || '').split(/\r?\n|[；;|｜]/).map(s => s.replace(/^[-*•\d.、)\s]+/, '').trim()).filter(pwTpIsMeaningful);
  }

  function pwTpIsMeaningful(v) {
    const s = String(v || '').trim();
    return !!s && !/^(?:无|空|未知|none|null|n\/a|na)$/i.test(s);
  }

  function pwTpToIdList(v) {
    return String(v || '')
      .split(/[,，、|｜\s]+/)
      .map(s => s.trim())
      .filter(pwTpIsMeaningful);
  }

  function pwTpFirstContentLine(v) {
    return String(v || '').split(/\r?\n/).map(s => s.trim()).find(Boolean) || '';
  }

  // ── 统一标签匹配（高容错）──────────────────────────────
  // 新格式（推荐，简单直观）：每个标签独占一行，以 # 开头，例如：
  //   # 标题
  //   # DETAIL
  // 旧格式（向后兼容）：<<<KEY>>>，并兼容写错括号数量的情况，如 <<<KEY>> / <<KEY>>> / <<KEY>>。
  //
  // 这里用一个统一正则把"一整行就是一个标签"的行识别出来：
  // - 形如  #KEY / # KEY / ##KEY
  // - 形如  <<<KEY>>> / <<KEY>> / <<<KEY>>  （两个或更多尖括号，左右数量可不一致）
  // 标签行里只允许标签本身（前后可有空白），不允许夹带正文，避免误伤。
  const PW_TP_TAG_LINE_RE = /^[ \t]*(?:#{1,3}[ \t]*([^\r\n#<>]+?)|<{2,}[ \t]*([^\r\n<>]+?)[ \t]*>{2,})[ \t]*$/;

  // 块的开始/结束标记（标准键，已归一化后比较）
  const PW_TP_BLOCK_BEGIN = { module: 'module_begin', summary: 'summary_begin', npc: 'npc_begin', relation: 'relation_begin' };
  const PW_TP_BLOCK_END = { module: 'module_end', summary: 'summary_end', npc: 'npc_end', relation: 'relation_end' };

  // 所有合法的归一化"字段"键集合（只有命中这些键的行才会被当作字段标签，
  // 否则视为正文，避免正文中偶发的 # 开头行被误判为标签而截断内容）。
  // 注意：故意排除块边界标记（module_begin/end、summary_begin/end），
  // 因为块的识别由 pwTpExtractBlocks/pwTpStripBlocks 单独处理；
  // 这样即便正文里出现“# 模块结束”等词，也只会当作普通正文，不会截断字段。
  const PW_TP_BLOCK_NORMS = new Set([
    PW_TP_BLOCK_BEGIN.module, PW_TP_BLOCK_END.module,
    PW_TP_BLOCK_BEGIN.summary, PW_TP_BLOCK_END.summary,
    PW_TP_BLOCK_BEGIN.npc, PW_TP_BLOCK_END.npc,
    PW_TP_BLOCK_BEGIN.relation, PW_TP_BLOCK_END.relation,
  ]);
  const PW_TP_VALID_NORMS = (() => {
    const s = new Set(Object.values(PW_TP_KEY_MAP));
    for (const b of PW_TP_BLOCK_NORMS) s.delete(b);
    return s;
  })();

  function pwTpScanTags(text) {
    const out = [];
    const src = String(text || '');
    const lines = src.split(/\r?\n/);
    let pos = 0;
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const lineLen = line.length;
      const lineEnd = pos + lineLen;
      pos = lineEnd + 1; // +1 为换行符
      const m = line.match(PW_TP_TAG_LINE_RE);
      if (m) {
        const rawKey = (m[1] || m[2] || '').trim();
        if (!rawKey) continue;
        const norm = pwTpNormalizeKey(rawKey);
        // 只接受已知字段键或块边界标记，未知的一律当正文处理
        if (!norm || !PW_TP_VALID_NORMS.has(norm)) continue;
        out.push({ rawKey, norm, contentStart: lineEnd + 1 });
      }
    }
    return out;
  }

  // 解析单个块内的字段（块内文本不含 BEGIN/END 标记行）
  function pwTpParseBlock(blockText) {
    const obj = {};
    if (!blockText) return obj;

    // 🦊 修复：AI 常把 key 和 value 写在同一行（如 "# ID su_father_insomnia"），
    // 与期望的换行格式（# ID \n su_father_insomnia）不一致，导致 pwTpScanTags
    // 把整行当成未知标签名而跳过，模块/NPC/关系全部解析为空。
    // 这里做预处理：若整行的 normalized fullKey 不在已知集合，但第一个空格前的词是，
    // 则把该行拆为标签行 + 值行，恢复为 pwTpScanTags 能识别的标准换行格式。
    if (blockText) {
      const lines = blockText.split(/\r?\n/);
      const converted = [];
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const m = line.match(PW_TP_TAG_LINE_RE);
        if (m) {
          let rawKey = (m[1] || m[2] || '').trim();
          if (rawKey) {
            let normFull = pwTpNormalizeKey(rawKey);
            if (!normFull || !PW_TP_VALID_NORMS.has(normFull)) {
              const firstSpace = rawKey.indexOf(' ');
              if (firstSpace > 0) {
                const firstPart = rawKey.slice(0, firstSpace);
                const firstNorm = pwTpNormalizeKey(firstPart);
                if (firstNorm && PW_TP_VALID_NORMS.has(firstNorm)) {
                  const prefixEnd = line.indexOf(rawKey);
                  const prefix = prefixEnd >= 0 ? line.slice(0, prefixEnd) : '# ';
                  converted.push(prefix + firstPart.trim());
                  converted.push(rawKey.slice(firstSpace + 1).trim());
                  continue;
                }
              }
            }
          }
        }
        converted.push(line);
      }
      blockText = converted.join('\n');
    }

    const tags = pwTpScanTags(blockText);
    if (!tags.length) return obj;
    for (let i = 0; i < tags.length; i++) {
      const cur = tags[i];
      const next = tags[i + 1];
      const norm = cur.norm;
      // 跳过块边界标记
      if (!norm || /_(begin|end)$/.test(norm)) continue;
      const sliceEnd = next ? Math.max(cur.contentStart, blockTextIndexOfTagLine(blockText, next)) : blockText.length;
      const value = blockText.slice(cur.contentStart, sliceEnd).trim();
      // 只在第一次出现时写入，避免重复标签覆盖（如正文中误带标签行的极端情况）
      if (!(norm in obj)) obj[norm] = value;
    }
    Object.defineProperty(obj, '__present', { value: new Set(Object.keys(obj)), enumerable: false });
    return obj;
  }

  // 找到某个标签在原文中所属行的起始下标（用于切分上一字段的值的末尾）
  function blockTextIndexOfTagLine(blockText, tag) {
    // tag.contentStart 是该标签行的下一行起点；回退到该标签行的行首
    let idx = tag.contentStart - 1; // 换行符位置
    if (idx < 0) idx = 0;
    // 回退到行首
    let lineStart = blockText.lastIndexOf('\n', idx - 1);
    return lineStart < 0 ? 0 : lineStart + 1;
  }

  // 通用块切分：按 BEGIN/END 标记，返回每个块内部文本（不含标记行）。高容错。
  function pwTpExtractBlocks(text, kind /* 'module' | 'summary' */) {
    const beginNorm = PW_TP_BLOCK_BEGIN[kind];
    const endNorm = PW_TP_BLOCK_END[kind];
    const src = String(text || '');
    const lines = src.split(/\r?\n/);
    const blocks = [];
    let cur = null; // 当前块的行缓冲
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const m = line.match(PW_TP_TAG_LINE_RE);
      const norm = m ? pwTpNormalizeKey((m[1] || m[2] || '').trim()) : '';
      if (norm === beginNorm) {
        // 开始一个新块（若上一个块未闭合，也先收掉，容错）
        if (cur !== null) blocks.push(cur.join('\n'));
        cur = [];
        continue;
      }
      if (norm === endNorm) {
        if (cur !== null) { blocks.push(cur.join('\n')); cur = null; }
        continue;
      }
      if (cur !== null) cur.push(line);
    }
    // 块未显式闭合也收掉（容错：模型漏写结束标记）
    if (cur !== null && cur.length) blocks.push(cur.join('\n'));
    return blocks;
  }

  // 把块标记行从文本中剔除，得到"顶层"部分（用于顶层标量解析）
  function pwTpStripBlocks(text) {
    const src = String(text || '');
    const lines = src.split(/\r?\n/);
    const out = [];
    let depth = 0;
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const m = line.match(PW_TP_TAG_LINE_RE);
      const norm = m ? pwTpNormalizeKey((m[1] || m[2] || '').trim()) : '';
      if (norm === PW_TP_BLOCK_BEGIN.module || norm === PW_TP_BLOCK_BEGIN.summary || norm === PW_TP_BLOCK_BEGIN.npc || norm === PW_TP_BLOCK_BEGIN.relation) { depth++; continue; }
      if (norm === PW_TP_BLOCK_END.module || norm === PW_TP_BLOCK_END.summary || norm === PW_TP_BLOCK_END.npc || norm === PW_TP_BLOCK_END.relation) { if (depth > 0) depth--; continue; }
      if (depth === 0) out.push(line);
    }
    return out.join('\n');
  }

  // 仅当整段输出被一对代码围栏包裹时，才剥掉首尾的围栏行。
  // 不再用贪婪的“首对反引号之间”捕获，避免正文里偶发的 ``` 把后续内容（整块模块/摘要）误删。
  function pwTpStripFence(text) {
    const raw = String(text || '');
    const lines = raw.split(/\r?\n/);
    // 找到第一行非空行与最后一行非空行
    let first = 0;
    while (first < lines.length && lines[first].trim() === '') first++;
    let last = lines.length - 1;
    while (last >= 0 && lines[last].trim() === '') last--;
    if (first > last) return raw;
    const isFenceLine = (s) => /^[ \t]*`{3,}[a-zA-Z]*[ \t]*$/.test(s);
    // 只有首尾都是围栏行时，才认为是“整段被围栏包裹”，剥掉这两行
    if (isFenceLine(lines[first]) && last > first && isFenceLine(lines[last])) {
      return lines.slice(first + 1, last).join('\n');
    }
    return raw;
  }

  // 顶层文本协议解析：返回与 JSON 等价的对象
  // 适用于 pwGenerateStep（整轮）/ pwAdvanceMultipleModules（多条推进）的输出
  function pwParseTextProtocolWorld(text) {
    const raw = String(text || '');
    if (!raw.trim()) throw new Error('AI 返回空内容');

    // 去掉可能的代码围栏（仅当整段被围栏包裹时）
    const body = pwTpStripFence(raw);

    // 先提取 module/summary 块，并把它们从主体里挖空，
    // 避免它们内部的字段干扰顶层标量解析
    const moduleBlocks = pwTpExtractBlocks(body, 'module');
    const summaryBlocks = pwTpExtractBlocks(body, 'summary');

    const topPart = pwTpStripBlocks(body);

    const top = pwTpParseBlock(topPart);

    let modules = moduleBlocks.map((b, i) => {
      const o = pwTpParseBlock(b);
      if (!Object.keys(o).length) return null;
      const module = {
        id: pwTpIsMeaningful(o.id) ? o.id : '',
        type: o.type || 'other',
        title: o.title || '',
        perspective: o.perspective || '',
        role_audit: o.role_audit || '',
        detail: o.detail || '',
        independence: o.independence || '',
        impact_level: o.impact_level || 'none',
        progress_enabled: pwTpToBool(o.progress_enabled),
        progress: pwTpToNumber(o.progress),
        progress_note: o.progress_note || '',
        current_location: o.current_location || '',
        current_state: o.current_state || '',
        next_tendency: o.next_tendency || '',
        danger_level: o.danger_level || 'none',
        linked_npc_ids: pwTpToIdList(o.linked_npc_ids || o.linked_npcs),
        origin: o.origin || '',
        initiator_npc_ids: pwTpToIdList(o.initiator_npc_ids),
        source_goal: pwTpIsMeaningful(o.source_goal) ? o.source_goal : '',
        source_stake: pwTpIsMeaningful(o.source_stake) ? o.source_stake : '',
        initiative_reason: pwTpIsMeaningful(o.initiative_reason) ? o.initiative_reason : '',
        is_dice_event: pwTpToBool(o.is_dice_event),
        dice_outcome: o.dice_outcome || '',
        dice_roll: pwTpToOptionalNumber(o.dice_roll),
        dice_threshold: pwTpToOptionalNumber(o.dice_threshold),
        dice_tension: pwTpToOptionalNumber(o.dice_tension),
        dice_turn: pwTpToOptionalNumber(o.dice_turn),
        remaining_turns: pwTpToOptionalNumber(o.remaining_turns),
        lifecycle_state: o.lifecycle_state || '',
        creation_reason: o.creation_reason || '',
        parent_event_id: o.parent_event_id || '',
      };
      return module;
    }).filter(Boolean);

    const moduleSummaries = summaryBlocks.map((b, i) => {
      const o = pwTpParseBlock(b);
      if (!Object.keys(o).length) return null;
      return {
        id: pwTpIsMeaningful(o.id) ? o.id : (modules[i]?.id || `summary_${i + 1}`),
        type: o.type || modules[i]?.type || 'other',
        title: o.title || modules[i]?.title || `后台摘要 ${i + 1}`,
        time: o.time || '',
        summary: o.summary || '',
        impact_level: o.impact_level || 'none',
        progress_enabled: pwTpToBool(o.progress_enabled),
        progress: pwTpToNumber(o.progress),
        progress_note: o.progress_note || '',
      };
    }).filter(Boolean);

    // ✅ NPC 持续模块：每个 NPC 一个独立长期档案（情绪/对主角看法/位置/状态）
    const npcBlocks = pwTpExtractBlocks(body, 'npc');
    const npcs = npcBlocks.map((b, i) => {
      const o = pwTpParseBlock(b);
      const npc = {
        id: o.id || `npc_${i + 1}`,
        name: o.name || o.title || `NPC ${i + 1}`,
        emotion: o.emotion || '',
        emotionLevel: o.emotion_level != null && o.emotion_level !== '' ? o.emotion_level : undefined,
        attitude: o.__present?.has('attitude') ? pwNormalizeNpcAttitude(o.attitude || '') : undefined,
        attitudeLevel: o.attitude_level != null && o.attitude_level !== '' ? o.attitude_level : undefined,
        location: o.location || o.current_location || '',
        status: o.status || o.current_state || '',
        goals: o.goals || '',
        currentThought: o.current_thought || '',
        shortTermGoal: o.short_term_goal || '',
        longTermGoal: o.long_term_goal || '',
        health: pwTpToOptionalNumber(o.health),
        healthNote: o.health_note || '',
        fatigue: pwTpToOptionalNumber(o.fatigue),
        fatigueNote: o.fatigue_note || '',
        standing: o.standing || '',
        standingLevel: pwTpToOptionalNumber(o.standing_level),
        standingNote: o.standing_note || '',
        goalStatus: o.goal_status || '',
        goalProgress: pwTpToOptionalNumber(o.goal_progress),
        goalProgressNote: o.goal_progress_note || '',
        goalPriority: pwTpToOptionalNumber(o.goal_priority),
        goalUrgency: pwTpToOptionalNumber(o.goal_urgency),
        goalImportance: pwTpToOptionalNumber(o.goal_importance),
        goalRisk: pwTpToOptionalNumber(o.goal_risk),
        goalCost: pwTpToOptionalNumber(o.goal_cost),
        goalObstacle: o.goal_obstacle || '',
        goalOutcome: o.goal_outcome || '',
        goalChangeReason: o.goal_change_reason || '',
        activeGoalReason: o.active_goal_reason || '',
        confirmedFacts: pwTpToLineList(o.confirmed_facts),
        rumors: pwTpToLineList(o.rumors),
        assumptions: pwTpToLineList(o.assumptions),
        falseBeliefs: pwTpToLineList(o.false_beliefs),
        deniedFacts: pwTpToLineList(o.denied_facts),
        commitments: pwTpToLineList(o.commitments),
        debts: pwTpToLineList(o.debts),
        secrets: pwTpToLineList(o.secrets),
        lifeLog: pwTpToLineList(o.life_log),
        autonomousIntent: o.autonomous_intent || '',
        schedule: o.schedule || '',
        currentTask: o.current_task || '',
        detail: o.detail || o.content || '',
        keywords: (o.keywords || '').split(/[,，、\s]+/).map(s => s.trim()).filter(Boolean),
        faction: o.faction || '',
        agenda: o.agenda || '',
        knows_about: (o.knows_about || '').split(/[,，、\n]+/).map(s => s.trim()).filter(Boolean),
      };
      Object.defineProperty(npc, '__present', { value: o.__present || new Set(), enumerable: false });
      return npc;
    });

    // ✅ NPC 关系：from/to/valence（决裂/敌意/好感/不认识/中立）
    const relationBlocks = pwTpExtractBlocks(body, 'relation');
    const npcRelations = relationBlocks.map((b) => {
      const o = pwTpParseBlock(b);
      return {
        from: o.from || o.npc_a || '',
        to: o.to || o.npc_b || '',
        valence: pwNormalizeNpcAttitude(o.valence || o.attitude || o.relation_type || ''),
        relationLevel: o.relation_level != null && o.relation_level !== '' ? o.relation_level : undefined,
        trust: pwTpToOptionalNumber(o.trust),
        intimacy: pwTpToOptionalNumber(o.intimacy),
        fear: pwTpToOptionalNumber(o.fear),
        respect: pwTpToOptionalNumber(o.respect),
        jealousy: pwTpToOptionalNumber(o.jealousy),
        interest: pwTpToOptionalNumber(o.interest),
        dependence: pwTpToOptionalNumber(o.dependence),
        note: o.note || o.detail || '',
      };
    }).filter(r => r.from && r.to);

    const invalidModules = modules.filter(m => !pwTpIsMeaningful(m.id) || !pwTpIsMeaningful(m.title) || !pwTpIsMeaningful(m.detail));
    if (invalidModules.length) {
      log(`[平行世界·解析] 忽略缺少ID、标题或DETAIL的模块：${invalidModules.map(m => m.id || m.title || '未知模块').join(', ')}`);
      modules = modules.filter(m => !invalidModules.includes(m));
    }
    if (!modules.length && !npcs.length) {
      throw new Error('文本协议未解析到任何有效模块块或NPC块');
    }

    return {
      generation_thought: top.think || '',
      world_clock: pwTpFirstContentLine(top.world_clock),
      // 🎲 P2/P3 可选顶层字段（AI 未输出则为空，由引擎兜底）
      time_skip: top.time_skip || '',
      tension_score: top.tension_score || '',
      dice_threshold: top.dice_threshold || '',
      faction_rep_delta: top.faction_rep_delta || '',
      recent_defeat: top.recent_defeat || '',
      selected_ids: pwTpToIdList(top.selected_ids),
      judged_expired_ids: pwTpToIdList(top.judged_expired_ids),
      refill_ids: pwTpToIdList(top.refill_ids),
      invalid_module_ids: invalidModules.map(m => String(m.id || m.title || '未知模块')),
      global_state: {
        title: pwTpFirstContentLine(top.global_title) || '当前世界状态',
        detail: top.global_detail || '',
      },
      modules,
      npcs,
      npc_relations: npcRelations,
      inject_summary: {
        global_summary: top.global_summary || '',
        module_summaries: (() => {
          const byId = new Map(moduleSummaries.filter(s => s?.id).map(s => [String(s.id), s]));
          return modules.map(m => byId.get(String(m.id)) || ({
            id: m.id, type: m.type, title: m.title, summary: m.summary,
            impact_level: m.impact_level,
            progress_enabled: m.progress_enabled, progress: m.progress, progress_note: m.progress_note,
          }));
        })(),
      },
    };
  }

  // 摘要-only 文本协议解析（用于 pwSummarize 重压缩摘要）
  function pwParseTextProtocolSummary(text) {
    const raw = String(text || '');
    if (!raw.trim()) throw new Error('AI 返回空内容');
    const body = pwTpStripFence(raw);

    const summaryBlocks = pwTpExtractBlocks(body, 'summary');
    const topPart = pwTpStripBlocks(body);
    const top = pwTpParseBlock(topPart);

    const moduleSummaries = summaryBlocks.map((b, i) => {
      const o = pwTpParseBlock(b);
      return {
        id: o.id || `summary_${i + 1}`,
        type: o.type || 'other',
        title: o.title || `后台摘要 ${i + 1}`,
        time: o.time || '',
        summary: o.summary || '',
        impact_level: o.impact_level || 'none',
      };
    });

    return {
      global_summary: top.global_summary || '',
      module_summaries: moduleSummaries,
    };
  }

  // 选模块阶段（pwSelectModulesToAdvance）解析
  function pwParseTextProtocolSelect(text) {
    const raw = String(text || '');
    const body = pwTpStripFence(raw);
    const top = pwTpParseBlock(body);
    let ids = [];
    const rawIds = top.selected_ids || '';
    if (rawIds) {
      // 支持 JSON 数组、逗号、换行、顿号、分号分隔
      try {
        const parsed = JSON.parse(rawIds);
        if (Array.isArray(parsed)) ids = parsed.map(x => String(x).trim());
      } catch {}
      if (!ids.length) {
        ids = rawIds
          .split(/[,，;；、\n\r]+/)
          .map(x => x.replace(/^[\-•·\*\d\.\s\[\]"'`]+|[\s\[\]"'`]+$/g, '').trim())
          .filter(Boolean);
      }
    }
    return {
      selected_ids: ids,
      reason: top.reason || '',
      generation_thought: top.think || '',
    };
  }

  // 统一入口：先尝试文本协议，失败再回退到 JSON 提取，确保兼容性
  function pwParseWorldOutput(text) {
    try { return pwParseTextProtocolWorld(text); } catch (protocolError) {
      log('[平行世界] 文本协议解析失败，回退尝试 JSON 解析：', protocolError?.message || protocolError);
      try {
        return pwExtractJson(text);
      } catch (jsonError) {
        throw new Error(`文本协议解析失败：${protocolError?.message || protocolError}；JSON 回退也失败：${jsonError?.message || jsonError}`);
      }
    }
  }
  function pwParseSummaryOutput(text) {
    try { return pwParseTextProtocolSummary(text); } catch (e) {
      log('[平行世界·摘要] 文本协议解析失败，回退尝试 JSON 解析：', e?.message || e);
      return pwExtractJson(text);
    }
  }
  function pwParseSelectOutput(text) {
    try {
      const r = pwParseTextProtocolSelect(text);
      if (r.selected_ids && r.selected_ids.length) return r;
      // selected_ids 为空也允许：但确认确实是文本协议格式（含 # 标签 或 旧 <<< 标签）
      if (/^[ \t]*(?:#{1,3}[ \t]*[^\r\n#<>]+|<{2,}[ \t]*[^\r\n<>]+[ \t]*>{2,})[ \t]*$/m.test(String(text || ''))) return r;
      throw new Error('文本协议无 selected_ids 标签');
    } catch (e) {
      log('[平行世界·选模块] 文本协议解析失败，回退尝试 JSON 解析：', e?.message || e);
      try { return pwExtractJson(text); } catch { return { selected_ids: [], reason: '' }; }
    }
  }

  // 单请求动态推进必须明确输出 SELECTED_IDS。不能把协议损坏误判成“无需推进”。
  function pwParseDynamicSelectOutput(text) {
    const raw = pwTpStripFence(String(text || ''));
    const hasSelectionTag = pwTpScanTags(raw).some(tag => tag.norm === 'selected_ids');
    if (hasSelectionTag) return pwParseTextProtocolSelect(raw);
    try {
      const json = pwExtractJson(raw);
      if (!Object.prototype.hasOwnProperty.call(json || {}, 'selected_ids') && !Object.prototype.hasOwnProperty.call(json || {}, 'selectedIds')) {
        throw new Error('JSON 缺少 selected_ids');
      }
      const selected = json.selected_ids ?? json.selectedIds;
      return {
        selected_ids: Array.isArray(selected) ? selected.map(x => String(x || '').trim()).filter(Boolean) : [],
        reason: String(json.reason || ''),
        generation_thought: String(json.generation_thought || json.generationThought || json.think || ''),
      };
    } catch (e) {
      throw new Error(`AI 响应缺少 SELECTED_IDS，无法确认本轮选择结果：${e?.message || e}`);
    }
  }

  // NPC 对主角看法/关系 5 级归一化：灰(不认识)/白(中立)/绿(好感)/红(敌意)/黑(决裂)
  function pwNormalizeNpcAttitude(raw) {
    const s = String(raw || '').trim();
    if (/不认识|未知|陌生|不熟|不识|unknown|grey|gray|灰/.test(s)) return 'unknown';
    if (/中立|普通|一般|认识|neutral|white|白/.test(s)) return 'neutral';
    if (/好感|喜欢|友好|亲近|信任|感激|friendly|green|绿/.test(s)) return 'friendly';
    if (/敌意|敌视|厌恶|反感|敌对|hostile|red|红/.test(s)) return 'hostile';
    if (/决裂|仇敌|反目|破裂|仇视|死敌|rupture|black|黑/.test(s)) return 'rupture';
    return 'unknown';
  }

  // ✅ NPC 数值化工具（用于 3D 关系网格 + 情绪/看法条）
  // emotionLevel: 0-100，50=平静中点，>50 越积极，<50 越消极，偏离 50 越远强度越大
  function pwClampEmotionLevel(v) {
    let n = v;
    if (typeof n === 'string') n = n.replace(/[^0-9.\-]/g, '');
    // ✅ 修复 Number("")===0 陷阱：纯文本(如"开心")strip 后为空，会误判为 0(崩溃)。
    //    空串/无有效数字时回退到 50(平静中点)，而非 0。
    if (n === '' || n === '-' || !Number.isFinite(Number(n))) n = 50;
    n = Number(n);
    if (!Number.isFinite(n)) n = 50;
    return Math.max(0, Math.min(100, Math.round(n)));
  }

  // attitudeLevel: -1=不认识(灰条未激活)；0-100，0=决裂、<50 敌意区、50=中立、>50 好感区、100=极度亲近
  function pwClampAttitudeLevel(v) {
    if (v == null || v === '') return -1;
    let n = v;
    if (typeof n === 'string') {
      const s = n.trim();
      if (/^-1$|不认识|未知|陌生|不熟|不识|unknown/i.test(s)) return -1;
      n = s.replace(/[^0-9.\-]/g, '');
    }
    // ✅ 修复 Number("")===0 陷阱：纯文本(如"好感")strip 后为空，会误判为 0(决裂)，
    //    并因 hasNewLevel=true 覆盖旧的真实值，把友好 NPC 静默翻成死敌。
    //    空串/无有效数字时回退到 -1(不认识)，绝不误判为决裂。
    if (n === '' || n === '-' || !Number.isFinite(Number(n))) return -1;
    n = Number(n);
    if (!Number.isFinite(n)) return -1;
    if (n < 0) return -1;
    return Math.max(0, Math.min(100, Math.round(n)));
  }

  // relationLevel: 0-100，50=中立，>50 友好，<50 敌对，0=决裂；不认识用 -1
  function pwClampRelationLevel(v) {
    return pwClampAttitudeLevel(v);
  }

  function pwClampNpcMetric(v, fallback = null) {
    if (v == null || v === '') return fallback;
    const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
    return Number.isFinite(n) ? Math.max(0, Math.min(100, Math.round(n))) : fallback;
  }

  function pwNormalizeGoalStatus(v, fallback = 'active') {
    const s = String(v || '').trim().toLowerCase();
    const map = {
      proposed: 'proposed', '未开始': 'proposed', '待定': 'proposed',
      active: 'active', '进行中': 'active', '推进中': 'active',
      waiting: 'waiting', wait: 'waiting', '等待': 'waiting',
      blocked: 'blocked', block: 'blocked', '受阻': 'blocked',
      completed: 'completed', done: 'completed', '已完成': 'completed', '完成': 'completed',
      failed: 'failed', fail: 'failed', '失败': 'failed', '已失败': 'failed',
      abandoned: 'abandoned', drop: 'abandoned', '放弃': 'abandoned', '已放弃': 'abandoned',
      rerouted: 'rerouted', reroute: 'rerouted', '改道': 'rerouted', '已改道': 'rerouted',
      suspended: 'suspended', '暂停': 'suspended',
    };
    return map[s] || fallback;
  }

  function pwMergeBoundedTextList(oldValue, newValue, limit = 8) {
    const toList = (v) => Array.isArray(v) ? v : pwTpToLineList(v);
    const out = [];
    for (const item of [...toList(oldValue), ...toList(newValue)]) {
      const text = pwClip(String(item || '').trim(), 240);
      if (!text || out.some(x => x === text)) continue;
      out.push(text);
    }
    return out.slice(-limit);
  }

  // ✅ 统一的 attitude 文本 -> 默认 attitudeLevel 映射（4 处共用，避免漂移）
  const PW_NPC_ATTITUDE_DEFAULT_LEVEL = { unknown: -1, rupture: 0, hostile: 25, neutral: 50, friendly: 75 };
  function pwAttitudeDefaultLevel(attitude) {
    return PW_NPC_ATTITUDE_DEFAULT_LEVEL[attitude] != null ? PW_NPC_ATTITUDE_DEFAULT_LEVEL[attitude] : -1;
  }

  // 从 attitudeLevel 反推 5 级 attitude（用于节点颜色/标签）
  function pwAttitudeFromLevel(level) {
    if (level == null || level < 0) return 'unknown';
    if (level === 0) return 'rupture';
    if (level < 40) return 'hostile';
    if (level < 60) return 'neutral';
    return 'friendly';
  }

  // 从 attitudeLevel 计算 RGB 渐变颜色（不认识=灰；0 决裂=深黑红；50 中立=白；100 好感=亮绿）
  // 返回形如 'rgb(r,g,b)'
  function pwAttitudeLevelColor(level) {
    if (level == null || level < 0) return 'rgb(136,136,136)'; // 灰
    const lv = Math.max(0, Math.min(100, level));
    if (lv === 0) return 'rgb(40,8,8)'; // 决裂：近黑红
    if (lv < 50) {
      // 0 -> 49：深黑红 -> 橙红 -> 浅红
      const t = lv / 50; // 0..1
      const r = Math.round(40 + (244 - 40) * t);
      const g = Math.round(8 + (67 - 8) * t);
      const b = Math.round(8 + (54 - 8) * t);
      return `rgb(${r},${g},${b})`;
    }
    if (lv === 50) return 'rgb(221,221,221)'; // 中立白
    // 51..100：白 -> 浅绿 -> 亮绿
    const t = (lv - 50) / 50; // 0..1
    const r = Math.round(221 + (76 - 221) * t);
    const g = Math.round(221 + (175 - 221) * t);
    const b = Math.round(221 + (80 - 221) * t);
    return `rgb(${r},${g},${b})`;
  }

  // 从 emotionLevel 计算颜色（50 中点灰蓝，>50 偏暖绿/积极，<50 偏冷红/消极）
  function pwEmotionLevelColor(level) {
    const lv = pwClampEmotionLevel(level);
    if (lv === 50) return 'rgb(120,145,170)';
    if (lv > 50) {
      const t = (lv - 50) / 50;
      const r = Math.round(120 + (76 - 120) * t);
      const g = Math.round(145 + (200 - 145) * t);
      const b = Math.round(170 + (90 - 170) * t);
      return `rgb(${r},${g},${b})`;
    }
    const t = lv / 50;
    const r = Math.round(120 + (244 - 120) * (1 - t));
    const g = Math.round(145 + (80 - 145) * (1 - t));
    const b = Math.round(170 + (70 - 170) * (1 - t));
    return `rgb(${r},${g},${b})`;
  }

  // NPC 长期档案归一化：稳定 ID 优先、精确名称兜底。长期字段采用增量合并，避免漏输出时丢档。
  function pwNormalizeNpcs(rawNpcs, oldNpcs, ctx) {
    const now = new Date().toISOString();
    const oldList = Array.isArray(oldNpcs) ? oldNpcs : [];
    const newList = Array.isArray(rawNpcs) ? rawNpcs : [];
    const result = oldList.map(n => ({ ...n }));
    for (const nn of newList) {
      const name = String(nn.name || '').trim();
      if (!name) continue;
      const incomingId = String(nn.id || '').trim();
      let idx = incomingId ? result.findIndex(n => String(n.id || '') === incomingId) : -1;
      if (idx < 0) idx = result.findIndex(n => String(n.name || '').trim() === name);
      const textAttitude = pwNormalizeNpcAttitude(nn.attitude);
      const hasTextAttitude = String(nn.attitude || '').trim() !== '';
      // ✅ attitudeLevel: AI 输出有效值(含 -1)就采用；没输出(null/undefined/空)就保留旧值；旧值也没有就按文本 attitude 推断默认
      // 兼容驼峰 attitudeLevel 与下划线 attitude_level（JSON 回退路径）
      const rawAttitudeLevel = nn.attitudeLevel != null ? nn.attitudeLevel : nn.attitude_level;
      const hasNewLevel = rawAttitudeLevel != null && rawAttitudeLevel !== '';
      let attitudeLevel;
      if (hasNewLevel) {
        attitudeLevel = pwClampAttitudeLevel(rawAttitudeLevel);
      } else if (idx >= 0 && result[idx].attitudeLevel != null) {
        attitudeLevel = result[idx].attitudeLevel;
      } else {
        // 🎲 P3 首次出现且无数值：优先用所属势力声望作基线，否则按文本 attitude 给默认值
        const faction = String(nn.faction || nn.faction_name || '').trim();
        const fb = faction ? pwFactionBaselineAttitude(ctx, faction) : null;
        attitudeLevel = (fb != null) ? fb : pwAttitudeDefaultLevel(textAttitude);
      }
      // attitude 标签：优先由数值反推（更精确），文本仅兜底
      const attitude = hasNewLevel
        ? pwAttitudeFromLevel(attitudeLevel)
        : (hasTextAttitude ? textAttitude : (idx >= 0 ? result[idx].attitude || pwAttitudeFromLevel(attitudeLevel) : textAttitude));
      // ✅ emotionLevel: AI 输出有效值就采用；没输出保留旧值；都没有默认 50
      const rawEmotionLevel = nn.emotionLevel != null ? nn.emotionLevel : nn.emotion_level;
      const hasNewEmotion = rawEmotionLevel != null && rawEmotionLevel !== '';
      const emotionLevel = hasNewEmotion
        ? pwClampEmotionLevel(rawEmotionLevel)
        : (idx >= 0 && result[idx].emotionLevel != null ? result[idx].emotionLevel : 50);
      // 🎲 P3 势力/议程/知情度（字符串/数组归一化）
      const faction = String(nn.faction || nn.faction_name || '');
      const agenda = String(nn.agenda || '');
      const knowsAbout = (() => {
        const src = nn.knows_about || nn.knowsAbout;
        if (Array.isArray(src)) return src.map(String).filter(Boolean);
        return String(src || '').split(/[,，、\n]+/).map(s => s.trim()).filter(Boolean);
      })();
      const oldNpc = idx >= 0 ? result[idx] : {};
      const health = pwClampNpcMetric(nn.health, oldNpc.health ?? null);
      const fatigue = pwClampNpcMetric(nn.fatigue, oldNpc.fatigue ?? null);
      const standingLevel = pwClampNpcMetric(nn.standingLevel ?? nn.standing_level, oldNpc.standingLevel ?? null);
      const goalStatus = pwNormalizeGoalStatus(nn.goalStatus || nn.goal_status, oldNpc.goalStatus || 'active');
      const goalProgress = pwClampNpcMetric(nn.goalProgress ?? nn.goal_progress, oldNpc.goalProgress ?? 0);
      const longGoalIncoming = String(nn.longTermGoal || nn.long_term_goal || '').trim();
      const goalChangeReason = String(nn.goalChangeReason || nn.goal_change_reason || '').trim();
      const longTermGoal = longGoalIncoming && oldNpc.longTermGoal && longGoalIncoming !== oldNpc.longTermGoal && !goalChangeReason
        ? oldNpc.longTermGoal
        : (longGoalIncoming || oldNpc.longTermGoal || '');
      const present = nn.__present instanceof Set ? nn.__present : null;
      const replaceListIfPresent = (current, incoming, field, limit) => {
        const camel = field.replace(/_([a-z])/g, (_, c) => c.toUpperCase());
        if ((present && present.has(field)) || Object.prototype.hasOwnProperty.call(nn, camel) || Object.prototype.hasOwnProperty.call(nn, field)) {
          return pwMergeBoundedTextList([], incoming, limit);
        }
        return pwMergeBoundedTextList(current, incoming, limit);
      };
      if (idx >= 0) {
        result[idx].emotion = String(nn.emotion || result[idx].emotion || '');
        result[idx].emotionLevel = emotionLevel;
        result[idx].attitude = attitude;
        result[idx].attitudeLevel = attitudeLevel;
        result[idx].location = String(nn.location || result[idx].location || '');
        result[idx].status = String(nn.status || result[idx].status || '');
        result[idx].goals = String(nn.goals || result[idx].goals || '');
        result[idx].currentThought = String(nn.currentThought || nn.current_thought || result[idx].currentThought || '');
        result[idx].shortTermGoal = String(nn.shortTermGoal || nn.short_term_goal || result[idx].shortTermGoal || result[idx].goals || '');
        result[idx].longTermGoal = longTermGoal;
        result[idx].goalChangeReason = goalChangeReason || result[idx].goalChangeReason || '';
        result[idx].health = health;
        result[idx].healthNote = String(nn.healthNote || nn.health_note || result[idx].healthNote || '');
        result[idx].fatigue = fatigue;
        result[idx].fatigueNote = String(nn.fatigueNote || nn.fatigue_note || result[idx].fatigueNote || '');
        result[idx].standing = String(nn.standing || result[idx].standing || '');
        result[idx].standingLevel = standingLevel;
        result[idx].standingNote = String(nn.standingNote || nn.standing_note || result[idx].standingNote || '');
        result[idx].goalStatus = goalStatus;
        result[idx].goalProgress = goalProgress;
        result[idx].goalProgressNote = String(nn.goalProgressNote || nn.goal_progress_note || result[idx].goalProgressNote || '');
        for (const key of ['goalPriority', 'goalUrgency', 'goalImportance', 'goalRisk', 'goalCost']) {
          result[idx][key] = pwClampNpcMetric(nn[key] ?? nn[key.replace(/[A-Z]/g, m => `_${m.toLowerCase()}`)], result[idx][key] ?? 50);
        }
        result[idx].goalObstacle = String(nn.goalObstacle || nn.goal_obstacle || result[idx].goalObstacle || '');
        result[idx].goalOutcome = String(nn.goalOutcome || nn.goal_outcome || result[idx].goalOutcome || '');
        result[idx].activeGoalReason = String(nn.activeGoalReason || nn.active_goal_reason || result[idx].activeGoalReason || '');
        result[idx].confirmedFacts = replaceListIfPresent(result[idx].confirmedFacts, nn.confirmedFacts || nn.confirmed_facts, 'confirmed_facts', 10);
        result[idx].rumors = replaceListIfPresent(result[idx].rumors, nn.rumors, 'rumors', 8);
        result[idx].assumptions = replaceListIfPresent(result[idx].assumptions, nn.assumptions, 'assumptions', 8);
        result[idx].falseBeliefs = replaceListIfPresent(result[idx].falseBeliefs, nn.falseBeliefs || nn.false_beliefs, 'false_beliefs', 6);
        result[idx].deniedFacts = replaceListIfPresent(result[idx].deniedFacts, nn.deniedFacts || nn.denied_facts, 'denied_facts', 6);
        result[idx].commitments = replaceListIfPresent(result[idx].commitments, nn.commitments, 'commitments', 6);
        result[idx].debts = replaceListIfPresent(result[idx].debts, nn.debts, 'debts', 6);
        result[idx].secrets = replaceListIfPresent(result[idx].secrets, nn.secrets, 'secrets', 6);
        result[idx].lifeLog = pwMergeBoundedTextList(result[idx].lifeLog, nn.lifeLog || nn.life_log, 8);
        result[idx].autonomousIntent = String(nn.autonomousIntent || nn.autonomous_intent || result[idx].autonomousIntent || '');
        result[idx].schedule = String(nn.schedule || result[idx].schedule || '');
        result[idx].currentTask = String(nn.currentTask || nn.current_task || result[idx].currentTask || '');
        result[idx].detail = String(nn.detail || result[idx].detail || '');
        result[idx].keywords = [...new Set([...(result[idx].keywords || []), ...(nn.keywords || [])])].filter(Boolean);
        if (faction) result[idx].faction = faction;
        if (agenda) result[idx].agenda = agenda;
        if (knowsAbout.length) result[idx].knowsAbout = knowsAbout;
        result[idx].updatedAt = now;
      } else {
        result.push({
          id: String(nn.id || `npc_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`),
          name,
          emotion: String(nn.emotion || ''),
          emotionLevel,
          attitude,
          attitudeLevel,
          location: String(nn.location || ''),
          status: String(nn.status || ''),
          goals: String(nn.goals || ''),
          currentThought: String(nn.currentThought || nn.current_thought || ''),
          shortTermGoal: String(nn.shortTermGoal || nn.short_term_goal || nn.goals || ''),
          longTermGoal,
          goalChangeReason,
          health,
          healthNote: String(nn.healthNote || nn.health_note || ''),
          fatigue,
          fatigueNote: String(nn.fatigueNote || nn.fatigue_note || ''),
          standing: String(nn.standing || ''),
          standingLevel,
          standingNote: String(nn.standingNote || nn.standing_note || ''),
          goalStatus,
          goalProgress,
          goalProgressNote: String(nn.goalProgressNote || nn.goal_progress_note || ''),
          goalPriority: pwClampNpcMetric(nn.goalPriority ?? nn.goal_priority, 50),
          goalUrgency: pwClampNpcMetric(nn.goalUrgency ?? nn.goal_urgency, 50),
          goalImportance: pwClampNpcMetric(nn.goalImportance ?? nn.goal_importance, 50),
          goalRisk: pwClampNpcMetric(nn.goalRisk ?? nn.goal_risk, 50),
          goalCost: pwClampNpcMetric(nn.goalCost ?? nn.goal_cost, 50),
          goalObstacle: String(nn.goalObstacle || nn.goal_obstacle || ''),
          goalOutcome: String(nn.goalOutcome || nn.goal_outcome || ''),
          activeGoalReason: String(nn.activeGoalReason || nn.active_goal_reason || ''),
          confirmedFacts: pwMergeBoundedTextList([], nn.confirmedFacts || nn.confirmed_facts, 10),
          rumors: pwMergeBoundedTextList([], nn.rumors, 8),
          assumptions: pwMergeBoundedTextList([], nn.assumptions, 8),
          falseBeliefs: pwMergeBoundedTextList([], nn.falseBeliefs || nn.false_beliefs, 6),
          deniedFacts: pwMergeBoundedTextList([], nn.deniedFacts || nn.denied_facts, 6),
          commitments: pwMergeBoundedTextList([], nn.commitments, 6),
          debts: pwMergeBoundedTextList([], nn.debts, 6),
          secrets: pwMergeBoundedTextList([], nn.secrets, 6),
          lifeLog: pwMergeBoundedTextList([], nn.lifeLog || nn.life_log, 8),
          autonomousIntent: String(nn.autonomousIntent || nn.autonomous_intent || ''),
          schedule: String(nn.schedule || ''),
          currentTask: String(nn.currentTask || nn.current_task || ''),
          detail: String(nn.detail || ''),
          keywords: Array.isArray(nn.keywords) ? nn.keywords.filter(Boolean) : [],
          faction,
          agenda,
          knowsAbout,
          createdAt: now,
          updatedAt: now,
        });
      }
    }
    return result;
  }

  // NPC 关系归一化：关系有方向，A 对 B 与 B 对 A 可不同；旧总刻度继续保留兼容。
  // ✅ 不能覆盖式清空：动态/单条推进提示词允许"无变化不输出关系块"，
  //    覆盖会导致单次推进未提关系时全部关系丢失。
  function pwNormalizeNpcRelations(rawRelations, oldRelations) {
    const now = new Date().toISOString();
    const newList = Array.isArray(rawRelations) ? rawRelations : [];
    const oldList = Array.isArray(oldRelations) ? oldRelations : [];
    const result = oldList.map(r => ({ ...r }));
    for (const nr of newList) {
      const from = String(nr.from || '').trim();
      const to = String(nr.to || '').trim();
      if (!from || !to) continue;
      const idx = result.findIndex(r => {
        const rf = String(r.from || '').trim();
        const rt = String(r.to || '').trim();
        return rf === from && rt === to;
      });
      const textValence = pwNormalizeNpcAttitude(nr.valence);
      const rawRelationLevel = nr.relationLevel != null ? nr.relationLevel : nr.relation_level;
      const hasNewLevel = rawRelationLevel != null && rawRelationLevel !== '';
      let relationLevel;
      if (hasNewLevel) {
        relationLevel = pwClampRelationLevel(rawRelationLevel);
      } else if (idx >= 0 && result[idx].relationLevel != null) {
        relationLevel = result[idx].relationLevel;
      } else {
        relationLevel = pwAttitudeDefaultLevel(textValence);
      }
      const hasTextValence = String(nr.valence || '').trim() !== '';
      const valence = hasNewLevel ? pwAttitudeFromLevel(relationLevel) : (hasTextValence ? textValence : (idx >= 0 ? result[idx].valence : textValence));
      const dimensions = {};
      for (const key of ['trust', 'intimacy', 'fear', 'respect', 'jealousy', 'interest', 'dependence']) {
        const raw = nr[key];
        dimensions[key] = pwClampNpcMetric(raw, idx >= 0 ? result[idx][key] ?? null : null);
      }
      if (idx >= 0) {
        result[idx].valence = valence;
        result[idx].relationLevel = relationLevel;
        result[idx].note = String(nr.note || result[idx].note || '');
        Object.assign(result[idx], dimensions);
        result[idx].updatedAt = now;
      } else {
        result.push({ from, to, valence, relationLevel, ...dimensions, note: String(nr.note || ''), updatedAt: now });
      }
    }
    return result;
  }

  // 🎯 Task 2: NPC档案强制更新校验
  // 比对 oldData.npcs 与 AI 输出的 parsed.npcs，检测哪些旧 NPC 被遗漏；
  // 整轮模式要求全部旧 NPC 都被更新，动态推进模式仅检查被推进事件涉及的 NPC。
  // 输出诊断日志并 toast 提示用户更新状态，不阻断保存（归一化层会自动补齐旧值）。
  function pwAuditNpcArchiveUpdate(parsed, oldData, mode) {
    try {
      const oldNpcs = Array.isArray(oldData?.npcs) ? oldData.npcs : [];
      const newNpcs = Array.isArray(parsed?.npcs) ? parsed.npcs : [];
      if (!oldNpcs.length) return; // 首轮无旧档案，跳过

      const newNameSet = new Set(newNpcs.map(n => String(n.name || '').trim()).filter(Boolean));
      const newNameLowerSet = new Set([...newNameSet].map(n => n.toLowerCase()));

      // 整轮：检查全部旧 NPC；动态推进：仅检查被推进事件 linked_npc_ids 涉及的 NPC
      let checklist = oldNpcs;
      if (mode === '动态推进') {
        const linkedNames = new Set();
        for (const m of (parsed?.modules || [])) {
          const ids = m.linked_npc_ids || m.linkedNpcIds || [];
          if (Array.isArray(ids)) ids.forEach(id => linkedNames.add(String(id || '').trim()));
        }
        checklist = oldNpcs.filter(n => linkedNames.has(String(n.name || '').trim()));
        if (!checklist.length) return; // 本轮事件不涉及任何已知 NPC
      }

      const missing = checklist.filter(n => {
        const name = String(n.name || '').trim();
        if (!name) return false;
        return !newNameSet.has(name) && !newNameLowerSet.has(name.toLowerCase());
      });
      const updatedCount = checklist.length - missing.length;

      if (missing.length) {
        const names = missing.map(n => String(n.name || '').trim()).slice(0, 8).join('、');
        const suffix = missing.length > 8 ? ` 等${missing.length}个` : '';
        log(`[平行世界·${mode}] NPC档案更新校验：${updatedCount}/${checklist.length} 已更新，遗漏 ${missing.length} 个 [${names}${suffix}]，归一化层已自动保留旧值`);
        try { toast(`⚠️ 平行世界·${mode}：${missing.length} 个NPC档案未被AI更新（${names}${suffix}），已自动保留旧值`, 'warning'); } catch {}
      } else {
        log(`[平行世界·${mode}] NPC档案更新校验通过：${updatedCount}/${checklist.length} 个NPC均已更新`);
        // 静默通过时不弹 toast，避免刷屏；仅在整轮全部通过且数量较多时给一次正向反馈
        if (mode === '整轮' && checklist.length >= 3) {
          try { toast(`✅ 平行世界：${updatedCount} 个NPC档案已全部更新`, 'success'); } catch {}
        }
      }
    } catch (e) {
      log(`[平行世界·${mode}] NPC档案更新校验异常：`, e?.message || e);
    }
  }

  // ==================== 🕰️ 平行世界时间对齐：狐刻同步 + 独立解析 ====================
  // 问题：平行世界的 worldClock 由 AI 自由生成，每轮推进时容易跑得比正文快。
  // 方案：狐刻启用时，用狐刻解析的结构化时钟同步到 PW；狐刻未启用时，
  //       PW 从最新 AI 楼层正文自行解析时间（简化版狐刻正则），保持对齐。

  // 获取狐刻时钟标签（仅狐刻启用且时钟已知时返回）
  function pwGetFoxTimeClockLabel() {
    try {
      const ftCfg = (typeof ftState !== 'undefined' && ftState.config) || (typeof ftLoadConfig === 'function' && ftLoadConfig());
      if (!ftCfg || !ftCfg.enabled) return null;
      const d = (typeof ftState !== 'undefined' && ftState.data) || (typeof ftLoadData === 'function' && ftLoadData());
      if (!d || !d.clock || d.clock.unknown) return null;
      return typeof ftClockLabel === 'function' ? ftClockLabel(d.clock) : null;
    } catch { return null; }
  }

  // 狐刻未启用时，从最新 AI 楼层正文独立解析时间（简化版 ftRegexExtract）
  // 解析优先级：▶ 箭头行 > <ft_clock> 标签 > 【时间：…】格式
  function pwParseStandaloneClock() {
    try {
      const msgs = getChatMessages(-1, { role: 'assistant' });
      if (!msgs || !msgs.length) return null;
      let text = msgs[0].message || '';
      if (!text) return null;
      // HTML 实体解码，确保标签可匹配
      text = text.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');

      let day = null, minute = null;

      // 优先级 1: ▶ 箭头行（取箭头后的目标时间）
      const arrowLine = text.match(/▶[^\n]+/);
      if (arrowLine) {
        const times = [...arrowLine[0].matchAll(/(\d{1,2})[:：](\d{2})/g)];
        const dayInLine = arrowLine[0].match(/第(\d+)天/);
        if (times.length >= 1) {
          const last = times[times.length - 1];
          day = dayInLine ? parseInt(dayInLine[1]) : 1;
          minute = parseInt(last[1]) * 60 + parseInt(last[2]);
        }
      }

      // 优先级 2: <ft_clock day="X" minute="Y" /> 标签
      if (day === null) {
        const clockTag = text.match(/<ft_clock\s+day=["']?(\d+)["']?\s+minute=["']?(\d+)["']?\s*\/?>/i);
        if (clockTag) {
          day = parseInt(clockTag[1]);
          minute = parseInt(clockTag[2]);
        }
      }

      // 优先级 3: 【时间：…】/ 当前时间：… / 时间：…
      if (day === null) {
        const timeBracket = text.match(/(?:【时间[：:]|当前时间[：:]|时间[：:])([^】\n]+)/);
        if (timeBracket) {
          const t = timeBracket[1].trim();
          const dayMatch = t.match(/第(\d+)天/);
          const hmMatch = t.match(/(\d{1,2}):(\d{2})/);
          if (dayMatch || hmMatch) {
            day = dayMatch ? parseInt(dayMatch[1]) : 1;
            minute = hmMatch ? parseInt(hmMatch[1]) * 60 + parseInt(hmMatch[2]) : 0;
          }
        }
      }

      if (day !== null && minute !== null) {
        day = Math.max(1, day);
        minute = Math.min(1439, Math.max(0, minute));
        const hh = String(Math.floor(minute / 60)).padStart(2, '0');
        const mm = String(minute % 60).padStart(2, '0');
        return `第${day}天 ${hh}:${mm}`;
      }
      return null;
    } catch { return null; }
  }

  // 统一获取同步后的时钟标签（优先狐刻，其次独立解析，均失败返回 null）
  function pwGetSyncedClockLabel() {
    const ftLabel = pwGetFoxTimeClockLabel();
    if (ftLabel) return ftLabel;
    return pwParseStandaloneClock();
  }

  // 获取时间约束文本（用于 PW 提示词注入）
  // 狐刻启用且有 pwGate 时用狐刻软约束；否则用独立解析的时间约束
  function pwGetTimeConstraintText() {
    // 1. 狐刻软约束（狐刻启用且 pwGate 开启时由 ftGetPwSoftConstraintText 返回）
    try {
      if (typeof ftGetPwSoftConstraintText === 'function') {
        const ftText = ftGetPwSoftConstraintText();
        if (ftText) return ftText;
      }
    } catch {}
    // 2. 狐刻启用但 pwGate 关闭：用狐刻时钟做简单约束
    const ftLabel = pwGetFoxTimeClockLabel();
    if (ftLabel) {
      return `【时间对齐·约束】当前剧情时间：${ftLabel}（来源：狐刻）。所有生成内容必须在此时间点之后，禁止时间倒流。world_clock 必须基于此时间推进，禁止大幅跳越。`;
    }
    // 3. 狐刻未启用：用独立解析的时间约束
    const standaloneLabel = pwParseStandaloneClock();
    if (standaloneLabel) {
      return `【时间对齐·约束】当前剧情时间：${standaloneLabel}（来源：正文解析）。所有生成内容必须在此时间点之后，禁止时间倒流。world_clock 必须基于此时间推进，禁止大幅跳越。`;
    }
    return '';
  }

  function pwNormalizeWorldResult(obj, oldData) {
    const now = new Date().toISOString();
    const old = oldData || pwLoadData();
    obj = obj && typeof obj === 'object' ? obj : {};

    const modules = Array.isArray(obj.modules) ? obj.modules.filter(m => m && typeof m === 'object') : [];
    const injectObj = obj.inject_summary || obj.inject || {};

    const normalizedModules = modules.map((m, i) => ({
      id: String(m.id || `module_${i + 1}`),
      type: String(m.type || 'other'),
      title: String(m.title || `后台镜头 ${i + 1}`),
      roleAudit: String(m.role_audit || m.roleAudit || ''),
      detail: pwLimitEventDetail(m.detail || m.content || ''),
      independence: String(m.independence || ''),
      impactLevel: pwNormalizeImpactLevel(m.impact_level || m.impactLevel || m.danger_level || m.dangerLevel || 'none', 'none'),
      progressEnabled: m.progress_enabled === true || m.progressEnabled === true,
      progress: pwClampProgress(m.progress ?? m.progress_percent ?? m.progressPercent ?? 0),
      progressNote: String(m.progress_note || m.progressNote || ''),
      perspective: String(m.perspective || m.viewpoint || m.point_of_view || ''),
      currentLocation: String(m.current_location || m.currentLocation || ''),
      currentState: String(m.current_state || m.currentState || ''),
      nextTendency: String(m.next_tendency || m.nextTendency || ''),
      dangerLevel: String(m.danger_level || m.dangerLevel || ''),
      linkedNpcIds: Array.isArray(m.linked_npc_ids || m.linkedNpcIds) ? (m.linked_npc_ids || m.linkedNpcIds).map(String).filter(pwTpIsMeaningful) : [],
      origin: String(m.origin || ''),
      initiatorNpcIds: Array.isArray(m.initiator_npc_ids || m.initiatorNpcIds) ? (m.initiator_npc_ids || m.initiatorNpcIds).map(String).filter(pwTpIsMeaningful) : [],
      sourceGoal: pwTpIsMeaningful(m.source_goal || m.sourceGoal) ? String(m.source_goal || m.sourceGoal) : '',
      sourceStake: pwTpIsMeaningful(m.source_stake || m.sourceStake) ? String(m.source_stake || m.sourceStake) : '',
      initiativeReason: pwTpIsMeaningful(m.initiative_reason || m.initiativeReason) ? String(m.initiative_reason || m.initiativeReason) : '',
      isDiceEvent: m.is_dice_event === true || m.isDiceEvent === true,
      diceOutcome: String(m.dice_outcome || m.diceOutcome || ''),
      diceRoll: pwClampNpcMetric(m.dice_roll ?? m.diceRoll, null),
      diceThreshold: pwClampNpcMetric(m.dice_threshold ?? m.diceThreshold, null),
      diceTension: pwClampNpcMetric(m.dice_tension ?? m.diceTension, null),
      diceTurn: Number.isFinite(Number(m.dice_turn ?? m.diceTurn)) ? Number(m.dice_turn ?? m.diceTurn) : null,
      diceSeverity: String(m.dice_severity || m.diceSeverity || ''),
      diceStoryteller: String(m.dice_storyteller || m.diceStoryteller || ''),
      remainingTurns: Number.isFinite(Number(m.remaining_turns ?? m.remainingTurns)) ? Number(m.remaining_turns ?? m.remainingTurns) : undefined,
      lifecycleState: String(m.lifecycle_state || m.lifecycleState || ''),
      creationReason: String(m.creation_reason || m.creationReason || ''),
      updatedAt: now,
    }));

    // 🎲 P2 生命周期字段：合并 AI 输出 + 旧模块延续，归一化 status/duration/tensionMeta/连锁
    const oldModMap = new Map((Array.isArray(old.modules) ? old.modules : []).map(m => [String(m.id), m]));
    const rawModMap = new Map(modules.map(m => [String(m.id || ''), m]));
    const newTurn = Number(old.turn || 0) + 1;
    for (const m of normalizedModules) {
      const om = oldModMap.get(String(m.id));
      const rm = rawModMap.get(String(m.id)) || {};
      if (om) {
        if (!m.tensionMeta) m.tensionMeta = om.tensionMeta;
        if (!m.parentEventId) m.parentEventId = om.parentEventId;
        if (m.chainStep == null) m.chainStep = om.chainStep;
      }
      if (rm.parent_event_id) m.parentEventId = String(rm.parent_event_id);
      pwNormalizeModuleLifecycle(m, om, newTurn);
    }

    const moduleMap = new Map(normalizedModules.map(m => [m.id, m]));

    const rawSummaries = Array.isArray(injectObj.module_summaries)
      ? injectObj.module_summaries.filter(s => s && typeof s === 'object')
      : normalizedModules.map(m => ({
        id: m.id,
        type: m.type,
        title: m.title,
        summary: pwClip(m.detail || m.currentState || m.nextTendency || '', pwSummaryRangeMaxChars()),
        impact_level: m.impactLevel || m.dangerLevel || 'none',
      }));

    const moduleSummaries = rawSummaries.map((s, i) => {
      const id = String(s.id || normalizedModules[i]?.id || `summary_${i + 1}`);
      const mod = moduleMap.get(id) || normalizedModules[i] || {};

      return {
        id,
        type: String(s.type || mod.type || 'other'),
        title: String(s.title || mod.title || `后台摘要 ${i + 1}`),
        summary: pwClip(mod.detail || s.summary || mod.currentState || mod.nextTendency || '', pwSummaryRangeMaxChars()),
        impactLevel: pwNormalizeImpactLevel(s.impact_level || s.impactLevel || mod.impactLevel || mod.dangerLevel || 'none', 'none'),
        progressEnabled: s.progress_enabled === true || s.progressEnabled === true || mod.progressEnabled === true,
        progress: pwClampProgress(s.progress ?? s.progress_percent ?? s.progressPercent ?? mod.progress ?? 0),
        progressNote: String(s.progress_note || s.progressNote || mod.progressNote || ''),
        dangerLevel: pwNormalizeImpactLevel(s.danger_level || s.dangerLevel || mod.dangerLevel || '', ''),
        time: String(s.time || ''),
        isDiceEvent: s.is_dice_event === true || s.isDiceEvent === true || mod.isDiceEvent === true,
        diceOutcome: String(s.dice_outcome || s.diceOutcome || mod.diceOutcome || ''),
      };
    });

    return {
      version: 2,
      cleared: false,
      turn: Number(old.turn || 0) + 1,
      // 🕰️ 时间对齐：优先用狐刻/独立解析的同步时间覆盖 AI 生成的 worldClock，
      //    防止平行世界时间跑得比正文快。同步失败时回退到 AI 生成值或轮次占位。
      worldClock: (() => {
        const synced = pwGetSyncedClockLabel();
        if (synced) return synced;
        return String(obj.world_clock || obj.worldClock || `主线最新事件后的后台第 ${Number(old.turn || 0) + 1} 轮`);
      })(),
      globalState: {
        title: String(obj.global_state?.title || obj.globalTitle || '当前世界状态'),
        // ✅ 兜底链里禁止把 obj.global_state（一个对象）丢给 String()——
        //    那样会得到 "[object Object]" 显示在面板下拉栏。
        //    只接受字符串字段，object 全部跳过。
        detail: String(
          (typeof obj.global_state?.detail === 'string' ? obj.global_state.detail : '') ||
          (typeof obj.globalDetail === 'string' ? obj.globalDetail : '') ||
