  function pwNormalizeSummaryResult(obj, data) {
    const now = new Date().toISOString();

    const summaries = Array.isArray(obj.module_summaries)
      ? obj.module_summaries
      : Array.isArray(obj.modules)
        ? obj.modules
        : [];

    const moduleLookup = new Map(
      (data.modules || []).map(m => [String(m.id || ''), m])
    );

    const normalized = summaries.map((m, i) => {
      const id = String(m.id || data.modules?.[i]?.id || `summary_${i + 1}`);
      const oldModule = moduleLookup.get(id) || data.modules?.[i] || {};

      return {
        id,
        type: String(m.type || oldModule.type || 'other'),
        title: String(m.title || oldModule.title || `后台摘要 ${i + 1}`),
        summary: String(m.summary || m.content || ''),
        impactLevel: pwNormalizeImpactLevel(m.impact_level || m.impactLevel || oldModule.impactLevel || oldModule.dangerLevel || 'none', 'none'),
        progressEnabled: m.progress_enabled === true || m.progressEnabled === true || oldModule.progressEnabled === true,
        progress: pwClampProgress(m.progress ?? m.progress_percent ?? m.progressPercent ?? oldModule.progress ?? 0),
        progressNote: String(m.progress_note || m.progressNote || oldModule.progressNote || ''),
        dangerLevel: pwNormalizeImpactLevel(m.danger_level || m.dangerLevel || oldModule.dangerLevel || '', ''),
        time: String(m.time || data.worldClock || ''),
      };
    });

    const map = new Map(normalized.map(x => [x.id, x]));

    return {
      ...data,
      cleared: false,
      modules: (data.modules || []).map(m => {
        const s = map.get(m.id);
        if (!s) return m;

        return {
          ...m,
          impactLevel: pwNormalizeImpactLevel(s.impactLevel || m.impactLevel || 'none', 'none'),
          progressEnabled: s.progressEnabled === true || m.progressEnabled === true,
          progress: pwClampProgress(s.progress ?? m.progress ?? 0),
          progressNote: s.progressNote || m.progressNote || '',
          updatedAt: now,
        };
      }),
      inject: {
        global_summary: String(obj.global_summary || obj.globalSummary || ''),
        module_summaries: normalized,
        manual_text: data.inject?.manual_text || '',
      },
      updatedAt: now,
    };
  }


