          assumptions: (n.assumptions || []).slice(-4), falseBeliefs: (n.falseBeliefs || []).slice(-3), deniedFacts: (n.deniedFacts || []).slice(-3),
          commitments: (n.commitments || []).slice(-4), debts: (n.debts || []).slice(-4), secrets: (n.secrets || []).slice(-3),
          lifeLog: (n.lifeLog || []).slice(-4), autonomousIntent: pwClip(n.autonomousIntent, 120),
          schedule: pwClip(n.schedule, 120),
