  function pwBuildCustomApi() {
    const c = pwState.config || pwLoadConfig();

    if (c.apiType !== 'custom') return null;

    const ca = c.customApi || {};

    // 🦊 与狐裁/狐忆/狐搜同款守卫：自定义 API 必须提供 apiurl 或 proxyPreset，
    //    否则宿主 generateRaw 不会把 chat_completion_source 切到 'custom'，
    //    只填模型名会被静默忽略 → 平行世界仍走主模型（本次修复的 BUG 根因）。
    if (!ca.apiurl && !ca.proxyPreset) return null;

    const customApi = {
      source: ca.source || 'openai',
    };

    if (ca.proxyPreset) {
      customApi.proxy_preset = ca.proxyPreset;
    } else {
      if (ca.apiurl) customApi.apiurl = ca.apiurl;
      if (ca.key) customApi.key = ca.key;
    }

    if (ca.model) customApi.model = ca.model;

    if (ca.temperature !== '' && !isNaN(parseFloat(ca.temperature))) {
      customApi.temperature = parseFloat(ca.temperature);
    }

    if (ca.max_tokens !== '' && !isNaN(parseInt(ca.max_tokens))) {
      customApi.max_tokens = parseInt(ca.max_tokens);
    }

    if (ca.top_p !== '' && !isNaN(parseFloat(ca.top_p))) {
      customApi.top_p = parseFloat(ca.top_p);
    }

    if (ca.frequency_penalty !== '' && !isNaN(parseFloat(ca.frequency_penalty))) {
      customApi.frequency_penalty = parseFloat(ca.frequency_penalty);
    }

    if (ca.presence_penalty !== '' && !isNaN(parseFloat(ca.presence_penalty))) {
      customApi.presence_penalty = parseFloat(ca.presence_penalty);
    }

    return customApi;
  }

  // 🦊 平行世界附加参数：根据 c.customApi 中的 YAML 文本构建 fetch hook inject。
  //    仅在 apiType === 'custom' 时生效，避免误污染主模型请求。
  function pwBuildExtraInject() {
    const c = pwState.config || pwLoadConfig();
    if (c.apiType !== 'custom') return null;
    return ssBuildExtraInjectFromCustomApi(c.customApi || {});
  }

  // 🏷️ 平行世界固定上下文构建：
  // - 启用标签过滤时（enableContentFilter !== false）：复用狐构/狐忆同款
  //   ssBuildFilteredChatHistoryPromptsForAnalysis，把 chat_history 展开成已过滤掉指定标签内容的
  //   逐楼 message prompts。即使 includeTagPairs/excludeTagPairs 都是空数组也走过滤路径，
  //   ssFilterByTagPairs 在两者都空时等价于"读取全文"，行为可预期。
  // - 关闭标签过滤时：仍然走原生 'chat_history'，由酒馆自己处理。
  //
  // ⚠️ 注：标签过滤启用时，host 的 max_chat_history 不再生效（chat_history token 没了）。
  //   楼层数量改由 pwResolveChatHistoryLimit() 映射到 contextFloors 控制，最近 N 楼的语义略有
  //   差异：host 的 max_chat_history 按 user/assistant 配对计数；contextFloors 按总楼层计数。
  // ✅ 跨模块联动补充：把狐构大纲/狐搜资料注入平行世界生成，形成模块联动
  function pwBuildLinkedSupplementPrompt() {
    try {
      if (typeof ssBuildParallelWorldLinkedSupplementPrompt === 'function') {
        return ssBuildParallelWorldLinkedSupplementPrompt();
      }
    } catch (e) {
      log('[平行世界·联动] 获取跨模块补充失败', e?.message || e);
    }
    return null;
  }

  function pwBuildFoxMemorySupplementPrompt() {
    try {
      const memoryConfig = loadFoxMemoryConfig();
      const data = loadFoxMemory();
      const queryText = foxMemoryGetRecentTextForPlotRelevance(memoryConfig?.recallFloors || 8);
      const body = foxMemoryBuildMemoryBodyForInject(data.memories || [], {
        queryText,
        profile: 'advance',
        charBudget: 999999,
        maxAtoms: 12,
        keywordFilterByContext: true,
      });
      const profileBody = memoryConfig?.cognitionArchEnabled
        ? foxMemoryBuildProfileInjectBody(queryText)
        : '';
      const fullBody = [body, profileBody].filter(Boolean).join('\n\n');
      if (!fullBody || fullBody === '（暂无回忆内容）') return '';
      return { role: 'system', content: ssBuildFoxMemoryInject(fullBody) };
    } catch (e) {
      log('[平行世界·狐忆联动] 构建失败', e?.message || e);
      return '';
    }
  }

  // 平行世界只把明确的长期字段同步到共享档案；位置、情绪、伤势、短期任务等动态信息禁写。
  function pwSyncStableNpcProfilesToFoxProfile(data) {
    try {
      const cfg = loadFoxMemoryConfig();
      if (!cfg?.cognitionArchEnabled) return 0;
      const memory = loadFoxMemory();
      const trusted = new Set(Object.keys(memory.characterProfiles || {}).map(name => name.toLowerCase()));
      let changed = 0;
      for (const npc of Array.isArray(data?.npcs) ? data.npcs : []) {
        const name = foxMemoryCanonicalCharacterName(npc?.name);
        if (!foxMemoryIsPlausibleCharacterName(name)) continue;
        const hasStableEvidence = String(npc?.longTermGoal || '').trim();
        if (!hasStableEvidence && !trusted.has(name.toLowerCase())) continue;
        const profile = foxMemoryGetOrCreateProfile(memory, name, false);
        if (!profile) continue;
        let profileChanged = false;
        const longGoal = String(npc?.longTermGoal || '').trim();
        if (longGoal && profile.cognition.goal !== longGoal) {
          profile.cognition.goal = longGoal.slice(0, 200);
          changed++;
          profileChanged = true;
        }
        if (profileChanged) {
          profile.updatedAtFloor = Math.max(profile.updatedAtFloor || 0, getCurrentLastMessageId());
          profile.updatedAt = new Date().toISOString();
        }
      }
      const relations = (data?.npcRelations || []).map(rel => foxMemoryNormalizeRelationship({
        a: rel?.from,
        b: rel?.to,
        type: rel?.type || rel?.relation || '',
        summary: rel?.detail || rel?.summary || '',
        aView: rel?.fromView || rel?.from_view || '',
        bView: rel?.toView || rel?.to_view || '',
        importance: rel?.importance ?? 0.5,
        updatedAtFloor: getCurrentLastMessageId(),
      })).filter(Boolean).filter(incoming => {
        const existing = (memory.relationships || []).find(rel => {
          const sameDirection = rel.a.toLowerCase() === incoming.a.toLowerCase() && rel.b.toLowerCase() === incoming.b.toLowerCase();
          const reverseDirection = rel.a.toLowerCase() === incoming.b.toLowerCase() && rel.b.toLowerCase() === incoming.a.toLowerCase();
          return sameDirection || reverseDirection;
        });
        if (!existing) return true;
        return existing.type !== incoming.type || existing.summary !== incoming.summary
          || existing.aView !== incoming.aView || existing.bView !== incoming.bView
          || Number(existing.importance ?? 0.5) !== Number(incoming.importance ?? 0.5);
      });
      if (relations.length) changed += foxMemoryApplyRelations(memory, relations, getCurrentLastMessageId());
      if (!changed) return 0;
      foxMemoryRefreshRelationRefs(memory);
      saveFoxMemory(memory);
      foxMemoryV2Log('平行世界档案回写', `profiles/rels=${changed}`);
      return changed;
    } catch (e) {
      log('[平行世界·共享档案回写] 失败', e?.message || e);
      return 0;
    }
  }

  function pwBuildContextOrderedPrompts() {
    const cfg = pwState.config || pwLoadConfig();

    log('[平行世界·世界书] 已加入 world_info_before/world_info_after；由酒馆原生扫描并注入常驻蓝灯与激活绿灯条目');

    const fixedHead = [
      'char_description',
      'char_personality',
      'scenario',
      'persona_description',
      // 保留原生占位符，覆盖全局/角色/聊天/玩家世界书。
      'world_info_before',
      'world_info_after',
    ];

    const enabled = cfg.enableContentFilter !== false;

    if (!enabled) {
      return [...fixedHead, 'chat_history'];
    }

    // 把 pwResolveChatHistoryLimit 的 'all' 或正整数映射到 contextFloors（0=全部）
    const limit = pwResolveChatHistoryLimit();
    const contextFloors = (limit === 'all' || !Number.isFinite(limit) || limit <= 0) ? 0 : limit;

    try {
      const filtered = ssBuildFilteredChatHistoryPromptsForAnalysis({
        enableContentFilter: true,
        includeTagPairs: Array.isArray(cfg.includeTagPairs) ? cfg.includeTagPairs : [],
        excludeTagPairs: Array.isArray(cfg.excludeTagPairs) ? cfg.excludeTagPairs : [],
        includeTagStarts: cfg.includeTagStarts || '',
        includeTagEnds: cfg.includeTagEnds || '',
        excludeTagStarts: cfg.excludeTagStarts || '',
        excludeTagEnds: cfg.excludeTagEnds || '',
        contextFloors,
      });
      return [...fixedHead, ...filtered];
    } catch (e) {
      log('[平行世界] 标签过滤上下文构建失败，回退原生 chat_history', e);
      return [...fixedHead, 'chat_history'];
    }
  }

  async function pwGenerateRaw(params) {
    const customApi = pwBuildCustomApi();
    const finalParams = { ...params };

    if (Array.isArray(finalParams.ordered_prompts)) {
      finalParams.ordered_prompts = [
        { role: 'system', content: '【NPC自然互动规则】\nNPC可以在没有 user 在场时自行见面、通信、合作、争吵、交易、恋爱、建立亲密关系、发生冲突、分离或共同经历事件。是否发生互动只由同地/合理交通、关系、共同目标、信息渠道、时间和人设决定；没有条件就不要硬凑。互动必须改变至少一项关系、目标、认知或事件状态，并尊重角色意愿、世界规则和既有事实。禁止为了让剧情热闹而强行配对、强行暧昧、强行发生关系，禁止为了主线或 user 把远方 NPC 拉过来。' },
        ...finalParams.ordered_prompts,
      ];
    }

    if (customApi) finalParams.custom_api = customApi;

    // 🦊 附加参数（YAML）：仅 custom 模式生效，由 fetch hook FIFO 一次性消费注入到请求体 / headers
    const __extra = pwBuildExtraInject();
    if (__extra) finalParams.__ssExtraInject = __extra;

    pwState.internalGenerating = true;

    try {
      const result = await ssGenerateRaw('parallel_world', finalParams, '平行世界');
      if (typeof result === 'string') return result;
      const content = result?.content ?? result?.message?.content ?? result?.choices?.[0]?.message?.content;
      if (typeof content === 'string') return content;
      throw new Error(`平行世界 API 返回类型异常：${Object.prototype.toString.call(result)}`);
    } finally {
      pwState.internalGenerating = false;
    }
  }

  function pwBuildGenerationThoughtOutputTemplate() {
