  function pwAuditAutonomousModules(parsedModules, oldModules, knownNpcs, label = '整轮') {
    const oldIds = new Set((oldModules || []).map(m => String(m?.id || '')).filter(Boolean));
    const knownNames = (knownNpcs || []).map(n => String(n?.name || '')).filter(Boolean);
    const origins = new Set(['autonomous', 'goal', 'commitment', 'debt', 'secret']);
    const issues = [];
    for (const m of (parsedModules || [])) {
      if (!m || oldIds.has(String(m.id || '')) || !origins.has(String(m.origin || '').toLowerCase())) continue;
      const initiators = Array.isArray(m.initiator_npc_ids || m.initiatorNpcIds) ? (m.initiator_npc_ids || m.initiatorNpcIds) : [];
      const linked = Array.isArray(m.linked_npc_ids || m.linkedNpcIds) ? (m.linked_npc_ids || m.linkedNpcIds) : [];
      const missing = [];
      if (!initiators.length) missing.push('发起人');
      if (!linked.length) missing.push('关联角色');
      if (!pwTpIsMeaningful(m.source_goal || m.sourceGoal || m.source_stake || m.sourceStake)) missing.push('来源目标/牵挂');
      if (!pwTpIsMeaningful(m.initiative_reason || m.initiativeReason)) missing.push('发起理由');
      const unknown = initiators.filter(name => !knownNames.some(known => pwNpcNameMatches(name, known)));
      if (unknown.length) missing.push(`未建档发起人:${unknown.join(',')}`);
      if (missing.length) issues.push(`${m.id || '未知ID'}(${missing.join('、')})`);
    }
    if (issues.length) log(`[平行世界·${label}] 自主事件元数据不完整，已容错保存：${issues.join('；')}`);
