  // ✅ 一致性校验：检查生成结果与上一轮/主线的潜在矛盾，记录警告日志
  function pwConsistencyCheck(newData, oldData) {
    if (!newData || !oldData) return;
    const warnings = [];
    const oldNpcs = new Map((oldData.npcs || []).map(n => [n.name, n]));
    for (const npc of (newData.npcs || [])) {
      const old = oldNpcs.get(npc.name);
      if (!old) continue;
      const oldAl = pwResolveNpcAttitudeLevel(old);
      const newAl = pwResolveNpcAttitudeLevel(npc);
      if (oldAl >= 0 && newAl >= 0 && Math.abs(newAl - oldAl) > 50) {
        warnings.push(`NPC ${npc.name} 态度剧变: ${oldAl}->${newAl}`);
      }
      if (old.location && npc.location && old.location !== npc.location) {
        const hasEvt = (newData.modules || []).some(m => (m.linkedNpcIds || []).includes(npc.name));
        if (!hasEvt) warnings.push(`NPC ${npc.name} 位置变更无关联事件: ${old.location}->${npc.location}`);
      }
    }
    if (warnings.length) log(`[平行世界·一致性校验] ${warnings.length}个潜在矛盾: ${warnings.join('; ')}`);
    return warnings;
  }

