    // ✅ 对齐动态推进：AI 漏判部分第0轮事件不再 throw 作废整轮，仅记录警告并继续。
    //    整轮为全量重写，未判事件仍会在下方统一收尾为 aftermath_judged，不阻塞保存。
    if (missingJudgments.length) log(`[平行世界·整轮] AI 未判断全部第0轮事件，已容错继续：${missingJudgments.join(', ')}`);
    const oldIds = new Set((oldData.modules || []).map(m => String(m.id)));
    for (const m of (parsedWorld.modules || [])) {
      if (oldIds.has(String(m.id)) || m.is_dice_event === true) continue;
      const reason = String(m.creation_reason || '').toLowerCase();
      const parent = String(m.parent_event_id || '');
      if (parent && expiredIds.has(parent)) {
        m.creation_reason = 'followup';
