        m.creation_reason = '';
        m.parent_event_id = '';
      }
    }
    // ✅ 对齐动态推进：AI 返回重复 ID 时不再 throw，改为保留首次出现、忽略重复。
    const _seenModuleIds = new Set();
    const _dupModuleIds = [];
    const _uniqueModules = [];
    for (const m of (parsedWorld.modules || [])) {
      const _id = String(m?.id || '').trim();
      if (_id && _seenModuleIds.has(_id)) { _dupModuleIds.push(_id); continue; }
      if (_id) _seenModuleIds.add(_id);
      _uniqueModules.push(m);
    }
    if (_dupModuleIds.length) {
      log(`[平行世界·整轮] AI 返回了重复的事件模块 ID，已保留首次出现、忽略重复：${_dupModuleIds.join(', ')}`);
      parsedWorld.modules = _uniqueModules;
    }
    pwAuditAutonomousModules(parsedWorld.modules, oldData.modules, [...(oldData.npcs || []), ...(parsedWorld.npcs || [])], '整轮');
    const result = pwNormalizeWorldResult(parsedWorld, oldData);
    pwSaveLatestGenerationThought(result, parsedWorld, 'full');
    const effectiveOrdinaryCount = (result.modules || []).filter(m => !m.isDiceEvent && !['aftermath_pending', 'aftermath_judged'].includes(m.lifecycleState)).length;
    if (effectiveOrdinaryCount < moduleCount) {
      result.moduleDeficit = moduleCount - effectiveOrdinaryCount;
      log(`[平行世界·整轮] 事件数量不足：目标 ${moduleCount} 个，实际 ${effectiveOrdinaryCount} 个；将在下次动态推进继续补足`);
    } else {
      result.moduleDeficit = 0;
    }
    for (const oldExpired of expiredModules) {
      const existing = (result.modules || []).find(m => String(m.id) === String(oldExpired.id));
      if (existing) {
        existing.lifecycleState = 'aftermath_judged';
        existing.remainingTurns = 0;
        existing.aftermathJudgedTurn = result.turn;
      } else {
        result.modules.push({ ...oldExpired, lifecycleState: 'aftermath_judged', remainingTurns: 0, aftermathJudgedTurn: result.turn });
      }
    }
    try { pwConsistencyCheck(result, oldData); } catch (e) { log('[平行世界·一致性校验] 异常', e?.message || e); }
    return result;
