  async function pwSummarize(data) {
    if (ssIsTaskRunning('parallel_world_summarize')) {
      ssCancelTask('parallel_world_summarize', '平行世界摘要');
      throw new Error('用户中断');
    }

    ssStartTask('parallel_world_summarize', '平行世界摘要');

    let summaryToast = null;

    try {
      summaryToast = ssTaskToast('parallel_world_summarize', '🧾 正在压缩生成注入主线用的摘要……点击可中断');
    } catch { }

    const maxChars = pwSummaryRangeMaxChars(pwState.config);
    const result = {
      ...data,
      inject: {
        ...(data.inject || {}),
        global_summary: data.inject?.global_summary || data.globalState?.detail || '',
        module_summaries: (data.modules || []).map(m => ({
          id: m.id, type: m.type, title: m.title, time: data.worldClock || '',
          summary: pwClip(m.detail || m.currentState || m.nextTendency || '', maxChars),
          impactLevel: m.impactLevel || m.dangerLevel || 'none',
          progressEnabled: m.progressEnabled === true,
          progress: pwClampProgress(m.progress), progressNote: m.progressNote || '',
          dangerLevel: m.dangerLevel || '', isDiceEvent: m.isDiceEvent === true,
          diceOutcome: m.diceOutcome || '',
        })),
      },
      updatedAt: new Date().toISOString(),
    };

    try { if (summaryToast?.remove) summaryToast.remove(); } catch { }
    ssEndTask('parallel_world_summarize');

    return result;
  }

  function pwSetStatus(text) {
