  function pwUpdateRunButton() {
    // 主"推进所有事件"按钮
    const btn = topDoc.getElementById('pw-run');
    if (btn) btn.textContent = pwState.running ? '⛔ 生成中，点击中断' : '🌌 推进所有事件';

    // 状态浮窗里的同名按钮
    const floatBtn = topDoc.getElementById('pw-state-run-cycle');
    if (floatBtn) floatBtn.textContent = pwState.running ? '⛔ 生成中，点击中断' : '🌌 推进所有事件';

    // 动态推进按钮：按 advanceMode 决定可用性。
    // 注意：running 期间也保持 disabled=false，让按钮充当"中断"入口；
    // 只有当模式不可用 (legacy_full) 时才禁用。
    const cfg = pwState.config || pwLoadConfig();
    const dynamicEnabled = cfg.advanceMode !== 'legacy_full';
    const tip = dynamicEnabled
      ? '让 AI 先判断哪些事件需要推进，然后只更新它们；速度快很多'
      : '当前推进模式为"每次更新所有事件（旧模式）"，动态推进按钮不可用。请到配置面板切换模式。';

    ['pw-dynamic-run', 'pw-state-dynamic-run'].forEach(id => {
      const b = topDoc.getElementById(id);
      if (!b) return;
      b.disabled = !dynamicEnabled;
      b.title = tip;
      b.textContent = pwState.running ? '⛔ 生成中，点击中断' : '⚡ 动态推进事件';
    });
  }

  async function pwRunCycle(auto = false) {
    const backgroundSilent = auto && (pwState.config || pwLoadConfig()).backgroundSilent === true;
    const flowDiag = ssModuleDiagBegin('平行世界', auto ? '自动整轮推进' : '手动整轮推进', {
      scope: `${getCurrentCharId()}::${pwGetChatId()}`,
    });
    if (pwState.running || ssIsTaskRunning('parallel_world')) {
      // ✅ Toast 中止时，直接调 ssCancelTask。
      // 任务内部会在 finally 里把 pwState.running / pwState.status 复位。
      ssCancelTask('parallel_world', '平行世界');
      return;
    }

    if (!pwGuardChatReady()) return;

    pwReadConfigFromPanel();

    // 🦊 抢请求加固：手动推进前等待其他模块/自动任务/主模型流式输出结束（自动路径已由队列等待）。
    if (!auto) await ssWaitForManualIdle(['parallel_world', 'parallel_world_single', 'parallel_world_summarize']);

    pwState.running = true;
    pwUpdateRunButton();

    ssStartTask('parallel_world', '平行世界');

    let taskToast = null;

    try {
      if (!backgroundSilent) taskToast = ssTaskToast(
        'parallel_world',
        '🌌 平行世界更新中：点击中断可立即停止后台生成与摘要生成。'
      );
    } catch { }

    // ✅ 立即在状态栏写正在运行，避免用户以为没反应
    pwSetStatus(auto ? '自动推进中：正在生成平行世界后台正文……' : '生成中：正在生成平行世界后台正文……');
    pwUpdateRunButton();

    try {
      pwSetStatus(auto ? '自动推进中：正在生成平行世界正文 + 主线注入摘要……' : '生成中：正在生成平行世界正文 + 主线注入摘要……');

      const oldData = pwLoadData();
      const guardMeta = foxMemoryGetMessageBranchMeta(getCurrentLastMessageId());
      const runGuard = { scope: `${getCurrentCharId()}::${pwGetChatId()}`, epoch: pwState.branchEpoch, floor: guardMeta.floor, swipeId: guardMeta.swipeId, fingerprint: guardMeta.fingerprint };
      pwState.runGuard = runGuard;
      if (!pwSaveSnapshot(guardMeta.floor)) throw new Error('平行世界快照保存失败，已取消本次推进');
      ssModuleDiag(flowDiag, '读取旧数据', { turn: Number(oldData.turn) || 0, modules: oldData.modules?.length || 0, npcs: oldData.npcs?.length || 0 });
      const lifecycle = pwPrepareLifecycleAdvance(oldData);
      const diceContext = pwPrepareDiceContext(oldData, lifecycle.nextTurn);
      const fullData = await pwGenerateStep(auto, diceContext, oldData, lifecycle.expired);
      ssModuleDiag(flowDiag, '生成解析完成', { modules: fullData.modules?.length || 0, npcs: fullData.npcs?.length || 0, expired: lifecycle.expired?.length || 0 });

      // ✅ 一次性注入门闩：本次更新后，仅注入到接下来"下一楼"那一次主线请求，不再持续注入
      if (!fullData.inject) fullData.inject = { global_summary: '', module_summaries: [], manual_text: '' };
      fullData.inject.consumed = false;

      // 生命周期与声望照常推进；提交请求前已经掷出的同一颗骰子，不再二次重掷。
      pwPostAdvanceTick(fullData, pwExtractAdvanceExtras(fullData), diceContext);
      const diceModule = diceContext ? (fullData.modules || []).find(m => m.isDiceEvent && String(m.id) === diceContext.eventId) : null;
      if (fullData.lastDice && diceModule) {
        fullData.lastDice.eventName = diceModule.title || '';
        const lastLog = fullData.diceLog?.[fullData.diceLog.length - 1];
        if (lastLog) lastLog.eventName = diceModule.title || '';
      }

      if (!pwRunGuardIsCurrent(runGuard)) throw new Error('aborted: 平行世界来源楼层已变化，丢弃过期结果');
      if (!pwSaveData(fullData)) throw new Error('平行世界数据写入失败');
      pwRenderPanel();
      pwRenderStateFloat();
      try { xhDockRefresh?.(); } catch { }

      const deficitText = fullData.moduleDeficit > 0 ? `；当前少 ${fullData.moduleDeficit} 个事件，将在动态推进继续补足` : '';
      pwSetStatus(`完成：第 ${fullData.turn} 轮后台世界已更新${deficitText}`);
      toast(`${backgroundSilent ? '✅ 平行世界后台静默更新完成' : '✅ 平行世界已更新'}${deficitText}`, fullData.moduleDeficit > 0 ? 'warning' : 'success');

      // ✅ 自动模式下，刷新自动模式计数锚点，避免主回复计数被错位清零
      if (auto) {
        pwState.autoCounter = 0;
        pwState.lastAutoMessageId = getCurrentLastMessageId();
      }
    } catch (e) {
      ssModuleDiag(flowDiag, '推进失败', { error: foxJudgeDiagError(e) }, 'error');
      const msg = e?.message || String(e || '');

      if (/abort|aborted|cancel|中断|取消/i.test(msg)) {
        pwState.running = false;
        pwSetStatus('已中断');
        pwUpdateRunButton();
        if (!backgroundSilent) toast('⛔ 平行世界已中断', 'warning');
      } else {
        pwState.running = false;
        pwSetStatus(`失败：${msg}`);
        pwUpdateRunButton();
        log('[平行世界] 生成失败', e);
        toast(`❌ 平行世界生成失败：${msg}`, 'error');
      }
    } finally {

      try { taskToast?.remove?.(); } catch { }

      pwState.running = false;
      pwState.runGuard = null;
      ssEndTask('parallel_world');
      pwUpdateRunButton();
      ssModuleDiag(flowDiag, '流程清理', { running: pwState.running, turn: Number(pwLoadData().turn) || 0 });
    }
  }


