  // 动态总入口：一次请求内完成判断 + 更新选中模块。
  async function pwRunDynamicCycle(auto = false) {
    const backgroundSilent = auto && (pwState.config || pwLoadConfig()).backgroundSilent === true;
    const flowDiag = ssModuleDiagBegin('平行世界', auto ? '自动动态推进' : '手动动态推进', {
      scope: `${getCurrentCharId()}::${pwGetChatId()}`,
    });
    if (pwState.running || ssIsTaskRunning('parallel_world')) {
      ssCancelTask('parallel_world', '平行世界');
      return;
    }

    if (!pwGuardChatReady()) return;

    pwReadConfigFromPanel?.();
    pwState.config = pwLoadConfig();

    const data = pwLoadData();
    const lifecycle = pwPrepareLifecycleAdvance(data);
    const expiredModules = lifecycle.expired;
    const modules = (Array.isArray(data.modules) ? data.modules : []).filter(m => m?.isDiceEvent !== true && !['aftermath_pending', 'aftermath_judged'].includes(m?.lifecycleState));

    const configuredTarget = Math.max(3, Math.min(24, parseInt(pwState.config?.moduleCount) || 8));
    const needsRefill = modules.length < configuredTarget || Number(data.moduleDeficit) > 0;
    if (!modules.length && !expiredModules.length && !needsRefill) {
      toast('⚠️ 当前还没有平行世界事件，请先点"推进所有事件"做初始化', 'warning');
      return;
    }

    pwState.running = true;
    pwUpdateRunButton?.();
    ssStartTask('parallel_world', '平行世界');

    let taskToast = null;
    try {
      if (!backgroundSilent) taskToast = ssTaskToast(
        'parallel_world',
        auto
          ? '⚡ 动态推进中……点击中断'
          : '⚡ 动态推进中……点击中断'
      );
    } catch { }

    pwSetStatus('动态推进中：正在一次性判断并更新事件……');

    try {
      const guardMeta = foxMemoryGetMessageBranchMeta(getCurrentLastMessageId());
      const runGuard = { scope: `${getCurrentCharId()}::${pwGetChatId()}`, epoch: pwState.branchEpoch, floor: guardMeta.floor, swipeId: guardMeta.swipeId, fingerprint: guardMeta.fingerprint };
      pwState.runGuard = runGuard;
      if (!pwSaveSnapshot(guardMeta.floor)) throw new Error('平行世界快照保存失败，已取消本次推进');
      const limit = Math.max(1, Math.min(24, parseInt(pwState.config?.dynamicMaxModules) || 4));
      const diceContext = pwPrepareDiceContext(data, (Number(data.turn) || 0) + 1);
      const result = await pwAdvanceMultipleModules(data, modules.map(m => String(m.id)), {
        dynamicSelect: true,
        limit,
        diceContext,
        expiredModules,
        retiredEventIds: lifecycle.removedIds,
        targetModuleCount: configuredTarget,
      });
      ssModuleDiag(flowDiag, '动态生成解析完成', {
        candidates: modules.length,
        selected: result.selectedIds?.length || 0,
        warnings: result.warnings?.length || 0,
        repairs: result.repairs?.length || 0,
        followups: Number(result.followupCount) || 0,
        refills: Number(result.refillCount) || 0,
      });
      const selectedIds = result.selectedIds || [];
      const partialWarnings = Array.isArray(result.warnings) ? result.warnings : [];
      const automaticRepairs = Array.isArray(result.repairs) ? result.repairs : [];
      const failedEventIds = Array.isArray(result.failedEventIds) ? result.failedEventIds : [];
      const repairedEventIds = Array.isArray(result.repairedEventIds) ? result.repairedEventIds : [];
      const followupCount = Math.max(0, Number(result.followupCount) || 0);
      const refillCount = Math.max(0, Number(result.refillCount) || 0);

      const newData = result.data;

      if (!newData.inject) newData.inject = { global_summary: '', module_summaries: [], manual_text: '' };
      newData.inject.consumed = false;

      // 动态推进也视作一轮；即使没有旧事件被选中，仍提交同请求生成的骰子事件。
      newData.turn = (Number(newData.turn) || 0) + 1;
      pwPostAdvanceTick(newData, pwExtractAdvanceExtras(newData), diceContext);
      const diceModule = diceContext ? (newData.modules || []).find(m => m.isDiceEvent && String(m.id) === diceContext.eventId) : null;
      if (newData.lastDice && diceModule) {
        newData.lastDice.eventName = diceModule.title || '';
        const lastLog = newData.diceLog?.[newData.diceLog.length - 1];
        if (lastLog) lastLog.eventName = diceModule.title || '';
      }

      if (!pwRunGuardIsCurrent(runGuard)) throw new Error('aborted: 平行世界来源楼层已变化，丢弃过期结果');
      if (!pwSaveData(newData)) throw new Error('平行世界数据写入失败');
      try { pwRenderPanel?.(); } catch { }
      try { pwRenderStateFloat?.(); } catch { }
      try { xhDockRefresh?.(); } catch { }

      const deficitText = newData.moduleDeficit > 0 ? `；仍少 ${newData.moduleDeficit} 个事件，下次继续补足` : '';
      const diceText = diceModule ? '，并生成骰子事件' : '';
      const warningText = partialWarnings.length
        ? `；${failedEventIds.length ? `${failedEventIds.length} 个事件推进未应用` : `${partialWarnings.length} 项更新被跳过`}，其余结果已保存`
        : '';
      const repairText = automaticRepairs.length ? `；已自动修复并应用 ${repairedEventIds.length || automaticRepairs.length} 个事件` : '';
      const newEventText = followupCount || refillCount ? `；新增 ${followupCount} 个后续、${refillCount} 个补位` : '';
      pwSetStatus(`动态推进完成：已更新 ${selectedIds.length} 个活动事件${newEventText}${diceText}${repairText}${warningText}${deficitText}`);
      toast(
        `${partialWarnings.length ? '⚠️' : '✅'} ${backgroundSilent ? '平行世界后台静默更新完成' : `动态推进完成：已更新 ${selectedIds.length} 个活动事件`}${newEventText}${diceText}${repairText}${warningText}${deficitText}`,
        partialWarnings.length || newData.moduleDeficit > 0 ? 'warning' : 'success'
      );

      if (auto) {
        pwState.autoCounter = 0;
        pwState.lastAutoMessageId = getCurrentLastMessageId();
      }
    } catch (e) {
      ssModuleDiag(flowDiag, '推进失败', { error: foxJudgeDiagError(e) }, 'error');
      const msg = e?.message || String(e || '');

      if (/abort|aborted|cancel|中断|取消/i.test(msg)) {
        pwSetStatus('已中断');
        if (!backgroundSilent) toast('⛔ 动态推进已中断', 'warning');
      } else {
        pwSetStatus(`动态推进失败：${msg}`);
        log('[平行世界·动态推进] 失败', e);
        toast(`❌ 动态推进失败：${msg}`, 'error');
      }
    } finally {
      try { taskToast?.remove?.(); } catch { }
      pwState.running = false;
      pwState.runGuard = null;
      ssEndTask('parallel_world');
      pwUpdateRunButton?.();
      ssModuleDiag(flowDiag, '流程清理', { running: pwState.running, turn: Number(pwLoadData().turn) || 0 });
    }
  }

  // 自动推进入口：按 advanceMode 分流
  // - two_phase  → 走动态推进；前提是已经有事件，否则回退一次整轮初始化
  // - legacy_full → 走整轮推进
  async function pwRunAutoAdvance() {
    pwState.config = pwLoadConfig();
    const mode = pwState.config?.advanceMode === 'legacy_full' ? 'legacy_full' : 'two_phase';

    if (mode === 'legacy_full') {
      return pwRunCycle(true);
    }

    // two_phase：如果还没有任何模块，回退到整轮做一次初始化
    const data = pwLoadData();
    if (!Array.isArray(data.modules) || !data.modules.length) {
      log('[平行世界·自动推进] 双阶段模式但无模块，回退一次整轮初始化');
      return pwRunCycle(true);
    }

    return pwRunDynamicCycle(true);
  }


  function pwBuildInjectPlainText(trackDelivery = false) {
    const data = pwLoadData();
    if (trackDelivery) pwState.pendingInjectedModuleIds = [];

    if (!pwHasContent(data)) return '';

    const cfg = pwState.config || pwLoadConfig();
    const inject = data.inject || {};
    const hasExpiredModules = (data.modules || []).some(m => ['aftermath_pending', 'aftermath_judged'].includes(m.lifecycleState));
    const moduleLookupForLife = new Map((data.modules || []).map(m => [String(m.id || ''), m]));
    const isInjectable = (id) => {
      const m = moduleLookupForLife.get(String(id || ''));
      if (!m) return false;
      pwNormalizeModuleLifecycle(m, null, Number(data.turn) || 0);
      return m.lifecycleState === 'ready' && m.remainingTurns > 0;
    };

    const oneShotMode = ['manual', 'interval'].includes(cfg.autoMode || 'manual');
    const manualText = oneShotMode && inject.consumed === true ? '' : (inject.manual_text?.trim() || '');
    const manualForcedModules = (data.modules || []).filter(m => isInjectable(m.id) && (
      m.isDiceEvent === true || pwClampProgress(m.progress) >= 100 || ['high', 'critical'].includes(pwGetEffectiveImpactLevel(m))
    ));
    if (manualText && !manualForcedModules.length) return manualText;
    if (manualText && manualForcedModules.length) {
      const forcedText = manualForcedModules.map((m, i) => `【${m.isDiceEvent ? '🎲' : '⚠️'} ${i + 1}. ${m.title || '强制事件'}】
${m.isDiceEvent ? `骰子结果：${pwDiceOutcomeLabel(m.diceOutcome)}｜d100=${m.diceRoll ?? '?'}｜阈值=${m.diceThreshold ?? '?'}｜紧张度=${m.diceTension ?? '?'}\n` : ''}剩余注入轮次：${m.remainingTurns}
事件内容：${pwClip(m.detail || m.currentState || m.nextTendency || '', pwSummaryRangeMaxChars(cfg))}`).join('\n\n');
      if (trackDelivery) pwState.pendingInjectedModuleIds = manualForcedModules.map(m => String(m.id));
      return `${manualText}\n\n⚠️⚠️⚠️【本轮强制事件｜不受手写摘要覆盖】⚠️⚠️⚠️\n${forcedText}`;
    }

    let summaries = Array.isArray(inject.module_summaries) ? inject.module_summaries : [];

    if (!summaries.length && Array.isArray(data.modules) && data.modules.length) {
      summaries = data.modules.map(m => ({
        id: m.id,
        type: m.type,
        title: m.title,
        time: data.worldClock || '',
        summary: pwClip(m.detail || m.currentState || m.nextTendency || '', pwSummaryRangeMaxChars(cfg)),
        impactLevel: m.impactLevel || m.dangerLevel || 'none',
