${forcedDice.map((m, i) => `${fmt(m, i)}
骰子结果：${pwDiceOutcomeLabel(m.diceOutcome)}｜d100=${m.diceRoll ?? '?'}｜阈值=${m.diceThreshold ?? '?'}｜紧张度=${m.diceTension ?? '?'}`).join('\n\n')}`);
    }
    if (trackDelivery) pwState.pendingInjectedModuleIds = [...high, ...mid, ...low, ...forcedDice].map(m => String(m.id || '')).filter(Boolean);
    return lines.join('\n').trim();
  }



  function ssGetParallelWorldCurrentInjectText() {
    try {
      pwState.config = pwLoadConfig();

      if (!pwState.config.enabled) return '';
      if (pwState.config.backgroundSilent && (pwState.running || [...xhAutoQueue.pending].some(key => key.startsWith('parallel_world_auto_advance_')))) {
        log('[平行世界·主线注入] 后台静默更新尚未完成，本次跳过注入');
        return '';
      }

      // ✅ 按自动模式分流：
      // - manual / interval：平行世界更新后只注入下一次主线请求，避免旧后台反复压过后续剧情。
      // - auto：每次合格回复都会更新平行世界，所以每次主线请求都应注入当前最新后台。
      const data = pwLoadData();
      if (!pwHasContent(data)) {
        log('[平行世界·主线注入] 跳过：当前聊天没有可注入内容');
        return '';
      }

      const cfg = pwState.config || pwLoadConfig();
      const autoMode = cfg.autoMode || 'manual';
      const oneShotMode = autoMode === 'manual' || autoMode === 'interval';

      const hasReadyModules = (data.modules || []).some(m => {
        pwNormalizeModuleLifecycle(m, null, Number(data.turn) || 0);
        return m.lifecycleState === 'ready' && m.remainingTurns > 0;
      });
      if (!hasReadyModules && !data.inject?.manual_text?.trim()) {
        log('[平行世界·主线注入] 跳过：没有剩余注入轮次的事件');
        return '';
      }
      if (oneShotMode && data.inject?.consumed === true && !hasReadyModules) {
        log(`[平行世界·一次性注入] 跳过：当前模式 ${autoMode} 已注入消费过，等待下一次平行世界更新`);
        return '';
      }

      if (oneShotMode) {
        pwState.pendingOneShotInjectConsume = true;
      }

      const plain = pwBuildInjectPlainText(true);

      if (!plain.trim()) return '';

      const rangeMaxChars = pwSummaryRangeMaxChars(cfg);
      const maxModules = Math.max(1, Math.min(50, parseInt(cfg.maxInjectModules) || 10));
      const safetyMaxChars = Math.max(1500, Math.min(30000, rangeMaxChars * maxModules + 2600));

      // 🦊 注册默认提示词，支持用户自定义
      xhRegisterPromptDefault('parallel_world', {
        head: '【平行世界注入】\n以下内容是主线之外正在独立发生的导演层世界后台。应参考其中的剧情内时间、地点、人物、事件、动机、关系变化、危险等级与自然影响路径，但不得把NPC私人认知泄露给无合理信息渠道的角色。\n如果其中存在 high 或 critical 事件，必须立即在主线中体现，甚至直接打断主线剧情，直接插入剧情，绝对不能被普通日常输入覆盖！必须在正文体现！',
        middle: '【中间低优先级内容因长度限制已裁剪】',
        tail: ''
      });

      const headPrompt = xhGetPrompt('parallel_world', 'head');
      const middlePrompt = xhGetPrompt('parallel_world', 'middle');
      const tailPrompt = xhGetPrompt('parallel_world', 'tail');

      // 应用长度裁剪（保留自定义中间提示词）
      const finalText = plain.length <= safetyMaxChars
        ? plain
        : `${plain.slice(0, Math.floor(safetyMaxChars * 0.38))}\n\n${middlePrompt}\n\n${plain.slice(-Math.floor(safetyMaxChars * 0.60))}`;

      return `<parallel_world>
${headPrompt}


${finalText}${tailPrompt ? '\n\n' + tailPrompt : ''}
</parallel_world>`;
    } catch (e) {
      log('[平行世界] 构建注入失败', e);
      return '';
    }
  }

  function pwGetAssistantTextForAutoCheck(messageId) {
    try {
      const gcm = getFn('getChatMessages');
      if (!gcm) return '';

      const m = gcm(messageId, {
        hide_state: 'all',
        include_swipes: true,
      })?.[0];

      if (!m || m.role !== 'assistant') return '';

      let text = xhGetAssistantMessageText(m).text.trim();

      // 这里只判断主回复是否存在，不使用狐忆提取标签过滤，也不整段删除思维链块。
      text = text
        .replace(/<[^>]+>/g, '')
        .replace(/\s+/g, '')
        .trim();

      return text;
    } catch {
      return '';
    }
  }

  function pwIsTruncatedMessage(messageId) {
    try {
      const gcm = getFn('getChatMessages');
      if (!gcm) return false;

      const m = gcm(messageId, {
        hide_state: 'all',
        include_swipes: true,
      })?.[0];

      if (!m) return false;

      const raw = JSON.stringify({
        data: m.data || {},
        extra: m.extra || {},
        swipes_data: m.swipes_data || [],
        swipes_info: m.swipes_info || [],
      }).toLowerCase();

      if (raw.includes('"finish_reason":"length"')) return true;
      if (raw.includes('"finishreason":"length"')) return true;
      if (raw.includes('"stop_reason":"max_tokens"')) return true;
      if (raw.includes('"truncated":true')) return true;
      if (raw.includes('"is_truncated":true')) return true;

      return false;
    } catch {
      return false;
    }
  }

  function pwShouldAutoAdvance(messageId, type) {
    if (pwState.internalGenerating) return false;
    if (pwState.running || ssIsTaskRunning('parallel_world')) return false;

    // 🦊 reroll / swipe 保护：
    //   MESSAGE_RECEIVED 偶尔不会透传 type 参数（参数为 undefined / null / ''）。
    //   此时回退到 GENERATION_STARTED 抓到的 xhLastGenerationType，
    //   避免 reroll / swipe 被当成 'normal' 再触发一次平行世界推进。
    const effType = (type && typeof type === 'string')
      ? type
      : (xhGetLastGenerationType() || null);
    if (effType && effType !== 'normal') {
      log(`[平行世界自动推进] 跳过：非 normal 回复 type=${effType}${type ? '' : '（来自 GENERATION_STARTED 追踪）'}`);
      return false;
    }

    if (pwIsTruncatedMessage(messageId)) {
      log('[平行世界自动推进] 跳过：检测到截断');
      return false;
    }

    const text = pwGetAssistantTextForAutoCheck(messageId);

    if (!text.trim()) {
      const resolved = xhResolveAssistantMessage(messageId);
      const raw = xhGetAssistantMessageText(resolved.message);
      log(`[平行世界自动推进] 跳过：空回 message_id=${messageId} source=${raw.source} raw_chars=${raw.text.length} role=${resolved.message?.role || 'missing'}`);
      return false;
    }

    return true;
  }

  function pwRegisterAutoListener() {
    pwUnregisterAutoListener(true);
    pwLoadAutoCounter();

    const eo = getFn('eventOn');
    const te = getFn('tavern_events') || tavern_events;

    if (typeof eo !== 'function' || !te?.MESSAGE_RECEIVED) {
      log('[平行世界自动推进] 注册失败：缺少 MESSAGE_RECEIVED');
      return;
    }

    if (te.GENERATION_STARTED) {
      pwState.branchHandle = eo(te.GENERATION_STARTED, (type, _option, dryRun) => {
        if (dryRun || !['swipe', 'regenerate', 'reroll'].includes(String(type || '').toLowerCase())) return;
        pwState.branchEpoch++;
        const floor = getCurrentLastMessageId();
        if (pwState.running || ssIsTaskRunning('parallel_world')) ssCancelTask('parallel_world', '平行世界分支变化', { silent: true });
        pwRestoreSnapshotForFloor(floor, String(type).toLowerCase());
      });
    }
    if (te.MESSAGE_DELETED) {
      pwState.deleteHandle = eo(te.MESSAGE_DELETED, messageId => {
        pwState.branchEpoch++;
        if (pwState.running || ssIsTaskRunning('parallel_world')) ssCancelTask('parallel_world', '平行世界楼层删除', { silent: true });
        setTimeout(() => pwRestoreSnapshotForFloor(Number(messageId), '删除楼层'), 300);
      });
    }
    if (te.MESSAGE_EDITED) {
      pwState.editHandle = eo(te.MESSAGE_EDITED, messageId => {
        pwState.branchEpoch++;
        if (pwState.running || ssIsTaskRunning('parallel_world')) ssCancelTask('parallel_world', '平行世界楼层编辑', { silent: true });
        setTimeout(() => pwRestoreSnapshotForFloor(Number(messageId), '编辑楼层'), 300);
      });
    }

    pwState.autoHandle = eo(te.MESSAGE_RECEIVED, (eventMessageId, type) => {
      pwState.config = pwLoadConfig();

      const mode = pwState.config.autoMode || 'manual';

      if (mode === 'manual') {
        // 手动模式也保存快照，确保重roll/删楼时平行世界状态能正确恢复
        if (!xhIsInternalMessageEvent(type)) {
          try {
            const resolved = xhResolveAssistantMessage(eventMessageId);
            if (resolved && Number.isFinite(Number(resolved.id))) {
              pwSaveSnapshot(Number(resolved.id));
            }
          } catch (e) { log('[平行世界快照] 手动模式保存快照失败', e); }
        }
        return;
      }
      if (xhIsInternalMessageEvent(type)) {
        log(`[平行世界自动推进] 跳过：内部生成事件 message_id=${foxJudgeDiagValue(eventMessageId)} type=${type || 'unknown'}`);
        return;
      }
      const resolved = xhResolveAssistantMessage(eventMessageId);
      const messageId = resolved.id;
      const received = resolved.message;
      const eventDiag = ssModuleDiagBegin('平行世界', 'MESSAGE_RECEIVED 自动推进判定', {
        eventMessageId: foxJudgeDiagValue(eventMessageId),
        resolvedMessageId: messageId,
        resolvedFrom: resolved.source,
        eventType: type || '',
        trackedType: xhGetLastGenerationType() || '',
        mode,
      });
      if (received && received.role !== 'assistant') {
        ssModuleDiag(eventDiag, '跳过:非assistant', { messageId, role: received?.role || 'missing' }, 'warn');
        log(`[平行世界自动推进] 跳过：message_id=${messageId} 不是 assistant 回复`);
        return;
      }

      // 🦊 reroll / swipe 保护：
      //   立即在 MESSAGE_RECEIVED 触发的"那一刻"快照当前生成类型，
      //   后续 setTimeout（默认 2600ms）期间 xhLastGenerationType 可能被脚本
      //   自己的 generateRaw（quiet）覆盖，所以必须先冻结。
      const snapshotType = (type && typeof type === 'string')
        ? type
        : (xhGetLastGenerationType() || null);
      const scheduledScope = `${getCurrentCharId()}::${pwGetChatId()}`;
      const scheduledMemoryScope = getFoxMemoryScopeId();
      const scheduledEpoch = state.foxMemoryBranchEpoch;
      const scheduledPwEpoch = pwState.branchEpoch;
      const branchMeta = foxMemoryGetMessageBranchMeta(Number(messageId));
      const replyKey = `${scheduledScope}::${messageId}::${branchMeta.swipeId}::${branchMeta.fingerprint}`;
      if (!xhReserveReply(pwState.autoScheduledReplies || (pwState.autoScheduledReplies = new Set()), replyKey)) {
        log(`[平行世界自动推进] 跳过：同一真实回复已调度 key=${replyKey}`);
        return;
      }

      setTimeout(async () => {
        try {
          if (scheduledScope !== `${getCurrentCharId()}::${pwGetChatId()}`) return;
          pwState.config = pwLoadConfig();

          const latestMode = pwState.config.autoMode || 'manual';
          if (latestMode === 'manual') return;

          // 防止同一条消息被重复触发
          const midKey = String(messageId);
          if (pwState.lastAutoMessageId === midKey) {
            log('[平行世界自动推进] 跳过：同一消息已处理');
            return;
          }

          // ✅ 所有自动模式都先走严格跳过检查：
          // - 非 normal，例如 roll / swipe / continue 等，跳过
          // - 截断，跳过
          // - 空回，跳过
          // - 非空 normal assistant 回复才计数
          const stable = await foxMemoryWaitForStableAssistantMessage(messageId, {
            scope: scheduledMemoryScope,
            epoch: scheduledEpoch,
            timeoutMs: 120000,
            stableMs: 1800,
          });
          if (!stable) {
            ssModuleDiag(eventDiag, '跳过:消息未稳定', { messageId }, 'warn');
            pwState.autoScheduledReplies?.delete(replyKey);
            return;
          }
          const currentMessageId = Number(messageId);
          if (currentMessageId < 0 || !pwShouldAutoAdvance(currentMessageId, snapshotType)) {
            ssModuleDiag(eventDiag, '跳过:回复不合格', {
              messageId: currentMessageId,
              type: snapshotType,
              textSource: xhGetAssistantMessageText(stable.message).source,
              rawTextLength: xhGetAssistantMessageText(stable.message).text.length,
            }, 'warn');
            return;
          }
          ssModuleDiag(eventDiag, '回复合格', {
            messageId: currentMessageId,
            type: snapshotType,
            textSource: xhGetAssistantMessageText(stable.message).source,
            visibleTextLength: stable.text.length,
            swipeId: stable.meta.swipeId,
          }, 'info');

          // 在进入全局后台队列前先留一份当前状态；真正开始请求时还会覆盖同楼快照，
          // 从而同时覆盖“排队期间就发生 swipe”与“前序任务提交后才轮到本任务”两种竞态。
          pwSaveSnapshot(currentMessageId);

          if (latestMode === 'auto') {
             xhEnqueueAutoTask(
              `parallel_world_auto_advance_${messageId}`,
              '平行世界自动推进',
              async () => {
                if (scheduledScope !== `${getCurrentCharId()}::${pwGetChatId()}` || scheduledPwEpoch !== pwState.branchEpoch) return;
                if (!pwState.config.backgroundSilent) toast('🌌 平行世界：检测到合格回复，开始自动推进……', 'info');
                const before = Number(pwLoadData().turn) || 0;
                await pwRunAutoAdvance();
                if ((Number(pwLoadData().turn) || 0) > before) {
                  pwState.lastAutoMessageId = midKey;
                  pwSaveAutoCounter();
                }
              },
              { dedupe: true }
            );
            return;
          }

           if (latestMode === 'interval') {
             const interval = Math.max(1, parseInt(pwState.config.autoInterval) || 5);
             const currentId = String(messageId);
             if (pwState.lastAutoMessageId === currentId) {
               log(`[平行世界自动推进] 跳过：楼层已计数 current=${currentId}`);
               return;
             }
             // 🦊 修复楼层计算：按真实楼层差计数（与狐忆同款），"隔N楼"直观对应聊天楼层数
             {
               const __lastN = parseInt(pwState.lastAutoMessageId);
               const __curN = parseInt(messageId);
               pwState.autoCounter += (Number.isFinite(__lastN) && Number.isFinite(__curN) && __curN > __lastN) ? (__curN - __lastN) : 1;
             }
             pwState.lastAutoMessageId = midKey;
             pwSaveAutoCounter();

            // 📊 楼层推进诊断日志：打印本楼被认为是主AI回复的楼层内容及前300字
            //    用于排查"隔N楼推进"是否计算到了正确的楼层
            let __pwPreview = '';
            try {
              const __gcm = getFn('getChatMessages');
              if (__gcm) {
                const __m = __gcm(messageId, { hide_state: 'all', include_swipes: true })?.[0];
                if (__m) {
                  const { text } = xhGetAssistantMessageText(__m);
                  __pwPreview = text.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim().slice(0, 300);
                }
              }
            } catch (e) { log('[平行世界·楼层推进] 日志打印失败', e); }
            log(`[平行世界·楼层推进] 检测到主AI回复楼层 message_id=${messageId}，计数=${pwState.autoCounter}/${interval}，内容前300字：${__pwPreview}`);

            if (pwState.autoCounter >= interval) {
              pwState.autoCounter = Math.max(0, pwState.autoCounter - interval);
              pwSaveAutoCounter();
              const queued = xhEnqueueAutoTask(
               `parallel_world_auto_advance_${messageId}`,
                '平行世界自动推进',
                 async () => { if (scheduledScope !== `${getCurrentCharId()}::${pwGetChatId()}` || scheduledPwEpoch !== pwState.branchEpoch) return; const before=Number(pwLoadData().turn)||0; await pwRunAutoAdvance(); const after=Number(pwLoadData().turn)||0; if(after<=before) log('[平行世界自动推进] 本周期未提交新轮次；下一周期继续正常计数'); },
               { dedupe: true }
              );
              if (queued?.queued === false) log('[平行世界自动推进] 同消息任务已存在，保留计数等待重试');
            }
          }
        } catch (e) {
          log('[平行世界自动推进] 检查失败', e);
        }
      }, Math.max(2600, parseInt(pwState.config.autoDelayMs) || 2600));
    });

    log('[平行世界自动推进] 已注册 MESSAGE_RECEIVED 监听');
  }
  function pwUnregisterAutoListener(removeBranchListeners = false) {
    ssStopEventHandle(pwState.autoHandle);
    pwState.autoHandle = null;
    if (removeBranchListeners) {
      ssStopEventHandle(pwState.branchHandle);
      ssStopEventHandle(pwState.deleteHandle);
      ssStopEventHandle(pwState.editHandle);
      pwState.branchHandle = null;
      pwState.deleteHandle = null;
      pwState.editHandle = null;
    }
  }

  function pwGetPresetOptionsHtml(selected) {
    try {
      const fn = getFn('getPresetNames');
      if (typeof fn !== 'function') return '<option value="">无可用预设</option>';

      const names = fn().filter(x => x !== 'in_use').sort();

      if (!names.length) return '<option value="">无可用预设</option>';

      return [
        '<option value="">使用内置提示词（推荐）</option>',
        ...names.map(n => `<option value="${escapeHtml(n)}" ${n === selected ? 'selected' : ''}>${escapeHtml(n)}</option>`),
      ].join('');
    } catch {
      return '<option value="">无可用预设</option>';
    }
  }

  function pwModelOptionsHtml(selected) {
    if (!pwState.models.length) return '<option value="">暂无模型列表</option>';

    return [
      '<option value="">从列表选择</option>',
      ...pwState.models.map(m => `<option value="${escapeHtml(m)}" ${m === selected ? 'selected' : ''}>${escapeHtml(m)}</option>`),
    ].join('');
  }

  async function pwFetchModelsFromPanel() {
    const apiurl = topDoc.getElementById('pw-api-url')?.value?.trim() || '';
    const key = topDoc.getElementById('pw-api-key')?.value?.trim() || '';
    const proxyPreset = topDoc.getElementById('pw-proxy-preset')?.value || '';
    const btn = topDoc.getElementById('pw-fetch-models');

    let finalApiUrl = apiurl;
    let finalKey = key;

    if (proxyPreset) {
      try {
        const p = getPreset(proxyPreset);
        finalApiUrl = p?.settings?.apiurl || '';
        finalKey = p?.settings?.key || '';
      } catch {
        toast('读取代理预设失败', 'error');
        return;
      }
    }

    if (!finalApiUrl) {
      toast('请先填写 API 地址或选择代理预设', 'warning');
      return;
    }

    pwState.loadingModels = true;

    if (btn) {
      btn.textContent = '加载中…';
      btn.disabled = true;
    }

    try {
      const getModelList = getFn('getModelList');

      if (typeof getModelList === 'function') {
        pwState.models = await getModelList({
          apiurl: finalApiUrl.replace(/\/+$/, ''),
          key: finalKey || '',
        });
      } else {
        const headers = SillyTavern?.getRequestHeaders?.() || {};
        const resp = await fetch('/api/backends/chat-completions/status', {
          method: 'POST',
          headers,
          body: JSON.stringify({
            reverse_proxy: finalApiUrl,
            proxy_password: finalKey || '',
            chat_completion_source: 'openai',
          }),
        });

        const json = await resp.json();

        pwState.models = (json?.data || [])
          .map(x => String(x?.id ?? '').trim())
          .filter(Boolean);
      }

      pwState.models = [...new Set(pwState.models)].sort();

      const sel = topDoc.getElementById('pw-model-select');
      if (sel) {
        sel.innerHTML = pwModelOptionsHtml(topDoc.getElementById('pw-model')?.value || '');
      }

      toast(
        pwState.models.length ? `已获取 ${pwState.models.length} 个模型` : '模型列表为空',
        pwState.models.length ? 'success' : 'warning'
      );
    } catch (e) {
      toast(`获取模型失败：${e.message || e}`, 'error');
    } finally {
      pwState.loadingModels = false;

      if (btn) {
        btn.textContent = '获取模型';
        btn.disabled = false;
      }
    }
  }

