/* ===== 质感提升（保留原色彩，仅加过渡+悬浮效果）===== */
#pw-panel button,#pw-panel .pw-btn,#pw-state-float button{transition:all .15s ease!important;}
#pw-panel button:hover,#pw-panel .pw-btn:hover,#pw-state-float button:hover{transform:translateY(-1px)!important;filter:brightness(1.12)!important;}
#pw-panel button:active,#pw-panel .pw-btn:active{transform:scale(.98)!important;}
`;

    topDoc.head.appendChild(style);
  }

  // NPC 态度 5 级配色：灰(不认识)/白(中立)/绿(好感)/红(敌意)/黑(决裂)
  const PW_NPC_ATTITUDE_META = {
    unknown: { label: '不认识', color: '#888', bg: 'rgba(136,136,136,0.18)' },
    neutral: { label: '中立', color: '#ddd', bg: 'rgba(221,221,221,0.18)' },
    friendly: { label: '好感', color: '#4caf50', bg: 'rgba(76,175,80,0.20)' },
    hostile: { label: '敌意', color: '#f44336', bg: 'rgba(244,67,54,0.20)' },
    rupture: { label: '决裂', color: '#222', bg: 'rgba(20,20,20,0.40)' },
  };

  // ✅ 解析 NPC 的 attitudeLevel（兼容旧数据：无数值时按文本 attitude 推断）
  function pwResolveNpcAttitudeLevel(n) {
    if (n.attitudeLevel != null && n.attitudeLevel !== '') return pwClampAttitudeLevel(n.attitudeLevel);
    return pwAttitudeDefaultLevel(n.attitude || 'unknown');
  }

  // ✅ NPC 情绪条（双向，50中点）+ 看法条（-1灰未激活 / 0-100渐变）
  function pwBuildNpcBarsHtml(n) {
    const emotionLevel = pwClampEmotionLevel(n.emotionLevel != null && n.emotionLevel !== '' ? n.emotionLevel : 50);
    const emotionColor = pwEmotionLevelColor(emotionLevel);
    let emoFill;
    if (emotionLevel >= 50) {
      emoFill = `left:50%;width:${emotionLevel - 50}%;background:linear-gradient(to right, rgba(120,145,170,0.25), ${emotionColor});`;
    } else {
      emoFill = `right:50%;width:${50 - emotionLevel}%;background:linear-gradient(to left, rgba(120,145,170,0.25), ${emotionColor});`;
    }

    const attitudeLevel = pwResolveNpcAttitudeLevel(n);
    const attLabel = PW_NPC_ATTITUDE_META[n.attitude || pwAttitudeFromLevel(attitudeLevel)] || PW_NPC_ATTITUDE_META.unknown;
    let attBarInner;
    if (attitudeLevel < 0) {
      attBarInner = `<div class="pw-attbar-fill" style="width:100%;background:repeating-linear-gradient(45deg,#333,#333 6px,#262626 6px,#262626 12px);opacity:0.7;"></div><span class="pw-attbar-nolabel">未结识</span>`;
    } else {
      const attColor = pwAttitudeLevelColor(attitudeLevel);
      attBarInner = `<div class="pw-attbar-fill" style="width:${attitudeLevel}%;background:linear-gradient(to right, rgb(40,8,8), ${attColor});box-shadow:0 0 8px ${attColor};"></div><span class="pw-attbar-marker" style="left:${attitudeLevel}%;background:${attColor};box-shadow:0 0 6px ${attColor};"></span>`;
    }

    return `
  <div class="pw-npc-bars">
    <div class="pw-npc-bar-row">
      <span class="pw-npc-bar-label">情绪</span>
      <div class="pw-emobar-track">
        <div class="pw-emobar-bg"></div>
        <div class="pw-emobar-mid"></div>
        <div class="pw-emobar-fill" style="${emoFill}"></div>
        <div class="pw-emobar-pointer" style="left:${emotionLevel}%;background:${emotionColor};box-shadow:0 0 8px ${emotionColor};"></div>
      </div>
      <span class="pw-npc-bar-value" style="color:${emotionColor};">${emotionLevel}</span>
    </div>
    ${n.emotion ? `<div class="pw-npc-bar-text">💬 ${escapeHtml(n.emotion)}</div>` : ''}
    <div class="pw-npc-bar-row">
      <span class="pw-npc-bar-label">看法</span>
      <div class="pw-attbar-track">${attBarInner}</div>
      <span class="pw-npc-bar-value" style="color:${attitudeLevel < 0 ? '#888' : pwAttitudeLevelColor(attitudeLevel)};">${attitudeLevel < 0 ? '—' : attitudeLevel}</span>
    </div>
    <div class="pw-npc-bar-text" style="color:${attLabel.color};">👤 对主角：${attLabel.label}</div>
  </div>`;
  }

  // NPC 卡片整体色调类名（按 attitudeLevel）
  function pwNpcCardClass(attitudeLevel) {
    if (attitudeLevel < 0) return 'pw-card-npc-unknown';
    if (attitudeLevel === 0) return 'pw-card-npc-rupture';
    if (attitudeLevel < 40) return 'pw-card-npc-hostile';
    if (attitudeLevel < 60) return 'pw-card-npc-neutral';
    return 'pw-card-npc-friendly';
  }

  function pwRenderNpcListLines(items) {
    return (Array.isArray(items) ? items : []).map(x => `• ${escapeHtml(x)}`).join('<br>');
  }

  function pwRenderNpcVitalsHtml(n) {
    const health = n.health == null ? '未知' : String(pwClampNpcMetric(n.health, 0));
    const fatigue = n.fatigue == null ? '未知' : String(pwClampNpcMetric(n.fatigue, 0));
    const standing = n.standing || (n.standingLevel == null ? '未知' : `刻度 ${pwClampNpcMetric(n.standingLevel, 0)}`);
    return `<div class="pw-npc-vitals">
      <div class="pw-npc-vital"><b>健康</b><span>${escapeHtml(health)}</span></div>
      <div class="pw-npc-vital"><b>疲劳</b><span>${escapeHtml(fatigue)}</span></div>
      <div class="pw-npc-vital"><b>地位</b><span>${escapeHtml(standing)}</span></div>
    </div>`;
  }

  function pwRenderNpcCardsHtml(data) {
    const npcs = Array.isArray(data?.npcs) ? data.npcs : [];
    const relations = Array.isArray(data?.npcRelations) ? data.npcRelations : [];
    if (!npcs.length) return '';
    const sorted = npcs.slice().sort((a, b) => (pwClampNpcMetric(b.standingLevel, 0) - pwClampNpcMetric(a.standingLevel, 0)) || String(a.name).localeCompare(String(b.name), 'zh-CN'));
    const cards = sorted.map((n) => {
      const attitudeLevel = pwResolveNpcAttitudeLevel(n);
      const meta = PW_NPC_ATTITUDE_META[n.attitude || pwAttitudeFromLevel(attitudeLevel)] || PW_NPC_ATTITUDE_META.unknown;
      const cardClass = 'pw-card-npc-neutral';
      const rels = relations.filter(r => r.from === n.name || r.to === n.name);
      const relHtml = rels.length ? rels.map(r => {
        const outgoing = r.from === n.name;
        const other = outgoing ? r.to : r.from;
        const rl = (r.relationLevel != null && r.relationLevel !== '') ? pwClampRelationLevel(r.relationLevel) : null;
        const rm = PW_NPC_ATTITUDE_META[r.valence || (rl != null ? pwAttitudeFromLevel(rl) : 'unknown')] || PW_NPC_ATTITUDE_META.unknown;
        const rc = (rl != null && rl >= 0) ? pwAttitudeLevelColor(rl) : rm.color;
        const dims = [['信',r.trust],['亲',r.intimacy],['惧',r.fear],['敬',r.respect],['妒',r.jealousy],['利',r.interest],['依',r.dependence]].filter(([,v]) => v != null).map(([k,v]) => `${k}${pwClampNpcMetric(v,0)}`).join(' ');
        return `<span class="pw-chip" style="border-color:${rc};color:${rc};">${outgoing ? '→' : '←'}${escapeHtml(other)}${dims ? `：${escapeHtml(dims)}` : `：${rm.label}${(rl != null && rl >= 0) ? `(${rl})` : ''}`}</span>`;
      }).join('') : '';
      return `
<div class="pw-card pw-card-small ${cardClass}">
  <div class="pw-card-topbar">
    <div class="pw-meta" style="margin-bottom:0;">
      <span class="pw-chip">👤 ${escapeHtml(n.name)}</span>
      ${n.location ? `<span class="pw-chip">📍${escapeHtml(n.location)}</span>` : ''}
    </div>
    <div class="pw-npc-actions">
      <button type="button" class="pw-npc-btn" data-pw-npc-edit="${escapeHtml(n.name)}" title="编辑此角色">✏️</button>
      <button type="button" class="pw-npc-btn danger" data-pw-npc-del="${escapeHtml(n.name)}" title="删除此角色">🗑️</button>
    </div>
  </div>
  ${pwRenderNpcVitalsHtml(n)}
  ${n.healthNote || n.fatigueNote || n.standingNote ? `<div style="font-size:10px;color:#706058;">${escapeHtml([n.healthNote,n.fatigueNote,n.standingNote].filter(Boolean).join('；'))}</div>` : ''}
  ${n.status ? `<div style="font-size:11px;color:#a09088;margin:4px 0;">${escapeHtml(n.status)}</div>` : ''}
  ${n.currentThought ? `<div class="pw-npc-goal-field"><b>当前想法</b><div>${escapeHtml(n.currentThought)}</div></div>` : ''}
  ${n.shortTermGoal || n.goals ? `<div class="pw-npc-goal-field"><b>短期目标 · ${escapeHtml(n.goalStatus || 'active')} · ${pwClampNpcMetric(n.goalProgress, 0)}%</b><div>${escapeHtml(n.shortTermGoal || n.goals)}</div>${n.goalProgressNote ? `<div style="color:#7a6a5e;margin-top:3px;">${escapeHtml(n.goalProgressNote)}</div>` : ''}</div>` : ''}
  ${n.shortTermGoal || n.goals ? `<div class="pw-meta"><span class="pw-chip">优先 ${pwClampNpcMetric(n.goalPriority, 50)}</span><span class="pw-chip">紧迫 ${pwClampNpcMetric(n.goalUrgency, 50)}</span><span class="pw-chip">重要 ${pwClampNpcMetric(n.goalImportance, 50)}</span><span class="pw-chip">风险 ${pwClampNpcMetric(n.goalRisk, 50)}</span><span class="pw-chip">成本 ${pwClampNpcMetric(n.goalCost, 50)}</span></div>` : ''}
  ${n.goalObstacle || n.goalOutcome ? `<div class="pw-npc-goal-field"><b>${n.goalOutcome ? '目标结果' : '当前阻碍'}</b><div>${escapeHtml(n.goalOutcome || n.goalObstacle)}</div></div>` : ''}
  ${n.longTermGoal ? `<div class="pw-npc-goal-field"><b>长期目标</b><div>${escapeHtml(n.longTermGoal)}</div></div>` : ''}
  ${n.currentTask ? `<div class="pw-npc-goal-field"><b>当前行动</b><div>${escapeHtml(n.currentTask)}</div></div>` : ''}
  ${n.activeGoalReason ? `<div class="pw-npc-goal-field"><b>目标竞争</b><div>${escapeHtml(n.activeGoalReason)}</div></div>` : ''}
  ${(n.commitments || []).length ? `<div class="pw-npc-stake"><b>承诺</b><br>${pwRenderNpcListLines(n.commitments)}</div>` : ''}
  ${(n.debts || []).length ? `<div class="pw-npc-stake"><b>债务</b><br>${pwRenderNpcListLines(n.debts)}</div>` : ''}
  ${(n.secrets || []).length ? `<div class="pw-npc-stake"><b>秘密 / 埋线</b><br>${pwRenderNpcListLines(n.secrets)}</div>` : ''}
  ${n.autonomousIntent ? `<div class="pw-npc-goal-field"><b>自主意图</b><div>${escapeHtml(n.autonomousIntent)}</div></div>` : ''}
  ${(n.confirmedFacts || []).length || (n.rumors || []).length || (n.assumptions || []).length || (n.falseBeliefs || []).length || (n.deniedFacts || []).length ? `<details class="pw-card-details"><summary>私人认知</summary><pre>${escapeHtml([...(n.confirmedFacts || []).map(x => `确认：${x}`), ...(n.rumors || []).map(x => `传言：${x}`), ...(n.assumptions || []).map(x => `推测：${x}`), ...(n.falseBeliefs || []).map(x => `错误认知：${x}`), ...(n.deniedFacts || []).map(x => `不愿承认：${x}`)].join('\n'))}</pre></details>` : ''}
  ${(n.lifeLog || []).length ? `<details class="pw-card-details"><summary>离屏生活</summary><pre>${escapeHtml((n.lifeLog || []).map(x => `• ${x}`).join('\n'))}</pre></details>` : ''}
  ${n.detail ? `<details class="pw-card-details"><summary>长期档案</summary><pre>${escapeHtml(n.detail)}</pre></details>` : ''}
  ${relHtml ? `<div class="pw-meta" style="margin-top:6px;">${relHtml}</div>` : ''}
</div>`;
    }).join('');
    return `<div style="margin-top:14px;"><div style="font-weight:700;color:#f0a070;font-size:13px;margin-bottom:8px;">👥 角色状态（${npcs.length}）</div><div class="pw-masonry">${cards}</div></div>`;
  }

  // ✅ NPC 编辑/删除按钮绑定
  function pwBindNpcActionButtons(root = topDoc) {
    const scope = root?.querySelectorAll ? root : topDoc;
    scope.querySelectorAll('[data-pw-npc-edit]').forEach(btn => {
      if (btn.dataset.bound === '1') return;
      btn.dataset.bound = '1';
      btn.onclick = (e) => { e.preventDefault(); e.stopPropagation(); pwEditNpc(btn.getAttribute('data-pw-npc-edit')); };
    });
    scope.querySelectorAll('[data-pw-npc-del]').forEach(btn => {
      if (btn.dataset.bound === '1') return;
      btn.dataset.bound = '1';
      btn.onclick = (e) => {
        e.preventDefault(); e.stopPropagation();
        const name = btn.getAttribute('data-pw-npc-del');
        const ok = topWindow?.confirm ? topWindow.confirm(`确定要删除角色「${name}」吗？\n\n该角色的所有档案和关系都会被清除，此操作不可撤销。`) : confirm(`确定要删除角色「${name}」吗？`);
        if (ok) pwDeleteNpc(name);
      };
    });
  }

  // ✅ 删除 NPC：从 data.npcs 移除 + 清理关联 npcRelations
  function pwDeleteNpc(name) {
    const data = pwLoadData();
    const target = String(name || '').trim();
    if (!target) return;
    data.npcs = (data.npcs || []).filter(n => String(n.name || '') !== target);
    data.npcRelations = (data.npcRelations || []).filter(r => {
      const f = String(r.from || '').trim();
      const t = String(r.to || '').trim();
      return f !== target && t !== target;
    });
    // 同步清理事件模块的 linkedNpcIds 中该 NPC
    if (Array.isArray(data.modules)) {
      data.modules = data.modules.map(m => {
        if (Array.isArray(m.linkedNpcIds) && m.linkedNpcIds.length) {
          m.linkedNpcIds = m.linkedNpcIds.filter(id => !pwNpcNameMatches(id, target));
        }
        return m;
      });
    }
    data.updatedAt = new Date().toISOString();
    pwSaveData(data);
    try { pwRenderPanel?.(); } catch {}
    try { pwRenderStateFloat?.(); } catch {}
    toast(`🗑️ 已删除角色：${target}`, 'success');
  }

