      if (newName !== target) {
        const dup = (data.npcs || []).some((n, i) => i !== idx && String(n.name || '') === newName);
        if (dup) { toast('⚠️ 该名字已存在，请换一个', 'warning'); return; }
      }
      if (idx >= 0) {
        data.npcs[idx].name = newName;
        data.npcs[idx].emotion = newEmotion;
        data.npcs[idx].emotionLevel = newEl;
        // ✅ Fix: 去掉冗余 unknown 分支，统一由 pwAttitudeFromLevel(newAl) 推导（<0 自然返回 unknown）
        data.npcs[idx].attitude = pwAttitudeFromLevel(newAl);
        data.npcs[idx].attitudeLevel = newAl;
        data.npcs[idx].location = newLoc;
        data.npcs[idx].status = newStatus;
        data.npcs[idx].currentThought = newCurrentThought;
        data.npcs[idx].shortTermGoal = newShortTermGoal;
        data.npcs[idx].longTermGoal = newLongTermGoal;
        data.npcs[idx].goalChangeReason = newGoalChangeReason;
        data.npcs[idx].currentTask = newCurrentTask;
        data.npcs[idx].health = newHealth;
        data.npcs[idx].healthNote = (topDoc.getElementById('pw-ne-health-note').value || '').trim();
        data.npcs[idx].fatigue = newFatigue;
        data.npcs[idx].fatigueNote = (topDoc.getElementById('pw-ne-fatigue-note').value || '').trim();
        data.npcs[idx].standing = newStanding;
        data.npcs[idx].standingLevel = newStandingLevel;
        data.npcs[idx].goalStatus = newGoalStatus;
        data.npcs[idx].goalProgress = newGoalProgress;
        data.npcs[idx].commitments = pwTpToLineList(topDoc.getElementById('pw-ne-commitments').value).slice(-6);
        data.npcs[idx].debts = pwTpToLineList(topDoc.getElementById('pw-ne-debts').value).slice(-6);
        data.npcs[idx].secrets = pwTpToLineList(topDoc.getElementById('pw-ne-secrets').value).slice(-6);
        data.npcs[idx].detail = newDetail;
        data.npcs[idx].updatedAt = new Date().toISOString();
      }
      // 如果改了名字，同步更新 npcRelations 里的 from/to
      if (newName !== target) {
        data.npcRelations = (data.npcRelations || []).map(r => ({
          ...r,
          from: String(r.from || '') === target ? newName : r.from,
          to: String(r.to || '') === target ? newName : r.to,
        }));
        // 同步 modules.linkedNpcIds（✅ Fix: 用 pwNpcNameMatches 模糊匹配，与显示侧一致）
        if (Array.isArray(data.modules)) {
          data.modules = data.modules.map(m => {
            if (Array.isArray(m.linkedNpcIds)) {
              m.linkedNpcIds = m.linkedNpcIds.map(id => pwNpcNameMatches(id, target) ? newName : id);
            }
            if (Array.isArray(m.initiatorNpcIds)) {
              m.initiatorNpcIds = m.initiatorNpcIds.map(id => pwNpcNameMatches(id, target) ? newName : id);
            }
            return m;
          });
        }
      }
      data.updatedAt = new Date().toISOString();
      if (!pwSaveData(data)) { toast('❌ 角色保存失败，请检查存储空间', 'error'); return; }
      close();
      try { pwRenderPanel?.(); } catch {}
      try { pwRenderStateFloat?.(); } catch {}
      toast(`✅ 已保存角色：${newName}`, 'success');
    };
  }

