  function pwGraphGetPlayerName() {
    try { const ctx = SillyTavern?.getContext?.(); if (ctx?.name1) return String(ctx.name1); } catch {}
    try { const ctx = topWindow.SillyTavern?.getContext?.(); if (ctx?.name1) return String(ctx.name1); } catch {}
    return '主角';
  }

  function pwGraphViewportSize() {
    const rect = PW_GRAPH.overlay?.getBoundingClientRect?.();
    const vv = topWindow.visualViewport;
    const layoutWidth = rect?.width || topWindow.innerWidth || 800;
    const layoutHeight = rect?.height || topWindow.innerHeight || 600;
    const width = Math.round(vv?.width ? Math.min(layoutWidth, vv.width) : layoutWidth);
    const height = Math.round(vv?.height ? Math.min(layoutHeight, vv.height) : layoutHeight);
    return { width: Math.max(1, width), height: Math.max(1, height) };
  }

  function pwGraphUpdatePointer(clientX, clientY) {
    if (!PW_GRAPH.pointer || !PW_GRAPH.canvas) return;
    const rect = PW_GRAPH.canvas.getBoundingClientRect();
    const width = Math.max(1, rect.width);
    const height = Math.max(1, rect.height);
    PW_GRAPH.pointer.x = ((clientX - rect.left) / width) * 2 - 1;
    PW_GRAPH.pointer.y = -((clientY - rect.top) / height) * 2 + 1;
  }

  // 加载 Three.js（多 CDN 回退）
  async function pwGraphLoadThree() {
    if (topWindow.THREE) { PW_GRAPH.THREE = topWindow.THREE; return topWindow.THREE; }
    if (PW_GRAPH.loadingPromise) return PW_GRAPH.loadingPromise;
    const urls = [
      'https://cdn.jsdelivr.net/npm/three@0.150.1/build/three.min.js',
      'https://unpkg.com/three@0.150.1/build/three.min.js',
      'https://cdnjs.cloudflare.com/ajax/libs/three.js/r150/three.min.js',
    ];
    PW_GRAPH.loadingPromise = (async () => {
      for (const url of urls) {
        try {
          await new Promise((resolve, reject) => {
            const s = topDoc.createElement('script');
            s.src = url;
            s.onload = () => { resolve(); };
            s.onerror = () => { try { s.remove(); } catch {} reject(new Error('load fail')); };
            topDoc.head.appendChild(s);
          });
          if (topWindow.THREE) { PW_GRAPH.THREE = topWindow.THREE; return topWindow.THREE; }
        } catch {}
      }
      throw new Error('所有 CDN 均加载失败，请检查网络');
    })();
    return PW_GRAPH.loadingPromise;
  }

  function pwGraphClose() {
    try { if (PW_GRAPH.rafId) { topWindow.cancelAnimationFrame(PW_GRAPH.rafId); PW_GRAPH.rafId = null; } } catch {}
    if (PW_GRAPH._hoverCardTimer) { try { topWindow.clearTimeout(PW_GRAPH._hoverCardTimer); } catch {} PW_GRAPH._hoverCardTimer = null; }
    try { pwGraphRemoveCard(); } catch {}
    if (PW_GRAPH.pinchEndTimer) { topWindow.clearTimeout(PW_GRAPH.pinchEndTimer); PW_GRAPH.pinchEndTimer = null; }
    PW_GRAPH.dragging = false;
    PW_GRAPH.isPinching = false;
    PW_GRAPH.activePointerId = null;
    try {
      if (PW_GRAPH.renderer) {
        PW_GRAPH.renderer.dispose?.();
        PW_GRAPH.renderer.forceContextLoss?.();
        PW_GRAPH.renderer = null;
      }
    } catch {}
    PW_GRAPH.scene = null;
    PW_GRAPH.camera = null;
    PW_GRAPH.group = null;
    PW_GRAPH.nodeMeshes = [];
    PW_GRAPH.edges = [];
    PW_GRAPH.beads = [];
    PW_GRAPH.focusMesh = null;
    PW_GRAPH.hovered = null;
    PW_GRAPH.cardActive = false;
    PW_GRAPH.cardSwingT = 0;
    PW_GRAPH.cardZoom = 1;
    PW_GRAPH.cardPan = { x: 0, y: 0 };
    PW_GRAPH.cardCamStartPos = null;
    PW_GRAPH.cardCamTargetPos = null;
    PW_GRAPH._lightsAdded = false;
    if (PW_GRAPH.overlay) { try { PW_GRAPH.overlay.remove(); } catch {} PW_GRAPH.overlay = null; }
    // 恢复面板遮罩层（打开3D网格时隐藏了它）
    try {
      const panelOverlay = topDoc.getElementById('pw-overlay');
      if (panelOverlay && panelOverlay.dataset._pwGraphHidden === '1') {
        panelOverlay.style.display = '';
        delete panelOverlay.dataset._pwGraphHidden;
      }
    } catch {}
  }

  // ── 星云纹理生成（移植自测试脚本）──
  function pwGraphMakeNebula(THREE) {
    try {
      const c = topDoc.createElement('canvas'); c.width = 2048; c.height = 1024;
      const ctx = c.getContext('2d');
      ctx.fillStyle = '#08060a'; ctx.fillRect(0, 0, 2048, 1024);
      [{x:500,y:300,r:500,c:'rgba(55,25,70,0.22)'},{x:1400,y:700,r:550,c:'rgba(20,45,65,0.18)'},{x:1000,y:200,r:350,c:'rgba(70,35,25,0.12)'},{x:300,y:800,r:400,c:'rgba(25,50,45,0.10)'},{x:1700,y:300,r:300,c:'rgba(45,20,35,0.14)'}].forEach(b => {
        const g = ctx.createRadialGradient(b.x, b.y, 0, b.x, b.y, b.r);
        g.addColorStop(0, b.c); g.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = g; ctx.fillRect(0, 0, 2048, 1024);
      });
      for (let i = 0; i < 500; i++) {
        const x = Math.random() * 2048, y = Math.random() * 1024, sz = Math.random() * 1.8 + 0.3, a = Math.random() * 0.7 + 0.15;
        ctx.fillStyle = Math.random() > 0.6 ? `rgba(255,220,180,${a})` : `rgba(180,200,230,${a})`;
        ctx.fillRect(x, y, sz, sz);
      }
      return new THREE.CanvasTexture(c);
    } catch (e) { log('[平行世界·3D] 星云纹理失败', e?.message || e); return null; }
  }

  function pwGraphInitScene(THREE) {
    const canvas = PW_GRAPH.canvas;
    const { width: w, height: h } = pwGraphViewportSize();

    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: false });
    renderer.setPixelRatio(Math.min(2, topWindow.devicePixelRatio || 1));
    renderer.setSize(w, h);
    renderer.setClearColor(0x08060a, 1);
    PW_GRAPH.renderer = renderer;

    const scene = new THREE.Scene();
    // 关系节点必须在全景距离下保持可见，不能被深色距离雾融入背景。
    scene.fog = null;
    PW_GRAPH.scene = scene;

    const camera = new THREE.PerspectiveCamera(55, w / h, 0.1, 200);
    camera.position.set(0, 4, PW_GRAPH.camDist);
    camera.lookAt(0, 0, 0);
    PW_GRAPH.camera = camera;

    const group = new THREE.Group();
    group.rotation.x = PW_GRAPH.rotation.x;
    group.rotation.y = PW_GRAPH.rotation.y;
    scene.add(group);
    PW_GRAPH.group = group;

    // 星空背景粒子
    // ✅ 跨 realm 修复：脚本跑在 iframe，THREE 在 topWindow。必须用 topWindow.Float32Array，
    //    否则 THREE.BufferAttribute 内部 `array instanceof Float32Array`（topWindow realm）
    //    对 iframe realm 的 Float32Array 实例返回 false，报 "Unsupported buffer data format"。
    try {
      const starGeo = new THREE.BufferGeometry();
      const starN = 600;
      const Float32 = topWindow.Float32Array || Float32Array;
      const pos = new Float32(starN * 3);
      for (let i = 0; i < starN; i++) {
        const r = 50 + Math.random() * 40;
        const t = Math.random() * Math.PI * 2;
        const p = Math.acos(2 * Math.random() - 1);
        pos[i * 3] = r * Math.sin(p) * Math.cos(t);
        pos[i * 3 + 1] = r * Math.sin(p) * Math.sin(t);
        pos[i * 3 + 2] = r * Math.cos(p);
      }
      starGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
      const starMat = new THREE.PointsMaterial({ color: 0x9a8a7a, size: 0.14, transparent: true, opacity: 0.45, sizeAttenuation: true, fog: false });
      scene.add(new THREE.Points(starGeo, starMat));
    } catch (e) {
      log('[平行世界·3D] 星空粒子创建失败（不影响主功能）', e?.message || e);
    }

    // 星云背景球
    try {
      const tex = pwGraphMakeNebula(THREE);
      if (tex) PW_GRAPH.scene.add(new THREE.Mesh(new THREE.SphereGeometry(90, 32, 32), new THREE.MeshBasicMaterial({ map: tex, side: THREE.BackSide, fog: false })));
    } catch (e) {
      log('[平行世界·3D] 星云创建失败（不影响主功能）', e?.message || e);
    }

    // 网格地板
    try {
      const grid = new THREE.GridHelper(50, 25, 0x2a1a14, 0x1a120e);
      grid.position.y = -14;
      grid.material.transparent = true;
      grid.material.opacity = 0.12;
      grid.material.fog = true;
      PW_GRAPH.scene.add(grid);
    } catch {}

    PW_GRAPH.raycaster = new THREE.Raycaster();
    PW_GRAPH.pointer = new THREE.Vector2(-2, -2);
    // ✅ 初始化复用 scratch 向量，避免每帧分配
    PW_GRAPH._scratchVec = new THREE.Vector3();
    PW_GRAPH._scratchVec2 = new THREE.Vector3();
    PW_GRAPH._scratchVec3 = new THREE.Vector3();
    PW_GRAPH._scratchVec4 = new THREE.Vector3();
    PW_GRAPH._scratchVec5 = new THREE.Vector3();
    PW_GRAPH._meshArray = null;

    if (!PW_GRAPH.resizeBound) {
      PW_GRAPH.resizeBound = true;
      topWindow.addEventListener('resize', pwGraphOnResize);
      // 📱 移动端地址栏/键盘/旋转导致的可视区变化
      try { const vv = topWindow.visualViewport; if (vv) vv.addEventListener('resize', pwGraphOnResize); } catch {}
    }
  }

  function pwGraphOnResize() {
    if (!PW_GRAPH.overlay || !PW_GRAPH.renderer || !PW_GRAPH.camera) return;
    const { width: w, height: h } = pwGraphViewportSize();
    PW_GRAPH.renderer.setSize(w, h);
    PW_GRAPH.camera.aspect = w / h;
    PW_GRAPH.camera.updateProjectionMatrix();
    topWindow.setTimeout(() => pwGraphDebugLabels('resize', null, true), 100);
  }

  // 斐波那契球面分布：在半径 r 的球面上均匀分布第 i/total 个点
  function pwGraphFibSphere(i, total, r, THREE) {
    const phi = Math.acos(1 - 2 * (i + 0.5) / Math.max(1, total));
    const theta = Math.PI * (1 + Math.sqrt(5)) * (i + 0.5);
    return new THREE.Vector3(
      r * Math.sin(phi) * Math.cos(theta),
      r * Math.sin(phi) * Math.sin(theta),
      r * Math.cos(phi)
    );
  }

  // ✅ 统一的 NPC 名字匹配（精确 OR 双向 includes），读/写/清理共用，避免漂移
  function pwNpcNameMatches(id, name) {
    const s = String(id || '').trim();
    const n = String(name || '');
    if (!s || !n) return false;
    return s === n || n.includes(s) || s.includes(n);
  }

  // 事件正文里是否提及某 NPC（模糊：全名 / 按·分隔的片段 / 末 2 字简称）
  function pwNameInText(name, text) {
    const nm = String(name || '');
    const tx = String(text || '');
    if (!nm || !tx) return false;
    if (tx.includes(nm)) return true;
    const parts = nm.split(/[·•・\s\-_,.，。、]+/).filter(p => p.length >= 2);
    for (const p of parts) if (tx.includes(p)) return true;
    if (nm.length >= 3) { const tail = nm.slice(-2); if (tail.length === 2 && tx.includes(tail)) return true; }
    return false;
  }

  // ✅ 统一的事件-NPC 关联判定（避免 build 与 detail 两处重复逻辑漂移）
  function pwModuleLinkedToNpc(m, npcName) {
    const ids = Array.isArray(m?.linkedNpcIds) ? m.linkedNpcIds : [];
    const name = String(npcName || '');
    if (!name) return false;
    return ids.some(id => pwNpcNameMatches(id, name));
  }

  // ── 关联 NPC 名解析（linkedNpcIds -> NPC 名列表）──
  function pwGraphResolveLinkedNpcNames(m, npcs) {
    const ids = Array.isArray(m?.linkedNpcIds) ? m.linkedNpcIds : [];
    const names = [];
    for (const id of ids) {
      // 同时按 name 与 id 匹配，兼容 AI 用 id 而非名字填 linkedNpcIds 的情况
      const matched = npcs.filter(n => pwNpcNameMatches(id, n.name) || pwNpcNameMatches(id, n.id));
      if (matched.length) {
        for (const n of matched) { if (!names.includes(n.name)) names.push(n.name); }
      } else if (!names.includes(String(id))) {
        names.push(String(id));
      }
    }
    return names;
  }

  // ── 由 module 构建事件卡片数据 ──
  function pwGraphBuildEventData(m, data) {
    const npcs = data?.npcs || [];
    const linkedNpcNames = pwGraphResolveLinkedNpcNames(m, npcs);
    const imp = pwGetEffectiveImpactLevel(m);
    const showProg = pwShouldShowProgress(m);
    return {
      id: m.id,
      title: m.title || m.id,
      type: m.type || 'event',
      impact: imp,
      impactLabel: pwImpactLabel(imp),
      progress: showProg ? pwClampProgress(m.progress) : null,
      progressNote: m.progressNote || '',
      summary: m.summary || m.detail || '',
      linkedNpcs: linkedNpcNames,
      isDiceEvent: m.isDiceEvent === true,
      diceOutcome: m.diceOutcome || '',
      diceRoll: m.diceRoll,
      diceThreshold: m.diceThreshold,
      diceTension: m.diceTension,
      _cardType: 'event',
    };
  }

  // ── Canvas 工具 ──
  function pwGraphRoundRect(ctx, x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function pwGraphWrapCh(ctx, text, x, y, maxW, lh, maxLines) {
    if (!text) return 0;
    const ch = String(text).split('');
    let line = '', n = 0;
    for (let i = 0; i < ch.length; i++) {
      const t = line + ch[i];
      if (ctx.measureText(t).width > maxW && line) {
        ctx.fillText(line, x, y + n * lh);
        line = ch[i];
        n++;
        if (n >= maxLines - 1) {
          while (ctx.measureText(line + '…').width > maxW && line.length > 0) line = line.slice(0, -1);
          ctx.fillText(line + '…', x, y + n * lh);
          return (n + 1) * lh;
        }
      } else {
        line = t;
      }
    }
    if (line) { ctx.fillText(line, x, y + n * lh); n++; }
    return n * lh;
  }

  function pwGraphImpColor(im) {
    const lv = pwNormalizeImpactLevel(im, 'none');
    if (lv === 'critical') return '#ff2d2d';
    if (lv === 'high') return '#ff684a';
    if (lv === 'mid') return '#f0be5a';
    if (lv === 'low') return '#4cc850';
    return '#5d8f62';
  }

  function pwGraphImpProgColor(p) {
    if (p >= 100) return '#ff3030';
    if (p >= 75) return '#ff5a4a';
    if (p >= 40) return '#f0a070';
    if (p > 0) return '#9bd36a';
    return '#5d8f62';
  }

  // ── 缓动函数 ──
  function pwGraphEaseInOutCubic(x) {
    return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
  }

  // ── 计算卡片关联节点名集合（用于暗化非关联节点）──
  function pwGraphComputeCardLinkedNames(data, cardData) {
    const names = new Set();
    const npcs = data?.npcs || [];
    const relations = data?.npcRelations || [];
    const modules = data?.modules || [];

    if (cardData._cardType === 'player' || cardData.isPlayer) {
      npcs.filter(n => pwResolveNpcAttitudeLevel(n) >= 0).forEach(n => names.add(n.name));
    } else if (cardData._cardType === 'npc') {
      names.add(cardData.name);
      relations.filter(r => r.from === cardData.name || r.to === cardData.name)
        .forEach(r => names.add(r.from === cardData.name ? r.to : r.from));
      modules.filter(m => pwModuleLinkedToNpc(m, cardData.name))
        .forEach(m => pwGraphResolveLinkedNpcNames(m, npcs).forEach(n => names.add(n)));
    } else {
      (cardData.linkedNpcs || []).forEach(n => names.add(n));
      modules.filter(m => m.id !== cardData.id &&
        pwGraphResolveLinkedNpcNames(m, npcs).some(n => (cardData.linkedNpcs || []).includes(n)))
        .forEach(m => pwGraphResolveLinkedNpcNames(m, npcs).forEach(n => names.add(n)));
    }
    return names;
  }

  // ── 节点网格构建 ──
  // 由 NPC 名字生成稳定的唯一身份色（HSL->rgb 字符串），用于给每个角色球一个与众不同的外环色，
  // 避免看法趋同时整片同色无法区分。
  function pwNameHueRgb(name) {
    const h = (pwHashSeed(name) % 360) / 360;
    const s = 0.62, l = 0.6;
    const c = (1 - Math.abs(2 * l - 1)) * s;
    const x = c * (1 - Math.abs((h * 6) % 2 - 1));
    const m = l - c / 2;
    let r = 0, g = 0, b = 0;
    const i = Math.floor(h * 6);
    if (i === 0) { r = c; g = x; } else if (i === 1) { r = x; g = c; }
    else if (i === 2) { g = c; b = x; } else if (i === 3) { g = x; b = c; }
    else if (i === 4) { r = x; b = c; } else { r = c; b = x; }
    return `rgb(${Math.round((r + m) * 255)},${Math.round((g + m) * 255)},${Math.round((b + m) * 255)})`;
  }

  function pwGraphMakeNodeMesh(THREE, radius, colorStr, isPlayer, ringColorStr) {
    const color = new THREE.Color(colorStr), r = Math.max(0.1, radius);
    const ringColor = ringColorStr ? new THREE.Color(ringColorStr) : color;
    const core = new THREE.Mesh(
      new THREE.SphereGeometry(r, 64, 64),
      new THREE.MeshBasicMaterial({ color, fog: false })
    );
    const glow1 = new THREE.Mesh(
      new THREE.SphereGeometry(r * 1.3, 32, 32),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.18, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    const glow2 = new THREE.Mesh(
      new THREE.SphereGeometry(r * 1.7, 24, 24),
      new THREE.MeshBasicMaterial({ color: ringColor, transparent: true, opacity: 0.07, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(r * (isPlayer ? 2.2 : 1.9), Math.max(0.015, r * 0.04), 8, 48),
      new THREE.MeshBasicMaterial({ color: ringColor, transparent: true, opacity: isPlayer ? 0.35 : 0.55, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    ring.rotation.x = Math.PI / 2 + (Math.random() - 0.5) * 0.6;
    ring.rotation.z = (Math.random() - 0.5) * 0.4;
    return { core, glow1, glow2, ring };
  }

  // ── 事件珠子网格构建 ──
  function pwGraphMakeBeadMesh(THREE, colorStr) {
    const color = new THREE.Color(colorStr);
    const core = new THREE.Mesh(
      new THREE.IcosahedronGeometry(0.3, 1),
      new THREE.MeshBasicMaterial({ color, fog: false })
    );
    const glow = new THREE.Mesh(
      new THREE.SphereGeometry(0.5, 16, 16),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.22, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    return { core, glow };
  }

  // 移动端部分浏览器不会把 HTML 标签合成到 WebGL 画布上，改用同场景 Sprite 显示名字。
  function pwGraphMakeMobileLabelSprite(THREE, name, dotColor, ringColor) {
    const c = topDoc.createElement('canvas');
    const ctx = c.getContext('2d');
    const text = String(name || '');
    ctx.font = '600 24px sans-serif';
    const textW = Math.ceil(ctx.measureText(text).width);
    c.width = Math.max(96, Math.min(512, textW + 58));
    c.height = 54;
    ctx.fillStyle = 'rgba(14,12,14,0.92)';
    pwGraphRoundRect(ctx, 1, 1, c.width - 2, c.height - 2, 18);
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.16)';
    ctx.lineWidth = 2;
    pwGraphRoundRect(ctx, 1, 1, c.width - 2, c.height - 2, 18);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(22, c.height / 2, 7, 0, Math.PI * 2);
    ctx.fillStyle = dotColor;
    ctx.fill();
    ctx.strokeStyle = ringColor;
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.fillStyle = '#e8ddd4';
    ctx.font = '600 24px sans-serif';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, 38, c.height / 2 + 1);
    const texture = new THREE.CanvasTexture(c);
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;
    const material = new THREE.SpriteMaterial({ map: texture, transparent: true, depthTest: false, depthWrite: false });
    const sprite = new THREE.Sprite(material);
    sprite.renderOrder = 1000;
    sprite.visible = false;
    sprite.userData = { pixelWidth: c.width / 2, pixelHeight: c.height / 2 };
    return sprite;
  }

  // ── 添加事件珠子（+ 到各关联角色的"辐条"连线，让多关联事件也 visibly 链接，不再悬空）──
  function pwGraphAddBead(THREE, evt, pos, fm, tm, spokeMeshes) {
    const cs = pwGraphImpColor(evt.impact || 'low');
    const m = pwGraphMakeBeadMesh(THREE, cs);
    m.core.position.copy(pos);
    m.glow.position.copy(pos);
    m.core.userData = { isBead: true, evt, fromMesh: fm, toMesh: tm };
    PW_GRAPH.group.add(m.core);
    PW_GRAPH.group.add(m.glow);
    const spokes = [];
    if (Array.isArray(spokeMeshes) && spokeMeshes.length) {
      const spokeColor = new THREE.Color(cs);
      for (const sm of spokeMeshes) {
        if (!sm || sm === m.core) continue;
        try {
          const g = new THREE.BufferGeometry().setFromPoints([m.core.position, sm.position]);
          const line = new THREE.Line(g, new THREE.LineBasicMaterial({ color: spokeColor, transparent: true, opacity: 0.34, depthWrite: false }));
          PW_GRAPH.group.add(line);
          spokes.push(line);
        } catch {}
      }
    }
    PW_GRAPH.beads.push({ mesh: m.core, glow: m.glow, evt, fromMesh: fm, toMesh: tm, tier: evt.tier || 'low', baseOpacity: 0.22, phase: Math.random() * Math.PI * 2, spokes });
  }

  // ── 计算关联事件 ID 集合 ──
  function pwGraphComputeRelatedEvents(evtId, data) {
    const modules = data?.modules || [];
    const npcs = data?.npcs || [];
    const evt = modules.find(m => m.id === evtId);
    if (!evt) return new Set();
    const ls = new Set(pwGraphResolveLinkedNpcNames(evt, npcs));
    const r = new Set([evtId]);
    for (const m of modules) {
      if (m.id === evtId) continue;
      const names = pwGraphResolveLinkedNpcNames(m, npcs);
      if (names.some(n => ls.has(n))) r.add(m.id);
    }
    return r;
  }

  // ==================== 📖 主角简介（AI 根据世界状态生成）====================
  // 缓存在 data.playerIntro，按数据签名失效；AI 失败时用兜底合成文本，保证卡片永远有内容。

  // 数据签名：turn / 世界钟 / 全部 NPC 名+对主角看法 / 前 8 个事件 id。任一变化即视为过期。
  function pwGraphPlayerIntroSig(data) {
    const npcs = data?.npcs || [];
    const mods = (data?.modules || []).slice().sort((a, b) => String(a.id || '').localeCompare(String(b.id || '')));
    return [
      data?.turn || 0,
      data?.worldClock || '',
      npcs.map(n => n.name + ':' + pwResolveNpcAttitudeLevel(n)).sort().join(','),
      mods.slice(0, 8).map(m => m.id || m.title).join(','),
    ].join('|');
  }

  // 兜底简介（AI 不可用时用），纯文本拼装，保证卡片不空。
  function pwGraphSynthPlayerIntro(data) {
    const name = pwGraphGetPlayerName();
    const npcs = data?.npcs || [];
    const att = (n) => pwResolveNpcAttitudeLevel(n);
    const friendly = npcs.filter(n => att(n) >= 60).map(n => n.name);
    const hostile = npcs.filter(n => { const a = att(n); return a >= 0 && a < 40; }).map(n => n.name);
    const known = npcs.filter(n => att(n) >= 0).length;
    const title = data?.globalState?.title || '';
    const clock = data?.worldClock || '';
    const parts = [];
    parts.push(`${name}${title ? '身处「' + title + '」' : '身处当前世界'}${clock ? '（' + clock + '）' : ''}。`);
    if (friendly.length) parts.push(`与${friendly.slice(0, 4).join('、')}关系亲近；`);
    if (hostile.length) parts.push(`与${hostile.slice(0, 4).join('、')}势成水火；`);
    parts.push(`已结识 ${known} 位角色。`);
    const evts = (data?.modules || []).map(m => ({ t: m.title, imp: pwGetEffectiveImpactLevel(m) }))
      .sort((a, b) => pwImpactRank(b.imp) - pwImpactRank(a.imp)).slice(0, 2);
    if (evts.length) parts.push(`眼下「${evts.map(e => e.t).join('」「')}」正在酝酿。`);
    return parts.join('');
  }

  // 调用主模型生成主角简介（suppress 主线注入 + quiet，避免触发平行世界/狐忆自动更新）
  async function pwGraphGeneratePlayerIntro(data) {
    const name = pwGraphGetPlayerName();
    const npcs = data?.npcs || [];
    const att = (n) => pwResolveNpcAttitudeLevel(n);
    const friendly = npcs.filter(n => att(n) >= 60).map(n => `${n.name}(${att(n)})`);
    const neutral = npcs.filter(n => { const a = att(n); return a >= 40 && a < 60; }).map(n => `${n.name}(${att(n)})`);
    const hostile = npcs.filter(n => { const a = att(n); return a >= 1 && a < 40; }).map(n => `${n.name}(${att(n)})`);
    const rupture = npcs.filter(n => att(n) === 0).map(n => n.name);
    const unknown = npcs.filter(n => att(n) < 0).map(n => n.name);
    const evts = (data?.modules || [])
      .map(m => ({ t: m.title || m.id, imp: pwGetEffectiveImpactLevel(m), s: (m.summary || m.detail || '').slice(0, 60) }))
      .sort((a, b) => pwImpactRank(b.imp) - pwImpactRank(a.imp)).slice(0, 6);
    const rep = data?.factionReputation || {};
    const repLine = Object.keys(rep).length ? `势力声望：${Object.keys(rep).map(k => `${k}:${rep[k]}`).join('，')}` : '';

    const worldLine = [
      data?.worldClock ? `剧情时间：${data.worldClock}` : '',
      data?.turn ? `第${data.turn}轮` : '',
      data?.globalState?.title ? `世界状态：${data.globalState.title}` : '',
      data?.globalState?.detail ? `状态简述：${data.globalState.detail}` : '',
    ].filter(Boolean).join('\n');
    const npcLine = [
      friendly.length ? `亲近主角：${friendly.join('、')}` : '',
      neutral.length ? `中立：${neutral.join('、')}` : '',
      hostile.length ? `敌对主角：${hostile.join('、')}` : '',
      rupture.length ? `已决裂：${rupture.join('、')}` : '',
      unknown.length ? `尚未结识：${unknown.join('、')}` : '',
    ].filter(Boolean).join('\n');
    const evtLine = evts.length ? evts.map(e => `· ${e.t}（${pwImpactLabel(e.imp)}）${e.s ? '：' + e.s : ''}`).join('\n') : '（暂无事件）';

    const system = `你是沉浸式小说的世界观旁白。请根据下面的「平行世界」状态快照，为故事的主角写一段**当前处境简介**。\n\n要求：\n1. 用第二人称「你」称呼主角（主角名：${name}）。\n2. 80～160 字，一段连贯的叙述，不分点、不列数据。\n3. 点出主角此刻的处境、最关键的人际张力（谁亲近、谁威胁）、迫近的危机或机遇。\n4. 文学化、有画面感，不要解释这是在做什么，不要出现「简介」「根据状态」等元描述。\n5. 只输出简介正文，不要标题、不要引号、不要多余说明。`;
    const user = `主角名：${name}\n\n${worldLine}\n\n${npcLine}\n\n当前关键事件：\n${evtLine}\n${repLine}\n\n请为主角 ${name} 写一段当前处境简介。`;

    const r = await ssGenerateRaw('parallel_world_player_intro', {
      user_input: user,
      should_silence: true,
      should_stream: false,
      max_chat_history: 0,
      ordered_prompts: [{ role: 'system', content: system }, 'user_input'],
    }, '平行世界主角简介');
    const t = foxJudgeExtractText(r).trim();
    // 去掉可能的 <think> 包裹与前缀标题，保持纯正文
    const cleaned = t.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/^(简介|主角简介|介绍|主角介绍)[:：]?\s*/i, '').trim();
    if (!cleaned) throw new Error('AI 返回为空');
    return cleaned;
  }

  // 确保主角简介就绪：缓存命中直接返回；否则异步生成（AI 失败回退兜底），完成后就地重绘卡片。
  async function pwGraphEnsurePlayerIntro(data, force) {
    if (!data) return;
    const sig = pwGraphPlayerIntroSig(data);
    if (!force && data.playerIntro && data.playerIntro.sig === sig && data.playerIntro.text) return;
    if (data._introGenerating) return; // 防并发重复生成
    data._introGenerating = true;
    try {
      let text;
      try { text = await pwGraphGeneratePlayerIntro(data); }
      catch (e) { log('[平行世界·3D] 主角简介 AI 生成失败，使用兜底', e?.message || e); text = ''; }
      if (!text) text = pwGraphSynthPlayerIntro(data);
      data.playerIntro = { text, sig, at: Date.now() };
      // 安全落盘：重新读取最新数据再只合并 playerIntro，避免生成期间世界被推进/刷新后
      //   把新数据（新轮次/NPC/事件）整体回退成旧快照。
      try {
        const _cur = pwLoadData();
        _cur.playerIntro = data.playerIntro;
        pwSaveData(_cur);
      } catch {}
      if (PW_GRAPH.cardActive && PW_GRAPH.cardData && (PW_GRAPH.cardData._cardType === 'player' || PW_GRAPH.cardData.isPlayer)) {
        pwGraphRedrawCard();
      }
    } finally {
      data._introGenerating = false;
    }
  }

  // ── 由数据构建节点 + 连线 + 珠子（按地点圆周布局）──
  function pwGraphBuildFromData(data) {
    const THREE = PW_GRAPH.THREE;
    if (!THREE || !PW_GRAPH.group) return;
    PW_GRAPH.lastData = data;

    // 清空旧节点/连线/珠子
    for (const nm of PW_GRAPH.nodeMeshes) {
      for (const m of [nm.mesh, nm.glow1, nm.glow2, nm.ring]) {
        try { if (m) { PW_GRAPH.group.remove(m); m.geometry?.dispose?.(); m.material?.dispose?.(); } } catch {}
      }
      try {
        if (nm.labelSprite) {
          PW_GRAPH.scene.remove(nm.labelSprite);
          nm.labelSprite.material?.map?.dispose?.();
          nm.labelSprite.material?.dispose?.();
        }
      } catch {}
      try { nm.labelDiv?.remove?.(); } catch {}
    }
    for (const e of PW_GRAPH.edges) {
      try { PW_GRAPH.group.remove(e.line); e.line.geometry?.dispose?.(); e.line.material?.dispose?.(); } catch {}
    }
    for (const b of PW_GRAPH.beads) {
      for (const m of [b.mesh, b.glow]) {
        try { if (m) { PW_GRAPH.group.remove(m); m.geometry?.dispose?.(); m.material?.dispose?.(); } } catch {}
      }
      for (const sp of (b.spokes || [])) {
        try { PW_GRAPH.group.remove(sp); sp.geometry?.dispose?.(); sp.material?.dispose?.(); } catch {}
      }
    }
    PW_GRAPH.nodeMeshes = [];
    PW_GRAPH.edges = [];
    PW_GRAPH.beads = [];
    PW_GRAPH.focusMesh = null;
    PW_GRAPH.hovered = null;

    // 灯光（MeshStandardMaterial 需要，仅添加一次）
    if (!PW_GRAPH._lightsAdded) {
      PW_GRAPH._lightsAdded = true;
      PW_GRAPH.scene.add(new THREE.AmbientLight(0x4a3a2a, 0.6));
      const pl = new THREE.PointLight(0xf0a070, 1.2, 40, 1.5); pl.position.set(0, 0, 0); PW_GRAPH.scene.add(pl);
      const fl = new THREE.PointLight(0x4a6a8a, 0.4, 50, 2); fl.position.set(10, 8, 12); PW_GRAPH.scene.add(fl);
    }

    // ✅ 按名字去重 NPC：避免数据里同名角色出现多颗重复球（含历史残留）
    const _npcsRaw = Array.isArray(data?.npcs) ? data.npcs : [];
    const _seenNpcName = new Set();
    const npcs = [];
    for (const _n of _npcsRaw) {
      const _nm = String(_n?.name || '').trim();
      if (!_nm || _seenNpcName.has(_nm)) continue;
      _seenNpcName.add(_nm);
      npcs.push(_n);
    }
    const relations = Array.isArray(data?.npcRelations) ? data.npcRelations : [];
    const modules = Array.isArray(data?.modules) ? data.modules : [];
    const playerName = pwGraphGetPlayerName();

    // 🎨 非颜色区分维度：每个 NPC 的关系连接数（连接越多球越大，作为"中心度"的体积 cue）
    const connCount = new Map();
    for (const n of npcs) connCount.set(n.name, 0);
    for (const r of relations) {
      if (connCount.has(r.from)) connCount.set(r.from, connCount.get(r.from) + 1);
      if (connCount.has(r.to)) connCount.set(r.to, connCount.get(r.to) + 1);
    }

    // ── 按地点分组 NPC，所有角色（含主角）排在圆周上，无中心 ──
    const locMap = new Map();
    for (const n of npcs) {
      const loc = n.location || '未知地点';
      if (!locMap.has(loc)) locMap.set(loc, []);
      locMap.get(loc).push(n);
    }
    const allLocs = [...locMap.keys()];
    const numLocs = allLocs.length;
    const totalSlots = numLocs + 1;
    const mapR = Math.max(10, totalSlots * 2.8);

    // 主角在圆周 slot 0（不在中心，和 NPC 平等）
    const playerPos = new THREE.Vector3(mapR, 0, 0);
    const pm = pwGraphMakeNodeMesh(THREE, 1.3, '#f0a070', true);
    pm.core.position.copy(playerPos); pm.glow1.position.copy(playerPos); pm.glow2.position.copy(playerPos); pm.ring.position.copy(playerPos);
    pm.core.userData = { isPlayer: true, name: playerName };
    PW_GRAPH.group.add(pm.core); PW_GRAPH.group.add(pm.glow1); PW_GRAPH.group.add(pm.glow2); PW_GRAPH.group.add(pm.ring);
    PW_GRAPH.nodeMeshes.push({ mesh: pm.core, glow1: pm.glow1, glow2: pm.glow2, ring: pm.ring, labelDiv: null, isPlayer: true, name: playerName, npc: null, ringRot: Math.random() * Math.PI * 2 });

    // 各地点在圆周 slot 1..N
    const locPos = new Map();
    allLocs.forEach((loc, i) => {
      const ang = ((i + 1) / totalSlots) * Math.PI * 2;
      const yVar = Math.sin(i * 2.3) * 1.5;
      locPos.set(loc, new THREE.Vector3(mapR * Math.cos(ang), yVar, mapR * Math.sin(ang)));
    });

    // NPC 节点：在各地点周围聚集
    const meshByName = new Map();
    const makeNpcNode = (n, pos) => {
      const al = pwResolveNpcAttitudeLevel(n);
      const el = pwClampEmotionLevel(n.emotionLevel != null && n.emotionLevel !== '' ? n.emotionLevel : 50);
      const cs = al < 0 ? 'rgb(136,136,136)' : pwAttitudeLevelColor(al);
      // 🎨 区分方案：核心色=看法(语义)，外环色=名字身份色(每人不同)；体积=连接数(非颜色 cue)
      const sizeBase = al < 0 ? 0.5 : 0.6;
      const size = sizeBase + Math.min(connCount.get(n.name) || 0, 4) * 0.07;
      const m = pwGraphMakeNodeMesh(THREE, size, cs, false, pwNameHueRgb(n.name));
      m.core.position.copy(pos); m.glow1.position.copy(pos); m.glow2.position.copy(pos); m.ring.position.copy(pos);
      m.core.userData = { isPlayer: false, name: n.name, npc: n };
      PW_GRAPH.group.add(m.core); PW_GRAPH.group.add(m.glow1); PW_GRAPH.group.add(m.glow2); PW_GRAPH.group.add(m.ring);
      const labelDiv = topDoc.createElement('div');
      labelDiv.className = 'pw-graph-label';
      const idColor = pwNameHueRgb(n.name);
      labelDiv.innerHTML = `<span class="pw-graph-label-dot" style="background:${cs};box-shadow:0 0 0 2px ${idColor};color:${cs};"></span><span class="pw-graph-label-name">${escapeHtml(n.name)}</span>`;
      labelDiv.style.cursor = 'pointer';
      labelDiv.onclick = (e) => {
        e.stopPropagation();
        pwGraphShowCard({ ...n, attitudeLevel: al, emotionLevel: el, _cardType: 'npc' }, m.core, PW_GRAPH.lastData || data);
      };
      PW_GRAPH.labelLayer.appendChild(labelDiv);
      const labelSprite = pwGraphMakeMobileLabelSprite(THREE, n.name, cs, idColor);
      PW_GRAPH.scene.add(labelSprite);
      PW_GRAPH.nodeMeshes.push({ mesh: m.core, glow1: m.glow1, glow2: m.glow2, ring: m.ring, labelDiv, labelSprite, isPlayer: false, name: n.name, npc: n, ringRot: Math.random() * Math.PI * 2 });
      return m.core;
    };
    for (const [loc, locNpcs] of locMap) {
      const lp = locPos.get(loc);
      const cr = Math.max(1.2, locNpcs.length * 0.6);
      locNpcs.forEach((n, i) => {
        const ang = (i / Math.max(locNpcs.length, 1)) * Math.PI * 2;
        const pos = lp.clone().add(new THREE.Vector3(cr * Math.cos(ang), 0, cr * Math.sin(ang)));
        meshByName.set(n.name, makeNpcNode(n, pos));
      });
    }

    // ── 连线 ──
    const makeEdge = (fm, tm, level) => {
      if (!fm || !tm) return;
      const geo = new THREE.BufferGeometry().setFromPoints([fm.position, tm.position]);
      let c, o;
      if (level == null || level < 0) { c = 'rgb(90,100,120)'; o = 0.18; }
      else { c = pwAttitudeLevelColor(level); o = level === 0 ? 0.6 : 0.2 + Math.abs(level - 50) / 50 * 0.35; }
      const line = new THREE.Line(geo, new THREE.LineBasicMaterial({ color: new THREE.Color(c), transparent: true, opacity: o }));
      PW_GRAPH.group.add(line);
      PW_GRAPH.edges.push({ line, fromMesh: fm, toMesh: tm, level });
    };
    // 主角 <-> NPC（attitudeLevel >= 0）
    const playerMeshRef = PW_GRAPH.nodeMeshes[0].mesh;
    for (const nm of PW_GRAPH.nodeMeshes) {
      if (nm.isPlayer) continue;
      const al = pwResolveNpcAttitudeLevel(nm.npc);
      if (al >= 0) makeEdge(playerMeshRef, nm.mesh, al);
    }
    // NPC <-> NPC（按关系）
    for (const r of relations) {
      const fm = meshByName.get(r.from);
      const tm = meshByName.get(r.to);
      if (!fm || !tm) continue;
      const rl = (r.relationLevel != null && r.relationLevel !== '') ? pwClampRelationLevel(r.relationLevel) : null;
      const level = rl != null && rl >= 0 ? rl : (r.valence && r.valence !== 'unknown' ? (r.valence === 'rupture' ? 0 : r.valence === 'hostile' ? 25 : r.valence === 'neutral' ? 50 : r.valence === 'friendly' ? 75 : null) : null);
      if (level == null) continue;
      makeEdge(fm, tm, level);
    }

    // ⚠️ 已移除"幽灵节点"逻辑：旧版用 /^(.{2,8}?)的/ 从事件标题里抠出"X的Y"前缀当角色名，
    //   会把"未曾停歇的寻找"误判成角色"未曾停歇"并建一个角色球，导致事件被识别成人物星球。
    //   现在事件珠子只串在真实存在的角色之间/球上方，不再凭标题造角色。

    // ── 事件珠子：每个事件只产生一颗珠子，杜绝重复 ──
    //  · 关联 2 个角色  -> 串在两人连线段中点（同段多事件沿线段错开）
    //  · 关联 3+ 角色   -> 单颗珠子置于所有关联角色质心（不再每对都生成，杜绝重复事件球）
    //  · 关联 1 个角色  -> 该角色球正上方（不再串到主角线上，保证落在球上而非悬空）
    //  · 无关联角色     -> 主角球正上方
    const beadTurn = data.turn || 0;
    const pairCount = new Map();      // 同一对角色之间已放置珠子数，沿线段错开
    const singleCount = new Map();    // 同一角色球上方已放置珠子数，环绕错开
    const centroidCount = new Map();  // 同一组关联角色已放置珠子数，径向错开
    const pairKey = (a, b) => (a < b ? a + '|' + b : b + '|' + a);
    const sigKey = (names) => names.slice().sort().join('|');
    let _orphanIdx = 0;
    for (const m of modules) {
      // 仅取真实存在节点网格的角色名；去重，杜绝重复关联
      let linked = pwGraphResolveLinkedNpcNames(m, npcs).filter(nm => meshByName.has(nm));
      linked = [...new Set(linked)];
      // 轻量兜底：仅在 AI 完全没填关联时，按事件正文里出现的「全名」补一个关联角色，
      //   不再用末2字/片段模糊匹配，避免把事件错配到无关角色导致珠子乱飘。
      if (linked.length === 0) {
        const _txt = `${m?.summary || ''} ${m?.detail || ''} ${m?.title || ''}`;
        if (_txt.trim()) {
          for (const _n of npcs) {
            const _nm = String(_n?.name || '').trim();
            if (_nm && meshByName.has(_nm) && !linked.includes(_nm) && _txt.includes(_nm)) {
              linked.push(_nm);
              break;
            }
          }
        }
      }
      // ✅ 关联角色网格数组：用于给事件珠子画"辐条"连线，让多关联事件也 visibly 链接到所有角色
      const linkedMeshes = linked.map(n => meshByName.get(n)).filter(Boolean);
      try { console.log('[平行世界]', String(m.title || m.id).slice(0, 24), '| 关联', linked.length, '人:', linked.slice(0, 4).join(',')); } catch {}
      const evt = pwGraphBuildEventData(m, data);
      evt.tier = pwTierOfModule(m, beadTurn);

      if (linked.length === 0) {
        // 无关联角色：主角球正上方，黄金角错开避免重叠（无辐条）
        const pos = playerMeshRef.position.clone();
        const ang = _orphanIdx * 2.39996;
        pos.x += Math.cos(ang) * (0.45 + Math.floor(_orphanIdx / 5) * 0.22);
        pos.z += Math.sin(ang) * (0.45 + Math.floor(_orphanIdx / 5) * 0.22);
        pos.y += 1.7 + (_orphanIdx % 4) * 0.32;
        pwGraphAddBead(THREE, evt, pos, null, null, null);
        _orphanIdx++;
      } else if (linked.length === 1) {
        // 关联 1 个角色：该角色球正上方，环绕错开，辐条连到该角色
        const mesh = meshByName.get(linked[0]);
        if (mesh) {
          const cnt = singleCount.get(linked[0]) || 0;
          singleCount.set(linked[0], cnt + 1);
          const ang = cnt * 2.39996;
          const pos = mesh.position.clone();
          const layer = Math.floor(cnt / 6);
          const ringR = 0.55 + layer * 0.28;
          pos.x += Math.cos(ang) * ringR;
          pos.z += Math.sin(ang) * ringR;
          pos.y += 1.25 + (cnt % 6) * 0.24 + layer * 0.25;
          pwGraphAddBead(THREE, evt, pos, mesh, null, linkedMeshes);
        } else {
          const pos = (playerMeshRef?.position || new THREE.Vector3()).clone(); pos.y += 1.7; pwGraphAddBead(THREE, evt, pos, null, null, null);
          _orphanIdx++;
        }
      } else if (linked.length === 2) {
        // 关联 2 个角色：串在两人连线段上，沿线段错开（多事件像项链珠子），辐条连到两人
        const fm = meshByName.get(linked[0]);
        const tm = meshByName.get(linked[1]);
        if (fm && tm) {
          const key = pairKey(linked[0], linked[1]);
          const cnt = pairCount.get(key) || 0;
          pairCount.set(key, cnt + 1);
          const off = cnt === 0 ? 0 : (Math.ceil((cnt % 8) / 2) * 0.14 * (cnt % 2 ? 1 : -1));
          const tt = Math.max(0.2, Math.min(0.8, 0.5 + off));
          const mid = fm.position.clone().lerp(tm.position, tt);
          mid.y += Math.floor(cnt / 8) * 0.34;
          pwGraphAddBead(THREE, evt, mid, fm, tm, linkedMeshes);
        } else {
          // 退化：两个关联名只有一个能找到节点 -> 退到单球上方
          const mesh = fm || tm;
          if (mesh) {
            const nm0 = mesh === fm ? linked[0] : linked[1];
            const cnt = singleCount.get(nm0) || 0; singleCount.set(nm0, cnt + 1);
            const pos = mesh.position.clone(); pos.y += 1.25 + cnt * 0.3; pwGraphAddBead(THREE, evt, pos, mesh, null, linkedMeshes);
          } else {
            const pos = (playerMeshRef?.position || new THREE.Vector3()).clone(); pos.y += 1.7; pwGraphAddBead(THREE, evt, pos, null, null, null); _orphanIdx++;
          }
        }
      } else {
        // 关联 3+ 角色：单颗珠子置于所有关联角色质心，径向错开，辐条连到每个角色（多线段链接，不再悬空）
        const meshes = linked.map(n => meshByName.get(n)).filter(Boolean);
        if (meshes.length >= 2) {
          const key = sigKey(linked);
          const cnt = centroidCount.get(key) || 0;
          centroidCount.set(key, cnt + 1);
          const centroid = new THREE.Vector3();
          for (const mm of meshes) centroid.add(mm.position);
          centroid.multiplyScalar(1 / meshes.length);
          const ang = cnt * 2.39996;
          const radius = 0.32 + Math.floor(cnt / 6) * 0.28;
          centroid.x += Math.cos(ang) * radius;
          centroid.z += Math.sin(ang) * radius;
          centroid.y += Math.sin(cnt * 1.7) * 0.18 + Math.floor(cnt / 6) * 0.24;
          pwGraphAddBead(THREE, evt, centroid, meshes[0], meshes[1], linkedMeshes);
        } else {
          const mesh = meshes[0];
          if (mesh) { const pos = mesh.position.clone(); pos.y += 1.25; pwGraphAddBead(THREE, evt, pos, mesh, null, linkedMeshes); }
          else { const pos = (playerMeshRef?.position || new THREE.Vector3()).clone(); pos.y += 1.7; pwGraphAddBead(THREE, evt, pos, null, null, null); _orphanIdx++; }
        }
      }
    }

    PW_GRAPH._meshArray = PW_GRAPH.nodeMeshes.map(n => n.mesh);
    PW_GRAPH._beadArray = PW_GRAPH.beads.map(b => b.mesh);
    const scenePoints = [
      ...PW_GRAPH.nodeMeshes.map(n => n.mesh.position),
      ...PW_GRAPH.beads.map(b => b.mesh.position),
    ];
    let sceneRadius = mapR + 3;
    for (const point of scenePoints) sceneRadius = Math.max(sceneRadius, point.length() + 1.5);
    const aspect = Math.max(0.2, PW_GRAPH.camera?.aspect || 1);
    const verticalFov = ((PW_GRAPH.camera?.fov || 55) * Math.PI) / 180;
    const horizontalFov = 2 * Math.atan(Math.tan(verticalFov / 2) * aspect);
    const fitFov = Math.max(0.2, Math.min(verticalFov, horizontalFov));
    PW_GRAPH.overviewCamDist = Math.max(22, sceneRadius / Math.sin(fitFov / 2) * 1.08);
    PW_GRAPH.maxCamDist = Math.max(45, PW_GRAPH.overviewCamDist + 12);
    PW_GRAPH.camDistTarget = PW_GRAPH.overviewCamDist;
    log('[平行世界·3D网格] 构建: ' + PW_GRAPH.nodeMeshes.length + '节点 ' + PW_GRAPH.edges.length + '连线 ' + PW_GRAPH.beads.length + '珠子');
    topWindow.requestAnimationFrame(() => pwGraphDebugLabels('labels-built', null, true));
  }

  // ── 3D 卡片纹理绘制 ──
  function pwGraphDrawCardTexture(data, playerName, fullData, cardWidth) {
    const W = cardWidth || 640, H = 2048;
    const DPR = 2;
    const c = topDoc.createElement('canvas');
    c.width = W * DPR; c.height = H * DPR;
    const ctx = c.getContext('2d');
    ctx.scale(DPR, DPR);
    const hotZones = [];
    c.hotZones = hotZones;
    c.logicalWidth = W;
    const _c = ssGetUiMode() === 'classic';
    const _e = (s) => '';
    const _acc = _c ? '#f0a070' : '#d4a87a';
    const _frameBg = _c ? 'rgba(14,10,12,0.94)' : 'rgba(13,12,16,0.95)';
    const _frameBd = _c ? 'rgba(232,120,74,0.28)' : 'rgba(212,168,122,0.22)';
    const _frameBd2 = _c ? 'rgba(232,120,74,0.08)' : 'rgba(212,168,122,0.06)';

