  function pwGraphShowCard(data, targetMesh, fullData, opts = {}) {
    if (!PW_GRAPH.THREE || !PW_GRAPH.scene || !PW_GRAPH.camera) return;
    if ((data?._cardType === 'player' || data?.isPlayer) && fullData) {
      // 异步生成主角简介，完成后就地重绘卡片（桌面/移动端共用此入口）
