    PW_GRAPH.selectedEvtId = null; PW_GRAPH.relatedEvtIds = null;
    PW_GRAPH.cardActive = false; PW_GRAPH.cardSwingT = 0;
    PW_GRAPH.cardPinned = false;
    PW_GRAPH.cardHoverNode = null;
    if (PW_GRAPH._hoverCardTimer) { try { topWindow.clearTimeout(PW_GRAPH._hoverCardTimer); } catch {} PW_GRAPH._hoverCardTimer = null; }
    PW_GRAPH.overlay?.classList.remove('pw-graph-card-active');
    if (shouldRestoreAutoRotate) PW_GRAPH.autoRotate = PW_GRAPH.cardAutoRotateBeforeOpen;
    PW_GRAPH.cardAutoRotateBeforeOpen = false;
