  }

  // ── 就地重绘卡片纹理（不重置摇镜，用于主角卡折叠/展开）──
  function pwGraphRedrawCard() {
    if (PW_GRAPH.cardOverlay2D) {
      // 📱 移动端 2D 重绘
      try {
        const canvas = pwGraphDrawCardTexture(PW_GRAPH.cardData, pwGraphGetPlayerName(), PW_GRAPH.cardFullData, 440);
        const cv = PW_GRAPH.cardOverlay2D.querySelector('canvas');
        if (cv) { cv.width = canvas.width; cv.height = canvas.height; cv.getContext('2d').drawImage(canvas, 0, 0); }
        PW_GRAPH.cardHotZones = canvas.hotZones || [];
        PW_GRAPH.cardContentH = canvas.contentHeight || 860;
        PW_GRAPH.cardLinkedNames = pwGraphComputeCardLinkedNames(PW_GRAPH.cardFullData, PW_GRAPH.cardData);
      } catch (e) { log('[平行世界·3D] 重绘2D卡片失败', e?.message || e); }
      return;
    }
    if (!PW_GRAPH.cardMesh || !PW_GRAPH.cardData || !PW_GRAPH.THREE) return;
    try {
      const THREE = PW_GRAPH.THREE;
      const canvas = pwGraphDrawCardTexture(PW_GRAPH.cardData, pwGraphGetPlayerName(), PW_GRAPH.cardFullData);
      const tex = new THREE.CanvasTexture(canvas); tex.minFilter = THREE.LinearFilter; tex.magFilter = THREE.LinearFilter; tex.generateMipmaps = false;
      if (PW_GRAPH.cardMesh.material.map) PW_GRAPH.cardMesh.material.map.dispose();
      PW_GRAPH.cardMesh.material.map = tex;
      PW_GRAPH.cardMesh.material.needsUpdate = true;
      // 📐 内容高度变化 -> 同步更新卡片平面与光晕尺寸，避免拉伸
      const cardW = PW_GRAPH.cardW || 3.6;
      const cardH = cardW * (canvas.contentHeight || 860) / 640;
      PW_GRAPH.cardH = cardH; PW_GRAPH.cardContentH = canvas.contentHeight || 860;
      PW_GRAPH.cardMesh.geometry.dispose();
      PW_GRAPH.cardMesh.geometry = new THREE.PlaneGeometry(cardW, cardH);
      if (PW_GRAPH.cardGlow) { PW_GRAPH.cardGlow.geometry.dispose(); PW_GRAPH.cardGlow.geometry = new THREE.PlaneGeometry(cardW + 0.3, cardH + 0.3); }
      PW_GRAPH.cardHotZones = canvas.hotZones || [];
      PW_GRAPH.cardLinkedNames = pwGraphComputeCardLinkedNames(PW_GRAPH.cardFullData, PW_GRAPH.cardData);
    } catch (e) { log('[平行世界·3D] 重绘卡片失败', e?.message || e); }
  }

    // ── 动画循环（摇镜 + 响应式屏幕空间卡片 + 暗化）──
  function pwGraphAnimate() {
    if (!PW_GRAPH.renderer || !PW_GRAPH.scene) return;
    PW_GRAPH.rafId = topWindow.requestAnimationFrame(pwGraphAnimate);
    PW_GRAPH._time = (PW_GRAPH._time || 0) + 0.016;
    const t = PW_GRAPH._time;
    const cam = PW_GRAPH.camera;

    if (PW_GRAPH.group && PW_GRAPH.autoRotate && !PW_GRAPH.dragging) {
      PW_GRAPH.group.rotation.y += PW_GRAPH.autoSpeed;
    }
    PW_GRAPH.camDist += (PW_GRAPH.camDistTarget - PW_GRAPH.camDist) * 0.12;

    // 🎯 Task 1: 悬停出卡时相机保持默认状态（不锁定、不运镜），仅卡片原地显示。
    // 相机始终走默认分支：环绕中心 + FOV 回归 55。
    cam.position.lerp(PW_GRAPH._scratchVec3.set(0, 4, PW_GRAPH.camDist), 0.06); cam.lookAt(0, 0, 0);
    cam.fov += (55 - cam.fov) * 0.08; cam.updateProjectionMatrix();

    // 主角脉动
    const p0 = PW_GRAPH.nodeMeshes[0];
    if (p0) {
      const pu = 1 + Math.sin(t * 2) * 0.08;
      p0.glow1.scale.setScalar(pu);
      p0.glow2.scale.setScalar(1 + Math.sin(t * 1.5 + 1) * 0.06);
      p0.ring.rotation.z += 0.004;
    }
    for (const nm of PW_GRAPH.nodeMeshes) {
      if (nm.isPlayer) continue;
      nm.ring.rotation.z += 0.002;
      nm.glow1.scale.setScalar(1 + Math.sin(t * 1.5 + (nm.ringRot || 0)) * 0.04);
    }
    // 珠子动画 + 关联高亮 + 分层脉动（🔴紧急强脉动 / 🟡中常态 / 🟢底弱）
    for (const b of PW_GRAPH.beads) {
      b.mesh.rotation.y += 0.012; b.mesh.rotation.x += 0.006;
      const isUrgent = b.tier === 'urgent';
      const isLow = b.tier === 'low';
      const pulse = isUrgent ? (1 + Math.sin(t * 4 + b.phase) * 0.22) : (1 + Math.sin(t * 2.5 + b.phase) * 0.12);
      b.glow.scale.setScalar(pulse);
      if (PW_GRAPH.selectedEvtId && PW_GRAPH.relatedEvtIds) {
        const rel = PW_GRAPH.relatedEvtIds.has(b.evt.id);
        b.mesh.material.opacity = 1;
        b.mesh.material.transparent = false;
        b.glow.material.opacity = rel ? b.baseOpacity * 1.8 : b.baseOpacity;
        for (const sp of (b.spokes || [])) { sp.material.opacity = rel ? 0.55 : 0.34; }
      } else {
        b.mesh.material.opacity = 1;
        b.mesh.material.transparent = false;
        b.glow.material.opacity = isUrgent ? b.baseOpacity * 2.2 : b.baseOpacity;
        for (const sp of (b.spokes || [])) { sp.material.opacity = 0.34; }
      }
    }
    // 不再压暗非关联星球；关联项只通过光晕增强表达，保证移动端始终看得见全貌。
    for (const nm of PW_GRAPH.nodeMeshes) {
      nm.mesh.material.opacity = 1;
      nm.mesh.material.transparent = false;
    }

    // 本帧相机刚完成摇镜/FOV 更新，先刷新矩阵再做目标投影，避免卡片锚点滞后一帧。
    cam.updateMatrixWorld();
    // 3D 卡片：按实时视锥缩放，在窄屏上也完整显示，并锚定到星球上方。
    if (PW_GRAPH.cardMesh && PW_GRAPH.cardActive) {
      if (PW_GRAPH.cardSwingT > 0.1) {
        const camFwd = PW_GRAPH._scratchVec4.set(0, 0, -1).applyQuaternion(cam.quaternion);
        const camUp = PW_GRAPH._scratchVec5.set(0, 1, 0).applyQuaternion(cam.quaternion);
        const cardDistance = 5.0;
        const cardW = PW_GRAPH.cardW || 3.6;
        const cardH = PW_GRAPH.cardH || 4.3;
        const halfVisibleH = cardDistance * Math.tan((cam.fov * Math.PI / 180) / 2);
        const halfVisibleW = halfVisibleH * Math.max(0.1, cam.aspect || 1);
        const fitScale = Math.max(0.01, Math.min(1, (halfVisibleW * 2 * 0.88) / cardW, (halfVisibleH * 2 * 0.82) / cardH));
        const cardScale = fitScale * Math.max(1, Math.min(3, PW_GRAPH.cardZoom || 1));
        const renderedW = cardW * cardScale;
        const renderedH = cardH * cardScale;
        let anchorX = 0;
        let anchorY = 0;
        let targetRadiusOnCardPlane = 0;
        if (PW_GRAPH.cardTarget) {
          PW_GRAPH.cardTarget.getWorldPosition(PW_GRAPH._scratchVec);
          const targetDistance = Math.max(0.1, PW_GRAPH._scratchVec.distanceTo(cam.position));
          const geometry = PW_GRAPH.cardTarget.geometry;
          if (geometry && !geometry.boundingSphere) geometry.computeBoundingSphere?.();
          const radius = geometry?.boundingSphere?.radius || 0;
          const scale = PW_GRAPH.cardTarget.scale;
          targetRadiusOnCardPlane = radius * Math.max(scale.x, scale.y, scale.z) * cardDistance / targetDistance;
          PW_GRAPH._scratchVec.project(cam);
          anchorX = PW_GRAPH._scratchVec.x * halfVisibleW;
          anchorY = PW_GRAPH._scratchVec.y * halfVisibleH;
        }
        const gap = Math.min(0.28, halfVisibleH * 0.08);
        const viewHalfW = halfVisibleW * 0.94;
        const viewHalfH = halfVisibleH * 0.94;
        const minX = Math.min(-viewHalfW + renderedW / 2, viewHalfW - renderedW / 2);
        const maxX = Math.max(-viewHalfW + renderedW / 2, viewHalfW - renderedW / 2);
        const minY = Math.min(-viewHalfH + renderedH / 2, viewHalfH - renderedH / 2);
        const maxY = Math.max(-viewHalfH + renderedH / 2, viewHalfH - renderedH / 2);
        const pan = PW_GRAPH.cardPan || { x: 0, y: 0 };
        const cardX = Math.max(minX, Math.min(maxX, anchorX + pan.x));
        const cardY = Math.max(minY, Math.min(maxY, anchorY + renderedH / 2 + targetRadiusOnCardPlane + gap + pan.y));
        const camRight = PW_GRAPH._scratchVec3.set(1, 0, 0).applyQuaternion(cam.quaternion);
        const cardPos = PW_GRAPH._scratchVec2.copy(cam.position)
          .addScaledVector(camFwd, cardDistance)
          .addScaledVector(camRight, cardX)
          .addScaledVector(camUp, cardY);
        PW_GRAPH.cardMesh.scale.setScalar(cardScale);
        if (PW_GRAPH.cardGlow) PW_GRAPH.cardGlow.scale.setScalar(cardScale);
        if (!PW_GRAPH.cardMesh.userData.positioned) {
          PW_GRAPH.cardMesh.position.copy(cardPos);
          PW_GRAPH.cardMesh.userData.positioned = true;
        } else {
          PW_GRAPH.cardMesh.position.lerp(cardPos, 0.18);
        }
        PW_GRAPH.cardGlow.position.copy(PW_GRAPH.cardMesh.position);
        PW_GRAPH.cardMesh.lookAt(cam.position); PW_GRAPH.cardGlow.lookAt(cam.position);
        const op = Math.min(1, (PW_GRAPH.cardSwingT - 0.1) / 0.35);
        PW_GRAPH.cardMesh.material.opacity = op; PW_GRAPH.cardGlow.material.opacity = op * 0.15;
      }
      // 连接线：从目标节点到卡片底部
      if (PW_GRAPH.cardTarget && PW_GRAPH.focusMesh) {
        const wp = PW_GRAPH._scratchVec; PW_GRAPH.cardTarget.getWorldPosition(wp);
        const linePos = PW_GRAPH.cardLine.geometry.attributes.position;
        linePos.setXYZ(0, wp.x, wp.y, wp.z);
        const camUp = PW_GRAPH._scratchVec5.set(0, 1, 0).applyQuaternion(cam.quaternion);
        const cardBottom = PW_GRAPH._scratchVec2.copy(PW_GRAPH.cardMesh.position).addScaledVector(camUp, -(PW_GRAPH.cardH || 4.3) * PW_GRAPH.cardMesh.scale.y / 2);
        linePos.setXYZ(1, cardBottom.x, cardBottom.y, cardBottom.z);
        linePos.needsUpdate = true;
        PW_GRAPH.cardLine.material.opacity = 0.35 * Math.min(1, PW_GRAPH.cardSwingT);
      }
    }

    PW_GRAPH.renderer.render(PW_GRAPH.scene, cam);
    pwGraphProjectLabels();
  }

  function pwGraphDebugLabels(reason, projection, force = false) {
    if (!PW_GRAPH.overlay || !PW_GRAPH.canvas || !PW_GRAPH.labelLayer) return;
    try {
      const now = Date.now();
      const canvasRect = PW_GRAPH.canvas.getBoundingClientRect();
      const layerRect = PW_GRAPH.labelLayer.getBoundingClientRect();
      const firstLabel = PW_GRAPH.labelLayer.querySelector('.pw-graph-label');
      const firstRect = firstLabel?.getBoundingClientRect?.();
      const layerStyle = topWindow.getComputedStyle(PW_GRAPH.labelLayer);
      const labelStyle = firstLabel ? topWindow.getComputedStyle(firstLabel) : null;
      const mobileQuery = topWindow.matchMedia?.('(max-width: 768px), (pointer: coarse)');
      const sig = [
        mobileQuery?.matches,
        Math.round(canvasRect.width), Math.round(canvasRect.height),
        Math.round(layerRect.width), Math.round(layerRect.height),
        PW_GRAPH.labelLayer.childElementCount,
        layerStyle.display, layerStyle.visibility, layerStyle.opacity,
        labelStyle?.display, labelStyle?.visibility, labelStyle?.opacity,
        projection?.visible, projection?.hiddenDepth, projection?.hiddenBounds,
      ].join('|');
      if (!force && sig === PW_GRAPH._labelDebugLastSig && now - PW_GRAPH._labelDebugLastAt < 5000) return;
      PW_GRAPH._labelDebugLastSig = sig;
      PW_GRAPH._labelDebugLastAt = now;
      const rectInfo = rect => rect ? {
        left: Math.round(rect.left * 10) / 10,
        top: Math.round(rect.top * 10) / 10,
        width: Math.round(rect.width * 10) / 10,
        height: Math.round(rect.height * 10) / 10,
        right: Math.round(rect.right * 10) / 10,
        bottom: Math.round(rect.bottom * 10) / 10,
      } : null;
      console.log('[平行世界·3D标签诊断]', {
        reason,
        mobile: mobileQuery?.matches ?? null,
        media: {
          narrow: topWindow.matchMedia?.('(max-width: 768px)')?.matches ?? null,
          coarse: topWindow.matchMedia?.('(pointer: coarse)')?.matches ?? null,
        },
        viewport: {
          innerWidth: topWindow.innerWidth,
          innerHeight: topWindow.innerHeight,
          devicePixelRatio: topWindow.devicePixelRatio,
          visualWidth: topWindow.visualViewport?.width ?? null,
          visualHeight: topWindow.visualViewport?.height ?? null,
          visualOffsetLeft: topWindow.visualViewport?.offsetLeft ?? null,
          visualOffsetTop: topWindow.visualViewport?.offsetTop ?? null,
        },
        canvas: {
          rect: rectInfo(canvasRect),
          widthAttribute: PW_GRAPH.canvas.width,
          heightAttribute: PW_GRAPH.canvas.height,
          display: topWindow.getComputedStyle(PW_GRAPH.canvas).display,
        },
        layer: {
          rect: rectInfo(layerRect),
          children: PW_GRAPH.labelLayer.childElementCount,
          connected: PW_GRAPH.labelLayer.isConnected,
          display: layerStyle.display,
          visibility: layerStyle.visibility,
          opacity: layerStyle.opacity,
          overflow: layerStyle.overflow,
          zIndex: layerStyle.zIndex,
        },
        firstLabel: firstLabel ? {
          text: firstLabel.textContent,
          rect: rectInfo(firstRect),
          inlineDisplay: firstLabel.style.display,
          inlineOpacity: firstLabel.style.opacity,
          inlineTransform: firstLabel.style.transform,
          display: labelStyle.display,
          visibility: labelStyle.visibility,
          opacity: labelStyle.opacity,
          color: labelStyle.color,
          fontSize: labelStyle.fontSize,
          zIndex: labelStyle.zIndex,
        } : null,
        nodes: PW_GRAPH.nodeMeshes.length,
        projection: projection || null,
      });
    } catch (e) {
      console.warn('[平行世界·3D标签诊断] 日志采集失败', e);
    }
  }

  // ── 投影标签到屏幕（含暗化）──
  function pwGraphProjectLabels() {
    if (!PW_GRAPH.camera || !PW_GRAPH.canvas || !PW_GRAPH.labelLayer) return;
    const canvasRect = PW_GRAPH.canvas.getBoundingClientRect();
    const layerRect = PW_GRAPH.labelLayer.getBoundingClientRect();
    const w = Math.max(1, canvasRect.width);
    const h = Math.max(1, canvasRect.height);
    const offsetX = canvasRect.left - layerRect.left;
    const offsetY = canvasRect.top - layerRect.top;
    const v = PW_GRAPH._scratchVec;
    const mobile = pwGraphIsMobile();
    const projection = { total: 0, visible: 0, hiddenDepth: 0, hiddenBounds: 0, spriteTotal: 0, spriteVisible: 0, first: null };
    for (const nm of PW_GRAPH.nodeMeshes) {
      if (!nm.labelDiv) continue;
      projection.total++;
      if (nm.labelSprite) projection.spriteTotal++;
      nm.mesh.getWorldPosition(v);
      v.project(PW_GRAPH.camera);
      const canvasX = (v.x * 0.5 + 0.5) * w;
      const canvasY = (-v.y * 0.5 + 0.5) * h;
      const hiddenDepth = v.z < -1 || v.z > 1;
      const hiddenBounds = canvasX < -50 || canvasX > w + 50 || canvasY < -50 || canvasY > h + 50;
      if (!projection.first) projection.first = {
        name: nm.name,
        ndcX: Math.round(v.x * 1000) / 1000,
        ndcY: Math.round(v.y * 1000) / 1000,
        ndcZ: Math.round(v.z * 1000) / 1000,
        canvasX: Math.round(canvasX * 10) / 10,
        canvasY: Math.round(canvasY * 10) / 10,
        hiddenDepth,
        hiddenBounds,
      };
      if (hiddenDepth || hiddenBounds) {
        if (hiddenDepth) projection.hiddenDepth++;
        if (hiddenBounds) projection.hiddenBounds++;
        nm.labelDiv.style.display = 'none';
        if (nm.labelSprite) nm.labelSprite.visible = false;
        continue;
      }
      const x = offsetX + canvasX;
      const y = offsetY + canvasY;
      nm.labelDiv.style.display = mobile ? 'none' : '';
      nm.labelDiv.style.opacity = '1';
      nm.labelDiv.style.transform = `translate(-50%,-50%) translate(${x}px,${y + 16}px)`;
      if (nm.labelSprite) {
        nm.labelSprite.visible = mobile && !PW_GRAPH.cardActive;
        if (nm.labelSprite.visible) {
          nm.mesh.getWorldPosition(v);
          const distance = Math.max(0.1, v.distanceTo(PW_GRAPH.camera.position));
          const worldPerPixel = 2 * Math.tan((PW_GRAPH.camera.fov * Math.PI / 180) / 2) * distance / h;
          const pixelW = nm.labelSprite.userData.pixelWidth || 64;
          const pixelH = nm.labelSprite.userData.pixelHeight || 27;
          nm.labelSprite.scale.set(pixelW * worldPerPixel, pixelH * worldPerPixel, 1);
          const cameraDown = PW_GRAPH._scratchVec2.set(0, -1, 0).applyQuaternion(PW_GRAPH.camera.quaternion);
          nm.labelSprite.position.copy(v).addScaledVector(cameraDown, (16 + pixelH / 2) * worldPerPixel);
          projection.spriteVisible++;
        }
      }
      projection.visible++;
    }
    pwGraphDebugLabels('projection', projection);
  }

  // ── 交互：拖拽旋转 + 自由滚轮缩放 + 点击 ──
  function pwGraphBindInteraction() {
    const canvas = PW_GRAPH.canvas;
    if (!canvas) return;
    const stage = PW_GRAPH.overlay;
    canvas.style.cursor = 'grab';

    canvas.addEventListener('pointerdown', (e) => {
      if (PW_GRAPH.isPinching || PW_GRAPH.activePointerId != null) return;
      PW_GRAPH.dragging = true;
      PW_GRAPH.activePointerId = e.pointerId;
      pwGraphUpdatePointer(e.clientX, e.clientY);
      PW_GRAPH.dragStart = { x: e.clientX, y: e.clientY };
      PW_GRAPH.dragRotStart = { x: PW_GRAPH.group.rotation.x, y: PW_GRAPH.group.rotation.y };
      PW_GRAPH.dragCardPanStart = { ...(PW_GRAPH.cardPan || { x: 0, y: 0 }) };
      try { canvas.setPointerCapture(e.pointerId); } catch {}
      canvas.style.cursor = 'grabbing';
    });
    stage.addEventListener('pointermove', (e) => {
      if (PW_GRAPH.dragging && e.pointerId !== PW_GRAPH.activePointerId) return;
      pwGraphUpdatePointer(e.clientX, e.clientY);
      if (PW_GRAPH.dragging && PW_GRAPH.cardActive && (PW_GRAPH.cardZoom || 1) > 1.01) {
        const rect = canvas.getBoundingClientRect();
        const cardDistance = 5.0;
        const halfVisibleH = cardDistance * Math.tan((PW_GRAPH.camera.fov * Math.PI / 180) / 2);
        const halfVisibleW = halfVisibleH * Math.max(0.1, PW_GRAPH.camera.aspect || 1);
        const dx = e.clientX - PW_GRAPH.dragStart.x;
        const dy = e.clientY - PW_GRAPH.dragStart.y;
        PW_GRAPH.cardPan.x = PW_GRAPH.dragCardPanStart.x + dx / Math.max(1, rect.width) * halfVisibleW * 2;
        PW_GRAPH.cardPan.y = PW_GRAPH.dragCardPanStart.y - dy / Math.max(1, rect.height) * halfVisibleH * 2;
      } else if (PW_GRAPH.dragging && PW_GRAPH.group && !PW_GRAPH.cardActive) {
        const dx = e.clientX - PW_GRAPH.dragStart.x;
        const dy = e.clientY - PW_GRAPH.dragStart.y;
        PW_GRAPH.group.rotation.y = PW_GRAPH.dragRotStart.y + dx * 0.006;
        PW_GRAPH.group.rotation.x = Math.max(-1.4, Math.min(1.4, PW_GRAPH.dragRotStart.x + dy * 0.006));
      } else {
        pwGraphHoverCheck();
      }
    });
    stage.addEventListener('pointerup', (e) => {
      if (e.pointerId !== PW_GRAPH.activePointerId) return;
      const wasDragging = PW_GRAPH.dragging;
      PW_GRAPH.dragging = false;
      pwGraphUpdatePointer(e.clientX, e.clientY);
      try { if (canvas.hasPointerCapture?.(e.pointerId)) canvas.releasePointerCapture(e.pointerId); } catch {}
      PW_GRAPH.activePointerId = null;
      canvas.style.cursor = 'grab';
      // 📱 触屏手指点按天然有 10~20px 抖动，阈值太小会被当成拖拽导致点不中球/不出卡片
      const threshold = (e.pointerType === 'touch') ? 16 : 5;
      if (!PW_GRAPH.isPinching && wasDragging && Math.abs(e.clientX - PW_GRAPH.dragStart.x) < threshold && Math.abs(e.clientY - PW_GRAPH.dragStart.y) < threshold) {
        pwGraphClickCheck();
      }
    });
    stage.addEventListener('pointercancel', (e) => {
      if (e.pointerId !== PW_GRAPH.activePointerId) return;
      PW_GRAPH.dragging = false;
      PW_GRAPH.activePointerId = null;
      try { if (canvas.hasPointerCapture?.(e.pointerId)) canvas.releasePointerCapture(e.pointerId); } catch {}
      canvas.style.cursor = 'grab';
    });
    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      // 🎯 Task 1: 卡片查看态只缩放卡片；其余情况统一调整相机距离，不再有"聚焦缩放"分支。
      if (PW_GRAPH.cardActive) {
        PW_GRAPH.cardZoom = Math.max(1, Math.min(3, (PW_GRAPH.cardZoom || 1) * Math.exp(-e.deltaY * 0.0015)));
        if (PW_GRAPH.cardZoom <= 1.001) PW_GRAPH.cardPan = { x: 0, y: 0 };
      } else {
        PW_GRAPH.camDistTarget = Math.max(8, Math.min(PW_GRAPH.maxCamDist, PW_GRAPH.camDistTarget + e.deltaY * 0.02));
      }
      return false;
    }, { passive: false });

    // 📱 双指捏合缩放（移动端无 wheel 事件，用 touch 模拟）
    let _pinchStartDist = 0;
    let _pinchStartCamDist = 0;
    let _pinchStartCardZoom = 1;
    canvas.addEventListener('touchstart', (e) => {
      if (e.touches.length === 2) {
        if (PW_GRAPH.pinchEndTimer) { topWindow.clearTimeout(PW_GRAPH.pinchEndTimer); PW_GRAPH.pinchEndTimer = null; }
        PW_GRAPH.isPinching = true;
        try { e.preventDefault(); } catch {}
        const dx = e.touches[0].clientX - e.touches[1].clientX;
        const dy = e.touches[0].clientY - e.touches[1].clientY;
        _pinchStartDist = Math.hypot(dx, dy) || 1;
        if (PW_GRAPH.cardActive) _pinchStartCardZoom = PW_GRAPH.cardZoom || 1;
        else _pinchStartCamDist = PW_GRAPH.camDistTarget;
        PW_GRAPH.dragging = false; // 双指时停止单指旋转
        if (PW_GRAPH.activePointerId != null) {
          try { if (canvas.hasPointerCapture?.(PW_GRAPH.activePointerId)) canvas.releasePointerCapture(PW_GRAPH.activePointerId); } catch {}
          PW_GRAPH.activePointerId = null;
        }
      }
    }, { passive: false });
    canvas.addEventListener('touchmove', (e) => {
      if (e.touches.length === 2 && _pinchStartDist > 0) {
        try { e.preventDefault(); } catch {}
        const dx = e.touches[0].clientX - e.touches[1].clientX;
        const dy = e.touches[0].clientY - e.touches[1].clientY;
        const dist = Math.hypot(dx, dy) || 1;
        if (PW_GRAPH.cardActive) {
          PW_GRAPH.cardZoom = Math.max(1, Math.min(3, _pinchStartCardZoom * dist / _pinchStartDist));
          if (PW_GRAPH.cardZoom <= 1.001) PW_GRAPH.cardPan = { x: 0, y: 0 };
        } else {
          const ratio = _pinchStartDist / dist;
          PW_GRAPH.camDistTarget = Math.max(8, Math.min(PW_GRAPH.maxCamDist, _pinchStartCamDist * ratio));
        }
      }
    }, { passive: false });
    const endPinch = (e) => {
      if (e.touches?.length >= 2) return;
      _pinchStartDist = 0;
      if (PW_GRAPH.pinchEndTimer) topWindow.clearTimeout(PW_GRAPH.pinchEndTimer);
      PW_GRAPH.pinchEndTimer = topWindow.setTimeout(() => {
        PW_GRAPH.isPinching = false;
        PW_GRAPH.pinchEndTimer = null;
      }, 80);
    };
    canvas.addEventListener('touchend', endPinch, { passive: true });
    canvas.addEventListener('touchcancel', endPinch, { passive: true });
  }

  // ── Hover 检测（含珠子和卡片）──
  function pwGraphHoverCheck() {
    if (!PW_GRAPH.raycaster || !PW_GRAPH.camera) return;
    PW_GRAPH.raycaster.setFromCamera(PW_GRAPH.pointer, PW_GRAPH.camera);
    const targets = [...(PW_GRAPH._meshArray || []), ...(PW_GRAPH._beadArray || [])];
    if (PW_GRAPH.cardMesh) targets.push(PW_GRAPH.cardMesh);
    const hits = PW_GRAPH.raycaster.intersectObjects(targets, false);
    const hit = hits.length ? hits[0].object : null;
    if (hit !== PW_GRAPH.hovered) {
      if (PW_GRAPH.hovered) {
        const old = [...PW_GRAPH.nodeMeshes, ...PW_GRAPH.beads].find(n => n.mesh === PW_GRAPH.hovered);
        if (old && !old.isPlayer) old.mesh.scale.setScalar(1);
      }
      PW_GRAPH.hovered = hit;
      PW_GRAPH.canvas.style.cursor = hit ? 'pointer' : 'grab';
      if (hit) {
        const nm = [...PW_GRAPH.nodeMeshes, ...PW_GRAPH.beads].find(n => n.mesh === hit);
        if (nm && !nm.isPlayer) nm.mesh.scale.setScalar(1.3);
      }
    }
    // 🖱️ 悬停自动出卡
    if (!PW_GRAPH.dragging) {
      if (PW_GRAPH._hoverCardTimer) { try { topWindow.clearTimeout(PW_GRAPH._hoverCardTimer); } catch {} PW_GRAPH._hoverCardTimer = null; }
      if (hit && !hit.userData.isCard) {
        // 该节点已有悬停卡 -> 不重复弹出（防闪烁）；钉住卡不抢夺
        const _already = PW_GRAPH.cardActive && !PW_GRAPH.cardPinned && PW_GRAPH.cardHoverNode === hit;
        if (!_already && (!PW_GRAPH.cardActive || !PW_GRAPH.cardPinned)) {
          const nm = [...PW_GRAPH.nodeMeshes, ...PW_GRAPH.beads].find(n => n.mesh === hit);
          if (nm) {
            PW_GRAPH._hoverCardTimer = topWindow.setTimeout(() => {
              if (PW_GRAPH.hovered === hit && !PW_GRAPH.dragging &&
                  !(PW_GRAPH.cardActive && !PW_GRAPH.cardPinned && PW_GRAPH.cardHoverNode === hit)) {
                pwGraphHoverShowCard(nm);
              }
            }, 150);
          }
        }
      } else if (!hit) {
        if (PW_GRAPH.cardActive && !PW_GRAPH.cardPinned) {
          PW_GRAPH._hoverCardTimer = topWindow.setTimeout(() => {
            if (!PW_GRAPH.hovered && !PW_GRAPH.cardPinned) pwGraphRemoveCard();
          }, 150);
        }
      }
    }
  }

  // ── 悬停出卡：复用 pwGraphShowCard，标记为非钉住（离开自动收起）──
  function pwGraphHoverShowCard(nm) {
    if (!nm) return;
    const data = PW_GRAPH.lastData || pwLoadData();
    if (nm.isPlayer) {
      pwGraphShowCard({ isPlayer: true, _cardType: 'player' }, nm.mesh, data, { pinned: false });
    } else if (nm.evt) {
      pwGraphShowCard(nm.evt, nm.mesh, data, { pinned: false });
    } else if (nm.npc) {
      const al = pwResolveNpcAttitudeLevel(nm.npc);
      const el = pwClampEmotionLevel(nm.npc.emotionLevel != null && nm.npc.emotionLevel !== '' ? nm.npc.emotionLevel : 50);
      pwGraphShowCard({ ...nm.npc, attitudeLevel: al, emotionLevel: el, _cardType: 'npc' }, nm.mesh, data, { pinned: false });
    }
  }

  // ── 点击检测（热区跳转）──
  function pwGraphNearestTouchTarget() {
    if (!pwGraphIsMobile() || !PW_GRAPH.camera || !PW_GRAPH.canvas || !PW_GRAPH.pointer) return null;
    const rect = PW_GRAPH.canvas.getBoundingClientRect();
    const px = (PW_GRAPH.pointer.x * 0.5 + 0.5) * rect.width;
    const py = (-PW_GRAPH.pointer.y * 0.5 + 0.5) * rect.height;
    const candidates = [];
    const maxD2 = 30 * 30;
    for (const item of [...PW_GRAPH.nodeMeshes, ...PW_GRAPH.beads]) {
      if (!item?.mesh) continue;
      const projected = PW_GRAPH._scratchVec;
      item.mesh.getWorldPosition(projected);
      projected.project(PW_GRAPH.camera);
      if (projected.z < -1 || projected.z > 1) continue;
      const x = (projected.x * 0.5 + 0.5) * rect.width;
      const y = (-projected.y * 0.5 + 0.5) * rect.height;
      const d2 = (x - px) ** 2 + (y - py) ** 2;
      if (d2 < maxD2) candidates.push({ mesh: item.mesh, d2, depth: projected.z });
    }
    if (!candidates.length) return null;
    return candidates
      .sort((a, b) => a.depth - b.depth || a.d2 - b.d2)[0].mesh;
  }

  function pwGraphClickCheck() {
    if (!PW_GRAPH.raycaster || !PW_GRAPH.camera) return;
    const data = PW_GRAPH.lastData || pwLoadData();
    PW_GRAPH.raycaster.setFromCamera(PW_GRAPH.pointer, PW_GRAPH.camera);
    const targets = [...(PW_GRAPH._meshArray || []), ...(PW_GRAPH._beadArray || [])];
    if (PW_GRAPH.cardMesh) targets.push(PW_GRAPH.cardMesh);
    const hits = PW_GRAPH.raycaster.intersectObjects(targets, false);
    const fallbackTarget = hits.length || PW_GRAPH.cardActive ? null : pwGraphNearestTouchTarget();
    if (!hits.length && !fallbackTarget) {
      if (PW_GRAPH.cardActive) { pwGraphRemoveCard(); return; }
      PW_GRAPH.focusMesh = null;
      return;
    }
    const obj = hits.length ? hits[0].object : fallbackTarget;
    if (obj.userData.isCard) {
      // 热区检测：UV -> 画布坐标 -> 命中热区则跳转关联
      const uv = hits[0].uv;
      if (uv && PW_GRAPH.cardHotZones && PW_GRAPH.cardHotZones.length) {
        // 纹理宽度恒为 640，高度随自动裁剪变化（cardContentH）
        const cx = uv.x * 640, cy = (1 - uv.y) * (PW_GRAPH.cardContentH || 860);
        for (const z of PW_GRAPH.cardHotZones) {
          if (cx >= z.x && cx <= z.x + z.w && cy >= z.y && cy <= z.y + z.h) {
            if (z.type === 'close') { pwGraphRemoveCard(); return; }
            if (z.type === 'toggle-player') { PW_GRAPH.playerCardExpanded = !PW_GRAPH.playerCardExpanded; pwGraphRedrawCard(); return; }
            if (z.type === 'regen-player') { const _fd = PW_GRAPH.cardFullData; if (_fd) { if (_fd.playerIntro) _fd.playerIntro.text = ''; pwGraphRedrawCard(); pwGraphEnsurePlayerIntro(_fd, true); } return; }
            if (z.type === 'npc') {
              // 优先精确名匹配，再模糊匹配；关联名可能与 NPC name 字段不完全一致
              const npc = (data.npcs || []).find(n => n.name === z.name)
                || (data.npcs || []).find(n => pwNpcNameMatches(z.name, n.name));
              const nm = npc ? (PW_GRAPH.nodeMeshes.find(n => n.npc === npc) || PW_GRAPH.nodeMeshes.find(n => n.name === npc.name)) : null;
              if (npc) {
                const al = pwResolveNpcAttitudeLevel(npc);
                const el = pwClampEmotionLevel(npc.emotionLevel != null && npc.emotionLevel !== '' ? npc.emotionLevel : 50);
                // 找不到节点时，用当前卡片目标/主角节点兜底，保证仍能跳转展示
                const targetMesh = nm ? nm.mesh : (PW_GRAPH.cardTarget || PW_GRAPH.nodeMeshes[0]?.mesh);
                pwGraphShowCard({ ...npc, attitudeLevel: al, emotionLevel: el, _cardType: 'npc' }, targetMesh, data);
                return;
              }
            }
            if (z.type === 'event') {
              const m = (data.modules || []).find(x => x.id === z.id);
              const bd = PW_GRAPH.beads.find(b => b.evt.id === z.id);
              if (m && bd) { pwGraphShowCard(pwGraphBuildEventData(m, data), bd.mesh, data); return; }
            }
          }
        }
      }
      // 非热区点击：关闭卡片（保持当前视角）
      pwGraphRemoveCard(); return;
    }
    if (obj.userData.isBead) { pwGraphShowCard(obj.userData.evt, obj, data); }
    else if (obj.userData.isPlayer) { pwGraphShowCard({ isPlayer: true, _cardType: 'player' }, obj, data); }
    else if (obj.userData.npc) {
      const n = obj.userData.npc;
      const al = pwResolveNpcAttitudeLevel(n);
      const el = pwClampEmotionLevel(n.emotionLevel != null && n.emotionLevel !== '' ? n.emotionLevel : 50);
      pwGraphShowCard({ ...n, attitudeLevel: al, emotionLevel: el, _cardType: 'npc' }, obj, data);
    }
  }

  // ── 按名称聚焦（显示卡片）──
  function pwGraphFocusByName(name) {
    const data = PW_GRAPH.lastData || pwLoadData();
    const nm = PW_GRAPH.nodeMeshes.find(n => n.name === name && !n.isPlayer);
    if (!nm) return;
    const al = pwResolveNpcAttitudeLevel(nm.npc);
    const el = pwClampEmotionLevel(nm.npc.emotionLevel != null && nm.npc.emotionLevel !== '' ? nm.npc.emotionLevel : 50);
    pwGraphShowCard({ ...nm.npc, attitudeLevel: al, emotionLevel: el, _cardType: 'npc' }, nm.mesh, data);
  }

  // ── 清除聚焦（关闭卡片）──
  function pwGraphClearFocus() {
    pwGraphRemoveCard();
    PW_GRAPH.focusMesh = null;
    PW_GRAPH.selectedNpcName = null;
  }

  function pwGraphRenderWorldCard(data) {
    const card = topDoc.getElementById('pw-graph-world-card');
    if (!card) return;
    const npcs = Array.isArray(data?.npcs) ? data.npcs : [];
    card.innerHTML = `
      <div class="wc-clock">🕐 ${escapeHtml(data?.worldClock || '剧情内时间未明')}${data?.turn ? ' · 第' + data.turn + '轮' : ''}</div>
      <div class="wc-title">📌 ${escapeHtml(data?.globalState?.title || '当前世界状态')}</div>
      <div class="wc-detail">${escapeHtml(data?.globalState?.detail || '暂无')}</div>
      <div class="wc-stats">
        <span>👥 ${npcs.length} 角色</span>
        <span>🔗 ${(data?.npcRelations || []).length} 关系</span>
        <span>📋 ${(data?.modules || []).length} 事件</span>
        <span>✅ ${npcs.filter(n => pwResolveNpcAttitudeLevel(n) >= 0).length} 已结识</span>
      </div>`;
  }

  // ── 打开 3D 关系网格 ──
  async function pwGraphOpen() {
    pwInjectStyle();
    if (PW_GRAPH.overlay) { pwGraphClose(); return; }

    const overlay = topDoc.createElement('div');
    overlay.id = 'pw-graph-overlay';
