  // ==================== 🦊 狐忆 3D 关系网格子系统 (FOX_GRAPH) ====================
  // 复用 PW_GRAPH 的 Three.js 渲染基础件（pwGraphLoadThree / pwGraphMakeNebula / pwGraphMakeNodeMesh / pwGraphMakeBeadMesh / pwAttitudeLevelColor），
  // 数据源换成狐忆角色认知档案 + 关系网 + 记忆事件。主角与角色按地点排在圆周上，节点颜色=与主角关系强度，连线=关系，◆珠子=记忆事件。
  const FOX_GRAPH = {
    THREE: null, loadingPromise: null, overlay: null, canvas: null, renderer: null, scene: null, camera: null, group: null,
    raycaster: null, pointer: null, rafId: null, nodeMeshes: [], edges: [], beads: [], labelLayer: null,
    rotation: { x: 0.42, y: 0 }, autoRotate: true, dragging: false, dragStart: { x: 0, y: 0 }, dragRotStart: { x: 0, y: 0 },
    camDist: 22, camDistTarget: 22, hovered: null, time: 0, lastData: null, cssInjected: false,
    _scratchVec: null, _meshArray: null, _beadArray: null,
  };

  // ── 由狐忆数据构建 PW 形状数据（适配复用渲染层）──
  function foxGraphBuildData() {
    const mem = loadFoxMemory();
    const profiles = Object.values(mem.characterProfiles || {});
    const rels = Array.isArray(mem.relationships) ? mem.relationships : [];
    const plotAtoms = Array.isArray(mem.plotAtoms) ? mem.plotAtoms : [];
    let prot = profiles.find(p => p.isProtagonist); if (!prot && profiles.length) prot = profiles[0];
    const protName = prot ? String(prot.name || '主角') : '主角';
    const impOf = (name) => { const r = rels.find(x => (x.a === protName && x.b === name) || (x.b === protName && x.a === name)); return (r && r.importance != null) ? Math.round(r.importance * 100) : -1; };
    const npcs = profiles.filter(p => p !== prot).map(p => ({
      name: String(p.name || '?'), attitudeLevel: impOf(String(p.name)), emotionLevel: 50,
      location: p.state?.location?.interior || p.state?.location?.building || p.state?.location?.area || p.state?.location?.city || p.facts?.location || '',
      status: p.state?.mind?.currentGoal || '',
      detail: p.cognition || p.behavior || '',
      _profile: p,
    }));
    const npcRelations = rels.filter(r => r.a !== protName && r.b !== protName).map(r => ({ from: r.a, to: r.b, relationLevel: Math.round((r.importance ?? 0.5) * 100) }));
    const nameSet = new Set(profiles.map(p => p.name).filter(Boolean));
    const modules = plotAtoms.slice(-12).reverse().map((m, i) => {
      const txt = String(m.summary || m.content || '');
      return { id: 'fm_' + i, title: txt.slice(0, 22) || '记忆', impact: 'mid', summary: txt, linkedNpcs: Array.from(nameSet).filter(n => txt.includes(n)).slice(0, 2) };
    });
    return { npcs, npcRelations, modules, globalState: { title: '狐忆·关系网格', detail: '角色认知档案与关系网络（五层档案 · 关系网 · 记忆事件）' }, worldClock: '记忆库', turn: 0, _protName: protName, _prot: prot };
  }

