  function foxGraphInitScene(THREE) {
    const w = FOX_GRAPH.overlay.clientWidth || topWindow.innerWidth, h = FOX_GRAPH.overlay.clientHeight || topWindow.innerHeight;
    FOX_GRAPH.renderer = new THREE.WebGLRenderer({ canvas: FOX_GRAPH.canvas, antialias: true, alpha: false });
    FOX_GRAPH.renderer.setPixelRatio(Math.min(2, topWindow.devicePixelRatio || 1));
    FOX_GRAPH.renderer.setSize(w, h, false); FOX_GRAPH.renderer.setClearColor(0x08060a, 1);
    FOX_GRAPH.scene = new THREE.Scene(); FOX_GRAPH.scene.fog = null;
    FOX_GRAPH.camera = new THREE.PerspectiveCamera(55, w / h, 0.1, 200); FOX_GRAPH.camera.position.set(0, 4, FOX_GRAPH.camDist); FOX_GRAPH.camera.lookAt(0, 0, 0);
    FOX_GRAPH.group = new THREE.Group(); FOX_GRAPH.group.rotation.x = FOX_GRAPH.rotation.x; FOX_GRAPH.scene.add(FOX_GRAPH.group);
    FOX_GRAPH.scene.add(new THREE.AmbientLight(0x4a3a2a, 0.6));
    const pl = new THREE.PointLight(0xf0a070, 1.2, 40, 1.5); pl.position.set(0, 0, 0); FOX_GRAPH.scene.add(pl);
    const fl = new THREE.PointLight(0x4a6a8a, 0.4, 50, 2); fl.position.set(10, 8, 12); FOX_GRAPH.scene.add(fl);
    try { const tex = pwGraphMakeNebula(THREE); if (tex) FOX_GRAPH.scene.add(new THREE.Mesh(new THREE.SphereGeometry(90, 32, 32), new THREE.MeshBasicMaterial({ map: tex, side: THREE.BackSide, fog: false }))); } catch {}
    try { const sg = new THREE.BufferGeometry(), N = 350, F32 = topWindow.Float32Array || Float32Array, pos = new F32(N * 3); for (let i = 0; i < N; i++) { const r = 58 + Math.random() * 25, t = Math.random() * Math.PI * 2, p = Math.acos(2 * Math.random() - 1); pos[i * 3] = r * Math.sin(p) * Math.cos(t); pos[i * 3 + 1] = r * Math.sin(p) * Math.sin(t); pos[i * 3 + 2] = r * Math.cos(p); } sg.setAttribute('position', new THREE.BufferAttribute(pos, 3)); FOX_GRAPH.scene.add(new THREE.Points(sg, new THREE.PointsMaterial({ color: 0x9a8a7a, size: 0.14, transparent: true, opacity: 0.45, sizeAttenuation: true, fog: false }))); } catch {}
    try { const grid = new THREE.GridHelper(50, 25, 0x2a1a14, 0x1a120e); grid.position.y = -14; grid.material.transparent = true; grid.material.opacity = 0.12; grid.material.fog = true; FOX_GRAPH.scene.add(grid); } catch {}
    FOX_GRAPH.raycaster = new THREE.Raycaster(); FOX_GRAPH.pointer = new THREE.Vector2(-2, -2);
    FOX_GRAPH._scratchVec = new THREE.Vector3();
  }

  function foxGraphBuild(data) {
    const THREE = FOX_GRAPH.THREE; if (!THREE || !FOX_GRAPH.group) return;
    FOX_GRAPH.lastData = data;
    // 清空
    for (const nm of FOX_GRAPH.nodeMeshes) { for (const m of [nm.mesh, nm.glow1, nm.glow2, nm.ring]) { try { if (m) { FOX_GRAPH.group.remove(m); m.geometry?.dispose?.(); m.material?.dispose?.(); } } catch {} } try { nm.labelDiv?.remove?.(); } catch {} }
    for (const e of FOX_GRAPH.edges) { try { FOX_GRAPH.group.remove(e.line); e.line.geometry?.dispose?.(); e.line.material?.dispose?.(); } catch {} }
    for (const b of FOX_GRAPH.beads) { for (const m of [b.mesh, b.glow]) { try { if (m) { FOX_GRAPH.group.remove(m); m.geometry?.dispose?.(); m.material?.dispose?.(); } } catch {} } }
    FOX_GRAPH.nodeMeshes = []; FOX_GRAPH.edges = []; FOX_GRAPH.beads = []; FOX_GRAPH.hovered = null;
    if (FOX_GRAPH.labelLayer) FOX_GRAPH.labelLayer.innerHTML = '';

    const npcs = data.npcs || [], rels = data.npcRelations || [], modules = data.modules || [], protName = data._protName;
    const conn = new Map(); npcs.forEach(n => conn.set(n.name, 0)); rels.forEach(r => { if (conn.has(r.from)) conn.set(r.from, conn.get(r.from) + 1); if (conn.has(r.to)) conn.set(r.to, conn.get(r.to) + 1); });

    const locMap = new Map(); npcs.forEach(n => { const l = n.location || '未知地点'; if (!locMap.has(l)) locMap.set(l, []); locMap.get(l).push(n); });
    const locs = Array.from(locMap.keys()), total = locs.length + 1, mapR = Math.max(10, total * 2.8);

    // 主角与地点使用同一半径，避免 NPC 较多时主角被单独推到远处。
    const pm = pwGraphMakeNodeMesh(THREE, 1.3, '#f0a070', true, '#f0a070');
    const playerPos = new THREE.Vector3(mapR, 0, 0);
    [pm.core, pm.glow1, pm.glow2, pm.ring].forEach(m => { m.position.copy(playerPos); FOX_GRAPH.group.add(m); });
    pm.core.userData = { isPlayer: true, name: protName, profile: data._prot };
    FOX_GRAPH.nodeMeshes.push({ mesh: pm.core, glow1: pm.glow1, glow2: pm.glow2, ring: pm.ring, labelDiv: null, isPlayer: true, name: protName, profile: data._prot, ringRot: Math.random() * 6.283 });

    // 按地点圆周
    const locPos = new Map(); locs.forEach((l, i) => { const ang = ((i + 1) / total) * Math.PI * 2, yv = Math.sin(i * 2.3) * 1.5; locPos.set(l, new THREE.Vector3(mapR * Math.cos(ang), yv, mapR * Math.sin(ang))); });
    const meshByName = new Map();
    locMap.forEach((arr, loc) => {
      const lp = locPos.get(loc), cr = Math.max(1.2, arr.length * 0.6);
      arr.forEach((n, i) => {
        const ang = (i / Math.max(arr.length, 1)) * Math.PI * 2;
        const pos = lp.clone().add(new THREE.Vector3(cr * Math.cos(ang), Math.sin(ang * 2) * Math.min(1.8, cr * 0.45), cr * Math.sin(ang)));
        const al = n.attitudeLevel, cs = (al == null || al < 0) ? 'rgb(136,136,136)' : pwAttitudeLevelColor(al);
        const r = 0.55 + Math.min(0.4, (conn.get(n.name) || 0) * 0.12);
        const m = pwGraphMakeNodeMesh(THREE, r, cs, false, cs);
        [m.core, m.glow1, m.glow2, m.ring].forEach(x => { x.position.copy(pos); FOX_GRAPH.group.add(x); });
        m.core.userData = { isPlayer: false, name: n.name, npc: n, profile: n._profile };
        let ld = null;
        if (FOX_GRAPH.labelLayer) { ld = topDoc.createElement('div'); ld.className = 'fg-label'; ld.innerHTML = `<span class="fg-label-dot" style="background:${cs};color:${cs};"></span>${escapeHtml(n.name)}`; ld.onclick = (e) => { e.stopPropagation(); foxGraphShowDetail(n._profile || n, m.core); }; FOX_GRAPH.labelLayer.appendChild(ld); }
        FOX_GRAPH.nodeMeshes.push({ mesh: m.core, glow1: m.glow1, glow2: m.glow2, ring: m.ring, labelDiv: ld, isPlayer: false, name: n.name, npc: n, profile: n._profile, ringRot: Math.random() * 6.283 });
        meshByName.set(n.name, m.core);
      });
    });

    // 连线：主角->NPC（态度/关系强度）+ NPC 间关系
    const makeEdge = (fm, tm, level) => { if (!fm || !tm) return; const g = new THREE.BufferGeometry().setFromPoints([fm.position, tm.position]); let c, o; if (level == null || level < 0) { c = 'rgb(90,100,120)'; o = 0.24; } else { c = pwAttitudeLevelColor(level); o = 0.34 + Math.abs(level - 50) / 50 * 0.4; } const line = new THREE.Line(g, new THREE.LineBasicMaterial({ color: new THREE.Color(c), transparent: true, opacity: o, fog: false })); FOX_GRAPH.group.add(line); FOX_GRAPH.edges.push({ line }); };
    for (const nm of FOX_GRAPH.nodeMeshes) { if (nm.isPlayer) continue; if (nm.npc && nm.npc.attitudeLevel >= 0) makeEdge(FOX_GRAPH.nodeMeshes[0].mesh, nm.mesh, nm.npc.attitudeLevel); }
    for (const r of rels) { const fm = meshByName.get(r.from), tm = meshByName.get(r.to); if (fm && tm && r.relationLevel >= 0) makeEdge(fm, tm, r.relationLevel); }

    // 记忆事件珠子
    for (const evt of modules) {
      const linked = evt.linkedNpcs || [];
      if (linked.length >= 2) { const fm = meshByName.get(linked[0]), tm = meshByName.get(linked[1]); if (fm && tm) foxGraphAddBead(THREE, evt, fm.position.clone().lerp(tm.position, 0.5)); }
      else if (linked.length === 1) { const mesh = meshByName.get(linked[0]); if (mesh) { const p = mesh.position.clone(); p.y += 1.2; foxGraphAddBead(THREE, evt, p); } }
      else { const p = playerPos.clone(); p.y += 1.6; foxGraphAddBead(THREE, evt, p); }
    }
    FOX_GRAPH._meshArray = FOX_GRAPH.nodeMeshes.map(n => n.mesh); FOX_GRAPH._beadArray = FOX_GRAPH.beads.map(b => b.mesh);
    foxMemoryV2Log('3D关系网格', `构建 ${FOX_GRAPH.nodeMeshes.length} 节点 ${FOX_GRAPH.edges.length} 连线 ${FOX_GRAPH.beads.length} 珠子`);
  }
  function foxGraphAddBead(THREE, evt, pos) { const cs = '#f0a070'; const m = pwGraphMakeBeadMesh(THREE, cs); m.core.position.copy(pos); m.glow.position.copy(pos); m.core.userData = { isBead: true, evt }; FOX_GRAPH.group.add(m.core); FOX_GRAPH.group.add(m.glow); FOX_GRAPH.beads.push({ mesh: m.core, glow: m.glow, evt, phase: Math.random() * 6.283 }); }

  function foxGraphAnimate() {
    if (!FOX_GRAPH.renderer) return;
    FOX_GRAPH.rafId = topWindow.requestAnimationFrame(foxGraphAnimate);
    FOX_GRAPH.time += 0.016; const t = FOX_GRAPH.time, THREE = FOX_GRAPH.THREE;
    if (FOX_GRAPH.group && FOX_GRAPH.autoRotate && !FOX_GRAPH.dragging) FOX_GRAPH.group.rotation.y += 0.0014;
    FOX_GRAPH.camDist += (FOX_GRAPH.camDistTarget - FOX_GRAPH.camDist) * 0.12;
    FOX_GRAPH.camera.position.lerp(FOX_GRAPH._scratchVec.set(0, 4, FOX_GRAPH.camDist), 0.06); FOX_GRAPH.camera.lookAt(0, 0, 0);
    const p0 = FOX_GRAPH.nodeMeshes[0]; if (p0) { p0.glow1.scale.setScalar(1 + Math.sin(t * 2) * 0.08); p0.ring.rotation.z += 0.004; }
    for (const nm of FOX_GRAPH.nodeMeshes) { if (nm.isPlayer) continue; nm.ring.rotation.z += 0.002; nm.glow1.scale.setScalar(1 + Math.sin(t * 1.5 + (nm.ringRot || 0)) * 0.04); }
    for (const b of FOX_GRAPH.beads) { b.mesh.rotation.y += 0.012; b.mesh.rotation.x += 0.006; b.glow.scale.setScalar(1 + Math.sin(t * 2.5 + b.phase) * 0.12); }
    FOX_GRAPH.renderer.render(FOX_GRAPH.scene, FOX_GRAPH.camera);
    foxGraphProjectLabels();
  }
  function foxGraphProjectLabels() {
    if (!FOX_GRAPH.camera || !FOX_GRAPH.labelLayer) return;
    const w = FOX_GRAPH.overlay.clientWidth || topWindow.innerWidth, h = FOX_GRAPH.overlay.clientHeight || topWindow.innerHeight, v = FOX_GRAPH._scratchVec;
    for (const nm of FOX_GRAPH.nodeMeshes) { if (!nm.labelDiv) continue; nm.mesh.getWorldPosition(v); v.project(FOX_GRAPH.camera); const x = (v.x * 0.5 + 0.5) * w, y = (-v.y * 0.5 + 0.5) * h; if (v.z > 1 || x < -50 || x > w + 50 || y < -50 || y > h + 50) { nm.labelDiv.style.display = 'none'; continue; } nm.labelDiv.style.display = ''; nm.labelDiv.style.transform = `translate(-50%,-50%) translate(${x}px,${y + 16}px)`; }
  }

  function foxGraphOnResize() {
    if (!FOX_GRAPH.overlay || !FOX_GRAPH.renderer || !FOX_GRAPH.camera) return;
    const w = FOX_GRAPH.overlay.clientWidth || topWindow.innerWidth;
    const h = FOX_GRAPH.overlay.clientHeight || topWindow.innerHeight;
    FOX_GRAPH.renderer.setSize(w, h, false);
    FOX_GRAPH.camera.aspect = w / Math.max(1, h);
