  function foxGraphLayerText(p) {
    const out = [];
    if (!p) return out;
    const f = p.facts || {};
    if (f.age || f.gender || f.occupation || f.identity) out.push(['① 事实', [f.age, f.gender, f.occupation, f.identity].filter(Boolean).join(' · ') + (f.skills?.length ? ' · 技能：' + f.skills.join('、') : '')]);
