    if (p.cognition) out.push(['③ 认知', p.cognition]);
    if (p.behavior) out.push(['④ 行为', p.behavior]);
    const ev = p.evolution || {};
    const evTotal = (ev.evidence || []).length;
    if (ev.causalChain || ev.pendingCount != null || evTotal > 0) out.push(['⑤ 演化', (ev.causalChain || '') + (ev.pendingCount != null ? `（待处理 ${ev.pendingCount}/总计 ${evTotal}）` : `（总计 ${evTotal}）`)]);
