  // 🎲 渲染骰子日志 + 紧张度条 + 势力声望面板区
  function pwRenderDiceLogHtml(data) {
    const last = data.lastDice;
    const log = Array.isArray(data.diceLog) ? data.diceLog : [];
    const rep = data.factionReputation || {};
    const repKeys = Object.keys(rep);
    const tension = (last && Number.isFinite(last.tension)) ? last.tension : pwComputeTension(data);
    const tensionColor = tension >= 60 ? '#ff5a4a' : tension >= 35 ? '#f0be5a' : '#4cc850';

    let logRows = '';
    for (const e of log.slice(-8).reverse()) {
      const verdict = e.triggered ? '⚡触发' : (e.mercy ? '🩵补偿' : '☕平安');
      const color = e.triggered ? '#ff5a4a' : (e.mercy ? '#7fdcff' : '#8a9aaa');
      logRows += `<div style="display:flex;gap:8px;font-size:11px;color:${color};padding:3px 0;border-bottom:1px solid rgba(255,255,255,0.04);">` +
        `<span style="flex:0 0 52px;color:#706058;">第${e.turn}轮</span>` +
        `<span style="flex:0 0 64px;">紧张${e.tension}</span>` +
        `<span style="flex:0 0 56px;">阈值${e.threshold}</span>` +
        `<span style="flex:0 0 48px;">🎲${e.roll}</span>` +
        `<span>${escapeHtml(PW_DICE_STORYTELLERS[e.storyteller]?.name || '')} · ${verdict} · ${escapeHtml(PW_DICE_SEVERITY[e.severity]?.label || e.severity || '中度')}${e.eventName ? ' · ' + escapeHtml(e.eventName) : ''}</span></div>`;
    }
    const repHtml = repKeys.length ? repKeys.map(k => {
      const v = Number(rep[k]) || 0;
      const c = v >= 20 ? '#4cc850' : v <= -20 ? '#f44336' : '#dddddd';
      return `<span class="pw-chip" style="color:${c};">${escapeHtml(k)} ${v > 0 ? '+' : ''}${v}</span>`;
    }).join('') : '<span class="pw-chip">暂无势力声望数据</span>';

    const assistantFloors = pwGetAssistantFloorCount();
    const nextDiceFloor = Number(data.nextDiceTurn) || 0;
    const scheduledInterval = Number(data.diceSchedule?.interval) || 0;
    const remainingFloors = nextDiceFloor > 0 ? Math.max(0, nextDiceFloor - assistantFloors) : null;
    const scheduleText = nextDiceFloor > 0
      ? `本周期${data.diceSchedule?.mode === 'fixed' ? '固定' : '随机抽到'} N=${scheduledInterval}；当前 ${assistantFloors} 个 AI 楼层；目标第 ${nextDiceFloor} 个 AI 楼层，还差 ${remainingFloors} 楼`
      : `当前 ${assistantFloors} 个 AI 楼层；下次投骰尚未安排`;
    const lastLine = last
      ? `<div style="font-size:11px;color:#8a9aaa;margin-bottom:6px;">最近一次投骰（平行世界第 ${last.turn} 轮）：${escapeHtml(PW_DICE_STORYTELLERS[last.storyteller]?.name || '')} · ${escapeHtml(PW_DICE_SEVERITY[last.severity]?.label || '')} · 紧张度 ${last.tension} · 骰子 ${last.roll} → ${last.triggered ? '⚡威胁' : '🩵补偿'}；${scheduleText}</div>`
      : `<div style="font-size:11px;color:#706058;margin-bottom:6px;">尚未投骰；${scheduleText}</div>`;

    return `
<div class="pw-main-card">
  <div class="pw-meta"><span class="pw-chip">🦊狐骰🎲~ | </span>${last ? `<span class="pw-chip">第 ${last.turn} 轮</span>` : ''}</div>
  <div style="display:flex;align-items:center;gap:10px;margin:8px 0 4px;">
    <span style="font-size:11px;color:#706058;flex:0 0 auto;">局势紧张度</span>
    <div style="flex:1;height:10px;border-radius:5px;background:rgba(255,255,255,0.08);overflow:hidden;">
      <div style="width:${tension}%;height:100%;background:${tensionColor};transition:width .3s;"></div>
    </div>
    <span style="font-size:13px;font-weight:700;color:${tensionColor};flex:0 0 auto;">${tension}</span>
  </div>
  ${lastLine}
  <details class="pw-card-details">
    <summary>🎲 骰子日志（最近 ${Math.min(8, log.length)} 条 / 共 ${log.length} 条）</summary>
    <div>${logRows || '<div style="font-size:11px;color:#706058;">暂无记录</div>'}</div>
  </details>
  <details class="pw-card-details">
    <summary>🏛️ 势力声望（${repKeys.length}）</summary>
    <div style="display:flex;gap:6px;flex-wrap:wrap;">${repHtml}</div>
  </details>
</div>`;
  }

  function pwRenderDiceStorytellerConfigHtml(config) {
    const selected = PW_DICE_STORYTELLERS[config.diceStoryteller] || PW_DICE_STORYTELLERS.xuanhu;
    const image = config.diceStorytellerImages?.[config.diceStoryteller] || {};
