      <summary style="cursor:pointer;padding:10px 12px;color:#7fdcff;font-size:12px;font-weight:700;">🎭 狐骰叙事者与投骰间隔</summary>
      <div class="pw-story-layout" style="display:grid;grid-template-columns:56px minmax(220px,1fr) minmax(150px,.8fr);min-height:260px;border-top:1px solid rgba(96,210,255,.1);">
        <div style="display:flex;flex-direction:column;align-items:center;gap:9px;padding:12px 5px;border-right:1px solid rgba(96,210,255,.1);">${avatar('linhu','❄️')}${avatar('huihu','🔥')}${avatar('xuanhu','🦊')}</div>
        <div style="padding:14px;display:flex;flex-direction:column;gap:10px;">
          <div><div id="pw-story-name" style="font-size:18px;font-weight:800;color:#dbeef6;">${selected.name}</div><div id="pw-story-subtitle" style="font-size:11px;color:#7fdcff;">${selected.subtitle}</div></div>
          <div id="pw-story-description" style="font-size:12px;color:#9eb4c2;line-height:1.7;">${selected.description}</div>
          <label class="pw-switch"><span>启用狐骰</span><input id="pw-dice-enabled" type="checkbox" ${config.diceEnabled ? 'checked' : ''}></label>
          <div class="pw-field"><label>难度</label><select id="pw-dice-difficulty"><option value="relaxed" ${config.diceDifficulty==='relaxed'?'selected':''}>悠闲</option><option value="normal" ${config.diceDifficulty==='normal'?'selected':''}>标准</option><option value="hard" ${config.diceDifficulty==='hard'?'selected':''}>艰难</option><option value="extreme" ${config.diceDifficulty==='extreme'?'selected':''}>极限</option></select></div>
          <div class="pw-field"><label>投骰间隔模式</label><select id="pw-dice-interval-mode"><option value="fixed" ${config.diceIntervalMode==='fixed'?'selected':''}>固定 N 个 AI 楼层</option><option value="range" ${config.diceIntervalMode!=='fixed'?'selected':''}>每周期随机 N（默认）</option></select></div>
