  function pwBindDiceStorytellerControls(root = topDoc) {
    const $ = id => root.querySelector?.(`#${id}`) || topDoc.getElementById(id);
    root.querySelectorAll?.('.pw-story-avatar').forEach(button => {
      button.onclick = () => {
        const storytellerId = button.dataset.storyteller;
        const storyteller = PW_DICE_STORYTELLERS[storytellerId] || PW_DICE_STORYTELLERS.xuanhu;
        pwState.config = pwLoadConfig();
        pwState.config.diceStoryteller = storytellerId;
        pwSaveConfig();

        root.querySelectorAll?.('.pw-story-avatar').forEach(avatar => {
          const active = avatar.dataset.storyteller === storytellerId;
          avatar.classList.toggle('is-active', active);
          avatar.style.borderColor = active ? '#7fdcff' : 'rgba(96,210,255,.18)';
        });
        const name = $('pw-story-name');
        const subtitle = $('pw-story-subtitle');
        const description = $('pw-story-description');
        if (name) name.textContent = storyteller.name;
        if (subtitle) subtitle.textContent = storyteller.subtitle;
        if (description) description.textContent = storyteller.description;
        const portrait = $('pw-story-portrait');
        const portraitUrl = pwState.config.diceStorytellerImages?.[storytellerId]?.portrait || storyteller.portrait || '';
        if (portrait) {
          portrait.innerHTML = portraitUrl
            ? `<img src="${escapeHtml(portraitUrl)}" alt="${escapeHtml(storyteller.name)}" style="width:100%;height:100%;object-fit:cover;">`
            : `<div style="text-align:center;color:#567080;"><div style="font-size:46px;margin-bottom:8px;">${storytellerId === 'linhu' ? '❄️' : storytellerId === 'huihu' ? '🔥' : '🦊'}</div><div>立绘接口已预留</div><div style="font-size:9px;margin-top:4px;">diceStorytellerImages.${storytellerId}.portrait</div></div>`;
        }
      };
    });
    const mode = $('pw-dice-interval-mode');
    const syncIntervalVisibility = () => {
      const fixed = $('pw-dice-fixed-wrap'); const range = $('pw-dice-range-wrap');
      if (fixed) fixed.style.display = mode.value === 'fixed' ? 'flex' : 'none';
      if (range) range.style.display = mode.value === 'fixed' ? 'none' : 'flex';
    };
    if (mode) syncIntervalVisibility();
    for (const id of ['pw-dice-enabled','pw-dice-difficulty','pw-dice-interval-mode','pw-dice-fixed','pw-dice-range-min','pw-dice-range-max']) {
      const el = $(id); if (!el) continue;
      el.onchange = () => {
        pwState.config = pwLoadConfig();
        const oldScheduleSettings = JSON.stringify({
          enabled: pwState.config.diceEnabled !== false,
          mode: pwState.config.diceIntervalMode,
          fixed: pwState.config.diceFixedInterval,
          min: pwState.config.diceRangeMin,
          max: pwState.config.diceRangeMax,
        });
        const enabled = !!$('pw-dice-enabled')?.checked;
        const difficulty = $('pw-dice-difficulty')?.value || 'normal';
        const intervalMode = $('pw-dice-interval-mode')?.value === 'fixed' ? 'fixed' : 'range';
        const fixedInterval = Math.max(1, Math.min(999, parseInt($('pw-dice-fixed')?.value) || 6));
        const min = Math.max(1, Math.min(999, parseInt($('pw-dice-range-min')?.value) || 4));
        const max = Math.max(min, Math.min(999, parseInt($('pw-dice-range-max')?.value) || 10));
        pwState.config.diceEnabled = enabled;
        pwState.config.diceDifficulty = difficulty;
        pwState.config.diceIntervalMode = intervalMode;
        pwState.config.diceFixedInterval = fixedInterval;
        pwState.config.diceRangeMin = min;
        pwState.config.diceRangeMax = max;
        pwSaveConfig();
        const newScheduleSettings = JSON.stringify({ enabled, mode: intervalMode, fixed: fixedInterval, min, max });
        if (oldScheduleSettings !== newScheduleSettings) {
          const data = pwLoadData(); data.nextDiceTurn = 0; data.diceSchedule = null; pwSaveData(data);
        }
        if (id === 'pw-dice-interval-mode') syncIntervalVisibility();
      };
    }
  }

  // 🎲 事件分层标签元信息
  function pwTierMeta(tier) {
    if (tier === 'urgent') return { icon: '🔴', label: '紧急', color: '#ff5a4a' };
    if (tier === 'mid') return { icon: '🟡', label: '中层', color: '#f0be5a' };
    return { icon: '🟢', label: '底层', color: '#4cc850' };
  }

  function pwRenderModulesHtml(data) {
    if (!pwHasContent(data)) {
      return `
<div class="pw-card pw-card-empty pw-card-impact-none">
  <div class="pw-meta"><span class="pw-chip">未启动</span></div>
  <h4>暂无平行世界数据</h4>
  <pre>当前平行世界为空。点击"推进所有事件"后，后台世界才会开始独立运转。</pre>
</div>`;
    }

    const globalHtml = `
<div class="pw-main-card">
  <div class="pw-meta">
    <span class="pw-chip">第 ${escapeHtml(data.turn || 0)} 轮</span>
    <span class="pw-chip">${escapeHtml(data.worldClock || '剧情内时间未明')}</span>
    ${data.updatedAt ? `<span class="pw-chip">更新：${escapeHtml(new Date(data.updatedAt).toLocaleString('zh-CN'))}</span>` : ''}
  </div>
  <h4>${escapeHtml(data.globalState?.title || '当前世界状态')}</h4>

  <details class="pw-card-details">
    <summary>世界整体状态</summary>
    <pre>${escapeHtml(data.globalState?.detail || '暂无')}</pre>
  </details>
</div>`;

    const modulesAll = Array.isArray(data.modules) ? data.modules : [];

    if (!modulesAll.length) {
      return `${globalHtml}
${pwRenderDiceLogHtml(data)}
<div class="pw-card pw-card-empty pw-card-impact-none">
  <pre>暂无平行世界模块。</pre>
</div>`;
    }

    // 🎲 按事件分层排序：🔴紧急 -> 🟡中层 -> 🟢底层
    const turn = data.turn || 0;
    const tierOrder = { urgent: 0, mid: 1, low: 2 };
    const tiered = modulesAll.map(m => ({ m, tier: pwTierOfModule(m, turn) }));
    tiered.sort((a, b) => (tierOrder[a.tier] - tierOrder[b.tier]) || (Number(b.m?.isDiceEvent === true) - Number(a.m?.isDiceEvent === true)));
    const modules = tiered.map(t => t.m);

    const cards = tiered.map(({ m, tier }, index) => {
      const tierMeta = pwTierMeta(tier);
      const detailLength = String(m.detail || '').length;
      const auditLength = String(m.roleAudit || '').length;
      const summaryLength = String(m.summary || '').length;

      let sizeClass = 'pw-card-mid';

      if (detailLength > 900 || auditLength > 500) {
        sizeClass = 'pw-card-large';
      } else if (detailLength < 260 && summaryLength < 140) {
        sizeClass = 'pw-card-small';
      }

      const offsetClass = index % 5 === 1
        ? 'pw-card-offset-a'
        : index % 5 === 3
          ? 'pw-card-offset-b'
          : '';

      const effectiveLevel = pwGetEffectiveImpactLevel(m);
      const impactClass = pwImpactCardClass(m);
      const progressHtml = pwBuildProgressHtml(m);
      const moduleId = escapeHtml(m.id || '');
      const isExpired = m.lifecycleState === 'aftermath_pending' || m.lifecycleState === 'aftermath_judged';

      return `
<div class="pw-card ${sizeClass} ${offsetClass} ${impactClass} ${isExpired ? 'pw-card-expired' : ''}">
  <div class="pw-card-topbar">
    <div class="pw-meta" style="margin-bottom:0;">
      <span class="pw-chip" style="color:${tierMeta.color};">${tierMeta.icon} ${tierMeta.label}</span>
      <span class="pw-chip">${escapeHtml(m.type || 'other')}</span>
      <span class="pw-chip">影响：${escapeHtml(pwImpactLabel(effectiveLevel))}</span>
      ${m.lifecycleState === 'ready' ? `<span class="pw-chip" style="color:#ffb36b;">⏳ 剩余 ${escapeHtml(m.remainingTurns)} 轮</span>` : ''}
      ${m.lifecycleState === 'aftermath_pending' ? `<span class="pw-chip" style="color:#9a9aa4;">0轮 · 已发生 · 待余波判断</span>` : ''}
      ${m.lifecycleState === 'aftermath_judged' ? `<span class="pw-chip" style="color:#777782;">余波已判断 · 下轮清理</span>` : ''}
      ${m.lifecycleState === 'static' ? `<span class="pw-chip" style="color:#8fa4aa;">静态背景</span>` : ''}
      ${m.parentEventId ? `<span class="pw-chip" style="color:#7fdcff;">🔗 连锁</span>` : ''}
      ${['autonomous','goal','commitment','debt','secret'].includes(String(m.origin || '').toLowerCase()) ? `<span class="pw-chip" style="color:#7fc7b0;">自主事件</span>` : ''}
      ${m.isDiceEvent ? `<span class="pw-chip" style="color:${m.diceOutcome === 'penalty' ? '#ff8070' : '#78d7c8'};">🎲 ${escapeHtml(pwDiceOutcomeLabel(m.diceOutcome))} · d100=${escapeHtml(m.diceRoll ?? '?')} / ${escapeHtml(m.diceThreshold ?? '?')}</span>` : ''}
      ${m.perspective ? `<span class="pw-chip">视角：${escapeHtml(m.perspective)}</span>` : ''}
      ${m.currentLocation ? `<span class="pw-chip">${escapeHtml(m.currentLocation)}</span>` : ''}
    </div>
    <div class="pw-card-actions" style="display:flex;gap:6px;align-items:center;">
      ${m.isDiceEvent || isExpired ? '' : `<button type="button" class="pw-module-advance" data-pw-id="${moduleId}" title="只推进这个事件，不影响其他事件">▶ 推进</button>`}
      <button type="button" class="pw-module-delete" data-pw-id="${moduleId}" title="删除这个平行世界条目及对应摘要">🗑</button>
    </div>
  </div>

  <h4>${escapeHtml(m.title || '未命名模块')}</h4>

  ${progressHtml}

  ${m.detail ? `
  <div class="pw-meta">完整后台生成内容</div>
  <pre>${escapeHtml(m.detail)}</pre>` : ''}

  ${m.roleAudit ? `
  <details class="pw-card-details">
    <summary>人设审查结论</summary>
    <pre>${escapeHtml(m.roleAudit)}</pre>
  </details>` : ''}

  ${m.nextTendency ? `
  <details class="pw-card-details">
    <summary>下一步倾向</summary>
    <pre>${escapeHtml(m.nextTendency)}</pre>
  </details>` : ''}
</div>`;
    }).join('');

    return `${globalHtml}
${pwRenderDiceLogHtml(data)}
<div class="pw-masonry">
${cards}
</div>
${pwRenderNpcCardsHtml(data)}`;
  }

  function pwOpenStateFloat() {
    pwInjectStyle();

    const old = topDoc.getElementById('pw-state-float');

    if (old) {
      old.remove();
      return;
    }

    const box = topDoc.createElement('div');
    box.id = 'pw-state-float';
    // ✅ 状态小悬浮窗：锁 overflow / 锁 resize（缩放由我们自带的 8 边手柄处理）
    box.style.resize = 'none';
    box.style.overflow = 'hidden';
    box.innerHTML = `
<div id="pw-state-head">
  <span>🌌 当前平行世界状态</span>
  <span id="pw-state-close" style="cursor:pointer;color:#7891a2;">✕</span>
</div>
<div id="pw-state-body"></div>`;

    topDoc.body.appendChild(box);

    topDoc.getElementById('pw-state-close').onclick = () => box.remove();

    pwRenderStateFloat();
    pwBindModuleActionButtons(box);
    pwBindNpcActionButtons(box);
    pwMakeFloatDraggable(box);
    // ✅ 关键修复：状态小悬浮窗也必须走平行世界专用移动端铺满逻辑
    pwForceMobileLayoutNow();
    setTimeout(() => pwForceMobileLayoutNow(), 50);
    setTimeout(() => pwForceMobileLayoutNow(), 300);
    setTimeout(() => pwForceMobileLayoutNow(), 800);

    // ✅ 监听手机地址栏/键盘/旋转导致的 viewport 变化
    try {
      const vv = topWindow.visualViewport;

      if (vv && !topWindow.__pwStateFloatViewportFixBound) {
        topWindow.__pwStateFloatViewportFixBound = true;

        const onPwStateViewportChange = () => {
          setTimeout(() => {
            try {
              pwForceMobileLayoutNow();
            } catch { }
          }, 60);
        };

        vv.addEventListener('resize', onPwStateViewportChange);
        vv.addEventListener('scroll', onPwStateViewportChange);
        topWindow.addEventListener('resize', onPwStateViewportChange);
        topWindow.addEventListener('orientationchange', onPwStateViewportChange);
      }
    } catch { }
  }

  function pwForceMobileLayoutNow() {
    let isMobile = false;

    try {
      const vw = topWindow.visualViewport?.width || topWindow.innerWidth || topDoc.documentElement.clientWidth || 0;
      isMobile = vw <= 768;
    } catch {
      isMobile = (topWindow.innerWidth || 0) <= 768;
    }

    if (!isMobile) return;

    const vv = topWindow.visualViewport;

    const viewportW = Math.floor(vv?.width || topWindow.innerWidth || topDoc.documentElement.clientWidth || 390);
    const viewportH = Math.floor(vv?.height || topWindow.innerHeight || topDoc.documentElement.clientHeight || 700);

    const offsetTop = Math.floor(vv?.offsetTop || 0);
    const offsetLeft = Math.floor(vv?.offsetLeft || 0);

    const gap = viewportW <= 420 ? 6 : 8;

    const top = offsetTop + gap;
    const left = offsetLeft + gap;
    const width = Math.max(1, viewportW - gap * 2);
    const height = Math.max(1, viewportH - gap * 2);

    const setImp = (el, prop, value) => {
      try {
        el.style.setProperty(prop, value, 'important');
      } catch {
        el.style[prop] = value;
      }
    };

    for (const id of ['pw-panel', 'pw-state-float']) {
      const el = topDoc.getElementById(id);
      if (!el) continue;

      setImp(el, 'position', 'fixed');
      setImp(el, 'top', `${top}px`);
      setImp(el, 'left', `${left}px`);
      setImp(el, 'right', 'auto');
      setImp(el, 'bottom', 'auto');

      // ✅ 关键修复：移动端直接给明确宽高，不再依赖 left/right/bottom 自动撑满
      setImp(el, 'width', `${width}px`);
      setImp(el, 'height', `${height}px`);
      setImp(el, 'max-width', `${width}px`);
      setImp(el, 'max-height', `${height}px`);
      setImp(el, 'min-width', '0');
      setImp(el, 'min-height', '0');

      setImp(el, 'transform', 'none');
      setImp(el, 'translate', 'none');

      setImp(el, 'box-sizing', 'border-box');
      setImp(el, 'overflow-x', 'hidden');
      // ✅ 新版边栏布局：panel自身不滚动，内部.main和.mb-body滚动
      if (id === 'pw-panel') {
        setImp(el, 'overflow-y', 'hidden');
        setImp(el, 'display', 'flex');
        setImp(el, 'flex-direction', 'column');
        setImp(el, 'border-radius', '14px');
        setImp(el, 'padding', '0');
      } else {
        setImp(el, 'overflow-y', 'auto');
      }
      setImp(el, '-webkit-overflow-scrolling', 'touch');
      setImp(el, 'overscroll-behavior', 'contain');
    }

    const overlay = topDoc.getElementById('pw-overlay');
    if (overlay) {
      setImp(overlay, 'position', 'fixed');
      setImp(overlay, 'inset', '0');
      setImp(overlay, 'width', '100vw');
      setImp(overlay, 'height', '100vh');
      setImp(overlay, 'touch-action', 'none');
      setImp(overlay, 'overscroll-behavior', 'none');
    }

    const stateFloat = topDoc.getElementById('pw-state-float');
    if (stateFloat) {
      setImp(stateFloat, 'display', 'flex');
      setImp(stateFloat, 'flex-direction', 'column');

      const head = topDoc.getElementById('pw-state-head');
      const body = topDoc.getElementById('pw-state-body');

      if (head) {
        setImp(head, 'flex', '0 0 auto');
        setImp(head, 'cursor', 'default');
      }

      if (body) {
        setImp(body, 'flex', '1 1 auto');
        setImp(body, 'min-height', '0');
        setImp(body, 'overflow-y', 'auto');
        setImp(body, '-webkit-overflow-scrolling', 'touch');
      }

      stateFloat.querySelectorAll('.pw-masonry').forEach(m => {
        m.style.setProperty('column-count', '1', 'important');
        m.style.setProperty('column-gap', '0', 'important');
      });
      stateFloat.querySelectorAll('.pw-card, .pw-card-small, .pw-card-mid, .pw-card-large, .pw-card-offset-a, .pw-card-offset-b').forEach(card => {
        card.style.setProperty('box-sizing', 'border-box', 'important');
        card.style.setProperty('transform', 'none', 'important');
        card.style.setProperty('display', 'block', 'important');
        card.style.setProperty('width', '100%', 'important');
      });
    }

    const panel = topDoc.getElementById('pw-panel');
    if (panel) {
      // ✅ 保持 flex 列布局：display:flex + flex-direction:column
      //    之前误写成 display:block，会覆盖上方循环里设置的 display:flex，
      //    导致 .work(flex:1) 失效 → .main 无法撑满剩余高度 → 滚动失效。
      setImp(panel, 'display', 'flex');
      setImp(panel, 'flex-direction', 'column');
      setImp(panel, 'padding', '0');

      panel.querySelectorAll('.pw-grid').forEach(g => {
        g.style.setProperty('grid-template-columns', '1fr', 'important');
      });
      panel.querySelectorAll('.pw-story-layout').forEach(g => {
        g.style.setProperty('grid-template-columns', '48px 1fr', 'important');
        const portrait = g.querySelector('#pw-story-portrait');
        if (portrait) portrait.style.setProperty('display', 'none', 'important');
      });

      panel.querySelectorAll('.pw-masonry').forEach(m => {
        m.style.setProperty('column-count', '1', 'important');
        m.style.setProperty('column-gap', '0', 'important');
      });

      panel.querySelectorAll('.pw-card, .pw-card-small, .pw-card-mid, .pw-card-large, .pw-card-offset-a, .pw-card-offset-b').forEach(card => {
        card.style.setProperty('transform', 'none', 'important');
        card.style.setProperty('display', 'block', 'important');
        card.style.setProperty('width', '100%', 'important');
      });
    }
  }


  function pwPositionMiniBubble() {
    const mini = topDoc.getElementById('pw-mini-bubble');
    const fox = topDoc.getElementById('ss-float-bubble');

    if (!mini || !fox) return;

    const rect = fox.getBoundingClientRect();
    const vw = topWindow.innerWidth || topDoc.documentElement.clientWidth || 800;

    const miniSize = 34;
    const gap = 8;

    const centerX = rect.left + rect.width / 2;
    let left = centerX - miniSize / 2;
    let top = rect.top - miniSize - gap;

    if (top < 8) {
      top = rect.bottom + gap;
    }

    left = Math.max(6, Math.min(vw - miniSize - 6, left));

    mini.style.left = `${left}px`;
    mini.style.top = `${top}px`;
    mini.style.right = 'auto';
    mini.style.bottom = 'auto';
  }

