  function pwMakeFloatDraggable(box) {
    let dragging = false;
    let sx = 0;
    let sy = 0;
    let sl = 0;
    let st = 0;

    const head = topDoc.getElementById('pw-state-head');
    if (!head) return;

    // ✅ 拖动开始时，临时把 8 个 resize 手柄的 pointer-events 关掉，
    // 避免拖动期间手柄误触导致“看起来拖不动”
    const toggleHandles = (enabled) => {
      const handles = box.querySelectorAll('.pw-resize-handle');
      handles.forEach(h => {
        h.style.pointerEvents = enabled ? 'auto' : 'none';
      });
    };

    const down = e => {
      if (e.target?.id === 'pw-state-close') return;
      if (e.target?.classList?.contains('pw-resize-handle')) return;

      dragging = true;
      toggleHandles(false);
      const rect = box.getBoundingClientRect();
      sx = e.clientX;
      sy = e.clientY;
      sl = rect.left;
      st = rect.top;

      box.style.left = `${rect.left}px`;
      box.style.top = `${rect.top}px`;
      box.style.right = 'auto';
      box.style.bottom = 'auto';

      e.preventDefault();
    };

    const move = e => {
      if (!dragging) return;

      e.preventDefault?.();
      e.stopPropagation?.();

      const vw = topWindow.innerWidth || 900;
      const vh = topWindow.innerHeight || 700;
      const rect = box.getBoundingClientRect();

      const nl = Math.max(4, Math.min(vw - rect.width - 4, sl + e.clientX - sx));
      const nt = Math.max(4, Math.min(vh - rect.height - 4, st + e.clientY - sy));

      box.style.left = `${nl}px`;
      box.style.top = `${nt}px`;
    };

    const up = () => {
      if (!dragging) return;
      dragging = false;
      toggleHandles(true);
    };

    head.addEventListener('pointerdown', down);
    topDoc.addEventListener('pointermove', move);
    topDoc.addEventListener('pointerup', up);
  }

  function pwOpenPanel() {
    pwInjectStyle();

    const old = topDoc.getElementById('pw-panel');
    if (old) {
      old.previousElementSibling?.remove();
      old.remove();
      return;
    }

    const overlay = topDoc.createElement('div');
    overlay.id = 'pw-overlay';
    overlay.onclick = () => {
      xhGuideEnd();
      overlay.remove();
      topDoc.getElementById('pw-panel')?.remove();
    };

    const panel = topDoc.createElement('div');
    panel.id = 'pw-panel';
    panel.style.position = '';
    // ❌ 主面板：不加 resize / 不锁 overflow
    panel.style.resize = '';

    topDoc.body.appendChild(overlay);
    topDoc.body.appendChild(panel);

    pwRenderPanel();
    xhGuideEnhancePanel(panel, 'pw', '平行世界');

    // 🦊 挂载平行世界提示词自定义编辑器到高级页
    try {
      const pwAdvPane = panel.querySelector('[data-pwpane="adv"]');
