      confirm: '确定要恢复平行世界本面板的全部设置为默认吗？\n\n这会清掉：自动模式/间隔、推进模式、API 类型/自定义 API、标签过滤等。\n\n注意：本聊天里已生成的事件、摘要不会被清掉，只清"面板设置"。\n\n此操作不可撤销。',
      onReset: () => {
        try {
          localStorage.removeItem(PW.CONFIG_KEY);
          pwState.config = pwLoadConfig();
        } finally {
          topDoc.getElementById('pw-overlay')?.remove();
          panel.remove();
          setTimeout(() => { try { pwOpenPanel(); } catch {} }, 50);
        }
      },
    });

    // ❌ 主面板不需要缩放：恢复 panel.style.overflow + 不加 resize handle
    try {
      panel.style.overflowX = 'hidden';
      panel.style.overflowY = 'auto';
    } catch { }

    // ✅ 移动端立即强制铺满
    pwForceMobileLayoutNow();
