  function pwReadConfigFromPanel() {
    const $ = id => topDoc.getElementById(id);
    const panel = $('pw-panel');
    if (!panel) return;

    pwState.config.enabled = !!$('pw-enabled')?.checked;
    pwState.config.autoMode = $('pw-auto-mode')?.value || 'manual';
    pwState.config.backgroundSilent = !!$('pw-background-silent')?.checked;
      pwState.config.autoInterval = Math.max(1, parseInt($('pw-auto-interval')?.value) || 5);
    pwState.config.generationMode = $('pw-generation-mode')?.value === 'quality' ? 'quality' : 'fast';
    pwState.config.eventDifficulty = ['easy', 'normal', 'hard'].includes($('pw-event-difficulty')?.value) ? $('pw-event-difficulty').value : 'normal';
    pwState.config.diceEnabled = $('pw-dice-enabled') ? !!$('pw-dice-enabled').checked : pwState.config.diceEnabled !== false;
    pwState.config.diceDifficulty = $('pw-dice-difficulty')?.value || pwState.config.diceDifficulty || 'normal';
    pwState.config.diceIntervalMode = $('pw-dice-interval-mode')?.value === 'fixed' ? 'fixed' : 'range';
    pwState.config.diceFixedInterval = Math.max(1, Math.min(999, parseInt($('pw-dice-fixed')?.value) || pwState.config.diceFixedInterval || 6));
    pwState.config.diceRangeMin = Math.max(1, Math.min(999, parseInt($('pw-dice-range-min')?.value) || pwState.config.diceRangeMin || 4));
    pwState.config.diceRangeMax = Math.max(pwState.config.diceRangeMin, Math.min(999, parseInt($('pw-dice-range-max')?.value) || pwState.config.diceRangeMax || 10));

    // 兼容旧字段
    pwState.config.autoAdvance = pwState.config.autoMode !== 'manual';

    // ✅ 推进模式 / 动态推进上限 / 聊天楼层上限
    const advRaw = $('pw-advance-mode')?.value;
    pwState.config.advanceMode = advRaw === 'legacy_full' ? 'legacy_full' : 'two_phase';
    pwState.config.dynamicMaxModules = Math.max(1, Math.min(24, parseInt($('pw-dynamic-max')?.value) || 4));

    const chlRaw = String($('pw-chat-history-limit')?.value || '').trim();
    if (!chlRaw || /^all$/i.test(chlRaw)) {
      pwState.config.chatHistoryLimit = '';
    } else {
      const n = parseInt(chlRaw);
      pwState.config.chatHistoryLimit = Number.isFinite(n) && n > 0 ? n : '';
    }

    pwState.config.moduleCount = Math.max(3, Math.min(24, parseInt($('pw-module-count')?.value) || 8));
    pwState.config.detailLevel = $('pw-detail-level')?.value || 'normal';
    const eventMinRaw = Math.max(20, Math.min(5000, parseInt($('pw-event-word-min')?.value) || 100));
    const eventMaxRaw = Math.max(20, Math.min(5000, parseInt($('pw-event-word-max')?.value) || 800));
    pwState.config.eventWordMin = Math.min(eventMinRaw, eventMaxRaw);
    pwState.config.eventWordMax = Math.max(eventMinRaw, eventMaxRaw);
    delete pwState.config.maxInjectChars;
    pwState.config.maxInjectModules = Math.max(1, Math.min(50, parseInt($('pw-max-inject-modules')?.value) || 8));
    pwState.config.impactMode = $('pw-impact-mode')?.value || 'strong';
    pwState.config.maxUrgentEvents = Math.max(1, Math.min(10, parseInt($('pw-max-urgent-events')?.value) || 3));
    pwState.config.autoDelayMs = Math.max(300, Math.min(20000, parseInt($('pw-auto-delay')?.value) || 1500));
    pwState.config.userGuide = $('pw-user-guide')?.value || '';

    pwState.config.apiType = $('pw-api-type')?.value || 'current';

    if (!pwState.config.customApi) pwState.config.customApi = { ...PW_DEFAULT_CONFIG.customApi };

    pwState.config.customApi.proxyPreset = $('pw-proxy-preset')?.value || '';
    pwState.config.customApi.apiurl = $('pw-api-url')?.value?.trim() || '';
    pwState.config.customApi.key = $('pw-api-key')?.value?.trim() || '';
    pwState.config.customApi.model = $('pw-model')?.value?.trim() || '';
    pwState.config.customApi.temperature = $('pw-temperature')?.value || '';
    pwState.config.customApi.max_tokens = $('pw-max-tokens')?.value || '';
    pwState.config.customApi.top_p = $('pw-top-p')?.value || '';
    pwState.config.customApi.frequency_penalty = $('pw-freq-pen')?.value || '';
    pwState.config.customApi.presence_penalty = $('pw-pres-pen')?.value || '';

    // 🦊 附加参数（YAML）：无论 apiType 都保存，避免切换 API 类型后丢失（实际仅 custom 模式生效）
    {
      const __extra = ssReadExtraParamsFromPanel('pw', topDoc);
      pwState.config.customApi.extraBodyParamsYaml = __extra.extraBodyParamsYaml;
      pwState.config.customApi.excludeBodyParamsYaml = __extra.excludeBodyParamsYaml;
      pwState.config.customApi.extraHeadersYaml = __extra.extraHeadersYaml;
    }

    // 🏷️ 同步标签过滤设置（如果当前 DOM 里能读到，就一起保存；读不到则保留旧值）
    try {
      const filterCb = $('pw-content-filter');
      if (filterCb) {
        pwState.config.enableContentFilter = !!filterCb.checked;
      }
      const incRows = panel.querySelectorAll?.('.pw-inc-tag-row') || [];
      const excRows = panel.querySelectorAll?.('.pw-exc-tag-row') || [];
      if (incRows.length || excRows.length) {
        pwState.config.includeTagPairs = ssReadTagPairsEditor('pw-inc', panel);
        pwState.config.excludeTagPairs = ssReadTagPairsEditor('pw-exc', panel);
        pwState.config.includeTagStarts = ssPairsToLines(pwState.config.includeTagPairs, 'start');
        pwState.config.includeTagEnds = ssPairsToLines(pwState.config.includeTagPairs, 'end');
        pwState.config.excludeTagStarts = ssPairsToLines(pwState.config.excludeTagPairs, 'start');
        pwState.config.excludeTagEnds = ssPairsToLines(pwState.config.excludeTagPairs, 'end');
      }
    } catch (e) {
      log('[平行世界] 同步标签过滤设置失败', e);
    }

    pwSaveConfig();

    if (pwState.config.autoMode !== 'manual') {
      pwRegisterAutoListener();
    } else {
      pwUnregisterAutoListener();
    }

    // 保存时也同步一次 UI，避免“每隔 N 次”输入框在非 interval 模式下残留显示
    try {
      const wrap = topDoc.getElementById('pw-auto-interval-wrap');
      if (wrap) {
        wrap.style.display = pwState.config.autoMode === 'interval' ? 'flex' : 'none';
      }
    } catch { }
  }

  function pwApplyAutoMode(mode, interval) {
    const nextMode = ['manual', 'auto', 'interval'].includes(mode) ? mode : 'manual';
    const cfg = pwState.config || pwLoadConfig();
    const previousMode = cfg.autoMode || 'manual';
    cfg.autoMode = nextMode;
    if (interval != null) cfg.autoInterval = Math.max(1, parseInt(interval, 10) || 5);
    if (previousMode !== nextMode && nextMode !== 'interval') {
      pwState.autoCounter = 0;
      pwState.lastAutoMessageId = null;
      pwSaveAutoCounter();
    }
    pwState.config = cfg;
    pwSaveConfig();
    if (nextMode === 'manual') pwUnregisterAutoListener();
    else pwRegisterAutoListener();
    return cfg;
  }

  // 🎯 平行世界 rail/dock 点击委托（防止重渲染后漏绑定导致无法切换）
  function pw__panelRailDelegation(e) {
    const panel = topDoc.getElementById('pw-panel');
    if (!panel) return;
    const it = e.target?.closest?.('.rail .mitem[data-pwtab]');
    if (!it) return;
    panel.querySelectorAll('.rail .mitem').forEach(x => x.classList.remove('cur'));
    it.classList.add('cur');
    const key = it.dataset.pwtab;
    const cur = panel.querySelector('.main .pw-tab-pane.active');
    if (cur && cur.dataset.pwpane === key) return;
    if (cur) { cur.style.opacity = '.4'; setTimeout(() => { cur.classList.remove('active'); cur.style.opacity = ''; }, 150); }
    setTimeout(() => { const nxt = panel.querySelector(`.main .pw-tab-pane[data-pwpane="${key}"]`); if (nxt) nxt.classList.add('active'); }, 160);
  }
  function pw__panelDockDelegation(e) {
    const panel = topDoc.getElementById('pw-panel');
    if (!panel) return;
    const d = e.target?.closest?.('.mb-dock .dock-item[data-pwdock]');
    if (!d) return;
    panel.querySelectorAll('.mb-dock .dock-item').forEach(x => x.classList.remove('cur'));
    d.classList.add('cur');
    const key = d.dataset.pwdock;
    panel.querySelectorAll('.main .pw-tab-pane').forEach(p => p.classList.remove('active'));
    const nxt = panel.querySelector(`.main .pw-tab-pane[data-pwpane="${key}"]`);
    if (nxt) nxt.classList.add('active');
    const mbSubMap = { ov: '主控 · 快捷操作 · 总开关', sum: '摘要 · 注入编辑器', ev: '事件 · 后台世界模块', th: '思考 · 命运骰 · 质量模式', cfg: '参数 · 开关 · 规模 · 模式', adv: 'API · 标签过滤 · 自定义模型' };
    const subEl = topDoc.getElementById('pw-mb-sub'); if (subEl) subEl.textContent = mbSubMap[key] || '';
  }

