    // ✅ 关闭按钮：PC端 pw-close-pc + 移动端 pw-close
    const closeFn = () => { xhGuideEnd(); ssCloseModal('pw-overlay', 'pw-panel'); };
    if ($('pw-close')) $('pw-close').onclick = closeFn;
    if ($('pw-close-pc')) $('pw-close-pc').onclick = closeFn;

    // 🌌 底栏悬浮窗按钮：PC端 pw-dock-btn-pc + 移动端 pw-dock-btn
