      try { xhDockToggleVisibility('pw'); }
      catch (e) { log('[平行世界] 底栏悬浮窗切换失败:', e); toast(`❌ 失败：${e?.message || e}`, 'error'); }
    };
    if ($('pw-dock-btn')) $('pw-dock-btn').onclick = dockFn;
    if ($('pw-dock-btn-pc')) $('pw-dock-btn-pc').onclick = dockFn;

    // ✅ PC端 左rail tab切换（统一走事件委托，避免重渲染后漏绑定 / 重复绑定）
    panel.removeEventListener('click', pw__panelRailDelegation);
