    $('pw-copy-inject').onclick = async () => {
      pwReadConfigFromPanel();

      const plain = pwBuildInjectPlainText();

      if (!plain.trim()) {
        toast('⚠️ 当前没有可复制的平行世界摘要', 'warning');
        return;
      }

      const ok = await copyTextToClipboard(`<parallel_world>\n${plain}\n</parallel_world>`);
      toast(ok ? '✅ 已复制当前平行世界注入摘要' : '❌ 复制失败', ok ? 'success' : 'error');
    };

    $('pw-clear').onclick = () => {
      const ok = topWindow.confirm
        ? topWindow.confirm('确定要清空当前聊天的平行世界数据吗？\n\n这会彻底清除当前聊天的所有平行世界事件、摘要、注入文本，且不可恢复。\n\n（不会清掉「平行世界配置」，比如自动模式、API 设置、注入规则等都会保留。）')
        : confirm('确定要清空当前聊天的平行世界数据吗？');

      if (!ok) return;

      try {
        // ① 删掉当前 (char, chat) 这把"主 key"
        try { localStorage.removeItem(pwDataKey()); } catch { }
        try { localStorage.removeItem(pwSnapshotKey()); } catch { }

        // ② 扫描整个 localStorage，把任何属于"当前角色卡+当前聊天"的
        //    平行世界残留 key 都清掉（包括历史 chatId 编码变化、__PENDING__ 孤儿、
        //    旧版本写入的兼容 key 等）。
        //    匹配条件：以 PW.DATA_PREFIX 开头 + 包含当前 charId 编码。
        try {
          const prefix = PW.DATA_PREFIX;
          const charEnc = encodeURIComponent(getCurrentCharId() || '');
          const chatEnc = encodeURIComponent(pwGetChatId() || '');
          const toRemove = [];
          for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (!k || !k.startsWith(prefix)) continue;
            // 命中条件：包含当前聊天编码、或当前角色卡下 __PENDING__ 残留、或恰好是主 key
            if (charEnc && k.includes(charEnc) && (
              (chatEnc && k.includes(chatEnc)) ||
              k.includes(`${prefix}${charEnc}_${encodeURIComponent('__PENDING__')}`)
            )) {
              toRemove.push(k);
            }
          }
          for (const k of toRemove) {
            try { localStorage.removeItem(k); } catch { }
          }
          if (toRemove.length) {
            log(`[平行世界·清空] 已清理 ${toRemove.length} 个相关 key`, toRemove);
          }
        } catch (e) {
          log('[平行世界·清空] 扫描清理失败（不影响主流程）', e);
        }
      } catch { }

      // ③ 清运行态：自动计数、上次消息 id、单条/整轮 running、internal 标记，
      //    防止"虽然 localStorage 没了但旧 pwState.data 还在内存里被读到"。
      try {
        pwState.data = null;
        pwState.autoCounter = 0;
        pwState.lastAutoMessageId = null;
        pwState.branchEpoch++;
        pwState.runGuard = null;
      } catch { }

      // ④ 写入一份空数据并保存。pwSaveData 会按当前 (char, chat) 落盘，
      //    保证后续 pwLoadData() 读出来的就是干净的 cleared:true 状态，
      //    pwHasContent() 直接返回 false，主线请求里也不会注入任何平行世界内容。
      try {
        pwSaveData(pwEmptyData());
      } catch { }

      // ⑤ 主线请求里曾经"已消费"或"待消费"的注入文本：靠 pwLoadData() + cleared:true
      //    判断即可（pwHasContent → false，ssGetParallelWorldCurrentInjectText 直接返回 ''），
      //    所以不需要再去翻预设条目。

      pwSetStatus('已清空');
      pwRenderPanel();
      pwRenderStateFloat();

      toast('🗑️ 已清空当前平行世界（所有相关 localStorage 残留已一并清除）', 'success');
    };

    $('pw-save-inject-text').onclick = () => {
      const data = pwLoadData();
      if (!data.inject) data.inject = {};
      data.cleared = false;
      data.inject.manual_text = $('pw-inject-manager')?.value || '';
      data.inject.consumed = false;
      pwSaveData(data);
      toast('✅ 已保存手动注入摘要', 'success');
