      'pw-event-word-min',
      'pw-event-word-max',
      'pw-max-inject-modules',
      'pw-impact-mode',
      'pw-max-urgent-events',
      'pw-auto-delay',
      'pw-user-guide',
      'pw-proxy-preset',
      'pw-api-url',
      'pw-api-key',
      'pw-model',
      'pw-temperature',
