  // 统一生成"分析控制"指令串，所有分析模块共用
  function novelBuildAnalysisDirectives() {
    const detail = String(novelModeConfig?.novelAnalysisDetail || '详细').trim() || '详细';
    let words = Number(novelModeConfig?.novelAnalysisWords);
    if (!Number.isFinite(words) || words < 100) words = 1500;
    const note = String(novelModeConfig?.novelAnalysisUserNote || '').trim();
    let s = `【分析控制（必须遵守）】
- 详细程度：${detail}（${detail === '简洁' ? '只写最关键的要点，不展开例句' : detail === '极度详尽' ? '尽可能展开，穷举维度与典型例句指示' : '覆盖全部维度，要点清楚'}）
- 目标字数：约 ${words} 字（不足则补足关键维度，超出则压缩冗余，但不要删掉必填维度）`;
    if (note) s += `\n- 用户补充要求（优先级最高，必须服从）：\n${note}`;
    return s;
  }

  function loadNovelModeConfig() {
    try {
      const raw = localStorage.getItem(CONFIG.NOVEL.STORAGE_KEY);
      const parsed = raw ? JSON.parse(raw) : {};
      let sourceText = localStorage.getItem(CONFIG.NOVEL.SOURCE_KEY) || parsed.sourceText || '';
      // 老版本曾把整篇小说写进 sourceText，会导致下次打开面板时 textarea 渲染卡死。一次性大小护栏。
      if (sourceText.length > 200000) {
        try { localStorage.removeItem(CONFIG.NOVEL.SOURCE_KEY); } catch { }
        sourceText = '';
      }
      return {
        ...novelModeConfig,
        ...parsed,
        sourceText,
      };
    } catch (e) {
      return { ...novelModeConfig };
    }
  }

