  }

  // 检测请求里是否带有"分析任务" sentinel；同时把 sentinel 从 content 中剥离掉。
  // 数组形态：扫所有消息，命中即返回 true 并就地清掉所有命中。
  // ⚠️ 命中后还会在 array 上挂一个 __novelAnalysisRequest 标记，让"同一份请求被两个事件
  //    （GENERATE_AFTER_COMBINE_PROMPTS / CHAT_COMPLETION_PROMPT_READY）先后命中"
  //    时，第二次回调即使因 sentinel 已被剥走而探测不到，也能凭标记继续识别为分析请求，
  //    避免落入主对话路径误注入头/尾。
  function novelDetectAndStripAnalysisSentinelInArray(arr) {
    if (!Array.isArray(arr)) return false;
    // 标记优先：sentinel 已经被前一次回调剥走时仍能识别
    if (arr.__novelAnalysisRequest) return true;
    let hit = false;
    for (const msg of arr) {
      if (!msg || typeof msg.content !== 'string') continue;
      if (msg.content.includes(SS_NOVEL_ANALYSIS_SENTINEL)) {
        hit = true;
        msg.content = msg.content.split(SS_NOVEL_ANALYSIS_SENTINEL).join('').replace(/^\s+/, '');
      }
    }
    if (hit) {
      try { arr.__novelAnalysisRequest = true; } catch { }
    }
    return hit;
  }
  function novelDetectAndStripAnalysisSentinelInString(s) {
    const str = String(s || '');
    if (!str.includes(SS_NOVEL_ANALYSIS_SENTINEL)) return { hit: false, content: str };
    return { hit: true, content: str.split(SS_NOVEL_ANALYSIS_SENTINEL).join('') };
  }

  // 在单条字符串内容里剥离旧的小说头/尾注入哨兵块，避免重复堆叠。
  function novelStripInjectedBlocks(text) {
    return String(text || '')
      .replace(
        new RegExp(
          `\\s*${SS_NOVEL_HEAD_START.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}[\\s\\S]*?${SS_NOVEL_HEAD_END.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*`,
          'g'
        ),
        ''
      )
      .replace(
        new RegExp(
          `\\s*${SS_NOVEL_TAIL_START.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}[\\s\\S]*?${SS_NOVEL_TAIL_END.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*`,
          'g'
        ),
        ''
      );
  }

  // 数组形式（chat completion 路径）：插入到最顶部 system + 最尾部 user
  function novelInjectIntoPromptArray(arr) {
    if (!Array.isArray(arr)) return false;

    // 🦊 关键：先把"分析任务" sentinel 探测+剥离掉。命中 → 这不是主对话，
    //    直接跳过头/尾注入，避免续写/润色提示词污染分析请求。
    if (novelDetectAndStripAnalysisSentinelInArray(arr)) {
      log('[小说模式] 检测到分析任务 sentinel，跳过头/尾注入');
      return false;
    }

    // 🦊 同一次生成会先后触发 GENERATE_AFTER_COMBINE_PROMPTS 与
    // CHAT_COMPLETION_PROMPT_READY 两个事件，且大多情况下二者收到的是同一份数组。
    // 用一个 per-array 标记避免重复 strip+inject（功能上幂等，但能减少日志噪音 +
    // 边际性能损耗）。注：每次新请求酒馆都会重建数组，所以标记不需要清理。
    if (arr.__novelInjected && novelModeConfig?.enabled) return true;

    // 先全局剥离旧哨兵，防止本次注入与上一次堆叠
    for (let i = arr.length - 1; i >= 0; i--) {
      const msg = arr[i];
      if (msg && typeof msg.content === 'string') {
        const before = msg.content;
        const after = novelStripInjectedBlocks(before);
        msg.content = after;
        if (before !== after && !after.trim()) arr.splice(i, 1);
      }
    }

    // 关闭状态：本次请求不注入（剥离即返回，保证开关一关旧注入自然消失）
    if (!novelModeConfig?.enabled) return false;

    const polishMode = !!novelModeConfig.polishMode;
    const head = novelBuildHeadPrompt(polishMode);
    const tail = novelBuildTailPrompt(polishMode) + '\n\n' + novelBuildWorkflow(polishMode);

    const headBlock = `${SS_NOVEL_HEAD_START}\n${head}\n${SS_NOVEL_HEAD_END}`;
    const tailBlock = `${SS_NOVEL_TAIL_START}\n${tail}\n${SS_NOVEL_TAIL_END}`;

    // 头部：作为新的第一条 system 消息
    arr.unshift({ role: 'system', content: headBlock });
    // 尾部：作为最末一条 system 消息（紧贴 user_input 之后，最大化对模型的引导力；
    // 用 system 角色而不是 user，避免被模型误判为"用户又说了一句话"）
    arr.push({ role: 'system', content: tailBlock });

    try { arr.__novelInjected = true; } catch { }

    log(`[小说模式] 已注入头/尾提示词（${polishMode ? '润色' : '续写'}模式）`);
    return true;
  }

  // 字符串形式（text completion 路径）：头放最前、尾放最后
  function novelInjectIntoPromptString(promptText) {
    let result = String(promptText || '');

    // 🦊 关键：分析任务 sentinel 探测+剥离。命中 → 跳过头/尾注入。
    const det = novelDetectAndStripAnalysisSentinelInString(result);
    if (det.hit) {
      log('[小说模式] 字符串 prompt：检测到分析任务 sentinel，跳过头/尾注入');
      return det.content;
    }

    result = novelStripInjectedBlocks(result);

    if (!novelModeConfig?.enabled) return result;

    const polishMode = !!novelModeConfig.polishMode;
    const head = novelBuildHeadPrompt(polishMode);
    const tail = novelBuildTailPrompt(polishMode) + '\n\n' + novelBuildWorkflow(polishMode);

    const headBlock = `${SS_NOVEL_HEAD_START}\n${head}\n${SS_NOVEL_HEAD_END}`;
    const tailBlock = `${SS_NOVEL_TAIL_START}\n${tail}\n${SS_NOVEL_TAIL_END}`;

    result = `${headBlock}\n\n${result.replace(/^\s+/, '')}`;
    result = `${result.replace(/\s+$/, '')}\n\n${tailBlock}`;
    log(`[小说模式] 字符串 prompt：已注入头/尾提示词（${polishMode ? '润色' : '续写'}模式）`);
    return result;
  }

  // 监听 GENERATE_AFTER_COMBINE_PROMPTS，把头/尾注入到请求体里。
  // 注：与 husou 的同事件监听互不冲突，事件总线允许多个 listener 同时挂载。
  let novelInjectListenerStops = [];
  function novelRegisterInjectListener() {
    novelUnregisterInjectListener();
    try {
      const eo = getFn('eventOn');
      const te = getFn('tavern_events') || tavern_events;
      if (typeof eo !== 'function' || !te) return;

      if (te.GENERATE_AFTER_COMBINE_PROMPTS) {
        const h = eo(te.GENERATE_AFTER_COMBINE_PROMPTS, r => {
          if (!ssShouldInjectForPromptEvent(r, r?.prompt)) return;
          if (Array.isArray(r?.prompt)) {
            novelInjectIntoPromptArray(r.prompt);
          } else if (typeof r?.prompt === 'string') {
            r.prompt = novelInjectIntoPromptString(r.prompt);
          }
        });
        if (h) novelInjectListenerStops.push(h);
      }

      // 兜底：chat completion 路径有些情况下只走 CHAT_COMPLETION_PROMPT_READY
      if (te.CHAT_COMPLETION_PROMPT_READY) {
        const h = eo(te.CHAT_COMPLETION_PROMPT_READY, d => {
          if (Array.isArray(d?.chat) && ssShouldInjectForPromptEvent(d, d.chat)) novelInjectIntoPromptArray(d.chat);
        });
        if (h) novelInjectListenerStops.push(h);
      }

      log('[小说模式] 头/尾注入监听已注册');
    } catch (e) {
      log('[小说模式] 注册注入监听失败', e);
    }
  }
  function novelUnregisterInjectListener() {
    for (const h of novelInjectListenerStops) {
      try { if (typeof h?.stop === 'function') h.stop(); } catch { }
    }
    novelInjectListenerStops = [];
  }

  async function novelTogglePolishMode() {
    novelModeConfig.polishMode = !novelModeConfig.polishMode;
    saveNovelModeConfig();

    if (novelModeConfig.enabled) {
      await novelApplyMode(true);
      ssRefreshDashboardIfOpen();
    } else {
      // 即使没点"一键进入小说模式"，也实时同步润色条目开关（大纲/正文流程已移除）
      await novelTogglePrompt(CONFIG.NOVEL.POLISH_ID, novelModeConfig.polishMode);
    }

    const btn = topDoc.getElementById('novel-polish-toggle');
    if (btn) {
      btn.textContent = novelModeConfig.polishMode ? '✍️ 润色模式：开' : '📖 小说模式：普通';
      btn.style.background = novelModeConfig.polishMode ? 'rgba(232,120,74,0.22)' : 'rgba(255,255,255,0.03)';
      btn.style.color = novelModeConfig.polishMode ? '#f0a070' : '#a09088';
    }

    const polishSw = topDoc.getElementById('novel-switch-wrap-polish');
    if (polishSw) polishSw.innerHTML = '';
    const polishSwitch = createToggleSwitch(CONFIG.NOVEL.POLISH_ID);
    if (polishSw) polishSw.appendChild(polishSwitch.wrapper);

    toast(
      novelModeConfig.polishMode
        ? '✍️ 已切换为润色模式：打开润色模式条目'
        : '📖 已切换为普通小说模式：关闭润色模式条目',
      'success'
    );
  }

  // ==================== 📖 小说进度悬浮窗（集成进主脚本） ====================
  // 抓取 AI 输出里的 <第N章[章名]大纲V版>…</…> 与 <第N章部分X>…</…> 区块，按章节/版本/部分
  // 归档；常驻悬浮窗显示推进进度，点击区块可定位楼层/开分支。开小说模式自动开窗。
  let novelProgPanel = null;
  let novelProgRecvHandle = null;

  function novelProgClassifyTag(name) {
    const s = String(name || '').trim();
    let m;
    if ((m = s.match(/^第(\d+)章(.*?)大纲(\d+)版$/))) return { type: 'outline', chapter: Number(m[1]), version: Number(m[3]), name: String(m[2] || '').trim() };
    if ((m = s.match(/^第(\d+)章部分(.+)$/))) return { type: 'part', chapter: Number(m[1]), part: String(m[2]).trim() };
    if ((m = s.match(/^部分(.+)$/))) return { type: 'part', chapter: null, part: String(m[1]).trim() };
    return null;
  }
  function novelProgScanPairedTags(text) {
    const src = String(text || '');
    const out = [];
    const openRe = /<([^\s<>][^<>]*?)>/g;
    let m;
    while ((m = openRe.exec(src)) !== null) {
      const name = m[1];
      const meta = novelProgClassifyTag(name);
      if (!meta) continue;
      const openStart = m.index;
      const openEnd = m.index + m[0].length;
      const closeTag = `</${name}>`;
      const closeIdx = src.indexOf(closeTag, openEnd);
      if (closeIdx < 0) { out.push({ name, meta, content: src.slice(openEnd), openStart, openEnd, closeStart: src.length, closeEnd: src.length, unclosed: true }); break; }
      out.push({ name, meta, content: src.slice(openEnd, closeIdx), openStart, openEnd, closeStart: closeIdx, closeEnd: closeIdx + closeTag.length, unclosed: false });
    }
    return out;
  }
  function novelProgScopeId() {
    try { const ctx = getCtx(); return `${ctx?.characterId ?? 'x'}::${ctx?.chatId ?? 'c'}`; } catch { return 'x::c'; }
  }
  function novelProgLoadAll() { try { return JSON.parse(localStorage.getItem(CONFIG.NOVEL.PROG_DATA_KEY) || '{}') || {}; } catch { return {}; } }
  function novelProgSaveAll(obj) { try { localStorage.setItem(CONFIG.NOVEL.PROG_DATA_KEY, JSON.stringify(obj)); } catch (e) { log('[小说进度] 保存失败', e); } }
  function novelProgGetScope() {
    const all = novelProgLoadAll();
    const scope = novelProgScopeId();
    if (!all[scope]) { all[scope] = { chapters: {}, updatedAt: Date.now() }; novelProgSaveAll(all); }
    return all[scope];
  }
  function novelProgSaveScope(s) { const all = novelProgLoadAll(); all[novelProgScopeId()] = { ...s, updatedAt: Date.now() }; novelProgSaveAll(all); }
  function novelProgEnsureChapter(data, n) { if (!data.chapters[n]) data.chapters[n] = { outlines: [], parts: [] }; return data.chapters[n]; }
  function novelProgInferChapter(data) { const nums = Object.keys(data.chapters).map(Number).filter(Number.isFinite); return nums.length ? Math.max(...nums) : 1; }

  function novelProgGetMsgText(messageId) {
    try {
      const gcm = getFn('getChatMessages'); if (!gcm) return '';
      const msg = gcm(messageId, { include_swipes: true })?.[0]; if (!msg || msg.role !== 'assistant') return '';
      const sid = msg.swipe_id ?? 0;
      return String(msg.swipes?.[sid] ?? msg.message ?? msg.mes ?? '');
    } catch { return ''; }
  }
  function novelProgUserInputBefore(messageId) {
    try {
      const gcm = getFn('getChatMessages'); if (!gcm) return '';
      for (let i = Number(messageId) - 1; i >= Math.max(0, Number(messageId) - 6); i--) { const m = gcm(i, { include_swipes: false })?.[0]; if (m && m.role === 'user') return String(m.message ?? m.mes ?? ''); }
    } catch {}
    return '';
  }
  function novelProgCaptureFromMessage(messageId) {
    try {
      const ctx = getCtx(); if (!ctx) return 0;
      const chat = ctx.chat || []; const mid = Number(messageId);
      if (!Number.isFinite(mid) || mid < 0 || mid >= chat.length) return 0;
      const msg = chat[mid]; if (!msg || msg.is_user) return 0;
      const full = novelProgGetMsgText(mid);
      const think = (full.match(/<think(?:[^>]*)>([\s\S]*?)<\/think>/i) || [])[1]?.trim() || '';
      const body = full.replace(/<think(?:[^>]*)>[\s\S]*?<\/think>/gi, '').trim();
      const userInput = novelProgUserInputBefore(mid);
      const swipeId = msg.swipe_id ?? 0;
      const blocks = novelProgScanPairedTags(body);
      if (!blocks.length) return 0;
      const data = novelProgGetScope(); let added = 0;
      for (const b of blocks) {
        const rec = { name: b.name, content: b.content.trim(), floor: mid, swipeId, think, userInput, capturedAt: new Date().toISOString(), unclosed: !!b.unclosed };
        if (b.meta.type === 'outline') {
          const ch = novelProgEnsureChapter(data, b.meta.chapter);
          const idx = ch.outlines.findIndex(o => o.meta?.version === b.meta.version);
          if (idx >= 0) ch.outlines[idx] = { ...ch.outlines[idx], ...rec, meta: b.meta }; else ch.outlines.push({ meta: b.meta, ...rec });
          added++;
        } else if (b.meta.type === 'part') {
          const chN = b.meta.chapter ?? novelProgInferChapter(data);
          const ch = novelProgEnsureChapter(data, chN);
          const idx = ch.parts.findIndex(p => String(p.meta?.part) === String(b.meta.part));
          if (idx >= 0) ch.parts[idx] = { ...ch.parts[idx], ...rec, meta: b.meta }; else ch.parts.push({ meta: b.meta, ...rec });
          added++;
        }
      }
      if (added) novelProgSaveScope(data);
      return added;
    } catch (e) { log('[小说进度] 抓取失败', e); return 0; }
  }
  function novelProgRecaptureAll() {
    try { const ctx = getCtx(); const chat = ctx?.chat || []; let n = 0; for (let i = 0; i < chat.length; i++) if (!chat[i].is_user) n += novelProgCaptureFromMessage(i); return n; } catch { return 0; }
  }
  function novelProgBuildProgress() {
    const data = novelProgGetScope();
    const chapters = Object.keys(data.chapters).map(Number).sort((a, b) => a - b);
    return chapters.map(n => {
      const ch = data.chapters[n];
      const outlines = (ch.outlines || []).slice().sort((a, b) => (a.meta?.version || 0) - (b.meta?.version || 0));
      return { chapter: n, outlines, parts: ch.parts || [], latest: outlines.length ? outlines[outlines.length - 1] : null };
    });
  }
  function novelProgNavigate(floor) {
    try {
      const ctx = getCtx(); const focus = ctx?.focusMessage || topWindow?.SillyTavern?.focusMessage;
      if (typeof focus === 'function') { focus(Number(floor)); return; }
    } catch {}
    try { const el = topDoc.querySelector(`.mes[mes_id="${Number(floor)}"]`); if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'center' }); el.style.outline = '2px solid #e8784a'; setTimeout(() => { el.style.outline = ''; }, 1800); } } catch {}
  }
  function novelProgBranch(floor) {
    try {
      const addSwipe = getCtx()?.addSwipe || topWindow?.SillyTavern?.addSwipe;
      const glmi = getFn('getLastMessageId'); const lastId = glmi ? glmi() : -1;
      if (typeof addSwipe === 'function' && lastId >= 0) { addSwipe(lastId); toast('🧩 已开新分支(swipe)，从最新楼重新生成', 'success'); return; }
    } catch (e) { log('[小说进度] 分支失败', e); }
    toast('⚠️ 未找到 addSwipe 接口，已定位到该楼层', 'warning'); novelProgNavigate(floor);
  }

  // ---- 悬浮窗 UI ----
  function novelProgShort(s, n = 90) { s = String(s || '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n) + '…' : s; }
  function novelProgRenderBody() {
    if (!novelProgPanel) return;
    const body = novelProgPanel.querySelector('#novelprog-body'); if (!body) return;
    const prog = novelProgBuildProgress();
    let html = `<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:10px;">
      <span style="font-size:12px;color:#a09088;">共 <b style="color:#f0a070;">${prog.length}</b> 章</span>
      <button id="novelprog-recapture" style="margin-left:auto;padding:4px 10px;border-radius:6px;border:1px solid rgba(232,120,74,0.35);background:rgba(232,120,74,0.12);color:#f0a070;cursor:pointer;font-size:11px;">🔄重扫</button>
      <button id="novelprog-clear" style="padding:4px 10px;border-radius:6px;border:1px solid rgba(255,255,255,0.12);background:rgba(255,255,255,0.04);color:#a09088;cursor:pointer;font-size:11px;">🗑清空</button>
    </div>`;
    if (!prog.length) html += `<div style="text-align:center;color:#706058;font-size:12px;padding:20px 0;">尚未抓到区块。让 AI 用 <code>&lt;第1章xx大纲1版&gt;…&lt;/第1章xx大纲1版&gt;</code> 或 <code>&lt;第1章部分一&gt;…&lt;/第1章部分一&gt;</code> 包裹内容。</div>`;
    for (const ch of prog) {
      const latestV = ch.latest ? 'v' + ch.latest.meta.version : '未定稿';
      html += `<div class="novelprog-chap" data-ch="${ch.chapter}" style="border:1px solid rgba(232,120,74,0.18);border-radius:10px;margin-bottom:8px;overflow:hidden;">
        <div class="novelprog-chap-head" style="display:flex;align-items:center;gap:8px;padding:8px 10px;background:rgba(232,120,74,0.06);cursor:pointer;">
          <span style="color:#f0a070;font-weight:700;font-size:13px;">第 ${ch.chapter} 章</span>
          <span style="font-size:10px;color:#e8784a;margin-left:auto;">${latestV}</span>
          <span style="font-size:10px;color:#706058;">大纲${ch.outlines.length}·正文${ch.parts.length}</span>
        </div>
        <div class="novelprog-chap-body" style="display:none;flex-direction:column;gap:6px;padding:8px 10px;">`;
      if (ch.outlines.length) { html += `<div style="font-size:11px;color:#a09088;">大纲版本（最新在最下，旧版可回溯）：</div>`; for (const o of ch.outlines) html += novelProgBlockHtml(o, 'outline', ch.chapter); }
      if (ch.parts.length) { html += `<div style="font-size:11px;color:#a09088;margin-top:6px;">正文部分：</div>`; for (const p of ch.parts) html += novelProgBlockHtml(p, 'part', ch.chapter); }
      if (!ch.outlines.length && !ch.parts.length) html += `<div style="font-size:11px;color:#706058;">（空）</div>`;
      html += `</div></div>`;
    }
    body.innerHTML = html;
    body.querySelectorAll('.novelprog-chap-head').forEach(h => { h.onclick = () => { const b = h.nextElementSibling; if (b) b.style.display = b.style.display === 'none' ? 'flex' : 'none'; }; });
    body.querySelectorAll('.novelprog-block').forEach(el => {
      const floor = Number(el.dataset.floor);
      el.querySelector('.np-go')?.addEventListener('click', e => { e.stopPropagation(); novelProgNavigate(floor); });
      el.querySelector('.np-branch')?.addEventListener('click', e => { e.stopPropagation(); novelProgBranch(floor); });
      el.querySelector('.np-view')?.addEventListener('click', e => { e.stopPropagation(); novelProgShowDetail(el); });
    });
    body.querySelector('#novelprog-recapture')?.addEventListener('click', () => { const n = novelProgRecaptureAll(); toast(`🔄 重扫归档 ${n} 个区块`, n ? 'success' : 'info'); novelProgRenderBody(); });
    body.querySelector('#novelprog-clear')?.addEventListener('click', () => { if (!confirm('确认清空当前聊天的小说区块记录？')) return; const all = novelProgLoadAll(); delete all[novelProgScopeId()]; novelProgSaveAll(all); novelProgRenderBody(); toast('🗑 已清空', 'info'); });
  }
  function novelProgBlockHtml(rec, type, chapter) {
    const label = type === 'outline' ? `大纲 v${rec.meta.version}${rec.unclosed ? ' ⚠未闭合' : ''}` : `部分·${escapeHtml(rec.meta.part)}${rec.unclosed ? ' ⚠未闭合' : ''}`;
    return `<div class="novelprog-block" data-floor="${rec.floor}" data-type="${type}" data-chapter="${chapter}" style="border:1px solid rgba(255,255,255,0.08);border-radius:8px;padding:7px 9px;background:rgba(255,255,255,0.02);">
      <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
        <span style="font-size:11px;font-weight:700;color:#f0a070;">${label}</span>
        <span style="font-size:10px;color:#706058;">第${rec.floor}楼</span>
        <span style="margin-left:auto;display:flex;gap:4px;">
