  function novelProgEnableDrag(panel, handle) {
    let dragging = false, ox = 0, oy = 0;
    handle.addEventListener('mousedown', e => { if (e.target.id === 'novelprog-close' || e.target.id === 'novelprog-hide') return; dragging = true; const r = panel.getBoundingClientRect(); ox = e.clientX - r.left; oy = e.clientY - r.top; panel.style.right = 'auto'; panel.style.bottom = 'auto'; e.preventDefault(); });
    topDoc.addEventListener('mousemove', e => { if (!dragging) return; panel.style.left = Math.max(0, e.clientX - ox) + 'px'; panel.style.top = Math.max(0, e.clientY - oy) + 'px'; });
    topDoc.addEventListener('mouseup', () => { dragging = false; });
  }
  function novelProgEnableResize(panel) {
    const minW = 340, minH = 280;
    const edges = [{ dir: 'right', css: 'top:0;right:-3px;width:8px;height:100%;cursor:ew-resize;' }, { dir: 'bottom', css: 'bottom:-3px;left:0;height:8px;width:100%;cursor:ns-resize;' }, { dir: 'br', css: 'bottom:-3px;right:-3px;width:16px;height:16px;cursor:nwse-resize;' }];
    let resizing = false, dir = '', sx = 0, sy = 0, sw = 0, sh = 0;
    for (const e of edges) { const h = topDoc.createElement('div'); h.style.cssText = `position:absolute;z-index:6;${e.css}`; h.dataset.resize = e.dir; h.addEventListener('mousedown', ev => { resizing = true; dir = e.dir; sx = ev.clientX; sy = ev.clientY; const r = panel.getBoundingClientRect(); sw = r.width; sh = r.height; ev.preventDefault(); ev.stopPropagation(); }); panel.appendChild(h); }
    topDoc.addEventListener('mousemove', ev => { if (!resizing) return; const dx = ev.clientX - sx, dy = ev.clientY - sy; const maxW = (topWindow?.innerWidth || window.innerWidth) - 20, maxH = (topWindow?.innerHeight || window.innerHeight) - 20; if (dir === 'right' || dir === 'br') panel.style.width = Math.max(minW, Math.min(maxW, sw + dx)) + 'px'; if (dir === 'bottom' || dir === 'br') { panel.style.maxHeight = 'none'; panel.style.height = Math.max(minH, Math.min(maxH, sh + dy)) + 'px'; } });
    topDoc.addEventListener('mouseup', () => { if (!resizing) return; resizing = false; try { localStorage.setItem(CONFIG.NOVEL.PROG_SIZE_KEY, JSON.stringify({ w: panel.style.width, h: panel.style.height })); } catch {} });
  }
