            <textarea id="novel-prompt-workflow" placeholder="留空=默认" style="width:100%;min-height:140px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.18);border-radius:8px;color:#e8ddd4;padding:10px;font-size:12px;font-family:monospace;resize:vertical;box-sizing:border-box;">${escapeHtml(novelBuildWorkflow(false))}</textarea>
          </div>
          <div>
            <div style="font-size:12px;color:#cdbcb4;margin-bottom:4px;">润色 · 工作流</div>
            <textarea id="novel-prompt-workflow-polish" placeholder="留空=默认" style="width:100%;min-height:140px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.18);border-radius:8px;color:#e8ddd4;padding:10px;font-size:12px;font-family:monospace;resize:vertical;box-sizing:border-box;">${escapeHtml(novelBuildWorkflow(true))}</textarea>
          </div>
          <div style="border:1px dashed rgba(232,120,74,0.22);border-radius:10px;padding:10px 12px;background:rgba(232,120,74,0.04);">
            <div style="font-weight:600;color:#e8ddd4;margin-bottom:4px;">🤖 让 AI 帮我写工作流（续写）</div>
            <div style="font-size:11px;color:#a09088;margin-bottom:6px;">描述你想要的工作流风格/步骤，AI 会生成一段工作流并填入下方"续写·工作流"框，可再编辑后保存。</div>
            <textarea id="novel-prompt-ai-req" placeholder="例：我想让AI每次都先问我要推进到哪个节点，再列分场景大纲，我点头后才写正文，写完留钩子并问下一段；要保留 <第N章…大纲V版> 和 <第N章部分X> 标签包裹。" style="width:100%;min-height:70px;background:rgba(255,255,255,0.04);border:1px solid rgba(232,120,74,0.18);border-radius:8px;color:#e8ddd4;padding:8px;font-size:12px;font-family:monospace;resize:vertical;box-sizing:border-box;"></textarea>
            <button id="novel-prompt-ai-write" style="margin-top:6px;padding:7px 12px;border:1px solid rgba(232,120,74,0.3);border-radius:8px;background:rgba(232,120,74,0.12);color:#f0a070;cursor:pointer;font-size:12px;">🤖 生成工作流</button>
          </div>
          <div style="display:flex;gap:8px;">
            <button id="novel-workflow-save" style="flex:1;padding:8px;border:1px solid rgba(232,120,74,0.28);border-radius:8px;background:rgba(232,120,74,0.1);color:#f0a070;cursor:pointer;font-size:12px;">💾 保存工作流</button>
            <button id="novel-workflow-reset" style="flex:1;padding:8px;border:1px solid rgba(139,0,0,0.3);border-radius:8px;background:rgba(139,0,0,0.13);color:#d08080;cursor:pointer;font-size:12px;">↩️ 恢复默认工作流</button>
          </div>
        </div>
      </div>
    `;

    topDoc.body.appendChild(overlay);
    topDoc.body.appendChild(panel);
    xhGuideEnhancePanel(panel, 'novel', '小说模式');

    // ✅ 自动保存：每个条目改了哪个 textarea 就触发该条目的保存按钮；
    //    分析结果框（novel-analysis-*）不算配置，跳过。
    //    novel-source-text 走 saveNovelModeConfig（在自定义回调里完成）。
    ssAttachAutoSave(panel, {
      excludeSelectors: ['[id^="novel-analysis-"]', '[id^="novel-prompt-"]'],
      resolveSaveBtns: (target) => {
        if (!target || !target.id) return [];
        const id = target.id;
        // 条目正文：触发该条目的 💾 保存
        const m = id.match(/^novel-entry-(.+)$/);
        if (m) return [`novel-save-entry-${m[1]}`];
        // 原文：没有按钮，回调里直接 saveNovelModeConfig
        if (id === 'novel-source-text') {
          try {
            novelModeConfig.sourceText = target.value || '';
            saveNovelModeConfig();
          } catch (e) { try { log('[autosave] novel-source-text 保存失败', e); } catch {} }
          return [];
        }
        return [];
      },
    });

    // 自定义注入提示词：折叠 + 保存 + 恢复默认
    (() => {
      const toggle = topDoc.getElementById('novel-prompt-toggle');
      const box = topDoc.getElementById('novel-prompt-box');
      let pOpen = false;
      if (toggle && box) toggle.onclick = () => { pOpen = !pOpen; box.style.display = pOpen ? 'flex' : 'none'; toggle.textContent = (pOpen ? '▼ ' : '▶ ') + '自定义注入提示词（头/尾 · 续写/润色）'; };
      const get = id => { const el = topDoc.getElementById(id); return el ? el.value : ''; };
      const saveBtn = topDoc.getElementById('novel-prompt-save');
      if (saveBtn) saveBtn.onclick = () => {
        novelModeConfig = loadNovelModeConfig();
        novelModeConfig.headPrompt = get('novel-prompt-head');
        novelModeConfig.tailPrompt = get('novel-prompt-tail');
        novelModeConfig.headPromptPolish = get('novel-prompt-head-polish');
        novelModeConfig.tailPromptPolish = get('novel-prompt-tail-polish');
        saveNovelModeConfig();
        toast('✅ 已保存自定义注入提示词', 'success');
      };
      const resetBtn = topDoc.getElementById('novel-prompt-reset');
      if (resetBtn) resetBtn.onclick = () => {
        novelModeConfig = loadNovelModeConfig();
        novelModeConfig.headPrompt = ''; novelModeConfig.tailPrompt = '';
        novelModeConfig.headPromptPolish = ''; novelModeConfig.tailPromptPolish = '';
        saveNovelModeConfig();
        const setVal = (id, val) => { const el = topDoc.getElementById(id); if (el) el.value = val; };
        setVal('novel-prompt-head', novelBuildHeadPrompt(false));
        setVal('novel-prompt-tail', novelBuildTailPrompt(false));
        setVal('novel-prompt-head-polish', novelBuildHeadPrompt(true));
        setVal('novel-prompt-tail-polish', novelBuildTailPrompt(true));
        toast('↩️ 已恢复内置默认提示词', 'info');
      };

    })();

    // 自定义工作流：折叠 + 保存 + 恢复默认 + AI 生成
    (() => {
      const wfToggle = topDoc.getElementById('novel-workflow-toggle');
      const wfBox = topDoc.getElementById('novel-workflow-box');
      let wOpen = false;
      if (wfToggle && wfBox) wfToggle.onclick = () => { wOpen = !wOpen; wfBox.style.display = wOpen ? 'flex' : 'none'; wfToggle.textContent = (wOpen ? '▼ ' : '▶ ') + '自定义工作流（续写/润色 · 分步骤流程）'; };
      const wfGet = id => { const el = topDoc.getElementById(id); return el ? el.value : ''; };
      const wfSaveBtn = topDoc.getElementById('novel-workflow-save');
      if (wfSaveBtn) wfSaveBtn.onclick = () => {
        novelModeConfig = loadNovelModeConfig();
        novelModeConfig.workflow = wfGet('novel-prompt-workflow');
        novelModeConfig.workflowPolish = wfGet('novel-prompt-workflow-polish');
        saveNovelModeConfig();
        toast('✅ 已保存自定义工作流', 'success');
      };
      const wfResetBtn = topDoc.getElementById('novel-workflow-reset');
      if (wfResetBtn) wfResetBtn.onclick = () => {
        novelModeConfig = loadNovelModeConfig();
        novelModeConfig.workflow = ''; novelModeConfig.workflowPolish = '';
        saveNovelModeConfig();
        const wfSetVal = (id, val) => { const el = topDoc.getElementById(id); if (el) el.value = val; };
        wfSetVal('novel-prompt-workflow', novelBuildWorkflow(false));
        wfSetVal('novel-prompt-workflow-polish', novelBuildWorkflow(true));
        toast('↩️ 已恢复内置默认工作流', 'info');
      };

      const aiBtn = topDoc.getElementById('novel-prompt-ai-write');
      if (aiBtn) aiBtn.onclick = async () => {
        const req = (topDoc.getElementById('novel-prompt-ai-req')?.value || '').trim();
        if (!req) { toast('请先在框里写上你想要的工作流要求', 'warning'); return; }
        aiBtn.disabled = true; const oldTxt = aiBtn.textContent; aiBtn.textContent = '🤖 正在生成…';
        try {
          const metaSys = `你是小说写作流程设计助手。根据作者要求，输出一段"续写工作流"（注入到尾部提示词之后、教AI按流程与作者协作续写），可直接复制使用。
要求：
${req}
硬性约束（必须包含在生成的工作流里，因为脚本要靠它们抓取归档）：输出的每一块正式内容用 <第N章[章名]大纲V版>…</第N章[章名]大纲V版>（版本递增、先讨论再下一版）和 <第N章部分X>…</第N章部分X> 包裹；讨论优先、确认后才动笔；禁止AI体自述；保持文风一致。
只输出工作流正文，不要解释、不要前后缀。`;
          const r = await ssGenerateRaw('novel_workflow_writer', {
            user_input: req,
            should_silence: true,
            should_stream: false,
            max_chat_history: 0,
            ordered_prompts: [{ role: 'system', content: metaSys }, 'user_input'],
          });
          const out = String(typeof r === 'string' ? r : (r?.content || '')).trim();
          if (!out) { toast('AI 返回空内容', 'error'); return; }
          const ta = topDoc.getElementById('novel-prompt-workflow');
          if (ta) { ta.value = out; toast('✅ 已生成工作流并填入「续写·工作流」，可再编辑后点保存', 'success'); }
          else toast('✅ 工作流已生成（未找到工作流输入框）', 'info');
        } catch (e) { log('[小说工作流生成] 失败', e); toast('❌ 生成失败', 'error'); }
        finally { aiBtn.disabled = false; aiBtn.textContent = oldTxt; }
      };
    })();

    // 分析控制：详细程度/目标字数/用户补充（统一应用到全部分析模块）
    const analysisSaveBtn = topDoc.getElementById('novel-analysis-save');
    if (analysisSaveBtn) analysisSaveBtn.onclick = () => {
      novelModeConfig = loadNovelModeConfig();
      const dEl = topDoc.getElementById('novel-analysis-detail');
      const wEl = topDoc.getElementById('novel-analysis-words');
      const nEl = topDoc.getElementById('novel-analysis-note');
      if (dEl) novelModeConfig.novelAnalysisDetail = dEl.value || '详细';
      const w = Number(wEl?.value); novelModeConfig.novelAnalysisWords = (Number.isFinite(w) && w >= 100) ? w : 1500;
      if (nEl) novelModeConfig.novelAnalysisUserNote = nEl.value || '';
      saveNovelModeConfig();
      toast('✅ 已保存分析控制（应用到小说模式全部 4 个分析模块；自定义文风分析使用各自独立配置）', 'success');
    };

    topDoc.getElementById('novel-close').onclick = () => {
      xhGuideEnd();
      overlay.remove();
      panel.remove();
    };

    const sourceSwitch = createToggleSwitch(CONFIG.NOVEL.SOURCE_ID, (enabled) => {
      novelModeConfig.injectSource = enabled;
      saveNovelModeConfig();
    });
    topDoc.getElementById('novel-switch-wrap-source')?.appendChild(sourceSwitch.wrapper);

    for (const entry of novelGetEntryDefs()) {
      const wrap = topDoc.getElementById(`novel-switch-wrap-${entry.key}`);
      if (wrap) {
        const sw = createToggleSwitch(entry.id);
        wrap.appendChild(sw.wrapper);
      }

      const saveBtn = topDoc.getElementById(`novel-save-entry-${entry.key}`);
      if (saveBtn) saveBtn.onclick = () => novelSaveEntry(entry.key);

      const clearBtn = topDoc.getElementById(`novel-clear-entry-${entry.key}`);
      if (clearBtn) clearBtn.onclick = () => novelClearEntry(entry.key);

      const coverBtn = topDoc.getElementById(`novel-cover-${entry.key}`);
      if (coverBtn) coverBtn.onclick = () => novelApplyAnalysisToEntry(entry.key, 'replace');

      const appendBtn = topDoc.getElementById(`novel-append-${entry.key}`);
      if (appendBtn) appendBtn.onclick = () => novelApplyAnalysisToEntry(entry.key, 'append');

      const clearAnalysisBtn = topDoc.getElementById(`novel-clear-analysis-${entry.key}`);
      if (clearAnalysisBtn) clearAnalysisBtn.onclick = () => novelClearAnalysis(entry.key);

      // 🦊 中断分析按钮（默认 display:none，分析运行中由 novelSetAnalysisRunningUI 切到 block）
      const cancelBtn = topDoc.getElementById(`novel-cancel-${entry.key}`);
      if (cancelBtn) cancelBtn.onclick = () => {
        const taskName = `novel_analysis_${entry.key}`;
        if (ssIsTaskRunning(taskName)) {
          ssCancelTask(taskName, '小说分析');
        } else {
          // 没在跑就把按钮自己藏起来，防止状态错位
          novelSetAnalysisRunningUI(entry.key, false);
        }
      };

      const reBtn = topDoc.getElementById(`novel-reanalyze-${entry.key}`);
      if (reBtn) reBtn.onclick = async () => {
        const resolved = await ssResolveTextWithPending(panel, 'novelSource', 'novel-source-text');
        panel.__ssNovelResolvedText = resolved.text;
        try {
          await novelRunAnalysisForEntry(entry.key);
        } finally {
          panel.__ssNovelResolvedText = '';
        }
      };
    }

    topDoc.getElementById('novel-polish-toggle').onclick = () => novelTogglePolishMode();

    const novelProgOpenBtn = topDoc.getElementById('novel-prog-open');
    if (novelProgOpenBtn) novelProgOpenBtn.onclick = () => {
      if (!novelModeConfig?.enabled) { toast('💡 建议先开启小说模式再使用进度窗（可自动抓取章节区块）', 'info'); }
      localStorage.setItem(CONFIG.NOVEL.PROG_WIN_KEY, 'true');
      novelProgToggleWindow(true);
    };

    topDoc.getElementById('novel-import-txt').onclick = async () => {
      await ssAttachTxtChips(panel, 'novelSource', 'novel-source-files', {
        sortByName: false,
        append: true,
      });
    };

    topDoc.getElementById('novel-import-txt-sort').onclick = async () => {
      await ssAttachTxtChips(panel, 'novelSource', 'novel-source-files', {
        sortByName: true,
        append: true,
      });
    };

    topDoc.getElementById('novel-inject-source').onclick = async () => {
      const typed = topDoc.getElementById('novel-source-text')?.value || '';
      novelModeConfig.sourceText = typed;
      saveNovelModeConfig();

      const resolved = await ssResolveTextWithPending(panel, 'novelSource', 'novel-source-text');
      panel.__ssNovelResolvedText = resolved.text;
      try {
        await novelInjectSourceText(resolved.text);
      } finally {
        panel.__ssNovelResolvedText = '';
      }
    };

    topDoc.getElementById('novel-clear-source').onclick = async () => {
      ssClearPendingTxtChips(panel, 'novelSource', 'novel-source-files');
      await novelClearOne('source');
    };

    topDoc.getElementById('novel-analyze-all').onclick = async () => {
      const typed = topDoc.getElementById('novel-source-text')?.value || '';
      novelModeConfig.sourceText = typed;
      saveNovelModeConfig();

      const resolved = await ssResolveTextWithPending(panel, 'novelSource', 'novel-source-text');
      panel.__ssNovelResolvedText = resolved.text;
      try {
        await novelAnalyzeAll();
      } finally {
        panel.__ssNovelResolvedText = '';
      }
    };

    topDoc.getElementById('novel-clear-all').onclick = async () => {
      await novelClearAll({ disablePrompt: false });
    };

    setTimeout(() => {
      try { applyMobilePanelFixNow?.(); } catch (e) { }
    }, 50);
  }


