/* ========== 🍎 iOS 开关（通用款，适用于未接入皮肤引擎的悬浮窗） ========== */
.ss-ios-sw{position:relative;width:38px;height:21px;border-radius:99px;cursor:pointer;flex-shrink:0;display:inline-block;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12);transition:all .25s cubic-bezier(.22,1,.36,1);vertical-align:middle;box-sizing:border-box;}
.ss-ios-sw::after{content:"";position:absolute;top:2px;left:2px;width:15px;height:15px;border-radius:50%;background:#8a7f78;transition:all .28s cubic-bezier(.34,1.56,.64,1);box-shadow:0 2px 6px rgba(0,0,0,.4);}
.ss-ios-sw.on{background:linear-gradient(90deg,rgba(232,120,74,.85),rgba(232,120,74,.55));border-color:rgba(232,120,74,.6);box-shadow:0 0 12px rgba(232,120,74,.35);}
.ss-ios-sw.on::after{left:18px;background:#fff8f2;}
.ss-ios-sw:active::after{width:18px;}
.ss-ios-sw.on:active::after{left:15px;}
input[type="checkbox"].ss-ios-done{position:absolute!important;opacity:0!important;width:0!important;height:0!important;margin:0!important;padding:0!important;}

/* ========== ✨ 主面板泛光美化（呼吸泛光 + 顶部高光） ========== */
@keyframes ssDashBreath{
    0%,100%{box-shadow:0 28px 90px rgba(0,0,0,.74),0 0 32px rgba(232,120,74,.10),0 0 90px rgba(232,120,74,.05),inset 0 1px 0 rgba(255,255,255,.05);}
    50%{box-shadow:0 28px 90px rgba(0,0,0,.74),0 0 56px rgba(232,120,74,.22),0 0 140px rgba(232,120,74,.09),inset 0 1px 0 rgba(255,255,255,.07);}
}
#ss-dashboard{
    animation:ss-scaleIn .25s cubic-bezier(.34,1.56,.64,1),ssDashBreath 5.6s ease-in-out .8s infinite !important;
}
#ss-dashboard::after{
    content:"";position:absolute;left:8%;right:8%;top:0;height:1px;pointer-events:none;
    background:linear-gradient(90deg,transparent,rgba(240,160,112,.55),transparent);
    filter:blur(.4px);
}

