  // ==================== 主面板排序 + 简单/高级模式 ====================
  function applyDashboardMode() {
    const dash = topDoc.getElementById('ss-dashboard');
    if (!dash) return;
    const simpleMode = localStorage.getItem(CONFIG.DASHBOARD_MODE_KEY) !== 'advanced';
    const simpleSections = [
      '思维链控制', '快捷开关', '实用工具', '预设选项控制', '杀八股', '自定义内容编辑',
      '大总结', '拷打模式', '狐析', '狐裁', '配置备份',
    ];

    // 🎴 方案A 工作台：简单/高级模式切换已移除，全部分区始终可见，无需显隐处理
    if (dash.classList.contains('xh-workbench')) return;

    const titles = [...dash.querySelectorAll(':scope > .ss-dashboard-section-title, :scope > [data-section-title]')];
    for (const title of titles) {
      const box = title.nextElementSibling;
      const titleText = String(title.dataset.sectionTitle || title.textContent || '').trim();
      const visible = !simpleMode || simpleSections.some(name => titleText.includes(name));
      if (title.dataset.ssDashboardDisplay == null) title.dataset.ssDashboardDisplay = title.style.display || '';
      title.style.display = visible ? title.dataset.ssDashboardDisplay : 'none';
      if (box && box !== dash.firstElementChild) {
        if (box.dataset.ssDashboardDisplay == null) box.dataset.ssDashboardDisplay = box.style.display || '';
        box.style.display = visible ? box.dataset.ssDashboardDisplay : 'none';
      }
    }

    // 兼容旧实例/额外入口：狐狐模式使用白名单，标题和内容卡成对显隐。
    if (simpleMode) {
      const allowed = new Set();
      for (const title of titles.filter(el => simpleSections.some(name => (el.textContent || '').includes(name)))) {
        allowed.add(title);
        if (title.nextElementSibling) allowed.add(title.nextElementSibling);
      }
      for (const child of [...dash.children]) {
        if (child === dash.firstElementChild || allowed.has(child)) continue;
        if (child.dataset.ssDashboardDisplay == null) child.dataset.ssDashboardDisplay = child.style.display || '';
        child.style.display = 'none';
      }
    } else {
      for (const child of [...dash.children]) {
        if (child.dataset.ssDashboardDisplay != null) child.style.display = child.dataset.ssDashboardDisplay;
      }
    }
  }

  function reorderDashboardSections() {
    const dash = topDoc.getElementById('ss-dashboard');
    if (!dash) return;

    // 🎴 方案A 工作台：页面顺序由布局映射固定，无需重排，只做简单/高级显隐
    if (dash.classList.contains('xh-workbench')) { applyDashboardMode(); return; }

    const header = dash.firstElementChild;
    if (!header) return;

    // 删除旧分割线，避免重复打开面板时叠加
    dash.querySelectorAll('.ss-extra-separator-title, .ss-extra-separator-box').forEach(el => el.remove());

    const pairs = [];
    const children = [...dash.children];

    for (let i = 1; i < children.length; i++) {
      const title = children[i];
      const box = children[i + 1];

      if (!title || !box) continue;

      const titleText = (title.textContent || '').trim();

      // sectionTitle 生成的是标题 div，后面紧跟 box
      if (
        titleText.includes('思维链控制') ||
        titleText.includes('快捷开关') ||
        titleText.includes('实用工具') ||
        titleText.includes('预设选项控制') ||
        titleText.includes('杀八股') ||
        titleText.includes('自定义内容编辑') ||
        titleText.includes('大总结') ||
        titleText.includes('拷打模式') ||
         titleText.includes('狐构') ||
         titleText.includes('狐忆') ||
         titleText.includes('狐裁') ||
         titleText.includes('狐析') ||
        titleText.includes('狐搜') ||
        titleText.includes('平行世界') ||
        titleText.includes('小说模式') ||
        titleText.includes('配置备份')
      ) {
        pairs.push({ title, box, text: titleText });
        i++;
      }
    }

    const order = [
      '思维链控制',
      '快捷开关',
      '实用工具',
      '预设选项控制',
      '杀八股',
      '自定义内容编辑',
      '大总结',
      '拷打模式',
      '狐构',
      '狐忆',
      '狐裁',
      '狐析',
      '狐搜',
      '平行世界',
      '小说模式',
      '配置备份',
    ];

    const used = new Set();

    function take(key) {
      const item = pairs.find(p => !used.has(p) && p.text.includes(key));
      if (item) used.add(item);
      return item;
    }

    const ordered = [];
    for (const key of order) {
      const item = take(key);
      if (item) ordered.push(item);
    }

    // 剩余未匹配模块保持原相对顺序，放最后
    for (const item of pairs) {
      if (!used.has(item)) ordered.push(item);
    }

    // 重新挂载
    for (const item of ordered) {
      dash.appendChild(item.title);
      dash.appendChild(item.box);
    }
    applyDashboardMode();
  }

  function polishHusouCheckboxes(panel) {
    if (!panel) return;

    panel.querySelectorAll('label').forEach(label => {
      const input = label.querySelector('input[type="checkbox"]');
      if (!input || label.dataset.ssSwitchified === '1') return;

      label.dataset.ssSwitchified = '1';
      label.style.display = 'flex';
      label.style.alignItems = 'center';
      label.style.justifyContent = 'space-between';
      label.style.gap = '10px';
      if (!label.classList.contains('husou-setting-row')) label.classList.add('husou-setting-row');

      input.style.display = 'none';

      const sw = topDoc.createElement('span');
      sw.className = 'ss-husou-switch';
      sw.setAttribute('role', 'switch');
      sw.setAttribute('aria-label', String(label.textContent || '狐搜开关').trim().slice(0, 40));

      label.appendChild(sw);

      const update = () => {
        sw.classList.toggle('is-on', input.checked);
        sw.classList.toggle('is-off', !input.checked);
        sw.setAttribute('aria-checked', input.checked ? 'true' : 'false');
      };

      update();

      input.addEventListener('change', update);
    });
  }

