      return saved && typeof saved === 'object' ? saved : {};
    } catch {
      return {};
    }
  }

  function ssSavePanelScrollPosition(panel, scroller) {
    if (!panel?.id || !scroller) return;
    try {
      const saved = ssReadPanelScrollPositions();
      saved[panel.id] = Math.max(0, Math.round(scroller.scrollTop || 0));
      localStorage.setItem(SS_PANEL_SCROLL_KEY, JSON.stringify(saved));
    } catch { }
  }

  function ssEnhanceScrollablePanel(panel) {
    if (!panel?.id || panel.dataset.ssScrollMemory === '1') return;
    panel.dataset.ssScrollMemory = '1';

    panel.querySelectorAll('span[id$="-close"], .pw-close').forEach(close => {
      close.classList.add('ss-panel-close');
      close.setAttribute('role', 'button');
      close.setAttribute('aria-label', close.getAttribute('aria-label') || '关闭面板');
    });

    const scroller = panel.id === 'pw-state-float'
      ? panel.querySelector('#pw-state-body') || panel
      : panel;
    let saveTimer = null;
    scroller.addEventListener('scroll', () => {
      clearTimeout(saveTimer);
      saveTimer = setTimeout(() => ssSavePanelScrollPosition(panel, scroller), 100);
    }, { passive: true });

    const restore = () => {
      if (!panel.isConnected) return;
      const position = Number(ssReadPanelScrollPositions()[panel.id]);
      if (Number.isFinite(position) && position > 0) scroller.scrollTop = position;
    };
    requestAnimationFrame(() => requestAnimationFrame(restore));
  }

  function ssInstallPanelScrollMemory() {
    try { topWindow.__ssPanelScrollMemoryObserver?.disconnect?.(); } catch { }

    topDoc.querySelectorAll(SS_SCROLL_PANEL_SELECTORS).forEach(ssEnhanceScrollablePanel);
    topDoc.addEventListener('pointerdown', event => {
      const close = event.target?.closest?.('.ss-panel-close');
      const panel = close?.closest?.(SS_SCROLL_PANEL_SELECTORS);
      if (!panel) return;
      const scroller = panel.id === 'pw-state-float'
        ? panel.querySelector('#pw-state-body') || panel
        : panel;
      ssSavePanelScrollPosition(panel, scroller);
    }, true);
    const Observer = topWindow?.MutationObserver || window.MutationObserver;
    if (!Observer) return;
    // 🦊 性能优化：body 级 subtree MutationObserver 在流式传输/DOM 频繁变动时
    //    会产生大量回调，用防抖合并处理，面板增强不需要实时响应
    let _panelScanTimer = null;
    const _pendingNodes = new Set();
    const observer = new Observer(mutations => {
      for (const mutation of mutations) {
        for (const node of mutation.addedNodes) {
          if (!(node instanceof (topWindow?.Element || Element))) continue;
          _pendingNodes.add(node);
        }
      }
      if (_pendingNodes.size === 0) return;
      if (_panelScanTimer) return;
      _panelScanTimer = setTimeout(() => {
        _panelScanTimer = null;
        for (const node of _pendingNodes) {
          if (!node.isConnected) continue;
          if (node.matches?.(SS_SCROLL_PANEL_SELECTORS)) ssEnhanceScrollablePanel(node);
          node.querySelectorAll?.(SS_SCROLL_PANEL_SELECTORS).forEach(ssEnhanceScrollablePanel);
        }
        _pendingNodes.clear();
      }, 500);
    });
    observer.observe(topDoc.body, { childList: true, subtree: true });
    topWindow.__ssPanelScrollMemoryObserver = observer;
  }

