    xhInjectPanelSkinCss();
    panel.classList.add('xh-skinned');
    if (cfg.blue) panel.setAttribute('data-xh-blue', '1');

    // ---- 统一命名：相同功能在各面板中的叫法/图标保持一致 ----
    try {
      const RENAMES = {
        '🔁 主线回复后自动推进平行世界': '🔁 自动推进｜世界事件',
        '📅 自动分析｜生成记忆库': '📅 自动分析｜生成记忆库',
        '🦊自动搜索': '🌐 自动搜索｜外部情报',
