        '🧠 记忆库管理': '🧠 记忆库管理',
      };
      panel.querySelectorAll('div, span').forEach(el => {
        if (el.children.length > 2) return;
        const t = String(el.textContent || '').trim();
        if (t.length > 24) return;
        const rn = RENAMES[t];
        if (rn && t !== rn) el.textContent = rn;
      });
    } catch (e) { log('[面板皮肤] 命名统一失败:', panel.id, e); }

    // ---- 头部统一：logo + 统一标题 + EN 副标题 ----
    // ✅ 新版标准边栏UI面板跳过头部统一，避免顶栏被吞
    if (panel.querySelector('.fj-work, .work, .pw-work, .fi-work, .ft-work, .fm-work, .hx-body')) {
      // 新版面板已有自己的PC顶栏+移动端顶栏，不需要旧版头部统一
    } else
    try {
      // 定位头部：优先面板第一个子元素；若它是纯容器（无标题 span），则取其第一个含标题 span 的子元素
      let header = panel.firstElementChild;
      const hasTitle = (el) => !!(el && el.querySelector && el.querySelector('span[style*="font-size:15px"], span[style*="font-weight:600"], .pw-title'));
      if (header && !hasTitle(header) && hasTitle(header.firstElementChild)) header = header.firstElementChild;
      if (header && hasTitle(header) && !header.querySelector('.xh-head-logo')) {
        const titleSpan = header.querySelector('span[style*="font-size:15px"], span[style*="font-weight:600"], .pw-title');
        const subDiv = header.querySelector('div[style*="margin-top:2px"], div[style*="margin-top:3px"]');
        const subText = subDiv ? String(subDiv.textContent || '').trim().replace(/\s+/g, ' ') : '';
        if (titleSpan) titleSpan.style.display = 'none';
        if (subDiv) subDiv.style.display = 'none';
        header.classList.add('xh-head');
        const logo = topDoc.createElement('div'); logo.className = 'xh-head-logo'; logo.textContent = cfg.title.slice(0, 2);
        const tbox = topDoc.createElement('div'); tbox.className = 'xh-head-t';
        const bb = topDoc.createElement('b'); bb.textContent = cfg.title;
        const sm = topDoc.createElement('small'); sm.textContent = cfg.en + (subText ? ' · ' + subText : '');
        tbox.appendChild(bb); tbox.appendChild(sm);
        header.insertBefore(tbox, header.firstChild);
        header.insertBefore(logo, header.firstChild);
        // 右侧关闭/按钮组：推到最后
        const right = header.querySelector('.ss-panel-close, [id$="-close"], .pw-close');
        if (right) {
          let host = right.parentElement;
          if (host === header) { const wrap = topDoc.createElement('div'); wrap.className = 'xh-head-right'; header.insertBefore(wrap, right.nextSibling); wrap.appendChild(right); }
          else host.classList.add('xh-head-right');
        }
      }
    } catch (e) { log('[面板皮肤] 头部统一失败:', panel.id, e); }

    // ---- 原生 checkbox → iOS 开关（纯视觉，逻辑不变）----
    try {
      panel.querySelectorAll('input[type="checkbox"]:not(.xh-pswd)').forEach(inp => {
        if (inp.closest('label[data-ss-switchified]')) return;
        if (inp.closest('.ss-husou-switch')) return;
        // ✅ 跳过已有 pw-sw 自定义开关的 checkbox（平行世界面板），避免重复生成第二个 iOS 开关
        if (inp.parentElement?.querySelector('.pw-sw')) return;
        inp.classList.add('xh-pswd');
        const sw = topDoc.createElement('span');
        sw.className = 'xh-psw' + (inp.checked ? ' on' : '');
        inp.insertAdjacentElement('afterend', sw);
        sw.onclick = (e) => { e.preventDefault(); e.stopPropagation(); inp.click(); };
        inp.addEventListener('change', () => sw.classList.toggle('on', inp.checked));
      });
    } catch (e) { log('[面板皮肤] checkbox 转换失败:', panel.id, e); }

    // ---- 开/关 两段式开关 → iOS 开关（隐藏原控件，点击映射到原 segment）----
    try {
      panel.querySelectorAll('span').forEach(w => {
        if (w.dataset.xhSegdone) return;
        const kids = [...w.children].filter(k => k.tagName === 'SPAN');
        if (kids.length !== 2) return;
        const t0 = (kids[0].textContent || '').trim(), t1 = (kids[1].textContent || '').trim();
        if (t0.length > 6 || t1.length > 6) return;
        if (!/开$/.test(t0) || !/关$/.test(t1)) return;
        const bgOf = (el) => String(el.style.background || '') + String(el.style.backgroundColor || '');
        if (!/rgba|rgb/.test(bgOf(kids[0])) && !/rgba|rgb/.test(bgOf(kids[1]))) return;
        w.dataset.xhSegdone = '1';
        const isOn = () => /rgba|rgb/.test(bgOf(kids[0]));
        const sw = topDoc.createElement('span');
        sw.className = 'xh-psw' + (isOn() ? ' on' : '');
        w.classList.add('xh-seg-hidden');
        w.insertAdjacentElement('afterend', sw);
        sw.onclick = (e) => {
          e.preventDefault(); e.stopPropagation();
          const target = !isOn();
          (target ? kids[0] : kids[1]).click();
          setTimeout(() => sw.classList.toggle('on', isOn()), 60);
        };
      });
    } catch (e) { log('[面板皮肤] 段开关转换失败:', panel.id, e); }
  }

  // ==================== 🍎 iOS 开关统一转换（适用于未接入皮肤引擎的悬浮窗面板）====================
