  // ==================== ⚡ 性能模式 ====================
  // 狐神模式（默认）：完整美化、动画、泛光、渐变
  // 性能模式：去除所有动画/阴影/泛光/渐变/模糊，保留核心配色、排版、圆角、边框、按钮配色
  function ssApplyPerfMode(on) {
    const root = topDoc.documentElement;
    const dash = topDoc.getElementById('ss-dashboard');

    // ✅ 修复：性能模式仅切换 CSS 类，不再触碰预设设置。
    //    之前的快照/恢复逻辑是因为 CSS `html.xh-perf *` 误伤酒馆本体导致
    //    预设勾选框视觉异常而加的补丁。现已将 CSS 作用域限定为脚本自身面板，
    //    不再需要快照/恢复。保留 setPreset 兜底以防极端情况。
    if (on) {
      root.classList.add('xh-perf');
      if (dash) dash.classList.add('xh-perf-on');
    } else {
      root.classList.remove('xh-perf');
      if (dash) dash.classList.remove('xh-perf-on');
    }

    // 同步开关状态
    const chk = topDoc.getElementById('xh-perf-check');
    if (chk) chk.checked = !!on;
    // 更新文案
    const nameEl = topDoc.querySelector('.xh-perf-name');
    const descEl = topDoc.querySelector('.xh-perf-desc');
    if (nameEl) nameEl.textContent = on ? '性能模式' : '狐神模式';
    if (descEl) descEl.textContent = on ? '精简提速·关闭美化' : '完整美化体验';
    try { localStorage.setItem('SPreset_XH_PerfMode', on ? '1' : '0'); } catch {}
    try { toast(on ? '⚡ 已切换至性能模式（已关闭美化与动画）' : '🦊 已切换至狐神模式（已开启完整美化）', 'success'); } catch {}
  }
  function ssInstallPerfMode() {
    // 读取已保存的状态（默认狐神模式）
