    app.innerHTML = `<div class="fox-phone-screen"><div class="fox-phone-status" data-drag><span>${clock}</span><span class="fp-status-ico">📶&nbsp;🛜&nbsp;🔋</span></div><div class="fox-phone-nav">${inSub ? '<button class="fp-navbtn" data-back>‹</button>' : '<span class="fp-navhold"></span>'}<b>${foxImageEscape(title)}</b><button class="fp-navbtn" data-close>✕</button></div><div class="fox-phone-body">${body}</div>${view.view === 'chat' ? `<div class="fp-inputbar"><input class="fp-input" placeholder="发消息..."><button class="fp-send">发送</button></div>` : inSub ? '' : `<div class="fox-phone-tabbar"><button data-tab="sessions" class="${tab === 'sessions' ? 'on' : ''}"><span>💬</span>消息${totalUnread ? `<i class="fp-badge">${totalUnread}</i>` : ''}</button><button data-tab="contacts" class="${tab === 'contacts' ? 'on' : ''}"><span>👥</span>通讯录${pendingIds.length ? `<i class="fp-badge">${pendingIds.length}</i>` : ''}</button><button data-tab="moments" class="${tab === 'moments' ? 'on' : ''}"><span>🌐</span>朋友圈</button></div>`}</div>`;
    const setView = v => { foxImageState.phoneView = v; foxPhoneRender(); };
    app.querySelector('[data-close]').onclick = () => { app.remove(); foxImageState.app = null; };
    app.querySelector('[data-back]')?.addEventListener('click', () => setView({ view: view.view === 'contactDetail' ? 'contacts' : 'sessions', contactId: '' }));
    app.querySelectorAll('[data-tab]').forEach(btn => btn.onclick = () => setView({ view: btn.dataset.tab, contactId: '' }));
    app.querySelectorAll('[data-chat]').forEach(cell => cell.onclick = () => { const id = cell.dataset.chat; const live = foxImageLoadDb(); if (live.contacts[id]) { live.contacts[id].unread = 0; foxImageSaveDb(live); } setView({ view: 'chat', contactId: id }); });
    app.querySelectorAll('[data-contact]').forEach(cell => cell.addEventListener('click', e => { if (e.target.closest('button')) return; setView({ view: 'contactDetail', contactId: cell.dataset.contact }); }));
    app.querySelector('[data-act="add"]')?.addEventListener('click', () => { const value = prompt('输入角色名或 9 位狐映号'); if (!value?.trim()) return; const live = foxImageLoadDb(); const contact = foxImageContact(live, value.trim()); contact.relation = 'contact'; contact.blockedByUser = false; contact.blocked = !!contact.blockedByContact; foxImagePendingAware(live, '添加好友', contact.accountId); foxImageSaveDb(live); foxImageTouchSnapshot(); setView({ view: 'contactDetail', contactId: contact.accountId }); });
    app.querySelectorAll('[data-accept]').forEach(btn => btn.onclick = () => { const live = foxImageLoadDb(); const id = btn.dataset.accept; if (live.contacts[id]) { live.contacts[id].relation = 'contact'; foxImagePendingAware(live, '接受好友申请', id); foxImageSaveDb(live); foxImageTouchSnapshot(); foxPhoneRender(); } });
    app.querySelectorAll('[data-reject]').forEach(btn => btn.onclick = () => { const live = foxImageLoadDb(); const id = btn.dataset.reject; if (live.contacts[id]) { live.contacts[id].relation = 'deleted'; foxImagePendingAware(live, '拒绝好友申请', id); foxImageSaveDb(live); foxImageTouchSnapshot(); foxPhoneRender(); } });
    app.querySelectorAll('.fp-action').forEach(btn => btn.onclick = () => {
      const id = foxImageState.phoneView.contactId; const live = foxImageLoadDb(); const c = live.contacts[id]; if (!c) return;
      if (btn.dataset.act === 'chat') { c.unread = 0; foxImageSaveDb(live); setView({ view: 'chat', contactId: id }); return; }
      if (btn.dataset.act === 'block') { c.blockedByUser = !c.blockedByUser; c.blocked = !!(c.blockedByUser || c.blockedByContact); c.relation = c.blockedByUser ? 'blocked_by_user' : c.blockedByContact ? 'blocked_by_contact' : 'contact'; foxImagePendingAware(live, c.blockedByUser ? '拉黑联系人' : '解除拉黑', id); }
      if (btn.dataset.act === 'delete') { c.relation = 'deleted'; foxImagePendingAware(live, '删除联系人', id); }
      foxImageSaveDb(live); foxImageTouchSnapshot(); setView({ view: 'contacts', contactId: '' });
    });
    app.querySelectorAll('.fp-moment').forEach(node => {
      node.querySelector('[data-like]').onclick = () => { const live = foxImageLoadDb(); const moment = live.moments.find(item => item.id === node.dataset.moment); if (!moment) return; moment.likes ||= []; const index = moment.likes.indexOf(live.accountId); if (index >= 0) moment.likes.splice(index, 1); else moment.likes.push(live.accountId); foxImagePendingAware(live, index >= 0 ? '取消朋友圈点赞' : '朋友圈点赞', moment.accountId, { momentId: moment.id }); foxImageSaveDb(live); foxImageTouchSnapshot(); foxPhoneRender(); };
      node.querySelector('[data-comment]').onclick = () => { const text = prompt('评论内容'); if (!text?.trim()) return; const live = foxImageLoadDb(); const moment = live.moments.find(item => item.id === node.dataset.moment); if (!moment) return; (moment.comments ||= []).push({ from: live.accountId, text: text.trim(), at: Date.now() }); foxImagePendingAware(live, '朋友圈评论', moment.accountId, { momentId: moment.id, text: text.trim() }); foxImageSaveDb(live); foxImageTouchSnapshot(); foxPhoneRender(); };
    });
    const sendNow = () => { const input = app.querySelector('.fp-input'); const text = String(input?.value || '').trim(); if (!text || !foxImageState.phoneView.contactId) return; input.value = ''; foxImageSendContact(foxImageState.phoneView.contactId, text); };
    app.querySelector('.fp-send')?.addEventListener('click', sendNow);
    app.querySelector('.fp-input')?.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendNow(); } });
    const bodyEl = app.querySelector('.fox-phone-body'); if (view.view === 'chat') bodyEl.scrollTop = bodyEl.scrollHeight;
    foxImageFloatDrag(app, app.querySelector('[data-drag]'), 'SPreset_FoxImage_Phone_Pos');
  }
  function foxImageFloatDrag(win, handle, storageKey) {
    if (!win || !handle) return;
    handle.addEventListener('pointerdown', e => {
      if (e.target.closest('button,input,select,textarea,a,label')) return;
      const rect = win.getBoundingClientRect(); const sx = e.clientX, sy = e.clientY, sl = rect.left, st = rect.top; let moved = false;
      const mv = ev => { const dx = ev.clientX - sx, dy = ev.clientY - sy; if (Math.abs(dx) > 4 || Math.abs(dy) > 4) moved = true; if (!moved) return; const vw = topWindow.innerWidth || 800, vh = topWindow.innerHeight || 600; win.style.left = `${Math.max(4, Math.min(vw - 90, sl + dx))}px`; win.style.top = `${Math.max(4, Math.min(vh - 50, st + dy))}px`; win.style.right = 'auto'; win.style.bottom = 'auto'; };
      const up = () => { topDoc.removeEventListener('pointermove', mv); topDoc.removeEventListener('pointerup', up); if (moved && storageKey) try { const r = win.getBoundingClientRect(); localStorage.setItem(storageKey, JSON.stringify({ left: Math.round(r.left), top: Math.round(r.top) })); } catch {} };
      topDoc.addEventListener('pointermove', mv); topDoc.addEventListener('pointerup', up); e.preventDefault();
    });
  }
  function foxImageRestoreFloatPos(win, storageKey, fallback) {
    let pos = null; try { pos = JSON.parse(localStorage.getItem(storageKey) || 'null'); } catch {}
    const vw = topWindow.innerWidth || 900, vh = topWindow.innerHeight || 700;
    const inBounds = pos && Number.isFinite(pos.left) && Number.isFinite(pos.top)
      && pos.left >= -50 && pos.left <= vw - 80
      && pos.top >= 40 && pos.top <= vh - 60;
    if (inBounds) { win.style.left = `${pos.left}px`; win.style.top = `${pos.top}px`; win.style.right = 'auto'; win.style.bottom = 'auto'; }
    else if (fallback) { win.style.left = `${fallback.left}px`; win.style.top = `${fallback.top}px`; }
  }

