  function foxFrontRenderMessage(host, message, config) {
    const messageId = message.message_id; const swipeId = message.swipe_id ?? 0;
    const text = foxImageGetMessageText(message);
    const blocks = foxImageTags(text, config.front.tag);
    if (!blocks.length) return;
    foxImageState.frontBodies ||= new Map();
    // 依次在文本节点中寻找占位符并挂载；每个挂载点消耗一个块（每次挂载后重新遍历，保证顺序正确）
