    while (placed < blocks.length) {
      const walker = topDoc.createTreeWalker(host, 4); let node; let mounted = false;
      while ((node = walker.nextNode())) {
        if (node.parentElement?.closest('.fox-front-frame')) continue;
        const value = String(node.nodeValue || ''); const idx = value.indexOf(config.front.placeholder);
        if (idx < 0) continue;
        const block = blocks[placed]; const key = foxMemoryHashText(`${messageId}|${swipeId}|${block.body}`);
        foxImageState.frontBodies.set(key, { body: block.body, messageId, swipeId });
        const anchor = topDoc.createElement('span'); anchor.className = 'fox-front-anchor'; anchor.innerHTML = foxFrontFrameHtml(key);
        const fragment = topDoc.createDocumentFragment();
        fragment.append(value.slice(0, idx), anchor, value.slice(idx + config.front.placeholder.length));
        node.replaceWith(fragment);
        placed++; mounted = true;
        break;
      }
      if (!mounted) break;
    }
    // 占位符不够时，剩余块追加到楼层末尾
    for (; placed < blocks.length; placed++) {
      const block = blocks[placed]; const key = foxMemoryHashText(`${messageId}|${swipeId}|${block.body}`);
      foxImageState.frontBodies.set(key, { body: block.body, messageId, swipeId });
      const anchor = topDoc.createElement('span'); anchor.className = 'fox-front-anchor'; anchor.innerHTML = foxFrontFrameHtml(key);
