    }
    host.querySelectorAll('.fox-front-frame').forEach(frame => {
      const key = frame.dataset.front; if (!key || frame.dataset.done) return; frame.dataset.done = '1';
      const cached = foxFrontGet(key);
      if (cached) { frame.style.height = `${Math.max(120, Math.min(800, Number(cached.height) || 380))}px`; foxFrontFillFrame(frame, cached); }
      else { const info = foxImageState.frontBodies.get(key); if (info) foxFrontQueue(info.messageId, info.swipeId, info.body); }
    });
  }

  // ---- 协议文本隐藏（手机标签 + 前端标签 + 旧版残留）----
  function foxImageHideProtocols(host, config = foxImageState.config || foxImageLoadConfig()) {
    const tags = [...new Set(['fox_social', 'fox_front', 'fox_letter', 'fox_system', 'fox_phone_log', config.phone?.tag, config.front?.tag].filter(Boolean))];
    for (const tag of tags) for (const node of [...host.querySelectorAll(tag)]) node.style.display = 'none';
    const walker = topDoc.createTreeWalker(host, 4); const nodes = []; let node;
    while ((node = walker.nextNode())) if (!node.parentElement?.closest('.fox-front-frame')) nodes.push(node);
    const placeholders = [config.phone?.placeholder, config.front?.placeholder].filter(Boolean);
    for (const textNode of nodes) {
      let value = String(textNode.nodeValue || '').replace(/<fox_(social|front|letter|system|phone_log)(?:\s[^>]*)?>[\s\S]*?<\/fox_\1>/gi, '');
      for (const tag of tags) value = value.replace(new RegExp(`<${tag}(?:\\s[^>]*)?>[\\s\\S]*?<\\/${tag}>`, 'gi'), '');
      for (const placeholder of placeholders) value = value.split(placeholder).join('');
      textNode.nodeValue = value;
    }
  }

  // ---- 楼层渲染编排 ----
  function foxImageRenderMessage(messageId) {
    const config = foxImageState.config || foxImageLoadConfig();
    const message = getFn('getChatMessages')?.(messageId, { include_swipes: true })?.[0]; if (!message) return;
    const host = topDoc.querySelector(`#chat > .mes[mesid="${messageId}"] .mes_text`); if (!host) return;
