  // ---- 提示词同步：写入预设条目「🦊狐映~」的 {{setvar::huying::}} 段 ----
  function foxImageWrapSetvar(existing, body) {
    const OPEN = '{{setvar::huying::'; const inner = String(body || '').trim().replace(/}}/g, '');
    const text = String(existing || ''); const start = text.indexOf(OPEN);
    if (start < 0) return `${OPEN}\n\n${inner}\n\n}}`;
    const closeIdx = text.indexOf('}}', start + OPEN.length);
