      const tag = config.phone.tag;
      const example = `#事件开始\n#类型 消息\n#事件ID 本轮唯一短ID\n#角色 角色名\n#账号 角色的9位账号（已知才写）\n#时间 剧情时间\n#内容\n角色真实发送的短消息\n#事件结束\n\n同一轮可继续写新的#事件开始块。#类型还可写：上线、离线、忙碌、加好友、好友申请、删好友、拉黑、解除拉黑、朋友圈、朋友圈评论。朋友圈评论用#目标写动态ID或被评论角色。`;
      parts.push(`【狐映·现代通讯输出协议】\n需要输出本模块时，先原样输出占位符：${config.phone.placeholder}\n紧接着输出 <${tag}>...</${tag}>。\n标签内部禁止JSON，禁止Markdown代码块，仅允许#字段；字段仅描述本轮新增变化，禁止重复历史状态；本轮无新增变化时不得输出占位符或标签。\n【严格格式示例】\n<${tag}>\n${example}\n</${tag}>\n${String(config.phone.prompt || FOX_IMAGE_PHONE_PROTOCOL).trim()}`);
