  // ---- 悬浮入口（输入框上方的 📱 按钮）----
  function foxImageEnsureLauncher() {
    topDoc.getElementById('fox-image-launcher')?.remove();
    foxImageInjectStyle();
    const config = foxImageState.config || foxImageLoadConfig();
    if (!config.enabled || !config.phone?.enabled || config.launcher === false) return;
    const bar = topDoc.createElement('div'); bar.id = 'fox-image-launcher'; bar.title = '狐映手机';
    bar.innerHTML = `<button type="button" data-open="phone" title="狐映手机">📱</button><button type="button" class="fi-lx" data-open="close" title="隐藏悬浮入口（可在狐映面板「全局设置」重新开启）">✕</button>`;
    topDoc.body.appendChild(bar);
    const updateLauncherPosition = () => {
      if (!bar.isConnected) return;
      const ta = topDoc.getElementById('send_textarea');
      if (ta) {
        const rect = ta.getBoundingClientRect(); const vh = topWindow.innerHeight;
        let bottom = vh - rect.top + 8;
        if (rect.top < 0 || rect.top > vh) bottom = 120;
        bottom = Math.max(50, Math.min(vh - 100, bottom));
        bar.style.bottom = `${bottom}px`;
      }
    };
    updateLauncherPosition();
    if (foxImageState._launcherResizeHandler) topWindow.removeEventListener('resize', foxImageState._launcherResizeHandler);
    let rTimer = null;
    foxImageState._launcherResizeHandler = () => { clearTimeout(rTimer); rTimer = setTimeout(updateLauncherPosition, 150); };
    topWindow.addEventListener('resize', foxImageState._launcherResizeHandler);
    if (foxImageState._launcherInterval) clearInterval(foxImageState._launcherInterval);
    // 🦊 性能优化：从 1s 改为 3s--悬浮按钮位置不需要实时精确，3s 足够覆盖布局变化
    foxImageState._launcherInterval = setInterval(updateLauncherPosition, 3000);
    bar.addEventListener('click', e => {
      const btn = e.target.closest('button'); if (!btn) return;
      if (btn.dataset.open === 'phone') { foxPhoneOpen(); return; }
      if (btn.dataset.open === 'close') {
        const live = foxImageState.config || foxImageLoadConfig(); live.launcher = false; foxImageSaveConfig(live);
        if (foxImageState._launcherInterval) { clearInterval(foxImageState._launcherInterval); foxImageState._launcherInterval = null; }
        bar.remove(); toast('📱 狐映悬浮入口已隐藏，可在狐映面板「全局设置」重新开启', 'info');
      }
    });
  }

  // ---- 事件绑定：渲染 + 快照回退 ----
  function foxImageBindEvents() {
    foxImageUnbindEvents();
    const eventOn = getFn('eventOn');
    const events = getFn('tavern_events') || (typeof tavern_events !== 'undefined' ? tavern_events : null);
    if (typeof eventOn !== 'function' || !events) return;
    // 防抖：多次快速渲染请求合并为一次
    let _renderTimer = null;
    let _renderIds = new Set();
    const _debouncedRender = (messageId) => {
      if (Number.isFinite(messageId)) _renderIds.add(messageId);
      else _renderIds.clear();
      if (_renderTimer) clearTimeout(_renderTimer);
      _renderTimer = setTimeout(() => {
        _renderTimer = null;
        if (_renderIds.size === 0) {
          foxImageRenderAll();
        } else {
          for (const id of _renderIds) foxImageRenderMessage(id);
          _renderIds.clear();
        }
        foxPhoneRender();
      }, 400);
    };
    for (const name of ['MESSAGE_RECEIVED', 'GENERATION_ENDED', 'CHAT_CHANGED', 'MESSAGE_EDITED', 'MESSAGE_UPDATED', 'MESSAGE_SWIPED', 'MESSAGE_DELETED']) {
      if (!events[name]) continue;
      const handle = eventOn(events[name], (...args) => setTimeout(() => {
        if (name === 'CHAT_CHANGED') {
          foxImageState.epoch++;
          foxImageState.queues.clear();
          foxImageState.scope = foxImageScope();
          foxImageState.phoneView = { view: 'sessions', contactId: '' };
          foxImageState.frontBodies?.clear?.();
          _renderIds.clear(); _debouncedRender();
          return;
        }
        const messageId = Number(args[0]);
        if (name === 'MESSAGE_SWIPED' && Number.isFinite(messageId)) {
          foxImageRestoreSnapshot(messageId - 1);
          _renderIds.clear(); _debouncedRender();
          return;
        }
        if (name === 'MESSAGE_DELETED') {
          const last = Number(getFn('getLastMessageId')?.() ?? -1);
          foxImageRestoreSnapshot(Math.max(0, last));
          _renderIds.clear(); _debouncedRender();
          return;
        }
        if (['MESSAGE_EDITED', 'MESSAGE_UPDATED'].includes(name)) _debouncedRender();
        else if (Number.isFinite(messageId)) _debouncedRender(messageId);
        else _debouncedRender();
      }, name === 'GENERATION_ENDED' ? 700 : 300));
      foxImageState.eventHandles.push(handle);
    }
    // MutationObserver：SillyTavern 重新渲染消息DOM后，自动重新插入狐映前端
    // 🦊 性能优化：移除 characterData:true（流式传输时每个字符都触发，造成严重卡顿），
    //    仅保留 childList 监听即可覆盖 SillyTavern 重新渲染消息 DOM 的场景。
    //    同时在回调入口处增加功能开关早退检查，避免功能关闭时仍做 clearTimeout/setTimeout。
    const chatContainer = topDoc.querySelector('#chat');
    if (chatContainer && topWindow.MutationObserver) {
      let _mutTimer = null;
      const observer = new topWindow.MutationObserver(() => {
        // 🦊 早退：功能关闭时直接返回，不触发防抖定时器
        const config = foxImageState.config || foxImageLoadConfig();
        if (!config.enabled || !config.front?.enabled) return;
        if (_mutTimer) clearTimeout(_mutTimer);
        _mutTimer = setTimeout(() => {
          _mutTimer = null;
          const last = getFn('getLastMessageId')?.() ?? -1;
          if (last < 0) return;
          for (let i = Math.max(0, last - 10); i <= last; i++) {
            const host = topDoc.querySelector(`#chat > .mes[mesid="${i}"] .mes_text`);
            if (!host) continue;
            const text = host.textContent || '';
            const hasAnchor = host.querySelector('.fox-front-anchor');
            // 有占位符或fox_front标签但没有锚点 = SillyTavern覆盖了，重新渲染
            if (!hasAnchor && (text.includes(config.front.placeholder || '【前端插入】') || text.includes('<fox_front') || text.includes('&lt;fox_front'))) {
              foxImageRenderMessage(i);
            }
          }
        }, 300);
      });
      observer.observe(chatContainer, { childList: true, subtree: true });
      foxImageState._observer = observer;
    }
  }
  function foxImageUnbindEvents() {
    for (const handle of foxImageState.eventHandles.splice(0)) ssStopEventHandle(handle);
    if (foxImageState._observer) { try { foxImageState._observer.disconnect(); } catch {} foxImageState._observer = null; }
  }
  function foxImageResetRuntime() {
    foxImageState.epoch++; foxImageUnbindEvents(); foxImageState.queues.clear();
    foxImageState.scope = foxImageScope(); foxImageState.phoneView = { view: 'sessions', contactId: '' };
    foxImageState.frontBodies?.clear?.(); foxImageState.frontPending.clear(); foxImageState.frontChain = Promise.resolve();
    foxImageState.app?.remove(); foxImageState.app = null;
    if (foxImageState._launcherInterval) { clearInterval(foxImageState._launcherInterval); foxImageState._launcherInterval = null; }
    if (foxImageState._launcherResizeHandler) { try { topWindow.removeEventListener('resize', foxImageState._launcherResizeHandler); } catch {} foxImageState._launcherResizeHandler = null; }
    foxImageEnsureLauncher();
  }
  function foxImageInit() {
    foxImageState.config = foxImageLoadConfig(); foxImageSaveConfig(foxImageState.config);
    foxImageState.scope = foxImageScope();
    // 🦊 清理旧版残留存储（V1 楼层状态 / 旧系统面板 / 旧悬浮窗位置）
    try {
      const doomed = [];
      for (let i = 0; i < localStorage.length; i++) { const key = localStorage.key(i); if (/^SPreset_FoxImage_(State_|System_)/.test(key || '')) doomed.push(key); }
      for (const key of doomed) localStorage.removeItem(key);
      localStorage.removeItem('SPreset_FoxImage_Comm_Pos'); localStorage.removeItem('SPreset_FoxImage_Sys_Pos'); localStorage.removeItem('SPreset_FoxImage_Launcher_Pos');
    } catch {}
    foxImageEnsureLauncher(); foxImageBindEvents();
    foxImageApplyPrompt().catch(error => log('[狐映] 初始化提示词同步失败', error));
    setTimeout(foxImageRenderAll, 1200);
  }

  // ==================== 🕰️ 狐刻：时刻表模块 ====================
  // 狐刻：基于楼层推进的剧情时间轴 / 时刻表 / 触发器模块。
  // 独立物理存储（SPreset_FoxTime_ 前缀），沿用当前角色卡 + 聊天作用域隔离。
