      }
    }
    // 0.5. 次优先：匹配时间刻标签 <ft_clock day="X" minute="Y" />
    //    仅在 ▶ 行未命中时使用（避免误用起始时间）
    if (!result.clock) {
    const clockTag = text.match(/<ft_clock\s+day=["']?(\d+)["']?\s+minute=["']?(\d+)["']?\s*\/?>/i);
    if (clockTag) {
      result.clock = { day: parseInt(clockTag[1]), minute: parseInt(clockTag[2]), confidence: 'explicit' };
    }
    }
    // 1. 【时间：…】或 当前时间：… 或 时间：…
    if (!result.clock) {
    const timeBracket = text.match(/(?:【时间[：:]|当前时间[：:]|时间[：:])([^】\n]+)/);
    if (timeBracket) {
      const t = timeBracket[1].trim();
      const dayMatch = t.match(/第(\d+)天/);
      const hmMatch = t.match(/(\d{1,2}):(\d{2})/);
      if (dayMatch || hmMatch) {
        const day = dayMatch ? parseInt(dayMatch[1]) : 1;
        const minute = hmMatch ? parseInt(hmMatch[1]) * 60 + parseInt(hmMatch[2]) : 0;
        result.clock = { day, minute, confidence: 'explicit' };
      }
    }
    }
    // 2. 在 <details> 块内扫描（避免误匹配正文中的时间）
    if (!result.clock) {
      const detailsMatch = text.match(/<details>[\s\S]*?<\/details>/i);
      const searchText = detailsMatch ? detailsMatch[0] : '';
      if (searchText) {
        const dayMatch = searchText.match(/第(\d+)天/);
        const hmMatch = searchText.match(/(\d{1,2}):(\d{2})/);
        if (dayMatch && hmMatch) {
          result.clock = { day: parseInt(dayMatch[1]), minute: parseInt(hmMatch[1]) * 60 + parseInt(hmMatch[2]), confidence: 'explicit' };
        } else if (hmMatch) {
          result.clock = { day: 1, minute: parseInt(hmMatch[1]) * 60 + parseInt(hmMatch[2]), confidence: 'explicit' };
        }
      }
    }

    // 好感度 / 数值提取
    const kvPatterns = [
      { key: '好感度', re: /(?:好感度|好感|好感值)[：:]\s*(\d+)/g },
      { key: '信任度', re: /(?:信任度|信任)[：:]\s*(\d+)/g },
      { key: '恐惧值', re: /(?:恐惧值|恐惧)[：:]\s*(\d+)/g },
      { key: '金钱', re: /(?:金钱|金币|资金)[：:]\s*(\d+)/g },
    ];
    for (const { key, re } of kvPatterns) {
      let m;
      while ((m = re.exec(text)) !== null) {
        result.kv[key] = { value: Number(m[1]), source: 'regex' };
      }
    }

    // 日期提取
    const dateMatch = text.match(/(?:日期[：:]|当前日期[：:])([^】\n]+)/);
    if (dateMatch) {
      result.kv['日期'] = { value: dateMatch[1].trim(), source: 'regex' };
    }

    // 阶段提取：【阶段：rel_alice = 信任】
    const stageRe = /(?:【阶段[：:]|当前阶段[：:])([^】\n]+)/g;
    let sm;
    while ((sm = stageRe.exec(text)) !== null) {
      const parts = sm[1].split(/[=＝:：]/).map(s => s.trim()).filter(Boolean);
      if (parts.length >= 2) {
        result.stageSchemas.push({ id: parts[0], current: parts[1] });
      }
    }

    // 用户自定义正则
    if (cfg.customRegex && typeof cfg.customRegex === 'string') {
      try {
        const userRe = new RegExp(cfg.customRegex, 'g');
        let um;
        while ((um = userRe.exec(text)) !== null) {
          const k = um[1] || um[0];
          const v = um[2] || '';
          if (k) result.kv[String(k)] = { value: v || true, source: 'custom_regex' };
        }
      } catch (e) {
        log('[狐刻·正则] 用户自定义正则无效', e);
      }
    }

    return result;
  }

  // ---- MVU 联动 ----
  function ftReadMvu() {
    try {
      if (typeof window === 'undefined' || !window.Mvu) return null;
      if (typeof window.Mvu.getMvuData !== 'function') return null;
      const data = window.Mvu.getMvuData({ type: 'message', message_id: 'latest' });
      // MVU 返回结构：{ stat_data: { ... }, display_data: { ... }, ... }
      // 拍平 stat_data 下的直接数值
      if (data && typeof data === 'object') {
        const stat = data.stat_data || data;
        if (stat && typeof stat === 'object') {
          const flat = {};
          for (const [k, v] of Object.entries(stat)) {
            if (typeof v === 'number' || typeof v === 'string') {
              flat[k] = v;
            } else if (typeof v === 'object' && v !== null && 'value' in v) {
              flat[k] = v.value;
            }
          }
          return Object.keys(flat).length ? flat : null;
        }
      }
      return null;
    } catch (e) { log('[狐刻·MVU] 读取失败', e); return null; }
  }

  function ftWriteMvu(clock) {
    try {
      const cfg = ftState.config || ftLoadConfig();
      if (!cfg.mvuWriteClock) return false;
      if (typeof window === 'undefined' || !window.Mvu) return false;
      if (typeof window.Mvu.setMvuVariable !== 'function') return false;
      const label = ftClockLabel(clock);
      const path = cfg.mvuClockPath || 'stat_data.剧情时间';
      window.Mvu.setMvuVariable(path, label);
      log(`[狐刻·MVU] 已写入时钟：${label}`);
      return true;
    } catch (e) { log('[狐刻·MVU] 写入失败', e); return false; }
  }

  // ---- 狐刻上下文注入：获取狐忆(事件+角色关系)和狐构(阶段+关系+事件) ----
  function ftBuildContextInject() {
    let memoryText = '';
    let outlineText = '';
    // 狐忆：事件 + 角色关系
    try {
      const memories = foxMemoryGetCurrent();
      const memData = loadFoxMemory();
      const hasMem = memories && memories.length;
      const hasProfile = memData?.characterProfiles && Object.keys(memData.characterProfiles).length;
      if (hasMem || hasProfile) {
        let parts = [];
        if (hasMem) {
          const body = foxMemoryBuildMemoryBodyForInject(memories, { maxPlotChunks: 50 });
          if (body?.trim()) parts.push(body.trim());
        }
        if (hasProfile) {
          const prof = foxMemoryBuildProfileInjectBody('');
          if (prof?.trim()) parts.push(prof.trim());
        }
        memoryText = parts.join('\n\n');
      }
    } catch (e) { log('[狐刻] 获取狐忆上下文失败', e); }
    // 狐构：阶段 + 关系 + 事件
    try {
      const raw = outlineLoadLocalRaw();
      if (raw?.trim()) {
        outlineText = ssBuildOutlineInject(raw).trim();
      }
    } catch (e) { log('[狐刻] 获取狐构上下文失败', e); }
    // 🏷️ 标签过滤（和狐忆/狐构/狐搜同款）
    const cfg = ftState.config || ftLoadConfig();
    if (cfg.enableContentFilter !== false) {
      const fs = ssNormalizeTagFilterSettings(cfg);
      if (memoryText) memoryText = ssFilterByTagPairs(memoryText, fs, { source: '狐刻·狐忆' });
      if (outlineText) outlineText = ssFilterByTagPairs(outlineText, fs, { source: '狐刻·狐构' });
    }
    return { memoryText, outlineText };
  }

  // ---- AI 解析协议 ----
  function ftBuildParsePrompt(recentText, currentState) {
    const clock = currentState.clock || {};
    const abs = ftClockAbs(clock);
    // 🦊 注册默认提示词，支持用户自定义
    xhRegisterPromptDefault('fox_time', {
      head: `你是剧情时间轴解析器。你的任务是分析最新回复正文，提取时间、数值、阶段和触发信息。

必须严格遵守以下输出协议，不要输出任何其他内容：

# TIME
DAY: <天数，整数>
MINUTE: <分钟，0-1439的整数>
CONFIDENCE: <explicit|estimated|unknown>
# KV
<键>: <值>
# STAGE
<阶段ID>: <当前阶段名>
# TRIGGER
FIRED: <已触发的节点ID，没有则写 none>

规则：
1. DAY 和 MINUTE 必须有值。如果正文中没有明确时间，基于上一轮时间合理推进（通常每轮推进30-120分钟）。
2. 时间只能前进，不能倒退。上一轮绝对时间为 ${abs} 分钟（第${clock.day}天 ${String(Math.floor((clock.minute||0)/60)).padStart(2,'0')}:${String((clock.minute||0)%60).padStart(2,'0')}）。
3. KV 段提取正文中出现的数值变化（好感度、信任度、金钱等），没有则留空段。
4. STAGE 段提取角色关系阶段变化，没有则留空段。
5. TRIGGER 段只填本轮正文已经触发的节点ID，没有则填 none。`,
      tail: '请按协议输出：'
    });

    return `${xhGetPrompt('fox_time', 'head')}

【当前时间状态】
${JSON.stringify({ clock, kv: currentState.kv || {}, stageSchemas: currentState.stageSchemas || [], nodes: (currentState.nodes || []).map(n => ({ id: n.id, name: n.name, type: n.type, status: n.status })) }, null, 2)}

【最新回复正文】
${recentText}

${xhGetPrompt('fox_time', 'tail')}`;
  }

  function ftParseAIResult(text) {
    const result = { clock: null, kv: {}, stageSchemas: [], triggers: [] };
    if (!text || typeof text !== 'string') return result;

    // 解析 # TIME 段
    const timeMatch = text.match(/#\s*TIME\s*\n([\s\S]*?)(?=\n#\s|\n$|$)/i);
    if (timeMatch) {
      const block = timeMatch[1];
      const dayM = block.match(/DAY\s*[:：]\s*(\d+)/i);
      const minM = block.match(/MINUTE\s*[:：]\s*(\d+)/i);
      const confM = block.match(/CONFIDENCE\s*[:：]\s*(\w+)/i);
      if (dayM || minM) {
        result.clock = {
          day: dayM ? parseInt(dayM[1]) : 1,
          minute: minM ? Math.min(1439, Math.max(0, parseInt(minM[1]))) : 0,
          confidence: confM ? String(confM[1]).toLowerCase() : 'estimated',
        };
      }
    }

    // 解析 # KV 段
    const kvMatch = text.match(/#\s*KV\s*\n([\s\S]*?)(?=\n#\s|\n$|$)/i);
    if (kvMatch) {
      const lines = kvMatch[1].split('\n').map(l => l.trim()).filter(Boolean);
      for (const line of lines) {
        const parts = line.split(/[:：]/).map(s => s.trim());
        if (parts.length >= 2) {
          const val = parts.slice(1).join(':').trim();
          const numVal = Number(val);
          result.kv[parts[0]] = { value: !isNaN(numVal) && val !== '' ? numVal : val, source: 'ai' };
        }
      }
    }

    // 解析 # STAGE 段
    const stageMatch = text.match(/#\s*STAGE\s*\n([\s\S]*?)(?=\n#\s|\n$|$)/i);
    if (stageMatch) {
      const lines = stageMatch[1].split('\n').map(l => l.trim()).filter(Boolean);
      for (const line of lines) {
        const parts = line.split(/[:：]/).map(s => s.trim());
        if (parts.length >= 2) {
          result.stageSchemas.push({ id: parts[0], current: parts.slice(1).join(':').trim() });
        }
      }
    }

    // 解析 # TRIGGER 段
    const trigMatch = text.match(/#\s*TRIGGER\s*\n([\s\S]*?)(?=\n#\s|\n$|$)/i);
    if (trigMatch) {
      const firedM = trigMatch[1].match(/FIRED\s*[:：]\s*(.+)/i);
      if (firedM) {
        const ids = firedM[1].trim().split(/[,，\s]+/).filter(id => id && id.toLowerCase() !== 'none');
        result.triggers = ids;
      }
    }

    return result;
  }

  // ---- 触发判定（纯数字比较）----
  function ftEvaluateTriggers(data) {
    const d = data || ftState.data;
    if (!d) return { due: [], fired: [], expired: [] };
    const clockAbs = ftClockAbs(d.clock);
    const result = { due: [], fired: [], expired: [] };
    const nodes = Array.isArray(d.nodes) ? d.nodes : [];

    for (const node of nodes) {
      if (!node || !node.id) continue;
      const status = String(node.status || 'pending');
      if (status === 'fired' || status === 'expired') continue;

      let isDue = false;
      const trigger = node.trigger || {};

      if (trigger.type === 'time') {
        // 时间触发：clock.absolute >= trigger.abs
        const triggerAbs = Number(trigger.abs) || 0;
        if (clockAbs >= triggerAbs) isDue = true;
      } else if (trigger.type === 'stage') {
        // 阶段触发：schemas[stageId].current >= minStep
        const stageId = trigger.stageId || '';
        const minStep = trigger.minStep || '';
        const schema = (d.stageSchemas || []).find(s => s.id === stageId);
        if (schema && schema.current) {
          const stepIndex = (schema.steps || []).indexOf(schema.current);
          const minIndex = (schema.steps || []).indexOf(minStep);
          if (stepIndex >= 0 && minIndex >= 0 && stepIndex >= minIndex) isDue = true;
        }
      } else if (trigger.type === 'kv') {
        // KV 触发：kv[key].value 满足 op
        const key = trigger.key || '';
        const op = trigger.op || '>=';
        const target = Number(trigger.value) || 0;
        const kvEntry = d.kv?.[key];
        if (kvEntry) {
          const currentVal = Number(kvEntry.value) || 0;
          switch (op) {
            case '>=': isDue = currentVal >= target; break;
            case '>': isDue = currentVal > target; break;
            case '<=': isDue = currentVal <= target; break;
            case '<': isDue = currentVal < target; break;
            case '==': isDue = currentVal === target; break;
            case '!=': isDue = currentVal !== target; break;
          }
        }
      } else if (trigger.type === 'ai') {
        // AI 触发：已由 ftParseAIResult 的 # TRIGGER 段回答
        if (node.aiFired) isDue = true;
      }

      if (isDue) {
        const window = node.window || {};
        if (window.latestAbs && Number(window.latestAbs) < clockAbs) {
          // 过期的到期节点：标记为 expired，不注入
          result.expired.push(node.id);
        } else {
          // 未过期的到期节点：标记为 due（注入C档）+ fired（标记状态）
          result.due.push(node.id);
          result.fired.push(node.id);
        }
      } else {
        // pending 节点已过窗口 -> expired
        const window = node.window || {};
        if (status === 'pending' && window.latestAbs && Number(window.latestAbs) < clockAbs) {
          result.expired.push(node.id);
        }
      }
    }

    return result;
  }

  // ---- 每楼推进主流程 ----
  async function ftAdvanceFloor(messageId) {
    // message_id 即楼层，禁止 +1
    const floor = Math.max(0, Number(messageId) || 0);
    const cfg = ftState.config || ftLoadConfig();
    if (!cfg.enabled) return false;

    ftState.running = true;
    try {
      let d = ftState.data || ftLoadData();
      const oldAbs = ftClockAbs(d.clock);

      // 1. 读 MVU（mvuLink!=off 且 window.Mvu 存在）-> 合并进 kv（source:'mvu'）
      if (cfg.mvuLink !== 'off') {
        const mvuData = ftReadMvu();
        if (mvuData && typeof mvuData === 'object') {
          for (const [k, v] of Object.entries(mvuData)) {
            // ftReadMvu 已拍平为 { key: number/string } 结构
            d.kv[k] = { value: v, source: 'mvu', updatedFloor: floor };
          }
        }
      }

      // 2. 获取最新楼正文 + 正则照抄
      const gcm = getFn('getChatMessages');
      let recentText = '';
      if (gcm) {
        const m = gcm(floor, { hide_state: 'all', include_swipes: true })?.[0];
        if (m) recentText = xhGetAssistantMessageText(m).text;
      }

      // 🎯 按解析范围配置提取有效文本（已剔除思维链等噪声标签）
      // recentText 保留原始全文用于排查；parseText 才是真正喂给正则/AI 的内容
      const parseText = ftExtractParseText(recentText);

      const regexResult = ftRegexExtract(parseText);
      log(`[狐刻·推进] 正则结果：clock=${regexResult.clock ? JSON.stringify(regexResult.clock) : 'null'}，解析范围=${(ftState.config || ftLoadConfig()).parseScope}，正文前200字=${parseText.slice(0, 200)}`);
      let clockUpdated = false;

      if (regexResult.clock) {
        // 正则匹配的时间刻标签是AI明确输出的，直接使用不钳制（避免之前误匹配的时间阻止正确更新）
        const newAbs = ftClockAbs(regexResult.clock);
        const newClock = ftClockFromAbs(newAbs);
        d.clock = { ...d.clock, ...newClock, label: ftClockLabel(newClock), confidence: 'explicit', updatedFloor: floor, unknown: false };
        clockUpdated = true;
        log(`[狐刻·推进] 正则命中时间：${ftClockLabel(d.clock)}`);
      }

      // 合并正则 KV
      for (const [k, v] of Object.entries(regexResult.kv)) {
        d.kv[k] = v;
      }
      // 合并正则阶段
      for (const stage of regexResult.stageSchemas) {
        const existing = (d.stageSchemas || []).find(s => s.id === stage.id);
        if (existing) existing.current = stage.current;
        else d.stageSchemas.push({ id: stage.id, current: stage.current, steps: [stage.current] });
      }

      // 3-5. AI 解析（hybrid 且正则没命中时间 / always_ai / batch 攒够）
      const shouldAI = cfg.parseMode === 'always_ai'
        || (cfg.parseMode === 'hybrid' && !clockUpdated)
        || (cfg.parseMode === 'batch' && (ftState.autoCounter % Math.max(1, cfg.batchN) === 0));

      if (shouldAI && parseText.trim()) {
        try {
          const prompt = ftBuildParsePrompt(parseText, d);
          const aiResult = await ftGenerateRaw({
            ordered_prompts: [
              { role: 'system', content: '你是剧情时间轴解析器，只按协议输出，禁止角色扮演。' },
              { role: 'user', content: prompt },
            ],
            should_silence: true,
            should_stream: false,
            max_chat_history: 0,
          });

          if (aiResult) {
            const parsed = ftParseAIResult(aiResult);
            // 6. 应用更新（clock 只允许前进）
            if (parsed.clock) {
              const aiAbs = ftClockAbs(parsed.clock);
              const clampedAbs = ftClampClockForward(ftClockAbs(d.clock), aiAbs);
              const clampedClock = ftClockFromAbs(clampedAbs);
              d.clock = { ...d.clock, ...clampedClock, label: ftClockLabel(clampedClock), confidence: parsed.clock.confidence || 'estimated', updatedFloor: floor, unknown: false };
            }
            for (const [k, v] of Object.entries(parsed.kv)) {
              d.kv[k] = v;
            }
            for (const stage of parsed.stageSchemas) {
              const existing = (d.stageSchemas || []).find(s => s.id === stage.id);
              if (existing) existing.current = stage.current;
              else d.stageSchemas.push({ id: stage.id, current: stage.current, steps: [stage.current] });
            }
            for (const nodeId of parsed.triggers) {
              const node = (d.nodes || []).find(n => n.id === nodeId);
              if (node) node.aiFired = true;
            }
            log(`[狐刻·推进] AI解析完成：${parsed.triggers.length} 个触发`);
          }
        } catch (e) {
          log('[狐刻·推进] AI解析失败，降级为正则结果', e);
        }
      }

      // 7. 触发判定
      const triggers = ftEvaluateTriggers(d);
      for (const nodeId of triggers.fired) {
        const node = (d.nodes || []).find(n => n.id === nodeId);
        if (node) { node.status = 'fired'; node.firedFloor = floor; }
      }
      for (const nodeId of triggers.expired) {
        const node = (d.nodes || []).find(n => n.id === nodeId);
        if (node) { node.status = 'expired'; node.expiredFloor = floor; }
      }

      // 8. MVU 写回（mvuLink=auto 且 mvuWriteClock）
      if (cfg.mvuLink === 'auto' && cfg.mvuWriteClock) {
        ftWriteMvu(d.clock);
      }

      // 9. 写快照
      ftWriteSnapshot(floor, d);
      ftSaveData(d);

      ftState.autoCounter++;
      log(`[狐刻·推进] floor=${floor} 完成，时钟=${ftClockLabel(d.clock)}，due=${triggers.due.length} fired=${triggers.fired.length} expired=${triggers.expired.length}`);

      // 🎯 面板/悬浮窗若打开则立即刷新，避免"数据已更新但UI还显示旧时间"（用户反馈"解析出来时间还是14:15"和"不会同步到悬浮窗"）
      try {
        if (topDoc.getElementById('ft-panel')) ftRenderPanel();
      } catch (e) { log('[狐刻·推进] 面板刷新失败', e); }
      try {
        if (typeof ftTimelineRefresh === 'function') ftTimelineRefresh();
      } catch (e) { log('[狐刻·推进] 悬浮窗刷新失败', e); }

      return true;
    } catch (e) {
      log('[狐刻·推进] 失败', e);
      return false;
    } finally {
      ftState.running = false;
    }
  }

  // 🔧 狐刻不再动态注入提示词。旧 ssGetFoxTimeCurrentInjectText 生成 <timeline>
  //    块注入 <fox_extra>，即使模块关闭（cfg.enabled=false）仍因只判断 injectEnabled
  //    而继续注入。现已彻底删除，狐刻仅靠 ftSyncPromptEntry 开关预设条目实现功能。

  // ---- 开局建轴（两阶段：扫楼 -> 生成节点表 + 门闩）----
  async function ftBuildOpeningAxis() {
    const cfg = ftState.config || ftLoadConfig();
    ftState.running = true;
    try {
      const glmi = getFn('getLastMessageId');
      const lastId = glmi ? Number(glmi()) : -1;
      if (lastId < 0) { toast('⚠️ 狐刻建轴失败：无聊天记录', 'warning'); return false; }

      // 获取狐忆(事件+角色关系)和狐构(阶段+关系+事件)上下文
      const ctx = ftBuildContextInject();
      const memoryBlock = ctx.memoryText ? `\n【狐忆·事件与角色关系】\n${ctx.memoryText}\n` : '';
      const outlineBlock = ctx.outlineText ? `\n【狐构·阶段与关系】\n${ctx.outlineText}\n` : '';

      const headerPrompt = `你是剧情时间轴分析大师，你需要学习以下上下文来生成准确的剧情时间轴。`;
      const footerPrompt = `你是剧情时间轴分析大师，你已经读取完了全部上下文，请你现在根据聊天记录和上述上下文，生成：

1. 初始时钟（第几天、几点几分）
2. 关键数值（好感度等）
3. 关系阶段表（必须参考狐构的阶段和狐忆的角色关系，没有档案则不写）
4. 未来可能触发的剧情节点（至少3个，必须基于已有上下文，禁止胡编乱造）
   ⚠️ 重要：如果多个事件发生在同一个时间节点，必须合并为一个节点，在desc中包含所有事件内容，禁止拆成多个节点。

输出协议：
# TIME
DAY: <天数>
MINUTE: <分钟>
CONFIDENCE: <explicit|estimated>
# KV
<键>: <值>
# STAGE
<阶段ID>: <当前阶段>
# NODES
- id: node_1
  name: <节点名称>
  type: time|stage|kv
  trigger: <触发条件描述>
  desc: <节点描述>
  status: pending

现在，禁止写小说，禁止寒暄，立刻按要求开始输出：`;

      // 用 ssBuildFixedContextOrderedPrompts 注入完整上下文（角色卡+世界书+聊天记录等，和狐忆同款）
      const fixedContext = ssBuildFixedContextOrderedPrompts({
        ...ssNormalizeTagFilterSettings(cfg),
        contextFloors: cfg.contextFloors || 50,
      });

      const result = await ftGenerateRaw({
        ordered_prompts: [
          { role: 'system', content: '你是剧情时间轴分析大师，只按协议输出，禁止角色扮演。' },
          { role: 'user', content: headerPrompt },
          ...fixedContext,
          { role: 'system', content: (memoryBlock + outlineBlock).trim() },
          { role: 'user', content: footerPrompt },
        ],
        should_silence: true,
        should_stream: false,
        max_chat_history: 0,
      });

      if (!result) { toast('⚠️ 狐刻建轴失败：AI无返回', 'warning'); return false; }

      const parsed = ftParseAIResult(result);
      let d = ftState.data || ftLoadData();

      // 应用时钟
      if (parsed.clock) {
        const clampedClock = ftClockFromAbs(ftClockAbs(parsed.clock));
        d.clock = { ...d.clock, ...clampedClock, label: ftClockLabel(parsed.clock), confidence: parsed.clock.confidence || 'estimated', updatedFloor: lastId, unknown: false };
      }
      // 应用 KV
      for (const [k, v] of Object.entries(parsed.kv)) d.kv[k] = v;
      // 应用阶段
      for (const stage of parsed.stageSchemas) {
        const existing = (d.stageSchemas || []).find(s => s.id === stage.id);
        if (existing) existing.current = stage.current;
        else d.stageSchemas.push({ id: stage.id, current: stage.current, steps: [stage.current] });
      }

      // 解析 NODES 段
      const nodesMatch = result.match(/#\s*NODES\s*\n([\s\S]*?)(?=\n#\s|\n$|$)/i);
      if (nodesMatch) {
        const nodeBlocks = nodesMatch[1].split(/\n(?=-\s)/).filter(b => b.trim());
        for (const block of nodeBlocks) {
          const idM = block.match(/id\s*[:：]\s*(\S+)/i);
          const nameM = block.match(/name\s*[:：]\s*(.+)/i);
          const typeM = block.match(/type\s*[:：]\s*(\S+)/i);
          const descM = block.match(/desc\s*[:：]\s*(.+)/i);
          const absM = block.match(/abs\s*[:：]\s*(\d+)/i);
          const windowEndM = block.match(/window_end\s*[:：]\s*(\d+)/i);
          const stageIdM = block.match(/stage_id\s*[:：]\s*(\S+)/i);
          const minStepM = block.match(/min_step\s*[:：]\s*(.+)/i);
          const keyM = block.match(/key\s*[:：]\s*(\S+)/i);
          const opM = block.match(/op\s*[:：]\s*(\S+)/i);
          const valueM = block.match(/value\s*[:：]\s*(\d+)/i);
          if (idM) {
            const nodeType = typeM ? typeM[1].trim() : 'time';
            const trigger = { type: nodeType };
            if (nodeType === 'time' && absM) {
              trigger.abs = parseInt(absM[1]);
            } else if (nodeType === 'stage' && stageIdM) {
              trigger.stageId = stageIdM[1].trim();
              trigger.minStep = minStepM ? minStepM[1].trim() : '';
            } else if (nodeType === 'kv' && keyM) {
              trigger.key = keyM[1].trim();
              trigger.op = opM ? opM[1].trim() : '>=';
              trigger.value = valueM ? parseInt(valueM[1]) : 0;
            }
            const window = {};
            if (absM) window.earliestAbs = parseInt(absM[1]);
            if (windowEndM) window.latestAbs = parseInt(windowEndM[1]);
            d.nodes.push({
              id: idM[1].trim(),
              name: nameM ? nameM[1].trim() : idM[1].trim(),
              trigger,
              window,
              desc: descM ? descM[1].trim() : '',
              status: 'pending',
              source: 'opening',
              createdFloor: lastId,
              firedFloor: null,
            });
          }
        }
      }

      // 初始化空门闩表（后续由用户或 AI 填充）
      d.pwGates = d.pwGates || {};

      ftSaveData(d);
      ftWriteSnapshot(lastId, d);
      toast('✅ 狐刻建轴完成', 'success');
      log(`[狐刻·建轴] 完成：时钟=${ftClockLabel(d.clock)}，节点=${d.nodes.length}，阶段=${d.stageSchemas.length}`);
      return true;
    } catch (e) {
      log('[狐刻·建轴] 失败', e);
      toast(`❌ 狐刻建轴失败：${e?.message || e}`, 'error');
      return false;
    } finally {
      ftState.running = false;
    }
  }

  // ---- 静默修正（照抄 outlineCorrect 模式，走 xhEnqueueAutoTask）----
  async function ftCorrect(opts = {}) {
    const automatic = opts?.automatic === true;
    const cfg = ftState.config || ftLoadConfig();
    const backgroundSilent = automatic && cfg.silentCorrect;

    if (ftState.running || ssIsTaskRunning('fox_time')) {
      if (!automatic) toast('⚠️ 狐刻正在执行中', 'warning');
      return false;
    }

    let d = ftState.data || ftLoadData();
    const floor = getCurrentLastMessageId();
    if (floor < 0) return false;

    // 检查修正间隔
    const lastCorrect = Number(d.meta?.lastCorrectFloor) || 0;
    const isInitialized = !!d.meta?.initialized;
    // ✅ 修复 BUG：未初始化时强制执行初始化分析，跳过间隔检查。
    //    旧版无论是否初始化都走间隔检查，导致"打开模块后第一次分析被跳过"
    //    （用户反馈"连初始化都没有，修正什么？"）。
    //    清空数据后 meta.initialized=false，下次自动触发时也会强制初始化。
    if (automatic && isInitialized && floor - lastCorrect < cfg.correctInterval) {
      log(`[狐刻·修正] 跳过：未到间隔 floor=${floor} lastCorrect=${lastCorrect} interval=${cfg.correctInterval} 差值=${floor - lastCorrect}`);
      return false;
    }
    log(`[狐刻·修正] ${isInitialized ? '修正' : '初始化'}开始 floor=${floor} lastCorrect=${lastCorrect} interval=${cfg.correctInterval} initialized=${isInitialized}`);

    ftState.running = true;
    try {
      // 获取狐忆(事件+角色关系)和狐构(阶段+关系+事件)上下文
      const ctx = ftBuildContextInject();
      const memoryBlock = ctx.memoryText ? `\n【狐忆·事件与角色关系】\n${ctx.memoryText}\n` : '';
      const outlineBlock = ctx.outlineText ? `\n【狐构·阶段与关系】\n${ctx.outlineText}\n` : '';

      const headerPrompt = `你是剧情时间轴修正大师，你需要学习以下上下文来修正当前时间轴状态。`;
      const footerPrompt = `你是剧情时间轴修正大师，你已经读取完了全部上下文，请你现在根据最近正文和上述上下文，修正当前时间轴状态。

注意：只能根据已有上下文和正文修正，禁止胡编乱造。没有档案的内容不要写。

请输出修正后的状态（按协议）：
# TIME
DAY: <天数>
MINUTE: <分钟>
CONFIDENCE: <explicit|estimated>
# KV
<键>: <值>
# STAGE
<阶段ID>: <当前阶段>
# TRIGGER
FIRED: <已触发节点ID或none>

现在，禁止写小说，禁止寒暄，立刻按要求开始输出：`;

      const currentStateBlock = `【当前状态】\n时钟：${ftClockLabel(d.clock)}（绝对时间 ${ftClockAbs(d.clock)} 分钟）\nKV：${JSON.stringify(d.kv || {})}\n阶段：${JSON.stringify(d.stageSchemas || [])}`;

      // 用 ssBuildFixedContextOrderedPrompts 注入完整上下文（角色卡+世界书+聊天记录等，和狐忆同款）
      const fixedContext = ssBuildFixedContextOrderedPrompts({
        ...ssNormalizeTagFilterSettings(cfg),
        contextFloors: cfg.contextFloors || 50,
      });

      const result = await ftGenerateRaw({
        ordered_prompts: [
          { role: 'system', content: '你是剧情时间轴修正大师，只按协议输出，禁止角色扮演。' },
          { role: 'user', content: headerPrompt },
          ...fixedContext,
          { role: 'system', content: (memoryBlock + outlineBlock).trim() },
          { role: 'system', content: currentStateBlock },
          { role: 'user', content: footerPrompt },
        ],
        should_silence: backgroundSilent,
        should_stream: false,
        max_chat_history: 0,
      });

      if (!result) return false;

      const parsed = ftParseAIResult(result);
      const oldAbs = ftClockAbs(d.clock);

      if (parsed.clock) {
        const newAbs = ftClockAbs(parsed.clock);
        const clampedAbs = ftClampClockForward(oldAbs, newAbs);
        const clampedClock = ftClockFromAbs(clampedAbs);
        d.clock = { ...d.clock, ...clampedClock, label: ftClockLabel(clampedClock), confidence: parsed.clock.confidence || 'estimated', updatedFloor: floor, unknown: false };
      }
      for (const [k, v] of Object.entries(parsed.kv)) d.kv[k] = v;
      for (const stage of parsed.stageSchemas) {
        const existing = (d.stageSchemas || []).find(s => s.id === stage.id);
        if (existing) existing.current = stage.current;
        else d.stageSchemas.push({ id: stage.id, current: stage.current, steps: [stage.current] });
      }
      for (const nodeId of parsed.triggers) {
        const node = (d.nodes || []).find(n => n.id === nodeId);
        if (node) { node.aiFired = true; node.status = 'fired'; node.firedFloor = floor; }
      }

      // 触发判定
      const triggers = ftEvaluateTriggers(d);
      for (const nodeId of triggers.fired) {
        const node = (d.nodes || []).find(n => n.id === nodeId);
        if (node) { node.status = 'fired'; node.firedFloor = floor; }
      }
      for (const nodeId of triggers.expired) {
        const node = (d.nodes || []).find(n => n.id === nodeId);
        if (node) { node.status = 'expired'; node.expiredFloor = floor; }
      }

      d.meta = d.meta || {};
      d.meta.lastCorrectFloor = floor;
      // ✅ 标记已初始化，后续才走正常的间隔修正逻辑
      d.meta.initialized = true;
      ftSaveData(d);
      ftWriteSnapshot(floor, d);
      log(`[狐刻·修正] 完成 floor=${floor}，时钟=${ftClockLabel(d.clock)}，initialized=true`);

      // 🎯 修正完成后也刷新面板/悬浮窗
      try { if (topDoc.getElementById('ft-panel')) ftRenderPanel(); } catch (e) { log('[狐刻·修正] 面板刷新失败', e); }
      try { if (typeof ftTimelineRefresh === 'function') ftTimelineRefresh(); } catch (e) { log('[狐刻·修正] 悬浮窗刷新失败', e); }

      if (!backgroundSilent) toast('✅ 狐刻静默修正完成', 'success');
      return true;
    } catch (e) {
      log('[狐刻·修正] 失败', e);
      if (!backgroundSilent) toast(`❌ 狐刻修正失败：${e?.message || e}`, 'error');
      return false;
    } finally {
      ftState.running = false;
    }
  }

  // ---- 自动监听器（照抄 pwShouldAutoAdvance / pwRegisterAutoListener）----
  function ftShouldAdvance(messageId, type) {
    if (ftState.internalGenerating) return false;
    if (ftState.running || ssIsTaskRunning('fox_time')) return false;

    // effType（normal 才过，回退 xhGetLastGenerationType）
    const effType = (type && typeof type === 'string')
      ? type
      : (xhGetLastGenerationType() || null);
    if (effType && effType !== 'normal') {
      log(`[狐刻·自动推进] 跳过：非 normal 回复 type=${effType}`);
      return false;
    }

    // 排除截断
    if (typeof pwIsTruncatedMessage === 'function' && pwIsTruncatedMessage(messageId)) {
      log('[狐刻·自动推进] 跳过：检测到截断');
      return false;
    }

    // 排除空回复
    const gcm = getFn('getChatMessages');
    if (gcm) {
      const m = gcm(messageId, { hide_state: 'all', include_swipes: true })?.[0];
      if (!m || m.role !== 'assistant') return false;
      const { text } = xhGetAssistantMessageText(m);
      const cleanText = text.replace(/<[^>]+>/g, '').replace(/\s+/g, '').trim();
      if (!cleanText) {
        log(`[狐刻·自动推进] 跳过：空回复 message_id=${messageId}`);
        return false;
      }
    }

    return true;
  }

  function ftRegisterAutoListener() {
    ftUnregisterAutoListener();
    const cfg = ftState.config || ftLoadConfig();
    if (!cfg.enabled) return;

    const eo = getFn('eventOn');
    const te = getFn('tavern_events') || (typeof tavern_events !== 'undefined' ? tavern_events : null);

    if (typeof eo !== 'function' || !te?.MESSAGE_RECEIVED) {
      log('[狐刻·自动推进] 注册失败：缺少 MESSAGE_RECEIVED');
      return;
    }

    if (te.GENERATION_STARTED) {
      ftState.genTypeHandle = eo(te.GENERATION_STARTED, (type, _option, dryRun) => {
        if (dryRun) return;
        if (['swipe', 'regenerate', 'reroll'].includes(String(type || '').toLowerCase())) {
          ftState.branchEpoch++;
        }
      });
    }

    ftState.autoHandle = eo(te.MESSAGE_RECEIVED, (eventMessageId, type) => {
      ftState.config = ftLoadConfig();
      if (!ftState.config.enabled) return;

      if (xhIsInternalMessageEvent(type)) {
        log(`[狐刻·自动推进] 跳过：内部生成事件 message_id=${eventMessageId} type=${type || 'unknown'}`);
        return;
      }

      const messageId = Number(eventMessageId);
      if (!Number.isFinite(messageId)) return;

      if (!ftShouldAdvance(messageId, type)) return;

      // 📊 楼层推进诊断日志：打印本楼被认为是主AI回复的楼层内容及前300字
      //    用于排查"隔N楼修正"是否计算到了正确的楼层
      try {
        const __gcm = getFn('getChatMessages');
        let __preview = '';
        if (__gcm) {
          const __m = __gcm(messageId, { hide_state: 'all', include_swipes: true })?.[0];
          if (__m) {
            const { text } = xhGetAssistantMessageText(__m);
            __preview = text.replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim().slice(0, 300);
          }
        }
        log(`[狐刻·楼层推进] 检测到主AI回复楼层 message_id=${messageId}，内容前300字：${__preview}`);
      } catch (e) { log('[狐刻·楼层推进] 日志打印失败', e); }

      // 入队执行推进（静默，成功后弹提示）
      xhEnqueueAutoTask('fox_time_advance', '狐刻楼层推进', async () => {
        const ok = await ftAdvanceFloor(messageId);
        if (ok) toast('🕰️ 时间轴已自动推进', 'info');
      }, { dedupe: true });

      // 静默修正（成功后弹提示）
      if (ftState.config.silentCorrect) {
        xhEnqueueAutoTask('fox_time_correct', '狐刻静默修正', async () => {
          const ok = await ftCorrect({ automatic: true });
          if (ok) toast('🕰️ 时间轴已静默修正', 'info');
        }, { dedupe: true });
      }
    });

    log('[狐刻·自动推进] 已注册');
  }

  function ftUnregisterAutoListener() {
    ssStopEventHandle(ftState.autoHandle);
    ssStopEventHandle(ftState.genTypeHandle);
    ssStopEventHandle(ftState.mvuHandle);
    ftState.autoHandle = null;
    ftState.genTypeHandle = null;
    ftState.mvuHandle = null;
    log('[狐刻·自动推进] 已注销');
  }

  // ---- 门闩（给平行世界用，剔除未到时间的模块）----
  function ftGateFilterModules(moduleIds) {
    const cfg = ftState.config || ftLoadConfig();
    if (!cfg.pwGate) return moduleIds;

    const d = ftState.data || ftLoadData();
    if (!d) return moduleIds;
    const clockAbs = ftClockAbs(d.clock);

    const filtered = [];
    const blocked = [];
    for (const modId of (Array.isArray(moduleIds) ? moduleIds : [])) {
      const gate = d.pwGates?.[modId];
      if (!gate) { filtered.push(modId); continue; }

      let blockedReason = null;
      // 时间门闩：notBeforeAbs > clock.absolute
      if (gate.notBeforeAbs && Number(gate.notBeforeAbs) > clockAbs) {
        blockedReason = `时间未到（${ftClockLabel(ftClockFromAbs(gate.notBeforeAbs))}）`;
      }
      // 阶段门闩：notBeforeStage 的阶段未达
      if (!blockedReason && gate.notBeforeStage) {
        const parts = String(gate.notBeforeStage).split(/[.:：]/);
        const stageId = parts[0]?.trim();
        const minStep = parts[1]?.trim();
        const schema = (d.stageSchemas || []).find(s => s.id === stageId);
        if (schema && minStep) {
          const stepIndex = (schema.steps || []).indexOf(schema.current);
          const minIndex = (schema.steps || []).indexOf(minStep);
          if (stepIndex >= 0 && minIndex >= 0 && stepIndex < minIndex) {
            blockedReason = `阶段未达（${stageId}: ${schema.current} < ${minStep}）`;
          }
        }
      }

      if (blockedReason) {
        blocked.push({ id: modId, reason: blockedReason });
      } else {
        filtered.push(modId);
      }
    }

    if (blocked.length) {
      log(`[狐刻·门闩] 已拦截 ${blocked.length} 个模块：${blocked.map(b => `${b.id}(${b.reason})`).join(', ')}`);
    }
    return filtered;
  }

  // ---- 软约束提示词（供平行世界三个 AI 入口注入）----
  function ftGetPwSoftConstraintText() {
    const cfg = ftState.config || ftLoadConfig();
    if (!cfg.pwGate) return '';

    const d = ftState.data || ftLoadData();
    if (!d) return '';

    const clockLabel = ftClockLabel(d.clock);
    const parts = [];
    parts.push(`【狐刻·时间约束】当前剧情时间：${clockLabel}。所有生成内容必须在此时间点之后，禁止时间倒流。`);

    // 门闩信息
    const gates = Object.entries(d.pwGates || {});
    if (gates.length) {
      const activeGates = gates.map(([id, g]) => {
        if (g.notBeforeAbs) return `${id}: ${ftClockLabel(ftClockFromAbs(g.notBeforeAbs))}后解锁`;
        if (g.notBeforeStage) return `${id}: ${g.notBeforeStage}后解锁`;
        return null;
      }).filter(Boolean);
      if (activeGates.length) parts.push(`【狐刻·门闩】\n${activeGates.map(g => `  ${g}`).join('\n')}`);
    }

    // 强制触发节点
    const triggers = ftEvaluateTriggers(d);
    if (triggers.due.length) {
      parts.push(`【狐刻·禁令】以下节点已到触发时间，本轮必须开启，禁止推迟：${triggers.due.join(', ')}`);
    }

    return parts.join('\n');
  }

  // ---- 狐忆联动 ----
  function ftGetClockForFloor(floor) {
    try {
      const d = ftState.data || ftLoadData();
      const f = Math.max(0, Number(floor) || 0);
      const snaps = d.snapshots || {};
      // 从快照查：找 ≤ floor 的最新快照
      const candidates = Object.values(snaps)
        .filter(s => s && typeof s === 'object' && Number(s.floor) <= f)
        .sort((a, b) => Number(b.floor) - Number(a.floor));
      if (candidates.length) {
        const snap = candidates[0];
        return snap.data?.clock || d.clock || FT.DEFAULT_DATA.clock;
      }
      return d.clock || FT.DEFAULT_DATA.clock;
    } catch { return FT.DEFAULT_DATA.clock; }
  }

  function ftAnnotateFoxMemory(memories) {
    // 给狐忆条目追加 plotTime 字段
    if (!Array.isArray(memories)) return memories;
    for (const mem of memories) {
      if (!mem || typeof mem !== 'object') continue;
      const floor = Number(mem.floor ?? mem.messageId ?? 0);
      if (Number.isFinite(floor) && floor >= 0) {
        const clock = ftGetClockForFloor(floor);
        mem.plotTime = ftClockLabel(clock);
      }
    }
    return memories;
  }

  // ---- 清空（只清狐刻命名空间）----
  function ftClearData() {
    try {
      const key = getFoxTimeStorageKey();
      localStorage.removeItem(key);
      ftState.data = JSON.parse(JSON.stringify(FT.DEFAULT_DATA));
      ftState.data.meta.createdAt = Date.now();
      // ✅ 显式重置 initialized=false，确保清空后下次自动触发时走初始化而非间隔修正
      ftState.data.meta.initialized = false;
      ftSaveData(ftState.data);
      ftState.autoCounter = 0;
      ftState.lastCorrectFloor = 0;
      log('[狐刻·清空] 已清除当前作用域狐刻数据，initialized 已重置为 false');
      toast('✅ 狐刻数据已清空', 'success');
      return true;
    } catch (e) {
      log('[狐刻·清空] 失败', e);
      return false;
    }
  }

  // ---- 面板 ----
  // 🦊 层级规范：与全脚本模块面板统一（overlay=1000002 / panel=1000003），
  //    必须高于主悬浮窗 #ss-dashboard(999999) / #ss-dash-overlay(999998)，
  //    否则从悬浮窗内打开时面板会被压在主窗之下（历史 bug：z-index 39998）。
