  function ftOpenPanel() {
    ftClosePanel();
    ftRenderPanel();
  }

  function ftClosePanel() {
    try { topDoc.getElementById('ft-panel-overlay')?.remove(); } catch { }
    try { topDoc.getElementById('ft-panel')?.remove(); } catch { }
  }

  // 节点状态徽章（暖色系，与全局 Ember 配色一致）
