    fired: { label: '已触发', color: '#7fc98f', bg: 'rgba(127,201,143,.12)', border: 'rgba(127,201,143,.35)' },
    expired: { label: '已过期', color: '#8a7f76', bg: 'rgba(138,127,118,.12)', border: 'rgba(138,127,118,.3)' },
    cancelled: { label: '已取消', color: '#8a7f76', bg: 'rgba(138,127,118,.12)', border: 'rgba(138,127,118,.3)' },
