    const panel = topDoc.createElement('div');
    panel.id = 'ft-panel';
    panel.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);width:min(960px,96vw);height:min(700px,94vh);overflow:hidden;background:linear-gradient(150deg,rgba(30,24,20,.97),rgba(15,12,10,.98));border:1px solid rgba(232,120,74,.22);border-radius:18px;padding:0;z-index:1000003;color:#e8ddd4;font-size:13px;box-shadow:0 30px 80px rgba(0,0,0,.7),0 0 60px rgba(232,120,74,.06);box-sizing:border-box;-webkit-overflow-scrolling:touch;display:flex;flex-direction:column;';
    // 手机端：全屏
    if (topWindow.innerWidth <= 720) {
      panel.style.top = '0'; panel.style.left = '0'; panel.style.transform = 'none';
      panel.style.width = '100vw'; panel.style.height = '100dvh'; panel.style.borderRadius = '0'; panel.style.border = '0';
    }

    const clock = d.clock || FT.DEFAULT_DATA.clock;
    const nodes = Array.isArray(d.nodes) ? d.nodes : [];
    const stages = Array.isArray(d.stageSchemas) ? d.stageSchemas : [];
    const kv = d.kv || {};

    // 动态数据统一转义，防止 AI 生成内容破坏面板结构
    const esc = typeof escapeHtml === 'function'
      ? escapeHtml
      : s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

    const stageRows = stages.map(s => `<tr><td>${esc(s.id || s.name)}</td><td style="color:#a09088">${esc((s.steps || []).join(' < ') || '-')}</td><td><span class="ft-chip" style="color:#f0a070;background:rgba(232,120,74,.1);border:1px solid rgba(232,120,74,.3)">${esc(s.steps?.[s.current] ?? s.current ?? '-')}</span></td></tr>`).join('') || '<tr><td colspan="3" class="ft-empty">暂无阶段表（开局建轴时AI生成）</td></tr>';

    const nodeRows = nodes.map((n, i) => {
      const meta = FT_STATUS_META[n.status] || { label: n.status || '-', color: '#a09088', bg: 'rgba(160,144,136,.1)', border: 'rgba(160,144,136,.3)' };
