    }).join('') || '<tr><td colspan="4" class="ft-empty">暂无节点</td></tr>';

    const kvRows = Object.entries(kv).slice(0, 30).map(([k, v]) => `<tr><td>${esc(k)}</td><td style="color:#f0a070">${esc(v?.value ?? v ?? '-')}</td><td style="color:#706058">${esc(v?.source || '-')}</td></tr>`).join('') || '<tr><td colspan="3" class="ft-empty">暂无数值</td></tr>';

    const dueCount = nodes.filter(n => n.status === 'due').length;
    const firedCount = nodes.filter(n => n.status === 'fired').length;

    panel.innerHTML = `
