                <label>&nbsp;<button id="ft-fetch-models" class="ft-btn ft-btn-ghost" style="width:100%;font-size:11px;padding:6px 10px;">${ftState.loadingModels ? '加载中…' : '获取模型列表'}</button></label>
                <label>温度<input data-cfg="customApi.temperature" type="text" value="${esc(c.customApi?.temperature||'')}" placeholder="留空=默认"></label>
