    overlay.addEventListener('click', ftClosePanel);
    panel.querySelector('[data-close]')?.addEventListener('click', ftClosePanel);

    // 📌 tab 切换（带 paneOut/paneIn 过渡动画）
    let ftTabSwitching = false;
    const ftSwitchTab = (tabKey, setCurItem) => {
      if (ftTabSwitching) return;
      const curPane = panel.querySelector('.ft-pane.active');
      if (curPane && curPane.dataset.pane === tabKey) return;
      ftTabSwitching = true;
      if (setCurItem) setCurItem();
      if (curPane) {
        curPane.classList.add('leaving');
        setTimeout(() => {
          curPane.classList.remove('active', 'leaving');
          const target = panel.querySelector(`.ft-pane[data-pane="${tabKey}"]`);
          if (target) target.classList.add('active');
          ftTabSwitching = false;
        }, 170);
      } else { ftTabSwitching = false; }
    };
    panel.querySelectorAll('.ft-mitem[data-tab]').forEach(it => {
      it.addEventListener('click', () => {
        ftSwitchTab(it.dataset.tab, () => {
          panel.querySelectorAll('.ft-mitem').forEach(x => x.classList.remove('cur'));
          it.classList.add('cur');
        });
      });
    });
    // 📌 移动端底栏切换（照抄狐刻 ftTabSwitching 模式）
    panel.querySelectorAll('.ft-mb-dock-item[data-mbtab]').forEach(it => {
      it.addEventListener('click', () => {
        ftSwitchTab(it.dataset.mbtab, () => {
          panel.querySelectorAll('.ft-mb-dock-item').forEach(x => x.classList.remove('cur'));
          it.classList.add('cur');
        });
      });
    });

