      const cfg = ftState.config || ftLoadConfig();
      cfg.enabled = !cfg.enabled;
      ftSaveConfig(cfg); ftState.config = cfg;
      this.classList.toggle('on', cfg.enabled);
      const pill = panel.querySelector('.ft-pill');
      if (pill) { pill.className = `ft-pill ${cfg.enabled ? 'on' : 'off'}`; pill.textContent = cfg.enabled ? '运行中' : '未启用'; }
      try { ftRegisterAutoListener(); } catch {}
      toast(cfg.enabled ? '🕰️ 狐刻已启用' : '🕰️ 狐刻已关闭', cfg.enabled ? 'success' : 'info');
    });

