        ev.preventDefault(); ev.stopPropagation();
        ftTimelineToggle();
        this.textContent = ftTL.el ? '📌 悬浮窗 ✓' : '📌 悬浮窗';
        // 同步移动端底栏悬浮窗按钮状态
        const mbBtn = panel.querySelector('#ft-mb-tl-toggle');
        if (mbBtn) mbBtn.classList.toggle('cur', !!ftTL.el);
      });
    }

    // 📌 移动端底栏"悬浮窗"按钮：与顶栏按钮功能一致
    const mbTlToggleBtn = panel.querySelector('#ft-mb-tl-toggle');
    if (mbTlToggleBtn) {
      mbTlToggleBtn.classList.toggle('cur', !!ftTL.el);
      mbTlToggleBtn.addEventListener('click', function (ev) {
        ev.preventDefault(); ev.stopPropagation();
        ftTimelineToggle();
        this.classList.toggle('cur', !!ftTL.el);
        // 同步顶栏按钮文案
        if (tlToggleBtn) tlToggleBtn.textContent = ftTL.el ? '📌 悬浮窗 ✓' : '📌 悬浮窗';
        try { toast(ftTL.el ? '📌 悬浮窗已开启' : '📌 悬浮窗已关闭', 'info'); } catch {}
      });
    }

    // 🌐 选择"自定义"API 时自动弹出配置面板（与其他模块交互一致）
    panel.querySelector('[data-cfg="apiType"]')?.addEventListener('change', function () {
      const show = this.value === 'custom';
      const wrap = panel.querySelector('#ft-custom-api-wrap');
      const det = panel.querySelector('#ft-custom-api-details');
      if (wrap) wrap.style.display = show ? 'block' : 'none';
      if (show && det) {
        det.open = true;
        try { det.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); } catch {}
      }
    });

    // 📌 配置自动保存（不需要点保存按钮）
    const ftAutoSaveCfg = () => {
      const cfg = ftState.config || ftLoadConfig();
      panel.querySelectorAll('[data-cfg]').forEach(el => {
        const key = el.dataset.cfg;
        if (key.startsWith('customApi.')) {
          if (!cfg.customApi) cfg.customApi = {};
          cfg.customApi[key.slice('customApi.'.length)] = el.value;
          return;
        }
        if (el.type === 'checkbox') cfg[key] = el.checked;
        else if (el.type === 'number') cfg[key] = Number(el.value) || 0;
        else cfg[key] = el.value;
      });
      cfg.enableContentFilter = panel.querySelector('#ft-content-filter')?.checked !== false;
      cfg.includeTagPairs = ssReadTagPairsEditor('ft-inc', panel);
      cfg.excludeTagPairs = ssReadTagPairsEditor('ft-exc', panel);
      const ep = ssReadExtraParamsFromPanel('ft', panel);
      if (ep) {
        cfg.customApi = { ...cfg.customApi, ...ep };
      }
      ftSaveConfig(cfg);
      ftState.config = cfg;
    };
    panel.querySelectorAll('[data-cfg]').forEach(el => el.addEventListener('change', ftAutoSaveCfg));
    panel.querySelector('#ft-content-filter')?.addEventListener('change', ftAutoSaveCfg);
    panel.querySelectorAll('[id^="ft-inc-"], [id^="ft-exc-"]').forEach(el => el.addEventListener('change', ftAutoSaveCfg));
    ['ft-extra-body-yaml', 'ft-exclude-body-yaml', 'ft-extra-headers-yaml'].forEach(id => {
      const el = panel.querySelector(`#${id}`);
      if (el) { el.addEventListener('input', ftAutoSaveCfg); el.addEventListener('change', ftAutoSaveCfg); }
    });
    ssAttachCustomApiPresetControls('ft', {
      readValues: () => {
        const cfg = ftState.config || ftLoadConfig();
        const ca = cfg.customApi || {};
        return {
          apiurl: ca.apiurl || '',
          key: ca.key || '',
          model: ca.model || '',
          proxyPreset: ca.proxyPreset || '',
          temperature: ca.temperature ?? '',
          max_tokens: ca.max_tokens ?? '',
          top_p: ca.top_p ?? '',
          frequency_penalty: ca.frequency_penalty ?? '',
          presence_penalty: ca.presence_penalty ?? '',
        };
      },
      applyValues: (item) => {
        const setCfg = (key, val) => {
          const el = panel.querySelector(`[data-cfg="customApi.${key}"]`);
          if (el) { el.value = val || ''; el.dispatchEvent(new Event('change', { bubbles: true })); }
        };
        setCfg('proxyPreset', item.proxyPreset);
        setCfg('apiurl', item.apiurl);
        setCfg('key', item.key);
        setCfg('model', item.model);
        setCfg('temperature', item.temperature);
        setCfg('max_tokens', item.max_tokens);
        setCfg('top_p', item.top_p);
        setCfg('frequency_penalty', item.frequency_penalty);
        setCfg('presence_penalty', item.presence_penalty);
      },
      onApply: () => {
        const apiSel = panel.querySelector('[data-cfg="apiType"]');
        if (apiSel) apiSel.value = 'custom';
        const wrap = panel.querySelector('#ft-custom-api-wrap');
        const det = panel.querySelector('#ft-custom-api-details');
        if (wrap) wrap.style.display = 'block';
        if (det) det.open = true;
      },
    });

    // 🦊 模型列表选择 -> 填入模型输入框
    const ftModelSel = panel.querySelector('#ft-api-model-select');
    const ftModelInp = panel.querySelector('[data-cfg="customApi.model"]');
    if (ftModelSel && ftModelInp) {
      ftModelSel.onchange = () => { if (ftModelSel.value) { ftModelInp.value = ftModelSel.value; ftModelInp.dispatchEvent(new Event('change', { bubbles: true })); } };
    }

    // 🦊 获取模型列表按钮（照抄狐忆 foxmem-fetch-models 模式）
    const ftFetchBtn = panel.querySelector('#ft-fetch-models');
    if (ftFetchBtn) {
      ftFetchBtn.onclick = async () => {
        const cfg = ftState.config || ftLoadConfig();
        const ca = cfg.customApi || {};
        let apiurl = '', key = '';
        if (ca.proxyPreset) {
          try {
            const p = getPreset(ca.proxyPreset);
            apiurl = p?.settings?.apiurl || '';
            key = p?.settings?.key || '';
          } catch (e) { toast('读取预设失败', 'error'); return; }
        } else {
          apiurl = (ca.apiurl || '').trim();
          key = (ca.key || '').trim();
        }
        if (!apiurl) { toast('请先填写 API 地址或选择代理预设', 'warning'); return; }
        ftState.loadingModels = true;
        ftFetchBtn.textContent = '加载中…';
        ftFetchBtn.disabled = true;
        try {
          const getModelList = getFn('getModelList');
          let models = [];
          if (typeof getModelList === 'function') {
            models = await getModelList({ apiurl: apiurl.replace(/\/+$/, ''), key });
          } else {
            const headers = SillyTavern?.getRequestHeaders?.() || {};
            const resp = await fetch('/api/backends/chat-completions/status', {
              method: 'POST', headers,
              body: JSON.stringify({ reverse_proxy: apiurl, proxy_password: key, chat_completion_source: 'openai' })
            });
            const json = await resp.json();
            models = (json?.data || []).map(x => String(x?.id ?? '').trim()).filter(Boolean);
          }
          ftState.models = [...new Set(models)].sort();
          const sel = panel.querySelector('#ft-api-model-select');
          if (sel) sel.innerHTML = '<option value="">（从列表选择）</option>' + ftState.models.map(m => `<option value="${esc(m)}">${esc(m)}</option>`).join('');
          toast(ftState.models.length ? `已获取 ${ftState.models.length} 个模型` : '模型列表为空', ftState.models.length ? 'success' : 'warning');
        } catch (e) { toast(`获取失败：${e.message}`, 'error'); } finally {
          ftState.loadingModels = false;
          ftFetchBtn.textContent = '获取模型列表';
          ftFetchBtn.disabled = false;
        }
      };
    }

    // 🦊 挂载狐刻提示词自定义编辑器到配置页
    try {
      const ftCfgPane = panel.querySelector('[data-pane="config"]');
      if (ftCfgPane) {
        // 先触发一次构建以注册默认值
        if (typeof ftBuildParsePrompt === 'function') {
          try { ftBuildParsePrompt('', { clock: {}, kv: {}, stageSchemas: [], nodes: [] }); } catch {}
        }
        xhMountPromptEditor(ftCfgPane, 'fox_time', '狐刻时间轴解析');
      }
    } catch (e) { log('[狐刻] 挂载提示词编辑器失败', e); }

    const setStatus = (msg, isError) => {
      const el = panel.querySelector('#ft-status-msg');
      if (el) { el.textContent = msg || ''; el.classList.toggle('err', !!isError); }
    };

    // 🕰️ 带中断按钮的toast（分析进行中可点击中断），返回清除函数
    const ftCancelableToast = (msg) => {
      const t = topWindow?.toastr || window.toastr;
      if (!t?.info) { toast(msg, 'info'); return () => {}; }
      const html = `${msg}<br><button class="ss-toast-cancel" data-task="fox_time" style="margin-top:8px;padding:4px 10px;border:1px solid rgba(232,120,74,0.35);border-radius:6px;background:rgba(139,0,0,0.22);color:#ffd0c0;cursor:pointer;pointer-events:auto;position:relative;z-index:1;">⛔ 中断</button>`;
      const $t = t.info(html, '🦊玄狐', { timeOut: 0, extendedTimeOut: 0, closeButton: true, tapToDismiss: false, preventDuplicates: false, escapeHtml: false, toastClass: 'toast xh-toast xh-toast--info' });
      try {
        const el = $t?.nodeType ? $t : ($t?.[0] || $t?.get?.(0));
        if (el) {
          const btn = el.querySelector?.('.ss-toast-cancel');
          if (btn && !btn.__ssBound) {
            btn.__ssBound = true;
            btn.addEventListener('click', (ev) => {
              ev.preventDefault(); ev.stopPropagation();
              try { ssCancelTask('fox_time', '用户手动中断'); } catch {}
              try { t.clear($t); } catch {}
            });
          }
        }
      } catch {}
      return () => { try { t.clear($t); } catch {} };
    };

    panel.addEventListener('click', async e => {
      const btn = e.target.closest('[data-act]');
      if (!btn) return;
      const act = btn.dataset.act;

      if (act === 'refresh') { ftOpenPanel(); return; }
      if (act === 'clear') {
        if (topWindow.confirm('确定清空当前聊天的狐刻数据？')) { ftClearData(); ftOpenPanel(); }
        return;
      }
      if (act === 'savecfg') {
        try {
          const cfg = ftState.config || ftLoadConfig();
          panel.querySelectorAll('[data-cfg]').forEach(el => {
            const key = el.dataset.cfg;
            // 🌐 支持嵌套键 customApi.xxx（自定义API配置）
            if (key.startsWith('customApi.')) {
              if (!cfg.customApi) cfg.customApi = {};
              cfg.customApi[key.slice('customApi.'.length)] = el.value;
              return;
            }
            if (el.type === 'checkbox') cfg[key] = el.checked;
            else if (el.type === 'number') cfg[key] = Number(el.value) || 0;
            else cfg[key] = el.value;
          });
          // 🏷️ 读取标签过滤设置
          cfg.enableContentFilter = panel.querySelector('#ft-content-filter')?.checked !== false;
          cfg.includeTagPairs = ssReadTagPairsEditor('ft-inc', panel);
          cfg.excludeTagPairs = ssReadTagPairsEditor('ft-exc', panel);
          ftSaveConfig(cfg); ftState.config = cfg;
          toast('✅ 狐刻配置已保存', 'success');
          setStatus('配置已保存');
        } catch (err) { log('[狐刻] 保存配置失败', err); toast('❌ 保存失败', 'error'); }
        return;
      }

      // 异步操作：不关闭面板，显示状态
      // 🦊 抢请求加固：狐刻手动建轴/解析/修正前等待其他模块/自动任务/主模型流式输出结束，避免并发 generateRaw。
      await ssWaitForManualIdle('fox_time');
      btn.disabled = true; btn.style.opacity = '0.5';
      try {
        if (act === 'build') {
          setStatus('正在建立时间轴……'); const clearT = ftCancelableToast('🕰️ 正在建立时间轴……');
          await ftBuildOpeningAxis();
          clearT(); setStatus('建轴完成'); toast('✅ 时间轴建立完成', 'success');
        } else if (act === 'parse') {
          const fid = getCurrentLastMessageId();
          if (fid < 0) { setStatus('无有效楼层', true); return; }
          setStatus('正在解析……'); const clearT = ftCancelableToast('🕰️ 正在解析……');
          await ftAdvanceFloor(fid);
          clearT(); setStatus('解析完成'); toast('✅ 解析完成', 'success');
        } else if (act === 'correct') {
          setStatus('正在修正……'); const clearT = ftCancelableToast('🕰️ 正在修正……');
          await ftCorrect({ automatic: false });
          clearT(); setStatus('修正完成'); toast('✅ 修正完成', 'success');
        }
        // 操作完成后刷新悬浮时间轴（不弹主面板，仅toast已提示）
        try { ftTimelineRefresh(); } catch { }
      } catch (err) {
        log('[狐刻] 面板操作失败', err);
        setStatus(`失败：${err?.message || err}`, true);
        toast(`❌ 操作失败：${err?.message || err}`, 'error');
      } finally {
        btn.disabled = false; btn.style.opacity = '';
      }
    });

    // 📱 手机端 viewport 适配
    try {
      const vv = topWindow.visualViewport;
      if (vv) {
        const onResize = () => {
          panel.style.maxHeight = `${(vv.height || topWindow.innerHeight) - 16}px`;
        };
        vv.addEventListener('resize', onResize);
        onResize();
      }
    } catch { }
  }

  // ==================== 📌 狐刻悬浮时间轴（固定屏幕底部悬浮窗） ====================
  // 独立挂载到 body，position:fixed 吸附屏幕底部，显示层级低于狐忆/平行世界各面板，
  // 不受底栏 #xh-dock 展开/收起/隐藏影响。
  // 丝滑动画：rAF节流 + transform位移 + will-change GPU加速 + 统一 cubic-bezier 缓动。
  const ftTL = {
    el: null, body: null, track: null, tip: null, nowEl: null, pastEl: null,
    spanLb: null, resetBtn: null, edgeL: null, edgeR: null, nowLb: null,
    span: 4320, viewStart: 0, fmtMode: 'h24', tipPinned: false, leaveTimer: null,
    IS_TOUCH: false, pts: new Map(), pinch: null, pan: null, panMoved: false,
    _inited: false, _raf: 0, _curEvs: [],
    SPAN_MIN: 120, SPAN_MAX: 64800,
    TICK_STEPS: [60,120,240,360,720,1440,4320,10080,21600],
    ST_OFFSET: { due: 0, fired: -240, pending: 1440, expired: -2880, cancelled: -2880, stage: 0 },
  };

  function ftTimelineToggle() {
    if (ftTL.el) {
      try { localStorage.setItem('ft-tl-closed', '1'); } catch {}
      ftTimelineUnmount();
    } else {
      ftTimelineMount();
    }
  }

  function ftTimelineMount() {
    if (ftTL.el) return;
    // 照搬 #xh-dock 的重试逻辑：等待 #send_textarea 就绪后再注入
    const ta = topDoc.getElementById('send_textarea');
    if (!ta) {
      if (!ftTL._mountRetry && (ftTL._mountRetryCount || 0) < 30) {
        ftTL._mountRetryCount = (ftTL._mountRetryCount || 0) + 1;
        ftTL._mountRetry = setTimeout(() => { ftTL._mountRetry = null; ftTimelineMount(); }, 600);
      }
      return;
    }
    if (ftTL._mountRetry) { clearTimeout(ftTL._mountRetry); ftTL._mountRetry = null; }
    ftTL._mountRetryCount = 0;
    if (!topDoc.getElementById('ft-tl-css')) {
      const sty = topDoc.createElement('style');
      sty.id = 'ft-tl-css';
      sty.textContent = `
