#ft-tl.open #fx-now{top:25px}
#ft-tl.open #fx-now .nd{width:13px;height:13px}
#fx-now .ring{position:absolute;left:0;top:0;width:10px;height:10px;border-radius:50%;border:1.5px solid rgba(240,160,112,.7);transform:translate(-50%,-50%);animation:nowRing 2.2s ease-out infinite;pointer-events:none}
@keyframes nowRing{0%{width:10px;height:10px;opacity:.9}100%{width:28px;height:28px;opacity:0}}
#fx-now .now-lb{position:absolute;left:50%;transform:translateX(-50%);bottom:11px;font-size:8.5px;font-weight:700;color:var(--xd-acc-lt,#f0a070);white-space:nowrap;opacity:0;transition:opacity .3s .12s;text-shadow:0 1px 4px #000;pointer-events:none}
#ft-tl.open #fx-now .now-lb{opacity:1}
#fx-now.hot .nd{background:var(--xd-acc-lt,#f0a070);animation:fxHot 1.4s ease-in-out infinite;color:var(--xd-acc-lt,#f0a070)}
#fx-now.hot .now-lb{color:#f08a5a;text-shadow:0 0 8px rgba(240,138,90,.8),0 1px 4px #000;animation:fxHot 1.4s ease-in-out infinite}
.fx-edge{position:absolute;top:50%;transform:translateY(-50%);z-index:4;font-size:8.5px;color:#a09088;background:rgba(22,17,19,.85);border:1px solid rgba(255,255,255,.12);border-radius:6px;padding:1px 5px;cursor:pointer;opacity:0;pointer-events:none;transition:opacity .3s .12s}
#ft-tl.open .fx-edge{opacity:1;pointer-events:auto}
.fx-edge:hover{border-color:rgba(var(--xd-acc-rgb,232,120,74),.5);color:var(--xd-acc-text,#f0a070)}
.fx-edge.l{left:-3px}.fx-edge.r{right:-3px}
#fx-tip{position:absolute;bottom:calc(100% + 8px);left:0;width:100%;max-width:240px;padding:10px 12px;border-radius:11px;background:rgba(22,17,19,.97);border:1px solid rgba(var(--xd-acc-rgb,232,120,74),.38);box-shadow:0 12px 36px rgba(0,0,0,.65);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);opacity:0;pointer-events:none;transform:translateY(6px) scale(.97);transition:opacity .22s cubic-bezier(.22,1,.36,1),transform .22s cubic-bezier(.34,1.56,.64,1);z-index:5;font-size:11px;line-height:1.6;will-change:opacity,transform}
#fx-tip::after{content:"";position:absolute;left:-12px;right:-12px;bottom:-12px;height:12px}
#fx-tip.show{opacity:1;transform:translateY(0) scale(1);pointer-events:auto}
#fx-tip .tp-t{font-size:12px;font-weight:700;color:#e8ddd4;display:flex;align-items:center;gap:6px;margin-bottom:4px}
#fx-tip .tp-row{display:flex;gap:6px;align-items:baseline;padding:1.5px 0;color:#a09088}
#fx-tip .tp-row b{color:#706058;font-weight:400;font-size:10px;min-width:36px;flex-shrink:0}
#fx-tip .tp-row .v{color:#e8ddd4}
#fx-tip .tp-chip{display:inline-block;padding:0 6px;border-radius:99px;font-size:9px;line-height:1.7;flex-shrink:0}
#fx-tip .tp-desc{margin-top:5px;padding-top:5px;border-top:1px dashed rgba(255,255,255,.08);color:#a09088;font-size:10.5px;white-space:normal;word-break:break-word;line-height:1.6}
.fx-fold{max-height:3.6em;overflow:hidden;position:relative;transition:max-height .38s cubic-bezier(.22,1,.36,1);white-space:normal;word-break:break-word}
.fx-fold::after{content:"";position:absolute;left:0;right:0;bottom:0;height:1.5em;background:linear-gradient(180deg,transparent,rgba(22,17,19,.98))}
.fx-fold.open{max-height:280px}
.fx-fold.open::after{display:none}
.fx-fold-btn{display:inline-block;margin-top:4px;font-size:9.5px;color:var(--xd-acc-text,#f0a070);cursor:pointer;padding:2px 7px;border-radius:5px;border:1px solid rgba(var(--xd-acc-rgb,232,120,74),.3);background:rgba(var(--xd-acc-rgb,232,120,74),.08);transition:background .15s}
.fx-fold-btn:hover{background:rgba(var(--xd-acc-rgb,232,120,74),.18)}
