  .fx-nd{top:4px}
  #fx-now{top:4px}
  .fx-seg span{padding:2px 6px;font-size:9px}
  #fx-head{gap:5px;padding:0 8px}
  #fx-head .fh-t{font-size:9px}
  #fx-head .fh-span{font-size:8px}
  #fx-head .fh-hint{display:none}
  #fx-reset{font-size:8.5px;min-width:22px;height:16px;padding:0 4px}
