    const evs = ftTimelineNodes();
    ftTL._curEvs = evs;
    if (!ftTL._inited) { ftTL.viewStart = nowAbs - 0.3 * ftTL.span; ftTL._inited = true; }
    const vs = ftTL.viewStart, ve = vs + ftTL.span;
    ftTL.spanLb.textContent = ftTL.span >= 1440 ? '跨度 ' + (ftTL.span / 1440).toFixed(ftTL.span % 1440 ? 1 : 0) + ' 天' : '跨度 ' + Math.round(ftTL.span / 60) + ' 小时';
    const nowPct = (nowAbs - vs) / ftTL.span * 100;
    ftTL.pastEl.style.width = ftTLClamp(nowPct, 0, 100) + '%';
