    for (let t = Math.ceil(vs / step) * step; t <= ve; t += step) { th += '<div class="fx-tick" style="left:' + ((t - vs) / ftTL.span * 100) + '%"><span>' + (step < 1440 ? ftTLTick(t) : ftTLDay(t)) + '</span></div>'; }
