      stageHtml = '<div class="tp-row"><b>阶段</b><span class="v" style="color:#cfa8e0">' + esc(curName) + '（' + ((s.steps||[]).indexOf(s.current)+1) + '/' + (s.steps||[]).length + '）</span></div><div class="tp-row"><b>序列</b><span class="v">' + esc((s.steps||[]).join(' -> ') || '-') + '</span></div>';
