      ev.preventDefault(); const delta = Math.abs(ev.deltaX) > Math.abs(ev.deltaY) ? ev.deltaX : ev.deltaY; ftTL.viewStart += delta > 0 ? ftTL.span * 0.12 : -ftTL.span * 0.12; ftTLScheduleRender();
    }, { passive: false });
    body.addEventListener('pointerdown', function (ev) { if (ev.pointerType === 'mouse' && ev.button !== 0) return; ftTL.panMoved = false; ftTL.pts.set(ev.pointerId, { x: ev.clientX, y: ev.clientY }); if (ftTL.pts.size === 2) { ftTL.pan = null; const a = [...ftTL.pts.values()], r = body.getBoundingClientRect(); const frac = ftTLClamp(((a[0].x + a[1].x) / 2 - r.left) / r.width, 0, 1); ftTL.pinch = { d0: Math.hypot(a[0].x - a[1].x, a[0].y - a[1].y), s0: ftTL.span, frac, a0: ftTL.viewStart + frac * ftTL.span }; } else if (ftTL.pts.size === 1) { ftTL.pan = { id: ev.pointerId, x: ev.clientX, vs: ftTL.viewStart, moved: false, cap: false }; } });
    body.addEventListener('pointermove', function (ev) { if (!ftTL.pts.has(ev.pointerId)) return; ftTL.pts.set(ev.pointerId, { x: ev.clientX, y: ev.clientY }); if (ftTL.pinch && ftTL.pts.size === 2) { const a = [...ftTL.pts.values()], d = Math.hypot(a[0].x - a[1].x, a[0].y - a[1].y); if (d > 10 && ftTL.pinch.d0 > 10) { el.classList.add('open'); ftTL.span = ftTLClamp(ftTL.pinch.s0 * (ftTL.pinch.d0 / d), ftTL.SPAN_MIN, ftTL.SPAN_MAX); ftTL.viewStart = ftTL.pinch.a0 - ftTL.pinch.frac * ftTL.span; ftTLScheduleRender(); } return; } if (ftTL.pan && ftTL.pan.id === ev.pointerId) { const dx = ev.clientX - ftTL.pan.x; if (Math.abs(dx) > 4 && !ftTL.pan.moved) { ftTL.pan.moved = true; ftTL.panMoved = true; body.style.cursor = 'grabbing'; if (!ftTL.pan.cap) { ftTL.pan.cap = true; try { body.setPointerCapture(ev.pointerId); } catch {} } } if (ftTL.pan.moved) { ftTL.viewStart = ftTL.pan.vs - dx / (ftTL.track.clientWidth || 1) * ftTL.span; ftTLScheduleRender(); } } });
    function ptEnd(ev) { ftTL.pts.delete(ev.pointerId); if (ftTL.pts.size < 2) ftTL.pinch = null; if (ftTL.pan && ftTL.pan.id === ev.pointerId) { ftTL.pan = null; body.style.cursor = ''; } }
    body.addEventListener('pointerup', ptEnd); body.addEventListener('pointercancel', ptEnd);
    // 拖动平移后阻止 click 事件（注册在 topDoc 捕获阶段，无论松手位置在哪都能拦截）
    ftTL._panClickGuard = function (ev) { if (ftTL.panMoved) { ftTL.panMoved = false; ev.stopPropagation(); ev.preventDefault(); } };
    topDoc.addEventListener('click', ftTL._panClickGuard, true);
    // 🕰️ 关闭按钮：隐藏悬浮窗并提示可从狐刻面板重新打开
