  function ftTimelineRefresh() { if (!ftTL.el) return; ftTL._inited = false; ftTLScheduleRender(); }
  // ==================== 狐刻悬浮时间轴 END ====================
  function foxTimeInit() {
    ftState.config = ftLoadConfig();
    ftSaveConfig(ftState.config);
    ftState.data = ftLoadData();
    if (ftState.config.enabled) {
      ftRegisterAutoListener();
      // 📌 狐刻启用时自动开启并写入"开头输出位置信息"预设条目（照抄狐析 injectUserPrefEntry 模式）
      try { ftSyncPromptEntry(true, FT_PROMPT_ENTRY_CONTENT); } catch (e) { log('[狐刻] 初始化开启位置信息条目失败', e); }
      // 🆕 狐刻启用时自动挂载悬浮窗（刷新后恢复，用户点✕关闭后不自动恢复）
      try {
        if (typeof ftTimelineMount === 'function' && !ftTL.el && localStorage.getItem('ft-tl-closed') !== '1') {
          ftTimelineMount();
        }
      } catch (e) { log('[狐刻] 初始化悬浮窗失败', e); }
    }
    log('[狐刻] 初始化完成');
  }

  // ==================== 狐刻 END ====================

  // ==================== INIT ====================
  async function init() {
    log('🚀 初始化');

    // 🦊 文件存储初始化：尝试恢复已保存的目录句柄
    try {
      const fileStorageActive = await FoxStorage.init();
      if (fileStorageActive) {
        log('[文件存储] 已恢复文件夹句柄:', FoxStorage.getDirName());
        // 🦊 启用文件存储模式：从文件加载数据到内存缓存，不再使用 localStorage
        await _loadCacheFromFiles();
        _fileStorageActive = true;
        log('[文件存储] 文件存储模式已启用，所有读写将通过内存缓存 + 文件同步');
      }
    } catch (e) { logError('[文件存储] 初始化失败', e); }

    // 🦊 安装 fetch 钩子：让狐裁/狐忆/狐搜的"附加参数"能真正注入到聊天完成请求。
    try { ssInstallExtraInjectFetchHook(); } catch (e) { log('[附加参数] 安装 fetch hook 失败', e); }
    try { ssInstallFoxJudgeFetchDiagnostics(); } catch (e) { log('[狐裁诊断] 安装 fetch 网络诊断失败', e); }

    // 清理旧版缩放持久化键，避免旧尺寸/位置被恢复。
    try {
      localStorage.removeItem('Xuanhu_PW_Float_Size');
      localStorage.removeItem('Xuanhu_PW_Panel_Size');
    } catch { }

    state.husouSettings = loadHusouSettings();
    state.hushenSettings = loadHushenSettings();

    // ✅ 刷新页面后同步平滑流式 UI 显示 + 强制 should_stream 与平滑流式开关一致
    await syncSmoothStreamState('init');

    // 🆕 批次 3A：初始化时加载 🦊 狐忆 配置
    foxMemoryConfig = loadFoxMemoryConfig();
    foxMemoryInstallVectorInputListener();
    novelModeConfig = loadNovelModeConfig();
    outlineApiConfig = loadOutlineApiConfig();

    // 🦊 小说模式：注册"头/尾提示词"统一注入监听（仅在 enabled 时往请求体里加东西，
    //    关闭时只剥离旧标记，对其他模块零影响）。
    try { novelRegisterInjectListener(); } catch (e) { log('[小说模式] 注册注入监听失败', e); }

    // 🦊 初始化时同步狐忆预设条目。
    // 默认关闭预设注入时，立刻关闭条目，避免旧记忆残留到新卡/新聊天。
    try {
      if (foxMemoryConfig.injectToPreset) {
        await foxMemorySyncToPreset(true);
      } else {
        await foxMemoryDisablePresetInject();
      }
    } catch (e) {
      log('[狐忆] 初始化同步预设注入失败', e);
    }
    // 🆕 初始化时同步隐藏远楼层正则脚本状态（确保配置与正则一致）
    try {
      if (foxMemoryConfig.hideFarFloorsEnabled) {
        foxMemoryApplyHideFarFloors(true, foxMemoryConfig.hideFarFloorsThreshold).catch(e => log('[狐忆] 初始化隐藏远楼层失败:', e));
      }
    } catch (e) { log('[狐忆] 初始化隐藏远楼层失败:', e); }
    // 统一底栏由 initUI 创建；其内部已有单实例延迟重试，不再轮询已废弃的旧悬浮窗节点。
    pwState.config = pwLoadConfig();
    pwState.data = pwLoadData();
    try { foxImageInit(); } catch (e) { log('[狐映] 初始化失败', e); }

    // 🕰️ 狐刻初始化（移到 initUI 之后执行，避免 cleanup 清理掉刚挂载的悬浮窗）
    try { foxJudgeCheckAndInvalidateIfChanged(); } catch (e) { log('[狐裁] 指纹检测失败', e); }

    try { foxJudgeRegisterSwipeRerollListeners(); } catch (e) { log('[狐裁] 注册swipe/reroll监听失败', e); }
    try { foxJudgeRegisterOutputInjectListener(); } catch (e) { log('[狐裁] 注册输出注入监听失败', e); }
    try { registerFoxJudgeInterceptListener(); } catch (e) { log('[狐裁] 注册独立拦截器失败', e); }
    try { ssRegisterContentRescueListener(); } catch (e) { log('[正文救援] 注册监听失败', e); }

    // 📖 小说进度窗：注册区块抓取监听；若小说模式已开则自动开窗
    try { novelProgRegister(); } catch (e) { log('[小说进度] 注册监听失败', e); }
    try { novelProgSyncWithNovelMode(); } catch (e) { log('[小说进度] 初始联动失败', e); }

    state.outlineFilterSettings = loadOutlineFilterSettings();

    // 默认 0 = 无楼层限制。
    // 如果用户设置了 N，则按实际楼层计数。
    {
      const v = parseInt(localStorage.getItem(CONFIG.OUTLINE_CONTEXT_FLOORS_KEY) ?? '0');
      state.outlineContextFloors = Number.isFinite(v) && v >= 0 ? v : 0;
    }
    {
      const v = parseInt(localStorage.getItem(CONFIG.OUTLINE_ANALYSIS_FLOORS_KEY) ?? '80');
      state.outlineAnalysisFloors = Number.isFinite(v) && v >= 0 ? v : 80;
    }

    state.outlineText = outlineLoadCurrentText();

    // 按角色卡恢复动态修正状态：大纲为空则强制关闭
    {
      const hasOutline = !!outlineLoadLocalRaw().trim();
      if (!hasOutline) {
        state.outlineAutoAnalysis = false;
      } else {
        state.outlineAutoAnalysis = localStorage.getItem(outlineGetAutoKey()) === 'true';
      }
    }

    // 🦊 初始化时立刻按当前角色卡本地大纲同步预设状态。
    // 默认关闭预设注入，避免切换角色卡后旧大纲残留在预设里。
    try {
      await outlineSyncPresetByConfig(state.outlineText);
    } catch (e) {
      log('[狐构] 初始化同步预设状态失败', e);
    }

    // 📌 狐构启用时自动同步"大纲阶段输出"预设条目状态（照抄狐刻 ftSyncPromptEntry 模式）
    //    开启时自动 enable 条目（提示词内容由用户手动粘贴），关闭时自动 disable
    try {
      if (state.outlineAutoAnalysis) {
        outlineSyncPromptEntry(true, '');
        log('[狐构] 初始化：已自动开启 <fox_hugou> 大纲阶段条目');
      } else {
        outlineSyncPromptEntry(false, '');
        log('[狐构] 初始化：已自动关闭 <fox_hugou> 大纲阶段条目');
      }
    } catch (e) { log('[狐构] 初始化同步 <fox_hugou> 条目失败', e); }

    const savedOutlineLast = parseInt(localStorage.getItem(outlineGetLastAnalyzedKey()) || '-1');

    state.outlineLastAnalyzedId = Number.isFinite(savedOutlineLast) ? savedOutlineLast : -1;
    // 🆕 批次 3C 修复 v2：注册推进监听器（用 GENERATION_AFTER_COMBINE_PROMPTS）
    if (foxMemoryConfig.autoPush) {
      registerFoxPushListener();
      log('[推进] 自动模式已注册（capture 阶段拦截）');
    }
    // 🦊 reroll / swipe 保护：捕获 GENERATION_STARTED 的 type，
    //    供狐忆 / 平行世界 / 狐构等 MESSAGE_RECEIVED 回退判断使用。
    //    必须在所有 register*AutoListener 之前注册。
    xhRegisterGenerationTypeTracker();

    // 🆕 记忆自动分析：每次回复结束自动提取记忆
    if (foxMemoryConfig.autoMode !== 'manual') {
      registerFoxMemoryAutoListener();
      log('[记忆自动分析] 已注册，模式:', foxMemoryConfig.autoMode);
    }
    registerFoxMemoryRepairListener();
    registerFoxMemorySnapshotListener();

    // ✅ 狐构动态修正独立监听。
    // 不依赖思维链总开关，不依赖主 onGenEnd。
    registerOutlineAutoListener();
    pwRegisterAutoListener();
    husouRegisterListeners();
    // 🕰️ 狐刻自动监听（enabled 时注册，否则跳过）
    try { if (ftState.config?.enabled) ftRegisterAutoListener(); } catch (e) { log('[狐刻] 注册自动监听失败', e); }
    // ✅ 预设切换/更新后再次同步平滑流式
    try {
      const eo = getFn('eventOn');
      const te = getFn('tavern_events') || tavern_events;

      if (typeof eo === 'function') {
        if (te?.PRESET_CHANGED) {
          state.worldInfoEventHandles.push(eo(te.PRESET_CHANGED, () => {
            setTimeout(() => syncSmoothStreamState('preset_changed'), 300);
            setTimeout(() => { try { foxStrategySyncModeFromPreset(); } catch {} }, 300);
            setTimeout(() => { foxImageApplyPrompt().catch(e => log('[狐映] 预设切换后同步失败', e)); }, 350);
            try { foxJudgeCheckAndInvalidateIfChanged(); } catch { }
            // ✅ 修复流式：预设切换后检查 should_stream 是否偏离用户偏好，偏离则恢复
            setTimeout(() => { ssRestoreStreamPreferenceIfNeeded('PRESET_CHANGED'); }, 400);
            setTimeout(() => { ssRestoreStreamPreferenceIfNeeded('PRESET_CHANGED(延迟)'); }, 1000);
          }));
        }

        if (te?.OAI_PRESET_CHANGED_AFTER) {
          state.worldInfoEventHandles.push(eo(te.OAI_PRESET_CHANGED_AFTER, () => {
            setTimeout(() => syncSmoothStreamState('oai_preset_changed_after'), 300);
            setTimeout(() => { try { foxStrategySyncModeFromPreset(); } catch {} }, 300);
            setTimeout(() => { foxImageApplyPrompt().catch(e => log('[狐映] OAI预设切换后同步失败', e)); }, 350);
            try { foxJudgeCheckAndInvalidateIfChanged(); } catch { }
            // ✅ 修复流式：OAI 预设切换后同样恢复用户偏好
            setTimeout(() => { ssRestoreStreamPreferenceIfNeeded('OAI_PRESET_CHANGED_AFTER'); }, 400);
            setTimeout(() => { ssRestoreStreamPreferenceIfNeeded('OAI_PRESET_CHANGED_AFTER(延迟)'); }, 1000);
          }));
        }

        if (te?.SETTINGS_UPDATED) {
          state.worldInfoEventHandles.push(eo(te.SETTINGS_UPDATED, () => {
            setTimeout(() => syncSmoothStreamState('settings_updated'), 300);
            try { restoreInlineMediaOption(); } catch { }
            // ✅ 捕获用户通过 UI 切换流式的偏好（仅在没有内部请求运行时捕获，
            //    避免把 host 在内部请求中泄漏的 should_stream:false 误判为用户意图）
            try {
              if (!xhCurrentGenerationIsInternal && xhInternalGenerationDepth === 0 && __ssStreamGuardCount === 0) {
                const cur = isStreamingEnabled();
                ssSaveStreamPreference(cur);
                log(`[流式偏好] SETTINGS_UPDATED：捕获用户流式偏好=${cur}`);
              }
            } catch {}
          }));
        }

        if (te?.SETTINGS_LOADED_AFTER) {
          state.worldInfoEventHandles.push(eo(te.SETTINGS_LOADED_AFTER, () => {
            setTimeout(() => { try { restoreInlineMediaOption(); } catch { } }, 500);
            // ✅ 设置加载后也恢复一次（覆盖首次加载预设重置流式的场景）
            setTimeout(() => { ssRestoreStreamPreferenceIfNeeded('SETTINGS_LOADED_AFTER'); }, 600);
          }));
        }

        // 世界书原生路径诊断：狐构/狐忆/狐搜/平行世界使用 world_info_before/after，
        // 这里直接记录酒馆扫描与最终激活结果，便于确认绿灯条目是否进入原生注入链路。
        if (te?.WORLDINFO_ENTRIES_LOADED) {
          state.worldInfoEventHandles.push(eo(te.WORLDINFO_ENTRIES_LOADED, lores => {
            try {
              const groups = ['globalLore', 'characterLore', 'chatLore', 'personaLore'];
              ssLastLoadedWorldInfoEntries = groups.flatMap(group => ssNormalizeWorldInfoEventEntries(lores?.[group]));
              log(`[世界书·原生扫描] WORLDINFO_ENTRIES_LOADED：全局=${lores?.globalLore?.length || 0}，角色=${lores?.characterLore?.length || 0}，聊天=${lores?.chatLore?.length || 0}，玩家=${lores?.personaLore?.length || 0}，合计=${ssLastLoadedWorldInfoEntries.length}`);
            } catch (e) {
              log('[世界书·原生扫描] 解析 WORLDINFO_ENTRIES_LOADED 失败', e);
            }
          }));
        }

        if (te?.WORLDINFO_SCAN_DONE) {
          state.worldInfoEventHandles.push(eo(te.WORLDINFO_SCAN_DONE, eventData => {
            try {
              const activatedMap = eventData?.activated?.entries;
              const activatedEntries = activatedMap && typeof activatedMap.values === 'function'
                ? Array.from(activatedMap.values())
                : (Array.isArray(activatedMap) ? activatedMap : []);
              const successfulCount = Array.isArray(eventData?.new?.successful) ? eventData.new.successful.length : 0;
              const allCount = Array.isArray(eventData?.new?.all) ? eventData.new.all.length : 0;
              ssLastActivatedWorldInfoEntries = activatedEntries;
              ssHasNativeWorldInfoActivationSnapshot = true;
              log(`[世界书·原生扫描] WORLDINFO_SCAN_DONE：候选=${allCount}，本轮新命中=${successfulCount}，最终激活=${activatedEntries.length}，预算=${eventData?.budget?.current ?? '?'}，溢出=${eventData?.budget?.overflowed === true ? '是' : '否'}`);
              ssLogNativeWorldInfoEntries(activatedEntries, 'WORLDINFO_SCAN_DONE');
            } catch (e) {
              log('[世界书·原生扫描] 解析 WORLDINFO_SCAN_DONE 失败', e);
            }
          }));
        }

        if (te?.WORLD_INFO_ACTIVATED) {
          state.worldInfoEventHandles.push(eo(te.WORLD_INFO_ACTIVATED, entries => {
            try {
              ssLastActivatedWorldInfoEntries = ssNormalizeWorldInfoEventEntries(entries);
              ssHasNativeWorldInfoActivationSnapshot = true;
              ssLogNativeWorldInfoEntries(ssLastActivatedWorldInfoEntries, 'WORLD_INFO_ACTIVATED');
            }
            catch (e) { log('[世界书·原生扫描] 解析 WORLD_INFO_ACTIVATED 失败', e); }
          }));
        }

        // 🦊 reroll / swipe 保护：切换聊天时酒馆可能重建事件，
        //    为防止追踪器静默失效，跟随 CHAT_CHANGED 重挂一次。
        if (te?.CHAT_CHANGED) {
          state.worldInfoEventHandles.push(eo(te.CHAT_CHANGED, () => {
            ssLastActivatedWorldInfoEntries = [];
            ssLastLoadedWorldInfoEntries = [];
            ssHasNativeWorldInfoActivationSnapshot = false;
            try { xhRegisterGenerationTypeTracker(); } catch (e) { log('[生成类型追踪] CHAT_CHANGED 重挂失败', e); }
          }));
        }
      }
    } catch (e) {
      log('[平滑流式] 注册同步监听失败', e);
    }
    log('[狐搜] 当前角色卡ID:', getCurrentCharId(), '狐忆角色卡ID:', getCurrentCharId());
    await initUI();

    // 🕰️ 狐刻初始化（在 initUI 之后执行，避免 cleanup 清理掉刚挂载的悬浮窗）
    try { foxTimeInit(); } catch (e) { log('[狐刻] 初始化失败', e); }

    window.addEventListener('pagehide', cleanup);
    const initTimer = setTimeout(async () => {
      state._timers.init = null;
      await setBeautyStyle(state.currentStyle, state.isExpanded);
      await forceRefreshAll();
      bindEvents();

      if (state.enabled) {
        // 🦊 平滑流式开关是流式状态唯一权威：刷新后强制 should_stream=true
        log('✅ 已启用（流式强制开）');
      } else {
        log('待开启（流式强制关），但狐构/自动分析监听已启用');
      }
      updateBubbleUI();
      log('🎉 完成|', buildStatusText(), '|流式:', isStreamingEnabled());

      // 🦊 修复「发送内联媒体」被脚本启动期 saveSettingsDebounced 重置为 disabled 的 BUG：
      //    agent marker guard 在早期就触发 saveSettingsDebounced，如果用户设置尚未完全加载，
      //    保存时会把 allow_sending_images 冲掉。这里在初始化完成后强制恢复为 'auto'。
      //    同时挂 SETTINGS_LOADED / PRESET_CHANGED 事件持续保护。
      try { restoreInlineMediaOption(); } catch (e) { log('[内联媒体] 恢复失败', e); }

      // 🦊 数据库冲突适配：初始化完成后检查"狐忆×数据库"冲突并弹窗提醒
      try { ssMaybeWarnDbFoxMemoryConflict(); } catch (e) { log('[狐裁][数据库适配] 冲突检查异常', e); }

      // 🦊 文件存储：初始化完成后触发一次文件同步（将内存缓存写入文件）
      try {
        if (_fileStorageActive) _scheduleFileSync();
      } catch (e) { /* ignore */ }
    }, CONFIG.INIT_DELAY);
    state._timers.init = initTimer;
  }

  // 🦊 修复「发送内联媒体」（allow_sending_images）被脚本覆盖关闭的 BUG
  function restoreInlineMediaOption() {
    try {
      const preset = getPreset('in_use');
      const cur = preset?.settings?.allow_sending_images;
      if (cur === 'disabled' || cur === undefined || cur === null) {
        setPreset('in_use', { settings: { allow_sending_images: 'auto' } })?.then(() => {
          log('[内联媒体] 已恢复 allow_sending_images=auto');
        })?.catch(e => log('[内联媒体] 恢复失败', e));
      }
    } catch { }
  }

  if (typeof SillyTavern !== 'undefined') init();
  else { const ck = setInterval(() => { if (typeof SillyTavern !== 'undefined') { clearInterval(ck); init(); } }, 500); }
  log('📦 脚本加载完成');

  function pwMakeResizable(targetEl, opts = {}) {
    if (!targetEl) return;

    // ✅ 移动端 / 触屏 / 小屏幕禁用：避免触屏误触
    try {
      const vw = topWindow.visualViewport?.width || topWindow.innerWidth || topDoc.documentElement.clientWidth || 0;
      const isMobile = vw <= 768;
      if (isMobile) return;
    } catch { }

    // ✅ 只允许在小悬浮窗（pw-state-float）上挂缩放手柄
    if (targetEl.id !== 'pw-state-float') return;

    // 移除旧手柄
    const existingHandles = targetEl.querySelectorAll('.pw-resize-handle');
    existingHandles.forEach(h => h.remove());

    // 确保有最小尺寸限制
    targetEl.style.minWidth = '260px';
    targetEl.style.minHeight = '200px';
    targetEl.style.boxSizing = 'border-box';

    const handleCss = `
      position: absolute;
      z-index: 1000006;
      pointer-events: auto;
      background: transparent;
      transition: background 0.15s ease;
    `;

    const handles = [];

    for (const h of handles) {
      const handle = topDoc.createElement('div');
      handle.className = `pw-resize-handle pw-resize-${h.name}`;
      handle.style.cssText = `
            position: absolute;
            ${h.top ? `top: ${h.top};` : ''}
            ${h.bottom ? `bottom: ${h.bottom};` : ''}
            ${h.left ? `left: ${h.left};` : ''}
            ${h.right ? `right: ${h.right};` : ''}
            ${h.width ? `width: ${h.width};` : ''}
            ${h.height ? `height: ${h.height};` : ''}
            cursor: ${h.cursor};
            z-index: 1000006;
            pointer-events: auto;
        `;
      handle.setAttribute('data-resize-dir', h.name);
      handle.setAttribute('aria-hidden', 'true');

      Object.assign(handle.style, {
        position: 'absolute',
        zIndex: '1000006',
        pointerEvents: 'auto',
        background: 'transparent',
        touchAction: 'none',
      });

      if (h.top) handle.style.top = h.top;
      if (h.bottom) handle.style.bottom = h.bottom;
      if (h.left) handle.style.left = h.left;
      if (h.right) handle.style.right = h.right;
      if (h.width) handle.style.width = h.width;
      if (h.height) handle.style.height = h.height;
      handle.style.cursor = h.cursor;

      handle.addEventListener('mouseenter', () => { handle.style.background = 'rgba(96,210,255,0.18)'; });
      handle.addEventListener('mouseleave', () => { handle.style.background = 'transparent'; });

      targetEl.appendChild(handle);
    }

    let isResizing = false;
